function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function isA1ProjectsAdminUser() {
  if (currentUser?.platform_admin || currentUser?.super_admin) return true;
  return String(currentUser?.role || "").trim().toLowerCase() === "admin";
}

