function isRenderOverlayState(state = null) {
  if (!state || typeof state !== "object") return false;
  const kind = String(state.kind || "").toLowerCase();
  const mode = String(state.promptMode || state.mode || state.prompt_mode || "").toLowerCase();
  return kind === "scene_render" || kind === "render" || kind === "render_region_edit" || mode === "render";
}

function sanitizeRenderOverlayProgress(progress = null) {
  if (!progress || typeof progress !== "object") return progress;
  const next = { ...progress };
  delete next.mcmaster_parts;
  delete next.mcmaster_count;
  delete next.electronics_parts;
  delete next.electronics_count;
  return next;
}

function syncViewportGenerationOverlay(completeOpts = {}) {
  const overlayPid = generationWatchPid || viewportOverlayPid;
  const activeOverlay = generationWatchOverlay?.kind === "wiring" ? (wiringOverlay || viewerOverlay) : viewerOverlay;
  const inactiveOverlay = activeOverlay === viewerOverlay ? wiringOverlay : viewerOverlay;

  function usageSummaryFromJobs(jobs = [], fallbackGen = null) {
    const list = Array.isArray(jobs) ? jobs : [];
    const focused = list[0] || null;
    const pick = focused || fallbackGen || null;
    if (!pick && !fallbackGen) return null;
    const usage = pick?.usage
      || pick?.meta?.usage
      || pick?.progress?.usage
      || fallbackGen?.usage
      || fallbackGen?.progress?.usage
      || null;
    const cost = pick?.cost_usd
      ?? pick?.meta?.cost_usd
      ?? pick?.progress?.cost_usd
      ?? fallbackGen?.cost_usd
      ?? fallbackGen?.progress?.cost_usd
      ?? null;
    const model = pick?.model || pick?.meta?.model || pick?.progress?.model || fallbackGen?.model || "";
    const tokens = usageTokenTotal(usage);
    const costNum = cost != null && Number.isFinite(Number(cost)) ? Number(cost) : null;
    if (!tokens && (costNum == null || costNum <= 0)) {
      // Multi-job: sum all running jobs when focused has no usage yet.
      if (list.length > 1) {
        let sumTokens = 0;
        let sumCost = 0;
        let hasCost = false;
        let anyModel = "";
        let calls = 0;
        for (const job of list) {
          const u = job.usage || job.meta?.usage || job.progress?.usage || null;
          sumTokens += usageTokenTotal(u);
          if (job.cost_usd != null || job.meta?.cost_usd != null || job.progress?.cost_usd != null) {
            sumCost += Number(job.cost_usd ?? job.meta?.cost_usd ?? job.progress?.cost_usd) || 0;
            hasCost = true;
          }
          calls += Number(job.ai_calls || job.meta?.ai_calls || job.progress?.ai_calls || 0) || 0;
          if (!anyModel) anyModel = job.model || job.meta?.model || job.progress?.model || "";
        }
        if (!sumTokens && !hasCost) return null;
        return {
          cost_usd: hasCost ? sumCost : null,
          usage: { total_tokens: sumTokens },
          model: anyModel,
          ai_calls: calls,
        };
      }
      return null;
    }
    return {
      cost_usd: costNum,
      usage: usage || { total_tokens: tokens },
      model,
      ai_calls: Number(pick?.ai_calls || pick?.meta?.ai_calls || pick?.progress?.ai_calls || fallbackGen?.ai_calls || 0) || 0,
    };
  }

  if (overlayPid && overlayPid === projectId) {
    const renderHud = viewportOverlayPid === projectId && isRenderOverlayState(viewportOverlayState);
    if (renderHud) {
      inactiveOverlay?.setGenerating(false);
      viewerOverlay.setGenerating(true, viewportOverlayState.message, {
        ...viewportOverlayState,
        progress: sanitizeRenderOverlayProgress(viewportOverlayState.progress),
        jobs: [],
      });
      wiringOverlay?.setGenerating(false);
      syncViewportGenerationUserBadge(viewportOverlayState);
      syncXrAiGeneratingIndicator();
      return;
    }
    if (generationWatchPid === projectId && generationWatchOverlay) {
      const liveGen = allProjects.find((p) => p.id === projectId)?.generation;
      const runningJobs = generationRunningJobs(liveGen, generationWatchOverlay);
      const cadJobs = runningJobs.filter((job) => !isVideoGenerationKind(job) && !isPendingGenerationJob(job));
      if (
        (generationWatchOverlay.kind === "video" || isVideoGenerationKind(generationWatchOverlay))
        && !cadJobs.length
      ) {
        inactiveOverlay?.setGenerating(false);
        viewerOverlay.setGenerating(false);
        wiringOverlay?.setGenerating(false);
        hideViewportGenerationUserBadge();
        syncXrAiGeneratingIndicator();
        return;
      }
      inactiveOverlay?.setGenerating(false);
      const watchProgress = generationWatchOverlay.progress || null;
      const liveProgress = liveGen?.progress || null;
      const focusedId = String(generationWatchOverlay.focusedJobId || "");
      const focused = runningJobs.find((j) => String(j.trace_id || j.id || "") === focusedId)
        || (generationWatchOverlay.pendingStart ? runningJobs.find((j) => isPendingGenerationJob(j)) : null)
        || runningJobs[runningJobs.length - 1]
        || runningJobs[0];
      const focusedIsPending = isPendingGenerationJob(focused);
      const focusedProgress = focused?.progress
        || (focusedIsPending ? watchProgress : (liveProgress || watchProgress));
      const mergedProgress = focusedProgress || watchProgress
        ? {
          ...(watchProgress || {}),
          ...(focusedIsPending ? {} : (liveProgress || {})),
          ...(focusedProgress || {}),
          improved_prompt:
            focusedProgress?.improved_prompt
            ?? focusedProgress?.prompt_preview
            ?? liveProgress?.improved_prompt
            ?? liveProgress?.prompt_preview
            ?? watchProgress?.improved_prompt
            ?? watchProgress?.prompt_preview,
          ...overlayPreviewFields({
            focusedIsPending,
            focusedProgress,
            liveProgress,
            watchProgress,
          }),
          mcmaster_parts:
            focusedProgress?.mcmaster_parts
            ?? liveProgress?.mcmaster_parts
            ?? watchProgress?.mcmaster_parts,
          mcmaster_count:
            focusedProgress?.mcmaster_count
            ?? liveProgress?.mcmaster_count
            ?? watchProgress?.mcmaster_count,
          electronics_parts:
            focusedProgress?.electronics_parts
            ?? liveProgress?.electronics_parts
            ?? watchProgress?.electronics_parts,
          electronics_count:
            focusedProgress?.electronics_count
            ?? liveProgress?.electronics_count
            ?? watchProgress?.electronics_count,
          thinking:
            focusedProgress?.thinking
            ?? liveProgress?.thinking
            ?? watchProgress?.thinking,
          thinking_log:
            focusedProgress?.thinking_log
            ?? liveProgress?.thinking_log
            ?? watchProgress?.thinking_log,
          thinking_append:
            focusedProgress?.thinking_append
            ?? liveProgress?.thinking_append
            ?? watchProgress?.thinking_append,
          harness:
            focusedProgress?.harness
            ?? liveProgress?.harness
            ?? watchProgress?.harness
            ?? focused?.harness
            ?? liveGen?.harness
            ?? generationWatchOverlay.harness,
          cost_usd:
            focusedProgress?.cost_usd
            ?? liveProgress?.cost_usd
            ?? watchProgress?.cost_usd
            ?? focused?.cost_usd
            ?? liveGen?.cost_usd,
          usage:
            focusedProgress?.usage
            ?? liveProgress?.usage
            ?? watchProgress?.usage
            ?? focused?.usage
            ?? liveGen?.usage,
          ai_calls:
            focusedProgress?.ai_calls
            ?? liveProgress?.ai_calls
            ?? focused?.ai_calls
            ?? liveGen?.ai_calls,
          model:
            focusedProgress?.model
            ?? liveProgress?.model
            ?? focused?.model
            ?? liveGen?.model,
        }
        : null;
      const usageSummary = usageSummaryFromJobs(
        focused ? [focused, ...runningJobs.filter((j) => j !== focused)] : runningJobs,
        liveGen,
      ) || generationWatchOverlay.usageSummary || null;
      if (usageSummary) generationWatchOverlay.usageSummary = usageSummary;
      const hudBrand = generationHudBrand(liveGen);
      activeOverlay.setGenerating(true, generationWatchOverlay.message, {
        ...generationWatchOverlay,
        focusedJobId: focused?.trace_id || focused?.id || generationWatchOverlay.focusedJobId,
        harness: generationWatchOverlay.harness
          || liveGen?.harness
          || focused?.harness
          || focusedProgress?.harness
          || liveProgress?.harness,
        startedAt: focused?.started_at || liveGen?.started_at || generationWatchOverlay.startedAt,
        progress: mergedProgress,
        jobs: runningJobs,
        usageSummary,
        generator: {
          model: hudBrand.model,
          provider: hudBrand.provider,
          source: hudBrand.source,
          ...resolveLiveGenerationIdentity(liveGen),
          progress: mergedProgress,
          brandLocked: true,
        },
      });
      scheduleLiveGenerationPreview(mergedProgress, { running: true });
      syncViewportGenerationUserBadge(
        runningJobs.length > 1
          ? { ...liveGen, status: "running", prompt: `${runningJobs.length} parts generating` }
          : (liveGen?.status === "running" ? liveGen : generationWatchOverlay),
      );
      syncXrAiGeneratingIndicator();
    } else if (viewportOverlayPid === projectId && viewportOverlayState) {
      viewerOverlay.setGenerating(true, viewportOverlayState.message, viewportOverlayState);
      wiringOverlay?.setGenerating(false);
      syncViewportGenerationUserBadge(viewportOverlayState);
      syncXrAiGeneratingIndicator();
    }
    return;
  }
  const currentGeneration = allProjects.find((p) => p.id === projectId)?.generation;
  const runningJobs = generationRunningJobs(currentGeneration).filter((job) => !isVideoGenerationKind(job));
  if (isVideoGenerationKind(currentGeneration) && !runningJobs.length) {
    /* Film edit uses the clip-editor overlay, not the CAD HUD. */
  } else if ((currentGeneration?.status === "running" || runningJobs.length) && currentGeneration?.kind !== "wiring") {
    const mode = generationPromptMode(currentGeneration);
    const focused = runningJobs[0] || currentGeneration;
    const hudBrand = generationHudBrand(currentGeneration);
    viewerOverlay.setGenerating(true, promptGenerationOverlayOpts(mode).message, {
      kind: currentGeneration.kind || "prompt",
      promptMode: mode,
      progress: currentGeneration.progress,
      jobs: runningJobs,
      usageSummary: usageSummaryFromJobs(runningJobs, focused),
      ...promptGenerationOverlayOpts(mode),
      generator: {
        model: hudBrand.model,
        provider: hudBrand.provider,
        source: hudBrand.source,
        ...resolveLiveGenerationIdentity(currentGeneration),
        progress: currentGeneration.progress,
        brandLocked: true,
      },
    });
    scheduleLiveGenerationPreview(focused?.progress || currentGeneration.progress, { running: true });
    wiringOverlay?.setGenerating(false);
    syncViewportGenerationUserBadge(
      runningJobs.length > 1
        ? { ...currentGeneration, status: "running", prompt: `${runningJobs.length} parts generating` }
        : currentGeneration,
    );
    syncXrAiGeneratingIndicator();
    return;
  }
  viewerOverlay.setGenerating(false, null, {
    complete: completeOpts.complete ?? false,
    force: !!completeOpts.force,
  });
  wiringOverlay?.setGenerating(false, null, {
    complete: completeOpts.complete ?? false,
    force: !!completeOpts.force,
  });
  syncViewportGenerationUserBadge(null);
  syncStopButtonVisibility();
  syncXrAiGeneratingIndicator();
}

function generationRunningJobs(gen, watchOverlay = null) {
  const fromGen = Array.isArray(gen?.running_jobs) && gen.running_jobs.length
    ? gen.running_jobs
    : Array.isArray(gen?.jobs)
      ? gen.jobs.filter((j) => j?.status === "running")
      : [];
  if (fromGen.length) {
    if (watchOverlay?.pendingStart && !fromGen.some((j) => String(j?.trace_id || j?.id || "") === "pending")) {
      return [
        ...fromGen,
        {
          id: "pending",
          trace_id: "pending",
          status: "running",
          kind: watchOverlay.kind || "prompt",
          prompt: watchOverlay.prompt || "Starting another generation…",
          progress: watchOverlay.progress || { pct: 2, label: "Starting another generation…" },
        },
      ];
    }
    return fromGen;
  }
  if (gen?.status === "running") {
    return [{
      id: gen.trace_id,
      trace_id: gen.trace_id,
      status: "running",
      kind: gen.kind || "prompt",
      prompt: gen.prompt,
      label: gen.label,
      mode: gen.mode,
      progress: gen.progress,
      usage: gen.usage,
      cost_usd: gen.cost_usd,
      ai_calls: gen.ai_calls,
      model: gen.model,
      provider: gen.provider,
      by_user_name: gen.by_user_name,
      by_user_id: gen.by_user_id,
      by_avatar_url: gen.by_avatar_url,
    }];
  }
  if (watchOverlay?.pendingStart) {
    const ident = resolveGenerationIdentity(watchOverlay, {
      liveGen: gen,
      overlay: watchOverlay,
      sessionUser: sessionUserForGeneration(),
    });
    return [{
      id: "pending",
      trace_id: "pending",
      status: "running",
      kind: watchOverlay.kind || "prompt",
      prompt: watchOverlay.prompt || watchOverlay.message,
      progress: watchOverlay.progress,
      usage: watchOverlay.usageSummary?.usage,
      cost_usd: watchOverlay.usageSummary?.cost_usd,
      ai_calls: watchOverlay.usageSummary?.ai_calls,
      model: watchOverlay.model,
      provider: watchOverlay.provider,
      by_user_name: ident.by_user_name,
      by_user_id: ident.by_user_id,
      by_avatar_url: ident.by_avatar_url,
      by_user_email: ident.by_user_email,
    }];
  }
  return [];
}

function isVideoGenerationKind(gen = {}) {
  const kind = String(gen?.kind || "").toLowerCase();
  return kind === "video" || kind === "film_edit" || kind === "film-edit" || kind === "video_edit";
}

function videoJobFromGeneration(gen = {}) {
  const jobs = [
    ...(Array.isArray(gen?.running_jobs) ? gen.running_jobs : []),
    ...(Array.isArray(gen?.jobs) ? gen.jobs : []),
    gen,
  ];
  return jobs.find((job) => job && isVideoGenerationKind(job) && String(job.status || "") === "running")
    || jobs.find((job) => job && isVideoGenerationKind(job))
    || null;
}

function emitVideoGeneration(job, pid, status) {
  if (!job) return;
  window.dispatchEvent(new CustomEvent("render3d:video-generation", {
    detail: { ...job, projectId: pid, status: status || job.status },
  }));
}

window.addEventListener("render3d:video-generation", (event) => {
  const job = event?.detail;
  const pid = String(job?.projectId || projectId || "").trim();
  if (!pid || String(job?.status || "") !== "running") return;
  if (hasGenerationPoll(pid) || generationWatchPid === pid) return;
  beginGenerationWatch(pid, {
    kind: "video",
    model: job.model,
    provider: job.provider,
  });
});

function liveServerCadJobs(gen) {
  return generationRunningJobs(gen, null).filter((job) => !isPendingGenerationJob(job) && !isVideoGenerationKind(job));
}

function cadPromptWatchIsLive(pid = projectId) {
  return generationWatchPid === pid
    && !!generationWatchOverlay
    && hasGenerationPoll(pid)
    && generationWatchOverlay.kind !== "wiring"
    && generationWatchOverlay.kind !== "rigging"
    && generationWatchOverlay.kind !== "build"
    && generationWatchOverlay.kind !== "video"
    && !isVideoGenerationKind(generationWatchOverlay);
}

function markAdditionalGenerationPending({
  prompt = "",
  mode = "",
  targetMode = "",
  usedCanvas = false,
  model = "",
  provider = "",
  source = "",
} = {}) {
  if (!generationWatchOverlay) return false;
  const live = liveServerCadJobs(allProjects.find((p) => p.id === generationWatchPid)?.generation);
  generationWatchOverlay.pendingStart = true;
  generationWatchOverlay.pendingStartedAt = Date.now();
  generationWatchOverlay.pendingBaselineCount = additionalPendingBaseline(live.length);
  generationWatchOverlay.focusedJobId = "pending";
  generationWatchOverlay.prompt = prompt || generationWatchOverlay.prompt;
  if (mode) generationWatchOverlay.promptMode = mode;
  const resolvedTarget = String(targetMode || "").toLowerCase();
  if (resolvedTarget === "edit" || resolvedTarget === "new") {
    generationWatchOverlay.targetMode = resolvedTarget;
  }
  if (usedCanvas) {
    generationWatchOverlay.from_canvas = true;
    generationWatchOverlay.usedCanvas = true;
  }
  if (model) generationWatchOverlay.model = model;
  if (provider) generationWatchOverlay.provider = provider;
  if (source) generationWatchOverlay.source = source;
  generationWatchOverlay.message = "Starting another generation…";
  generationWatchOverlay.progress = {
    pct: 3,
    label: "Starting another generation…",
    thinking: "Improving prompt and queueing another CAD job…",
    spiceHold: true,
  };
  syncViewportGenerationOverlay();
  syncStopButtonVisibility();
  return true;
}

function serverGenerationIsLive(gen, jobs = []) {
  if (String(gen?.status || "").toLowerCase() === "running") return true;
  return (Array.isArray(jobs) ? jobs : []).some((job) => (
    !isPendingGenerationJob(job) && String(job?.status || "").toLowerCase() === "running"
  ));
}

function generationBelongsToCurrentWatch(gen = {}) {
  const watchStarted = Number(generationWatchOverlay?.startedAt) || 0;
  if (!watchStarted) return false;
  for (const key of ["started_at", "finished_at"]) {
    const ts = new Date(gen?.[key] || "").getTime();
    if (Number.isFinite(ts) && ts >= watchStarted - 250) return true;
  }
  return false;
}

async function keepRiggingGenerationOpenIfRunning(pid = projectId, status = null) {
  if (!pid) return false;
  try {
    const gen = await api(`/api/projects/${pid}/generation`);
    const runningJobs = generationRunningJobs(gen);
    const riggingRunning = gen?.status === "running" && (
      isRiggingGeneration(gen)
      || runningJobs.some((job) => isRiggingGeneration(job))
    );
    if (!riggingRunning) return false;
    const proj = allProjects.find((p) => p.id === pid);
    if (proj) proj.generation = gen;
    if (generationWatchPid !== pid || !hasGenerationPoll(pid)) {
      beginGenerationWatch(pid, {
        kind: "rigging",
        mode: "rigging",
        pendingStart: false,
        model: gen.model,
        provider: gen.provider,
      });
    } else if (generationWatchOverlay) {
      Object.assign(generationWatchOverlay, {
        kind: "rigging",
        promptMode: "rigging",
        pendingStart: false,
        ...promptGenerationOverlayOpts("rigging"),
      });
    }
    renderProjectList();
    syncViewportGenerationOverlay();
    syncStopButtonVisibility();
    if (status) {
      status.className = "status loading";
      status.textContent = "Robot artifact generation is running… safe to refresh or switch projects.";
    }
    setEditStatus("loading", "Robot artifact generation is running…");
    return true;
  } catch {
    return false;
  }
}

function activeCadGenerationCount(pid = projectId) {
  if (!pid) return 0;
  const gen = allProjects.find((p) => p.id === pid)?.generation;
  const jobs = generationRunningJobs(gen, generationWatchPid === pid ? generationWatchOverlay : null);
  const cachedCount = Math.max(Number(gen?.running_count || 0), jobs.length);
  if (cachedCount > 0) return cachedCount;
  if (generationWatchPid === pid && generationWatchOverlay?.kind !== "wiring") return 1;
  if (viewportOverlayPid === pid && viewportOverlayState?.kind !== "wiring") return 1;
  return isProjectGenerating(pid) ? 1 : 0;
}

function promptGenerateButtonLabel(mode = promptMode, runningCount = activeCadGenerationCount()) {
  const busy = runningCount > 0;
  if (busy) return runningCount > 1 ? `Generate another (${runningCount} running)` : "Generate another";
  if (mode === "render") return "Render scene";
  if (mode === "draw") return "Apply Draw command";
  if (mode === "architect") return "Generate modular house part";
  if (mode === "mesh") return "Generate mesh";
  if (mode === "fusion") return "Generate mesh";
  if (mode === "v2") return "Generate with CAD";
  return "Generate / modify with AI";
}

function sessionUserForGeneration() {
  return currentUser || getStoredUser() || null;
}

function generationCollaboratorById(userId) {
  const uid = String(userId || "").trim();
  if (!uid) return null;
  try {
    const remotes = collab?.getRemoteUsers?.() || [];
    return remotes.find((u) => String(u?.id || u?.user_id || "") === uid) || null;
  } catch {
    return null;
  }
}

function resolveLiveGenerationIdentity(gen = {}) {
  const pid = projectId || generationWatchPid;
  const live = allProjects.find((p) => p.id === pid)?.generation || {};
  const overlay = generationWatchPid === pid ? generationWatchOverlay : null;
  const jobs = generationRunningJobs(gen?.status || gen?.by_user_id || gen?.by_user_name ? gen : live, overlay);
  const leadId = gen?.by_user_id || jobs[0]?.by_user_id || live?.by_user_id || overlay?.by_user_id;
  return resolveGenerationIdentity(gen, {
    liveGen: live,
    jobs,
    overlay,
    sessionUser: sessionUserForGeneration(),
    collaborator: generationCollaboratorById(leadId),
  });
}

function generationUserAvatar(gen = {}) {
  const ident = resolveLiveGenerationIdentity(gen);
  const name = ident.by_user_name || gen.by_user_name || "AI";
  const initial = appEscapeHtml(String(name).trim().charAt(0).toUpperCase() || "A");
  const avatar = ident.by_avatar_url || gen.by_avatar_url || "";
  if (avatar) {
    return `<span class="vgu-avatar vgu-avatar--image" style="background-image:url('${appEscapeHtml(avatar)}')"></span>`;
  }
  return `<span class="vgu-avatar">${initial}</span>`;
}

function isRiggingGeneration(gen = {}) {
  return String(gen?.kind || "").toLowerCase() === "rigging"
    || generationPromptMode(gen) === "rigging";
}

function generationStatusElementId(gen = {}) {
  if (String(gen?.kind || "").toLowerCase() === "wiring") return "wiring-prompt-status";
  if (isRiggingGeneration(gen)) return "rigging-prompt-status";
  return "prompt-status";
}

function showModelReadyBanner(message, statusElementId = "prompt-status") {
  const text = String(message || "").trim();
  if (!text) return;
  const statusEl = document.getElementById(statusElementId);
  if (statusEl) {
    statusEl.className = "status ok";
    statusEl.textContent = text;
  }
  const overlay = statusElementId === "wiring-prompt-status"
    ? (wiringOverlay || window.Render3DViewerOverlay)
    : window.Render3DViewerOverlay;
  overlay?.showReadyBanner?.(text);
}

function isOwnGeneration(gen = {}) {
  const ident = resolveLiveGenerationIdentity(gen);
  return generationBelongsToSessionUser(ident, sessionUserForGeneration());
}

function isVrGenerationClient(gen = {}) {
  const jobs = Array.isArray(gen?.running_jobs) && gen.running_jobs.length
    ? gen.running_jobs
    : Array.isArray(gen?.jobs)
      ? gen.jobs.filter((job) => job?.status === "running")
      : [];
  const lead = jobs[0] || gen || {};
  const token = String(
    lead.client
    || gen.client
    || lead.request_body?.client
    || gen.request_body?.client
    || "",
  ).toLowerCase();
  return token === "xr" || token === "vr" || token === "headset" || token === "quest";
}

function generationKindBadge(gen = {}) {
  const kind = String(gen.kind || "").toLowerCase();
  const mode = generationPromptMode(gen);
  const rendering = kind === "render" || kind === "scene_render" || kind === "render_region_edit" || mode === "render";
  const meshish = !rendering && ["mesh", "mesh_beta"].includes(mode);
  const v2ish = !rendering && !meshish && ["v2", "vibecad", "mac", "architect", "jake"].includes(mode);
  const rigging = isRiggingGeneration(gen);
  const vr = isVrGenerationClient(gen);
  if (vr) {
    if (rigging) return "VR RIG";
    if (kind === "video" || kind === "film_edit" || kind === "film-edit" || kind === "video_edit") return "VR VIDEO";
    if (kind === "improve_lab") return "VR LAB";
    if (rendering) return "VR Render";
    if (meshish) return "VR Mesh";
    if (v2ish) return "VR CAD";
    return "VR AI";
  }
  if (kind === "improve_lab") return "LAB";
  if (kind === "video" || kind === "film_edit" || kind === "film-edit" || kind === "video_edit") return "VIDEO";
  return rigging ? "RIG" : rendering ? "RENDER" : meshish ? "MESH" : v2ish ? "CAD" : "AI";
}

function hideViewportGenerationUserBadge({ resetExpand = false } = {}) {
  const btn = document.getElementById("viewport-generation-user");
  if (resetExpand) viewportGenerationUserExpanded = false;
  if (!btn) return;
  btn.classList.add("hidden");
  btn.classList.remove(
    "viewport-generation-user--rigging",
    "viewport-generation-user--prompt",
    "viewport-generation-user--v2",
    "viewport-generation-user--mesh",
    "viewport-generation-user--render",
    "viewport-generation-user--beside-browser",
    "viewport-generation-user--stack",
    "viewport-generation-user--expanded",
  );
  btn.style.left = "";
  btn.style.top = "";
  btn.innerHTML = "";
  delete btn.dataset.prompt;
  delete btn.dataset.user;
  delete btn.dataset.userId;
}

function generationHudBrand(gen = {}) {
  const overlay = generationWatchPid === projectId ? generationWatchOverlay : null;
  let clicked = {};
  try {
    clicked = getSelectedPromptModelInfo() || {};
  } catch {
    clicked = {};
  }
  return {
    model: String(overlay?.model || gen.model || clicked.model || "").trim(),
    provider: String(overlay?.provider || gen.provider || clicked.provider || "").trim(),
    source: String(overlay?.source || gen.source || clicked.source || "").trim(),
  };
}

function generationJobKindFlags(gen = {}) {
  const kind = String(gen.kind || generationWatchOverlay?.kind || "prompt").toLowerCase();
  const mode = generationPromptMode(gen);
  const rendering = kind === "render" || kind === "scene_render" || kind === "render_region_edit" || mode === "render";
  const meshish = !rendering && ["mesh", "mesh_beta"].includes(mode);
  const v2ish = !rendering && !meshish && ["v2", "vibecad", "mac", "architect", "jake"].includes(mode);
  const rigging = isRiggingGeneration(gen);
  return { kind, mode, rendering, meshish, v2ish, rigging, vr: isVrGenerationClient(gen) };
}

function generationForMeVerb(gen = {}) {
  const { kind, rigging, rendering, meshish, v2ish, vr } = generationJobKindFlags(gen);
  if (kind === "video" || kind === "film_edit" || kind === "film-edit" || kind === "video_edit") {
    return vr ? "generating VR video for me" : "generating video for me";
  }
  if (rigging) return vr ? "generating VR rigging for me" : "generating rigging for me";
  if (rendering) return vr ? "generating VR Render for me" : "rendering for me";
  if (meshish) return vr ? "generating VR Mesh for me" : "generating Mesh for me";
  if (v2ish) return vr ? "generating VR CAD for me" : "generating CAD for me";
  return vr ? "generating with VR AI for me" : "generating for me";
}

function liveJobsForGenerationBadge(gen) {
  const pid = projectId || generationWatchPid;
  const live = allProjects.find((p) => p.id === pid)?.generation || gen || {};
  const overlay = generationWatchPid === pid ? generationWatchOverlay : null;
  const fromLive = generationRunningJobs(live, overlay);
  if (fromLive.length) return { live, overlay, jobs: fromLive };
  if (gen && gen !== live) {
    const fromGen = generationRunningJobs(gen, overlay);
    if (fromGen.length) return { live: gen, overlay, jobs: fromGen };
  }
  return { live, overlay, jobs: fromLive };
}

function collaboratorPeopleForBadge(gen) {
  const session = sessionUserForGeneration();
  const { live, overlay, jobs } = liveJobsForGenerationBadge(gen);
  return collaboratorGeneratingPeople(jobs, session, {
    liveGen: live,
    overlay,
    sessionUser: session,
  });
}

function ownRunningJobForHud(gen, jobs = []) {
  const session = sessionUserForGeneration();
  const ownJob = (Array.isArray(jobs) ? jobs : []).find((job) => (
    generationBelongsToSessionUser(
      resolveGenerationIdentity(job, { sessionUser: session, jobs: [job] }),
      session,
    )
  ));
  if (ownJob) return ownJob;
  if (gen && String(gen.status || "").toLowerCase() === "running" && gen.kind !== "wiring" && isOwnGeneration(gen)) {
    return gen;
  }
  return null;
}

function syncOwnGenerationHudCard(gen, jobs = []) {
  const source = ownRunningJobForHud(gen, jobs);
  if (!source) {
    try { window.Render3DViewerOverlay?.setGeneratorInfo?.(null); } catch (_) { }
    return;
  }
  const ident = resolveLiveGenerationIdentity(source);
  const name = ident.by_user_name || source.by_user_name || sessionUserForGeneration()?.display_name || "Someone";
  const pctRaw = Number(source.progress?.pct ?? source.pct);
  const brand = generationHudBrand(source);
  try {
    window.Render3DViewerOverlay?.setGeneratorInfo?.({
      status: "running",
      by_user_name: name,
      by_user_id: ident.by_user_id || source.by_user_id || "",
      by_user_email: ident.by_user_email || source.by_user_email || "",
      by_avatar_url: ident.by_avatar_url || source.by_avatar_url || "",
      provider: brand.provider,
      model: brand.model,
      source: brand.source,
      pct: Number.isFinite(pctRaw) ? pctRaw : undefined,
      progress: source.progress || (Number.isFinite(pctRaw) ? { pct: pctRaw } : undefined),
      brandLocked: true,
    });
  } catch (_) { }
}

function viewportGenerationPersonHtml(person) {
  const gen = { ...(person.job || {}), ...person };
  const name = person.by_user_name || gen.by_user_name || "Someone";
  const first = String(name).trim().split(/\s+/)[0] || "Someone";
  const prompt = collapseRepeatedSpokenPrompt(gen.prompt || gen.label || "") || "Generating model";
  const { rigging, rendering, meshish, v2ish } = generationJobKindFlags(gen);
  const pctRaw = Number(person.pct ?? gen.progress?.pct ?? gen.pct);
  const pctLabel = Number.isFinite(pctRaw)
    ? `${Math.round(Math.max(0, Math.min(100, pctRaw)))}%`
    : "";
  const kindClass = rigging
    ? "viewport-generation-user--rigging"
    : rendering
      ? "viewport-generation-user--render"
      : meshish
        ? "viewport-generation-user--mesh"
        : v2ish
          ? "viewport-generation-user--v2"
          : "viewport-generation-user--prompt";
  return `
    <span class="vgu-person ${kindClass}"
      data-user-id="${appEscapeHtml(person.by_user_id || "")}"
      data-user="${appEscapeHtml(name)}"
      data-prompt="${appEscapeHtml(prompt)}"
      role="button">
      ${generationUserAvatar({ ...gen, ...person })}
      ${rigging ? '<span class="vgu-kind-icon" aria-hidden="true"><svg viewBox="0 0 16 16"><path d="M4 12.5h8M5 12.5V9l3-3 3 3v3.5M8 6V2.5M6.5 4h3M8 2.5l2 1.5M8 2.5 6 4" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>' : ""}
      <span class="vgu-copy"><strong>${appEscapeHtml(first)}</strong><small>… ${generationForMeVerb(gen)}${pctLabel ? ` · ${pctLabel}` : ""}</small></span>
      ${pctLabel ? `<span class="vgu-pct" aria-label="${pctLabel} complete">${pctLabel}</span>` : ""}
      <span class="vgu-ai">${appEscapeHtml(generationKindBadge(gen))}</span>
    </span>
  `;
}

function applyViewportGenerationKindClasses(btn, people) {
  const lead = people[0]?.job || people[0] || {};
  const { rigging, rendering, meshish, v2ish } = generationJobKindFlags(lead);
  btn.classList.toggle("viewport-generation-user--rigging", rigging && people.length === 1);
  btn.classList.toggle("viewport-generation-user--render", !rigging && rendering && people.length === 1);
  btn.classList.toggle("viewport-generation-user--mesh", !rigging && meshish && people.length === 1);
  btn.classList.toggle("viewport-generation-user--v2", !rigging && v2ish && people.length === 1);
  btn.classList.toggle("viewport-generation-user--prompt", !rigging && !rendering && !meshish && !v2ish && people.length === 1);
}

function syncViewportGenerationUserBadge(gen) {
  const btn = document.getElementById("viewport-generation-user");
  if (!btn) return;
  const { jobs } = liveJobsForGenerationBadge(gen);
  const people = collaboratorPeopleForBadge(gen);
  viewportCollaboratorGenerators = people;
  const ownJob = ownRunningJobForHud(gen, jobs);
  const idle = !gen || gen.status !== "running" || gen.kind === "wiring";
  if (idle && !people.length && !ownJob) {
    hideViewportGenerationUserBadge({ resetExpand: true });
    try { window.Render3DViewerOverlay?.setGeneratorInfo?.(null); } catch (_) { }
    return;
  }
  syncOwnGenerationHudCard(gen, jobs);
  if (!people.length) {
    hideViewportGenerationUserBadge({ resetExpand: true });
    return;
  }
  const names = people.map((p) => p.by_user_name || "Someone");
  const title = names.length === 1
    ? `${names[0]} is generating with AI`
    : `${names.join(", ")} are generating with AI`;
  btn.classList.remove("hidden");
  applyViewportGenerationKindClasses(btn, people);
  btn.title = title;
  btn.setAttribute("aria-label", title);
  btn.dataset.user = names[0] || "Someone";
  btn.dataset.userId = people[0]?.by_user_id || "";
  btn.dataset.prompt = people[0]?.job?.prompt || people[0]?.job?.label || "";
  const showStack = people.length > 1 && !viewportGenerationUserExpanded;
  btn.classList.toggle("viewport-generation-user--stack", showStack);
  btn.classList.toggle("viewport-generation-user--expanded", people.length > 1 && viewportGenerationUserExpanded);
  if (showStack) {
    btn.innerHTML = `
      <span class="vgu-stack" aria-hidden="true">
        ${people.map((person, idx) => `
          <span class="vgu-stack-slot" style="z-index:${people.length - idx}">
            ${generationUserAvatar({ ...(person.job || {}), ...person })}
          </span>
        `).join("")}
      </span>
    `;
  } else if (people.length === 1) {
    btn.innerHTML = viewportGenerationPersonHtml(people[0]);
  } else {
    btn.innerHTML = `<span class="vgu-strip">${people.map((person) => viewportGenerationPersonHtml(person)).join("")}</span>`;
  }
  syncViewportGenerationBesideBrowser();
}

/** Park the generating pill just right of the open Browser panel (not on top of it). */
function syncViewportGenerationBesideBrowser() {
  const btn = document.getElementById("viewport-generation-user");
  const panel = document.getElementById("viewport-browser-panel");
  const viewport = document.getElementById("viewport");
  if (!btn || btn.classList.contains("hidden")) return;
  const browserOpen = !!(
    panel
    && !panel.classList.contains("hidden")
    && !panel.hidden
    && panel.getClientRects().length
  );
  btn.classList.toggle("viewport-generation-user--beside-browser", browserOpen);
  if (!browserOpen || !viewport) {
    btn.style.left = "";
    btn.style.top = "";
    return;
  }
  const vRect = viewport.getBoundingClientRect();
  const pRect = panel.getBoundingClientRect();
  const left = Math.round(Math.max(14, pRect.right - vRect.left + 10));
  const top = Math.round(Math.max(12, pRect.top - vRect.top));
  const maxLeft = Math.max(14, vRect.width - 170);
  btn.style.left = `${Math.min(left, maxLeft)}px`;
  btn.style.top = `${top}px`;
}

window.addEventListener("resize", () => {
  syncViewportGenerationBesideBrowser();
});

function closeViewportPromptDropdown() {
  viewportPromptDropdown?.remove();
  viewportPromptDropdown = null;
}

function promptHistoryUserKey(entry = {}) {
  return entry.user_id || entry.user_name || "";
}

function latestPromptsForGenerationUser(userId, userName, limit = 5) {
  const wanted = userId || userName || "";
  const byUser = latestPromptHistoryEntries
    .filter((entry) => entry.prompt && promptHistoryUserKey(entry) === wanted)
    .sort((a, b) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime())
    .slice(0, limit);
  if (byUser.length || !userName) return byUser;
  return latestPromptHistoryEntries
    .filter((entry) => entry.prompt && entry.user_name === userName)
    .sort((a, b) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime())
    .slice(0, limit);
}

function showViewportPromptDropdown(anchor, entries) {
  closeViewportPromptDropdown();
  if (!anchor || !entries.length) return;
  const menu = document.createElement("div");
  menu.className = "ph-person-menu vgu-prompt-menu";
  menu.innerHTML = `
    <div class="ph-person-menu-title">Latest prompts</div>
    ${entries.map((entry, idx) => `
      <button type="button" data-prompt-index="${idx}">
        <strong>${idx === 0 ? "Latest" : new Date(entry.created_at || 0).toLocaleString([], { dateStyle: "short", timeStyle: "short" })}</strong>
        <span>${appEscapeHtml(entry.prompt)}</span>
      </button>
    `).join("")}
  `;
  document.body.appendChild(menu);
  const rect = anchor.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  menu.style.left = `${Math.max(10, Math.min(rect.left, window.innerWidth - menuRect.width - 10))}px`;
  menu.style.top = `${Math.max(10, Math.min(rect.bottom + 8, window.innerHeight - menuRect.height - 10))}px`;
  menu.addEventListener("click", async (event) => {
    const btn = event.target.closest("button[data-prompt-index]");
    if (!btn) return;
    const entry = entries[Number(btn.dataset.promptIndex)];
    if (!entry) return;
    const ok = await copyText(entry.prompt);
    setEditStatus(ok ? "ok" : "error", ok ? "Copied to clipboard: prompt." : "Could not copy prompt.");
    closeViewportPromptDropdown();
  });
  viewportPromptDropdown = menu;
}

function showViewportOverlay(pid, message, opts = {}) {
  if (!pid) return;
  viewportOverlayPid = pid;
  viewportOverlayState = { message, ...opts };
  syncViewportGenerationOverlay();
  syncStopButtonVisibility();
}

function hideViewportOverlay(pid, completeOpts = {}) {
  if (pid != null && viewportOverlayPid !== pid) return;
  viewportOverlayPid = null;
  viewportOverlayState = null;
  syncViewportGenerationOverlay(completeOpts);
  syncStopButtonVisibility();
}

function isGenerationUiActive(pid = projectId) {
  if (!pid) return false;
  if (generationWatchPid === pid) return true;
  if (viewportOverlayPid === pid && viewerOverlay.isGenerating?.()) return true;
  return isProjectGenerating(pid);
}

function isProjectGenerating(id) {
  if (!id) return false;
  if (generationWatchPid === id) return true;
  const proj = allProjects.find((p) => p.id === id);
  const gen = proj?.generation;
  if (!gen) return false;
  if (gen.status === "running") return true;
  return Number(gen.running_count || 0) > 0 || generationRunningJobs(gen).length > 0;
}

function isRecentRunningGeneration(gen) {
  if (!gen) return false;
  const running = String(gen.status || "") === "running"
    || Number(gen.running_count || 0) > 0
    || generationRunningJobs(gen).length > 0;
  if (!running) return false;
  const ts = Date.parse(gen.started_at || "") || 0;
  return ts > 0 && Date.now() - ts < 90 * 60 * 1000;
}

const LS_CANVAS_GEN = "render3d:canvas-gen-pending";
let canvasStoreName = "Canvas";
let canvasAutosaveTimer = 0;
let canvasBoardDirty = false;
let canvasBoardSwitching = false;
let canvasBoardLoadedFor = "";
let canvasActiveTabId = CANVAS_TAB_ID;
const canvasTabStores = new Map();

function markCanvasGenerationPending(pid = projectId) {
  if (!pid || !document.body.classList.contains("canvas-design-tab")) return;
  try {
    sessionStorage.setItem(LS_CANVAS_GEN, JSON.stringify({ pid, at: Date.now() }));
  } catch (_) { }
}

function clearCanvasGenerationPending(pid = projectId) {
  try {
    const raw = sessionStorage.getItem(LS_CANVAS_GEN);
    if (!raw) return;
    const data = JSON.parse(raw);
    if (!pid || data?.pid === pid) sessionStorage.removeItem(LS_CANVAS_GEN);
  } catch (_) { }
}

function syncCanvasGenerationUi() {
  const banner = document.getElementById("canvas-generation-banner");
  const messageEl = document.getElementById("canvas-generation-message");
  if (!banner) {
    try { viewerOverlay.syncHost?.(); } catch (_) { /* overlay may not be ready */ }
    return;
  }
  const active =
    document.body.classList.contains("canvas-design-tab")
    && projectId
    && isGenerationUiActive(projectId)
    && isCadGenerationActive(projectId);
  // Same viewport generate tab docks onto the canvas; hide the old top banner.
  banner.classList.add("hidden");
  try { viewerOverlay.syncHost?.(); } catch (_) { /* overlay may not be ready */ }
  if (!active) return;
  const msg =
    generationWatchOverlay?.message
    || "Generating 3D model in background — safe to switch tabs or refresh.";
  if (messageEl) {
    messageEl.textContent = msg.replace(/\s*\(safe to refresh\)/i, " — safe to switch tabs or refresh");
  }
  const statusEl = document.getElementById("prompt-status");
  if (statusEl && !statusEl.textContent) {
    statusEl.className = "status loading";
    statusEl.textContent = "Generating in background… safe to switch tabs or refresh.";
  }
}

let resumeGenerationAbort = null; // leakfix48
async function resumeGenerationFromProjects() {
  if (resumeGenerationAbort) {
    try { resumeGenerationAbort.abort(); } catch (_) { /* ignore */ }
    resumeGenerationAbort = null;
  }
  if (!projectId) return;
  const proj = allProjects.find((p) => p.id === projectId);
  if (proj?.generation?.status === "running") {
    await resumeGenerationIfNeeded(projectId, proj.generation);
    return;
  }
  const ctl = new AbortController();
  resumeGenerationAbort = ctl;
  try {
    const gen = await api(`/api/projects/${projectId}/generation`, { signal: ctl.signal });
    if (ctl.signal.aborted) return;
    if (gen?.status === "running") {
      const cached = allProjects.find((p) => p.id === projectId);
      if (cached) cached.generation = gen;
      await resumeGenerationIfNeeded(projectId, gen);
    }
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return;
  } finally {
    if (resumeGenerationAbort === ctl) resumeGenerationAbort = null;
  }
}

function generationAppliedKey(pid) {
  return `render3d:gen-applied:${pid}`;
}

function generationAppliedSet(pid) {
  if (!pid) return new Set();
  try {
    const raw = localStorage.getItem(generationAppliedKey(pid));
    if (!raw) return new Set();
    if (raw.trim().startsWith("[")) {
      const parsed = JSON.parse(raw);
      return new Set(Array.isArray(parsed) ? parsed.map(String).filter(Boolean) : []);
    }
    return new Set([raw]);
  } catch {
    return new Set();
  }
}

function wasGenerationApplied(pid, traceId) {
  if (!pid || !traceId) return false;
  return generationAppliedSet(pid).has(String(traceId));
}

function markGenerationApplied(pid, traceId) {
  if (!pid || !traceId) return;
  try {
    const traces = generationAppliedSet(pid);
    traces.add(String(traceId));
    localStorage.setItem(generationAppliedKey(pid), JSON.stringify([...traces].slice(-40)));
  } catch (_) { }
}

const pendingViewportReveal = new Set();

function pendingViewportRevealKey() {
  return "render3d:pending-viewport-reveal";
}

function markPendingViewportReveal(pid) {
  if (!pid) return;
  pendingViewportReveal.add(pid);
  try {
    const raw = JSON.parse(localStorage.getItem(pendingViewportRevealKey()) || "[]");
    const all = Array.isArray(raw) ? raw.map(String) : [];
    if (!all.includes(pid)) all.push(pid);
    localStorage.setItem(pendingViewportRevealKey(), JSON.stringify(all.slice(-80)));
  } catch (_) { }
}

function clearPendingViewportReveal(pid) {
  if (!pid) return;
  pendingViewportReveal.delete(pid);
  try {
    const raw = JSON.parse(localStorage.getItem(pendingViewportRevealKey()) || "[]");
    const all = (Array.isArray(raw) ? raw.map(String) : []).filter((id) => id !== pid);
    localStorage.setItem(pendingViewportRevealKey(), JSON.stringify(all));
  } catch (_) { }
}

function hasPendingViewportReveal(pid) {
  if (!pid) return false;
  if (pendingViewportReveal.has(pid)) return true;
  try {
    const raw = JSON.parse(localStorage.getItem(pendingViewportRevealKey()) || "[]");
    return Array.isArray(raw) && raw.map(String).includes(pid);
  } catch {
    return false;
  }
}

function jobFinishedDuringCurrentWatch(job = {}) {
  if (!generationWatchOverlay?.startedAt) return true;
  const watchStarted = Number(generationWatchOverlay.startedAt) || 0;
  const slackMs = 5000;
  let sawTs = false;
  for (const key of ["finished_at", "updated_at", "started_at"]) {
    const value = job?.[key];
    if (!value) continue;
    sawTs = true;
    const ts = new Date(value).getTime();
    if (Number.isFinite(ts) && ts >= watchStarted - slackMs) return true;
  }
  // Jobs without timestamps are the live watch — do not skip apply.
  return !sawTs;
}

let promptHistoryFollowupTimer = 0; // leakfix13
function schedulePromptHistoryFollowupRefresh(pid = projectId, delayMs = 1600) {
  if (!pid || pid !== projectId) return;
  if (promptHistoryFollowupTimer) window.clearTimeout(promptHistoryFollowupTimer);
  promptHistoryFollowupTimer = window.setTimeout(() => {
    promptHistoryFollowupTimer = 0;
    if (projectId === pid) void refreshPromptHistory();
  }, delayMs);
}

function isImproveLabJob(gen = {}) {
  const kind = String(gen.kind || "").toLowerCase();
  if (kind === "improve_lab") return true;
  return Boolean(gen.request_body?.lab_session_id || gen.lab_session_id);
}

async function applyImproveLabJobComplete(job, pid = projectId) {
  if (!job) return;
  const slot = Number(job.lab_slot ?? job.request_body?.lab_slot);
  if (Number.isFinite(slot)) {
    contextLabUI?.updateLabSlot?.(slot, {
      url: job.filename,
      filename: job.filename,
      status: "complete",
      label: job.label,
    });
  }
  if (pid === projectId) {
    void refreshFiles();
    const statusEl = document.getElementById("prompt-status");
    if (statusEl) {
      statusEl.className = "status ok";
      statusEl.textContent = "Improve Lab slot ready — 4-up overlay, not the main timeline.";
    }
  }
  markGenerationApplied(pid, job.trace_id);
}

async function applyVideoGenerationComplete(gen, pid = projectId) {
  emitVideoGeneration(gen, pid, "complete");
  const editorName = String(gen.editor_name || gen.request_body?.editor_name || "").trim();
  if (editorName && readyVideoEdits.get(pid)?.trace_id !== gen.trace_id) {
    readyVideoEdits.set(pid, { editor_name: editorName, trace_id: gen.trace_id });
    const notice = document.createElement("div");
    notice.className = "video-edit-ready-notice";
    notice.setAttribute("role", "status");
    const label = document.createElement("span");
    label.textContent = `Render Agent: AI edit clip ready in ${editorName}.`;
    const open = document.createElement("button");
    open.type = "button";
    open.textContent = "Open editor";
    open.addEventListener("click", () => {
      void openReadyVideoEditor(pid, editorName);
      notice.remove();
    });
    const close = document.createElement("button");
    close.type = "button";
    close.className = "video-edit-ready-notice-close";
    close.setAttribute("aria-label", "Close video editor notification");
    close.title = "Close";
    close.textContent = "\u00d7";
    close.addEventListener("click", () => notice.remove());
    notice.append(label, open, close);
    document.body.appendChild(notice);
    renderAgentUi?.announce?.(`AI edit clip ready in ${editorName}. Use “Open editor” in the notification or project panel.`, { ping: true });
  }
  markGenerationApplied(pid, gen.trace_id);
  newlyCompletedProjects.add(pid);
  renderProjectList();
  try { viewportVideoRecorder?.resumeFilmJob?.(); } catch (_) { /* editor may not be open */ }
}

async function openReadyVideoEditor(pid, editorName) {
  if (pid !== projectId) await openProjectById(pid, { throwOnError: true });
  if (pid !== projectId) return;
  readyVideoEdits.delete(pid);
  renderProjectList();
  await viewportVideoRecorder?.openEditorProject?.(editorName);
}

async function applyGenerationComplete(gen, pid = projectId) {
  if (isVideoGenerationKind(gen)) {
    await applyVideoGenerationComplete(gen, pid);
    return;
  }
  if (isImproveLabJob(gen)) {
    await applyImproveLabJobComplete(gen, pid);
    return;
  }
  if (!gen?.filename || !pid) return;
  const deferViewport = shouldDeferCompletedJobViewport({
    completedTraceId: gen.trace_id,
    runningJobs: generationRunningJobs(
      allProjects.find((p) => p.id === pid)?.generation,
      generationWatchPid === pid ? generationWatchOverlay : null,
    ),
    pendingStart: generationWatchPid === pid && !!generationWatchOverlay?.pendingStart,
    pendingBaselineCount: generationWatchPid === pid
      ? Number(generationWatchOverlay?.pendingBaselineCount || 0)
      : 0,
  });
  if (pid === projectId && deferViewport) {
    // Another Generate another job still owns the overlay / live mesh.
    syncPendingPromptHistoryFromGeneration(gen, pid);
    newlyCompletedProjects.add(pid);
    renderProjectList();
    await refreshFiles();
    await refreshTimeline();
    await refreshPromptHistory();
    markGenerationApplied(pid, gen.trace_id);
    syncViewportGenerationOverlay();
    syncStopButtonVisibility();
    notifyAgentFinish({ kind: generationFinishKind(gen), pid, gen });
    window.dispatchEvent(new CustomEvent("render3d:generation-settled", {
      detail: { ...gen, projectId: pid, status: "complete" },
    }));
    return;
  }
  syncPendingPromptHistoryFromGeneration(gen, pid);
  window.dispatchEvent(new CustomEvent("render3d:model", { detail: { ...gen, projectId: pid } }));
  emitQuest("welcome-first-generate", "Generate your first part");
  emitQuest("ai-generate", "Generate CAD with AI");
  // Always mark the project as having a new model — badge shows in the explorer
  // for every completion and is cleared when the user clicks on the project.
  newlyCompletedProjects.add(pid);
  renderProjectList();
  if (pid === projectId) {
    const completionMode = generationPromptMode(
      gen,
      generationWatchOverlay?.promptMode || (document.body.classList.contains("architect-design-tab") ? "architect" : "")
    );
    // CAD/Mesh completions must show the real model. If the user was in Rigging,
    // a placeholder URDF scene can leave the CAD assembly hidden → empty viewport.
    try {
      urdfRobotRuntime?.clear?.();
    } catch {
      /* optional */
    }
    setCadAssemblyHiddenForUrdf(false);
    if (
      document.body.classList.contains("rigging-design-tab")
      || document.body.classList.contains("canvas-design-tab")
      || workspaceModes?.getDesignTab?.() === "RIGGING"
    ) {
      workspaceModes?.setDesignTab?.("SOLID");
      ribbon?.setDesignTab?.("SOLID");
      exitRiggingMode();
    }
    saveActiveModelPromptState();
    try { disposeLiveGenerationPreview(); } catch (_) { }
    const preservedTexture = captureTextureForGeneratedReplacement(gen.filename);
    selectedFile = gen.filename;
    void refreshJointOverlay();
    const hiddenAfterReveal = setStoredComponentHidden(pid, gen.filename, false);
    projectTree.setHidden?.([...hiddenAfterReveal]);
    bumpModelCacheEpoch();
    await refreshFiles();
    if (pid !== projectId) {
      markPendingViewportReveal(pid);
      markGenerationApplied(pid, gen.trace_id);
      clearCanvasGenerationPending(pid);
      notifyAgentFinish({ kind: generationFinishKind(gen), pid, gen });
      window.dispatchEvent(new CustomEvent("render3d:generation-settled", {
        detail: { ...gen, projectId: pid, status: "complete" },
      }));
      return;
    }
    const placedFiles = (gen.placed_parts || []).map((part) => part.filename).filter(Boolean);
    const orientationMode = completionMode === "v2" && String(gen.target_mode || "").toLowerCase() !== "edit"
      ? "v2-upright"
      : null;
    const styleMode = (completionMode === "mesh" || completionMode === "mesh_beta" || completionMode === "mesh-beta")
      ? "shaded"
      : "auto";
    await reloadViewportFromProject({
      fitView: true,
      latestFile: gen.filename,
      placedFiles,
      // Keep other project components on screen after Mode 2.0 / Fusion finishes —
      // otherwise clear+reload of only the latest file makes siblings "disappear".
      loadAll: true,
      placeLatestBeside: String(gen.target_mode || gen.request_body?.target_mode || "new").toLowerCase() !== "edit",
      orientationMode,
      styleMode,
    });
    hideOverlappingScaledDuplicates(gen.filename);
    if (pid !== projectId) {
      markPendingViewportReveal(pid);
      markGenerationApplied(pid, gen.trace_id);
      clearCanvasGenerationPending(pid);
      notifyAgentFinish({ kind: generationFinishKind(gen), pid, gen });
      window.dispatchEvent(new CustomEvent("render3d:generation-settled", {
        detail: { ...gen, projectId: pid, status: "complete" },
      }));
      return;
    }
    setCadAssemblyHiddenForUrdf(false);
    restorePromptSelectionContext(pendingPromptSelectionContext, { resultFilename: gen.filename });
    viewerOverlay.clearError();
    await refreshTimeline();
    await refreshPromptHistory();
    schedulePromptHistoryFollowupRefresh(pid);
    showAiComposePanel();
    clearPromptComposeResult();
    await maybeReapplyCapturedTexture(preservedTexture, gen.filename);
    const statusEl = document.getElementById("prompt-status");
    if (statusEl) {
      const ref = gen.prompt_id
        ? formatPromptRef({
          promptId: gen.prompt_id,
          projectId: pid,
          filename: gen.filename,
          traceId: gen.trace_id,
          promptMode: gen.mode || gen.prompt_mode,
          model: gen.model,
          provider: gen.provider,
          skills: gen.skills || gen.request_body?.skills,
        })
        : "";
      statusEl.className = "status ok";
      statusEl.textContent = ref ? `Model ready · ${ref}` : "Model ready.";
    }
    setEditStatus("ok", "Model ready — opened in 3D view.");
    if (isVrGenerationClient(gen) && gen.filename) {
      registerXrCreationBody({
        filename: gen.filename,
        kind: "solid",
        createdAt: Date.now(),
      });
    }
    pendingPromptSelectionContext = null;
    try {
      if (document.body.classList.contains("xr-presenting") || viewportXR?.isPresenting?.()) {
        viewportXR?.setAiPanelStatus?.(
          `Model ready: ${gen.filename || "part"}`,
        );
        viewportXR?.refreshAiPromptPanel?.();
        if (!viewportXR?.isWorkshopActive?.()) void viewportXR.placeAfterProjectLoad?.({ attempts: 20, delayMs: 80 });
      }
    } catch (_) { }
    void maybeAskGenerateSimulatedMotion(gen, pid);
    void maybeShowElectronicsSuggestDockAfterGeneration(pid);
    clearPendingViewportReveal(pid);
  } else {
    // Finished while viewing another project — badge yes, viewport load on next open.
    markPendingViewportReveal(pid);
  }
  clearCanvasGenerationPending(pid);
  markGenerationApplied(pid, gen.trace_id);
  notifyAgentFinish({ kind: generationFinishKind(gen), pid, gen });
  window.dispatchEvent(new CustomEvent("render3d:generation-settled", {
    detail: { ...gen, projectId: pid, status: "complete" },
  }));
}

async function applyLiveModelReload(msg = {}, pid = msg.project_id || projectId) {
  if (!msg?.filename || !pid) return;
  syncPendingPromptHistoryFromGeneration(msg, pid);
  window.dispatchEvent(new CustomEvent("render3d:model", { detail: { ...msg, projectId: pid } }));
  if (pid !== projectId) {
    newlyCompletedProjects.add(pid);
    renderProjectList();
    return;
  }
  // Local transform/paint already ran afterModelEdit with a placement baseline.
  // Re-applying the same model.reload here races that swap and leaves twin meshes
  // (z-fighting / color flicker) that bounce between the pre/post poses.
  const action = String(msg.action || msg.kind || "").toLowerCase();
  const ownEdit =
    !!msg.by_user_id
    && !!currentUser?.id
    && msg.by_user_id === currentUser.id
    && (
      action === "transform"
      || action === "body_transform"
      || action === "paint"
      || action === "color"
      || action === "texture"
      || action === "face_pull"
      || action === "face_pad"
      || action === "create_primitive"
      // Mesh-fallback Create upload after the user already deleted the local solid.
      || (action === "upload" && suppressedCreateSolidFilenames.has(String(msg.filename || "")))
    );
  if (ownEdit) {
    if (msg.timeline_entry || msg.timeline) void refreshTimeline();
    return;
  }
  if (isDxfDrawingFilename(msg.filename)) {
    await refreshFiles();
    setEditStatus("ok", `Added DXF drawing ${msg.filename}. Open it from Reference Files when needed.`);
    return;
  }
  // Catalog STEP/GLB is a kernel input (VibeCAD `inputs[hw_*]`), not a Fusion-edged
  // viewport body. Reloading the assembly + EdgesGeometry on a fastener freezes the tab.
  if (isCatalogHardwareViewportEvent(msg)) {
    await refreshFiles();
    const label = msg.uploaded_filename || msg.filename;
    setEditStatus("ok", `Catalog hardware ${label} is on the server — Generate mates to the STEP.`);
    if (msg.timeline_entry || msg.timeline) void refreshTimeline();
    return;
  }
  const reloadMode = generationPromptMode(
    msg,
    generationWatchOverlay?.promptMode || (document.body.classList.contains("architect-design-tab") ? "architect" : "")
  );
  saveActiveModelPromptState();
  const preservedTexture = captureTextureForGeneratedReplacement(msg.filename);
  selectedFile = msg.filename;
  const hiddenAfterReveal = setStoredComponentHidden(pid, msg.filename, false);
  projectTree.setHidden?.([...hiddenAfterReveal]);
  bumpModelCacheEpoch();
  await refreshFiles();
  if (pid !== projectId) {
    newlyCompletedProjects.add(pid);
    renderProjectList();
    return;
  }
  const placedFiles = (msg.placed_parts || []).map((part) => part.filename).filter(Boolean);
  const orientationMode = reloadMode === "v2" && String(msg.target_mode || "").toLowerCase() !== "edit"
    ? "v2-upright"
    : null;
  // Transforms from teammates: swap one component in place (no full assembly reload).
  if (action === "transform" || action === "body_transform") {
    await afterModelEdit({
      ...msg,
      filename: msg.filename,
      url: msg.url || `/api/projects/${pid}/files/${encodeURIComponent(msg.filename)}`,
      replaceCatalog: msg.replace_catalog || msg.replaceCatalog || null,
      action: action === "body_transform" ? "body_transform" : "transform",
    });
    viewerOverlay.clearError();
    await refreshTimeline();
    return;
  }
  await reloadViewportFromProject({
    fitView: true,
    latestFile: msg.filename,
    placedFiles,
    loadAll: true,
    placeLatestBeside: String(msg.target_mode || msg.request_body?.target_mode || "new").toLowerCase() !== "edit",
    orientationMode,
  });
  if (pid !== projectId) {
    newlyCompletedProjects.add(pid);
    renderProjectList();
    return;
  }
  restorePromptSelectionContext(pendingPromptSelectionContext, { resultFilename: msg.filename });
  viewerOverlay.clearError();
  await refreshTimeline();
  await refreshPromptHistory();
  schedulePromptHistoryFollowupRefresh(pid);
  showAiComposePanel();
  await maybeReapplyCapturedTexture(preservedTexture, msg.filename);
  pendingPromptSelectionContext = null;
  void maybeShowElectronicsSuggestDockAfterGeneration(pid);
  if (viewportXR?.isPresenting?.()) {
    try {
      await viewportXR.placeAfterProjectLoad?.({ attempts: 20, delayMs: 80 });
    } catch (err) {
      console.warn("[xr] place after collab reload", err);
    }
    try { viewportXR.refreshAiPromptPanel?.(); } catch (_) { }
    try { viewportXR.setAiGenerating?.(false, ""); } catch (_) { }
  }
}

async function applyWiringGenerationComplete(gen, pid = projectId) {
  if (!pid || !getToken()) return;
  const copyContext = {
    promptId: gen.prompt_id,
    projectId: pid,
    filename: selectedFile,
    traceId: gen.trace_id,
    promptText: gen.prompt || lastPromptCopyContext?.promptText,
  };
  if (pid === projectId) {
    const schematic = await api(`/api/projects/${pid}/wiring`);
    if (pid !== projectId) return;
    wiringSim.applySchematic(schematic, { revealRequirements: true });
    invalidateWiringPrefetch();
    const liveBlocker = (gen?.blocker?.reason && gen.blocker)
      || (schematic?.blocker?.reason && schematic.blocker)
      || inferWiringBlocker(schematic);
    const statusEl = document.getElementById("wiring-prompt-status");
    if (liveBlocker?.reason) {
      if (statusEl) {
        statusEl.className = "status error";
        statusEl.textContent = "Could not complete this wiring — see the message on the canvas.";
      }
      wiringOverlay?.showError(liveBlocker.reason, {
        ...copyContext,
        suggestions: liveBlocker.suggestions || [],
      });
    } else {
      const ref = gen.prompt_id
        ? formatPromptRef({
          promptId: gen.prompt_id,
          projectId: pid,
          traceId: gen.trace_id,
          promptMode: gen.mode || gen.prompt_mode,
          model: gen.model,
          provider: gen.provider,
          skills: gen.skills || gen.request_body?.skills,
        })
        : (gen.trace_id ? `trace #${gen.trace_id}` : "");
      showModelReadyBanner(ref ? `Schematic ready · ${ref}` : "Schematic ready.", "wiring-prompt-status");
      wiringOverlay?.clearError();
    }
    await refreshFiles();
    const pendingId = lastPromptCopyContext?.promptHistoryId || gen.prompt_id;
    if (pendingId) {
      updatePendingPromptHistoryEntry(pendingId, {
        status: liveBlocker ? "failed" : "complete",
        success: !liveBlocker,
        trace_id: gen.trace_id,
        prompt_id: gen.prompt_id,
        error: liveBlocker?.reason || null,
      });
    }
    await refreshWiringPromptHistory();
    await refreshPromptHistory();
    showAiComposePanel();
  }
  newlyCompletedProjects.add(pid);
  renderProjectList();
  notifyAgentFinish({ kind: "wiring", pid, gen });
  markGenerationApplied(pid, gen.trace_id);
}

function inferWiringBlocker(schematic) {
  if (!schematic || schematic.blocker?.reason) return schematic?.blocker || null;
  const comps = (schematic.components || []).filter((c) => String(c?.type || "").toLowerCase() !== "breadboard");
  const wires = schematic.wires || [];
  if (comps.length < 2 || wires.length) return null;
  return {
    reason: schematic.description || schematic.notes?.[0] || "This circuit could not be wired as requested.",
    suggestions: [
      "Use the motor kit’s rated driver for coil power — not a logic HAT.",
      "Power the Pi from 5V only, then retry Wiring asking for STEP/DIR into that driver.",
    ],
  };
}

async function applyRiggingGenerationComplete(gen, pid = projectId) {
  if (!pid) return;
  if (pid === projectId) {
    const ref = gen.prompt_id
      ? formatPromptRef({
        promptId: gen.prompt_id,
        projectId: pid,
        traceId: gen.trace_id,
        promptMode: "rigging",
        model: gen.model,
        provider: gen.provider,
      })
      : (gen.trace_id ? `trace #${gen.trace_id}` : "");
    showModelReadyBanner(ref ? `Rigging ready · ${ref}` : (gen.message || "Rigging ready."), "rigging-prompt-status");
  }
  if (pid === projectId) {
    try {
      const rig = await api(`/api/projects/${pid}/rigging`);
      riggingEditor.applyRigData(rig);
    } catch {
      /* Some rigging runs may only update history; refresh the surrounding UI anyway. */
    }
    try { urdfRobotRuntime?.setPlaceholderVisualsVisible?.(false); } catch (_) { /* optional */ }
    try { setCadAssemblyHiddenForUrdf(false); } catch (_) { /* optional */ }
    await refreshFiles();
    await refreshRobotArtifacts({ quiet: true });
    await refreshRiggingPromptHistory();
    if (projectAssembly.count() === 0) {
      await reloadViewportFromProject({ fitView: true, loadAll: true });
    } else {
      try { fitCamera(); } catch (_) { /* optional */ }
    }
    setCadAssemblyHiddenForUrdf(false);
    setRiggingWorkspaceMode("urdf");
    await ensureUrdfRobotScene({ quiet: true, force: true });
    setCadAssemblyHiddenForUrdf(false);
    try { urdfRobotRuntime?.setPlaceholderVisualsVisible?.(false); } catch (_) { /* optional */ }
    await attachRobotPlaybackForLoadedModel(selectedFile, pid);
    setRiggingViewportPlaybackVisible(true);
    syncRiggingViewportPlaybackUi();
    syncRiggingViewportOverlay({ status: "Rigging ready — Play is on the viewport." });
    await syncRiggingAdjustSliders({ autoExpand: true });
    if (document.body.classList.contains("rigging-design-tab")) {
      setRightTab("rigging");
    }
  }
  newlyCompletedProjects.add(pid);
  const proj = allProjects.find((p) => p.id === pid);
  if (proj) proj.has_rig = true;
  renderProjectList();
  notifyAgentFinish({ kind: "rigging", pid, gen });
  markGenerationApplied(pid, gen.trace_id);
  try { syncCadArticulationToggle(); } catch (_) { /* gizmo optional */ }
  const qc = gen?.qc || lastRigQcResult;
  if (pid === projectId) {
    void (async () => {
      const result = qc?.token === RIGQC1_TOKEN
        ? qc
        : await runRigQc({ filename: selectedFile || gen?.target_filename || "", prompt: gen?.prompt || "make the wheels drive", play: false });
      if (result?.pass) {
        try { await playActiveModelRig(); } catch (_) { /* play after QC */ }
      }
    })();
  }
}

function isCadGenerationActive(pid = projectId) {
  if (!pid || !isGenerationUiActive(pid)) return false;
  if (generationWatchPid === pid) {
    if (generationWatchOverlay?.kind === "wiring") return false;
    if (generationWatchOverlay?.kind === "video" || isVideoGenerationKind(generationWatchOverlay)) return false;
    if (isRenderOverlayState(generationWatchOverlay)) return false;
    return true;
  }
  const gen = allProjects.find((p) => p.id === pid)?.generation;
  if (isRenderOverlayState(gen) || isRenderOverlayState({
    kind: gen?.kind,
    promptMode: gen?.prompt_mode || gen?.promptMode,
    mode: gen?.mode,
  })) {
    return false;
  }
  if (isVideoGenerationKind(gen) && !liveServerCadJobs(gen).length) return false;
  return String(gen?.kind || "").toLowerCase() !== "wiring";
}

function syncStopButtonVisibility() {
  const btn = document.getElementById("btn-stop-generation");
  const promptBtn = document.getElementById("btn-prompt");
  const canvasStopBtn = document.getElementById("btn-canvas-stop-generation");
  const wiringBtn = document.getElementById("btn-wiring-stop");
  const wiringToolbeltBtn = document.getElementById("btn-wiring-toolbelt-stop");
  const watchMatchesProject = generationWatchPid === projectId;
  const wiringGenerating = watchMatchesProject && generationWatchOverlay?.kind === "wiring";
  const renderGenerating = viewportOverlayPid === projectId && isRenderOverlayState(viewportOverlayState);
  const cadGenerating = watchMatchesProject
    ? (generationWatchOverlay?.kind !== "wiring"
      && generationWatchOverlay?.kind !== "video"
      && !isVideoGenerationKind(generationWatchOverlay)
      && !isRenderOverlayState(generationWatchOverlay))
    : isCadGenerationActive(projectId);
  const runningCount = cadGenerating ? activeCadGenerationCount(projectId) : (renderGenerating ? 1 : 0);
  const meshGenerating = cadGenerating && ["mesh", "fusion"].includes(
    String(generationWatchOverlay?.promptMode || generationPromptMode(allProjects.find((p) => p.id === projectId)?.generation) || promptMode || "").toLowerCase(),
  );
  const showStop = cadGenerating || renderGenerating;
  if (btn) {
    btn.classList.toggle("hidden", !showStop);
    if (!showStop) btn.disabled = false;
    btn.textContent = runningCount > 1 ? `Stop ${runningCount} generations` : "Stop generating";
    btn.setAttribute("aria-label", runningCount > 1 ? `Stop ${runningCount} running generations` : "Stop generating");
  }
  if (canvasStopBtn) {
    canvasStopBtn.classList.toggle("hidden", !showStop);
    canvasStopBtn.textContent = runningCount > 1 ? `Stop ${runningCount}` : "Stop generating";
  }
  // Keep Generate available while jobs run (including Mesh) so users can queue another part.
  if (promptBtn) {
    promptBtn.classList.remove("hidden");
    promptBtn.textContent = promptGenerateButtonLabel(promptMode, runningCount);
    if (!cadGenerating || !promptSubmitInFlight) promptBtn.removeAttribute("disabled");
  }
  if (wiringBtn) wiringBtn.classList.toggle("hidden", !wiringGenerating);
  if (wiringToolbeltBtn) wiringToolbeltBtn.classList.toggle("hidden", !wiringGenerating);
  const wiringGenBtn = document.getElementById("btn-wiring-prompt");
  const wiringToolbeltGenBtn = document.getElementById("btn-wiring-toolbelt-generate");
  if (wiringGenBtn) {
    wiringGenBtn.classList.toggle("hidden", wiringGenerating);
    if (!wiringGenerating) wiringGenBtn.removeAttribute("disabled");
  }
  if (wiringToolbeltGenBtn) {
    wiringToolbeltGenBtn.classList.toggle("hidden", wiringGenerating);
    if (!wiringGenerating) wiringToolbeltGenBtn.removeAttribute("disabled");
  }
  viewerOverlay.setStopVisible?.(showStop ? Math.max(runningCount, 1) : 0);
  wiringOverlay?.setStopVisible?.(wiringGenerating);
  syncCanvasGenerationUi();
  syncXrAiGeneratingIndicator();
}

/** Green AI VR dock icon + panel header while generating in headset. */
function syncXrAiGeneratingIndicator() {
  try {
    if (!viewportXR?.setAiGenerating) return;
    if (!viewportXR.isPresenting?.()) {
      viewportXR.setAiGenerating(false);
      return;
    }
    const liveGen = projectId ? allProjects.find((p) => p.id === projectId)?.generation : null;
    const runningJobs = generationRunningJobs(liveGen, generationWatchOverlay);
    const generating = !!(
      (projectId && isGenerationUiActive(projectId) && isCadGenerationActive(projectId))
      || (generationWatchPid === projectId && generationWatchOverlay)
      || promptSubmitInFlight
      || runningJobs.length
    );
    const focused = runningJobs.find((j) => j.trace_id === generationWatchOverlay?.focusedJobId)
      || runningJobs[0]
      || liveGen;
    const who = focused?.by_user_name
      || liveGen?.by_user_name
      || currentUser?.display_name
      || "Someone";
    const count = Math.max(runningJobs.length, generating ? 1 : 0);
    const msg = generating
      ? (count > 1
        ? `${count} generating · ${who} + others`
        : `${who} is generating…`)
      : "";
    viewportXR.setAiGenerating(generating, msg);
    if (generating) {
      try { viewportXR.refreshAiPromptPanel?.(); } catch (_) { }
    }
  } catch (err) {
    console.warn("[xr] ai generating indicator", err);
  }
}

function xrGenerationJobsForPanel() {
  try {
    const liveGen = projectId ? allProjects.find((p) => p.id === projectId)?.generation : null;
    const runningJobs = generationRunningJobs(liveGen, generationWatchOverlay);
    const fallbackName = liveGen?.by_user_name || currentUser?.display_name || "Someone";
    const fallbackAvatar = liveGen?.by_avatar_url || currentUser?.avatar_url || "";
    if (runningJobs.length) {
      return runningJobs.map((j, i) => ({
        id: String(j.trace_id || j.id || `job-${i}`),
        name: j.by_user_name || fallbackName,
        avatarUrl: j.by_avatar_url || fallbackAvatar,
        prompt: String(j.prompt || j.label || liveGen?.prompt || "Generation").slice(0, 96),
        pct: Number(j.progress?.pct ?? liveGen?.progress?.pct ?? 0) || 0,
        label: String(j.progress?.label || liveGen?.progress?.label || "Generating…").slice(0, 72),
        mode: String(j.mode || liveGen?.mode || generationWatchOverlay?.promptMode || "").toLowerCase(),
        source: (
          String(j.client || j.request_body?.client || "").toLowerCase() === "xr"
          || String(j.client || j.request_body?.client || "").toLowerCase() === "vr"
          || String(j.client || j.source || "").toLowerCase().includes("xr")
        ) ? "VR" : "PC",
      }));
    }
    if (liveGen?.status === "running" || (generationWatchPid === projectId && generationWatchOverlay)) {
      return [{
        id: String(liveGen?.trace_id || "active"),
        name: fallbackName,
        avatarUrl: fallbackAvatar,
        prompt: String(liveGen?.prompt || generationWatchOverlay?.prompt || "Generation").slice(0, 96),
        pct: Number(liveGen?.progress?.pct ?? generationWatchOverlay?.progress?.pct ?? 0) || 0,
        label: String(
          liveGen?.progress?.label
          || generationWatchOverlay?.message
          || "Generating…",
        ).slice(0, 72),
        mode: String(liveGen?.mode || generationWatchOverlay?.promptMode || "").toLowerCase(),
        source: isVrGenerationClient(liveGen) || promptSubmitOpts?.source === "xr" ? "VR" : "PC",
      }];
    }
  } catch (err) {
    console.warn("[xr] generation jobs", err);
  }
  return [];
}

let promptSubmitInFlight = false;
/** @type {{ source?: "ui" | "xr" }} */
let promptSubmitOpts = { source: "ui" };
let wiringPromptSubmitInFlight = false;
let promptClickInFlight = false;

function stopGenerationWatch(targetPid = generationWatchPid) {
  // Full reset (rare): stop every project poll.
  if (targetPid == null) {
    for (const pid of [...generationPollTimers.keys()]) clearGenerationPoll(pid);
    generationWatchPid = null;
    generationWatchOverlay = null;
    promptSubmitInFlight = false;
    wiringPromptSubmitInFlight = false;
    promptClickInFlight = false;
    syncViewportGenerationOverlay({ complete: true });
    try { disposeLiveGenerationPreview(); } catch (_) { }
    document.getElementById("btn-prompt")?.removeAttribute("disabled");
    document.getElementById("btn-wiring-prompt")?.removeAttribute("disabled");
    document.getElementById("btn-wiring-toolbelt-generate")?.removeAttribute("disabled");
    syncStopButtonVisibility();
    return;
  }
  clearGenerationPoll(targetPid);
  // Generation no longer owns project-tree loading; clear in case an older
  // session left the Browser stuck on "Loading project…".
  setProjectLoading(targetPid, false);
  clearCanvasGenerationPending(targetPid);
  const wasFocused = generationWatchPid === targetPid;
  if (wasFocused) {
    generationWatchPid = null;
    generationWatchOverlay = null;
    promptSubmitInFlight = false;
    wiringPromptSubmitInFlight = false;
    promptClickInFlight = false;
    // Prefer the open project's still-running poll as the new focus.
    if (projectId && projectId !== targetPid && hasGenerationPoll(projectId)) {
      generationWatchPid = projectId;
    }
    syncViewportGenerationOverlay({ complete: true });
    if (targetPid === projectId) {
      try { disposeLiveGenerationPreview(); } catch (_) { }
    }
    document.getElementById("btn-prompt")?.removeAttribute("disabled");
    document.getElementById("btn-wiring-prompt")?.removeAttribute("disabled");
    document.getElementById("btn-wiring-toolbelt-generate")?.removeAttribute("disabled");
    syncStopButtonVisibility();
    if (targetPid === projectId) clearPendingPromptTimelineStep();
  } else {
    syncStopButtonVisibility();
    renderProjectList();
  }
}

async function cancelActiveGeneration(opts = {}) {
  // Only cancel the open project (or an explicit pid). Never fall back to a
  // background generationWatchPid on another project — that stopped gens when
  // switching projects / when Stop fired while the watch pointed elsewhere.
  const pid = opts.projectId || opts.pid || projectId;
  if (!pid || !isGenerationUiActive(pid)) return;

  if (
    viewportOverlayPid === pid
    && viewportOverlayState?.kind === "scene_render"
    && generationWatchPid !== pid
  ) {
    userCancelRequested = true;
    activePromptGenerationId++;
    const renderPrompt = String(viewportOverlayState?.prompt || "").trim();
    const renderTraceId = allProjects.find((p) => p.id === pid)?.generation?.trace_id || null;
    const renderBase = selectedFile || null;
    const renderSpeed = document.getElementById("prompt-speed")?.value === "quality" ? "quality" : "fast";
    activePromptAbort?.abort();
    activePromptAbort = null;
    const statusEl = document.getElementById("prompt-status");
    if (statusEl && pid === projectId) {
      statusEl.className = "status";
      statusEl.textContent = "Stopping render…";
    }
    hideViewportOverlay(pid);
    syncStopButtonVisibility();
    const stoppedEntry = await recordStoppedRenderHistory(pid, {
      prompt: renderPrompt || "Render",
      traceId: renderTraceId,
      baseFilename: renderBase,
      speed: renderSpeed,
    });
    if (statusEl && pid === projectId) {
      statusEl.textContent = stoppedStatusMessage(stoppedEntry, "Render stopped.");
    }
    return;
  }

  let gen = allProjects.find((p) => p.id === pid)?.generation;
  try {
    gen = await api(`/api/projects/${pid}/generation`);
    const proj = allProjects.find((p) => p.id === pid);
    if (proj) proj.generation = gen;
  } catch (_) {
    /* use cached */
  }
  const runningJobs = generationRunningJobs(gen, generationWatchOverlay);
  let traceId = opts.traceId || opts.trace_id || null;
  if (!traceId && runningJobs.length > 1) {
    const picked = await openGenerationCancelPicker(runningJobs, {
      focusedJobId: opts.focusedJobId || null,
    });
    if (!picked) return;
    traceId = picked === "__all__" ? null : picked;
  } else if (!traceId && runningJobs.length === 1) {
    traceId = runningJobs[0].trace_id || runningJobs[0].id || null;
  }

  userCancelRequested = true;
  if (!traceId || runningJobs.length <= 1) {
    activePromptGenerationId++;
    activePromptAbort?.abort();
    activePromptAbort = null;
  }

  const btn = document.getElementById("btn-stop-generation");
  const wiringBtn = document.getElementById("btn-wiring-stop");
  const wiringToolbeltBtn = document.getElementById("btn-wiring-toolbelt-stop");
  if (btn) btn.disabled = true;
  if (wiringBtn) wiringBtn.disabled = true;
  if (wiringToolbeltBtn) wiringToolbeltBtn.disabled = true;
  try {
    await api(`/api/projects/${pid}/generation/cancel`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(traceId ? { trace_id: traceId } : {}),
    });
    if (pid === projectId) {
      const isWiring = generationWatchOverlay?.kind === "wiring";
      const stopMode = (generationWatchOverlay?.promptMode || "").toLowerCase();
      const isV2 = stopMode === "v2";
      const isMesh = stopMode === "mesh" || stopMode === "fusion";
      const statusEl = document.getElementById(isWiring ? "wiring-prompt-status" : "prompt-status");
      if (statusEl) {
        statusEl.className = "status";
        statusEl.textContent = isWiring
          ? "Stopping… killing generation now"
          : isMesh
            ? "Stopping Mesh mode… killing generation now"
            : isV2
              ? "Stopping CAD… killing generation now"
              : runningJobs.length > 1 && traceId
                ? "Stopping selected generation…"
                : "Stopping… killing generation now";
      }
    }
    let nextGen;
    try {
      nextGen = await api(`/api/projects/${pid}/generation`);
      const proj = allProjects.find((p) => p.id === pid);
      if (proj) proj.generation = nextGen;
    } catch (_) {
      /* best-effort status check */
    }
    const stillRunning = generationRunningJobs(nextGen).length > 0 || nextGen?.status === "running";
    if (stillRunning) {
      if (!hasGenerationPoll(pid)) {
        beginGenerationWatch(pid, {
          kind: nextGen?.kind || "prompt",
          mode: generationPromptMode(nextGen, generationWatchOverlay?.promptMode || "standard"),
          model: nextGen?.model || generationWatchOverlay?.model,
          provider: nextGen?.provider || generationWatchOverlay?.provider,
        });
      } else {
        syncViewportGenerationOverlay();
        syncStopButtonVisibility();
      }
      userCancelRequested = false;
    } else {
      stopGenerationWatch(pid);
      hideViewportOverlay(pid);
      promptSubmitInFlight = false;
      document.getElementById("btn-prompt")?.removeAttribute("disabled");
      document.getElementById("btn-wiring-prompt")?.removeAttribute("disabled");
      document.getElementById("btn-wiring-toolbelt-generate")?.removeAttribute("disabled");
      userCancelRequested = false;
      if (nextGen?.status === "canceled" && pid === projectId) {
        const statusEl = document.getElementById(nextGen.kind === "wiring" ? "wiring-prompt-status" : "prompt-status");
        if (statusEl) {
          statusEl.className = "status";
        }
        await refreshTimeline();
        if (nextGen.kind === "wiring") {
          await refreshWiringPromptHistory();
          await refreshPromptHistory();
        } else if (nextGen.kind === "rigging") await refreshRiggingPromptHistory();
        else await refreshPromptHistory();
        if (statusEl) {
          const stoppedEntry = latestPromptHistoryEntries.find(
            (e) => e.status === "stopped" && (!traceId || e.trace_id === traceId),
          ) || latestPromptHistoryEntries.find((e) => e.status === "stopped");
          const jobUsageLabel = formatUsageStopLabel(nextGen);
          const historyLabel = formatUsageStopLabel(stoppedEntry);
          const usageLabel = historyLabel || jobUsageLabel;
          const fallback = nextGen.error || "Generation canceled.";
          statusEl.textContent = usageLabel
            ? `${fallback.replace(/\.$/, "")}. Used ${usageLabel} before stopping.`
            : fallback;
        }
        // Mesh + 2.0: put the prompt back in the compose draft so Stop → edit → retry works.
        if (nextGen.kind !== "wiring" && nextGen.kind !== "rigging") {
          const draftPrompt = promptTextForStoppedGeneration(
            nextGen,
            latestPromptHistoryEntries.find(
              (e) => e.status === "stopped" && (!traceId || e.trace_id === traceId),
            )?.prompt,
          );
          restoreComposeDraftAfterStop({
            prompt: draftPrompt,
            promptMode: nextGen.mode || nextGen.prompt_mode || generationWatchOverlay?.promptMode,
          });
          // Costs can land a beat after cancel — refresh once more like 2.0.
          schedulePromptHistoryFollowupRefresh(pid, 1800);
        }
      }
    }
  } catch (err) {
    const statusEl = document.getElementById(generationWatchOverlay?.kind === "wiring" ? "wiring-prompt-status" : "prompt-status");
    if (statusEl && pid === projectId) {
      statusEl.className = "status error";
      statusEl.textContent = formatUserError(err);
    }
  } finally {
    if (btn) btn.disabled = false;
    if (wiringBtn) wiringBtn.disabled = false;
    if (wiringToolbeltBtn) wiringToolbeltBtn.disabled = false;
    syncStopButtonVisibility();
  }
}

function openGenerationCancelPicker(jobs, { focusedJobId = null } = {}) {
  return new Promise((resolve) => {
    const existing = document.getElementById("generation-cancel-modal");
    existing?.remove();
    const modal = document.createElement("div");
    modal.id = "generation-cancel-modal";
    modal.className = "auth-modal generation-cancel-modal";
    modal.setAttribute("role", "dialog");
    modal.setAttribute("aria-modal", "true");
    modal.setAttribute("aria-labelledby", "generation-cancel-title");
    const rows = (jobs || []).map((job, index) => {
      const id = String(job.trace_id || job.id || "");
      const pct = Math.round(Math.max(0, Math.min(100, Number(job.progress?.pct) || 0)));
      const prompt = String(job.prompt || job.label || `Generation ${index + 1}`).trim();
      const step = String(job.progress?.label || job.progress?.thinking || "Working…");
      const mode = generationPromptMode(job);
      const selected = focusedJobId && id === focusedJobId;
      return `
        <div class="generation-cancel-row${selected ? " is-focused" : ""}" data-trace-id="${appEscapeHtml(id)}">
          <button type="button" class="generation-cancel-expand" aria-expanded="false" data-expand="${appEscapeHtml(id)}">Details</button>
          <div class="generation-cancel-main">
            <div class="generation-cancel-prompt">${appEscapeHtml(prompt.slice(0, 160))}${prompt.length > 160 ? "…" : ""}</div>
            <div class="generation-cancel-meta">
              <span>${pct}%</span>
              <span>${appEscapeHtml(mode)}</span>
              <span>${appEscapeHtml(String(step).slice(0, 80))}</span>
            </div>
            <div class="generation-cancel-track"><span style="width:${pct}%"></span></div>
            <div class="generation-cancel-details hidden" hidden>
              <p><strong>Prompt</strong></p>
              <pre>${appEscapeHtml(prompt)}</pre>
              <p><strong>Current step</strong> ${appEscapeHtml(String(step))}</p>
              ${job.progress?.thinking ? `<p><strong>Detail</strong> ${appEscapeHtml(String(job.progress.thinking))}</p>` : ""}
              ${id ? `<p class="muted small">trace:${appEscapeHtml(id)}</p>` : ""}
            </div>
          </div>
          <button type="button" class="btn danger generation-cancel-one" data-stop="${appEscapeHtml(id)}">Stop this</button>
        </div>
      `;
    }).join("");
    modal.innerHTML = `
      <div class="auth-backdrop" data-cancel-close="1"></div>
      <div class="auth-card generation-cancel-card">
        <button type="button" class="auth-close" data-cancel-close="1" aria-label="Close">&times;</button>
        <h2 id="generation-cancel-title">Stop which generation?</h2>
        <p class="muted small">Expand a row to confirm which prompt you are stopping. Other generations keep running.</p>
        <div class="generation-cancel-list">${rows}</div>
        <div class="generation-cancel-actions">
          <button type="button" class="btn secondary" data-cancel-close="1">Keep generating</button>
          <button type="button" class="btn danger" data-stop-all="1">Stop all</button>
        </div>
      </div>
    `;
    const finish = (value) => {
      modal.remove();
      document.removeEventListener("keydown", onKey);
      resolve(value);
    };
    const onKey = (e) => {
      if (e.key === "Escape") finish(null);
    };
    document.addEventListener("keydown", onKey);
    modal.addEventListener("click", (e) => {
      if (e.target.closest?.("[data-cancel-close]")) {
        finish(null);
        return;
      }
      if (e.target.closest?.("[data-stop-all]")) {
        finish("__all__");
        return;
      }
      const stopBtn = e.target.closest?.("[data-stop]");
      if (stopBtn) {
        finish(stopBtn.getAttribute("data-stop") || null);
        return;
      }
      const expandBtn = e.target.closest?.("[data-expand]");
      if (expandBtn) {
        const row = expandBtn.closest(".generation-cancel-row");
        const details = row?.querySelector(".generation-cancel-details");
        if (!details) return;
        const open = details.classList.contains("hidden");
        details.classList.toggle("hidden", !open);
        details.hidden = !open;
        expandBtn.setAttribute("aria-expanded", open ? "true" : "false");
        expandBtn.textContent = open ? "Hide" : "Details";
        row?.classList.toggle("is-expanded", open);
      }
    });
    document.body.appendChild(modal);
  });
}

function promptGenerationOverlayOpts(mode = "standard") {
  const normalized = (mode || "standard").toLowerCase();
  if (normalized === "build" || normalized === "kernel" || normalized === "ribbon") {
    return {
      message: "Building solid with CAD kernel…",
      mode: "build",
      estimateMs: 45000,
    };
  }
  if (normalized === "rigging") {
    return {
      message: "Authoring and generating robot artifacts… (safe to refresh)",
      mode: "rigging",
      estimateMs: 180000,
    };
  }
  if (normalized === "mesh" || normalized === "mesh_beta" || normalized === "mesh-beta" || normalized === "fusion") {
    return {
      message: "Mesh · parts draw in the viewport as they export… (safe to refresh)",
      mode: "ai",
      promptMode: "mesh",
      harness: "mesh",
      wand: "img2threejs",
      estimateMs: 600000,
    };
  }
  if (normalized === "vibecad" || normalized === "vibe" || normalized === "vibecade") {
    return {
      message: "VibeCAD · parts draw in the viewport as they tessellate… (safe to refresh)",
      mode: "ai",
      promptMode: "vibecad",
      harness: "vibecad",
      estimateMs: 900000,
    };
  }
  if (normalized === "mac" || normalized === "macad" || normalized === "multi_agent_cad") {
    return {
      message: "MAC · parts draw in the viewport as they’re published… (safe to refresh)",
      mode: "ai",
      promptMode: "mac",
      harness: "mac",
      estimateMs: 900000,
    };
  }
  if (normalized === "v2" || normalized === "jake" || normalized === "cad") {
    return {
      message: "Jake · parts draw in the viewport as they’re built… (safe to refresh)",
      mode: "ai",
      promptMode: "v2",
      harness: "jake",
      estimateMs: 900000,
    };
  }
  if (normalized === "render") {
    return {
      message: "Rendering photoreal scene…",
      mode: "render",
      promptMode: "render",
      estimateMs: 240000,
    };
  }
  return {
    message: "Generating in background… (safe to refresh)",
    mode: "ai",
    estimateMs: 360000,
  };
}

function generationPromptMode(generation = {}, fallback = "standard") {
  if (String(generation?.kind || "").toLowerCase() === "rigging") return "rigging";
  const explicitRaw =
    generation?.mode ||
    generation?.prompt_mode ||
    generation?.promptMode ||
    generation?.request_body?.mode ||
    generation?.request_body?.prompt_mode;
  const text = String(explicitRaw || "").toLowerCase();
  if (text === "mesh_beta" || text === "mesh-beta") return "mesh_beta";
  if (text === "mesh" || text === "img2threejs" || text === "threejs") return "mesh";
  if (text === "fusion" || text === "fusion360" || text === "fusion-360") return "mesh";
  if (text === "architect" || text === "architecture") return "architect";
  if (text === "vibecad" || text === "vibe" || text === "vibecade") return "vibecad";
  if (text === "mac" || text === "macad" || text === "multi_agent_cad" || text === "multiagentcad") return "mac";
  if (text === "v2" || text === "2.0" || text === "2" || text === "cad" || text === "jake") return "v2";
  if (text === "render") return "render";
  if (text === "draw") return "draw";
  if (text === "rigging" || text === "rig") return "rigging";
  const searchable = String([
    generation?.message,
    generation?.label,
    generation?.prompt,
    generation?.progress?.label,
  ].filter(Boolean).join(" "));
  if (searchable.match(/\bmesh[_-]?beta\b/i)) return "mesh_beta";
  if (searchable.match(/\bmesh\b|img2threejs|three\.?js/i)) return "mesh";
  if (searchable.match(/\bfusion\b/i)) return "mesh";
  if (searchable.match(/\bvibecad\b/i)) return "vibecad";
  if (searchable.match(/\barchitect(?:ure)?\b/i)) return "architect";
  if (searchable.match(/\b(v2|2\.0)\b/i)) return "v2";
  const fallbackText = String(fallback || "standard").toLowerCase();
  if (fallbackText === "mesh_beta" || fallbackText === "mesh-beta") return "mesh_beta";
  if (fallbackText === "mesh" || fallbackText === "img2threejs") return "mesh";
  if (fallbackText === "fusion" || fallbackText === "fusion360" || fallbackText === "fusion-360") return "mesh";
  if (fallbackText === "vibecad" || fallbackText === "vibe" || fallbackText === "vibecade") return "vibecad";
  if (fallbackText === "architect" || fallbackText === "architecture") return "architect";
  if (fallbackText === "v2" || fallbackText === "2.0" || fallbackText === "2" || fallbackText === "cad" || fallbackText === "jake") return "v2";
  if (fallbackText === "render") return "render";
  if (fallbackText === "rigging" || fallbackText === "rig") return "rigging";
  return fallbackText === "draw" ? "draw" : "standard";
}

function applyPromptModeUI(mode = promptMode) {
  promptMode = mode === "draw" ? DEFAULT_PROMPT_MODE : (mode || DEFAULT_PROMPT_MODE);
  if (promptMode === "fusion") {
    // Fusion prompt tab removed — map legacy sessions to Mesh.
    promptMode = "mesh";
  }
  // VibeCAD / MAC are engines under 2.0 — keep the 2.0 tab selected in the UI.
  if (promptMode === "vibecad" || promptMode === "vibe" || promptMode === "vibecade") {
    setPromptCadEngine("vibecad");
    promptMode = "v2";
  }
  if (promptMode === "mac" || promptMode === "macad" || promptMode === "multi_agent_cad") {
    setPromptCadEngine("mac");
    promptMode = "v2";
  }
  // mesh_beta is an engine under Mesh — keep the Mesh tab selected in the UI.
  if (promptMode === "mesh_beta" || promptMode === "mesh-beta") {
    setPromptMeshEngine("beta");
    promptMode = "mesh";
  }
  const modeBtn = document.querySelector(`[data-prompt-mode="${promptMode}"]`);
  if (!modeBtn || modeBtn.disabled) {
    promptMode = DEFAULT_PROMPT_MODE;
  }
  document.querySelectorAll("[data-prompt-mode]").forEach((b) => {
    const isMode = (b.dataset.promptMode || DEFAULT_PROMPT_MODE) === promptMode;
    b.classList.toggle("active", isMode && !cadComposeRigging);
  });
  if (promptMode !== "render") xrEnvWrapArmed = false;
  const promptBtn = document.getElementById("btn-prompt");
  if (promptBtn) {
    promptBtn.textContent = promptGenerateButtonLabel(promptMode);
  }
  const input = document.getElementById("prompt-input");
  if (input) {
    const engine = getPromptCadEngine();
    const meshEngine = getPromptMeshEngine();
    const placeholder = promptMode === "render"
      ? "Describe the scene around this viewport model — any language. Keep its facing — example: oak kitchen counter, morning window light, materials on the object only…"
      : promptMode === "mesh" && meshEngine === "beta"
        ? "Describe a character, vehicle, or prop in any language for img2threejs 2.0.0 + character plugin — named pivots + clips that play…"
        : promptMode === "mesh"
          ? "Attach a reference image or describe an object in any language to rebuild as a procedural Three.js mesh…"
          : promptMode === "v2" && engine === "vibecad"
            ? "Describe a part for VibeCAD (build123d) in any language — principal mechanical design, named solids…"
            : promptMode === "v2" && engine === "mac"
              ? "Describe a printable part for MAC (Multi-Agent CAD) in any language — features, clearances, mm dimensions…"
              : "Describe what to make or edit in any language. Type @ to link uploaded files…";
    input.placeholder = placeholder;
    if (composer?.editor) composer.editor.dataset.placeholder = placeholder;
  }
  if (typeof syncCadComposeRiggingUi === "function") syncCadComposeRiggingUi();
  if (promptMode === "architect") {
    setSkillEnabled("cad", true);
    setSkillEnabled("architect", true);
    skillsPromptUI?.render?.();
    skillsPromptUI?.updatePlan?.();
  }
  syncCodexToggleVisibility(promptMode);
  syncElectronicsToggleVisibility(promptMode);
  syncMcMasterPartsToggleVisibility(promptMode);
  syncJakeSpendVisibility(promptMode);
  syncSpiceTipForPromptMode(promptMode);
  syncCadDebugToggleVisibility(promptMode);
  if (promptMode === "v2") {
    syncPromptCadEngineChip();
    syncAgentDefaultsForSelectedKey(promptMode);
  } else {
    setPromptCadEngineOpen(false);
  }
  if (promptMode === "mesh") {
    syncPromptMeshEngineChip();
  } else {
    setPromptMeshEngineOpen(false);
  }
  const dropTitle = document.getElementById("prompt-image-drop-title");
  const dropHint = document.getElementById("prompt-image-drop-hint");
  if (dropTitle && dropHint) {
    if (promptMode === "mesh") {
      dropTitle.textContent = "Add reference image, notes (.txt), or docs";
      dropHint.innerHTML =
        "Drop a photo of the object (and optional text notes). Mesh uses the image for img2threejs — "
        + "<strong>no DXF convert prompt</strong>. Same attach flow as CAD.";
    } else {
      dropTitle.textContent = "Add image, CAD, DXF, or document references";
      dropHint.innerHTML =
        "Drop files here for this prompt — or open <strong>Project browser → Reference Files</strong> (left) "
        + "to store images permanently, mark them up, and Send to AI.";
    }
  }
}

function selectedPromptSupportsElectronics(mode = promptMode) {
  // Electronics solids apply to every Mode 2.0 CAD harness (Jake / VibeCAD / MAC / Architect).
  const m = String(mode || "").toLowerCase();
  if (m === "mac" || m === "macad" || m === "multi_agent_cad") return true;
  if (m === "vibecad" || m === "vibe" || m === "vibecade") return true;
  if (m === "v2" || m === "architect" || m === "fusion") return true;
  return isCadHarnessMode(m);
}

function isModelElectronicsEnabled() {
  return Boolean(document.getElementById("prompt-electronics")?.checked);
}

function setModelElectronicsEnabled(enabled, { persist = true } = {}) {
  const btn = document.getElementById("prompt-electronics");
  const on = Boolean(enabled);
  if (btn) {
    btn.checked = on;
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("active", on);
    btn.title = on
      ? "Model electronics solids — on (hover for details)"
      : "Model electronics solids — off (hover for details)";
  }
  if (persist) {
    try {
      localStorage.setItem(ELECTRONICS_KEY, on ? "1" : "0");
    } catch {
      /* ignore */
    }
  }
}

function syncElectronicsToggleVisibility(mode = promptMode) {
  syncMcMasterPartsToggleVisibility(mode);
}

function selectedPromptSupportsMcMasterParts(mode = promptMode) {
  const m = String(mode || "").toLowerCase();
  return m === "v2" || isCadHarnessMode(m);
}

const DEFAULT_MCMASTER_PARTS_ENABLED = true;

function mcmasterPartsPrefStorageKey(pid = projectId) {
  return pid ? `${MCMASTER_PARTS_KEY}:${pid}` : null;
}

function readLegacyMcMasterPartsEnabled() {
  try {
    const saved = localStorage.getItem(MCMASTER_PARTS_KEY);
    if (saved === "0") return false;
    if (saved === "1") return true;
  } catch {
    /* local storage is best-effort */
  }
  return DEFAULT_MCMASTER_PARTS_ENABLED;
}

function readProjectMcMasterPartsEnabled(pid = projectId) {
  const key = mcmasterPartsPrefStorageKey(pid);
  if (!key) return DEFAULT_MCMASTER_PARTS_ENABLED;
  try {
    const raw = localStorage.getItem(key);
    if (raw === "1") return true;
    if (raw === "0") return false;
  } catch {
    /* local storage is best-effort */
  }
  return readLegacyMcMasterPartsEnabled();
}

function persistProjectMcMasterPartsEnabled(enabled, pid = projectId) {
  if (!pid || newProjectPending) return;
  const key = mcmasterPartsPrefStorageKey(pid);
  if (!key) return;
  try {
    localStorage.setItem(key, enabled ? "1" : "0");
  } catch {
    /* local storage is best-effort */
  }
}

function applyProjectMcMasterPartsPreference(pid = projectId) {
  setMcMasterPartsEnabled(readProjectMcMasterPartsEnabled(pid), { persist: false });
}

function isMcMasterPartsEnabled() {
  const btn = document.getElementById("prompt-mcmaster-parts");
  if (btn) return btn.getAttribute("aria-pressed") === "true";
  return projectId ? readProjectMcMasterPartsEnabled(projectId) : DEFAULT_MCMASTER_PARTS_ENABLED;
}

function setMcMasterPartsEnabled(enabled, { persist = true } = {}) {
  const btn = document.getElementById("prompt-mcmaster-parts");
  const on = Boolean(enabled);
  if (btn) {
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("active", on);
    btn.title = on
      ? "Parts & Electronics — on (McMaster + electronics CAD)"
      : "Parts & Electronics — off (hover for details)";
  }
  const elec = document.getElementById("prompt-electronics");
  if (elec) {
    elec.checked = on;
    elec.setAttribute("aria-pressed", on ? "true" : "false");
  }
  if (persist) {
    persistProjectMcMasterPartsEnabled(on);
    try {
      localStorage.setItem(ELECTRONICS_KEY, on ? "1" : "0");
    } catch {
      /* ignore */
    }
  }
}

function syncMcMasterPartsToggleVisibility(mode = promptMode) {
  const wrap = document.getElementById("prompt-mcmaster-parts-wrap");
  if (!wrap) return;
  const show = selectedPromptSupportsMcMasterParts(mode) || selectedPromptSupportsElectronics(mode);
  wrap.classList.toggle("hidden", !show);
  if (show) wrap.removeAttribute("hidden");
  else wrap.setAttribute("hidden", "");
}

function getCadMcMasterPartsBodyFields(mode = promptMode) {
  const cad = selectedPromptSupportsMcMasterParts(mode);
  return { use_mcmaster_parts: cad && isMcMasterPartsEnabled() };
}

function selectedPromptShowsSpendCaps(mode = promptMode) {
  const m = String(mode || "").toLowerCase();
  return (
    m === "v2" ||
    m === "architect" ||
    m === "vibecad" ||
    m === "vibe" ||
    m === "vibecade" ||
    m === "mac" ||
    m === "macad" ||
    m === "multi_agent_cad" ||
    m === "multiagentcad"
  );
}

function syncJakeSpendVisibility(mode = promptMode) {
  const wrap = document.getElementById("prompt-jake-spend");
  if (!wrap) return;
  wrap.hidden = !selectedPromptShowsSpendCaps(mode);
}

function parseOptionalPositiveNumber(value) {
  const text = String(value ?? "").trim();
  if (!text) return null;
  const n = Number(text);
  return Number.isFinite(n) && n > 0 ? n : null;
}

/** $5 ≈ 8 agent loops for Mode 2.0 / VibeCAD / MAC. */
const SESSION_LOOPS_PER_USD = 8 / 5;

function loopsFromBudgetUsd(usd) {
  if (usd == null || !Number.isFinite(usd) || usd <= 0) return null;
  return Math.max(1, Math.round(usd * SESSION_LOOPS_PER_USD));
}

function syncSessionLoopsFromBudget() {
  const budgetEl = document.getElementById("prompt-jake-budget");
  const budget = parseOptionalPositiveNumber(budgetEl?.value);
  const loops = loopsFromBudgetUsd(budget);
  const chip = document.getElementById("prompt-session-loops");
  const tip = document.getElementById("prompt-session-loops-tip");
  if (chip) chip.textContent = loops == null ? "∞ loops" : `${loops} loop${loops === 1 ? "" : "s"}`;
  if (tip) tip.textContent = loops == null ? "∞" : String(loops);
  if (budgetEl) {
    const text = String(budgetEl.value || budgetEl.placeholder || "∞").trim() || "∞";
    budgetEl.style.width = `${Math.max(1.5, Math.min(5.5, text.length + 0.35))}ch`;
  }
}

function getJakeSpendBodyFields() {
  if (!selectedPromptShowsSpendCaps()) return {};
  const budget = parseOptionalPositiveNumber(document.getElementById("prompt-jake-budget")?.value);
  const fields = {};
  if (budget != null) {
    fields.budget_usd = budget;
    const loops = loopsFromBudgetUsd(budget);
    if (loops != null) fields.max_turns = loops;
  } else {
    fields.max_turns = 0;
  }
  return fields;
}

function initJakeSpendCaps() {
  const budgetEl = document.getElementById("prompt-jake-budget");
  try {
    const savedBudget = localStorage.getItem(JAKE_BUDGET_KEY);
    if (budgetEl && savedBudget != null) budgetEl.value = savedBudget;
  } catch {
    /* ignore */
  }
  const persist = () => {
    try {
      if (budgetEl) localStorage.setItem(JAKE_BUDGET_KEY, String(budgetEl.value || "").trim());
    } catch {
      /* ignore */
    }
    syncSessionLoopsFromBudget();
  };
  budgetEl?.addEventListener("change", persist);
  budgetEl?.addEventListener("input", persist);
  bindFixedHoverTip(
    document.getElementById("prompt-jake-spend"),
    document.getElementById("prompt-jake-spend-tip"),
    { width: 300, preferBelow: true, hideDelay: 180 },
  );
  syncSessionLoopsFromBudget();
  syncJakeSpendVisibility();
}

function initPromptElectronicsToggle() {
  const btn = document.getElementById("prompt-electronics");
  if (!btn) return;
  let enabled = true;
  try {
    const saved = localStorage.getItem(ELECTRONICS_KEY);
    enabled = saved !== "0";
  } catch {
    enabled = true;
  }
  setModelElectronicsEnabled(enabled, { persist: false });
  btn.addEventListener("change", () => {
    setModelElectronicsEnabled(btn.checked);
  });
  syncElectronicsToggleVisibility(promptMode);
  initPromptElectronicsHoverTip();
}

function initPromptMcMasterPartsToggle() {
  const btn = document.getElementById("prompt-mcmaster-parts");
  if (!btn) return;
  const enabled = projectId ? readProjectMcMasterPartsEnabled(projectId) : DEFAULT_MCMASTER_PARTS_ENABLED;
  setMcMasterPartsEnabled(enabled, { persist: false });
  btn.addEventListener("click", () => {
    setMcMasterPartsEnabled(!isMcMasterPartsEnabled());
  });
  syncMcMasterPartsToggleVisibility(promptMode);
  bindFixedHoverTip(
    document.getElementById("prompt-mcmaster-parts-wrap"),
    document.getElementById("prompt-mcmaster-parts-tip"),
    { width: 300, preferBelow: true, hideDelay: 180 },
  );
}

function placeFixedHoverTip(tip, anchorEl, {
  width = 280,
  gap = 10,
  preferBelow = false,
} = {}) {
  if (!tip || !anchorEl) return;
  const rect = anchorEl.getBoundingClientRect();
  const tipWidth = Math.min(width, Math.max(220, Math.min(window.innerWidth - 16, width)));
  tip.style.width = `${tipWidth}px`;
  tip.style.bottom = "auto";
  tip.style.right = "auto";

  let left = rect.left + rect.width / 2 - tipWidth / 2;
  left = Math.max(8, Math.min(left, window.innerWidth - tipWidth - 8));
  tip.style.left = `${Math.round(left)}px`;

  const wasVisible = tip.classList.contains("is-visible");
  if (!wasVisible) tip.classList.add("prompt-spice-tip--measure");
  const estimatedHeight = tip.offsetHeight || 120;
  if (!wasVisible) tip.classList.remove("prompt-spice-tip--measure");

  const spaceAbove = rect.top;
  const spaceBelow = window.innerHeight - rect.bottom;
  const placeBelow = preferBelow
    || spaceAbove < estimatedHeight + gap + 8
    || (spaceBelow >= estimatedHeight + gap && spaceBelow > spaceAbove);

  if (placeBelow) {
    tip.classList.add("prompt-spice-tip--below");
    tip.style.top = `${Math.round(rect.bottom + gap)}px`;
  } else {
    tip.classList.remove("prompt-spice-tip--below");
    tip.style.top = `${Math.round(rect.top - gap)}px`;
  }

  // Point the caret toward the anchor button, not always the tip's left edge.
  const caretLeft = Math.max(14, Math.min(tipWidth - 14, rect.left + rect.width / 2 - left - 5));
  tip.style.setProperty("--tip-caret-left", `${Math.round(caretLeft)}px`);
}

function bindFixedHoverTip(wrap, tip, options = {}) {
  if (!wrap || !tip) return;
  tip.hidden = false;
  if (tip.parentElement !== document.body) {
    document.body.appendChild(tip);
  }

  let showTimer = 0;
  let hideTimer = 0;
  let open = false;
  const hideDelay = Number.isFinite(options.hideDelay) ? options.hideDelay : 60;

  const placeTip = () => placeFixedHoverTip(tip, wrap, options);

  const show = () => {
    if (wrap.classList.contains("hidden") || wrap.hidden) return;
    clearTimeout(hideTimer);
    hideTimer = 0;
    if (open) {
      placeTip();
      return;
    }
    clearTimeout(showTimer);
    showTimer = window.setTimeout(() => {
      open = true;
      tip.classList.add("is-visible");
      placeTip();
    }, 50);
  };

  const hide = () => {
    clearTimeout(showTimer);
    showTimer = 0;
    clearTimeout(hideTimer);
    hideTimer = window.setTimeout(() => {
      open = false;
      tip.classList.remove("is-visible");
    }, hideDelay);
  };

  const relatedInside = (event) => {
    const next = event.relatedTarget;
    return wrap.contains(next) || tip.contains(next);
  };

  wrap.addEventListener("pointerenter", show);
  wrap.addEventListener("pointerleave", hide);
  wrap.addEventListener("focusin", show);
  wrap.addEventListener("focusout", (event) => {
    if (!relatedInside(event)) hide();
  });
  tip.addEventListener("pointerenter", show);
  tip.addEventListener("pointerleave", hide);
  tip.addEventListener("focusin", show);
  tip.addEventListener("focusout", (event) => {
    if (!relatedInside(event)) hide();
  });
  window.addEventListener("scroll", () => {
    if (open) placeTip();
  }, true);
  window.addEventListener("resize", () => {
    if (open) placeTip();
  });
}

function initPromptModeHoverTips() {
  const tips = [
    { wrap: '[data-prompt-mode-tip="render"]', tip: "prompt-mode-render-tip" },
    { wrap: '[data-prompt-mode-tip="v2"]', tip: "prompt-mode-v2-tip" },
    { wrap: '[data-prompt-mode-tip="mesh"]', tip: "prompt-mode-mesh-tip" },
  ];
  for (const entry of tips) {
    bindFixedHoverTip(
      document.querySelector(entry.wrap),
      document.getElementById(entry.tip),
      { width: 280, preferBelow: true },
    );
  }
}

function initPromptElectronicsHoverTip() {
  /* Combined with Parts & Electronics; tip is bound in initPromptMcMasterPartsToggle. */
}

function preservePromptModeAfterAttach(modeBeforeAttach = promptMode) {
  const mode = String(modeBeforeAttach || DEFAULT_PROMPT_MODE).toLowerCase();
  if (!["render", "v2", "mesh", "fusion", "architect"].includes(mode)) return;
  if (promptMode !== mode || !document.querySelector(`[data-prompt-mode="${mode}"]`)?.classList.contains("active")) {
    applyPromptModeUI(mode);
  }
}

function beginGenerationWatch(pid = projectId, { kind = "prompt", mode = "standard", pendingStart = false, model, provider, source, client, targetMode, usedCanvas = false } = {}) {
  if (!pid) return;
  // Replace only this project's poll — leave sibling project generations running.
  clearGenerationPoll(pid);
  generationWatchPid = pid;
  const brand = {
    model: String(model ?? "").trim(),
    provider: String(provider ?? "").trim(),
    source: String(source ?? "").trim(),
  };
  const xrClient = String(client || "").toLowerCase() === "xr" ? "xr" : null;
  if (pendingStart && kind !== "build" && (!brand.model || !brand.provider || !brand.source)) {
    const clicked = getSelectedPromptModelInfo() || {};
    if (!brand.model) brand.model = String(clicked.model || "").trim();
    if (!brand.provider) brand.provider = String(clicked.provider || "").trim();
    if (!brand.source) brand.source = String(clicked.source || "").trim();
  }
  if (currentUser) {
    upsertProjectInList({
      id: pid,
      generation: {
        ...(allProjects.find((p) => p.id === pid)?.generation || {}),
        status: "running",
        kind,
        by_user_id: currentUser.id,
        by_user_name: currentUser.display_name,
        by_avatar_url: currentUser.avatar_url,
        ...(brand.model ? { model: brand.model } : {}),
        ...(brand.provider ? { provider: brand.provider } : {}),
        ...(brand.source ? { source: brand.source } : {}),
        ...(xrClient ? { client: xrClient } : {}),
      },
    });
    renderProjectList();
  }
  if (kind === "wiring") {
    generationWatchOverlay = {
      kind,
      promptMode: "wiring",
      startedAt: Date.now(),
      pendingStart: !!pendingStart,
      message: "Generating wiring schematic… (safe to refresh)",
      mode: "ai",
      estimateMs: 120000,
      ...(brand.model ? { model: brand.model } : {}),
    };
  } else if (kind === "build") {
    generationWatchOverlay = {
      kind,
      promptMode: "build",
      startedAt: Date.now(),
      pendingStart: !!pendingStart,
      message: "Building solid with CAD kernel…",
      mode: "build",
      estimateMs: 45000,
    };
  } else if (kind === "rigging") {
    generationWatchOverlay = {
      kind,
      promptMode: "rigging",
      startedAt: Date.now(),
      pendingStart: !!pendingStart,
      progress: {
        pct: 2,
        label: "Starting robot artifact generation…",
        thinking: "Preparing the URDF/SRDF authoring job.",
      },
      ...promptGenerationOverlayOpts("rigging"),
    };
  } else if (kind === "improve_lab") {
    generationWatchOverlay = {
      kind,
      promptMode: mode || "v2",
      startedAt: Date.now(),
      pendingStart: !!pendingStart,
      message: "Improve Lab — comparing overlays…",
      estimateMs: 180000,
    };
  } else if (kind === "video") {
    generationWatchOverlay = {
      kind: "video",
      promptMode: "video",
      startedAt: Date.now(),
      pendingStart: !!pendingStart,
      message: "Generating film edit… (safe to refresh)",
      estimateMs: 180000,
    };
  } else {
    generationWatchOverlay = {
      kind,
      promptMode: mode,
      startedAt: Date.now(),
      pendingStart: !!pendingStart,
      skills: getEnabledSkillsForPrompt({
        hasImages: (typeof promptImages !== "undefined" && promptImages?.length > 0),
        mode,
      }),
      ...promptGenerationOverlayOpts(mode),
    };
  }
  generationWatchOverlay.model = brand.model;
  generationWatchOverlay.provider = brand.provider;
  generationWatchOverlay.source = brand.source;
  const resolvedTarget = String(targetMode || getPromptTargetMode?.() || "").toLowerCase();
  if (resolvedTarget === "edit" || resolvedTarget === "new") {
    generationWatchOverlay.targetMode = resolvedTarget;
  }
  Object.assign(generationWatchOverlay, resolveGenerationIdentity(generationWatchOverlay, {
    sessionUser: sessionUserForGeneration(),
  }));
  if (xrClient) generationWatchOverlay.client = xrClient;
  if (usedCanvas) {
    generationWatchOverlay.from_canvas = true;
    generationWatchOverlay.usedCanvas = true;
  }
  generationWatchOverlay.pendingStartedAt = Number(generationWatchOverlay.startedAt) || Date.now();
  generationWatchOverlay.pendingBaselineCount = liveServerCadJobs(
    allProjects.find((p) => p.id === pid)?.generation,
  ).length;
  // Do not setProjectLoading here — that blanked the Browser tree with
  // "Loading project…" for the whole AI run. Generation has its own overlay/pill.
  if (kind === "wiring") {
    showAiComposePanel();
  } else if (kind === "rigging") {
    const keepRiggingVisible = workspaceModes?.getDesignTab?.() === "RIGGING";
    if (keepRiggingVisible) {
      workspaceModes?.setDesignTab?.("RIGGING");
      ribbon?.setDesignTab?.("RIGGING");
      enterRiggingMode();
      setRightTab("rigging");
    }
  } else if (kind === "video" || isVideoGenerationKind({ kind })) {
    // Film edit lives in the clip editor — do not steal CAD compose.
  } else if (kind !== "build") {
    showAiComposePanel();
  }
  syncViewportGenerationOverlay();
  if (kind === "wiring") {
    document.getElementById("btn-wiring-prompt")?.setAttribute("disabled", "true");
    document.getElementById("btn-wiring-toolbelt-generate")?.setAttribute("disabled", "true");
    const wiringStatus = document.getElementById("wiring-prompt-status");
    if (wiringStatus && pid === projectId) {
      wiringStatus.className = "status loading";
      wiringStatus.textContent = "Generating schematic… safe to refresh.";
    }
  } else if (kind === "rigging") {
    const riggingStatus = document.getElementById("rigging-prompt-status");
    if (riggingStatus && pid === projectId) {
      riggingStatus.className = "status loading";
      riggingStatus.textContent = "Generating rigging… safe to refresh or switch projects.";
    }
  } else if (kind === "build") {
    // Parametric ribbon / kernel builds — never reuse AI "Generating…" copy.
    const statusEl = document.getElementById("prompt-status");
    if (statusEl && pid === projectId) {
      statusEl.className = "status loading";
      statusEl.textContent = "Building solid…";
    }
  } else if (kind === "improve_lab") {
    const statusEl = document.getElementById("prompt-status");
    if (statusEl && pid === projectId) {
      statusEl.className = "status loading";
      statusEl.textContent = "Improve Lab — comparing overlays (not on the main timeline)…";
    }
  } else if (kind === "video" || isVideoGenerationKind({ kind })) {
    /* Clip editor owns generating status. */
  } else {
    // Keep Generate enabled so another part can be queued while this runs.
    const statusEl = document.getElementById("prompt-status");
    if (statusEl && pid === projectId) {
      statusEl.className = "status loading";
      statusEl.textContent =
        (mode || "standard").toLowerCase() === "mesh" || (mode || "standard").toLowerCase() === "fusion"
          ? "Generating Mesh in background… Three.js factory → GLB (safe to refresh)."
          : (mode || "standard").toLowerCase() === "vibecad"
            || (mode || "standard").toLowerCase() === "vibe"
            || (mode || "standard").toLowerCase() === "vibecade"
            ? "Generating with VibeCAD in background... refresh anytime; model loads when ready."
            : (mode || "standard").toLowerCase() === "mac"
              || (mode || "standard").toLowerCase() === "macad"
              || (mode || "standard").toLowerCase() === "multi_agent_cad"
              ? "Generating with MAC (Multi-Agent CAD) in background... refresh anytime; model loads when ready."
              : (mode || "standard").toLowerCase() === "v2"
                || (mode || "standard").toLowerCase() === "jake"
                ? "Generating with Jake (text-to-cad) in background... refresh anytime; model loads when ready."
                : "Generating in background… safe to refresh.";
    }
    // Do NOT applyPromptModeUI(mode) here. Resuming a prior 2.0 job was stealing
    // the compose picker (Mesh → 2.0) right before Generate built the request body.
  }
  syncStopButtonVisibility();
  if ((kind === "prompt" || kind === "build") && pid === projectId) {
    showPendingPromptTimelineStep({
      kind,
      mode,
      skills: generationWatchOverlay?.skills,
      usedCanvas: !!(generationWatchOverlay?.from_canvas || generationWatchOverlay?.usedCanvas),
    });
  }

  const poll = async () => {
    // Project-swap GLBs share the origin with these ticks — stay quiet until
    // the viewport mesh is in.
    if (loadingProjectIds.size > 0) return;
    abortGenerationPoll(pid);
    const ctl = new AbortController();
    generationPollAborts.set(pid, ctl);
    try {
      const gen = await api(`/api/projects/${pid}/generation`, { signal: ctl.signal });
      meshEditSession.reconcilePaidGeneration(pid, gen);
      if (ctl.signal.aborted) return;
      syncPendingPromptHistoryFromGeneration(gen, pid);
      try { hydrateWiringHistoryFromGeneration(gen, pid); } catch (_) { /* history optional */ }
      const runningJobs = generationRunningJobs(gen, generationWatchOverlay);
      const liveOnServer = serverGenerationIsLive(gen, runningJobs);
      const proj = allProjects.find((p) => p.id === pid);
      if (proj) {
        const prevGen = proj.generation;
        if (generationWatchOverlay?.pendingStart && !liveOnServer) {
          // POST is still in flight — don't replace the local "running" row with
          // the previous job's leftover complete/idle payload.
          proj.generation = mergeGenerationIdentity({
            ...gen,
            status: "running",
            kind: generationWatchOverlay.kind || gen.kind || "prompt",
          }, prevGen);
        } else {
          proj.generation = mergeGenerationIdentity(gen, prevGen);
        }
      }
      if (liveOnServer) {
        if (generationWatchPid === pid && generationWatchOverlay) {
          const isKernelBuild = generationWatchOverlay.kind === "build";
          const liveMode = generationWatchOverlay.kind === "rigging"
            ? "rigging"
            : isKernelBuild
              ? "build"
              : generationPromptMode(gen, generationWatchOverlay.promptMode || mode);
          const liveJobs = runningJobs.filter((job) => !isPendingGenerationJob(job));
          const baseline = Number(generationWatchOverlay.pendingBaselineCount || 0);
          const keepPending = keepPendingAdditionalGeneration({
            pendingStart: generationWatchOverlay.pendingStart,
            liveJobCount: liveJobs.length,
            baseline,
          });
          const newestLive = liveJobs[liveJobs.length - 1];
          const overlayPatch = {
            promptMode: liveMode,
            pendingStart: keepPending,
            pendingBaselineCount: keepPending ? baseline : liveJobs.length,
            focusedJobId: focusedJobIdAfterPending({
              keepPending,
              focusedJobId: generationWatchOverlay.focusedJobId,
              newestLiveId: newestLive?.trace_id || newestLive?.id || null,
            }),
            benignInterruptAt: null,
            progress: keepPending
              ? {
                ...(generationWatchOverlay.progress || {}),
                pct: Math.max(2, Number(generationWatchOverlay.progress?.pct) || 2),
                label: generationWatchOverlay.progress?.label || "Starting another generation…",
              }
              : {
                ...(generationWatchOverlay.progress || {}),
                ...(gen.progress || {}),
                improved_prompt:
                  gen.progress?.improved_prompt
                  ?? gen.progress?.prompt_preview
                  ?? generationWatchOverlay.progress?.improved_prompt
                  ?? generationWatchOverlay.progress?.prompt_preview,
              },
          };
          if (isKernelBuild) {
            // Keep CAD build copy — do not overwrite with AI "Generating…" opts.
            Object.assign(generationWatchOverlay, overlayPatch, {
              message: gen.progress?.label || generationWatchOverlay.message || "Building solid with CAD kernel…",
              mode: "build",
              estimateMs: 45000,
            });
          } else if (generationWatchOverlay.kind === "improve_lab") {
            Object.assign(generationWatchOverlay, overlayPatch, {
              kind: "improve_lab",
              message: gen.progress?.label || generationWatchOverlay.message || "Improve Lab — comparing overlays…",
            });
          } else if (keepPending) {
            Object.assign(generationWatchOverlay, overlayPatch);
          } else {
            Object.assign(generationWatchOverlay, overlayPatch, promptGenerationOverlayOpts(liveMode));
          }
        }
        // Apply any sibling jobs that finished while others still run.
        for (const job of gen.jobs || []) {
          if (job.status === "complete" && !jobFinishedDuringCurrentWatch(job)) {
            markGenerationApplied(pid, job.trace_id);
            continue;
          }
          if (job.status === "complete" && job.kind === "rigging" && !wasGenerationApplied(pid, job.trace_id)) {
            try {
              await applyRiggingGenerationComplete(job, pid);
            } catch (err) {
              console.warn("apply completed rigging generation failed", err);
            }
          } else if (job.status === "complete" && job.kind !== "wiring" && !wasGenerationApplied(pid, job.trace_id)) {
            try {
              await applyGenerationComplete(job, pid);
            } catch (err) {
              console.warn("apply completed parallel generation failed", err);
            }
          } else if (job.status === "complete" && job.kind === "wiring" && !wasGenerationApplied(pid, job.trace_id)) {
            try {
              await applyWiringGenerationComplete(job, pid);
            } catch (err) {
              console.warn("apply completed wiring generation failed", err);
            }
          }
        }
        const liveVideo = runningJobs.find((job) => isVideoGenerationKind(job))
          || (isVideoGenerationKind(gen) ? gen : null);
        if (liveVideo) emitVideoGeneration(liveVideo, pid, "running");
        syncViewportGenerationOverlay();
        syncExplorerLoadingUI();
        syncStopButtonVisibility();
        syncCanvasGenerationUi();
        return;
      }
      // Improve/POST still in flight. The previous mesh job is still "complete" on
      // the server, so treating that as this click finishing flashed "Model ready"
      // and dropped the project before the new run actually started.
      if (generationWatchOverlay?.pendingStart && !generationBelongsToCurrentWatch(gen)) {
        syncViewportGenerationOverlay();
        syncExplorerLoadingUI();
        syncStopButtonVisibility();
        syncCanvasGenerationUi();
        return;
      }
      const watchAgeMs = Math.max(0, Date.now() - Number(generationWatchOverlay?.startedAt || Date.now()));
      if (
        (!gen.status || gen.status === "idle") &&
        (generationWatchOverlay?.pendingStart || watchAgeMs < 20_000)
      ) {
        syncStopButtonVisibility();
        syncCanvasGenerationUi();
        return;
      }
      if (
        generationWatchOverlay?.pendingStart
        && generationWatchOverlay?.kind === "rigging"
        && watchAgeMs < 20_000
      ) {
        const statusEl = document.getElementById("rigging-prompt-status");
        if (statusEl && pid === projectId) {
          statusEl.className = "status loading";
          statusEl.textContent = "Starting robot artifact generation…";
        }
        syncViewportGenerationOverlay();
        syncStopButtonVisibility();
        syncCanvasGenerationUi();
        return;
      }
      // After a deploy, stuck jobs are STOPPED (not auto-resumed). Auto-resume
      // used to re-run the prompt from scratch and re-bill. Fall through to the
      // normal finished-job handlers below.
      stopGenerationWatch(pid);
      userCancelRequested = false;
      // Handle finished jobs from the multi-job list first.
      const finishedJobs = Array.isArray(gen.jobs) && gen.jobs.length ? gen.jobs : [gen];
      for (const job of finishedJobs) {
        if (job.status === "complete") {
          if (job.kind === "wiring") {
            if (!wasGenerationApplied(pid, job.trace_id)) {
              await applyWiringGenerationComplete(job, pid);
            }
          } else if (job.kind === "rigging") {
            if (!wasGenerationApplied(pid, job.trace_id)) {
              await applyRiggingGenerationComplete(job, pid);
            }
          } else if (!wasGenerationApplied(pid, job.trace_id)) {
            await applyGenerationComplete(job, pid);
          }
        }
      }
      if (gen.status === "complete") {
        if (gen.kind === "wiring") {
          if (!wasGenerationApplied(pid, gen.trace_id)) {
            await applyWiringGenerationComplete(gen, pid);
          } else if (pid === projectId) {
            const schematic = await api(`/api/projects/${pid}/wiring`);
            wiringSim.applySchematic(schematic, { revealRequirements: true });
            invalidateWiringPrefetch();
            await refreshFiles();
            await refreshWiringPromptHistory();
            await refreshPromptHistory();
          }
        } else if (gen.kind === "rigging") {
          if (!wasGenerationApplied(pid, gen.trace_id)) {
            await applyRiggingGenerationComplete(gen, pid);
          }
        } else if (!wasGenerationApplied(pid, gen.trace_id)) {
          await applyGenerationComplete(gen, pid);
        } else if (pid === projectId) {
          await refreshFiles();
          await refreshTimeline();
          await refreshPromptHistory();
          const statusEl = document.getElementById("prompt-status");
          if (statusEl && gen.filename) {
            const ref = gen.prompt_id
              ? formatPromptRef({
                promptId: gen.prompt_id,
                projectId: pid,
                filename: gen.filename,
                traceId: gen.trace_id,
                promptMode: gen.mode || gen.prompt_mode,
                model: gen.model,
                provider: gen.provider,
                skills: gen.skills || gen.request_body?.skills,
              })
              : "";
            statusEl.className = "status ok";
            statusEl.textContent = ref ? `Model ready · ${ref}` : "Model ready.";
          }
        }
      } else if (gen.status === "failed") {
        const rawError = String(gen.error || "Generation failed.");
        rememberCadDebugFailure(gen);
        const msg = formatUserError({ message: rawError });
        const copyContext = {
          promptId: gen.prompt_id,
          projectId: pid,
          filename: gen.filename || selectedFile,
          traceId: gen.trace_id,
          promptText: gen.prompt || lastPromptCopyContext?.promptText,
        };
        const statusEl = document.getElementById(generationStatusElementId(gen));
        // Server-restart stops are expected after deploys — never popup, never auto-resume.
        if (gen.benign_interrupt || gen.server_restart_stop || isBenignGenerationInterrupt(rawError)) {
          if (statusEl && pid === projectId) {
            statusEl.className = "status";
            statusEl.textContent =
              "Ready — previous run stopped during a server restart (not re-billed). Retry when ready.";
          }
          if (pid === projectId) {
            viewerOverlay.clearError();
            wiringOverlay?.clearError();
          }
          stopGenerationWatch(pid);
          userCancelRequested = false;
          if (pid === projectId) {
            if (gen.kind === "wiring") {
              await refreshWiringPromptHistory();
              await refreshPromptHistory();
            } else if (gen.kind === "rigging") await refreshRiggingPromptHistory();
            else await refreshPromptHistory();
            await refreshTimeline();
            try {
              if (document.body.classList.contains("xr-presenting") || viewportXR?.isPresenting?.()) {
                viewportXR?.setAiGenerating?.(false);
                viewportXR?.setAiPanelStatus?.(
                  "Ready — previous run stopped during a server restart. Retry when ready.",
                );
                viewportXR?.refreshAiPromptPanel?.();
              }
            } catch (_) { }
          }
        } else {
          setPromptPanelFailureStatus(statusEl);
          // Only popup once per failed trace — avoids re-showing old timeout banners on refresh/Generate.
          const alreadyShown = generationWatchOverlay?.shownFailureTrace === gen.trace_id;
          if (pid === projectId && !alreadyShown) {
            if (gen.kind === "wiring") {
              wiringOverlay?.showError(msg, {
                ...copyContext,
                suggestions: generationFailureAdvice({ message: rawError }),
              });
              await refreshWiringPromptHistory();
              await refreshPromptHistory();
            } else if (gen.kind === "rigging") {
              showPromptGenerationFailure({ message: rawError }, copyContext, gen.trace_id);
              await refreshRiggingPromptHistory();
            } else {
              showPromptGenerationFailure({ message: rawError }, copyContext, gen.trace_id);
              await refreshPromptHistory();
            }
            await refreshTimeline();
            try {
              if (document.body.classList.contains("xr-presenting") || viewportXR?.isPresenting?.()) {
                viewportXR?.setAiGenerating?.(false);
                viewportXR?.setAiPanelStatus?.(
                  `Generate failed — see timeline · ${gen.prompt_id || gen.trace_id || "retry"}`,
                );
                viewportXR?.setMenuFooterHint?.("Generate failed — check timeline / retry");
                viewportXR?.refreshAiPromptPanel?.();
              }
            } catch (_) { }
          } else if (pid === projectId) {
            if (gen.kind === "wiring") {
              await refreshWiringPromptHistory();
              await refreshPromptHistory();
            } else if (gen.kind === "rigging") await refreshRiggingPromptHistory();
            else await refreshPromptHistory();
            await refreshTimeline();
          }
          // Failed runs are finished — always unlock Generate for a retry.
          document.getElementById("btn-prompt")?.removeAttribute("disabled");
          promptSubmitInFlight = false;
        }
        window.dispatchEvent(new CustomEvent("render3d:generation-settled", {
          detail: { ...gen, projectId: pid, status: "failed", error: rawError },
        }));
      } else if (gen.status === "canceled") {
        const rawCancel = gen.error || "Generation canceled.";
        const msg = isBenignGenerationInterrupt(rawCancel)
          ? "Ready — previous run stopped during a server restart (not re-billed). Retry when ready."
          : rawCancel;
        const statusEl = document.getElementById(generationStatusElementId(gen));
        if (statusEl && pid === projectId) {
          statusEl.className = "status";
          statusEl.textContent = msg;
        }
        if (pid === projectId) {
          viewerOverlay.clearError();
          wiringOverlay?.clearError();
          if (gen.kind !== "wiring" && gen.kind !== "rigging") {
            await refreshPromptHistory();
            const stoppedEntry = latestPromptHistoryEntries.find(
              (e) => e.status === "stopped" && (!gen.trace_id || e.trace_id === gen.trace_id),
            );
            const usageLabel = formatUsageStopLabel(stoppedEntry) || formatUsageStopLabel(gen);
            if (statusEl && usageLabel && !isBenignGenerationInterrupt(rawCancel)) {
              statusEl.textContent = `${String(msg).replace(/\.$/, "")}. Used ${usageLabel} before stopping.`;
            }
            restoreComposeDraftAfterStop({
              prompt: promptTextForStoppedGeneration(gen, stoppedEntry?.prompt),
              promptMode: gen.mode || gen.prompt_mode,
            });
            schedulePromptHistoryFollowupRefresh(pid, 1800);
          }
        }
        window.dispatchEvent(new CustomEvent("render3d:generation-settled", {
          detail: { ...gen, projectId: pid, status: "canceled", error: rawCancel },
        }));
      }
      syncExplorerLoadingUI();
      document.getElementById("btn-wiring-prompt")?.removeAttribute("disabled");
      document.getElementById("btn-wiring-toolbelt-generate")?.removeAttribute("disabled");
    } catch (err) {
      if (ctl.signal.aborted || err?.name === "AbortError") return;
      console.warn("generation poll failed", err);
    } finally {
      if (generationPollAborts.get(pid) === ctl) generationPollAborts.delete(pid);
    }
  };
  poll();
  generationPollTimers.set(pid, setInterval(poll, 8000));
  syncStopButtonVisibility();
  syncCanvasGenerationUi();
}

async function resumeGenerationIfNeeded(pid, generation) {
  if (!pid || !generation || generation.status === "idle") {
    if (pid === projectId) syncStopButtonVisibility();
    return;
  }
  if (generation.status === "running") {
    const videoJob = videoJobFromGeneration(generation);
    beginGenerationWatch(pid, {
      kind: generation.kind || "prompt",
      mode: generationPromptMode(generation),
      model: generation.model,
      provider: generation.provider,
      usedCanvas: generationUsedCanvas(generation),
    });
    if (videoJob && String(videoJob.status || "") === "running") {
      emitVideoGeneration(videoJob, pid, "running");
    }
    return;
  }
  if (generation.status === "complete") {
    const applied = wasGenerationApplied(pid, generation.trace_id);
    // Off-project completions mark applied without loading — reopen must still reveal.
    const needsViewportReload =
      pid === projectId
      && !!generation.filename
      && !(workspaceModes?.isWiring?.() ?? false)
      && (
        hasPendingViewportReveal(pid)
        || (projectAssembly.count() === 0 && !projectAssembly.has(generation.filename))
      );
    if (!applied || needsViewportReload) {
      if (generation.kind === "wiring") {
        await applyWiringGenerationComplete(generation, pid);
        return;
      }
      if (generation.kind === "rigging") {
        await applyRiggingGenerationComplete(generation, pid);
        return;
      }
      await applyGenerationComplete(generation, pid);
    }
  }
}

