const _studioCreditStampAt = Object.create(null);
function reportClientIncident(feature, status, note = "", fields = {}) {
  if (!feature || !getToken()) return;
  void fetch("/api/ops/incidents/events", {
    method: "POST", headers: { ...authHeaders(), "Content-Type": "application/json" },
    body: JSON.stringify({
      feature, status, kind: "client-smoke", project_id: projectId || "",
      source: "studio-webgl", note, fields
    }),
  }).catch(() => { });
}
function stampStudioCreditIncident(eventType, note = "", fields = {}) {
  const feature = studioSmokeFeature(eventType, fields);
  if (!feature) return;
  const now = Date.now();
  if (_studioCreditStampAt[feature] && now - _studioCreditStampAt[feature] < 20000) return;
  _studioCreditStampAt[feature] = now;
  reportClientIncident(feature, studioSmokeStatus(eventType), note, fields);
}
try {
  globalThis.addEventListener?.(STUDIO_CREDIT_EVENT, (ev) => {
    const d = ev?.detail || {};
    stampStudioCreditIncident(d.eventType || d.kind, d.note || "", d);
  });
} catch (_) { /* stamp is best-effort */ }
function startStudioRamCreditWatchdog() {
  let lastHeap = heapMbNow();
  window.setInterval(() => {
    const mem = heapMbNow();
    let limit = null;
    try {
      const n = performance.memory?.jsHeapSizeLimit;
      if (Number.isFinite(n)) limit = Math.round((n / (1024 * 1024)) * 10) / 10;
    } catch (_) { /* Chrome-only */ }
    if (mem != null && lastHeap != null && (mem - lastHeap) >= DESK_HEAP_JUMP_MB) {
      const scope = desktopPerfScope();
      stampStudioCreditIncident("heap.jump", `Heap jumped ${lastHeap}→${mem} MB`, { memMb: mem, prevMb: lastHeap, scope });
    }
    if (mem != null && limit && mem >= limit * 0.9) {
      stampStudioCreditIncident("ram.high", `Heap near limit ${mem}/${limit} MB`, { memMb: mem, limitMb: limit, scope: desktopPerfScope() });
    }
    if (mem != null) lastHeap = mem;
  }, 15000);
}
startStudioRamCreditWatchdog();
