hardenTransformHelper();

/** XR Folders tab: personal + shared folder roots, then projects inside a folder. */
function buildXrFolderBrowserItems(folderId = null) {
  const projects = Array.isArray(allProjects) ? allProjects : [];
  const folders = (typeof workspaceBrowser?.getFolders === "function"
    ? workspaceBrowser.getFolders()
    : []) || [];

  const isCommunity = (f) => {
    const id = String(f?.id || "");
    return f?.public === true || id === "__public__" || id === "__other_user_renders__";
  };
  const isSharedWs = (f) => {
    const id = String(f?.id || "");
    return f?.shared_workspace === true || id.startsWith("__shared_ws_");
  };
  const isSharedFolder = (f) => {
    if (!f) return false;
    if (isSharedWs(f)) return true;
    if (f.shared_with_me) return true;
    if (f.visibility === "shared") return true;
    return (Number(f.share_count) || 0) > 0;
  };

  const projectsInFolder = (fid) => {
    if (fid === "__root__" || fid == null || fid === "") {
      return projects.filter((p) => !p?.folder_id);
    }
    return projects.filter((p) => String(p?.folder_id || "") === String(fid));
  };

  // Drill into a folder → list its projects
  if (folderId) {
    const lines = [
      { id: "__back__", label: "← All folders", kind: "back", icon: "undo" },
    ];
    const list = projectsInFolder(folderId);
    if (!list.length) {
      lines.push({ id: "", label: "No projects in this folder", kind: "hint", icon: "front" });
      return lines;
    }
    for (const p of list.slice(0, 8)) {
      lines.push({
        id: p.id,
        label: p.name || p.id,
        kind: "project",
        active: p.id === projectId,
        icon: "front",
      });
    }
    return lines;
  }

  // Root: Personal + Shared folders
  const personal = [];
  const shared = [];
  const rootCount = projectsInFolder("__root__").length;
  personal.push({
    id: "__root__",
    label: rootCount ? `Personal files · ${rootCount}` : "Personal files",
    kind: "folder",
    icon: "place",
  });

  for (const f of folders) {
    if (!f?.id || isCommunity(f)) continue;
    const count = projectsInFolder(f.id).length;
    const row = {
      id: f.id,
      label: count ? `${f.name || "Folder"} · ${count}` : (f.name || "Folder"),
      kind: "folder",
      icon: "place",
      shared: isSharedFolder(f),
    };
    if (isSharedFolder(f)) shared.push(row);
    else personal.push(row);
  }

  const lines = [];
  if (personal.length) {
    lines.push({ id: "", label: "PERSONAL", kind: "section", icon: "place" });
    for (const row of personal) {
      lines.push(row);
      if (lines.length >= 9) return lines.slice(0, 9);
    }
  }
  if (shared.length) {
    if (lines.length < 9) {
      lines.push({ id: "", label: "SHARED", kind: "section", icon: "place" });
    }
    for (const row of shared) {
      if (lines.length >= 9) break;
      lines.push(row);
    }
  }
  if (!lines.length) {
    return [{ id: "", label: "No folders yet", kind: "hint", icon: "place" }];
  }
  return lines.slice(0, 9);
}

let xrPublicLobby = null;
let publishSceneMeshesToRoom = async () => ({ ok: true, skipped: true });
let voiceMold = null;
let voiceWake = null;
let xrAgent = null;
let activeHeyAiContext = null;
let heyAiFinalizePromise = null;
let lastHeyAiCompletedAt = 0;
let heyAiProjectContextCache = null;
const HEY_AI_REFERENCE_FOLDER = "Hey AI";
const voiceStartGate = createVoiceStartGate();

function heyAiReference(session = activeHeyAiContext) {
  if (!session) return null;
  const transcript = session.transcript
    .map((line) => `${line.role === "assistant" ? "AI" : "You"}: ${line.text}`)
    .join("\n");
  const summary = transcript || "Hey AI is listening…";
  return {
    id: session.id,
    type: "document",
    token: `@hey-ai-${session.startedAt}`,
    label: session.label,
    filename: session.filename || `${session.stem}.json`,
    stem: session.stem,
    format: "json",
    text_content: summary.slice(0, 100000),
    description: session.live ? "Hey AI · listening" : (session.summary || "Hey AI conversation context"),
    projectId: projectId || null,
    url: session.url || "",
    voice_context: true,
    voice_live: session.live === true,
    voice_summary: session.summary || "",
  };
}

function syncHeyAiReference() {
  const session = activeHeyAiContext;
  if (!session) return;
  const ref = heyAiReference(session);
  const refs = composer?.getReferences?.() || [];
  const next = refs.filter((item) => item?.id !== session.id);
  next.push(ref);
  composer?.replaceReferences?.(next);
}

function beginHeyAiContext() {
  if (activeHeyAiContext?.live) return activeHeyAiContext;
  const startedAt = Date.now();
  const stamp = new Date(startedAt).toISOString().replace(/[:.]/g, "-");
  activeHeyAiContext = {
    id: `voice-context:${projectId || "pending"}:${startedAt}`,
    startedAt,
    stem: `hey-ai-${stamp}`,
    label: "Hey AI · listening",
    live: true,
    transcript: [],
    pointers: [],
    promptAtStart: String(composer?.getPromptText?.() || ""),
    sceneAtStart: getVoiceMoldDesignContext(),
    recorder: null,
    audioChunks: [],
    askGenerateAnother: lastHeyAiCompletedAt > 0,
  };
  syncHeyAiReference();
  syncVoiceOrderControls(true);
  return activeHeyAiContext;
}

function startHeyAiAudioCapture(stream) {
  const session = activeHeyAiContext;
  if (!session || session.recorder || !stream?.getAudioTracks?.().length || !window.MediaRecorder) return;
  try {
    const preferred = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4"]
      .find((type) => MediaRecorder.isTypeSupported?.(type));
    const recorder = preferred ? new MediaRecorder(stream, { mimeType: preferred }) : new MediaRecorder(stream);
    recorder.ondataavailable = (event) => { if (event.data?.size) session.audioChunks.push(event.data); };
    recorder.start(500);
    session.recorder = recorder;
  } catch (err) {
    console.warn("[hey-ai] audio context recording unavailable", err);
  }
}

function captureHeyAiTranscript(entry = {}) {
  const session = activeHeyAiContext;
  const text = String(entry.text || "").trim();
  if (!session?.live || !text) return;
  session.transcript.push({ role: entry.role === "assistant" ? "assistant" : "user", text, at: Date.now() });
  if (session.transcript.length > 80) session.transcript.splice(0, session.transcript.length - 80);
  syncHeyAiReference();
}

function captureHeyAiPointerContext(event, kind = "hover") {
  const session = activeHeyAiContext;
  if (!session?.live || !event || (kind === "hover" && Date.now() - (session.lastPointerAt || 0) < 180)) return;
  session.lastPointerAt = Date.now();
  let hit = null;
  try {
    hit = pickObject(event, { camera, domElement: renderer.domElement, meshRoot: currentMesh });
  } catch (_) { }
  const point = hit?.point;
  const selection = objectTools?.getSelection?.();
  session.pointers.push({
    at: session.lastPointerAt,
    kind,
    screen: [Math.round(event.clientX || 0), Math.round(event.clientY || 0)],
    world: point ? [point.x, point.y, point.z].map((value) => Number(value.toFixed(5))) : null,
    object: hit?.mesh ? (catalogNameForMesh(hit.mesh) || hit.mesh.name || null) : null,
    selected: selection?.catalogName || selection?.label || selectedFile || null,
    camera: camera ? {
      position: camera.position.toArray().map((value) => Number(value.toFixed(5))),
      target: controls?.target?.toArray?.().map((value) => Number(value.toFixed(5))) || null,
    } : null,
  });
  if (session.pointers.length > 240) session.pointers.splice(0, session.pointers.length - 240);
}

async function uploadHeyAiFile(file, folder = HEY_AI_REFERENCE_FOLDER) {
  if (!projectId || !file) return null;
  const form = new FormData();
  form.append("file", file, file.name);
  form.append("reference_folder", folder);
  return api(`/api/projects/${projectId}/upload`, { method: "POST", body: form });
}

async function finalizeHeyAiContext({ stopVoice = false, removed = false } = {}) {
  if (heyAiFinalizePromise) return heyAiFinalizePromise;
  const session = activeHeyAiContext;
  if (!session) return null;
  heyAiFinalizePromise = (async () => {
    session.live = false;
    session.label = "Hey AI context";
    if (stopVoice) {
      try { await xrAgent?.stop?.(); } catch { try { voiceMold?.stop?.(); } catch (_) { } }
    }
    if (session.recorder?.state && session.recorder.state !== "inactive") {
      await new Promise((resolve) => {
        const recorder = session.recorder;
        const done = () => resolve();
        recorder.addEventListener("stop", done, { once: true });
        try { recorder.stop(); } catch (_) { resolve(); }
        window.setTimeout(resolve, 1200);
      });
    }
    session.endedAt = Date.now();
    lastHeyAiCompletedAt = session.endedAt;
    const userLines = session.transcript.filter((line) => line.role === "user").map((line) => line.text);
    const aiLines = session.transcript.filter((line) => line.role === "assistant").map((line) => line.text);
    session.summary = userLines.length
      ? `${userLines.slice(0, 3).join(" ").slice(0, 260)}${aiLines.length ? ` · AI replied ${aiLines.length} time${aiLines.length === 1 ? "" : "s"}` : ""}`
      : "Voice session captured with viewport context";
    if (!removed) {
      try {
        await ensureProject();
        if (session.audioChunks.length) {
          const mime = session.recorder?.mimeType || session.audioChunks[0]?.type || "audio/webm";
          const ext = mime.includes("mp4") ? "m4a" : "webm";
          const audio = new File(session.audioChunks, `${session.stem}.${ext}`, { type: mime });
          const audioUploaded = await uploadHeyAiFile(audio);
          session.audio_filename = audioUploaded?.filename || audio.name;
          session.audio_url = audioUploaded?.url || "";
        }
        const payload = {
          version: 1,
          kind: "hey-ai-context",
          project_id: projectId,
          started_at: new Date(session.startedAt).toISOString(),
          ended_at: new Date(session.endedAt).toISOString(),
          summary: session.summary,
          prompt_at_start: session.promptAtStart,
          prompt_at_submit: String(composer?.getPromptText?.() || ""),
          transcript: session.transcript,
          pointer_samples: session.pointers,
          scene_at_start: session.sceneAtStart,
          scene_at_end: getVoiceMoldDesignContext(),
          audio_filename: session.audio_filename || null,
          audio_url: session.audio_url || null,
        };
        const json = new File([JSON.stringify(payload, null, 2)], `${session.stem}.json`, { type: "application/json" });
        const uploaded = await uploadHeyAiFile(json);
        session.filename = uploaded?.filename || json.name;
        session.url = uploaded?.url || "";
        await refreshFiles();
        syncHeyAiReference();
      } catch (err) {
        console.warn("[hey-ai] context persistence failed", err);
        syncHeyAiReference();
      }
      rememberHeyAiSessionSummary(projectId, session);
      heyAiProjectContextCache = null;
    }
    syncVoiceOrderControls(false);
    return session;
  })().finally(() => { heyAiFinalizePromise = null; });
  return heyAiFinalizePromise;
}
