function currentXrCaptureModeLabel() {
  const mode = String(viewportXR?.getSessionMode?.() || "").toLowerCase();
  return mode.includes("vr") ? "VR" : "AR";
}

async function dataUrlToBlob(dataUrl) {
  const res = await fetch(dataUrl);
  return res.blob();
}

function revealSavedReferenceFolder(folder) {
  const name = String(folder || "").split("/")[0].trim() || "Screen Recordings";
  try { projectTree?.revealReferenceFolder?.(name); } catch (_) { }
  try { workspaceBrowser?.showReferenceFiles?.({ folder: name }); } catch (_) { }
}

async function saveCaptureToReferences(blob, opts = {}) {
  if (!blob) return null;
  if (!projectId) {
    try { await ensureProject(); } catch (_) { }
  }
  if (opts.saved?.filename) {
    const folderName = opts.saved.folder || (opts.kind === "video" ? "Screen Recordings" : "Screenshots");
    rememberSavedReference(opts.saved);
    setEditStatus("ok", `Saved ${opts.saved.filename} under Reference Files → ${folderName}.`);
    try { await refreshFiles(); } catch (err) {
      console.warn("[capture] refresh after save failed", err);
    }
    revealSavedReferenceFolder(folderName);
    if (opts.xr) {
      try {
        const kind = opts.kind === "video" ? "video" : "screenshot";
        rememberLastXrCapture(opts.saved, {
          kind,
          modeLabel: opts.modeLabel || currentXrCaptureModeLabel(),
          blob,
        });
        await publishXrCaptureReady({
          kind,
          filename: opts.saved.filename,
          url: opts.saved.url,
          modeLabel: opts.modeLabel || currentXrCaptureModeLabel(),
          shareX: !!opts.shareX,
        });
        if (viewportXR?.isPresenting?.()) {
          viewportXR?.setCaptureState?.({
            recording: false,
            paused: false,
            elapsedMs: 0,
            clipReady: true,
          });
          playXrCaptureInHeadset({
            url: opts.saved.url,
            filename: opts.saved.filename,
            kind,
            blob,
          });
        }
      } catch (err) {
        console.warn("[xr] publish capture ready failed", err);
      }
    }
    return opts.saved;
  }
  if (!projectId) {
    setEditStatus("error", "Open a project first so captures save under Reference Files.");
    return null;
  }
  const kind = opts.kind === "video" ? "video" : "screenshot";
  const xr = !!opts.xr;
  const referenceFolder = kind === "video" ? "Screen Recordings" : "Screenshots";
  let ext = "png";
  let type = opts.mime || blob.type || "image/png";
  if (kind === "video") {
    if (/mp4|m4v/i.test(type)) ext = "mp4";
    else if (/quicktime|mov/i.test(type)) ext = "mov";
    else ext = "webm";
    type = type || (ext === "mp4" ? "video/mp4" : "video/webm");
  } else {
    ext = "png";
    type = "image/png";
  }
  const filename = `${captureFileBaseName({
    kind,
    xr,
    page: !!opts.page,
    fullscreen: !!opts.fullscreen,
    crop: !!opts.crop,
  })}.${ext}`;
  try {
    const data = await uploadProjectCapture(blob, {
      projectId,
      token: getToken?.(),
      kind,
      folder: referenceFolder,
      filename,
    });
    rememberSavedReference(data);
    setEditStatus("ok", `Saved ${data?.filename || filename} under Reference Files → ${data?.folder || referenceFolder}.`);
    try { await refreshFiles(); } catch (err) {
      console.warn("[capture] refresh after save failed", err);
    }
    revealSavedReferenceFolder(data?.folder || referenceFolder);
    if (xr) {
      viewportXR?.setMenuFooterHint?.(
        kind === "video"
          ? "Stopped — Send to computer or Share to X"
          : "Shot ready — Send to computer or Share to X",
      );
      try {
        const savedName = data?.filename || filename;
        const folderName = data?.folder || referenceFolder;
        const fileUrl = data?.url
          || `/api/projects/${projectId}/files/${encodeURIComponent(`${folderName}/${savedName}`)}`;
        rememberLastXrCapture(
          { filename: savedName, url: fileUrl },
          { kind, modeLabel: opts.modeLabel || currentXrCaptureModeLabel(), blob },
        );
        await publishXrCaptureReady({
          kind,
          filename: savedName,
          url: fileUrl,
          modeLabel: opts.modeLabel || currentXrCaptureModeLabel(),
          shareX: !!opts.shareX,
        });
        if (viewportXR?.isPresenting?.()) {
          viewportXR?.setCaptureState?.({
            recording: false,
            paused: false,
            elapsedMs: 0,
            clipReady: true,
          });
          playXrCaptureInHeadset({
            url: fileUrl,
            filename: savedName,
            kind,
            blob,
          });
        }
      } catch (err) {
        console.warn("[xr] publish capture ready failed", err);
      }
    }
    return data;
  } catch (err) {
    console.warn("[capture] save to references failed", err);
    setEditStatus("error", err?.message || "Could not save capture to Reference Files.");
    return null;
  }
}

function rememberSavedReference(data) {
  if (!data?.filename || !lastProjectBrowser) return;
  const folder = data.folder || null;
  const nextRow = {
    id: folder ? `${folder}:${String(data.filename).replace(/\.[^.]+$/, "")}` : String(data.filename).replace(/\.[^.]+$/, ""),
    name: data.filename,
    stem: String(data.filename).replace(/\.[^.]+$/, ""),
    format: String(data.filename).split(".").pop() || "",
    kind: data.kind || "video",
    url: data.url,
    folder,
    label: data.filename,
  };
  const refs = [...(lastProjectBrowser.references || [])];
  if (!refs.some((row) => row?.name === data.filename && String(row?.folder || "") === String(folder || ""))) {
    refs.unshift(nextRow);
    renderProjectBrowser({ ...lastProjectBrowser, references: refs });
  }
  const proj = (allProjects || []).find((row) => row?.id === projectId);
  if (proj) {
    const browser = { ...(proj.browser || {}) };
    const prefRefs = [...(browser.references || [])];
    if (!prefRefs.some((row) => row?.name === data.filename && String(row?.folder || "") === String(folder || ""))) {
      prefRefs.unshift(nextRow);
      proj.browser = { ...browser, references: prefRefs };
      try { renderProjectList(); } catch (_) { }
    }
  }
}

async function saveXrCaptureToReferences(blob, opts = {}) {
  return saveCaptureToReferences(blob, { ...opts, xr: true, silent: true });
}

async function publishXrCaptureReady({ kind, filename, url, modeLabel, shareX = false } = {}) {
  if (!projectId || !filename || !getToken?.()) return null;
  const res = await api(`/api/projects/${projectId}/xr-capture-ready`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      kind: kind === "video" ? "video" : "screenshot",
      filename,
      url,
      mode_label: modeLabel || currentXrCaptureModeLabel(),
      source_client_id: String(xrClientId() || "").slice(0, 64),
      share_x: !!shareX,
    }),
  });
  return res?.capture || null;
}

async function ackXrCapture(captureId) {
  if (!captureId || !getToken?.()) return;
  try {
    await api(`/api/me/xr-captures/${encodeURIComponent(captureId)}/ack`, { method: "POST" });
  } catch (_) { }
}

async function downloadXrCaptureBlob(msg = {}) {
  const pid = msg.project_id;
  const name = String(msg.filename || "").replace(/^.*\//, "");
  const candidates = [];
  if (msg.url) candidates.push(msg.url);
  if (pid && name) {
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(name)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`Screen Recordings/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`Screenshots/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`recordings/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`AR/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`references/Screen Recordings/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`references/Screenshots/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`references/recordings/${name}`)}`);
    candidates.push(`/api/projects/${pid}/files/${encodeURIComponent(`references/AR/${name}`)}`);
  }
  let lastErr = null;
  for (const url of candidates) {
    try {
      const res = await rawFetch(url);
      if (!res.ok) {
        lastErr = new Error(`Could not download capture (${res.status})`);
        continue;
      }
      return { blob: await res.blob(), url };
    } catch (err) {
      lastErr = err;
    }
  }
  throw lastErr || new Error("Could not download capture");
}

const handledXrPromptIds = new Set();

function applyLaptopXrPromptBridge(msg) {
  const already = msg?.id && handledXrPromptIds.has(msg.id);
  if (msg?.id) handledXrPromptIds.add(msg.id);
  if (already) return { ok: true, duplicate: true };
  try { showAiComposePanel(); } catch (_) { }
  const result = applyPromptBridgeOnLaptop(msg, {
    setPromptText: (text) => composer?.setPromptText?.(text),
    attachImage: (img) => {
      if (!img?.imageDataUrl) return;
      promptImages.push({
        id: img.id || `xr-${Date.now()}`,
        name: img.name || "VR sketch",
        data_url: img.imageDataUrl,
        promptAugment: img.promptAugment || "",
      });
      try { renderPromptImages?.(); } catch (_) { }
    },
    onStatus: (kind, message) => setEditStatus?.(kind === "error" ? "error" : "ok", message),
  });
  if (msg?.id && getToken?.()) {
    void api(`/api/me/xr-prompt-bridge/${encodeURIComponent(msg.id)}/ack`, { method: "POST" }).catch(() => { });
  }
  return result;
}

async function openRemoteXrCaptureShare(msg = {}) {
  const id = msg.id || `${msg.project_id}:${msg.filename}`;
  if (!id || handledXrCaptureIds.has(id)) return;
  handledXrCaptureIds.add(id);
  const kind = msg.kind === "video" ? "video" : "screenshot";
  const mode = msg.mode_label || msg.modeLabel || "AR";
  if (!msg.url && !(msg.project_id && msg.filename)) {
    handledXrCaptureIds.delete(id);
    return;
  }

  // Headset session that created it: keep local banner only; PC gets the editor
  const fromSelf = msg.source_client_id && msg.source_client_id === xrClientId();
  if (fromSelf && viewportXR?.isPresenting?.()) {
    showXrCaptureReadyBanner({ kind, modeLabel: mode });
    viewportXR?.setMenuFooterHint?.("Opened on your PC — mark up & Share to X");
    // Leave pending so the PC tab can still open + ack it.
    handledXrCaptureIds.delete(id);
    return;
  }

  // Toast immediately — don't wait on download / project switch
  showXrCaptureReadyBanner({ kind, modeLabel: mode });

  try {
    if (msg.project_id && msg.project_id !== projectId) {
      try { await openProjectById?.(msg.project_id); } catch (_) { }
    }
    const downloaded = await downloadXrCaptureBlob(msg);
    const blob = downloaded?.blob || downloaded;
    const fileRel = resolveXrCaptureFileRel(downloaded?.url || msg.url, msg.filename);
    if (kind === "video") {
      await viewportVideoRecorder?.openShareModal?.(blob);
      setEditStatus("ok", `${mode} XR video ready — mark up or Share to X.`);
    } else {
      const dataUrl = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error("Could not read screenshot"));
        reader.readAsDataURL(blob);
      });
      if (fileRel && (msg.project_id || projectId)) {
        try {
          await referenceFilesViewer?.openTab?.(fileRel, {
            projectId: msg.project_id || projectId,
            kind: "image",
            forceReload: true,
          });
        } catch (_) { }
      }
      if (screenshotMarkup?.open) {
        await screenshotMarkup.open(dataUrl, { modeLabel: `${mode} POV screenshot` });
      }
      if (msg.share_x) {
        try { await screenshotMarkup?.shareToX?.(); } catch (_) { }
      }
      setEditStatus("ok", `${mode} XR screenshot ready — mark up or Share to X.`);
    }
    await ackXrCapture(msg.id);
  } catch (err) {
    console.warn("[xr] open remote capture failed", err);
    handledXrCaptureIds.delete(id);
    setEditStatus("error", err?.message || "Could not open XR capture on this PC.");
  }
}

async function flushPendingRemoteXrCaptures() {
  if (!getToken?.()) return;
  try {
    const data = await api("/api/me/xr-captures/pending");
    const items = data?.captures || [];
    for (const item of items) {
      // Prefer opening on non-XR windows
      if (viewportXR?.isPresenting?.()) continue;
      await openRemoteXrCaptureShare(item);
    }
  } catch (err) {
    console.warn("[xr] pending captures poll failed", err);
  }
}

async function captureXrScreenshotForShare({ openDesktopNow = true, shareX = false } = {}) {
  try {
    const presentingNow = !!viewportXR?.isPresenting?.();
    let dataUrl = null;
    if (presentingNow) {
      void shouldCaptureXrFramebufferOnSelectTick();
      await new Promise((resolve) => setTimeout(resolve, xrRecordStartDeferMs()));
      try {
        const canvas = viewportXR?.paintRecordOverlayCanvas?.(undefined, undefined, { force: true, still: true });
        if (canvas?.toDataURL) dataUrl = canvas.toDataURL(xrScreenshotMimeType());
      } catch (_) { }
      if (!viewportVideoRecorder?.isRecording?.()) {
        try { viewportXR?.disposeRecordSpectator?.(); } catch (_) { }
      }
    } else if (shouldCaptureWebglFramebufferOnXrMenu({ presenting: presentingNow })) {
      try { dataUrl = renderer?.domElement?.toDataURL?.("image/png") || null; } catch { dataUrl = null; }
    }
    if (!dataUrl) {
      if (presentingNow) {
        setEditStatus("error", "Could not capture headset POV. Try Record for a clip.");
        return;
      }
      await downloadViewportScreenshot({ forceMode: "viewport", openShare: true });
      if (shareX) {
        try { await screenshotMarkup?.shareToX?.(); } catch (_) { }
      }
      return;
    }
    pendingXrScreenshotUrl = dataUrl;
    pendingXrCaptureMode = currentXrCaptureModeLabel();
    let saved = null;
    try {
      const blob = await dataUrlToBlob(dataUrl);
      saved = await saveXrCaptureToReferences(blob, { kind: "screenshot", modeLabel: pendingXrCaptureMode, shareX });
    } catch (err) {
      console.warn("[xr] immediate reference save failed", err);
    }
    const inXr = !!viewportXR?.isPresenting?.();
    // In XR: publish to PC only — don't open markup on the headset.
    if (inXr) {
      showXrCaptureReadyBanner({ kind: "screenshot", modeLabel: pendingXrCaptureMode });
      viewportXR?.setMenuFooterHint?.(
        saved
          ? "Screenshot saved — markup opening on your PC"
          : "Screenshot captured — save failed; try again",
      );
      setEditStatus(
        saved ? "ok" : "error",
        saved
          ? `${pendingXrCaptureMode} screenshot saved — opening on your PC.`
          : "Could not save screenshot to Reference Files → AR.",
      );
      return;
    }
    if (openDesktopNow) {
      try {
        if (saved?.filename) {
          await referenceFilesViewer?.openTab?.(saved.filename, { projectId, kind: "image" });
        }
        if (screenshotMarkup?.open) {
          await screenshotMarkup.open(dataUrl, { modeLabel: `${pendingXrCaptureMode} POV screenshot` });
        }
        if (shareX) {
          try { await screenshotMarkup?.shareToX?.(); } catch (_) { }
        }
        showXrCaptureReadyBanner({ kind: "screenshot", modeLabel: pendingXrCaptureMode });
        setEditStatus("ok", `${pendingXrCaptureMode} screenshot open — mark up or Share to X.`);
        return;
      } catch (err) {
        console.warn("[xr] desktop screenshot open failed", err);
      }
    }
    setEditStatus("ok", `${pendingXrCaptureMode} screenshot saved to Reference Files → AR.`);
  } catch (err) {
    setEditStatus("error", err?.message || "Could not capture VR screenshot.");
  }
}

async function flushPendingXrScreenshotShare() {
  const url = pendingXrScreenshotUrl;
  const mode = pendingXrCaptureMode || "AR";
  pendingXrScreenshotUrl = null;
  if (!url) return;
  try {
    if (screenshotMarkup?.open) {
      await screenshotMarkup.open(url, { modeLabel: `${mode} POV screenshot` });
      setEditStatus("ok", `${mode} screenshot ready — mark up or Share to X (also in AR captures).`);
    } else {
      downloadDataUrl(url, `render3d-${mode.toLowerCase()}-screenshot`);
    }
  } catch (err) {
    console.warn("[xr] pending screenshot share failed", err);
  }
}
