const GRID_VISIBLE_KEY = "render3d:gridVisible:v1";
const DEFAULT_GRID_VISIBLE = false;
let gridVisible = DEFAULT_GRID_VISIBLE;
let gridVisibleBeforeArchitect = null;
let hideGridForRecording = false;
let gridHelper = null;
let floorGridWorldSize = 0;
const SKETCH_CANVAS = 0xe8e8e8;
let savedSceneBg = null;
let gridAxesGroup = null;
let gridDotsGroup = null;

function disposeSceneObject(obj) {
  obj?.traverse?.((child) => {
    child.geometry?.dispose?.();
    if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose?.());
    else child.material?.dispose?.();
  });
}

function niceGridSize(radius) {
  const desired = Math.max(radius * 7, 10);
  const pow = 10 ** Math.floor(Math.log10(desired));
  for (const m of [1, 2, 5, 10]) {
    if (pow * m >= desired) return pow * m;
  }
  return pow * 10;
}

function makeAxisLine(points, color) {
  const geo = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, depthTest: true, depthWrite: false, transparent: true, opacity: 0.88 });
  const line = new THREE.Line(geo, mat);
  line.renderOrder = -9;
  return line;
}

function makeGridDepthAware(grid) {
  // Let object geometry occlude the grid. The slight negative offset prevents
  // floor-aligned parts from z-fighting with grid lines.
  grid.position.z = -0.002;
  grid.renderOrder = -10;
  protectFloorChrome(grid);
  const mats = Array.isArray(grid.material) ? grid.material : [grid.material];
  for (const mat of mats) {
    if (!mat) continue;
    mat.depthTest = true;
    mat.depthWrite = false;
    mat.transparent = true;
    mat.opacity = 0.62;
    mat.needsUpdate = true;
  }
}

function buildGridDots(size, step, color = 0x6a7d99) {
  const half = size / 2;
  const points = [];
  const dotStep = Math.max(step, 0.5);
  for (let x = -half; x <= half + 1e-6; x += dotStep) {
    for (let y = -half; y <= half + 1e-6; y += dotStep) {
      points.push(x, y, -0.0015);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.Float32BufferAttribute(points, 3));
  const mat = new THREE.PointsMaterial({
    color,
    size: Math.max(dotStep * 0.06, 0.02),
    sizeAttenuation: true,
    transparent: true,
    opacity: 0.34,
    depthTest: true,
    depthWrite: false,
    clippingPlanes: [],
  });
  const dots = new THREE.Points(geo, mat);
  dots.renderOrder = -11;
  dots.name = "architect-grid-dots";
  return dots;
}

function floorGridViewOpts(contentRadius = sceneRadius()) {
  const dist = camera?.position?.distanceTo?.(controls?.target);
  let hasContent = contentRadius > 1.25;
  try { hasContent = (projectAssembly?.count?.() || 0) > 0; } catch (_) { }
  return {
    sceneRadius: contentRadius,
    hasContent,
    cameraPosition: camera?.position || { x: 0, y: 0, z: 4 },
    fovDeg: camera?.fov || 50,
    aspect: camera?.aspect || 1,
    far: camera?.far || 100,
    orbitDist: Number.isFinite(dist) && dist > 0 ? dist : 8,
  };
}

function visibleFloorGridRadius() {
  return floorGridHalfExtent(floorGridViewOpts());
}

function rebuildGrid() {
  if (gridHelper) {
    scene.remove(gridHelper);
    disposeSceneObject(gridHelper);
  }
  if (gridAxesGroup) {
    scene.remove(gridAxesGroup);
    disposeSceneObject(gridAxesGroup);
  }
  if (gridDotsGroup) {
    scene.remove(gridDotsGroup);
    disposeSceneObject(gridDotsGroup);
  }

  const size = floorGridSize(floorGridViewOpts());
  floorGridWorldSize = size;
  try { renderer?.domElement && (renderer.domElement.dataset.floorGrid = String(Math.round(size))); } catch (_) { }
  const orbit = floorGridViewOpts().orbitDist;
  const targetCell = Math.max(orbit / 30, size / 400, 0.25);
  const divisions = Math.min(400, Math.max(80, Math.round(size / targetCell)));
  const themeColors = currentThemeSceneColors();
  gridHelper = new THREE.GridHelper(size, divisions, themeColors.gridMajor, themeColors.gridMinor);
  gridHelper.rotation.x = Math.PI / 2;
  makeGridDepthAware(gridHelper);
  try { gridHelper.userData.xrDesktopChrome = true; } catch (_) { }
  scene.add(gridHelper);

  gridAxesGroup = new THREE.Group();
  gridAxesGroup.name = "large-grid-axes";
  try { gridAxesGroup.userData.xrDesktopChrome = true; } catch (_) { }
  const half = size / 2;
  gridAxesGroup.add(makeAxisLine([new THREE.Vector3(-half, 0, -0.001), new THREE.Vector3(half, 0, -0.001)], 0xff4d4f));
  gridAxesGroup.add(makeAxisLine([new THREE.Vector3(0, -half, -0.001), new THREE.Vector3(0, half, -0.001)], 0x3fb950));
  protectFloorChrome(gridAxesGroup);
  scene.add(gridAxesGroup);

  const dotStep = Math.max(size / 70, size >= 100 ? 5 : 0.5);
  gridDotsGroup = buildGridDots(size, dotStep, themeColors.gridMinor);
  protectFloorChrome(gridDotsGroup);
  try { gridDotsGroup.userData.xrDesktopChrome = true; } catch (_) { }
  scene.add(gridDotsGroup);
  applyGridVisibility();
}

function isImmersiveXrActive() {
  try {
    if (document.body.classList.contains("xr-presenting")) return true;
    if (typeof viewportXR !== "undefined" && viewportXR?.isPresenting?.()) return true;
  } catch (_) { }
  return false;
}

function applyGridVisibility() {
  // Desktop floor grid is CAD-scale (often huge in meters). Never show it in XR.
  const show = !!gridVisible && !hideGridForRecording && !isImmersiveXrActive();
  if (gridHelper) gridHelper.visible = show;
  if (gridAxesGroup) gridAxesGroup.visible = show;
  if (gridDotsGroup) gridDotsGroup.visible = show;
}

function gridPrefStorageKey(pid = projectId) {
  return pid ? `${GRID_VISIBLE_KEY}:${pid}` : null;
}

function readNewProjectGridVisible() {
  try {
    const raw = localStorage.getItem(LS_NEW_PROJECT_GRID_VISIBLE);
    if (raw === "0") return false;
    if (raw === "1") return true;
  } catch {
    /* local storage is best-effort */
  }
  return true;
}

function syncNewProjectGridPrefControls() {
  const on = readNewProjectGridVisible();
  for (const id of ["pref-new-project-grid", "viewport-new-project-grid"]) {
    const el = document.getElementById(id);
    if (el) el.checked = on;
  }
}

function writeNewProjectGridVisible(on) {
  try {
    localStorage.setItem(LS_NEW_PROJECT_GRID_VISIBLE, on ? "1" : "0");
  } catch {
    /* local storage is best-effort */
  }
  syncNewProjectGridPrefControls();
  return !!on;
}

function setNewProjectGridVisible(on, { announce = true } = {}) {
  const next = writeNewProjectGridVisible(on);
  syncNewProjectGridPrefControls();
  if (announce) {
    setEditStatus("ok", next
      ? "New projects will start with the grid visible."
      : "New projects will start with the grid hidden.");
  }
  return next;
}

function readProjectGridVisible(pid = projectId) {
  const key = gridPrefStorageKey(pid);
  if (!key) return readNewProjectGridVisible();
  try {
    const raw = localStorage.getItem(key);
    if (raw === "1") return true;
    if (raw === "0") return false;
  } catch {
    /* local storage is best-effort */
  }
  return readNewProjectGridVisible();
}

function persistProjectGridVisible(visible, pid = projectId) {
  if (!pid || newProjectPending) return;
  const key = gridPrefStorageKey(pid);
  if (!key) return;
  try {
    localStorage.setItem(key, visible ? "1" : "0");
  } catch {
    /* local storage is best-effort */
  }
}

function applyProjectGridPreference(pid = projectId) {
  setGridVisible(readProjectGridVisible(pid), { persist: false });
}

function setGridVisible(visible, { persist = false } = {}) {
  gridVisible = !!visible;
  applyGridVisibility();
  syncGridToggleButtons();
  if (persist) persistProjectGridVisible(gridVisible);
  const overlayGrid = document.getElementById("viewport-look-grid");
  if (overlayGrid) overlayGrid.checked = !!gridVisible;
  const prefGrid = document.getElementById("pref-grid-visible");
  if (prefGrid) prefGrid.checked = !!gridVisible;
}

function syncGridToggleButtons() {
  for (const id of ["btn-grid"]) {
    const el = document.getElementById(id);
    if (!el) continue;
    el.classList.toggle("active", gridVisible);
    el.setAttribute("aria-pressed", gridVisible ? "true" : "false");
  }
}

function toggleGrid() {
  setGridVisible(!gridVisible, { persist: true });
}

function applyViewportSceneBackground() {
  if (savedSceneBg != null) return;
  if (viewportSceneLook !== "light") {
    syncViewportLookBackground(scene);
    return;
  }
  const hex = currentThemeSceneColors().canvas;
  if (scene.background?.isColor && typeof scene.background.setHex === "function") {
    scene.background.setHex(hex);
  } else {
    scene.background = new THREE.Color(hex);
  }
}

function syncGridSceneMenuUi() {
  const menu = document.getElementById("viewport-grid-menu");
  menu?.querySelectorAll("[data-viewport-scene]").forEach((btn) => {
    const active = btn.dataset.viewportScene === viewportSceneLook;
    btn.classList.toggle("active", active);
    btn.setAttribute("aria-checked", String(active));
  });
  syncNewProjectGridPrefControls();
}

function defaultGridMenuBounds() {
  const btn = document.getElementById("btn-grid-options") || document.getElementById("btn-grid");
  const r = btn?.getBoundingClientRect();
  const w = 280;
  const h = 360;
  const x = r ? Math.max(8, r.right - w) : 24;
  const y = r ? r.bottom + 8 : 80;
  return { x, y, w, h };
}

function ensureGridSceneWindow() {
  const menu = document.getElementById("viewport-grid-menu");
  if (!menu) return null;
  attachStudioFloatWindow(menu, {
    title: "Grid",
    storageKey: GRID_WINDOW_BOUNDS_KEY,
    defaultBounds: defaultGridMenuBounds,
    minW: 248,
    minH: 200,
    closeTitle: "Close",
    closeLabel: "Close grid panel",
    onClose: closeGridSceneMenu,
    reparentTo: document.body,
  });
  return menu;
}

function closeGridSceneMenu() {
  const menu = document.getElementById("viewport-grid-menu");
  if (menu?.dataset.studioFloat === "1") {
    try { attachStudioFloatWindow(menu)?.save?.(); } catch { /* ignore */ }
  }
  menu?.classList.add("hidden");
  document.getElementById("btn-grid-options")?.setAttribute("aria-expanded", "false");
}

function toggleGridSceneMenu() {
  const menu = document.getElementById("viewport-grid-menu");
  const btn = document.getElementById("btn-grid-options");
  if (!menu || !btn) return;
  const open = menu.classList.contains("hidden");
  closeTransparentModeMenu();
  closeExplodedModeMenu();
  closeViewportLookOverlay();
  if (open) {
    ensureGridSceneWindow();
    if (!hasSavedFloatBounds(GRID_WINDOW_BOUNDS_KEY)) {
      attachStudioFloatWindow(menu)?.applyBounds?.(defaultGridMenuBounds());
    }
    syncGridSceneMenuUi();
  }
  menu.classList.toggle("hidden", !open);
  btn.setAttribute("aria-expanded", String(open));
}

function setViewportSceneLook(look, { persist = true, rebuild = true, announce = true } = {}) {
  viewportSceneLook = normalizedViewportSceneLook(look);
  if (viewportSceneLook === "dark" && viewportShadingMode === "lookdev") {
    setViewportShadingMode("lookdev");
  } else {
    applyViewportSceneBackground();
  }
  if (rebuild) rebuildGrid();
  syncGridSceneMenuUi();
  if (persist) {
    try {
      localStorage.setItem(VIEWPORT_SCENE_LOOK_KEY, viewportSceneLook);
    } catch {
      /* local storage is best-effort */
    }
  }
  if (announce) {
    setEditStatus(
      "ok",
      viewportSceneLook === "light"
        ? "Light viewport scene — Jake CAD lighting still applies."
        : "Dark viewport scene.",
    );
  }
}

