let collab;

function composeDraftPid(pid = projectId) {
  return String(pid || readLastProjectId() || "").trim() || null;
}

function liveComposePromptText() {
  try {
    return String(composer?.getRawPromptText?.() || document.getElementById("prompt-input")?.value || "");
  } catch {
    return "";
  }
}

function projectPromptStateKey(pid = projectId) {
  const id = composeDraftPid(pid);
  return id ? `${id}:__project_draft` : null;
}

function modelStateKey(filename = selectedFile, pid = projectId) {
  const id = composeDraftPid(pid);
  return id && filename ? `${id}:${filename}` : projectPromptStateKey(pid);
}

function storedComposePromptForProject(pid, filename = selectedFile) {
  const id = String(pid || "").trim();
  if (!id) return "";
  const states = readModelPromptState();
  const key = filename ? `${id}:${filename}` : null;
  const projectKey = `${id}:__project_draft`;
  const candidates = [key ? states[key] : null, states[projectKey]].filter((c) => {
    if (!c) return false;
    if (c.project_id && c.project_id !== id) return false;
    return true;
  });
  candidates.sort((a, b) => Number(b.updated_at || 0) - Number(a.updated_at || 0));
  for (const c of candidates) {
    if (String(c?.prompt || "").trim()) return c.prompt;
  }
  return "";
}

function readModelPromptState() {
  try {
    return JSON.parse(localStorage.getItem(LS_MODEL_PROMPT_STATE) || "{}");
  } catch {
    return {};
  }
}

function writeModelPromptState(state) {
  try {
    localStorage.setItem(LS_MODEL_PROMPT_STATE, JSON.stringify(state));
  } catch (_) { }
}

function readGlobalComposeDraft() {
  try {
    return JSON.parse(localStorage.getItem(LS_COMPOSE_DRAFT) || "null");
  } catch {
    return null;
  }
}

function clearGlobalComposeDraft() {
  for (const key of LEAKED_GLOBAL_COMPOSE_KEYS) {
    try { localStorage.removeItem(key); } catch (_) { /* ignore */ }
  }
}

function currentComposeSnapshot() {
  return {
    prompt: composer?.getRawPromptText?.() || "",
    references: composer?.getReferences?.() || [],
    images: (promptImages || []).map((img) => ({
      id: img.id,
      name: img.name,
      media_type: img.media_type,
      stored_name: img.stored_name || undefined,
      url: img.url || undefined,
      // Keep a small data URL for instant restore; huge photos live on the server.
      data_url: promptImageHasBytes(img) && String(img.data_url).length < 220000
        ? img.data_url
        : undefined,
    })),
    project_id: projectId || null,
    filename: selectedFile || null,
    promptMode: resolveCadPromptMode(promptMode),
    cadEngine: getPromptCadEngine(),
    cadRigging: !!cadComposeRigging,
    updated_at: Date.now(),
  };
}

function saveActiveModelPromptState({ forceEmpty = false } = {}) {
  if (!composer || restoringModelPromptState || promptDraftSwitchLock) return;
  const snapshot = currentComposeSnapshot();
  // Drafts are per-project only — never write a global draft that leaks into
  // every prompt box across projects. Writes use the live projectId only
  // (not lastProjectId) so boot/switch cannot stamp the old textarea onto
  // the next project.
  clearGlobalComposeDraft();
  const pid = String(projectId || "").trim();
  if (!pid) return;
  snapshot.project_id = pid;
  const key = modelStateKey(selectedFile, pid);
  const projectKey = projectPromptStateKey(pid);
  if (!key && !projectKey) return;
  const state = readModelPromptState();
  const existing = (key && state[key]) || (projectKey && state[projectKey]) || null;
  if (!shouldPersistComposeSnapshot(snapshot, existing, {
    forceEmpty,
    protectExisting: restoringModelPromptState || promptDraftSwitchLock,
  })) return;
  if (key) state[key] = snapshot;
  if (projectKey) state[projectKey] = snapshot;
  writeModelPromptState(state);
}

/** Wipe the compose UI without touching localStorage (used during project switch). */
function clearComposeUiOnly() {
  if (!composer) return;
  restoringModelPromptState = true;
  try {
    composer.setPromptText?.("");
    composer.replaceReferences?.([]);
    resetRefCounter();
    promptImages = [];
    renderPromptImages();
  } finally {
    restoringModelPromptState = false;
  }
}

/** Clear the compose box + persisted draft for the open project (after submit). */
function clearActiveProjectPromptDraft({ clearUi = true } = {}) {
  if (clearUi && composer) {
    restoringModelPromptState = true;
    try {
      composer.setPromptText?.("");
      composer.replaceReferences?.([]);
      resetRefCounter();
      promptImages = [];
      renderPromptImages();
    } finally {
      restoringModelPromptState = false;
    }
    sendCollabPresence?.();
  }
  clearGlobalComposeDraft();
  const pid = composeDraftPid();
  if (!pid) return;
  const state = readModelPromptState();
  const key = modelStateKey(selectedFile, pid);
  const projectKey = projectPromptStateKey(pid);
  if (key) delete state[key];
  if (projectKey) delete state[projectKey];
  const prefix = `${pid}:`;
  for (const k of Object.keys(state)) {
    if (k === pid || k.startsWith(prefix)) delete state[k];
  }
  writeModelPromptState(state);
}

// The composer renders synchronously, before selection tools and canvas state exist.
// Enable the shared catalog after this module finishes initializing.
let promptMentionablesReady = false;
queueMicrotask(() => { promptMentionablesReady = true; });

const composer = createPromptComposer({
  getProjectId: () => projectId,
  textarea: document.getElementById("prompt-input"),
  chipsEl: document.getElementById("ref-chips"),
  inlineChipsEl: document.getElementById("prompt-inline-ref-chips"),
  refsListEl: document.getElementById("ref-list"),
  getMentionables: getPromptMentionables,
  resolveClipboardPaste: (text, clipboardData) => resolvePromptLinkPaste(text, clipboardData),
  onMentionActivate: (ref) => {
    const id = ref?.canvas_element_id || ref?.elementId;
    if (!id) return false;
    return canvasModeInstance?.selectElement?.(id) === true;
  },
  onStatus: (kind, text) => {
    const el = document.getElementById("prompt-status");
    if (el && text) {
      el.className = `status ${kind || "ok"}`;
      el.textContent = text;
    }
  },
  onUnlinkMentionable: (ref) => {
    if (ref?.type === "image" && ref.id) {
      const before = promptImages.length;
      promptImages = promptImages.filter((img) => `image:${img.id}` !== ref.id && img.id !== ref.id);
      if (promptImages.length !== before) renderPromptImages();
    }
    if ((ref?.type === "document" || ref?.type === "spec") && ref.filename) {
      const source = String(ref.filename);
      const before = promptImages.length;
      promptImages = promptImages.filter((img) => String(img.source_filename || "") !== source);
      if (promptImages.length !== before) renderPromptImages();
    }
  },
  onReferencesChange: (refs) => {
    window.dispatchEvent(new CustomEvent("render3d:prompt-references-changed", { detail: { references: refs } }));
    if (activeHeyAiContext?.live && !refs.some((ref) => ref?.id === activeHeyAiContext.id)) {
      void finalizeHeyAiContext({ stopVoice: true, removed: true });
      activeHeyAiContext = null;
    }
    if (!restoringModelPromptState) saveActiveModelPromptState();
    sendCollabPresence();
    meshCleanup?.refresh?.();
    if (!measureModeActive) refreshSelectionMeasureOverlay();
  },
});

/** Wiring AI Prompt 2.0 composer — mounted later onto #wiring-prompt-input. */
let wiringComposer = null;

function collapsePromptEnginePopupsOnCompose() {
  if (promptMode === "v2") setPromptCadEngineOpen(false);
  if (promptMode === "mesh") setPromptMeshEngineOpen(false);
}
composer?.editor?.addEventListener?.("focus", collapsePromptEnginePopupsOnCompose);
composer?.editor?.addEventListener?.("input", collapsePromptEnginePopupsOnCompose);
composer?.editor?.addEventListener?.("keydown", collapsePromptEnginePopupsOnCompose);

function flattenBrowserEntries(entries) {
  const out = [];
  const walk = (list) => {
    for (const entry of list || []) {
      if (!entry) continue;
      if (entry.virtual_folder) {
        walk(entry.children);
        continue;
      }
      if (entry.name || entry.filename || entry.viewer_filename) out.push(entry);
      if (entry.children?.length) walk(entry.children);
      if (entry.hardware?.length) walk(entry.hardware);
    }
  };
  walk(entries);
  return out;
}

function mentionTypeForFilename(name = "", fallback = "component") {
  const n = String(name || "");
  if (isDxfDrawingFilename(n)) return "dxf";
  if (isReferenceFilename(n)) {
    if (/\.(png|jpe?g|webp|gif|bmp|svg|tiff?|webm|mp4|mov|m4v)$/i.test(n)) return "image";
    return "document";
  }
  return fallback;
}

function getPromptMentionables() {
  if (!promptMentionablesReady) return [];
  const items = [];
  const seenIds = new Set();
  const seenTokens = new Set();
  const pushItem = (item) => {
    if (!item?.id) return;
    if (seenIds.has(item.id)) return;
    let token = String(item.token || "").trim();
    if (!token) return;
    if (seenTokens.has(token)) {
      let n = 2;
      while (seenTokens.has(`${token}-${n}`)) n += 1;
      token = `${token}-${n}`;
      item = { ...item, token };
      if (item.ref) item.ref = { ...item.ref, token };
    }
    seenIds.add(item.id);
    seenTokens.add(token);
    items.push({ ...item, token });
  };
  const pushRef = (ref, detail = "") => {
    if (!ref?.id || !ref?.token) return;
    pushItem({
      id: ref.id,
      token: ref.token,
      label: ref.label || ref.stem || ref.filename || ref.token,
      detail: detail || ref.filename || ref.type,
      type: ref.type,
      filename: ref.filename,
      stem: ref.stem,
      format: ref.format,
      viewer_filename: ref.viewer_filename,
      projectId: ref.projectId,
      url: ref.url,
      ref,
    });
  };
  const pushFileEntry = (entry, detail, typeHint) => {
    const board = canvasBoardReference(entry);
    const filename = board?.filename || String(entry?.filename || entry?.viewer_filename || entry?.name || "").trim();
    if (!filename || isInternalCadSidecar(filename)) return;
    const type = board ? "sketch" : typeHint || mentionTypeForFilename(filename, "component");
    const stem = board?.name || entry.stem || fileStem(filename);
    const ref = {
      id: `${type}:${projectId || "project"}:${filename}`,
      type,
      token: compactComponentToken(stem || filename),
      label: entry.label || entry.component_name || stem || filename,
      filename,
      stem,
      format: entry.format || (filename.includes(".") ? filename.slice(filename.lastIndexOf(".") + 1).toLowerCase() : undefined),
      viewer_filename: entry.viewer_filename || filename,
      projectId,
    };
    pushRef(ref, detail);
  };

  const selected = objectTools?.getSelection?.();
  if (selected?.catalogName || selected?.root || selected?.mesh) {
    const catalogName = selected.catalogName || selected.root?.userData?.catalogFilename || selectedFile || "";
    const baseStem = String(catalogName || selected.label || "selection").replace(/\.[^.]+$/, "");
    const bodyLabel = selected.label || (Number.isInteger(selected.bodyIndex) ? `Body ${selected.bodyIndex + 1}` : "Selected object");
    const bodyToken = compactComponentToken(bodyLabel || baseStem || "selected");
    pushRef({
      id: `selection:${projectId || "project"}:${catalogName || "model"}:${selected.bodyIndex ?? 0}`,
      type: "component",
      token: bodyToken,
      label: bodyLabel,
      filename: catalogName || selectedFile || undefined,
      stem: baseStem || bodyLabel,
      projectId,
      body_index: selected.bodyIndex,
    }, "selected object/body");
    pushRef({
      id: `selection-current:${projectId || "project"}`,
      type: "component",
      token: "@selected",
      label: bodyLabel,
      filename: catalogName || selectedFile || undefined,
      stem: baseStem || bodyLabel,
      projectId,
      body_index: selected.bodyIndex,
    }, "current selection");
    if (selected.faceIndex != null) {
      const faceLabel = `Face ${Number(selected.faceIndex) + 1}${baseStem ? ` on ${baseStem}` : ""}`;
      pushRef({
        id: `face:${projectId || "project"}:${catalogName || selected.mesh?.uuid || "model"}:${selected.faceIndex}`,
        type: "face",
        token: "@face",
        label: faceLabel,
        filename: catalogName || selectedFile || undefined,
        stem: baseStem,
        projectId,
        face_index: selected.faceIndex,
        mesh_uuid: selected.mesh?.uuid,
      }, "selected face");
    }
  }

  for (const [name, obj] of projectAssembly?.list?.() || []) {
    const ref = componentPromptReference({
      filename: name,
      stem: fileStem(name),
      label: obj?.name || fileStem(name),
      viewer_filename: obj?.userData?.viewerFilename || name,
      projectId,
    });
    pushRef(ref, obj?.visible === false ? "imported object (hidden)" : "imported object");

    const meshes = listObjectMeshes(obj).slice(0, 24);
    meshes.forEach((mesh, index) => {
      const rawLabel = mesh.name?.trim() || mesh.userData?.name || `Body ${index + 1}`;
      if (!rawLabel || rawLabel === obj?.name || rawLabel === name) return;
      const stem = `${fileStem(name)}-${String(rawLabel).replace(/[^a-zA-Z0-9_-]+/g, "-")}`;
      pushRef({
        id: `component-body:${projectId || "project"}:${name}:${index}`,
        type: "component",
        token: compactComponentToken(stem),
        label: rawLabel,
        filename: name,
        stem,
        viewer_filename: name,
        projectId,
        body_index: index,
      }, `body in ${name}`);
    });
  }

  for (const file of lastProjectFiles || []) {
    const name = String(file?.name || "");
    if (!name || isInternalCadSidecar(name) || isRobotArtifactFilename(name)) continue;
    if (!isViewportImportFile(name) && !isReferenceFilename(name) && !isDxfDrawingFilename(name)) continue;
    const ref = componentPromptReference({
      filename: name,
      stem: fileStem(name),
      format: name.includes(".") ? name.slice(name.lastIndexOf(".") + 1).toLowerCase() : undefined,
      viewer_filename: file.viewer_filename || name,
      projectId,
    });
    pushRef(ref, isReferenceFilename(name) ? "reference file" : "project file");
  }

  const browser = lastProjectBrowser || {};
  for (const entry of flattenBrowserEntries(browser.components)) {
    pushFileEntry(entry, entry.visible === false ? "component (hidden)" : "component", "component");
  }
  for (const entry of flattenBrowserEntries(browser.bodies)) {
    pushFileEntry(entry, "component", "component");
  }
  for (const entry of flattenBrowserEntries(browser.references)) {
    pushFileEntry(entry, "reference file", mentionTypeForFilename(entry.name || entry.filename, "document"));
  }
  for (const entry of flattenBrowserEntries(browser.drawings)) {
    pushFileEntry(entry, "drawing", "dxf");
  }
  for (const entry of flattenBrowserEntries(browser.sketches)) {
    pushFileEntry(entry, "sketch", "sketch");
  }
  for (const entry of flattenBrowserEntries(browser.wiring)) {
    pushFileEntry(entry, "wiring", "wiring");
  }

  for (const ref of composer.getReferences?.() || []) {
    if (!["component", "sketch", "wiring", "dxf", "document", "image", "face", "edge", "corner", "lasso", "path", "url", "link", "box", "line", "arrow", "view", "split"].includes(ref.type)) continue;
    pushRef({
      ...ref,
      token: ref.token || compactComponentToken(ref.stem || ref.label || ref.filename || "file"),
    }, ref.filename || ref.type);
  }

  const canvasState = canvasModeInstance?.exportState?.();
  for (const item of collectCanvasNodeMentions(canvasState?.elements, {
    projectId: projectId || "project",
    boardName: canvasModeInstance?.getTitle?.() || canvasStoreName || "Canvas",
  })) {
    pushItem({
      ...item,
      ref: {
        id: item.id,
        type: item.type || "image",
        token: item.token,
        label: item.label,
        filename: item.filename,
        stem: item.stem,
        projectId,
        canvas_element_id: item.elementId,
        canvas_board: item.boardName,
        data_url: item.dataUrl,
        source_filename: item.filename ? `references/Canvas/${item.boardName}/${item.filename}` : "",
        hash: !!item.hash,
      },
    });
  }

  for (const img of promptImages || []) {
    const stem = String(img.name || "image").replace(/\.[^.]+$/, "");
    const token = compactComponentToken(stem);
    pushItem({
      id: `image:${img.id}`,
      token,
      label: stem,
      detail: img.name || "image",
      type: "image",
      filename: img.name,
      stem,
      ref: {
        id: `image:${img.id}`,
        type: "image",
        token,
        label: stem,
        filename: img.name,
        stem,
      },
    });
  }

  return items;
}

function isExplorerPromptRef(ref) {
  return (
    ref?.type === "component" ||
    ref?.type === "sketch" ||
    ref?.type === "wiring" ||
    ref?.type === "dxf" ||
    ref?.type === "document" ||
    ref?.type === "spec" ||
    ref?.type === "url" ||
    ref?.type === "link"
  );
}

function dedupeRefsById(refs = []) {
  const out = [];
  const seen = new Set();
  for (const ref of refs) {
    if (!ref?.id || seen.has(ref.id)) continue;
    seen.add(ref.id);
    out.push(ref);
  }
  return out;
}

function mergePromptReferenceSnapshots(modelState, projectState, globalState) {
  // Prefer model → project only. Ignore cross-project global drafts.
  const candidates = [modelState, projectState, globalState].filter((c) => {
    if (!c) return false;
    if (projectId && c.project_id && c.project_id !== projectId) return false;
    return true;
  });
  candidates.sort((a, b) => Number(b.updated_at || 0) - Number(a.updated_at || 0));
  const newest = candidates[0] || null;
  let prompt = "";
  for (const c of candidates) {
    if (String(c?.prompt || "").trim()) {
      prompt = c.prompt;
      break;
    }
  }
  if (Array.isArray(newest?.references)) {
    return {
      prompt,
      references: dedupeRefsById(newest.references),
      images: newest?.images,
      promptMode: newest?.promptMode || null,
      cadEngine: newest?.cadEngine || null,
      cadRigging: newest?.cadRigging || false,
    };
  }
  const modelRefs = modelState?.references || [];
  const projectRefs = projectState?.references || [];
  return {
    prompt,
    references: dedupeRefsById([...modelRefs, ...projectRefs]),
    images: newest?.images,
    promptMode: newest?.promptMode || null,
    cadEngine: newest?.cadEngine || null,
    cadRigging: newest?.cadRigging || false,
  };
}

function restoreActiveModelPromptState({ allowLiveFallback = false, restoreMode = true } = {}) {
  const pid = composeDraftPid();
  const key = modelStateKey(selectedFile, pid);
  const projectKey = projectPromptStateKey(pid);
  const states = readModelPromptState();
  const modelState = key ? states[key] : null;
  const projectState = projectKey ? states[projectKey] : null;
  // Legacy global draft: restore only if tagged for this project, then delete.
  // Untagged globals leaked into every box — never migrate those.
  let globalState = null;
  const legacy = readGlobalComposeDraft();
  if (legacy && pid && legacy.project_id === pid) {
    globalState = legacy;
    const state = readModelPromptState();
    if (projectKey) state[projectKey] = { ...legacy, project_id: pid };
    if (key) state[key] = { ...legacy, project_id: pid, filename: selectedFile || legacy.filename || null };
    writeModelPromptState(state);
  }
  clearGlobalComposeDraft();
  const merged = mergePromptReferenceSnapshots(modelState, projectState, globalState);
  const live = liveComposePromptText();
  const storedPrompt = String(merged.prompt || "");
  const nextPrompt = pickComposeRestorePrompt({ stored: storedPrompt, live, allowLiveFallback });
  restoringModelPromptState = true;
  resetRefCounter();
  if (storedPrompt.trim()) {
    promptImages = Array.isArray(merged.images) ? merged.images.slice(0, 8) : [];
    composer.replaceReferences(merged.references || []);
  } else if (!allowLiveFallback) {
    promptImages = Array.isArray(merged.images) ? merged.images.slice(0, 8) : [];
    composer.replaceReferences(merged.references || []);
  } else if (Array.isArray(merged.images) && merged.images.length) {
    promptImages = merged.images.slice(0, 8);
  }
  if (!allowLiveFallback || String(nextPrompt) !== live) {
    composer.setPromptText(nextPrompt);
  }
  restoreReferenceMarkers((merged.references || []).filter((ref) => !isExplorerPromptRef(ref)), {
    meshRoot: currentMesh,
    meshCenterOffset,
  });
  if (restoreMode) {
    cadComposeRigging = !!merged.cadRigging;
    // Restore Mode 2.0 engine (Jake vs VibeCAD) + prompt mode with the draft.
    const modeSnap = merged.promptMode || modelState?.promptMode || projectState?.promptMode || globalState?.promptMode;
    const engineSnap = merged.cadEngine || modelState?.cadEngine || projectState?.cadEngine || globalState?.cadEngine;
    if (engineSnap === "vibecad" || engineSnap === "jake" || engineSnap === "mac") {
      try { setPromptCadEngine(engineSnap); } catch { /* ignore */ }
    }
    if (modeSnap) {
      try {
        const mode = promptModeForRef(modeSnap);
        if (["v2", "vibecad", "mac", "mesh", "architect", "draw", "render", "standard"].includes(mode)) {
          applyPromptModeUI(mode === "standard" ? "render" : mode);
        }
      } catch { /* ignore */ }
    }
    syncCadComposeRiggingUi();
  }
  restoringModelPromptState = false;
  sendCollabPresence();
  refreshSelectionMeasureOverlay();
  renderPromptImages();
  void hydratePromptImages().then((changed) => {
    renderPromptImages();
    if (changed && !restoringModelPromptState) saveActiveModelPromptState();
  });
}

function safeRestoreActiveModelPromptState(opts = {}) {
  try {
    restoreActiveModelPromptState(opts);
  } catch (err) {
    console.error("Could not restore AI compose draft:", err);
    restoringModelPromptState = false;
  }
}

document.getElementById("prompt-input")?.addEventListener("input", () => {
  if (!restoringModelPromptState) saveActiveModelPromptState();
});

const promptImageDrop = document.getElementById("prompt-image-drop");
const promptImageInput = document.getElementById("prompt-image-input");
const promptImageList = document.getElementById("prompt-image-list");
const promptPaneCompose = document.getElementById("prompt-pane-compose");
const promptPanel = document.querySelector(".prompt-panel");

function promptImagesFromTechnicalDrawing() {
  const refs = typeof promptReferencesForSubmit === "function" ? promptReferencesForSubmit() : [];
  const refIsDrawing = refs.some((ref) => {
    const name = String(ref?.filename || ref?.label || "").toLowerCase();
    const fmt = String(ref?.format || "").toLowerCase();
    const kind = String(ref?.type || "").toLowerCase();
    return name.endsWith(".pdf") || name.endsWith(".dxf") || fmt === "pdf" || fmt === "dxf" || kind === "pdf" || kind === "dxf";
  });
  if (refIsDrawing) return true;
  return (promptImages || []).some((img) => {
    const src = String(img.source_filename || img.parent_filename || img.name || "").toLowerCase();
    return src.endsWith(".pdf") || src.includes(".pdf") || src.endsWith(".dxf");
  });
}

function askConvertImageToDrawing() {
  // Quest AR cannot interact with desktop confirm modals — keep the photo as-is.
  if (
    promptSubmitOpts?.source === "xr"
    || document.body.classList.contains("xr-presenting")
    || viewportXR?.isPresenting?.()
  ) {
    return Promise.resolve("no");
  }
  return new Promise((resolve) => {
    const modal = document.getElementById("image-drawing-confirm-modal");
    if (!modal) {
      resolve("no");
      return;
    }
    const remember = modal.querySelector("#image-drawing-remember");
    if (remember) remember.checked = false;
    let settled = false;
    const yesBtn = modal.querySelector("#image-drawing-confirm-yes");
    const noBtn = modal.querySelector("#image-drawing-confirm-no");
    const closeEls = [...modal.querySelectorAll("[data-image-drawing-close]")];
    const setBusy = (busy) => {
      [yesBtn, noBtn, ...closeEls].forEach((el) => {
        if (!el || el.dataset.imageDrawingClose !== undefined && el.classList?.contains("auth-backdrop")) return;
        if (el.tagName === "BUTTON") el.disabled = !!busy;
      });
      if (yesBtn) yesBtn.disabled = !!busy;
      if (noBtn) noBtn.disabled = !!busy;
    };
    const finish = (value) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey);
      yesBtn?.removeEventListener("click", onYes);
      noBtn?.removeEventListener("click", onNo);
      closeEls.forEach((el) => el.removeEventListener("click", onCancel));
      setBusy(false);
      modal.classList.add("hidden");
      resolve(value);
    };
    const onYes = (e) => {
      e?.preventDefault?.();
      e?.stopPropagation?.();
      if (remember?.checked) persistDxfDontAskAgain("yes");
      setBusy(true);
      finish("yes");
    };
    const onNo = (e) => {
      e?.preventDefault?.();
      e?.stopPropagation?.();
      if (remember?.checked) persistDxfDontAskAgain("no");
      setBusy(true);
      finish("no");
    };
    const onCancel = (e) => {
      e?.preventDefault?.();
      e?.stopPropagation?.();
      finish("cancel");
    };
    const onKey = (e) => {
      if (e.key === "Escape") finish("cancel");
    };
    // Drop any stale listeners from a prior open by cloning buttons.
    yesBtn?.addEventListener("click", onYes);
    noBtn?.addEventListener("click", onNo);
    closeEls.forEach((el) => el.addEventListener("click", onCancel));
    document.addEventListener("keydown", onKey);
    setBusy(false);
    modal.classList.remove("hidden");
  });
}

const SIM_MOTION_PREF_KEY = "render3d:sim-motion-after-gen:v1";
const SIM_MOTION_PREF_VALUES = new Set(["ask", "never", "urdf", "srdf", "both"]);
const SIM_MOTION_HINT_RE =
  /\b(urdf|srdf|robot(?:ic)?|cobot|humanoid|manipulator|end[-\s]?effector|gripper|scara|delta(?:\s+robot)?|gantry(?:\s+robot)?|industrial\s+arm|6[-\s]?axis|5[-\s]?axis|4[-\s]?axis|[1-8]\s*-?\s*dof|degrees?\s+of\s+freedom|articulated|kinematic|joint(?:ed|s)?|servo|actuator|linkage|pick[-\s]?and[-\s]?place|legged|walker|hexapod|quadruped)\b/i;

function getSimMotionAfterGenPref() {
  try {
    const raw = String(localStorage.getItem(SIM_MOTION_PREF_KEY) || "ask").toLowerCase();
    return SIM_MOTION_PREF_VALUES.has(raw) ? raw : "ask";
  } catch {
    return "ask";
  }
}

function setSimMotionAfterGenPref(value, { announce = false } = {}) {
  const next = SIM_MOTION_PREF_VALUES.has(value) ? value : "ask";
  try {
    localStorage.setItem(SIM_MOTION_PREF_KEY, next);
  } catch {
    /* ignore */
  }
  if (announce) {
    const labels = {
      ask: "Ask after generating articulated models",
      never: "Never ask to generate simulated motion",
      urdf: "Always generate URDF after articulated models",
      srdf: "Always generate SRDF after articulated models",
      both: "Always generate URDF + SRDF after articulated models",
    };
    setEditStatus("ok", `${labels[next] || "Preference saved"}. Change anytime in Preferences.`);
  }
  return next;
}

function simMotionHintText(gen = {}) {
  const chunks = [
    gen.prompt,
    gen.label,
    gen.filename,
    gen.stem,
    selectedFile,
    document.getElementById("prompt-input")?.value,
  ]
    .filter(Boolean)
    .map(String);
  return chunks.join("\n");
}

function modelLooksLikeSimMotionCandidate(gen = {}) {
  if (!gen || gen.kind === "wiring") return false;
  const mode = String(gen.mode || gen.prompt_mode || "").toLowerCase();
  if (mode === "architect" || mode === "wiring") return false;
  const text = simMotionHintText(gen);
  if (!text.trim()) return false;
  // Manufacturing notes like "robot-assemblable / FANUC fixture" are CAD, not URDF robots.
  // Those used to auto-trigger URDF authoring and rewrite mm CAD constants into meters.
  const manufacturingOnly =
    /\b(robot[-\s]?assembl(?:able|y)|assembled\s+by\s+(?:a\s+)?(?:fanuc\s+)?robot|for\s+robotic\s+assembly|fanuc)\b/i.test(text)
    && !/\b(urdf|srdf|\bdof\b|end[-\s]?effector|manipulator|base_link|joint\s+limits|kinematic\s+chain|moveit)\b/i.test(text);
  if (manufacturingOnly) return false;
  return SIM_MOTION_HINT_RE.test(text);
}

function pickSimMotionPythonSource(gen = {}, artifacts = null) {
  const data = artifacts || robotArtifactData || {};
  const sources = (data.sources || []).map(String).filter((name) => /\.py$/i.test(name));
  if (!sources.length) return null;
  const stem = fileStem(gen.filename || selectedFile || "").toLowerCase();
  if (stem) {
    const matched = sources.find((name) => fileStem(name).toLowerCase() === stem);
    if (matched) return matched;
  }
  return sources[0];
}

function projectAlreadyHasSimMotion(gen = {}, artifacts = null) {
  const data = artifacts || robotArtifactData || {};
  const stem = fileStem(gen.filename || selectedFile || "").toLowerCase();
  const artifactsList = (data.artifacts || [])
    .map(String)
    .filter((name) => !/^robot\.urdf$/i.test(name.trim()));
  if (!artifactsList.length) return false;
  if (stem) {
    return artifactsList.some((name) => {
      const lower = name.toLowerCase();
      return fileStem(lower) === stem && (lower.endsWith(".urdf") || lower.endsWith(".srdf"));
    });
  }
  return artifactsList.some((name) => /\.(urdf|srdf)$/i.test(name));
}

function askGenerateSimulatedMotion({ reason = "" } = {}) {
  return new Promise((resolve) => {
    const modal = document.getElementById("sim-motion-confirm-modal");
    if (!modal) {
      resolve({ action: "skip", remember: false });
      return;
    }
    let settled = false;
    const reasonEl = modal.querySelector("#sim-motion-confirm-reason");
    const rememberEl = modal.querySelector("#sim-motion-remember");
    const bothBtn = modal.querySelector("#sim-motion-both");
    const urdfBtn = modal.querySelector("#sim-motion-urdf");
    const srdfBtn = modal.querySelector("#sim-motion-srdf");
    const skipBtn = modal.querySelector("#sim-motion-skip");
    const closeEls = [...modal.querySelectorAll("[data-sim-motion-close]")];
    if (reasonEl) reasonEl.textContent = reason || "";
    if (rememberEl) rememberEl.checked = true;
    const finish = (action) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey);
      bothBtn?.removeEventListener("click", onBoth);
      urdfBtn?.removeEventListener("click", onUrdf);
      srdfBtn?.removeEventListener("click", onSrdf);
      skipBtn?.removeEventListener("click", onSkip);
      closeEls.forEach((el) => el.removeEventListener("click", onSkip));
      modal.classList.add("hidden");
      resolve({ action, remember: !!rememberEl?.checked });
    };
    const onBoth = (e) => {
      e?.preventDefault?.();
      finish("both");
    };
    const onUrdf = (e) => {
      e?.preventDefault?.();
      finish("urdf");
    };
    const onSrdf = (e) => {
      e?.preventDefault?.();
      finish("srdf");
    };
    const onSkip = (e) => {
      e?.preventDefault?.();
      finish("skip");
    };
    const onKey = (e) => {
      if (e.key === "Escape") finish("skip");
    };
    bothBtn?.addEventListener("click", onBoth);
    urdfBtn?.addEventListener("click", onUrdf);
    srdfBtn?.addEventListener("click", onSrdf);
    skipBtn?.addEventListener("click", onSkip);
    closeEls.forEach((el) => {
      if (el === skipBtn) return;
      el.addEventListener("click", onSkip);
    });
    document.addEventListener("keydown", onKey);
    modal.classList.remove("hidden");
    requestAnimationFrame(() => bothBtn?.focus?.({ preventScroll: true }));
  });
}

async function maybeAskGenerateSimulatedMotion(gen, pid = projectId) {
  if (!gen || pid !== projectId || !projectId) return;
  if (!modelLooksLikeSimMotionCandidate(gen)) return;
  const pref = getSimMotionAfterGenPref();
  if (pref === "never") return;

  let artifacts = robotArtifactData;
  try {
    artifacts = (await refreshRobotArtifacts({ quiet: true })) || artifacts;
  } catch {
    /* ignore */
  }
  if (projectAlreadyHasSimMotion(gen, artifacts)) return;
  const source = pickSimMotionPythonSource(gen, artifacts);
  if (!source) return;

  let kind = pref;
  if (pref === "ask") {
    const match = String(simMotionHintText(gen)).match(SIM_MOTION_HINT_RE);
    const reason = match?.[0]
      ? `Detected “${match[0]}” in the prompt or filename — URDF/SRDF usually helps for motion.`
      : "This design looks jointed — URDF/SRDF usually helps for motion.";
    // In VR: ask on the retractable robot rail (right of the prompt), not a desktop modal.
    if (viewportXR?.isPresenting?.()) {
      try {
        viewportXR.openRobotRailPanel?.({
          expanded: true,
          askGenerate: true,
          reason,
          source,
        });
        viewportXR.setRobotRailStatus?.(reason);
      } catch (_) { /* optional */ }
      return;
    }
    const choice = await askGenerateSimulatedMotion({ reason });
    if (choice.action === "skip") {
      if (choice.remember) setSimMotionAfterGenPref("never", { announce: true });
      return;
    }
    kind = choice.action;
    if (choice.remember) setSimMotionAfterGenPref(kind, { announce: true });
  } else if (pref === "urdf" || pref === "srdf" || pref === "both") {
    setEditStatus(
      "ok",
      `Generating ${pref.toUpperCase()} for simulation (Preferences → Simulated motion).`
    );
  } else {
    return;
  }

  await authorJakeRobotDescription({
    source,
    kind,
    openMotion: true,
    announcePrefHint: pref === "ask",
  });
  try {
    if (viewportXR?.isPresenting?.()) {
      viewportXR.openRobotRailPanel?.({ expanded: true, askGenerate: false });
      viewportXR.setRobotRailStatus?.("URDF / SRDF ready — Play or enable Point grid");
    }
  } catch (_) { /* optional */ }
}

function promptImageDisplaySrc(img) {
  const dataUrl = String(img?.data_url || "");
  if (dataUrl.startsWith("data:image/") || dataUrl.startsWith("blob:")) return dataUrl;
  const preview = String(img?.preview_url || "");
  if (preview.startsWith("data:image/") || preview.startsWith("blob:")) return preview;
  return "";
}

function promptImageApiPayload(img) {
  if (!img) return null;
  const payload = {
    id: String(img.id || `img-${Date.now()}`),
    name: String(img.name || "image.jpg").slice(0, 160),
    media_type: String(img.media_type || "image/jpeg").toLowerCase() === "image/jpg"
      ? "image/jpeg"
      : String(img.media_type || "image/jpeg"),
    data_url: promptImageHasBytes(img) ? String(img.data_url) : "",
  };
  if (img.stored_name) payload.stored_name = String(img.stored_name);
  if (img.url && !String(img.url).includes("%2E")) payload.url = String(img.url);
  if (img.source_filename) payload.source_filename = String(img.source_filename).slice(0, 260);
  if (isCanvasReference(img)) payload.role = "canvas";
  if (img.drawing_metadata) payload.drawing_metadata = img.drawing_metadata;
  return payload;
}

function renderPromptImages() {
  if (!promptImageList) return;
  promptImageList.innerHTML = promptImages
    .map((img) => {
      const src = promptImageDisplaySrc(img);
      const thumb = src
        ? `<img src="${src}" alt="${appEscapeHtml(img.name)}" />`
        : `<div class="prompt-image-missing" title="Reloading image…">Loading…</div>`;
      return `<div class="prompt-image-card" data-id="${img.id}" role="button" tabindex="0" title="Edit this photo">
        ${thumb}
        <button type="button" class="prompt-image-remove" title="Remove image">×</button>
        <span>${appEscapeHtml(img.name)}</span>
      </div>`;
    })
    .join("");
  promptImageList.querySelectorAll(".prompt-image-remove").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = btn.closest(".prompt-image-card")?.dataset.id;
      const removed = promptImages.find((img) => img.id === id);
      promptImages = promptImages.filter((img) => img.id !== id);
      unlinkPromptDocumentChipIfOrphaned(removed?.source_filename);
      renderPromptImages();
      if (!restoringModelPromptState) saveActiveModelPromptState();
    });
  });
  promptImageList.querySelectorAll(".prompt-image-card").forEach((card) => {
    const openEditor = () => {
      const id = card.dataset.id;
      const img = promptImages.find((item) => item.id === id);
      if (img) void openPromptComposerImageEditor(img);
    };
    card.addEventListener("click", (e) => {
      if (e.target.closest(".prompt-image-remove")) return;
      openEditor();
    });
    card.addEventListener("keydown", (e) => {
      if (e.key !== "Enter" && e.key !== " ") return;
      e.preventDefault();
      openEditor();
    });
  });
  syncBlueprintVisionForImages(promptImages.length);
  skillsPromptUI.render();
  skillsPromptUI.updatePlan?.();
  if (promptImages.length > 0) {
    requestAnimationFrame(() => {
      document.getElementById("btn-prompt")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    });
  }
}

function readImageFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(reader.error || new Error("Could not read image"));
    reader.readAsDataURL(file);
  });
}

function promptImageEditedName(name, { asNew = false } = {}) {
  const raw = String(name || "image.png");
  const stem = raw.replace(/\.[^.]+$/, "") || "image";
  if (asNew) {
    const base = stem.replace(/-edited(?:-\d+)?$/i, "");
    return `${base}-edited.png`;
  }
  return /\.png$/i.test(raw) ? raw : `${stem}.png`;
}

async function applyEditedPromptImage({ dataUrl, mode, sourceId }) {
  if (!dataUrl) throw new Error("No edited image to send.");
  const mediaType = promptImageMediaTypeFromDataUrl(dataUrl, "image/png");
  const source = promptImages.find((img) => img.id === sourceId);
  if (mode === "replace") {
    if (!source) throw new Error("That prompt photo is no longer attached.");
    const next = {
      ...source,
      data_url: dataUrl,
      media_type: mediaType,
      name: promptImageEditedName(source.name),
      preview_url: "",
    };
    promptImages = promptImages.map((img) => (img.id === sourceId ? next : img));
    renderPromptImages();
    queuePromptImagePersist(next);
    if (!restoringModelPromptState) saveActiveModelPromptState();
    setEditStatus("ok", "Updated that photo on the AI prompt.");
    return;
  }
  if (promptImages.length >= 8) {
    throw new Error("The prompt already has 8 images. Remove one before attaching another.");
  }
  const attached = {
    id: `img-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    name: promptImageEditedName(source?.name || "image.png", { asNew: true }),
    media_type: mediaType,
    data_url: dataUrl,
  };
  promptImages.push(attached);
  renderPromptImages();
  queuePromptImagePersist(attached);
  if (!restoringModelPromptState) saveActiveModelPromptState();
  setEditStatus("ok", "Attached the edited photo as a new AI reference.");
}

async function openPromptComposerImageEditor(img) {
  if (!img) return;
  let source = img;
  if (!promptImageDisplaySrc(source)) {
    try {
      await hydratePromptImages({ project_id: projectId });
    } catch (_) {
      /* optional */
    }
    source = promptImages.find((item) => item.id === img.id) || img;
  }
  const src = promptImageDisplaySrc(source);
  if (!src) {
    setEditStatus("error", "That photo is still loading. Try again in a moment.");
    return;
  }
  if (!screenshotMarkup?.open) {
    setEditStatus("error", "Image editor is not available.");
    return;
  }
  await screenshotMarkup.open(src, {
    purpose: "prompt-image",
    modeLabel: source.name || "Prompt photo",
    onApply: ({ dataUrl, mode }) => applyEditedPromptImage({ dataUrl, mode, sourceId: source.id }),
  });
}

function promptImageHasBytes(img) {
  const dataUrl = String(img?.data_url || "");
  if (!dataUrl.startsWith("data:image/") || !dataUrl.includes(";base64,")) return false;
  // JS split(sep, limit) caps array length (unlike Python maxsplit). Slice the payload.
  const b64 = dataUrl.slice(dataUrl.indexOf(";base64,") + ";base64,".length);
  return Boolean(b64.trim());
}

function isPromptAttachableImageFile(file) {
  const type = String(file?.type || "").toLowerCase();
  if (type.startsWith("image/")) return true;
  return /\.(png|jpe?g|webp|gif|bmp|heic|heif)$/i.test(String(file?.name || ""));
}

function promptImageMediaTypeFromDataUrl(dataUrl, fallback = "image/png") {
  const header = String(dataUrl || "").split(";base64,", 1)[0];
  if (header.startsWith("data:image/")) {
    const mediaType = header.slice("data:".length).split(";")[0].trim().toLowerCase();
    if (mediaType === "image/jpg") return "image/jpeg";
    if (mediaType) return mediaType;
  }
  return fallback;
}

async function canvasToJpegDataUrl(src) {
  const image = await loadImageElement(src, "Could not decode image.");
  const width = image.naturalWidth || image.width || 0;
  const height = image.naturalHeight || image.height || 0;
  if (width < 1 || height < 1) throw new Error("empty image");
  const scale = Math.min(1, 2048 / Math.max(width, height));
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(width * scale));
  canvas.height = Math.max(1, Math.round(height * scale));
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Could not draw image");
  ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", 0.92);
}

async function normalizePromptImageDataUrl(dataUrl, mediaType) {
  const url = String(dataUrl || "");
  let type = String(mediaType || promptImageMediaTypeFromDataUrl(url) || "").toLowerCase();
  if (type === "image/jpg") type = "image/jpeg";
  const allowed = new Set(["image/png", "image/jpeg", "image/webp"]);
  if (promptImageHasBytes({ data_url: url }) && allowed.has(type)) {
    return { data_url: url, media_type: type };
  }
  const jpeg = await canvasToJpegDataUrl(url);
  return { data_url: jpeg, media_type: "image/jpeg" };
}

async function fileToNormalizedPromptImage(file) {
  const raw = await readImageFile(file);
  try {
    return await normalizePromptImageDataUrl(raw, file.type);
  } catch {
    if (promptImageHasBytes({ data_url: raw })) {
      let type = promptImageMediaTypeFromDataUrl(raw, file.type || "image/png");
      if (!["image/png", "image/jpeg", "image/webp"].includes(type)) type = "image/jpeg";
      return { data_url: raw, media_type: type };
    }
    throw new Error("Could not read image");
  }
}

function promptImageJpegName(name) {
  const raw = String(name || "image.jpg");
  return /\.(png|jpe?g|webp)$/i.test(raw) ? raw : raw.replace(/\.[^.]+$/, "") + ".jpg";
}

async function hydratePromptImages(entry = {}) {
  const previous = Array.isArray(promptImages) ? promptImages.slice() : [];
  const next = [];
  let changed = false;
  for (const img of previous) {
    let restored = img;
    if (!promptImageHasBytes(img)) {
      restored = await restorePromptHistoryImage(img, {
        ...entry,
        project_id: entry.project_id || projectId,
      });
      if (!restored) {
        changed = true;
        // Keep stored_name/url so CAD/Mesh/Render can hydrate from disk on generate.
        if (img?.stored_name || (img?.url && String(img.url).includes("/prompt-history/"))) {
          next.push(img);
        }
        continue;
      }
      changed = true;
    }
    try {
      const norm = await normalizePromptImageDataUrl(restored.data_url, restored.media_type);
      if (norm.data_url !== restored.data_url || norm.media_type !== restored.media_type) {
        changed = true;
      }
      next.push({ ...restored, ...norm });
    } catch {
      if (promptImageHasBytes(restored)) {
        next.push(restored);
      } else if (restored?.stored_name) {
        next.push(restored);
        changed = true;
      } else {
        changed = true;
      }
    }
  }
  promptImages = next;
  return changed || next.length !== previous.length;
}

function decodePromptImageName(value) {
  let raw = String(value || "").trim();
  for (let i = 0; i < 3; i += 1) {
    try {
      const next = decodeURIComponent(raw.replace(/\+/g, " "));
      if (next === raw) break;
      raw = next;
    } catch {
      break;
    }
  }
  const slash = raw.replace(/\\/g, "/");
  return slash.split("/").pop() || slash;
}

function promptImageFetchCandidates(img, entry = {}) {
  const storedName = decodePromptImageName(img?.stored_name || "");
  const pid = String(entry.project_id || projectId || "").trim();
  const entryId = String(entry.id || img?.prompt_id || "").trim();
  const urls = [];
  const push = (value) => {
    const clean = String(value || "").trim();
    if (!clean || clean.startsWith("data:") || clean.startsWith("blob:")) return;
    if (!urls.includes(clean)) urls.push(clean);
  };
  const dataUrl = String(img?.data_url || "").trim();
  if (dataUrl.startsWith("/api/") || /^https?:\/\//i.test(dataUrl)) push(dataUrl);
  let url = String(img?.url || "").trim();
  if (url) {
    try {
      push(decodeURI(url));
    } catch {
      push(url);
    }
    push(url.replace(/%2E/gi, "."));
  }
  if (storedName && pid) {
    const folders = [...new Set([entryId, "attached"].filter(Boolean))];
    for (const folder of folders) {
      push(`/api/projects/${pid}/prompt-history/${encodeURIComponent(folder)}/images/${encodeURIComponent(storedName)}`);
    }
  }
  return urls;
}

function withPromptImageAccessToken(path) {
  const token = getToken();
  if (!token || !path || path.startsWith("data:") || path.startsWith("blob:")) return path;
  if (/[?&]access_token=/.test(path)) return path;
  const sep = path.includes("?") ? "&" : "?";
  return `${path}${sep}access_token=${encodeURIComponent(token)}`;
}

async function restorePromptHistoryImage(img, entry = {}) {
  if (!img || typeof img !== "object") return null;
  const name = String(img.name || "image.png");
  const mediaType = String(img.media_type || "image/png").toLowerCase() === "image/jpg"
    ? "image/jpeg"
    : String(img.media_type || "image/png");
  const id = String(img.id || `img-${Date.now()}-${Math.random().toString(16).slice(2)}`);
  const dataUrl = String(img.data_url || "");
  if (dataUrl.startsWith("data:") && dataUrl.includes(";base64,")) {
    try {
      const norm = await normalizePromptImageDataUrl(dataUrl, mediaType);
      return {
        ...img,
        id,
        name,
        media_type: norm.media_type,
        data_url: norm.data_url,
        stored_name: img.stored_name,
        url: img.url,
      };
    } catch {
      if (promptImageHasBytes({ data_url: dataUrl })) {
        return { ...img, id, name, media_type: mediaType, data_url: dataUrl, stored_name: img.stored_name, url: img.url };
      }
    }
  }
  const storedName = decodePromptImageName(img.stored_name || "");
  const candidates = promptImageFetchCandidates({ ...img, stored_name: storedName, data_url: dataUrl }, entry);
  for (const url of candidates) {
    try {
      const path = url.startsWith("http") ? _apiPath(url) : url;
      const res = await rawFetch(withPromptImageAccessToken(path), {}, 60000);
      if (!res.ok) continue;
      const blob = await res.blob();
      if (!blob || !blob.size) continue;
      const type = String(blob.type || "").toLowerCase();
      if (type.includes("json") || type.includes("html") || type.includes("text")) continue;
      const restored = await blobToDataUrl(blob);
      if (!String(restored || "").startsWith("data:image/")) continue;
      try {
        const norm = await normalizePromptImageDataUrl(restored, blob.type || mediaType);
        return {
          ...img,
          id,
          name,
          media_type: norm.media_type,
          data_url: norm.data_url,
          stored_name: storedName || img.stored_name,
          url: img.url || url,
        };
      } catch {
        return {
          ...img,
          id,
          name,
          media_type: blob.type || mediaType,
          data_url: restored,
          stored_name: storedName || img.stored_name,
          url: img.url || url,
        };
      }
    } catch {
      /* try next candidate */
    }
  }
  return null;
}

async function restorePromptHistoryImages(entry = {}) {
  const imgs = Array.isArray(entry?.images) ? entry.images : [];
  const out = [];
  for (const img of imgs.slice(0, 8)) {
    const restored = await restorePromptHistoryImage(img, entry);
    if (restored) out.push(restored);
  }
  return out;
}

const pendingPromptImagePersists = [];

function queuePromptImagePersist(img) {
  const work = persistAttachedPromptImage(img).then((saved) => {
    if (saved) {
      const idx = promptImages.findIndex((p) => p.id === (img?.id || saved.id));
      if (idx >= 0) promptImages[idx] = { ...promptImages[idx], ...saved };
      if (!restoringModelPromptState) saveActiveModelPromptState();
    }
    return saved;
  });
  pendingPromptImagePersists.push(work);
  void work.finally(() => {
    const i = pendingPromptImagePersists.indexOf(work);
    if (i >= 0) pendingPromptImagePersists.splice(i, 1);
  });
  return work;
}

async function persistAttachedPromptImage(img) {
  if (!promptImageHasBytes(img)) return img;
  if (!projectId) {
    try {
      await ensureProject();
    } catch {
      /* compose can attach before a project exists */
    }
  }
  if (!projectId) return img;
  try {
    const blob = await (await fetch(String(img.data_url))).blob();
    if (!blob || !blob.size) return img;
    const form = new FormData();
    form.append("file", blob, String(img.name || "image.jpg"));
    form.append("image_id", String(img.id || ""));
    form.append("name", String(img.name || "image.jpg"));
    form.append("media_type", String(img.media_type || blob.type || "image/jpeg"));
    const res = await rawFetch(`/api/projects/${projectId}/prompt-images`, {
      method: "POST",
      body: form,
    }, 120000);
    if (!res.ok) {
      console.warn("Could not persist prompt image", res.status);
      return img;
    }
    const data = await res.json().catch(() => ({}));
    return {
      ...img,
      stored_name: data?.stored_name || img.stored_name,
      url: data?.url || img.url,
      media_type: data?.media_type || img.media_type,
    };
  } catch (err) {
    console.warn("Could not persist prompt image to project:", err);
    return img;
  }
}

async function addPromptImages(files) {
  let added = 0;
  const list = [...files];
  if (!list.length) return;
  setPromptAttachBusy(true, list.length === 1 ? `Attaching ${list[0].name}…` : `Attaching ${list.length} images…`);
  try {
    for (const file of list) {
      if (promptImages.length >= 8) break;
      if (!isPromptAttachableImageFile(file)) continue;
      if (file.size > 12 * 1024 * 1024) {
        viewerOverlay.showError(`${file.name} is too large. Use images under 12 MB.`);
        continue;
      }
      try {
        const ready = await convertHeicFileToPng(file);
        const norm = await fileToNormalizedPromptImage(ready);
        const attached = {
          id: `img-${Date.now()}-${Math.random().toString(16).slice(2)}`,
          name: promptImageJpegName(ready.name),
          media_type: norm.media_type,
          data_url: norm.data_url,
        };
        promptImages.push(attached);
        added += 1;
        renderPromptImages();
        queuePromptImagePersist(attached);
      } catch (err) {
        console.warn("Could not attach image", file.name, err);
        viewerOverlay.showError(`${file.name} could not be read. Try PNG or JPEG.`);
      }
    }
    renderPromptImages();
    if (added > 0) {
      setEditStatus("ok", added === 1 ? "Attached 1 image to the AI prompt." : `Attached ${added} images to the AI prompt.`);
      if (!isImagineComposeTabActive()) showAiComposePanel();
    } else if (list.length) {
      viewerOverlay.showError("Could not attach that image. Use PNG, JPEG, WebP, or an iPhone HEIC photo.");
    }
    if (!restoringModelPromptState) saveActiveModelPromptState();
  } finally {
    setPromptAttachBusy(false);
  }
}

promptImageDrop?.addEventListener("click", (e) => {
  if (e.target === promptImageInput) return;
  promptImageInput?.click();
});
promptImageDrop?.addEventListener("keydown", (e) => {
  if (e.key === "Enter" || e.key === " ") promptImageInput?.click();
});
promptImageInput?.addEventListener("change", async (e) => {
  const selected = [...(e.target.files || [])];
  try {
    const cadFiles = selected.filter((file) => isPromptCadFile(file));
    const dxfFiles = selected.filter((file) => /\.dxf$/i.test(file.name) && !isPromptCadFile(file));
    const docFiles = selected.filter(
      (file) => !/\.dxf$/i.test(file.name) && !isPromptCadFile(file) && isPromptDocumentFile(file)
    );
    const refFiles = selected.filter(
      (file) => isPromptProjectReferenceFile(file) && !isPromptCadFile(file) && !isPromptDocumentFile(file)
    );
    const imageFiles = selected.filter((file) => isPromptAttachableImageFile(file));
    const mediaFiles = selected.filter(
      (file) =>
        isPromptLinkedMediaFile(file)
        && !isPromptAttachableImageFile(file)
        && !isPromptCadFile(file)
        && !isPromptDocumentFile(file)
        && !isPromptProjectReferenceFile(file),
    );
    if (cadFiles.length) await addPromptCadFiles(cadFiles);
    if (dxfFiles.length) await addPromptDxfFiles(dxfFiles);
    if (docFiles.length) await addPromptDocumentFiles(docFiles);
    if (refFiles.length) await addPromptProjectReferenceFiles(refFiles);
    if (imageFiles.length) await addPromptImages(imageFiles);
    if (mediaFiles.length) await addPromptLinkedMediaFiles(mediaFiles);
    if (
      selected.length
      && !cadFiles.length
      && !dxfFiles.length
      && !docFiles.length
      && !refFiles.length
      && !imageFiles.length
      && !mediaFiles.length
    ) {
      viewerOverlay.showError("That file type is not a prompt attachment. Use a photo (PNG/JPEG), video, DXF, CAD, or PDF.");
    }
  } finally {
    e.target.value = "";
  }
});

function droppedImageFiles(e) {
  const out = [];
  const seen = new Set();
  const addFile = (file) => {
    if (!isPromptAttachableImageFile(file)) return;
    const key = `${file.name}:${file.size}:${file.lastModified}`;
    if (seen.has(key)) return;
    seen.add(key);
    out.push(file);
  };
  [...(e.dataTransfer?.items || [])].forEach((item) => {
    if (item.kind === "file") addFile(item.getAsFile());
  });
  [...(e.dataTransfer?.files || [])].forEach(addFile);
  return out;
}

function droppedDxfFiles(e) {
  return [...(e.dataTransfer?.files || [])].filter(
    (file) => /\.dxf$/i.test(file.name) || file.type === "application/dxf" || file.type === "image/vnd.dxf"
  );
}

const PROMPT_CAD_EXT_RE = /\.(stl|obj|glb|gltf|ply|off|3mf|step|stp|iges|igs|brep|brp|f3z|f3d|sldprt|sldasm|zip)$/i;

function isPromptCadFile(file) {
  const name = String(file?.name || "");
  if (!name) return false;
  return PROMPT_CAD_EXT_RE.test(name);
}

function droppedCadFiles(e) {
  return [...(e.dataTransfer?.files || [])].filter((file) => isPromptCadFile(file));
}

const PROMPT_DOC_EXT_RE = /\.(txt|md|csv|tsv|json|ya?ml|log)$/i;

function isPromptDocumentFile(file) {
  const name = String(file?.name || "");
  if (!name) return false;
  if (PROMPT_DOC_EXT_RE.test(name)) return true;
  const mime = String(file?.type || "").toLowerCase();
  return mime.startsWith("text/") || mime === "application/json" || mime.includes("yaml");
}

function droppedDocumentFiles(e) {
  return [...(e.dataTransfer?.files || [])].filter(
    (file) =>
      isPromptDocumentFile(file) &&
      !/\.dxf$/i.test(file.name) &&
      !isPromptCadFile(file) &&
      !file.type?.startsWith?.("image/")
  );
}

function droppedExplorerRefs(e) {
  return readExplorerDragPayloads(e);
}

function isExplorerComponentDrag(e) {
  const types = e.dataTransfer?.types;
  if (!types) return false;
  return [...types].includes("application/render3d-component");
}

function isPromptImageDrag(e) {
  if (droppedImageFiles(e).length) return true;
  if (droppedCadFiles(e).length) return true;
  if (droppedDxfFiles(e).length) return true;
  if (droppedDocumentFiles(e).length) return true;
  const files = [...(e.dataTransfer?.files || [])];
  if (files.some((file) => isPromptProjectReferenceFile(file))) return true;
  const types = e.dataTransfer?.types;
  return types && [...types].includes("Files");
}

function setPromptAttachBusy(busy, message = "") {
  const drop = document.getElementById("prompt-image-drop");
  const status = document.getElementById("prompt-status");
  drop?.classList.toggle("is-loading", !!busy);
  drop?.setAttribute("aria-busy", busy ? "true" : "false");
  if (drop) {
    let badge = drop.querySelector(".prompt-attach-busy");
    if (busy) {
      if (!badge) {
        badge = document.createElement("div");
        badge.className = "prompt-attach-busy";
        badge.innerHTML = `<span class="prompt-attach-spinner" aria-hidden="true"></span><span class="prompt-attach-busy-text"></span>`;
        drop.appendChild(badge);
      }
      const textEl = badge.querySelector(".prompt-attach-busy-text");
      if (textEl) textEl.textContent = message || "Loading file…";
    } else if (badge) {
      badge.remove();
    }
  }
  if (status) {
    if (busy) {
      status.className = "status loading";
      status.textContent = message || "Loading file…";
    } else if (status.classList.contains("loading") && (!message || status.textContent === message || /loading|upload|attach|opening/i.test(status.textContent || ""))) {
      status.className = "status";
      status.textContent = "";
    }
  }
  if (busy && message) setEditStatus("loading", message);
}

async function addPromptCadFiles(files) {
  const list = [...files].filter((file) => isPromptCadFile(file));
  if (!list.length) return;
  const modeBeforeAttach = promptMode;
  let added = 0;
  const total = list.length;
  showAiComposePanel();
  setPromptAttachBusy(
    true,
    total === 1 ? `Uploading CAD ${list[0].name}…` : `Uploading ${total} CAD files…`
  );
  try {
    await ensureProject();
    for (let i = 0; i < list.length; i += 1) {
      const file = list[i];
      const progress = total > 1 ? ` (${i + 1}/${total})` : "";
      if (file.size > 80 * 1024 * 1024) {
        viewerOverlay?.showError?.(`${file.name} is too large for a CAD reference (max 80 MB).`);
        continue;
      }
      setPromptAttachBusy(true, `Uploading CAD${progress}: ${file.name}…`);
      try {
        const form = new FormData();
        form.append("file", file, file.name);
        const uploaded = await api(`/api/projects/${projectId}/upload`, {
          method: "POST",
          body: form,
        });
        const filename = uploaded?.filename || file.name;
        const viewerFilename = uploaded?.viewer_filename || filename;
        const stem = String(filename).replace(/\.[^.]+$/, "");
        const formatMatch = String(filename).match(/\.([^.]+)$/);
        const format = (formatMatch?.[1] || "").toLowerCase() || undefined;
        const attached = addComponentPromptReference({
          filename,
          stem,
          format,
          viewer_filename: viewerFilename,
          label: stem,
          projectId,
          type: "component",
          mate_target: getPromptTargetMode() !== "edit",
        });
        if (attached) added += 1;
        setPromptAttachBusy(true, `Reading geometry${progress}: ${filename}…`);
        try {
          const brief = await api(
            `/api/projects/${projectId}/files/${encodeURIComponent(filename)}/geometry-brief?include_views=true`,
            { method: "POST" }
          );
          const views = brief?.views || brief?.geometry?.views || [];
          let viewAdded = 0;
          for (const view of views) {
            if (promptImages.length >= 8) break;
            if (!view?.data_url) continue;
            // Prefer iso/top/front for the AI; skip side if we're near the image cap.
            if (viewAdded >= 3) break;
            promptImages.push({
              id: view.id || `cadref-${Date.now()}-${view.view || viewAdded}`,
              name: view.name || `${stem}_${view.view || "view"}.png`,
              media_type: view.media_type || "image/png",
              data_url: view.data_url,
            });
            const last = promptImages[promptImages.length - 1];
            queuePromptImagePersist(last);
            viewAdded += 1;
          }
          if (viewAdded > 0) renderPromptImages();
          const size = brief?.geometry?.size_mm;
          if (Array.isArray(size) && size.length >= 3) {
            setEditStatus(
              "ok",
              `Attached ${filename} (${size[0]}×${size[1]}×${size[2]} mm) with ${viewAdded} shape views for the AI.`
            );
          } else {
            setEditStatus("ok", `Attached CAD reference ${filename}.`);
          }
        } catch (err) {
          console.warn("CAD geometry brief failed", err);
          setEditStatus("ok", `Attached CAD reference ${filename} (geometry preview unavailable).`);
        }
        setPromptAttachBusy(true, `Loading CAD${progress}: ${filename}…`);
        await refreshFiles();
        try {
          const hadComponents = projectAssembly.count() > 0;
          await loadModel(uploaded?.url || `/api/projects/${projectId}/files/${encodeURIComponent(viewerFilename)}`, viewerFilename, {
            projectId,
            append: hadComponents,
            catalogFilename: filename,
            autoGizmo: false,
            fitView: true,
          });
          projectTree.setSelected(filename);
        } catch (err) {
          console.warn("Could not load CAD into viewport after prompt attach", err);
        }
      } catch (err) {
        console.warn("CAD prompt upload failed", err);
        viewerOverlay?.showError?.(err?.message || `Could not attach ${file.name}.`);
      }
    }
    if (added > 0) {
      setSkillEnabled("cad", true);
      skillsPromptUI?.render?.();
      skillsPromptUI?.updatePlan?.();
      const status = document.getElementById("prompt-status");
      if (status) {
        status.className = "status ok";
        status.textContent =
          added === 1
            ? "Attached CAD/STEP — AI will model new parts to that object (mate to B-rep). Switch to Edit to change the STEP itself."
            : `Attached ${added} CAD references — AI will model new parts to those objects.`;
      }
    }
  } finally {
    setPromptAttachBusy(false);
    preservePromptModeAfterAttach(modeBeforeAttach);
  }
  if (!restoringModelPromptState) saveActiveModelPromptState();
}

async function addPromptDxfFiles(files) {
  const MAX_DXF_CHARS = 400_000;
  const list = [...files];
  if (!list.length) return;
  const modeBeforeAttach = promptMode;
  let added = 0;
  const total = list.length;
  showAiComposePanel();
  setPromptAttachBusy(true, total === 1 ? `Loading DXF ${list[0].name}…` : `Loading ${total} DXF files…`);
  try {
    for (let i = 0; i < list.length; i += 1) {
      const file = list[i];
      const progress = total > 1 ? ` (${i + 1}/${total})` : "";
      if (file.size > 8 * 1024 * 1024) {
        viewerOverlay?.showError?.(`${file.name} is too large for a DXF reference (max 8 MB).`);
        continue;
      }
      setPromptAttachBusy(true, `Uploading DXF${progress}: ${file.name}…`);
      let uploaded = null;
      try {
        await ensureProject();
        const form = new FormData();
        form.append("file", file, file.name);
        uploaded = await api(`/api/projects/${projectId}/upload`, {
          method: "POST",
          body: form,
        });
        setPromptAttachBusy(true, `Opening DXF${progress}: ${uploaded?.filename || file.name}…`);
        await refreshFiles();
      } catch (err) {
        console.warn("DXF project upload failed; falling back to inline DXF reference", err);
        setEditStatus("warn", `Attached ${file.name} as inline DXF; project upload failed.`);
      }
      setPromptAttachBusy(true, `Reading DXF${progress}: ${file.name}…`);
      const text = await file.text();
      const filename = uploaded?.filename || file.name;
      const stem = filename.replace(/\.dxf$/i, "");
      const id = `dxf:${projectId || "project"}:${filename}`;
      const token = `@${stem.replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "dxf"}`;
      const truncated = text.length > MAX_DXF_CHARS;
      composer.addReference({
        id,
        type: "dxf",
        token,
        label: filename,
        filename,
        stem,
        format: "dxf",
        text_content: truncated ? text.slice(0, MAX_DXF_CHARS) : text,
        text_truncated: truncated,
        projectId,
      });
      added += 1;
      if (uploaded?.filename && projectId) {
        try {
          setPromptAttachBusy(true, `Opening drawing tab: ${filename}…`);
          referenceFilesViewer?.hideViewerOnly?.();
          await dxfViewer.openTab(filename, {
            projectId,
            label: stem,
          });
        } catch (err) {
          console.warn("Could not open DXF tab after prompt attach", err);
        }
      }
      setEditStatus("ok", `Attached DXF reference ${filename}.`);
    }
    if (added > 0) {
      setSkillEnabled("dxf", true);
      skillsPromptUI?.render?.();
      skillsPromptUI?.updatePlan?.();
      const status = document.getElementById("prompt-status");
      if (status) {
        status.className = "status ok";
        status.textContent =
          added === 1
            ? `Attached DXF — opened in a tab. Close the tab anytime with ×.`
            : `Attached ${added} DXF files — opened in tabs.`;
      }
    }
  } finally {
    setPromptAttachBusy(false);
    preservePromptModeAfterAttach(modeBeforeAttach);
  }
  if (!restoringModelPromptState) saveActiveModelPromptState();
}

function isPromptProjectReferenceFile(file) {
  const name = String(file?.name || "");
  return /\.(pdf|svg)$/i.test(name);
}

function isPromptLinkedMediaFile(file) {
  const name = String(file?.name || "");
  const type = String(file?.type || "").toLowerCase();
  if (type.startsWith("video/") || /\.(webm|mp4|mov|m4v)$/i.test(name)) return true;
  if (type.startsWith("audio/") || /\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(name)) return true;
  return false;
}

function promptLinkedFileType(file) {
  const name = String(file?.name || "");
  const type = String(file?.type || "").toLowerCase();
  if (type.startsWith("video/") || /\.(webm|mp4|mov|m4v)$/i.test(name)) return "video";
  if (type.startsWith("audio/") || /\.(mp3|wav|ogg|m4a|aac|flac)$/i.test(name)) return "audio";
  return "file";
}

async function addPromptLinkedMediaFiles(files) {
  const list = [...files].filter((file) => isPromptLinkedMediaFile(file));
  if (!list.length) return 0;
  let added = 0;
  showAiComposePanel();
  setPromptAttachBusy(true, list.length === 1 ? `Attaching ${list[0].name}…` : `Attaching ${list.length} files…`);
  try {
    await ensureProject();
    for (const file of list) {
      const kind = promptLinkedFileType(file);
      let uploaded = null;
      try {
        uploaded = await uploadReferenceProjectFile(file, {
          destination: "current",
          projectId,
          silent: true,
        });
      } catch (err) {
        console.warn("Prompt media upload failed; linking locally", file.name, err);
      }
      const filename = uploaded?.filename || file.name;
      const stem = String(filename).replace(/\.[^.]+$/, "") || kind;
      const url = uploaded?.url
        || (projectId
          ? `/api/projects/${encodeURIComponent(projectId)}/files/${String(filename).split("/").map(encodeURIComponent).join("/")}`
          : URL.createObjectURL(file));
      const ref = {
        id: `${kind}:${projectId || "project"}:${filename}`,
        type: kind,
        token: compactComponentToken(stem),
        label: filename,
        filename,
        stem,
        format: String(filename).split(".").pop()?.toLowerCase() || kind,
        url,
        mime: file.type || (kind === "video" ? "video/webm" : file.type),
        projectId,
      };
      composer.removeReference?.(ref.id);
      composer.addReference(ref, { insertMention: false });
      stripPromptReferenceProse(filename);
      added += 1;
    }
    if (added > 0) {
      setEditStatus("ok", added === 1 ? "Linked 1 file to the AI prompt." : `Linked ${added} files to the AI prompt.`);
    }
  } finally {
    setPromptAttachBusy(false);
  }
  if (!restoringModelPromptState) saveActiveModelPromptState();
  return added;
}

async function addPromptProjectReferenceFiles(files) {
  const list = [...files].filter((file) => isPromptProjectReferenceFile(file));
  if (!list.length) return 0;
  let added = 0;
  showAiComposePanel();
  setPromptAttachBusy(true, list.length === 1 ? `Attaching ${list[0].name}…` : `Attaching ${list.length} reference files…`);
  try {
    await ensureProject();
    for (const file of list) {
      const uploaded = await uploadReferenceProjectFile(file, {
        destination: "current",
        projectId,
        silent: true,
      });
      const filename = uploaded?.filename || file.name;
      try {
        await openReferenceFile({ name: filename, kind: uploaded?.kind });
        await referenceFilesViewer?.sendToPrompt?.(filename);
      } catch (err) {
        console.warn("Send reference to prompt failed", filename, err);
        composer.addReference(promptDocumentReference({ filename }));
      }
      added += 1;
    }
    if (added > 0) {
      setEditStatus("ok", added === 1 ? "Attached 1 reference file to the AI prompt." : `Attached ${added} reference files to the AI prompt.`);
    }
  } finally {
    setPromptAttachBusy(false);
  }
  return added;
}

async function addPromptDocumentFiles(files) {
  const MAX_DOC_BYTES = 2 * 1024 * 1024;
  const MAX_DOC_CHARS = 100_000;
  let added = 0;
  for (const file of [...files]) {
    if (!isPromptDocumentFile(file)) continue;
    if (file.size > MAX_DOC_BYTES) {
      viewerOverlay?.showError?.(`${file.name} is too large for a prompt document (max 2 MB).`);
      continue;
    }
    const text = await file.text();
    if (!text.trim()) continue;
    const filename = file.name;
    const stem = filename.replace(/\.[^.]+$/, "");
    const tokenStem = String(stem || "doc").replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "doc";
    const truncated = text.length > MAX_DOC_CHARS;
    composer.addReference({
      id: `document:${projectId || "project"}:${filename}`,
      type: "document",
      token: `@doc-${tokenStem}`,
      label: filename,
      filename,
      stem,
      format: filename.split(".").pop()?.toLowerCase() || "txt",
      text_content: truncated ? text.slice(0, MAX_DOC_CHARS) : text,
      text_truncated: truncated,
      projectId,
    });
    added += 1;
  }
  if (added > 0) {
    setEditStatus("ok", added === 1 ? "Attached 1 document reference." : `Attached ${added} document references.`);
  }
  if (!restoringModelPromptState) saveActiveModelPromptState();
}

function eventHitsOpenRefViewer(e) {
  const viewer = document.getElementById("ref-viewer");
  if (!viewer || viewer.classList.contains("hidden")) return false;
  if (e.target instanceof Element && e.target.closest("#ref-viewer, .ref-viewer")) return true;
  const x = e.clientX;
  const y = e.clientY;
  if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
  const rect = viewer.getBoundingClientRect();
  return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
}

function eventHitsPromptPanel(e) {
  const t = e.target;
  if (!(t instanceof Element)) return false;
  return !!t.closest('.prompt-panel[data-right-panel="prompt"], #prompt-pane-imagine, .imagine-compose, #imagine-input');
}

function eventHitsClipEditor(e) {
  const t = e.target;
  if (!(t instanceof Element)) return false;
  return !!t.closest("[data-video-editor-card], .clip-editor-panel, [data-vtl-host], [data-vtl-video-lane], [data-vtl-audio-lane]");
}

async function handleImagineComposeDrop(e) {
  if (eventHitsOpenRefViewer(e) || eventHitsClipEditor(e)) return false;
  const files = [...(e.dataTransfer?.files || [])].filter((file) => isImagineReferenceFile(file));
  if (!files.length) return false;
  e.preventDefault();
  e.stopPropagation();
  promptPaneCompose?.classList.remove("dragging-image");
  promptImageDrop?.classList.remove("dragging");
  await imagineUi?.attachDroppedFiles?.(files);
  showImaginePanel({ focus: false });
  return true;
}

async function routeDroppedFilesToImagine(files, e) {
  if (!isImagineComposeTabActive()) return false;
  if (e && (eventHitsClipEditor(e) || eventHitsOpenRefViewer(e))) return false;
  if (e && isCanvasDesignTabActive() && !eventHitsPromptPanel(e)) return false;
  const refs = [...(files || [])].filter((file) => isImagineReferenceFile(file));
  if (!refs.length) return false;
  await imagineUi?.attachDroppedFiles?.(refs);
  showImaginePanel({ focus: false });
  return true;
}

function handlePromptComposeDragover(e) {
  if (eventHitsOpenRefViewer(e)) return;
  if (!isPromptImageDrag(e) && !isExplorerComponentDrag(e)) return;
  e.preventDefault();
  e.stopPropagation();
  if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
  if (isImagineComposeTabActive()) return;
  promptPaneCompose?.classList.add("dragging-image");
  promptImageDrop?.classList.add("dragging");
}

function handlePromptComposeDragleave(e) {
  if (!promptPanel?.contains(e.relatedTarget)) {
    promptPaneCompose?.classList.remove("dragging-image");
    promptImageDrop?.classList.remove("dragging");
  }
}

async function handlePromptComposeDrop(e) {
  if (eventHitsOpenRefViewer(e)) return;
  if (isImagineComposeTabActive()) {
    await handleImagineComposeDrop(e);
    return;
  }
  const modeBeforeAttach = promptMode;
  const componentRefs = droppedExplorerRefs(e);
  if (componentRefs.length) {
    e.preventDefault();
    e.stopPropagation();
    promptPaneCompose?.classList.remove("dragging-image");
    promptImageDrop?.classList.remove("dragging");
    const added = addComponentPromptReferences(componentRefs);
    const specs = promptMode === "mesh" || !isMcMasterPartsEnabled()
      ? 0
      : await attachMcMasterSpecPointers(componentRefs);
    if (added > 0) {
      const componentCount = composer.getReferences().filter((r) => r.type === "component").length;
      preservePromptModeAfterAttach(modeBeforeAttach);
      setEditStatus(
        "ok",
        specs > 0
          ? added === 1
            ? "Referenced McMaster part + AI spec pointer (strength/material/listing)."
            : `Referenced ${added} items + ${specs} McMaster AI spec pointer${specs === 1 ? "" : "s"}.`
          : added === 1
            ? "Referenced 1 item in the AI prompt."
            : `Referenced ${added} items in the AI prompt (${componentCount} component${componentCount === 1 ? "" : "s"} total).`
      );
    }
    return;
  }
  const cadFiles = droppedCadFiles(e);
  if (cadFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptPaneCompose?.classList.remove("dragging-image");
    promptImageDrop?.classList.remove("dragging");
    setPromptAttachBusy(
      true,
      cadFiles.length === 1 ? `Uploading CAD ${cadFiles[0].name}…` : `Uploading ${cadFiles.length} CAD files…`
    );
    await addPromptCadFiles(cadFiles);
    preservePromptModeAfterAttach(modeBeforeAttach);
    return;
  }
  const dxfFiles = droppedDxfFiles(e);
  if (dxfFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptPaneCompose?.classList.remove("dragging-image");
    promptImageDrop?.classList.remove("dragging");
    setPromptAttachBusy(true, dxfFiles.length === 1 ? `Loading DXF ${dxfFiles[0].name}…` : `Loading ${dxfFiles.length} DXF files…`);
    await addPromptDxfFiles(dxfFiles);
    preservePromptModeAfterAttach(modeBeforeAttach);
    return;
  }
  const docFiles = droppedDocumentFiles(e);
  if (docFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptPaneCompose?.classList.remove("dragging-image");
    promptImageDrop?.classList.remove("dragging");
    await addPromptDocumentFiles(docFiles);
    preservePromptModeAfterAttach(modeBeforeAttach);
    return;
  }
  const refFiles = [...(e.dataTransfer?.files || [])].filter((file) => isPromptProjectReferenceFile(file));
  if (refFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptPaneCompose?.classList.remove("dragging-image");
    promptImageDrop?.classList.remove("dragging");
    await addPromptProjectReferenceFiles(refFiles);
    preservePromptModeAfterAttach(modeBeforeAttach);
    return;
  }
  const mediaFiles = [...(e.dataTransfer?.files || [])].filter((file) => isPromptLinkedMediaFile(file));
  const files = droppedImageFiles(e);
  if (!files.length && !mediaFiles.length) {
    if ([...(e.dataTransfer?.files || [])].length || [...(e.dataTransfer?.types || [])].includes("Files")) {
      e.preventDefault();
      e.stopPropagation();
      promptPaneCompose?.classList.remove("dragging-image");
      promptImageDrop?.classList.remove("dragging");
      stripPromptReferenceProse();
    }
    return;
  }
  if (e.target instanceof Element && e.target.closest("#prompt-image-drop") && !mediaFiles.length) return;
  e.preventDefault();
  e.stopPropagation();
  promptPaneCompose?.classList.remove("dragging-image");
  promptImageDrop?.classList.remove("dragging");
  if (files.length) await addPromptImages(files);
  if (mediaFiles.length) await addPromptLinkedMediaFiles(mediaFiles);
  preservePromptModeAfterAttach(modeBeforeAttach);
}

function compactComponentToken(stem = "component") {
  return `@${String(stem || "component").replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "component"}`;
}

function componentPromptReference(payload) {
  if (!payload?.filename && !payload?.name) return null;
  const board = canvasBoardReference(payload);
  const filename = board?.filename || payload.filename || payload.name;
  const stem = board?.name || payload.stem || filename.replace(/\.[^.]+$/, "");
  const pid = payload.projectId || projectId || null;
  return {
    id: `component:${pid || "project"}:${filename}`,
    type: board ? "sketch" : payload.type === "sketch" || payload.type === "wiring" ? payload.type : "component",
    token: compactComponentToken(stem),
    label: payload.label || stem,
    filename,
    stem,
    format: payload.format,
    viewer_filename: payload.viewer_filename,
    projectId: pid,
    body_index: payload.body_index,
    mate_target: payload.mate_target === true,
  };
}

function addComponentPromptReference(payload) {
  const ref = componentPromptReference(payload);
  if (!ref) return false;
  composer.addReference(ref);
  return true;
}

function addComponentPromptReferences(payloads = []) {
  const refs = payloads.map((payload) => componentPromptReference(payload)).filter(Boolean);
  if (!refs.length) return 0;
  return composer.addReferences(refs) || 0;
}

let mcmasterLibraryCache = { projectId: null, at: 0, entries: [] };

async function loadMcMasterLibraryEntries(pid = projectId) {
  if (!pid) return [];
  const now = Date.now();
  if (mcmasterLibraryCache.projectId === pid && now - mcmasterLibraryCache.at < 15000) {
    return mcmasterLibraryCache.entries;
  }
  try {
    const data = await api(`/api/projects/${pid}/mcmaster-library`);
    const entries = data?.entries || [];
    mcmasterLibraryCache = { projectId: pid, at: now, entries };
    return entries;
  } catch {
    return mcmasterLibraryCache.projectId === pid ? mcmasterLibraryCache.entries : [];
  }
}

function matchMcMasterLibraryEntry(entries, filename) {
  const want = String(filename || "").trim().toLowerCase();
  if (!want) return null;
  const stem = want.replace(/\.[^.]+$/, "");
  let best = null;
  for (const entry of entries || []) {
    const names = [
      entry.name,
      entry.filename,
      entry.project_filename,
    ].map((n) => String(n || "").trim().toLowerCase()).filter(Boolean);
    if (names.includes(want)) return entry;
    const entryStem = String(entry.project_filename || entry.name || "").replace(/\.[^.]+$/, "").toLowerCase();
    if (entryStem && entryStem === stem) best = best || entry;
    const pn = String(entry.part_number || "").trim().toLowerCase();
    if (pn && (stem.startsWith(pn) || want.startsWith(pn))) best = best || entry;
  }
  return best;
}

async function fetchProjectTextFile(pid, filename) {
  if (!pid || !filename) return "";
  try {
    const res = await rawFetch(`/api/projects/${pid}/files/${encodeURIComponent(filename)}`);
    if (!res.ok) return "";
    return await res.text();
  } catch {
    return "";
  }
}

/** When a McMaster CAD part is dropped into the AI prompt, also attach its spec pointer. */
function isMcMasterPromptRef(ref) {
  const blob = `${ref?.id || ""} ${ref?.filename || ""} ${ref?.label || ""} ${ref?.token || ""} ${ref?.stem || ""}`.toLowerCase();
  return blob.includes("mcmaster") || Boolean(ref?.mcmaster_part_number);
}

function promptReferencesForMode(mode, refs = []) {
  const engine = String(mode || "").toLowerCase();
  const mesh = engine === "mesh" || engine === "mesh_beta" || engine === "mesh-beta" || engine === "fusion";
  if (!mesh) return refs || [];
  return (refs || []).filter((r) => !isMcMasterPromptRef(r));
}

async function attachMcMasterSpecPointers(payloads = []) {
  const pid = projectId;
  if (!pid || !payloads?.length) return 0;
  const entries = await loadMcMasterLibraryEntries(pid);
  if (!entries.length) return 0;
  const matched = payloads.some((payload) =>
    matchMcMasterLibraryEntry(entries, payload?.filename || payload?.name),
  );
  if (!matched) return 0;
  const already = (composer.getReferences?.() || []).some(
    (r) => r?.mcmaster_parts_list || String(r?.filename || "").toLowerCase() === "parts_list.md",
  );
  if (already) return 0;
  let text = await fetchProjectTextFile(pid, "parts_list.md");
  if (!text.trim()) {
    text = await fetchProjectTextFile(pid, "McMaster/parts_list.md");
  }
  if (!text.trim()) return 0;
  const MAX_DOC_CHARS = 100_000;
  const truncated = text.length > MAX_DOC_CHARS;
  composer.addReference({
    id: `mcmaster-spec:${pid}:parts_list.md`,
    type: "spec",
    token: "@mcmaster-parts",
    label: "McMaster parts list",
    filename: "parts_list.md",
    stem: "parts_list",
    format: "md",
    folder: "McMaster",
    text_content: truncated ? text.slice(0, MAX_DOC_CHARS) : text,
    text_truncated: truncated,
    projectId: pid,
    mcmaster_parts_list: true,
  });
  return 1;
}

let autoSelectedObjectRefId = null;

function selectedWholeObjectPromptReference(selection = null) {
  if (!selection) return null;
  const filename =
    selection.catalogName
    || selection.root?.userData?.catalogFilename
    || selection.mesh?.userData?.catalogFilename
    || (selection.mesh ? catalogNameForMesh(selection.mesh) : null)
    || selectedFile;
  if (!filename) return null;
  const stem = fileStem(filename) || selection.label || "selected-object";
  const mateTarget = getPromptTargetMode() !== "edit";
  return {
    id: `selection-whole:${projectId || "project"}:${filename}`,
    type: "component",
    token: "@selected-object",
    label: mateTarget ? `Mate to: ${stem}` : `Selected object: ${stem}`,
    filename,
    stem,
    viewer_filename: filename,
    projectId,
    mate_target: mateTarget,
  };
}

function isAutoSelectedObjectReference(ref) {
  return (
    String(ref?.id || "").startsWith("selection-whole:")
    || String(ref?.token || "") === "@selected-object"
  );
}

function syncSelectedObjectPromptReference(selection = null) {
  const nextRef = selectedWholeObjectPromptReference(selection);
  if (autoSelectedObjectRefId && (!nextRef || autoSelectedObjectRefId !== nextRef.id)) {
    composer.removeReference(autoSelectedObjectRefId);
    autoSelectedObjectRefId = null;
  }
  if (!nextRef) return;
  autoSelectedObjectRefId = nextRef.id;
  const existing = (composer.getReferences?.() || []).find((ref) => ref.id === nextRef.id);
  if (existing) {
    existing.label = nextRef.label;
    existing.mate_target = nextRef.mate_target;
    return;
  }
  composer.addReference(nextRef, { insertMention: true });
}

window.addEventListener("render3d:object-selection-changed", (event) => {
  syncSelectedObjectPromptReference(event.detail?.selected || null);
});

promptImageDrop?.addEventListener("dragover", (e) => {
  if (!isPromptImageDrag(e) && !isExplorerComponentDrag(e)) return;
  e.preventDefault();
  if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
  promptImageDrop.classList.add("dragging");
});
promptImageDrop?.addEventListener("dragleave", () => promptImageDrop.classList.remove("dragging"));
promptImageDrop?.addEventListener("drop", async (e) => {
  if (eventHitsOpenRefViewer(e)) return;
  if (isImagineComposeTabActive()) {
    await handleImagineComposeDrop(e);
    return;
  }
  if (isExplorerComponentDrag(e) && droppedExplorerRefs(e).length) {
    await handlePromptComposeDrop(e);
    return;
  }
  const cadFiles = droppedCadFiles(e);
  if (cadFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptImageDrop.classList.remove("dragging");
    setPromptAttachBusy(
      true,
      cadFiles.length === 1 ? `Uploading CAD ${cadFiles[0].name}…` : `Uploading ${cadFiles.length} CAD files…`
    );
    await addPromptCadFiles(cadFiles);
    return;
  }
  const dxfFiles = droppedDxfFiles(e);
  if (dxfFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptImageDrop.classList.remove("dragging");
    setPromptAttachBusy(true, dxfFiles.length === 1 ? `Loading DXF ${dxfFiles[0].name}…` : `Loading ${dxfFiles.length} DXF files…`);
    await addPromptDxfFiles(dxfFiles);
    return;
  }
  const docFiles = droppedDocumentFiles(e);
  if (docFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptImageDrop.classList.remove("dragging");
    await addPromptDocumentFiles(docFiles);
    return;
  }
  const refFiles = [...(e.dataTransfer?.files || [])].filter((file) => isPromptProjectReferenceFile(file));
  if (refFiles.length) {
    e.preventDefault();
    e.stopPropagation();
    promptImageDrop.classList.remove("dragging");
    await addPromptProjectReferenceFiles(refFiles);
    return;
  }
  e.preventDefault();
  e.stopPropagation();
  promptImageDrop.classList.remove("dragging");
  const mediaFiles = [...(e.dataTransfer?.files || [])].filter((file) => isPromptLinkedMediaFile(file));
  if (mediaFiles.length) await addPromptLinkedMediaFiles(mediaFiles);
  await addPromptImages(droppedImageFiles(e));
});

