function userRealtimeUrl() {
  const token = encodeURIComponent(getToken());
  const proto = location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${location.host}/api/ws/user?token=${token}`;
}

function workspaceRealtimeUrl(teamId) {
  const token = encodeURIComponent(getToken());
  const proto = location.protocol === "https:" ? "wss:" : "ws:";
  return `${proto}//${location.host}/api/ws/workspaces/${encodeURIComponent(teamId)}?token=${token}`;
}

function scheduleUserRealtimeReconnect() {
  if (userRealtimeReconnectTimer || !getToken()) return;
  userRealtimeReconnectTimer = setTimeout(() => {
    userRealtimeReconnectTimer = null;
    connectUserRealtime();
  }, 2500);
}

function scheduleWorkspaceRealtimeReconnect() {
  if (workspaceRealtimeReconnectTimer || !getToken() || !workspaceRealtimeTeamId) return;
  workspaceRealtimeReconnectTimer = setTimeout(() => {
    workspaceRealtimeReconnectTimer = null;
    connectWorkspaceRealtime(workspaceRealtimeTeamId);
  }, 2500);
}

function renderWorkspaceRealtimePresence() {
  const el = document.getElementById("workspace-realtime-presence");
  if (!el) return;
  if (!workspaceRealtimeTeamId) {
    el.textContent = "Select workspace";
    return;
  }
  const count = workspaceRealtimeUsers.length;
  el.textContent = count ? `${count} live` : "Live";
  el.title = workspaceRealtimeUsers.map((u) => u.display_name || "User").join(", ");
}

function handleWorkspaceRealtimeEvent(msg = {}) {
  if (msg.type === "workspace.presence.sync") {
    workspaceRealtimeUsers = msg.users || [];
    renderWorkspaceRealtimePresence();
    return;
  }
  if (msg.type === "workspace.presence.join") {
    const user = msg.user;
    if (user && !workspaceRealtimeUsers.some((u) => u.id === user.id)) {
      workspaceRealtimeUsers.push(user);
      renderWorkspaceRealtimePresence();
    }
    return;
  }
  if (msg.type === "workspace.presence.leave") {
    workspaceRealtimeUsers = workspaceRealtimeUsers.filter((u) => u.id !== msg.user_id);
    renderWorkspaceRealtimePresence();
    return;
  }
  handleRealtimeEvent(msg);
  if (
    msg.type === "workspace.render_folder.updated"
    || msg.type === "workspace.updated"
    || msg.type === "project.created"
    || msg.type === "project.deleted"
    || msg.type === "project.renamed"
    || msg.type === "folder.shared"
    || msg.type === "folder.unshared"
    || msg.type === "folder.renamed"
    || msg.type === "folder.created"
    || msg.type === "folder.deleted"
    || msg.type === "project.shared"
    || msg.type === "project.unshared"
    || msg.type === "fusion.mirror.updated"
  ) {
    if (msg.type === "fusion.mirror.updated") {
      scheduleLiveFusionMirrorRefresh(msg);
    } else if (isStructuralWorkspaceEvent(msg) || msg.type === "workspace.render_folder.updated") {
      void refreshWorkspaceRealtimeEditor();
    }
  }
}

function connectWorkspaceRealtime(teamId) {
  if (teamId && workspaceRealtimeTeamId === teamId && workspaceRealtimeSocket && workspaceRealtimeSocket.readyState <= WebSocket.OPEN) {
    return;
  }
  workspaceRealtimeSocket?.close();
  workspaceRealtimeSocket = null;
  workspaceRealtimeTeamId = teamId || null;
  workspaceRealtimeUsers = [];
  renderWorkspaceRealtimePresence();
  if (!teamId || !getToken()) return;
  const ws = new WebSocket(workspaceRealtimeUrl(teamId));
  workspaceRealtimeSocket = ws;
  ws.onmessage = (ev) => {
    try {
      handleWorkspaceRealtimeEvent(JSON.parse(ev.data));
    } catch {
      /* ignore malformed websocket packets */
    }
  };
  ws.onerror = () => {
    stampStudioCreditIncident("websocket.error", "Workspace realtime websocket error");
  };
  ws.onclose = (ev) => {
    if (ev && ev.code === 1006) {
      stampStudioCreditIncident("websocket.fail", "Workspace realtime websocket dropped", { code: ev.code });
    }
    if (workspaceRealtimeSocket === ws) {
      workspaceRealtimeSocket = null;
      scheduleWorkspaceRealtimeReconnect();
    }
  };
}

let xrCapturePollTimer = 0;
function startXrCapturePolling() {
  if (xrCapturePollTimer) return;
  xrCapturePollTimer = window.setInterval(() => {
    if (!getToken?.()) return;
    if (document.hidden) return;
    if (viewportXR?.isPresenting?.()) return;
    void flushPendingRemoteXrCaptures?.();
  }, 30000);
}
// Do not boot-poll /api/me/xr-captures/pending. Captures arrive on the user
// websocket. Leftover studio + dashboard tabs polling this froze project open.

function connectUserRealtime() {
  userRealtimeSocket?.close();
  if (!getToken()) return;
  const ws = new WebSocket(userRealtimeUrl());
  userRealtimeSocket = ws;
  ws.onmessage = (ev) => {
    let msg;
    try {
      msg = JSON.parse(ev.data);
    } catch {
      return;
    }
    handleRealtimeEvent(msg);
  };
  ws.onopen = () => {
    // Catch captures published while this PC tab was offline
    window.setTimeout(() => { void flushPendingRemoteXrCaptures(); }, 400);
  };
  ws.onerror = () => {
    stampStudioCreditIncident("websocket.error", "User realtime websocket error");
  };
  ws.onclose = (ev) => {
    if (ev && ev.code === 1006) {
      stampStudioCreditIncident("websocket.fail", "User realtime websocket dropped", { code: ev.code });
    }
    if (userRealtimeSocket === ws) {
      userRealtimeSocket = null;
      scheduleUserRealtimeReconnect();
    }
  };
}

let imagineUi = null;

function listImagineImageKeys() {
  const personal = (aiStatus?.keys || []).map((k) => ({
    id: k.id,
    provider: k.provider,
    source: "personal",
  }));
  const team = (aiStatus?.team_keys || [])
    .filter((k) => k.enabled !== false)
    .map((k) => ({ id: k.id, provider: k.provider, source: "team" }));
  const picked = typeof getSelectedPromptAiKey === "function" ? getSelectedPromptAiKey() : null;
  const info = typeof getSelectedPromptModelInfo === "function" ? getSelectedPromptModelInfo() : null;
  const selected = [];
  if (picked?.source === "chatgpt" || picked?.source === "subscription" || picked?.source === "platform" || picked?.source === "cursor") {
    selected.push({
      id: picked.keyId || picked.source,
      provider: info?.provider || "openai",
      source: picked.source,
    });
  }
  return [...selected, ...personal, ...team];
}

async function attachImagineItemToPrompt(item, { prompt = "", mode = "v2" } = {}) {
  if (!item?.name) return;
  if (/\.(step|stp|stl|glb|gltf|3mf)$/i.test(item.name)) {
    await openBrowserComponent(item);
    setEditStatus("ok", `Opened fetched ${item.name}.`);
    return false;
  }
  const pid = projectId;
  const url = item.url || (pid ? `/api/projects/${encodeURIComponent(pid)}/files/${String(item.name).split("/").map(encodeURIComponent).join("/")}` : "");
  if (!url) throw new Error("That Imagine file has no URL yet.");
  const res = await rawFetch(url);
  if (!res.ok) throw new Error("Could not load the Imagine image.");
  const blob = await res.blob();
  const dataUrl = await readImageFile(blob);
  promptImages = [{
    id: `imagine-${Date.now()}`,
    name: String(item.name).replace(/^.*\//, "") || "imagine.png",
    media_type: blob.type || "image/png",
    data_url: dataUrl,
    source_filename: item.name,
  }];
  renderPromptImages();
  applyPromptModeUI(mode);
  const text = String(prompt || "").replace(/^\/fetch\b[\s\S]*/i, "").trim()
    || "Make a 3D model of this product photo. Match the silhouette and major features.";
  composer.setPromptText(text);
  showAiComposePanel();
  promptHistory.setTab("compose");
  return true;
}

async function attachSavedCanvasBoardToPrompt(entry, boardRef) {
  const pid = entry.projectId || projectId;
  const board = await api(`/api/projects/${pid}/canvas-board?name=${encodeURIComponent(boardRef.name)}`);
  const snapshot = await renderCanvasBoardSnapshot(board?.state || {}, { fetchFile: (url) => rawFetch(url) });
  if (!snapshot?.data_url) throw new Error("Could not render that canvas.");
  attachCanvasSketchImage(snapshot.data_url, "design", snapshot.drawing_metadata, boardRef.name);
  attachCanvasGoalMetadata({
    elements: board?.state?.elements || [],
    boardName: boardRef.name,
    description: board?.state?.description || "",
  });
  showAiComposePanel();
}

async function sendBrowserImagineOrReferenceToPrompt(entry) {
  if (!entry) return;
  const boardRef = canvasBoardFromBrowserEntry(entry) || canvasBoardReference(entry);
  if (boardRef) {
    try {
      await attachSavedCanvasBoardToPrompt(entry, boardRef);
      return;
    } catch (err) {
      const fallback = pickBrowserFolderImage(entry);
      if (fallback && fallback !== entry && fallback.name) {
        await sendBrowserImagineOrReferenceToPrompt(fallback);
        return;
      }
      throw err;
    }
  }
  if (entry.virtual_folder) {
    const image = pickBrowserFolderImage(entry);
    if (image?.name) {
      await sendBrowserImagineOrReferenceToPrompt(image);
      return;
    }
    if (isProjectCodeFolder(entry) || flattenFolderFiles(entry).some((row) => isCodeFilename(row.name))) {
      await attachCodeFolderToPrompt(entry);
      return;
    }
    return;
  }
  if (!entry.name) return;
  if (isImagineRel(entry.name)) {
    if (/\.(step|stp|stl|glb|gltf|3mf)$/i.test(entry.name)) {
      await openBrowserComponent(entry);
      sendSelectedObjectToAi(entry);
      return;
    }
    await openReferenceFile(entry);
    showImaginePanel();
    return;
  }
  await openReferenceFile(entry);
  await referenceFilesViewer.sendToPrompt?.(entry.name);
}

async function sendImagineItemToCad(item, opts = {}) {
  const ready = await attachImagineItemToPrompt(item, { ...opts, mode: "v2" });
  if (ready) return handlePromptGenerateClick({ source: "ui" });
}

async function sendImagineItemToMesh(item, opts = {}) {
  const ready = await attachImagineItemToPrompt(item, { ...opts, mode: "mesh" });
  if (ready) return handlePromptGenerateClick({ source: "ui" });
}

