async function reuseUnifiedPromptHistoryEntry(entry, { useOriginal = true } = {}) {
  const kind = String(entry?.kind || "cad").toLowerCase();
  if (kind === "rigging") {
    cadComposeRigging = true;
    pendingCadRigPick = false;
    syncCadComposeRiggingUi();
    await reusePromptHistoryEntry(entry, { useOriginal });
    return "compose";
  }
  if (kind === "imagine") {
    showImaginePanel();
    imagineUi?.loadHistoryEntry?.(entry, { useOriginal });
    return "imagine";
  }
  if (kind === "wiring") {
    workspaceModes?.setMode?.("wiring");
    applyWorkspaceMode("wiring");
    const original = String(entry.original_prompt || "").trim();
    const improved = String(entry.prompt || "").trim();
    const text = useOriginal ? (original || improved) : (improved || original);
    const refs = wiringPromptReferencesForReuse(entry);
    if (wiringComposer) {
      wiringComposer.clearReferences();
      wiringComposer.replaceReferences(refs);
      wiringComposer.setPromptText(text);
      wiringComposer.editor?.focus?.();
    } else {
      const ta = document.getElementById("wiring-prompt-input");
      if (ta) {
        ta.value = text;
        ta.focus();
      }
    }
    wiringPromptRefs = refs;
    renderWiringPromptRefs();
    const refCount = wiringPromptRefs.length;
    const status = document.getElementById("wiring-prompt-status");
    if (status) {
      status.className = "status ok";
      status.textContent = refCount
        ? `Reused wiring prompt with ${refCount} linked reference${refCount === 1 ? "" : "s"}.`
        : "Reused wiring prompt.";
    }
    return false;
  }
  await reusePromptHistoryEntry(entry, { useOriginal });
  return "compose";
}

async function reusePromptHistoryEntry(entry, { useOriginal = true } = {}) {
  if (!entry) return false;
  const original = String(entry.original_prompt || "").trim();
  const improved = String(entry.prompt || "").trim();
  const text = useOriginal ? (original || improved) : (improved || original);
  if (!text) return false;
  const reusedMode = generationPromptMode({ prompt_mode: entry.prompt_mode }, promptMode);
  if (CAD_OR_MESH_MODES.includes(reusedMode) || reusedMode === "draw" || reusedMode === "standard") {
    applyPromptModeUI(reusedMode === "standard" ? "render" : reusedMode);
  }
  const refs = promptHistoryReferencesForReuse(entry);
  restoringModelPromptState = true;
  composer.setPromptText(text);
  composer.replaceReferences(refs);
  promptImages = await restorePromptHistoryImages(entry);
  restoringModelPromptState = false;
  renderPromptImages();
  saveActiveModelPromptState();
  document.getElementById("prompt-input")?.focus();
  const refCount = refs.length;
  const imgCount = promptImages.length;
  const parts = [];
  if (refCount) parts.push(`${refCount} reference${refCount === 1 ? "" : "s"}`);
  if (imgCount) parts.push(`${imgCount} image${imgCount === 1 ? "" : "s"}`);
  const which = useOriginal && original && original !== improved ? "original prompt" : "prompt";
  setEditStatus("ok", parts.length ? `Reused ${which} with ${parts.join(" and ")}.` : `Reused ${which}.`);
  return true;
}

