/** ChatGPT device-auth subscription can drive CAD 2.0 / Architect via Codex CLI. */
function chatgptSubscriptionReady(status = aiStatus) {
  return !!(status?.chatgpt_signed_in || status?.chatgpt?.signed_in);
}

function chatgptTrialRemaining(status = aiStatus) {
  const trial = status?.credits?.trial || status?.chatgpt || {};
  if (String(trial.kind || status?.chatgpt?.source || "") === "chatgpt_renders"
    || status?.chatgpt?.source === "trial") {
    return Math.max(0, Number(trial.renders_remaining ?? status?.chatgpt?.renders_remaining ?? 0));
  }
  if (status?.chatgpt?.source === "trial") {
    return Math.max(0, Number(status.chatgpt.renders_remaining || 0));
  }
  const remaining = Number(status?.credits?.trial?.renders_remaining);
  if (status?.credits?.trial?.kind === "chatgpt_renders") {
    return Math.max(0, remaining || 0);
  }
  return null;
}

function chatgptPickerLabel(status = aiStatus) {
  const source = String(status?.chatgpt?.source || "");
  const remaining = chatgptTrialRemaining(status);
  if (source === "trial" || (status?.credits?.trial?.kind === "chatgpt_renders" && remaining != null && remaining > 0 && !["self", "team", "personal"].includes(source))) {
    const n = remaining == null ? 0 : remaining;
    return n === 1 ? "OpenAI Sub · 1 left" : `OpenAI Sub · ${n} left`;
  }
  if (["team", "personal"].includes(source) && status?.chatgpt?.owner_name) {
    return `OpenAI Sub · ${status.chatgpt.owner_name}`;
  }
  return "OpenAI Sub";
}

function cursorSubscriptionReady(status = aiStatus) {
  return false;
}

function claudeSubscriptionReady(status = aiStatus) {
  return !!(status?.claude_signed_in || status?.claude?.signed_in);
}

function anyCliSubscriptionReady(status = aiStatus) {
  return chatgptSubscriptionReady(status) || cursorSubscriptionReady(status) || claudeSubscriptionReady(status);
}

function cursorPickerLabel(status = aiStatus) {
  if (status?.cursor?.source === "team" && status?.cursor?.owner_name) {
    return `Cursor · ${status.cursor.owner_name}`;
  }
  return "Cursor subscription";
}

function claudePickerLabel(status = aiStatus) {
  if (["team", "personal"].includes(status?.claude?.source) && status?.claude?.owner_name) {
    return `Claude · ${status.claude.owner_name}`;
  }
  return "Claude subscription";
}

function isCliSubscriptionPickerSource(source) {
  const s = String(source || "").toLowerCase();
  return s === "chatgpt" || s === "subscription" || s === "cursor" || s === "claude";
}

function flattenAiKeysResponse(data) {
  if (!data) return null;
  if (data.ai) return { ...data.ai, keys: data.keys || data.ai.keys || [] };
  return data;
}

async function hydrateAiKeysFromServer() {
  try {
    const data = await api("/api/user/ai-keys?full=true");
    const status = flattenAiKeysResponse(data);
    if (!status) return null;
    aiKeyUi?.render(status);
    return status;
  } catch (err) {
    console.warn("AI keys hydrate failed:", err);
    return null;
  }
}

function refreshTrialRenderCount() {
  void refreshPromptAiKeysFromServer();
}

async function refreshPromptAiKeysFromServer({ announceIfNew = false, selectChatgpt = false } = {}) {
  try {
    const data = await api("/api/user/ai-keys?full=true");
    const status = flattenAiKeysResponse(data);
    applyPromptAiStatus(status, { announceIfNew, selectChatgpt });
    return status;
  } catch {
    return null;
  }
}

function chatgptSubscriptionModelReady(model = loadChatgptCodexModel()) {
  const m = String(model || "").toLowerCase();
  return m.startsWith("gpt-6-astra") || m.startsWith("gpt-6.1-sol") || m.startsWith("gpt-5.6-");
}

function promptPathReady(mode = promptMode) {
  if (aiStatus?.ai_ready) return true;
  const m = String(mode || "").toLowerCase();
  const cadModes = ["v2", "architect", "vibecad", "mac", "mesh", "mesh_beta", "mesh-beta", "wiring", "rigging"];
  let cadEngine = false;
  try {
    const engine = getPromptCadEngine?.();
    cadEngine = engine === "vibecad" || engine === "mac";
  } catch {
    /* ignore */
  }
  if (!cadModes.includes(m) && !cadEngine) return false;
  const picked = getSelectedPromptAiKey();
  const source = String(picked?.source || "");
  if (source === "cursor") return cursorSubscriptionReady();
  if (source === "claude") return claudeSubscriptionReady();
  if (source === "chatgpt" || source === "subscription") {
    return chatgptSubscriptionReady() && chatgptSubscriptionModelReady();
  }
  if (cursorSubscriptionReady() || claudeSubscriptionReady()) return true;
  if (!chatgptSubscriptionReady()) return false;
  return chatgptSubscriptionModelReady();
}

/** Codex CLI is opt-in for Jake 2.0 / Architect — never VibeCAD, never auto-on for Sol. */
function isCodexEnabled(mode = promptMode) {
  if (!selectedPromptSupportsCodex(mode)) return false;
  const input = document.getElementById("prompt-codex");
  if (input) return Boolean(input.checked);
  try {
    return localStorage.getItem(CODEX_KEY) === "1"
      || localStorage.getItem(CODEX_KEY_LEGACY) === "1";
  } catch {
    return false;
  }
}

function listOpenAiKeysForCodex(status = aiStatus) {
  const isOpenAi = (key) => String(key?.provider || "openai").toLowerCase() === "openai";
  const personal = (status?.keys || [])
    .filter(isOpenAi)
    .map((key) => ({ ...key, source: "personal" }));
  const team = (status?.team_keys || [])
    .filter((key) => key.enabled !== false && aiKeyAllowedForCurrentProject(key) && isOpenAi(key))
    .map((key) => ({ ...key, source: "team" }));
  return [...personal, ...team];
}

function getStoredCodexOpenAiKeyValue() {
  try {
    return localStorage.getItem(CODEX_OPENAI_KEY) || "";
  } catch {
    return "";
  }
}

function storeCodexOpenAiKeyValue(value) {
  try {
    if (value) localStorage.setItem(CODEX_OPENAI_KEY, value);
    else localStorage.removeItem(CODEX_OPENAI_KEY);
  } catch {
    /* ignore */
  }
}

let aiPromptStatusHydrated = false;
let lastAiReadyAnnounce = "";
let lastAiReadyAnnounceAt = 0;

function announcePromptAiReady(preview) {
  const text = String(preview || "").trim();
  if (!text) return;
  const now = Date.now();
  if (text === lastAiReadyAnnounce && now - lastAiReadyAnnounceAt < 15000) return;
  lastAiReadyAnnounce = text;
  lastAiReadyAnnounceAt = now;
  setEditStatus("ok", text);
  try {
    renderAgentUi?.announce?.(text, { openPanel: false, ping: true });
  } catch {
    try {
      renderAgentUi?.openFromAlert?.({ preview: text, open_agent: false, ping: true });
    } catch {
      /* ignore */
    }
  }
}

function applyPromptAiStatus(status, { announceIfNew = false, selectChatgpt = false, selectCursor = false, selectClaude = false } = {}) {
  if (!status) return;
  const prevChatgpt = chatgptSubscriptionReady(aiStatus);
  const prevCursor = cursorSubscriptionReady(aiStatus);
  const prevClaude = claudeSubscriptionReady(aiStatus);
  const prevKeyIds = new Set(
    [...(aiStatus?.keys || []), ...(aiStatus?.team_keys || [])].map((k) => String(k.id || "")),
  );
  const hadStatus = aiPromptStatusHydrated;
  renderAIStatus(status);
  const voiceAccess = voiceSubscriptionAccess(aiStatus, xrAgent?.getState?.()?.settings?.voiceModel || "");
  const voiceLive = !!(voiceMold?.getState?.()?.live || xrAgent?.getState?.()?.live);
  if (!voiceAccess.allowed && voiceLive) void finalizeHeyAiContext({ stopVoice: true });
  syncVoiceOrderControls();
  aiPromptStatusHydrated = true;
  const pinned = getPinnedPromptKey(status);
  if (pinned && !getSelectedPromptAiKey()) {
    selectPromptAiKeyValue(pinned);
    return;
  }
  if (getSelectedPromptAiKey()) {
    /* Keep the key the user clicked (GPT vs Fable) over pin/hydrate. */
  } else if (selectCursor && cursorSubscriptionReady(status)) {
    selectPromptAiKeyValue(promptKeyOptionValue("cursor", "subscription"));
  } else if (selectClaude && claudeSubscriptionReady(status)) {
    selectPromptAiKeyValue(promptKeyOptionValue("claude", "subscription"));
  } else if (selectChatgpt && chatgptSubscriptionReady(status)) {
    selectPromptAiKeyValue(promptKeyOptionValue("chatgpt", "subscription"));
    try {
      if (selectedPromptSupportsCodex()) setCodexEnabled(true);
    } catch {
      /* ignore */
    }
  }
  if (!announceIfNew || !hadStatus) return;
  if (cursorSubscriptionReady(status) && !prevCursor) {
    if (!selectCursor) selectPromptAiKeyValue(promptKeyOptionValue("cursor", "subscription"));
    announcePromptAiReady(
      "Your Cursor subscription is connected. It’s in the prompt key menu now — pick Auto, Grok 4.6, Composer, or Sonnet for CAD.",
    );
    return;
  }
  if (claudeSubscriptionReady(status) && !prevClaude) {
    if (!selectClaude) selectPromptAiKeyValue(promptKeyOptionValue("claude", "subscription"));
    announcePromptAiReady(
      "Your Claude subscription is connected. It’s in the prompt key menu now — CAD 2.0, Architect, VibeCAD, and Mesh run on that plan.",
    );
    return;
  }
  if (chatgptSubscriptionReady(status) && !prevChatgpt) {
    if (!selectChatgpt) {
      selectPromptAiKeyValue(promptKeyOptionValue("chatgpt", "subscription"));
      try {
        if (selectedPromptSupportsCodex()) setCodexEnabled(true);
      } catch {
        /* ignore */
      }
    }
    announcePromptAiReady(
      "Your ChatGPT subscription is connected. It’s in the prompt key menu now — pick GPT-5.6 Sol, Terra, Luna, Astra, or Astra Pro for CAD.",
    );
    return;
  }
  const added = [...(status.keys || []), ...(status.team_keys || [])].filter(
    (k) => k.id && !prevKeyIds.has(String(k.id)),
  );
  if (added.length) {
    const key = added[0];
    const isTeam = (status.team_keys || []).some((row) => row.id === key.id);
    const label = key.name || key.provider_label || "API key";
    if (key.id) selectPromptAiKeyValue(promptKeyOptionValue(isTeam ? "team" : (key.source || "personal"), key.id));
    announcePromptAiReady(`${label} is saved. You’ll see it in the prompt key menu — pick it before you generate.`);
  }
}

function selectPromptAiKeyValue(value) {
  const sel = document.getElementById("prompt-ai-key-select");
  if (!value) return false;
  storePromptAiKeyValue(value);
  if (sel && ![...sel.options].some((opt) => opt.value === value)) {
    renderPromptAiKeySelect(aiStatus, { preserveSelection: false });
  }
  if (!sel || ![...sel.options].some((opt) => opt.value === value)) return false;
  sel.value = value;
  const parsed = parsePromptKeyOptionValue(value);
  if (!(parsed?.source === "platform" && parsed.keyId === "anthropic")) {
    storeCodexOpenAiKeyValue(value);
  }
  syncPromptKeyPill(aiStatus);
  if (promptKeyPopupOpen) renderPromptKeyPopup(aiStatus);
  return true;
}

function applyCodexOpenAiKey(key) {
  if (!key?.id) return false;
  const value = promptKeyOptionValue(key.source || "personal", key.id);
  storeCodexOpenAiKeyValue(value);
  return true;
}

function askCodexOpenAiKey(keys) {
  // In XR, auto-pick a stored/first OpenAI key so Run AI never stalls on a desktop modal.
  if (
    (promptSubmitOpts?.source === "xr"
      || document.body.classList.contains("xr-presenting")
      || viewportXR?.isPresenting?.())
    && Array.isArray(keys)
    && keys.length
  ) {
    const preferred = getStoredCodexOpenAiKeyValue()
      || getStoredProjectPromptAiKeyValue()
      || getStoredPromptAiKeyValue()
      || "";
    const match = keys.find((key) => promptKeyOptionValue(key.source || "personal", key.id) === preferred)
      || keys[0];
    return Promise.resolve(match || null);
  }
  return new Promise((resolve) => {
    const modal = document.getElementById("codex-openai-key-modal");
    const list = document.getElementById("codex-openai-key-list");
    const confirmBtn = document.getElementById("codex-openai-key-confirm");
    if (!modal || !list || !keys.length) {
      resolve(null);
      return;
    }
    const preferred = getStoredCodexOpenAiKeyValue()
      || getStoredProjectPromptAiKeyValue()
      || getStoredPromptAiKeyValue()
      || "";
    list.innerHTML = keys.map((key, index) => {
      const value = promptKeyOptionValue(key.source || "personal", key.id);
      const checked = preferred === value || (!preferred && index === 0);
      const model = key.model || key.effective_model || "";
      const sourceLabel = key.source === "team" ? "Shared" : "Personal";
      const name = key.name || "OpenAI key";
      return `
        <label class="codex-openai-key-option">
          <input type="radio" name="codex-openai-key" value="${appEscapeHtml(value)}" ${checked ? "checked" : ""} />
          <span class="codex-openai-key-option-body">
            <strong>${appEscapeHtml(name)}</strong>
            <span class="muted small">${appEscapeHtml(sourceLabel)}${model ? ` · ${appEscapeHtml(formatModelLabel(model, "openai") || model)}` : ""}</span>
          </span>
        </label>
      `;
    }).join("");

    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey);
      confirmBtn?.removeEventListener("click", onConfirm);
      closeEls.forEach((el) => el.removeEventListener("click", onCancel));
      modal.classList.add("hidden");
      resolve(value);
    };
    const onConfirm = () => {
      const picked = list.querySelector('input[name="codex-openai-key"]:checked')?.value || "";
      if (!picked) return;
      const key = keys.find((row) => promptKeyOptionValue(row.source || "personal", row.id) === picked);
      finish(key || null);
    };
    const onCancel = () => finish(null);
    const onKey = (e) => {
      if (e.key === "Escape") finish(null);
    };
    const closeEls = [...modal.querySelectorAll("[data-codex-key-close]")];
    confirmBtn?.addEventListener("click", onConfirm);
    closeEls.forEach((el) => el.addEventListener("click", onCancel));
    document.addEventListener("keydown", onKey);
    modal.classList.remove("hidden");
  });
}

async function ensureCodexOpenAiKey({ interactive = true } = {}) {
  if (chatgptSubscriptionReady()) {
    return { source: "chatgpt", id: "subscription", provider: "openai" };
  }
  const selectedKey = getSelectedPromptAiKey();
  if (selectedKey?.source === "cursor" && cursorSubscriptionReady()) {
    return { source: "cursor", id: "subscription", provider: "cursor" };
  }
  if (selectedKey?.source === "claude" && claudeSubscriptionReady()) {
    return { source: "claude", id: "subscription", provider: "anthropic" };
  }
  const keys = listOpenAiKeysForCodex();
  if (!keys.length) {
    if (interactive) {
      const status = document.getElementById("prompt-status");
      if (status) {
        status.className = "status error";
        status.textContent = "Codex needs an OpenAI API key. Add one to continue.";
      }
      aiKeyUi?.openRequired?.({
        preferProvider: "openai",
        message: "Codex requires an OpenAI API key. Add one below (Claude keys won't work for Codex).",
        openAdd: true,
      });
    }
    return null;
  }
  if (keys.length === 1) {
    applyCodexOpenAiKey(keys[0]);
    return keys[0];
  }

  const preferredValue = getStoredCodexOpenAiKeyValue()
    || (() => {
      const picked = getSelectedPromptAiKey();
      const match = keys.find((key) => key.id === picked?.keyId && key.source === picked?.source);
      return match ? promptKeyOptionValue(match.source, match.id) : "";
    })()
    || "";
  // Enabling with multiple keys: always ask which OpenAI key to use.
  if (!interactive) {
    const current = getSelectedPromptAiKey();
    const match = keys.find((key) => key.id === current?.keyId && key.source === current?.source);
    if (match) {
      storeCodexOpenAiKeyValue(promptKeyOptionValue(match.source, match.id));
      return match;
    }
    const stored = keys.find((key) => promptKeyOptionValue(key.source, key.id) === preferredValue);
    if (stored) {
      applyCodexOpenAiKey(stored);
      return stored;
    }
    applyCodexOpenAiKey(keys[0]);
    return keys[0];
  }

  const picked = await askCodexOpenAiKey(keys);
  if (!picked) return null;
  applyCodexOpenAiKey(picked);
  return picked;
}

function setCodexEnabled(enabled, { persist = true } = {}) {
  const input = document.getElementById("prompt-codex");
  if (input) input.checked = Boolean(enabled);
  if (persist) {
    try {
      localStorage.setItem(CODEX_KEY, enabled ? "1" : "0");
      localStorage.removeItem(CODEX_KEY_LEGACY);
    } catch {
      /* ignore */
    }
  }
  syncCodexToggleVisibility();
}

function selectedPromptSupportsCodex(mode = promptMode) {
  const m = String(mode || "").toLowerCase();
  if (m === "vibecad" || m === "mac") return false;
  if (m === "v2") {
    try {
      const engine = getPromptCadEngine();
      if (engine === "vibecad" || engine === "mac") return false;
    } catch {
      /* ignore */
    }
  }
  if (!["v2", "architect"].includes(m)) return false;
  const picked = getSelectedPromptAiKey();
  if (isCliSubscriptionPickerSource(picked?.source)) return false;
  const { provider } = getSelectedPromptModelInfo();
  return String(provider || "").toLowerCase() === "openai";
}

/** Do not auto-enable Codex CLI when the user picked Sol / another OpenAI chat model. */
function selectedPromptShouldAutoCodex(_mode = promptMode) {
  return false;
}

/** Last provider we auto-applied agent/engine defaults for (avoids fighting manual Jake). */
let _lastAutoAgentProvider = null;

/**
 * Keep Codex toggle visibility in sync with the active key.
 * Do not auto-switch CAD engine to VibeCAD or force Codex CLI on.
 */
function syncAgentDefaultsForSelectedKey(mode = promptMode) {
  const m = String(mode || promptMode || "").toLowerCase();
  syncCodexToggleVisibility(m);
  if (m !== "v2" && m !== "architect") {
    _lastAutoAgentProvider = null;
    return;
  }
  const { provider } = getSelectedPromptModelInfo();
  const prov = String(provider || "").toLowerCase();
  _lastAutoAgentProvider = prov || null;
}

function rememberSelectedOpenAiKeyForCodex() {
  const picked = getSelectedPromptAiKey();
  if (!picked?.keyId) return false;
  const keys = listOpenAiKeysForCodex();
  const match = keys.find((key) => key.id === picked.keyId && key.source === picked.source);
  if (!match) return false;
  storeCodexOpenAiKeyValue(promptKeyOptionValue(match.source, match.id));
  return true;
}

function syncCodexToggleVisibility(mode = promptMode) {
  const wrap = document.getElementById("prompt-codex-wrap")
    || document.getElementById("prompt-codex-toggle");
  if (!wrap) return;
  const input = document.getElementById("prompt-codex");
  const show = selectedPromptSupportsCodex(mode);
  wrap.classList.toggle("hidden", !show);
  if (!show) {
    if (input) input.checked = false;
    try {
      localStorage.removeItem(CODEX_KEY);
      localStorage.removeItem(CODEX_KEY_LEGACY);
    } catch {
      /* ignore */
    }
    return;
  }
  // Respect the user's Codex toggle. OpenAI Sol/5.6 uses Jake's tool agent, not Codex CLI.
  let stored = false;
  try {
    stored = localStorage.getItem(CODEX_KEY) === "1"
      || localStorage.getItem(CODEX_KEY_LEGACY) === "1";
  } catch {
    stored = false;
  }
  if (input) input.checked = stored;
}

async function handleCodexToggleChange(wantEnabled) {
  if (!wantEnabled) {
    setCodexEnabled(false);
    return;
  }
  if (!selectedPromptSupportsCodex()) {
    setCodexEnabled(false);
    const status = document.getElementById("prompt-status");
    if (status) {
      status.className = "status error";
      status.textContent = "Codex is only available with an OpenAI prompt key. Claude/Fable runs directly through Anthropic.";
    }
    return;
  }
  // Optimistic UI: keep checked while we validate; revert on failure/cancel.
  setCodexEnabled(true, { persist: false });
  const key = await ensureCodexOpenAiKey({ interactive: true });
  if (!key) {
    setCodexEnabled(false);
    return;
  }
  setCodexEnabled(true);
}

function reconcileCodexToggleWithKeys() {
  if (anyCliSubscriptionReady() && isCliSubscriptionPickerSource(getSelectedPromptAiKey()?.source)) return;
  if (!isCodexEnabled()) return;
  const keys = listOpenAiKeysForCodex();
  if (!keys.length) {
    setCodexEnabled(false);
    return;
  }
  if (keys.length === 1) {
    applyCodexOpenAiKey(keys[0]);
    return;
  }
  const current = getSelectedPromptAiKey();
  const match = keys.find((key) => key.id === current?.keyId && key.source === current?.source);
  if (match) {
    storeCodexOpenAiKeyValue(promptKeyOptionValue(match.source, match.id));
    return;
  }
  const stored = keys.find((key) => promptKeyOptionValue(key.source, key.id) === getStoredCodexOpenAiKeyValue());
  if (stored) applyCodexOpenAiKey(stored);
}

(() => {
  let enabled = false;
  try {
    enabled = localStorage.getItem(CODEX_KEY) === "1"
      || localStorage.getItem(CODEX_KEY_LEGACY) === "1";
  } catch {
    enabled = false;
  }
  const input = document.getElementById("prompt-codex");
  if (input) {
    input.checked = enabled;
    input.addEventListener("change", () => {
      void handleCodexToggleChange(input.checked);
    });
  }
  syncCodexToggleVisibility();
})();

function getPromptGenerationSpeed() {
  return document.getElementById("prompt-speed")?.value === "quality" ? "quality" : "fast";
}

const SPICE_KEY = "render3d:spice-prompt:v2";
const SPICE_COMPARE_KEY = "render3d:spice-prompt-compare:v1";
const DEFAULT_SPICE_ENABLED = true;

/** @type {{ original: string, improved: string, unchanged?: boolean, at?: string } | null} */
let lastSpicePromptCompare = null;
let spiceCompareModalState = null;

function isSpiceEnabled() {
  const btn = document.getElementById("prompt-spice");
  if (!btn) return DEFAULT_SPICE_ENABLED;
  return btn.getAttribute("aria-pressed") === "true";
}

function spicePrefStorageKey(pid = projectId) {
  return pid ? `${SPICE_KEY}:${pid}` : null;
}

function readLegacySpiceEnabled() {
  try {
    const saved = localStorage.getItem(SPICE_KEY);
    if (saved === "1") return true;
    if (saved === "0") return false;
  } catch {
    /* local storage is best-effort */
  }
  return DEFAULT_SPICE_ENABLED;
}

function readProjectSpiceEnabled(pid = projectId) {
  const key = spicePrefStorageKey(pid);
  if (!key) return DEFAULT_SPICE_ENABLED;
  try {
    const raw = localStorage.getItem(key);
    if (raw === "1") return true;
    if (raw === "0") return false;
  } catch {
    /* local storage is best-effort */
  }
  return readLegacySpiceEnabled();
}

function persistProjectSpiceEnabled(enabled, pid = projectId) {
  if (!pid || newProjectPending) return;
  const key = spicePrefStorageKey(pid);
  if (!key) return;
  try {
    localStorage.setItem(key, enabled ? "1" : "0");
  } catch {
    /* local storage is best-effort */
  }
}

function applyProjectSpicePreference(pid = projectId) {
  setSpiceEnabled(readProjectSpiceEnabled(pid), { persist: false });
}

function setSpiceEnabled(enabled, { persist = true } = {}) {
  const btn = document.getElementById("prompt-spice");
  const on = Boolean(enabled);
  if (btn) {
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("is-on", on);
    syncSpiceTipForPromptMode(promptMode);
  }
  if (persist) persistProjectSpiceEnabled(on);
}

function syncSpiceTipForPromptMode(mode = promptMode) {
  const tip = document.getElementById("prompt-spice-tip");
  const btn = document.getElementById("prompt-spice");
  const titleEl = tip?.querySelector(".prompt-spice-tip-title");
  const bodyEl = tip?.querySelector(".prompt-spice-tip-body");
  const listEl = tip?.querySelector(".prompt-spice-tip-list");
  const normalized = String(mode || "").toLowerCase();
  const on = isSpiceEnabled();
  let title = "Improve prompt with AI";
  let body = "";
  let items = [];
  let btnTitle = on ? "Improve prompt with AI — on" : "Improve prompt with AI — off";

  if (normalized === "mesh" || normalized === "fusion" || normalized === "mesh_beta" || normalized === "mesh-beta") {
    const beta = normalized === "mesh_beta" || normalized === "mesh-beta"
      || (normalized === "mesh" && typeof getPromptMeshEngine === "function" && getPromptMeshEngine() === "beta");
    if (beta) {
      title = "Clarify Mesh intent";
      body =
        "Keep your prompt. AI adds one short clarification so the engineering mesh model can understand your intent.";
      items = [
        "Adds to the end instead of rewriting",
        "Does not invent missing details",
        "Tap to turn improve on or off",
      ];
      btnTitle = on
        ? "Improve Mesh Beta prompt — on"
        : "Improve Mesh Beta prompt — off";
    } else {
      title = "Clarify Mesh intent";
      body =
        "Keep your prompt. AI adds one short clarification so the engineering mesh model can understand your intent.";
      items = [
        "Adds to the end instead of rewriting",
        "Does not invent missing details",
        "Tap to turn improve on or off",
      ];
      btnTitle = on
        ? "Improve Mesh prompt — on"
        : "Improve Mesh prompt — off";
    }
  } else if (normalized === "render" || normalized === "standard") {
    title = "Improve for photoreal render";
    body =
      "In <b>Render</b>, Improve locks the <b>exact 3D model and camera facing</b> from the viewport, "
      + "then writes object-only materials so the look wraps the mesh — not the whole scene.";
    items = [
      "Same model, pose, and facing as the viewport",
      "Materials on the object only (texture wrap)",
      "Scene and lighting around the model",
    ];
    btnTitle = on ? "Improve render prompt — on" : "Improve render prompt — off";
  } else {
    title = "Clarify CAD intent";
    body =
      "Keep your prompt. AI adds one short clarification so the engineering CAD model can understand your intent.";
    items = [
      "Adds to the end instead of rewriting",
      "Does not invent dimensions or requirements",
      "Tap to turn improve on or off",
    ];
    btnTitle = on ? "Improve CAD prompt — on" : "Improve CAD prompt — off";
  }

  if (promptHasCanvasSketchImage()) {
    title = "Clarify intent from canvas";
    body =
      "Keep your prompt. AI reads the drawing and adds one short clarification about the relationship you intended.";
    items = [
      "Adds to the end instead of rewriting",
      "Uses drawings only to clarify intent",
      "Does not invent missing details",
    ];
    btnTitle = on ? "Improve canvas prompt — on" : "Improve canvas prompt — off";
  }

  if (titleEl) titleEl.textContent = title;
  if (bodyEl) bodyEl.innerHTML = body;
  if (listEl) {
    listEl.innerHTML = items.map((item) => `<li>${item}</li>`).join("");
  }
  if (btn) btn.title = btnTitle;
}

function loadSpicePromptCompare() {
  try {
    const raw = sessionStorage.getItem(SPICE_COMPARE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return null;
    const original = String(parsed.original || "").trim();
    const improved = String(parsed.improved || "").trim();
    if (!original || !improved) return null;
    return {
      original,
      improved,
      unchanged: Boolean(parsed.unchanged) || original === improved,
      at: parsed.at ? String(parsed.at) : undefined,
    };
  } catch {
    return null;
  }
}

function saveSpicePromptCompare(compare) {
  lastSpicePromptCompare = compare;
  try {
    if (!compare) {
      sessionStorage.removeItem(SPICE_COMPARE_KEY);
    } else {
      sessionStorage.setItem(SPICE_COMPARE_KEY, JSON.stringify(compare));
    }
  } catch {
    /* ignore */
  }
  syncSpiceCompareViewButton();
}

function syncSpiceCompareViewButton() {
  /* Compare opens from history; toolbar eye control removed. */
}

function closeSpiceCompareModal() {
  const modal = document.getElementById("prompt-spice-compare-modal");
  if (!modal) return;
  modal.classList.add("hidden");
  spiceCompareModalState = null;
}

function openSpiceCompareModal(compareOverride = null) {
  const compare = compareOverride || lastSpicePromptCompare || loadSpicePromptCompare();
  if (!compare?.original && !compare?.improved) return;
  if (!compareOverride) lastSpicePromptCompare = compare;
  spiceCompareModalState = compare;
  const modal = document.getElementById("prompt-spice-compare-modal");
  const originalEl = document.getElementById("prompt-spice-original");
  const improvedEl = document.getElementById("prompt-spice-improved");
  const noteEl = document.getElementById("prompt-spice-compare-note");
  if (!modal || !originalEl || !improvedEl) return;
  const originalText = String(compare.original || "").trim();
  const improvedText = String(compare.improved || "").trim();
  originalEl.textContent = originalText || "(Original prompt was not saved for this run.)";
  improvedEl.textContent = improvedText || originalText || "(No improved prompt.)";
  originalEl.classList.toggle("is-missing", !originalText);
  improvedEl.classList.toggle("is-same", Boolean(originalText && improvedText && originalText === improvedText));
  if (noteEl) {
    if (compare.note) {
      noteEl.textContent = compare.note;
    } else if (compare.unchanged || (originalText && originalText === improvedText)) {
      noteEl.textContent = "The improved prompt matched your original — nothing was changed.";
    } else if (compare.fromHistory && !compare.promptImproved) {
      noteEl.textContent = "Full prompt text from history.";
    } else {
      noteEl.textContent = "Original wording is on the left. The AI rewrite used for generation is on the right. Click a prompt to load it.";
    }
  }
  modal.classList.remove("hidden");
}

async function applySpiceComparePrompt(useOriginal) {
  const compare = spiceCompareModalState;
  if (!compare) return;
  if (compare.entry) {
    await reusePromptHistoryEntry(compare.entry, { useOriginal: Boolean(useOriginal) });
  } else {
    const text = String(useOriginal ? compare.original : compare.improved || compare.original || "").trim();
    if (text) composer.setPromptText(text);
    document.getElementById("prompt-input")?.focus();
    setEditStatus("ok", useOriginal ? "Loaded original prompt." : "Loaded improved prompt.");
  }
  closeSpiceCompareModal();
}

function initPromptSpiceToggle() {
  // New projects default ON. Per-project :pid keys keep an explicit Off.
  // Bare SPICE_KEY ("0"/"1") is legacy account fallback for older projects.
  const enabled = projectId ? readProjectSpiceEnabled(projectId) : DEFAULT_SPICE_ENABLED;
  const btn = document.getElementById("prompt-spice");
  if (!btn) return;
  setSpiceEnabled(enabled, { persist: false });
  btn.addEventListener("click", () => {
    setSpiceEnabled(!isSpiceEnabled());
  });

  lastSpicePromptCompare = loadSpicePromptCompare();
  syncSpiceCompareViewButton();

  initPromptSpiceHoverTip();

  const modal = document.getElementById("prompt-spice-compare-modal");
  modal?.querySelectorAll("[data-spice-compare-close]").forEach((el) => {
    el.addEventListener("click", () => closeSpiceCompareModal());
  });
  document.getElementById("prompt-spice-use-original")?.addEventListener("click", () => {
    void applySpiceComparePrompt(true);
  });
  document.getElementById("prompt-spice-use-improved")?.addEventListener("click", () => {
    void applySpiceComparePrompt(false);
  });
  document.getElementById("prompt-spice-original")?.addEventListener("click", () => {
    void applySpiceComparePrompt(true);
  });
  document.getElementById("prompt-spice-improved")?.addEventListener("click", () => {
    void applySpiceComparePrompt(false);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    if (!modal || modal.classList.contains("hidden")) return;
    closeSpiceCompareModal();
  });
}

function initPromptSpiceHoverTip() {
  const wrap = document.getElementById("prompt-spice-wrap");
  const tip = document.getElementById("prompt-spice-tip");
  if (wrap && tip) bindFixedHoverTip(wrap, tip, { width: 280 });
  const imagineWrap = document.getElementById("imagine-spice-wrap");
  const imagineTip = document.getElementById("imagine-spice-tip");
  if (imagineWrap && imagineTip) bindFixedHoverTip(imagineWrap, imagineTip, { width: 300 });
}

const CAD_DEBUG_KEY = "render3d:cad-debug:v1";
const DEFAULT_CAD_DEBUG_ENABLED = false;
const MICRO_EDITS_KEY = "render3d:micro-edits:v1";
const DEFAULT_MICRO_EDITS_ENABLED = false;
let lastCadDebugSnapshot = { error: "", logs: "", at: 0 };

function isCadDebugEnabled() {
  const btn = document.getElementById("prompt-cad-debug");
  if (!btn) return false;
  return btn.getAttribute("aria-pressed") === "true";
}

function isCadDebugActive(mode = promptMode) {
  if (!isCadDebugEnabled()) return false;
  const m = String(mode || promptMode || "").toLowerCase();
  if (["mesh", "mesh_beta", "mesh-beta", "render", "standard", "imagine", "draw"].includes(m)) return false;
  return isCadHarnessMode(mode) || m === "v2" || m === "architect" || m === "vibecad" || m === "mac";
}

function cadDebugPrefStorageKey(pid = projectId) {
  return pid ? `${CAD_DEBUG_KEY}:${pid}` : null;
}

function readProjectCadDebugEnabled(pid = projectId) {
  const key = cadDebugPrefStorageKey(pid);
  if (!key) return DEFAULT_CAD_DEBUG_ENABLED;
  try {
    const raw = localStorage.getItem(key);
    if (raw === "1") return true;
    if (raw === "0") return false;
  } catch {
    /* local storage is best-effort */
  }
  return DEFAULT_CAD_DEBUG_ENABLED;
}

function persistProjectCadDebugEnabled(enabled, pid = projectId) {
  if (!pid || newProjectPending) return;
  const key = cadDebugPrefStorageKey(pid);
  if (!key) return;
  try {
    localStorage.setItem(key, enabled ? "1" : "0");
  } catch {
    /* local storage is best-effort */
  }
}

function applyProjectCadDebugPreference(pid = projectId) {
  setCadDebugEnabled(readProjectCadDebugEnabled(pid), { persist: false });
}

function setCadDebugEnabled(enabled, { persist = true } = {}) {
  const btn = document.getElementById("prompt-cad-debug");
  const on = Boolean(enabled);
  if (btn) {
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("is-on", on);
    btn.title = on
      ? "CAD Debug — on. Improve and Generate include debug prompts until you turn this off."
      : "CAD Debug — off. When on, Generate and Improve include a debug prompt.";
  }
  if (persist) persistProjectCadDebugEnabled(on);
}

function microEditsPrefStorageKey(pid = projectId) {
  return pid ? `${MICRO_EDITS_KEY}:${pid}` : null;
}

function readProjectMicroEditsEnabled(pid = projectId) {
  const key = microEditsPrefStorageKey(pid);
  if (!key) return DEFAULT_MICRO_EDITS_ENABLED;
  try {
    const raw = localStorage.getItem(key);
    if (raw === "1") return true;
    if (raw === "0") return false;
  } catch {
    /* local storage is best-effort */
  }
  return DEFAULT_MICRO_EDITS_ENABLED;
}

function persistProjectMicroEditsEnabled(enabled, pid = projectId) {
  if (!pid || newProjectPending) return;
  const key = microEditsPrefStorageKey(pid);
  if (!key) return;
  try {
    localStorage.setItem(key, enabled ? "1" : "0");
  } catch {
    /* local storage is best-effort */
  }
}

function applyProjectMicroEditsPreference(pid = projectId) {
  microEditTools?.setEnabled?.(readProjectMicroEditsEnabled(pid), { persist: false });
}

function syncCadDebugToggleVisibility(mode = promptMode) {
  const wrap = document.getElementById("prompt-cad-debug-wrap");
  const tools = document.getElementById("prompt-cad-tools");
  const cad = CAD_HARNESS_MODES.includes(String(mode || "").toLowerCase())
    || String(mode || "").toLowerCase() === "v2";
  if (wrap) wrap.hidden = !cad;
  if (tools) tools.hidden = !cad;
}

function cadDebugSelectedBodies() {
  const names = [];
  const seen = new Set();
  const push = (value) => {
    const name = String(value || "").trim();
    if (!name || seen.has(name)) return;
    seen.add(name);
    names.push(name);
  };
  try {
    const sel = objectTools?.getSelection?.();
    if (sel?.label) push(sel.label);
    if (sel?.catalogName) push(sel.catalogName);
    if (Number.isInteger(sel?.bodyIndex)) push(`body:${sel.bodyIndex}`);
    for (const row of sel?.selections || []) {
      push(row?.label);
      if (Number.isInteger(row?.bodyIndex)) push(`body:${row.bodyIndex}`);
    }
  } catch {
    /* ignore */
  }
  if (selectedFile) push(selectedFile);
  return names.slice(0, 16);
}

function rememberCadDebugFailure(gen = {}) {
  const kind = String(gen.kind || "prompt").toLowerCase();
  if (kind === "wiring" || kind === "rigging" || kind === "imagine" || kind === "render") return;
  const error = String(gen.error || "").trim();
  const activity = gen.progress?.activity || gen.activity || [];
  const logBits = [];
  if (Array.isArray(activity)) {
    for (const row of activity.slice(-8)) {
      const text = String(row?.text || row?.label || row || "").trim();
      if (text) logBits.push(text);
    }
  }
  const thinking = String(gen.progress?.thinking || gen.thinking || "").trim();
  if (thinking) logBits.push(thinking);
  lastCadDebugSnapshot = {
    error: error.slice(0, 1800),
    logs: logBits.join("\n").slice(0, 1800),
    at: Date.now(),
  };
}

function buildCadDebugBriefText() {
  const engine = promptCadEngineLabel(getPromptCadEngine());
  const units = (typeof getUnits === "function" ? getUnits() : "") || "mm";
  const bodies = cadDebugSelectedBodies();
  const lines = [
    "CAD DEBUG BRIEF:",
    `- Engine: ${engine}`,
    `- Units: ${units}`,
  ];
  lines.push(bodies.length ? `- Selected bodies: ${bodies.join(", ")}` : "- Selected bodies: (none)");
  if (lastCadDebugSnapshot.error) lines.push(`- Last error:\n${lastCadDebugSnapshot.error}`);
  else lines.push("- Last error: (none this session)");
  if (lastCadDebugSnapshot.logs) lines.push(`- Kernel / harness logs:\n${lastCadDebugSnapshot.logs}`);
  return lines.join("\n").slice(0, 6000);
}

function getCadDebugBodyFields(mode = promptMode) {
  if (!isCadDebugActive(mode)) return {};
  return { cad_debug: true, cad_debug_brief: buildCadDebugBriefText() };
}

function initPromptCadDebugToggle() {
  const btn = document.getElementById("prompt-cad-debug");
  if (!btn) return;
  setCadDebugEnabled(projectId ? readProjectCadDebugEnabled(projectId) : DEFAULT_CAD_DEBUG_ENABLED, { persist: false });
  syncCadDebugToggleVisibility();
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    setCadDebugEnabled(!isCadDebugEnabled());
  });
  const wrap = document.getElementById("prompt-cad-debug-wrap");
  const tip = document.getElementById("prompt-cad-debug-tip");
  if (wrap && tip) bindFixedHoverTip(wrap, tip, { width: 280 });
}

function setPromptAiGearOpen(open) {
  const host = document.getElementById("prompt-ai-gear-host");
  const popup = document.getElementById("prompt-ai-gear-popup");
  const btn = document.getElementById("prompt-ai-gear");
  const next = Boolean(open);
  if (next) {
    setPromptCadEngineOpen(false);
    setPromptMeshEngineOpen(false);
  }
  if (host) host.dataset.open = next ? "true" : "false";
  if (popup) popup.hidden = !next;
  if (btn) btn.setAttribute("aria-expanded", next ? "true" : "false");
  if (next && popup && btn) {
    const rect = btn.getBoundingClientRect();
    const width = Math.min(320, Math.max(240, window.innerWidth - 24));
    let left = Math.round(rect.right - width);
    left = Math.max(12, Math.min(left, window.innerWidth - width - 12));
    let top = Math.round(rect.bottom + 8);
    const height = Math.min(popup.scrollHeight || 440, window.innerHeight - 24);
    if (top + height > window.innerHeight - 12) top = Math.max(12, Math.round(rect.top - height - 8));
    popup.style.maxHeight = `${Math.max(80, window.innerHeight - top - 12)}px`;
    popup.style.position = "fixed";
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.style.width = `${width}px`;
    popup.style.zIndex = "90";
    if (popup.parentElement !== document.body) document.body.appendChild(popup);
  }
}

function syncCadComposeRiggingUi() {
  const on = !!cadComposeRigging;
  for (const id of ["prompt-cad-rigging", "prompt-ai-rig"]) {
    const btn = document.getElementById(id);
    if (!btn) continue;
    btn.classList.toggle("active", on);
    btn.classList.toggle("is-on", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  }
  document.querySelectorAll("#prompt-pane-compose [data-prompt-mode]").forEach((b) => {
    const isMode = (b.dataset.promptMode || DEFAULT_PROMPT_MODE) === promptMode;
    b.classList.toggle("active", isMode && !on);
  });
  document.body.classList.toggle("cad-articulation-mode", on);
  document.body.classList.toggle("cad-compose-rigging", on);
  const input = document.getElementById("prompt-input");
  if (on && input) {
    const ph = "Describe the motion (e.g. lid opens and closes)";
    input.placeholder = ph;
    if (composer?.editor) composer.editor.dataset.placeholder = ph;
  }
  const genBtn = document.getElementById("btn-prompt");
  if (genBtn) {
    genBtn.textContent = on ? "Add motion to model" : promptGenerateButtonLabel(promptMode);
  }
}

async function enterCadComposeRigging({ filename = null } = {}) {
  cadComposeRigging = true;
  pendingCadRigPick = false;
  if (promptMode !== "v2" && promptMode !== "mesh") {
    try { applyPromptModeUI("v2"); } catch (_) { /* keep current engine */ }
  }
  setPromptTargetMode("edit");
  showAiComposePanel?.();
  const entries = (typeof visiblePromptTargetEntries === "function" ? visiblePromptTargetEntries() : []) || [];
  const name = filename || selectedFile || (entries.length === 1 ? entries[0].name : null);
  if (name) {
    try { choosePromptTargetObject(name); } catch (_) { selectedFile = name; }
  }
  ensurePromptEditSelection?.();
  syncPromptTargetUI?.();
  syncCadComposeRiggingUi();
  if (!name) {
    pendingCadRigPick = true;
    try { openPromptTargetPopup(); } catch (_) { /* no models yet */ }
    const header = document.querySelector(".prompt-target-popup-header strong");
    if (header) header.textContent = "Which model should get rigging?";
    setEditStatus("ok", "Pick the viewport model to add joints / open-close motion.");
  } else {
    document.getElementById("prompt-input")?.focus?.();
    composer?.editor?.focus?.();
    setEditStatus("ok", `Rigging ${name}. Describe the motion, then Generate.`);
  }
  void refreshModelRigs();
  if (!restoringModelPromptState) saveActiveModelPromptState();
}

function exitCadComposeRigging() {
  cadComposeRigging = false;
  pendingCadRigPick = false;
  syncCadComposeRiggingUi();
  try { applyPromptModeUI(promptMode); } catch (_) { /* ignore */ }
  if (!restoringModelPromptState) saveActiveModelPromptState();
}

function initPromptCadRigging() {
  const activate = (event) => {
    event?.preventDefault?.();
    event?.stopPropagation?.();
    if (cadComposeRigging) exitCadComposeRigging();
    else void enterCadComposeRigging();
  };
  document.getElementById("prompt-cad-rigging")?.addEventListener("click", activate);
  document.getElementById("prompt-ai-rig")?.addEventListener("click", activate);
  initRigQcHotkeys();
}

function setCadArticulationDragEnabled(on) {
  setArticulationDragEnabled(on);
}

async function runCadComposeRiggingPrompt(promptText) {
  const prompt = String(promptText || "").trim();
  const status = document.getElementById("prompt-status");
  if (!projectId) {
    setEditStatus("error", "Select a project first.");
    return { ok: false, error: "no project" };
  }
  if (!prompt) {
    if (status) { status.className = "status error"; status.textContent = "Describe the motion (e.g. lid opens and closes)"; }
    return { ok: false, error: "empty" };
  }
  const target = String(
    promptTargetSelectedBody?.filename
    || document.getElementById("prompt-target-object")?.value
    || selectedFile
    || "",
  ).trim();
  if (!target) {
    pendingCadRigPick = true;
    try { openPromptTargetPopup(); } catch (_) { /* ignore */ }
    setEditStatus("error", "Pick which viewport model to add rigging to.");
    return { ok: false, error: "no target" };
  }
  if (status) {
    status.className = "status loading";
    status.textContent = "Adding joints / motion to the selected model…";
  }
  const promptHistoryId = newPromptHistoryId();
  addPendingPromptHistoryEntry({
    id: promptHistoryId,
    project_id: projectId,
    prompt,
    success: false,
    status: "running",
    _pending: true,
    created_at: new Date().toISOString(),
    user_id: currentUser?.id || null,
    user_name: currentUser?.display_name || currentUser?.email || "You",
    user_avatar_url: currentUser?.avatar_url || null,
    kind: "rigging",
    prompt_mode: "rigging",
    speed: getPromptGenerationSpeed(),
    target_mode: "edit",
    base_filename: target,
  });
  try { renderPromptHistoryEntries(latestPromptHistoryEntries); } catch (_) { /* ignore */ }
  beginGenerationWatch(projectId, { kind: "rigging", mode: "rigging", pendingStart: true });
  try {
    let workPrompt = prompt;
    if (inferRigKind(workPrompt) === "wheels" || /\bfix wheels\b/i.test(workPrompt)) {
      workPrompt = `${wheelDriveGeneratePrefix({ filename: target })} ${workPrompt}`;
    }
    if (isSpiceEnabled()) {
      const spiceMeta = await maybeSpiceUpPrompt(workPrompt, { statusEl: status, forceMode: "rigging" });
      workPrompt = String(spiceMeta?.prompt || workPrompt).trim() || workPrompt;
    }
    const data = await api(`/api/projects/${projectId}/rigging/prompt`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: workPrompt,
        target_filename: target,
        target_label: fileStem(target) || target,
        images: (promptImages || []).slice(0, 4).map(promptImageApiPayload).filter(Boolean),
        speed: document.getElementById("prompt-speed")?.value || "fast",
        ...getPromptAiKeyBodyFields(),
      }),
    });
    if (data?.qc) {
      lastRigQcResult = data.qc;
      setEditStatus(data.qc.pass ? "ok" : "error", (data.qc.notes || []).slice(0, 2).join(" · ") || (data.qc.pass ? "QC PASS" : "QC FAIL"));
    }
    if (data?.accepted || data?.status === "running") {
      if (status) {
        status.className = "status loading";
        status.textContent = "Generating rigging in background…";
      }
      return { ok: true, accepted: true };
    }
    if (data?.rigging) riggingEditor.applyRigData(data.rigging);
    await refreshFiles();
    await refreshRobotArtifacts({ quiet: true });
    await refreshRiggingPromptHistory();
    await refreshPromptHistory();
    await applyRiggingGenerationComplete({
      ...data,
      kind: "rigging",
      prompt_id: data?.prompt_history?.id || promptHistoryId,
    }, projectId);
    await refreshModelRigs();
    if (status) {
      status.className = "status ok";
      status.textContent = data.message || "Rigging added. Use Open/Close next to Gizmo to drag.";
    }
    return { ok: true };
  } catch (err) {
    await refreshRiggingPromptHistory();
    await refreshPromptHistory();
    if (status) {
      status.className = "status error";
      status.textContent = err.message || "Rigging prompt failed.";
    }
    return { ok: false, error: err.message };
  }
}

async function sendSelectedModelsToWheelFix(entries = []) {
  const picked = pickCadModelsForAgentFix(
    (entries?.length ? entries : (projectTree.getSelectedEntries?.() || [])),
  );
  if (!picked.length) {
    pendingCadRigPick = true;
    try { openPromptTargetPopup(); } catch (_) { /* ignore */ }
    setEditStatus("error", "Pick 1–few CAD models in Projects / Browser (Holonomic base wheels).");
    return { ok: false, error: "no models" };
  }
  const primary = picked[0];
  await enterCadComposeRigging({ filename: primary.filename });
  const names = picked.map((row) => row.filename);
  try {
    await fetch("/api/xr/round-table", {
      method: "POST",
      headers: { "Content-Type": "application/json", ...authHeaders() },
      body: JSON.stringify({
        action: "fix_wheels",
        filenames: names,
        project_id: projectId,
        auto_apply: false,
      }),
    });
  } catch (_) { /* chat optional */ }
  const prompt = `make the wheels drive on ${names.join(", ")}`;
  const status = document.getElementById("prompt-status");
  if (status) {
    status.className = "status loading";
    status.textContent = `Fix wheels on ${names.join(", ")}…`;
  }
  return runCadComposeRiggingPrompt(prompt);
}

async function runRigQc({ filename = "", prompt = "make the wheels drive", play = true } = {}) {
  if (!projectId) return { ok: false, error: "no project" };
  const target = filename || selectedFile || "";
  try {
    const data = await api(`/api/projects/${projectId}/rigging/qc`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ filename: target, prompt, post: true }),
    });
    lastRigQcResult = data;
    const notes = (data?.notes || []).slice(0, 2).join(" · ");
    setEditStatus(data?.pass ? "ok" : "error", notes || (data?.pass ? "QC PASS" : "QC FAIL"));
    if (data?.pass && play) {
      try { await playActiveModelRig(); } catch (_) { /* play optional */ }
    }
    return data;
  } catch (err) {
    const local = qcRigFix({ prompt, filename: target });
    lastRigQcResult = local;
    setEditStatus("error", local.notes?.[0] || err.message || "QC failed");
    return local;
  }
}

function initRigQcHotkeys() {
  window.addEventListener("render-studio:fix-wheels", (event) => {
    void sendSelectedModelsToWheelFix(event?.detail?.entries || []);
  });
  window.addEventListener("render-studio:qc-rig", (event) => {
    void runRigQc({ filename: event?.detail?.filename || "", prompt: event?.detail?.prompt || "make the wheels drive" });
  });
}

function cadRigPickerEl() {
  let el = document.getElementById("cad-rig-picker");
  if (el) return el;
  el = document.createElement("div");
  el.id = "cad-rig-picker";
  el.className = "cad-rig-picker hidden";
  el.setAttribute("role", "dialog");
  el.setAttribute("aria-label", "Choose a rig");
  el.innerHTML = `<input id="cad-rig-picker-search" class="cad-rig-picker-search" type="search" placeholder="Search rigs…" autocomplete="off" /><div id="cad-rig-picker-list" class="cad-rig-picker-list"></div>`;
  document.body.appendChild(el);
  el.querySelector("#cad-rig-picker-search")?.addEventListener("input", () => renderCadRigPickerList());
  el.addEventListener("click", (event) => {
    const item = event.target.closest("[data-rig-id]");
    if (!item) return;
    selectModelRig(item.getAttribute("data-rig-id"));
    closeCadRigPicker();
  });
  return el;
}

function renderCadRigPickerList() {
  const list = document.getElementById("cad-rig-picker-list");
  if (!list) return;
  const q = document.getElementById("cad-rig-picker-search")?.value || "";
  const rows = filterRigs(modelRigs, q);
  list.innerHTML = rows.length
    ? rows.map((rig) => `<button type="button" class="cad-rig-picker-item" data-rig-id="${escapeHtml(rig.id)}" aria-selected="${rig.id === activeModelRigId ? "true" : "false"}"><strong>${escapeHtml(rig.name)}</strong><small>${escapeHtml(rigKindLabel(rig.kind))}${rig.source ? ` · ${escapeHtml(rig.source)}` : ""}</small></button>`).join("")
    : `<p class="muted small">No matching rigs.</p>`;
}

function closeCadRigPicker() {
  cadRigPickerOpen = false;
  document.getElementById("cad-rig-picker")?.classList.add("hidden");
  document.getElementById("btn-rig-play-menu")?.setAttribute("aria-expanded", "false");
}

function openCadRigPicker(anchor) {
  const el = cadRigPickerEl();
  renderCadRigPickerList();
  el.classList.remove("hidden");
  cadRigPickerOpen = true;
  const btn = anchor || document.getElementById("btn-rig-play-menu") || document.getElementById("btn-rig-play");
  const rect = btn?.getBoundingClientRect?.();
  if (rect) {
    el.style.left = `${Math.max(8, Math.min(rect.left, window.innerWidth - 296))}px`;
    el.style.top = `${Math.min(rect.bottom + 8, window.innerHeight - 120)}px`;
  }
  document.getElementById("btn-rig-play-menu")?.setAttribute("aria-expanded", "true");
  document.getElementById("cad-rig-picker-search")?.focus();
}

function syncRigPlayMenuVisibility() {
  const play = document.getElementById("btn-rig-play");
  const menu = document.getElementById("btn-rig-play-menu");
  const hasModel = !!(selectedFile || currentMesh || (projectAssembly?.count?.() || 0));
  const playable = modelRigs.length > 0
    || !!urdfRobotRuntime?.isLoaded?.()
    || !!cadComposeRigging
    || Number(jointOverlay?.count?.() || 0) > 0;
  if (play) {
    play.hidden = false;
    play.removeAttribute("hidden");
    play.style.display = "";
    play.disabled = !hasModel && !playable;
    play.classList.toggle("is-ready", playable);
    play.classList.toggle("is-disabled", !hasModel && !playable);
    const fallback = modelRigs.some((rig) => rig.source === "fallback");
    play.title = !hasModel && !playable
      ? "Play rigging — select a model or click Rigging"
      : fallback
        ? "Play fallback open/close (no movable clip yet — joints may be fixed)"
        : "Play the selected rig";
  }
  if (!menu) return;
  const many = modelRigs.length >= 1;
  menu.hidden = !many;
  menu.style.display = many ? "" : "none";
  menu.setAttribute("aria-hidden", many ? "false" : "true");
}

function selectModelRig(id) {
  if (!id) return;
  activeModelRigId = id;
  const rig = modelRigs.find((row) => row.id === id);
  if (rig) setEditStatus("ok", `Active rig: ${rig.name} (${rigKindLabel(rig.kind)}).`);
  renderCadRigPickerList();
}

let modelRigsAbort = null; // leakfix100
function beginModelRigsFetch() {
  if (modelRigsAbort) {
    try { modelRigsAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  modelRigsAbort = ctl;
  return ctl;
}

async function fetchProjectJsonFile(name, signal) {
  if (!projectId || !name) return null;
  try {
    const res = await fetch(`/api/projects/${encodeURIComponent(projectId)}/files/${encodeURIComponent(name)}`, {
      headers: authHeaders(),
      signal,
    });
    if (signal?.aborted) return null;
    if (res.ok) return await res.json();
  } catch (err) {
    if (signal?.aborted || err?.name === "AbortError") throw err;
    /* optional sidecar */
  }
  return null;
}

async function refreshModelRigs() {
  const ctl = beginModelRigsFetch();
  const filename = selectedFile || document.getElementById("prompt-target-object")?.value || "";
  const stem = String(filename || "").replace(/\.[^.]+$/, "");
  if (projectId && !(robotArtifactData?.artifacts || []).length) {
    try { await refreshRobotArtifacts({ quiet: true }); } catch (_) { /* optional */ }
  }
  if (ctl.signal.aborted) return modelRigs;
  const names = (lastProjectFiles || []).map((f) => f.name || f.filename).filter(Boolean);
  const artifacts = robotArtifactData?.artifacts || [];
  const extraSidecars = [
    `${stem}.rigs.json`,
    `${String(stem).split(/[/\\]/).pop()}.rigs.json`,
    "r3d_joints.json",
    "rigging.json",
  ];
  const all = [...new Set([...names, ...artifacts])];
  let sidecar = null;
  let authoredJoints = jointOverlay?.list?.() || [];
  try {
  const sidecarName = pickSidecarName(stem, [...all, ...extraSidecars]);
  if (sidecarName) sidecar = await fetchProjectJsonFile(sidecarName, ctl.signal);
  if (ctl.signal.aborted) return modelRigs;
  if (!sidecar) {
    for (const guess of extraSidecars.filter((n) => /\.rigs\.json$/i.test(n))) {
      sidecar = await fetchProjectJsonFile(guess, ctl.signal);
      if (ctl.signal.aborted) return modelRigs;
      if (sidecar) {
        all.push(guess);
        break;
      }
    }
  } else if (sidecarName && !all.includes(sidecarName)) {
    all.push(sidecarName);
  }
  const jointsSidecar = await fetchProjectJsonFile("r3d_joints.json", ctl.signal);
  if (ctl.signal.aborted) return modelRigs;
  if (Array.isArray(jointsSidecar?.joints) && jointsSidecar.joints.length) {
    authoredJoints = jointsSidecar.joints;
    if (!all.includes("r3d_joints.json")) all.push("r3d_joints.json");
  }
  const riggingSidecar = await fetchProjectJsonFile("rigging.json", ctl.signal);
  if (ctl.signal.aborted) return modelRigs;
  if (riggingSidecar && !all.includes("rigging.json")) all.push("rigging.json");
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return modelRigs;
    throw err;
  }
  try {
    if (!stepModuleRuntime.hasModule?.()) await stepModuleRuntime.ensureLoaded?.();
  } catch (_) { /* optional */ }
  if (ctl.signal.aborted) return modelRigs;
  modelRigs = ensurePlayableRigs(mergeDiscoveredRigs({
    sidecar,
    files: all,
    urdfFiles: all.filter((n) => /\.urdf$/i.test(n)),
    srdfFiles: all.filter((n) => /\.srdf$/i.test(n)),
    stepAnimations: stepModuleRuntime.animationIds?.() || [],
    stepModule: stepModuleRuntime.moduleName?.() || "",
  }), {
    joints: authoredJoints,
    cadRigging: !!cadComposeRigging,
    filename,
  });
  if (!activeModelRigId || !modelRigs.some((r) => r.id === activeModelRigId)) {
    activeModelRigId = modelRigs[0]?.id || "";
  }
  syncRigPlayMenuVisibility();
  const hasRig = modelRigs.length > 0 || !!urdfRobotRuntime?.isLoaded?.() || authoredJoints.length > 0 || !!cadComposeRigging;
  const artBtn = document.getElementById("btn-articulation-drag");
  if (artBtn) {
    artBtn.disabled = !hasRig;
    artBtn.classList.toggle("is-disabled", !hasRig);
  }
  gizmoPanel?.setArticulationAvailable?.(hasRig);
  if (!hasRig && articulationDragEnabled) setArticulationDragEnabled(false);
  setRiggingViewportPlaybackVisible(hasAnyRiggingPlayback());
  return modelRigs;
}

function activeModelRig() {
  return modelRigs.find((r) => r.id === activeModelRigId) || modelRigs[0] || null;
}

function cadMotionRoots() {
  const roots = [];
  const seen = new Set();
  const add = (node) => {
    if (!node || seen.has(node)) return;
    seen.add(node);
    roots.push(node);
  };
  add(projectAssembly.getRoot?.());
  try {
    for (const [, obj] of projectAssembly.list?.() || []) add(obj);
  } catch (_) { /* optional */ }
  add(currentMesh);
  return roots;
}

function bindUrdfToCadAssembly() {
  try {
    return Number(urdfRobotRuntime.bindCadRoots?.(cadMotionRoots()) || 0);
  } catch {
    return 0;
  }
}

function stopCadRigPlayback() {
  try { urdfRobotRuntime.stopTrajectory?.(); } catch (_) { /* ignore */ }
  try { stepModuleRuntime.stop?.({ reset: false }); } catch (_) { /* ignore */ }
  try { planetaryGearRuntime.stop?.({ reset: false }); } catch (_) { /* ignore */ }
  if (cadRigProcedural?.raf) cancelAnimationFrame(cadRigProcedural.raf);
  cadRigProcedural = null;
}

function playProceduralRig(kind) {
  const roots = cadMotionRoots();
  const root = roots[0] || projectAssembly.getRoot?.() || currentMesh;
  if (!root) return false;
  const openClose = kind === "open_close" || kind === "custom";
  const lid = openClose ? pickOpenCloseNodes(roots).lid : null;
  const children = [];
  if (lid) {
    children.push(lid);
  } else {
    root.traverse((node) => {
      if (node !== root && (node.isMesh || node.isGroup) && node.parent === root) children.push(node);
    });
    if (!children.length) {
      root.traverse((node) => { if (node.isMesh && node !== root) children.push(node); });
    }
  }
  if (!children.length) return false;
  const bases = children.map((node) => ({
    node,
    pos: node.position.clone(),
    quat: node.quaternion.clone(),
  }));
  const started = performance.now();
  const duration = kind === "assemble" ? 4200 : 3600;
  const hinge = new THREE.Vector3(1, 0, 0);
  const tick = (now) => {
    const t = ((now - started) % duration) / duration;
    const ease = t < 0.5 ? t * 2 : (1 - t) * 2;
    const open = 0.5 - 0.5 * Math.cos(t * Math.PI * 2);
    bases.forEach((row, i) => {
      if (kind === "vortex") {
        row.node.quaternion.copy(row.quat);
        row.node.rotateOnWorldAxis(new THREE.Vector3(0, 0, 1), t * Math.PI * 2);
      } else if (kind === "assemble") {
        const explode = 18 + i * 8;
        const from = 1 - ease;
        row.node.position.copy(row.pos).add(new THREE.Vector3((i % 2 ? 1 : -1) * explode * from, 0, explode * 0.4 * from));
      } else {
        row.node.position.copy(row.pos);
        row.node.quaternion.copy(row.quat);
        const angle = open * 1.92;
        row.node.position.applyAxisAngle(hinge, angle);
        row.node.quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(hinge, angle));
      }
    });
    cadRigProcedural.raf = requestAnimationFrame(tick);
  };
  cadRigProcedural = { kind, raf: requestAnimationFrame(tick), bases };
  return true;
}

async function playActiveModelRig() {
  await refreshModelRigs();
  const rig = activeModelRig();
  if (!rig) {
    return toggleRiggingPlayback();
  }
  stopCadRigPlayback();
  if (rig.kind === "urdf" || rig.urdfFile) {
    return toggleRiggingPlayback();
  }
  if (rig.kind === "step" || rig.animationId) {
    try {
      if (!stepModuleRuntime.hasModule()) await stepModuleRuntime.ensureLoaded();
      const root = projectAssembly.getRoot?.() || currentMesh;
      if (!stepModuleRuntime.isBound()) await stepModuleRuntime.bind(root);
      const playing = stepModuleRuntime.play?.(rig.animationId || null);
      setEditStatus("ok", playing ? `Playing ${rig.name}` : `${rig.name} paused.`);
      return playing;
    } catch (err) {
      console.warn("STEP rig play failed", err);
    }
  }
  if (playProceduralRig(rig.kind)) {
    setEditStatus("ok", `Playing ${rig.name} (${rigKindLabel(rig.kind)}).`);
    return true;
  }
  return toggleRiggingPlayback();
}

function isArticulationDragEnabled() {
  return articulationDragEnabled;
}

function setArticulationDragEnabled(on) {
  const hasRig = !!(urdfRobotRuntime?.isLoaded?.() || modelRigs.length || riggingEditor?.jointControls?.()?.length || cadComposeRigging || Number(jointOverlay?.count?.() || 0) > 0);
  const btn = document.getElementById("btn-articulation-drag");
  if (btn) {
    btn.disabled = !hasRig;
    btn.classList.toggle("is-disabled", !hasRig);
  }
  gizmoPanel?.setArticulationAvailable?.(hasRig);
  if (on && !hasRig) {
    articulationDragEnabled = false;
    btn?.classList.remove("active");
    btn?.setAttribute("aria-pressed", "false");
    gizmoPanel?.setArticulationActive?.(false);
    setEditStatus("error", "No rigging on the current selection. Generate Rigging first.");
    return;
  }
  articulationDragEnabled = !!on;
  btn?.classList.toggle("active", articulationDragEnabled);
  btn?.setAttribute("aria-pressed", articulationDragEnabled ? "true" : "false");
  gizmoPanel?.setArticulationActive?.(articulationDragEnabled);
  if (articulationDragEnabled) {
    try {
      transformControls.detach();
      gizmoPanel.hide?.();
      document.getElementById("btn-gizmo")?.classList.remove("active");
    } catch (_) { /* ignore */ }
    setEditStatus("ok", "Open/Close on — drag the model to articulate. Orbit on empty canvas.");
  } else if (cadArticulationDrag) {
    cadArticulationDrag = null;
    try { if (controls) controls.enabled = true; } catch (_) { /* ignore */ }
  }
}

function driveActiveRigByDelta(dx) {
  const amount = dx * 0.012;
  const rig = activeModelRig();
  if (urdfRobotRuntime.isLoaded?.()) {
    const joints = (urdfRobotRuntime.getState?.()?.urdf?.joints || []).filter(
      (j) => ["revolute", "continuous", "prismatic"].includes(String(j.type || "").toLowerCase()),
    );
    const joint = joints.find((j) => !rig || j.name === rig.id) || joints[0];
    if (joint) {
      const cur = Number(urdfRobotRuntime.getState?.()?.jointValuesRad?.[joint.name] || 0);
      urdfRobotRuntime.setJointValue(joint.name, cur + amount);
      return true;
    }
  }
  if (cadRigProcedural?.bases) {
    cadRigProcedural.bases.forEach((row) => {
      row.node.rotateOnAxis(new THREE.Vector3(1, 0, 0), amount);
    });
    return true;
  }
  const sel = objectTools?.getSelection?.();
  const mesh = sel?.mesh;
  if (mesh && mesh.parent) {
    mesh.rotateOnAxis(new THREE.Vector3(1, 0, 0), amount);
    return true;
  }
  return false;
}

function beginArticulationDrag(e) {
  if (!articulationDragEnabled || e.button !== 0) return false;
  cadArticulationDrag = { pointerId: e.pointerId, lastX: e.clientX, lastY: e.clientY };
  controls.enabled = false;
  renderer.domElement.setPointerCapture?.(e.pointerId);
  return true;
}

function moveArticulationDrag(e) {
  if (!cadArticulationDrag || e.pointerId !== cadArticulationDrag.pointerId) return false;
  const dx = e.clientX - cadArticulationDrag.lastX;
  cadArticulationDrag.lastX = e.clientX;
  cadArticulationDrag.lastY = e.clientY;
  driveActiveRigByDelta(dx);
  return true;
}

function endArticulationDrag(e) {
  if (!cadArticulationDrag) return false;
  if (e && e.pointerId !== cadArticulationDrag.pointerId) return false;
  cadArticulationDrag = null;
  controls.enabled = true;
  return true;
}

function initPromptAiGear() {
  mountElectronicsBuildSettings(() => projectId);
  const btn = document.getElementById("prompt-ai-gear");
  const host = document.getElementById("prompt-ai-gear-host");
  const popup = document.getElementById("prompt-ai-gear-popup");
  if (!btn || !host || !popup) return;
  btn.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    setPromptAiGearOpen(host.dataset.open !== "true");
  });
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape" || host.dataset.open !== "true") return;
    event.preventDefault();
    setPromptAiGearOpen(false);
    btn.focus();
  }, { capture: true });
  document.addEventListener("pointerdown", (e) => {
    if (host.dataset.open !== "true") return;
    if (host.contains(e.target) || popup.contains(e.target) || btn.contains(e.target)) return;
    setPromptAiGearOpen(false);
  });
  window.addEventListener("resize", () => {
    if (host.dataset.open === "true") setPromptAiGearOpen(true);
  });
}

function pushSpiceOverlayProgress(progress = {}) {
  const renderHud = isRenderOverlayState(viewportOverlayState);
  if (generationWatchOverlay && !renderHud) {
    generationWatchOverlay.progress = {
      ...(generationWatchOverlay.progress || {}),
      ...progress,
      improved_prompt:
        progress.improved_prompt
        ?? progress.prompt_preview
        ?? generationWatchOverlay.progress?.improved_prompt,
    };
    if (progress.label) {
      generationWatchOverlay.message = progress.label;
    }
    if (progress.usageSummary) {
      generationWatchOverlay.usageSummary = progress.usageSummary;
    }
    // Keep the submit-hold alive through the whole improve step so the spinner
    // cannot tear down mid-rewrite (pct>=5 used to clear pendingHoldUntil).
    if (generationWatchOverlay.pendingStart || progress.spiceHold) {
      generationWatchOverlay.pendingStart = true;
    }
  }
  const overlay = generationWatchOverlay?.kind === "wiring"
    ? (wiringOverlay || viewerOverlay)
    : viewerOverlay;
  const spiceMode = String(promptModeForRef?.() || promptMode || "").toLowerCase();
  const spiceIsRender = renderHud || spiceMode === "render";
  // Ensure the viewport spinner is up before applying improve progress.
  if (!overlay?.isGenerating?.()) {
    showViewportOverlay(projectId, progress.label || "Improving prompt with AI…", {
      kind: spiceIsRender ? "scene_render" : "prompt",
      promptMode: spiceIsRender ? "render" : promptModeForRef(),
      mode: spiceIsRender ? "render" : promptModeForRef(),
      pendingStart: true,
      progress: {
        pct: Number(progress.pct) || 3,
        label: progress.label || "Improving prompt with AI…",
        thinking: progress.thinking,
        activity: progress.activity,
        improved_prompt: progress.improved_prompt,
        spiceHold: true,
      },
    });
  }
  overlay?.updateProgress?.({ ...progress, spiceHold: true });
  if (!spiceIsRender) syncViewportGenerationOverlay();
  if (progress.usageSummary && !spiceIsRender) {
    overlay?.setGenerating?.(true, progress.label || generationWatchOverlay?.message, {
      ...(generationWatchOverlay || {}),
      usageSummary: progress.usageSummary,
      pendingStart: true,
      progress: generationWatchOverlay?.progress,
    });
  }
}

function meshImproveUiCopy(improveMode) {
  const beta = String(improveMode || "").toLowerCase() === "mesh_beta"
    || String(improveMode || "").toLowerCase() === "mesh-beta";
  if (beta) {
    return {
      status: "Improving Mesh Beta prompt for realistic materials and animation…",
      thinking: "Rewriting for PBR materials, named pivots, and a playable animation plan…",
      activity: "Improving Mesh Beta prompt (look-dev + clips)…",
    };
  }
  return {
    status: "Improving Mesh prompt for realistic materials…",
    thinking: "Rewriting for realistic PBR, named parts, and animation-ready hierarchy…",
    activity: "Improving Mesh prompt (look-dev + hierarchy)…",
  };
}

function overlayUsageFromImproveTrace(trace) {
  if (!trace || typeof trace !== "object") return null;
  const usage = trace.usage || null;
  const cost = trace.cost_usd;
  const tokens = usageTokenTotal(usage);
  const costNum = cost != null && Number.isFinite(Number(cost)) ? Number(cost) : null;
  if (!tokens && (costNum == null || costNum <= 0)) return null;
  return {
    cost_usd: costNum,
    usage: usage || { total_tokens: tokens },
    model: trace.model || "",
    ai_calls: 1,
  };
}

function looksLikeSceneRenderIntent(text) {
  const t = String(text || "").toLowerCase().replace(/\s+/g, " ").trim();
  if (!t) return false;
  if (/\b(photoreal(?:istic)?|photo[\s-]?real|product shot|lifestyle shot)\b/.test(t)) return true;
  if (/\b(create|make|generate|do|give me|i want)\s+(a\s+|an\s+)?(photoreal(?:istic)?\s+)?render\b/.test(t)) return true;
  if (/\brender\s+(of|this|the|my|it|from)\b/.test(t)) return true;
  if (/\brender\b/.test(t) && /\b(table|desk|counter|outside|outdoors|kitchen|studio|environment|scene|living room|on a)\b/.test(t)) {
    return true;
  }
  return false;
}

/** Z-up world: +Y front, +X right. Used so Render Improve locks facing. */
function describeViewportFacingHint() {
  const cam = sketchEditor?.getRenderCamera?.() || camera;
  const target = controls?.target;
  if (!cam?.position || !target) return "";
  const look = new THREE.Vector3().subVectors(target, cam.position);
  if (look.lengthSq() < 1e-12) return "";
  look.normalize();
  const horiz = [];
  if (Math.abs(look.y) >= 0.35) horiz.push(look.y < 0 ? "front (+Y) toward camera" : "back (−Y) toward camera");
  if (Math.abs(look.x) >= 0.35) horiz.push(look.x < 0 ? "right side (+X) toward camera" : "left side (−X) toward camera");
  const elev = look.z < -0.25 ? "from slightly above" : look.z > 0.25 ? "from below" : "near eye-level";
  return (
    "Keep this exact viewport pose and object facing ("
    + (horiz.join(", ") || "current 3/4 view")
    + `; ${elev}`
    + "). Do not yaw, pitch, roll, or mirror the product. Paint realistic materials only on the CAD subject "
    + "so they can be camera-projected onto the mesh; keep the environment around the model, not wrapped onto it."
  );
}

function downscaleDataUrlForImprove(dataUrl, maxEdge = 1024) {
  return new Promise((resolve) => {
    const src = String(dataUrl || "");
    if (!src.startsWith("data:image/")) {
      resolve(src);
      return;
    }
    const img = new Image();
    img.onload = () => {
      const w = img.naturalWidth || img.width || 1;
      const h = img.naturalHeight || img.height || 1;
      const scale = Math.min(1, maxEdge / Math.max(w, h, 1));
      if (scale >= 0.98) {
        resolve(src);
        return;
      }
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(2, Math.round(w * scale));
      canvas.height = Math.max(2, Math.round(h * scale));
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        resolve(src);
        return;
      }
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL("image/jpeg", 0.84));
    };
    img.onerror = () => resolve(src);
    img.src = src;
  });
}

async function captureViewportImageForRenderImprove() {
  try {
    const target = resolveRenderGeometryTarget(promptReferencesForSubmit());
    const dataUrl = captureSceneRenderReferencePng(target.filename || null);
    const scaled = await downscaleDataUrlForImprove(dataUrl, 1024);
    const jpeg = String(scaled).startsWith("data:image/jpeg");
    return {
      id: `viewport-capture-${Date.now()}`,
      name: jpeg ? "viewport-capture.jpg" : "viewport-capture.png",
      media_type: jpeg ? "image/jpeg" : "image/png",
      data_url: scaled,
    };
  } catch {
    return null;
  }
}

async function maybeSpiceUpPrompt(promptText, { statusEl, forceMode = null, editContext = null, canvasSmart = false } = {}) {
  const original = String(promptText || "").trim();
  if (!original || !isSpiceEnabled()) {
    return { prompt: original, originalPrompt: original, promptImproved: false };
  }
  if (!aiStatus?.ai_ready && anyCliSubscriptionReady()) {
    const spiceMode = String(forceMode || promptMode || "").toLowerCase();
    if (["render", "draw", "standard", ""].includes(spiceMode)) {
      return { prompt: original, originalPrompt: original, promptImproved: false };
    }
  }
  // Explicit forceMode (e.g. scene-render path). Otherwise honor the active UI
  // mode so Mode 2.0 always gets CAD improve — Mesh gets img2threejs realistic materials.
  // VibeCAD engine under 2.0 uses mode=vibecad for improve + generation.
  let improveMode = forceMode
    || (cadComposeRigging ? "rigging" : null)
    || (promptMode === "draw" ? "draw" : promptMode || DEFAULT_PROMPT_MODE);
  if (!forceMode && improveMode === "v2") {
    improveMode = resolveCadPromptMode("v2");
  }
  if (!forceMode && (improveMode === "mesh" || improveMode === "mesh_beta" || improveMode === "mesh-beta")) {
    improveMode = resolveMeshPromptMode("mesh");
  }
  if (improveMode === "fusion" || improveMode === "img2threejs" || improveMode === "threejs") {
    improveMode = "mesh";
  }
  const meshCopy = (improveMode === "mesh" || improveMode === "mesh_beta" || improveMode === "mesh-beta")
    ? meshImproveUiCopy(improveMode)
    : null;
  if (statusEl) {
    statusEl.className = "status loading";
    statusEl.textContent = meshCopy?.status
      || (improveMode === "vibecad"
        ? "Improving prompt for VibeCAD…"
        : improveMode === "mac"
          ? "Improving prompt for MAC…"
          : improveMode === "render"
            ? "Improving Render prompt (viewport pose + object materials)…"
            : improveMode === "rigging"
              ? "Improving prompt for joints on the selected model…"
              : "Improving prompt with AI…");
  }
  pushSpiceOverlayProgress({
    pct: 4,
    stage: "analyze",
    label: meshCopy?.status
      || (improveMode === "vibecad"
        ? "Improving prompt for VibeCAD…"
        : improveMode === "mac"
          ? "Improving prompt for MAC…"
          : improveMode === "render"
            ? "Improving Render prompt (viewport pose + object materials)…"
            : "Improving prompt with AI…"),
    thinking:
      meshCopy?.thinking
      || (improveMode === "render"
        ? "Locking the viewport model and facing, then writing object-only materials and scene lighting…"
        : improveMode === "rigging"
          ? articulationImproveHint(inferRigKind(original))
          : improveMode === "vibecad"
            ? "Rewriting your prompt for VibeCAD parametric CAD…"
            : improveMode === "mac"
              ? "Rewriting your prompt for MAC (Multi-Agent CAD)…"
              : improveMode === "v2" || improveMode === "architect"
                ? "Rewriting your prompt for clearer parametric CAD…"
                : improveMode === "draw"
                  ? "Rewriting your prompt for a clearer direct edit…"
                  : "Rewriting your prompt for a clearer rendered look…"),
    activity: [
      {
        text: meshCopy?.activity
          || (improveMode === "vibecad"
            ? "Improving prompt for VibeCAD…"
            : improveMode === "mac"
              ? "Improving prompt for MAC…"
              : improveMode === "render"
                ? "Improving Render prompt…"
                : improveMode === "rigging"
                  ? "Improving prompt for joints on the selected model…"
                  : "Improving prompt with AI…"),
        stage: "analyze",
      },
    ],
  });
  try {
    await Promise.allSettled(pendingPromptImagePersists.slice());
    await hydratePromptImages({ project_id: projectId });
    const improveImages = (promptImages || [])
      .map(promptImageApiPayload)
      .filter((img) => img && (promptImageHasBytes(img) || img.stored_name || img.url))
      .slice(0, 8);
    if (improveMode === "render") {
      const viewportCapture = await captureViewportImageForRenderImprove();
      const viewportPayload = viewportCapture ? promptImageApiPayload(viewportCapture) : null;
      if (viewportPayload?.data_url) {
        improveImages.unshift(viewportPayload);
        if (improveImages.length > 4) improveImages.length = 4;
      }
    }
    const cadImprove =
      improveMode !== "render" &&
      improveMode !== "mesh" &&
      improveMode !== "mesh_beta" &&
      improveMode !== "mesh-beta" &&
      improveMode !== "rigging";
    const improvePrompt = original;
    const data = await api("/api/prompt/improve", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: improvePrompt,
        mode: improveMode,
        target_mode: editContext?.targetMode || getPromptTargetMode?.() || "new",
        base_filename: editContext ? editContext.baseFilename : promptBaseFilename(),
        references: editContext?.references || promptReferencesForSubmit(),
        articulation: cadComposeRigging || improveMode === "rigging",
        articulation_kind: cadComposeRigging ? inferRigKind(original) : undefined,
        // Keep prompt rewriting quick/reliable. The actual generation still
        // uses the selected Speed/Quality value when the prompt is submitted.
        speed: "fast",
        project_id: projectId || null,
        has_images: improveImages.length > 0,
        // CAD (Jake / VibeCAD / MAC) and Mesh improve both need the photo.
        images: improveImages,
        ...(improveMode === "render" ? { viewport_hint: describeViewportFacingHint() || null } : {}),
        ...getContextLabImproveFields(),
        ...getPromptAiKeyBodyFields(),
        ...(cadImprove ? getCadMcMasterPartsBodyFields(improveMode) : {}),
        ...(cadImprove ? getCadDebugBodyFields(improveMode) : {}),
      }),
    }, 120000);
    const spiceUsage = overlayUsageFromImproveTrace(data?.trace);
    const startingLine = meshCopy
      ? ((improveMode === "mesh_beta" || improveMode === "mesh-beta")
        ? "Starting Mesh Beta generation…"
        : "Starting Mesh generation…")
      : improveMode === "render"
        ? "Starting photoreal render…"
        : improveMode === "rigging"
          ? "Starting rigging on the selected model…"
          : "Starting CAD generation…";
    const improved = String(data?.improved_prompt || "").trim();
    if (!improved || improved === original) {
      saveSpicePromptCompare({
        original,
        improved: original,
        unchanged: true,
        at: new Date().toISOString(),
      });
      pushSpiceOverlayProgress({
        pct: 6,
        stage: "analyze",
        label: "Using original prompt…",
        thinking: "Prompt already clear — starting generation…",
        activity: [
          { text: "Prompt unchanged — starting generation…", stage: "analyze" },
        ],
        usageSummary: spiceUsage,
      });
      return { prompt: original, originalPrompt: original, promptImproved: false };
    }
    saveSpicePromptCompare({
      original,
      improved,
      unchanged: false,
      at: new Date().toISOString(),
    });
    if (statusEl) {
      statusEl.className = "status ok";
      statusEl.textContent = "Prompt improved — generating…";
    }
    pushSpiceOverlayProgress({
      pct: 8,
      stage: "analyze",
      label: "Prompt improved — generating…",
      thinking: meshCopy
        ? "Using the improved prompt for a realistic Mesh rebuild…"
        : improveMode === "render"
          ? "Using the improved prompt to photorealize the exact viewport model…"
          : "Using the improved prompt for CAD generation…",
      improved_prompt: improved,
      activity: [
        { text: "Prompt improved with AI", stage: "analyze" },
        { text: startingLine, stage: "analyze" },
      ],
      usageSummary: spiceUsage,
    });
    return { prompt: improved, originalPrompt: original, promptImproved: true };
  } catch (err) {
    if (statusEl) {
      statusEl.className = "status error";
      statusEl.textContent = `Improve prompt with AI failed (${formatUserError(err)}). Generating with original prompt…`;
    }
    pushSpiceOverlayProgress({
      pct: 6,
      stage: "analyze",
      label: "Using original prompt…",
      thinking: "Improve prompt failed — generating with your original text…",
      activity: [
        { text: "Improve prompt failed — using original", stage: "analyze" },
      ],
    });
    return { prompt: original, originalPrompt: original, promptImproved: false };
  }
}

function getWiringGenerationSpeed() {
  const value = document.getElementById("wiring-speed")?.value
    ?? document.getElementById("wiring-toolbelt-speed")?.value
    ?? document.getElementById("wdbg-speed")?.value;
  return value === "quality" ? "quality" : "fast";
}

function setWiringGenerationSpeed(value, { persist = true } = {}) {
  const next = value === "quality" ? "quality" : "fast";
  for (const id of ["wiring-speed", "wiring-toolbelt-speed", "wdbg-speed"]) {
    const select = document.getElementById(id);
    if (select) select.value = next;
  }
  if (persist) {
    try { localStorage.setItem(WIRING_SPEED_KEY, next); } catch { }
  }
}

function initWiringGenerationSpeed() {
  let saved = "fast";
  try { saved = localStorage.getItem(WIRING_SPEED_KEY) || "fast"; } catch { }
  setWiringGenerationSpeed(saved, { persist: false });
  for (const id of ["wiring-speed", "wiring-toolbelt-speed", "wdbg-speed"]) {
    document.getElementById(id)?.addEventListener("change", (e) => {
      setWiringGenerationSpeed(e.currentTarget.value);
    });
  }
}

function setPromptGenerationSpeed(value, { persist = true } = {}) {
  const next = value === "quality" ? "quality" : "fast";
  const select = document.getElementById("prompt-speed");
  if (select) select.value = next;
  if (persist) {
    try { localStorage.setItem(PROMPT_SPEED_KEY, next); } catch { }
  }
  applyPromptModeUI(promptMode);
}

/** Track last prompt model so we only auto-force Speed when Pro is newly selected. */
let lastPromptModelForSpeedGuard = "";

function isGpt55ProModel(model) {
  return String(model || "").trim().toLowerCase() === "gpt-5.5-pro";
}

/**
 * GPT-5.5 Pro Quality is very expensive ($30/$180). Whenever Pro becomes the
 * selected model, default Mode to Speed so users don't burn money by accident.
 * They can still switch back to Quality manually after that.
 */
function syncSpeedModeForSelectedModel() {
  const model = String(getSelectedPromptModelInfo()?.model || "").trim().toLowerCase();
  if (!model) return;
  const becamePro = isGpt55ProModel(model) && !isGpt55ProModel(lastPromptModelForSpeedGuard);
  lastPromptModelForSpeedGuard = model;
  if (!becamePro) return;
  setPromptGenerationSpeed("fast", { persist: true });
}

function initPromptGenerationSpeed() {
  let saved = "fast";
  try { saved = localStorage.getItem(PROMPT_SPEED_KEY) || "fast"; } catch { }
  setPromptGenerationSpeed(saved, { persist: false });
  document.getElementById("prompt-speed")?.addEventListener("change", (e) => {
    setPromptGenerationSpeed(e.currentTarget.value);
  });
  // If Pro is already selected on boot, still prefer Speed over a stale Quality save.
  syncSpeedModeForSelectedModel();
}

const FUSION_TARGET_KEY = "render3d:fusion-target:v1";
let fusionTarget = (() => {
  try {
    return localStorage.getItem(FUSION_TARGET_KEY) === "fusion360" ? "fusion360" : "in_app";
  } catch {
    return "in_app";
  }
})();

function fusionTargetLabel(target = fusionTarget) {
  return target === "fusion360" ? "Fusion 360 plugin" : "in-app Fusion";
}

function promptModeForRef(mode = promptMode) {
  const normalized = (mode || DEFAULT_PROMPT_MODE).toLowerCase();
  if (normalized === "mesh_beta" || normalized === "mesh-beta") return "mesh";
  if (normalized === "mesh") return "mesh";
  if (normalized === "fusion") return "mesh";
  if (normalized === "architect") return "architect";
  if (normalized === "vibecad" || normalized === "vibe" || normalized === "vibecade") return "vibecad";
  if (normalized === "mac" || normalized === "macad" || normalized === "multi_agent_cad") return "mac";
  if (normalized === "v2") return "v2";
  if (normalized === "draw") return "draw";
  if (normalized === "render") return "render";
  return "standard";
}

const CAD_ENGINE_KEY = "render3d:promptCadEngine";
const CAD_HARNESS_ENGINES = ["jake", "vibecad", "mac", "steve"];
const CAD_HARNESS_MODES = ["v2", "vibecad", "mac", "architect", "fusion"];
const CAD_OR_MESH_MODES = [...CAD_HARNESS_MODES, "mesh", "mesh_beta"];

function isCadHarnessMode(mode = promptMode) {
  const m = String(mode || "").toLowerCase();
  if (CAD_HARNESS_MODES.includes(m)) return true;
  if (m === "v2") return true;
  try {
    return CAD_HARNESS_ENGINES.includes(getPromptCadEngine());
  } catch {
    return false;
  }
}

function promptCadEngineLabel(engine) {
  const e = String(engine || "").toLowerCase();
  if (e === "vibecad") return "VibeCAD";
  if (e === "mac" || e === "macad" || e === "multi_agent_cad") return "MAC";
  if (e === "steve") return "STEVE";
  return "Jake";
}

function normalizeCadEngine(engine) {
  const e = String(engine || "jake").toLowerCase();
  if (e === "vibecad" || e === "vibe" || e === "vibecade") return "vibecad";
  if (e === "mac" || e === "macad" || e === "multi_agent_cad" || e === "multiagentcad") return "mac";
  if (e === "steve") return "steve";
  return "jake";
}

function syncPromptCadEngineChip(engine = getPromptCadEngine()) {
  const current = normalizeCadEngine(engine);
  document.querySelectorAll("[data-cad-engine]").forEach((btn) => {
    const on = btn.getAttribute("data-cad-engine") === current;
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("is-selected", on);
  });
  const modeBtn = document.querySelector('.prompt-mode-btn--v2[data-prompt-mode="v2"]');
  if (modeBtn) {
    modeBtn.title = `CAD · ${promptCadEngineLabel(current)} harness — click CAD to switch Jake / VibeCAD / MAC / STEVE`;
  }
  const harnessTip = document.querySelector("#prompt-mode-v2-tip .prompt-mode-v2-tip-harness");
  if (harnessTip) {
    harnessTip.innerHTML =
      `<b>Click CAD</b> to switch harnesses — currently <b>${promptCadEngineLabel(current)}</b>. `
      + `<b>Jake</b> (text-to-cad), <b>VibeCAD</b> (FreeCAD / build123d), `
      + `<b>MAC</b> (Multi-Agent CAD · 4-agent pipeline), or <b>STEVE</b> (Autodesk Fusion).`;
  }
}

function setPromptCadEngineOpen(open, { focusSelect = false } = {}) {
  const host = document.getElementById("prompt-cad-engine-host");
  const popup = document.getElementById("prompt-cad-engine-popup");
  const modeBtn = document.querySelector('.prompt-mode-btn--v2[data-prompt-mode="v2"]');
  const next = Boolean(open);
  if (next) {
    setPromptMeshEngineOpen(false);
    setPromptAiGearOpen(false);
  }
  if (host) host.dataset.open = next ? "true" : "false";
  if (popup) popup.hidden = !next;
  if (modeBtn) modeBtn.setAttribute("aria-expanded", next ? "true" : "false");
  if (next && popup && modeBtn) {
    // Fixed position so the panel isn't clipped by sidebar overflow.
    const rect = modeBtn.getBoundingClientRect();
    const width = Math.min(280, Math.max(220, window.innerWidth - 24));
    let left = Math.round(rect.left);
    left = Math.max(12, Math.min(left, window.innerWidth - width - 12));
    let top = Math.round(rect.bottom + 8);
    const estimatedH = 520;
    if (top + estimatedH > window.innerHeight - 12) {
      top = Math.max(12, Math.round(rect.top - estimatedH - 8));
    }
    popup.style.position = "fixed";
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.style.width = `${width}px`;
    popup.style.zIndex = "12000";
    if (popup.parentElement !== document.body) {
      document.body.appendChild(popup);
    }
    syncPromptCadEngineChip();
    if (focusSelect) {
      queueMicrotask(() => {
        const selected =
          popup.querySelector('.prompt-cad-engine-option[aria-pressed="true"]')
          || popup.querySelector(".prompt-cad-engine-option");
        try { selected?.focus?.({ preventScroll: true }); } catch { /* ignore */ }
      });
    }
  } else if (popup && host && popup.parentElement !== host) {
    host.appendChild(popup);
    popup.style.left = "";
    popup.style.top = "";
    popup.style.width = "";
    popup.style.position = "";
    popup.style.zIndex = "";
  }
}

function getPromptCadEngine() {
  const sel = document.getElementById("prompt-cad-engine");
  const fromUi = String(sel?.value || "").toLowerCase();
  if (fromUi === "vibecad" || fromUi === "jake" || fromUi === "mac" || fromUi === "steve") return fromUi;
  try {
    const saved = String(localStorage.getItem(CAD_ENGINE_KEY) || "jake").toLowerCase();
    return normalizeCadEngine(saved);
  } catch {
    return "jake";
  }
}

function setPromptCadEngine(engine) {
  const next = normalizeCadEngine(engine);
  const sel = document.getElementById("prompt-cad-engine");
  if (sel) sel.value = next;
  try {
    localStorage.setItem(CAD_ENGINE_KEY, next);
  } catch {
    /* ignore */
  }
  syncPromptCadEngineChip(next);
  if (next === "jake" && selectedPromptSupportsCodex()) {
    rememberSelectedOpenAiKeyForCodex();
  }
  return next;
}

function resolveCadPromptMode(uiMode = promptMode) {
  const mode = String(uiMode || DEFAULT_PROMPT_MODE).toLowerCase();
  if (mode === "v2") {
    const engine = getPromptCadEngine();
    if (engine === "vibecad") return "vibecad";
    if (engine === "mac") return "mac";
    if (engine === "steve") return "steve";
  }
  return mode;
}

let steveIntegrationPromise = null;
function getSteveIntegration() {
  if (!steveIntegrationPromise) {
    steveIntegrationPromise = import("../cad/steve-connector.js?v=20260930-steve1").then((mod) => mod.mountSteveConnector({
      getPrompt: () => composer?.getPromptText?.() || "",
      setPromptStatus: (tone, message) => {
        const status = document.getElementById("prompt-status");
        if (!status) return;
        status.className = `status ${tone === "error" ? "error" : ""}`.trim();
        status.textContent = message;
      },
    }));
  }
  return steveIntegrationPromise;
}

function syncSteveIntegrationActivity() {
  const menuOpen = document.getElementById("prompt-cad-engine-host")?.dataset.open === "true";
  const workflowActive = getPromptCadEngine() === "steve";
  if (!menuOpen && !workflowActive && !steveIntegrationPromise) return;
  void getSteveIntegration().then((integration) => integration.setActive(menuOpen || workflowActive));
}

