function shouldShowMeshIntro() {
  try {
    return localStorage.getItem(MESH_INTRO_KEY) !== "1";
  } catch {
    return true;
  }
}

function markMeshIntroSeen() {
  try {
    localStorage.setItem(MESH_INTRO_KEY, "1");
  } catch {
    /* ignore */
  }
}

function selectMeshIntroDemo(demoId) {
  const demo = MESH_INTRO_DEMOS.find((d) => d.id === demoId) || MESH_INTRO_DEMOS[2];
  const frame = document.getElementById("mesh-intro-demo-frame");
  if (frame && demo) {
    // Query before hash so SPA routes stay valid while still forcing a reload.
    const hashIdx = demo.live.indexOf("#");
    const base = hashIdx >= 0 ? demo.live.slice(0, hashIdx) : demo.live;
    const hash = hashIdx >= 0 ? demo.live.slice(hashIdx) : "";
    const joiner = base.includes("?") ? "&" : "?";
    frame.src = `${base}${joiner}t=${Date.now()}${hash}`;
  }
  document.querySelectorAll("[data-mesh-intro-demo]").forEach((card) => {
    card.classList.toggle("is-active", card.getAttribute("data-mesh-intro-demo") === demo?.id);
  });
}

function ensureMeshIntroDemoCards() {
  const host = document.getElementById("mesh-intro-demos");
  if (!host || host.dataset.ready === "1") return;
  host.dataset.ready = "1";
  host.innerHTML = MESH_INTRO_DEMOS.map(
    (demo) => `
    <div class="mesh-intro-demo-card" data-mesh-intro-demo="${escapeHtml(demo.id)}" role="listitem" tabindex="0" title="${escapeHtml(demo.title)}">
      <div class="mesh-intro-demo-thumb">
        <img src="${escapeHtml(demo.thumb)}" alt="" loading="lazy" />
      </div>
      <div class="mesh-intro-demo-meta">
        <strong>${escapeHtml(demo.title)}</strong>
        <span>${escapeHtml(demo.subject)}</span>
      </div>
      <div class="mesh-intro-demo-links">
        <a href="${escapeHtml(demo.live)}" target="_blank" rel="noopener noreferrer" data-mesh-intro-ext>Live</a>
        <a href="${escapeHtml(demo.code)}" target="_blank" rel="noopener noreferrer" data-mesh-intro-ext>Code</a>
      </div>
    </div>
  `,
  ).join("");
  host.querySelectorAll("[data-mesh-intro-demo]").forEach((card) => {
    const pick = () => selectMeshIntroDemo(card.getAttribute("data-mesh-intro-demo"));
    card.addEventListener("click", (e) => {
      if (e.target?.closest?.("[data-mesh-intro-ext]")) return;
      pick();
    });
    card.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        pick();
      }
    });
  });
}

