const MESH_BETA_INTRO_KEY = "render3d:mesh-beta-intro-v1";

function promptMeshEngineLabel(engine) {
  return meshEngineLabel(engine);
}

function syncPromptMeshEngineChip(engine = getPromptMeshEngine()) {
  const current = normalizeMeshEngine(engine);
  const configured = meshEngine(current);
  const isBeta = current === "beta";
  document.querySelectorAll("[data-mesh-engine]").forEach((btn) => {
    const on = btn.getAttribute("data-mesh-engine") === current;
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.classList.toggle("is-selected", on);
  });
  const modeBtn = document.querySelector('.prompt-mode-btn--mesh[data-prompt-mode="mesh"]');
  if (modeBtn) {
    modeBtn.dataset.meshEngineActive = current;
    modeBtn.classList.toggle("is-mesh-beta", isBeta);
    modeBtn.title = isBeta
      ? `Mesh · ${meshEngineLabel(current, { withVersion: true })} — character clips & VFX. Click Mesh to switch engines.`
      : `Mesh · ${meshEngineLabel(current, { withVersion: true })} — click Mesh to switch engines.`;
    modeBtn.setAttribute(
      "aria-label",
      isBeta ? "Mesh Beta selected — click to switch Regular / Beta" : "Mesh Regular — click to choose Regular / Beta engine",
    );
    const badge = modeBtn.querySelector(".prompt-mode-mesh-beta-badge");
    if (badge) badge.hidden = !isBeta;
  }
  const wrap = document.querySelector(".prompt-mode-wrap--mesh");
  wrap?.classList.toggle("is-mesh-beta", isBeta);
  const harnessTip = document.querySelector("#prompt-mode-mesh-tip .prompt-mode-mesh-tip-harness");
  if (harnessTip) {
    const other = isBeta ? "Regular" : "Beta";
    harnessTip.innerHTML =
      `<b>Click Mesh</b> to switch engines — currently <b>${promptMeshEngineLabel(current)}</b>. `
      + `Pick <b>${other}</b> (or the other) in the popup: <b>Regular</b> (default img2threejs) `
      + `or <b>Beta</b> (${configured.version} — character clips &amp; VFX).`;
  }
}

function setPromptMeshEngineOpen(open, { focusSelect = false } = {}) {
  const host = document.getElementById("prompt-mesh-engine-host");
  const popup = document.getElementById("prompt-mesh-engine-popup");
  const modeBtn = document.querySelector('.prompt-mode-btn--mesh[data-prompt-mode="mesh"]');
  const next = Boolean(open);
  if (host) host.dataset.open = next ? "true" : "false";
  if (popup) popup.hidden = !next;
  if (modeBtn) modeBtn.setAttribute("aria-expanded", next ? "true" : "false");
  if (next && popup && modeBtn) {
    setPromptCadEngineOpen(false);
    setPromptAiGearOpen(false);
    const rect = modeBtn.getBoundingClientRect();
    const width = Math.min(280, Math.max(220, window.innerWidth - 24));
    let left = Math.round(rect.left);
    left = Math.max(12, Math.min(left, window.innerWidth - width - 12));
    let top = Math.round(rect.bottom + 8);
    const estimatedH = 220;
    if (top + estimatedH > window.innerHeight - 12) {
      top = Math.max(12, Math.round(rect.top - estimatedH - 8));
    }
    popup.style.position = "fixed";
    popup.style.left = `${left}px`;
    popup.style.top = `${top}px`;
    popup.style.width = `${width}px`;
    popup.style.zIndex = "12000";
    if (popup.parentElement !== document.body) {
      document.body.appendChild(popup);
    }
    syncPromptMeshEngineChip();
    if (focusSelect) {
      queueMicrotask(() => {
        const selected =
          popup.querySelector('.prompt-mesh-engine-option[aria-pressed="true"]')
          || popup.querySelector(".prompt-mesh-engine-option");
        try { selected?.focus?.({ preventScroll: true }); } catch { /* ignore */ }
      });
    }
  } else if (popup && host && popup.parentElement !== host) {
    host.appendChild(popup);
    popup.style.left = "";
    popup.style.top = "";
    popup.style.width = "";
    popup.style.position = "";
    popup.style.zIndex = "";
  }
  syncSteveIntegrationActivity();
}

function getPromptMeshEngine() {
  const sel = document.getElementById("prompt-mesh-engine");
  const fromUi = String(sel?.value || "").toLowerCase();
  if (fromUi === "beta" || fromUi === "stable") return normalizeMeshEngine(fromUi);
  try {
    const saved = String(localStorage.getItem(MESH_ENGINE_KEY) || "stable").toLowerCase();
    return normalizeMeshEngine(saved);
  } catch {
    return "stable";
  }
}

