document.querySelectorAll("[data-prompt-mode]").forEach((btn) => {
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    if (btn.disabled) return;
    const nextMode = btn.dataset.promptMode || DEFAULT_PROMPT_MODE;
    const alreadyV2 = promptMode === "v2" && nextMode === "v2" && !cadComposeRigging;
    const alreadyMesh = promptMode === "mesh" && nextMode === "mesh" && !cadComposeRigging;
    if (cadComposeRigging) exitCadComposeRigging();
    applyPromptModeUI(nextMode);
    saveActiveModelPromptState();
    if (nextMode === "v2") {
      setPromptMeshEngineOpen(false);
      const host = document.getElementById("prompt-cad-engine-host");
      const open = alreadyV2 ? host?.dataset?.open !== "true" : true;
      setPromptCadEngineOpen(open, { focusSelect: open });
    } else if (nextMode === "mesh") {
      setPromptCadEngineOpen(false);
      const host = document.getElementById("prompt-mesh-engine-host");
      const open = alreadyMesh ? host?.dataset?.open !== "true" : true;
      setPromptMeshEngineOpen(open, { focusSelect: open });
      if (!alreadyMesh) maybeOpenMeshIntroOnFirstUse();
    } else {
      setPromptCadEngineOpen(false);
      setPromptMeshEngineOpen(false);
    }
  });
});

