const wiringPromptHistory = createPromptHistoryUI({
  listEl: document.getElementById("wiring-prompt-history-list"),
  summaryEl: document.getElementById("wiring-prompt-history-summary"),
  tabSelector: ".wiring-prompt-tab",
  panes: {
    compose: document.getElementById("wiring-prompt-pane-compose"),
    history: document.getElementById("wiring-prompt-pane-history"),
  },
  refStatusEl: document.getElementById("wiring-prompt-ref-status"),
  historyTabSelector: '.wiring-prompt-tab[data-pane="history"]',
  getProjectId: () => projectId,
  onReuse: (entry, { useOriginal = true } = {}) => {
    const original = String(entry.original_prompt || "").trim();
    const improved = String(entry.prompt || "").trim();
    const text = useOriginal ? (original || improved) : (improved || original);
    const refs = wiringPromptReferencesForReuse(entry);
    if (wiringComposer) {
      wiringComposer.clearReferences();
      wiringComposer.replaceReferences(refs);
      wiringComposer.setPromptText(text);
      wiringComposer.editor?.focus?.();
    } else {
      const ta = document.getElementById("wiring-prompt-input");
      if (ta) {
        ta.value = text;
        ta.focus();
      }
    }
    wiringPromptRefs = refs;
    renderWiringPromptRefs();
    const refCount = wiringPromptRefs.length;
    const status = document.getElementById("wiring-prompt-status");
    if (status) {
      status.className = "status ok";
      status.textContent = refCount
        ? `Reused wiring prompt with ${refCount} linked reference${refCount === 1 ? "" : "s"}.`
        : "Reused wiring prompt.";
    }
  },
});

function renderWiringPromptHistoryEntries(entries = [], summary = null) {
  const pid = String(projectId || "");
  const scoped = (entries || []).filter((entry) => {
    const entryPid = String(entry?.project_id || "");
    return !entryPid || !pid || entryPid === pid;
  });
  const merged = mergePendingPromptHistory(scoped, projectId, "wiring");
  latestWiringPromptHistoryEntries = merged;
  latestWiringPromptHistorySummary = summary;
  wiringPromptHistory.render(merged, summary);
  wiringPromptHistory.setCountBadge(merged.length);
  return merged;
}

function clearWiringHistoryDisplay() {
  latestWiringPromptHistoryEntries = [];
  latestWiringPromptHistorySummary = null;
  try {
    wiringPromptHistory.render([]);
    wiringPromptHistory.setCountBadge(0);
  } catch (_) { /* history chrome optional */ }
}

