const contextLabUI = createContextLabUI({
  iconBtn: document.getElementById("prompt-ctx-icon-btn"),
  badgeEl: document.getElementById("prompt-ctx-icon-badge"),
  getProjectId: () => projectId,
  getPromptText: () => composer?.getPromptText?.() || document.getElementById("prompt-input")?.value || "",
  getPromptImages: () => (promptImages || []).map(promptImageApiPayload).filter(Boolean),
  getPromptMode: () => promptMode || "v2",
  getAiKeyFields: () => getPromptAiKeyBodyFields(),
  openKnowledge: () => document.getElementById("prompt-kb-icon-btn")?.click(),
  openSkills: () => document.getElementById("prompt-skills-toggle")?.click(),
  openRenderAgent: (opts) => renderAgentUi?.open?.(opts || { debugImprove: true }),
  sendSelectionToAgent: (payload) => {
    const sel = objectTools?.getSelection?.() || null;
    renderAgentUi?.openWithDebug?.({
      ...payload,
      selection: {
        label: sel?.label || payload?.label,
        filename: selectedFile,
        kind: sel?.kind || payload?.kind,
        faces: sel?.faceIndices || sel?.faces,
        edges: sel?.edges,
        body: sel?.bodyName || sel?.label,
      },
    });
  },
  onStatus: (kind, message) => setEditStatus(kind, message),
  startLabJobs: async ({ session, jobs, images }) => {
    if (!projectId || !session?.id) return;
    beginGenerationWatch(projectId, { kind: "improve_lab", pendingStart: true });
    const overlay = document.getElementById("improve-lab-overlay");
    overlay?.classList.remove("hidden");
    overlay?.removeAttribute("hidden");
    overlay?.setAttribute("aria-hidden", "false");
    const runOne = async (job) => {
      const body = {
        prompt: job.prompt,
        original_prompt: job.original,
        prompt_improved: job.kind !== "original",
        images: images || [],
        references: typeof promptReferencesForSubmit === "function" ? promptReferencesForSubmit() : (composer?.getReferences?.() || []),
        skills: getEnabledSkillsForPrompt({ hasImages: (images || []).length > 0, mode: promptMode || "v2" }),
        speed: getPromptGenerationSpeed?.() || "fast",
        mode: promptMode === "draw" ? "v2" : (promptMode || "v2"),
        target_mode: "new",
        lab_session_id: session.id,
        lab_slot: job.index,
        ...getPromptAiKeyBodyFields(),
        ...getKnowledgePromptFields(),
      };
      for (let attempt = 0; attempt < 6; attempt += 1) {
        try {
          await api(`/api/projects/${projectId}/prompt`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(body),
          }, 180000);
          return;
        } catch (err) {
          const msg = String(err.message || "");
          if (attempt < 5 && /409|already in progress/i.test(msg)) {
            await new Promise((resolve) => setTimeout(resolve, 900 * (attempt + 1)));
            continue;
          }
          setEditStatus("error", err.message || "Improve Lab job failed.");
          contextLabUI?.updateLabSlot?.(job.index, { status: "error", label: job.label });
          return;
        }
      }
    };
    await Promise.all((jobs || []).map((job) => runOne(job)));
  },
});
