function renderUserMenuAiCost() {
  const valueEl = document.getElementById("user-menu-ai-cost-value");
  const labelEl = document.getElementById("user-menu-ai-cost-label");
  const noteEl = document.getElementById("user-menu-ai-cost-note");
  const claudeEl = document.getElementById("user-menu-ai-cost-claude");
  const openaiEl = document.getElementById("user-menu-ai-cost-openai");
  const chatgptEl = document.getElementById("user-menu-ai-cost-chatgpt");
  const kimiEl = document.getElementById("user-menu-ai-cost-kimi");
  const otherEl = document.getElementById("user-menu-ai-cost-other");
  const chatgptRow = document.getElementById("user-menu-ai-cost-chatgpt-row");
  const kimiRow = document.getElementById("user-menu-ai-cost-kimi-row");
  const otherRow = document.getElementById("user-menu-ai-cost-other-row");
  const barClaude = document.getElementById("user-menu-ai-cost-bar-claude");
  const barOpenai = document.getElementById("user-menu-ai-cost-bar-openai");
  const barChatgpt = document.getElementById("user-menu-ai-cost-bar-chatgpt");
  const barKimi = document.getElementById("user-menu-ai-cost-bar-kimi");
  const barOther = document.getElementById("user-menu-ai-cost-bar-other");
  const wrap = document.getElementById("user-menu-ai-cost");
  if (!valueEl) return;

  const usage = workspaceAiUsage;
  if (!usage) {
    valueEl.textContent = "—";
    if (labelEl) labelEl.textContent = "This month";
    if (claudeEl) claudeEl.textContent = "—";
    if (openaiEl) openaiEl.textContent = "—";
    if (chatgptEl) chatgptEl.textContent = "—";
    if (kimiEl) kimiEl.textContent = "—";
    if (otherEl) otherEl.textContent = "—";
    chatgptRow?.classList.add("hidden");
    kimiRow?.classList.add("hidden");
    otherRow?.classList.add("hidden");
    if (barClaude) barClaude.style.flex = "0";
    if (barOpenai) barOpenai.style.flex = "0";
    if (barChatgpt) barChatgpt.style.flex = "0";
    if (barKimi) barKimi.style.flex = "0";
    if (barOther) barOther.style.flex = "0";
    wrap?.classList.add("is-empty");
    return;
  }

  const monthLabel = usage.month_label || "This month";
  const openaiTotal = Number(usage.openai_cost_usd) || 0;
  const claudeTotal = Number(usage.anthropic_cost_usd) || 0;
  const chatgptTotal = Number(usage.chatgpt_cost_usd) || 0;
  const kimiTotal = Number(usage.kimi_cost_usd) || 0;
  const otherTotal = Number(usage.other_cost_usd) || 0;
  const partsSum = openaiTotal + claudeTotal + chatgptTotal + kimiTotal + otherTotal;
  const reported = Number(usage.cost_usd);
  const total = Number.isFinite(reported) && reported >= 0 ? reported : partsSum;
  const tracked = usage.tracked_count ?? 0;
  const projectCount = usage.project_count ?? 0;

  if (labelEl) labelEl.textContent = monthLabel;
  valueEl.textContent = formatCostUsd(total) ?? "$0.00";
  if (claudeEl) claudeEl.textContent = formatCostUsd(claudeTotal) ?? "$0.00";
  if (openaiEl) openaiEl.textContent = formatCostUsd(openaiTotal) ?? "$0.00";
  if (chatgptEl) chatgptEl.textContent = formatCostUsd(chatgptTotal) ?? "$0.00";
  if (kimiEl) kimiEl.textContent = formatCostUsd(kimiTotal) ?? "$0.00";
  if (otherEl) otherEl.textContent = formatCostUsd(otherTotal) ?? "$0.00";
  chatgptRow?.classList.toggle("hidden", chatgptTotal <= 0);
  kimiRow?.classList.toggle("hidden", kimiTotal <= 0);
  otherRow?.classList.toggle("hidden", otherTotal <= 0);

  const denom = Math.max(partsSum, total, 0.0001);
  if (barClaude) barClaude.style.flex = String(Math.max(0, claudeTotal / denom));
  if (barOpenai) barOpenai.style.flex = String(Math.max(0, openaiTotal / denom));
  if (barChatgpt) barChatgpt.style.flex = String(Math.max(0, chatgptTotal / denom));
  if (barKimi) barKimi.style.flex = String(Math.max(0, kimiTotal / denom));
  if (barOther) barOther.style.flex = String(Math.max(0, otherTotal / denom));
  wrap?.classList.toggle("is-empty", total <= 0 && tracked <= 0);
  const basis = usage.cost_basis === "estimated_list_price"
    ? "list-price estimate from your tracked prompts — not provider invoices"
    : "estimated from tracked prompt token usage";
  const chatNote = chatgptTotal > 0
    ? `ChatGPT plan ${formatCostUsd(chatgptTotal)} is API-equivalent, not a ChatGPT invoice.`
    : "";
  wrap?.setAttribute(
    "title",
    `${tracked} tracked prompt${tracked === 1 ? "" : "s"} · ${projectCount} project${projectCount === 1 ? "" : "s"} · ${basis}`
  );
  if (noteEl) {
    noteEl.textContent = chatNote
      ? `Est. list price · ${chatNote}`
      : "Est. list price from your tracked prompts — not billed invoices";
  }
}

function compactTokenCount(value) {
  const total = Number(value) || 0;
  if (total >= 1_000_000) return `${(total / 1_000_000).toFixed(2)}M tokens`;
  if (total >= 1000) return `${(total / 1000).toFixed(1)}k tokens`;
  return `${total} tokens`;
}

function usageTokenTotal(usage) {
  if (!usage) return 0;
  return Number(usage.total_tokens) || Number(usage.input_tokens || 0) + Number(usage.output_tokens || 0) || 0;
}

function formatUsageStopLabel(entry) {
  if (!entry) return "";
  const cost = entry.cost_usd != null ? formatCostUsd(entry.cost_usd) : null;
  const tokens = usageTokenTotal(entry.usage);
  const tokenLabel = tokens > 0 ? compactTokenCount(tokens) : "";
  if (cost && tokenLabel) return `${cost} · ${tokenLabel}`;
  return cost || tokenLabel || "";
}

/** Put the stopped generation’s prompt back in the compose draft (Mesh + 2.0). */
function restoreComposeDraftAfterStop({ prompt, promptMode = null } = {}) {
  const text = String(prompt || "").trim();
  if (!text || !composer) return false;
  const current = String(composer.getPromptText?.() || "").trim();
  // Don't clobber if the user already typed something new.
  if (current && current !== text) return false;
  restoringModelPromptState = true;
  try {
    composer.setPromptText?.(text);
    if (promptMode) {
      const mode = promptModeForRef(promptMode);
      if (mode === "mesh" || mode === "fusion" || mode === "v2" || mode === "vibecad" || mode === "mac" || mode === "architect") {
        try {
          applyPromptModeUI(mode);
        } catch {
          /* best-effort */
        }
      }
    }
  } finally {
    restoringModelPromptState = false;
  }
  try {
    saveActiveModelPromptState();
  } catch {
    /* ignore */
  }
  sendCollabPresence?.();
  return true;
}

function promptTextForStoppedGeneration(gen = {}, fallback = "") {
  return (
    String(gen?.prompt || "").trim()
    || String(lastPromptCopyContext?.promptText || lastPromptCopyContext?.prompt || "").trim()
    || String(fallback || "").trim()
  );
}

function stoppedStatusMessage(entry, fallback = "Generation stopped.") {
  const usageLabel = formatUsageStopLabel(entry);
  return usageLabel ? `${fallback.replace(/\.$/, "")}. Used ${usageLabel} before stopping.` : fallback;
}

async function recordStoppedRenderHistory(pid, { prompt, traceId, baseFilename, speed } = {}) {
  const text = String(prompt || "").trim();
  if (!pid || !text) return null;
  try {
    const data = await api(`/api/projects/${pid}/prompt-history/stopped`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: text,
        trace_id: traceId || null,
        prompt_mode: "render",
        kind: "render",
        base_filename: baseFilename || null,
        speed: speed || "fast",
        message: "Stopped before completion.",
      }),
    });
    if (pid === projectId) await refreshPromptHistory();
    return data?.entry || null;
  } catch (_) {
    return null;
  }
}

function renderProjectCostThumb(entries = [], summary = null) {
  const wrap = document.getElementById("project-cost-thumb");
  if (!wrap) return;
  const totalEl = document.getElementById("project-cost-thumb-total");
  const costEl = document.getElementById("project-cost-thumb-cost");
  const promptEl = document.getElementById("project-cost-thumb-prompts");
  const tokenEl = document.getElementById("project-cost-thumb-tokens");
  const chartEl = document.getElementById("project-cost-thumb-chart");
  const creditEl = document.getElementById("project-cost-thumb-credits");
  const totalCost = Number((summary?.cost_usd ?? 0) > 0 ? summary.cost_usd : (summary?.openai_cost_usd ?? 0)) || 0;
  const costLabel = formatCostUsd(totalCost) || "$0.00";
  const tracked = Number(summary?.tracked_count ?? entries.filter((e) => e.cost_usd != null || e.usage).length) || 0;
  const tokens = usageTokenTotal(summary?.usage) || entries.reduce((sum, e) => sum + usageTokenTotal(e.usage), 0);
  if (totalEl) totalEl.textContent = costLabel;
  if (costEl) costEl.textContent = `Cost ${costLabel}`;
  if (promptEl) promptEl.textContent = `${tracked} tracked prompt${tracked === 1 ? "" : "s"}`;
  if (tokenEl) tokenEl.textContent = compactTokenCount(tokens);
  if (creditEl) {
    const credits = aiStatus?.credits || {};
    const balance = Number(credits.balance_cents || 0) / 100;
    const percent = credits.last_purchase_percent_left;
    creditEl.textContent = `Credits ${formatCostUsd(balance) || "$0.00"}`;
    creditEl.title = percent == null
      ? "Open AI keys to buy shared-key credits."
      : `${Math.max(0, Math.min(100, Number(percent))).toFixed(0)}% left from your last credit purchase. Click to buy more.`;
    creditEl.classList.toggle("hidden", !credits.use_platform_key && balance <= 0);
  }
  if (chartEl) {
    const recent = entries
      .slice()
      .reverse()
      .slice(-14)
      .map((e) => Number(e.cost_usd) || 0);
    // Keep a readable sparkline even with sparse history.
    while (recent.length < 8) recent.unshift(0);
    const values = recent.length ? recent : [0, 0, 0, 0, 0, 0, 0, 0];
    const max = Math.max(0.000001, ...values);
    const chartH = 30; // fits inside .project-cost-thumb-chart (40px - padding)
    chartEl.innerHTML = values
      .map((value) => {
        const h = value > 0
          ? Math.max(4, Math.round((value / max) * chartH))
          : 2;
        const tip = formatCostUsd(value) || "$0.00";
        return `<i style="height:${h}px" title="${tip}"></i>`;
      })
      .join("");
  }
  wrap.classList.toggle("is-empty", !tracked);
}

