function promptHistoryReferencesForReuse(entry = {}) {
  const saved = Array.isArray(entry.references) ? entry.references : [];
  const refs = saved
    .filter((ref) => ref?.id && ref?.type)
    .map((ref) => ({
      ...ref,
      projectId: ref.projectId || projectId || null,
    }));
  if (refs.length) return refs;

  const prompt = String(entry.prompt || "");
  const asksForDxf = /\b(dxf|dwg|drawing|blueprint|from this .* file)\b/i.test(prompt);
  if (!asksForDxf) return [];
  const drawings = (lastProjectBrowser?.drawings || []).filter((drawing) => /\.dxf$/i.test(String(drawing?.name || "")));
  return drawings.slice(0, 4).map((drawing) => {
    const filename = drawing.name || drawing.filename;
    const stem = drawing.stem || fileStem(filename);
    return {
      id: `dxf:${projectId || "project"}:${filename}`,
      type: "dxf",
      token: `@${String(stem || "dxf").replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "dxf"}`,
      label: filename,
      filename,
      stem,
      format: "dxf",
      projectId,
    };
  });
}

function newPromptHistoryId() {
  try {
    const uuid = crypto?.randomUUID?.();
    if (uuid) return uuid.replace(/-/g, "").slice(0, 12);
  } catch {
    /* fall through */
  }
  return `p${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
}

function promptHistorySortNewestFirst(entries = []) {
  return [...entries].sort(
    (a, b) => new Date(b.created_at || 0).getTime() - new Date(a.created_at || 0).getTime(),
  );
}

function pendingPromptHistoryForProject(pid = projectId) {
  if (!pid) return [];
  return [...pendingPromptHistoryEntries.values()].filter((entry) => entry.project_id === pid);
}

function mergePendingPromptHistory(entries = [], pid = projectId, kind = null) {
  const serverEntries = (entries || []).filter((entry) => !entry?._pending);
  const serverIds = new Set(serverEntries.map((entry) => String(entry?.id || "")).filter(Boolean));
  const serverTraces = new Set(serverEntries.map((entry) => String(entry?.trace_id || "")).filter(Boolean));
  for (const id of serverIds) {
    if (pendingPromptHistoryEntries.has(id)) pendingPromptHistoryEntries.delete(id);
  }
  const wantedKind = kind ? String(kind).toLowerCase() : null;
  const pending = pendingPromptHistoryForProject(pid)
    .filter((entry) => {
      if (serverIds.has(String(entry.id || ""))) return false;
      if (entry.trace_id && serverTraces.has(String(entry.trace_id))) {
        pendingPromptHistoryEntries.delete(entry.id);
        return false;
      }
      const entryKind = String(entry.kind || "cad").toLowerCase();
      if (wantedKind) return entryKind === wantedKind;
      return entryKind !== "wiring";
    });
  return promptHistorySortNewestFirst([...pending, ...serverEntries]);
}

function renderPromptHistoryEntries(entries = [], summary = null) {
  const mergedEntries = mergePendingPromptHistory(entries, projectId);
  latestPromptHistoryEntries = mergedEntries;
  promptHistory.render(mergedEntries, summary);
  promptHistory.setCountBadge(mergedEntries.length);
  renderProjectCostThumb(mergedEntries, summary);
  try { renderRailPromptHistory(); } catch (_) { }
  try { renderCostsPanel(); } catch (_) { }
  try {
    if (document.querySelector('[data-right-panel="analytics"].active')) renderAnalyticsPanel();
  } catch (_) { }
  return mergedEntries;
}

function stampWiringPromptHistoryPending({
  prompt = "",
  promptId = "",
  traceId = "",
  model = "",
  provider = "",
  speed = "",
} = {}) {
  const selectedModelInfo = typeof getSelectedPromptModelInfo === "function"
    ? getSelectedPromptModelInfo()
    : {};
  const id = String(promptId || "").trim() || newPromptHistoryId();
  const existing = pendingPromptHistoryEntries.get(id);
  if (existing) {
    updatePendingPromptHistoryEntry(id, {
      status: "running",
      success: false,
      prompt: prompt || existing.prompt,
      ...(traceId ? { trace_id: traceId } : {}),
      ...(model ? { model } : {}),
      ...(provider ? { provider } : {}),
    });
    return id;
  }
  if (latestWiringPromptHistoryEntries.some((entry) => (
    String(entry?.id || "") === id
    || (traceId && String(entry?.trace_id || "") === String(traceId))
  ))) {
    return id;
  }
  addPendingPromptHistoryEntry({
    id,
    project_id: projectId,
    prompt: prompt || "Wiring generation",
    success: false,
    status: "running",
    _pending: true,
    created_at: new Date().toISOString(),
    user_id: currentUser?.id || null,
    user_name: currentUser?.display_name || currentUser?.email || "You",
    user_avatar_url: currentUser?.avatar_url || null,
    kind: "wiring",
    prompt_mode: "wiring",
    speed: speed || (typeof getWiringGenerationSpeed === "function" ? getWiringGenerationSpeed() : "fast"),
    model: model || selectedModelInfo.model || (typeof loadWiringPreferredModel === "function" ? loadWiringPreferredModel() : ""),
    provider: provider || selectedModelInfo.provider || "",
    ...(traceId ? { trace_id: traceId } : {}),
  });
  return id;
}

function hydrateWiringHistoryFromGeneration(gen, pid = projectId) {
  if (!gen || !pid || String(gen.kind || "").toLowerCase() !== "wiring") return;
  const status = String(gen.status || "").toLowerCase();
  if (!["accepted", "pending", "queued", "running", "starting"].includes(status)) return;
  stampWiringPromptHistoryPending({
    prompt: String(gen.prompt || lastPromptCopyContext?.promptText || "").trim(),
    promptId: gen.prompt_id || lastPromptCopyContext?.promptHistoryId || "",
    traceId: gen.trace_id || "",
    model: gen.model || "",
    provider: gen.provider || "",
    speed: gen.speed || "",
  });
}

function addPendingPromptHistoryEntry(entry = {}) {
  if (!entry.id || !entry.project_id) return;
  pendingPromptHistoryEntries.set(entry.id, entry);
  if (String(entry.kind || "").toLowerCase() === "wiring") {
    renderWiringPromptHistoryEntries(
      latestWiringPromptHistoryEntries,
      latestWiringPromptHistorySummary,
    );
    return;
  }
  renderPromptHistoryEntries(
    latestPromptHistoryEntries,
    allProjects.find((p) => p.id === entry.project_id)?.usage_summary || null,
  );
}

function updatePendingPromptHistoryEntry(id, patch = {}) {
  if (!id || !pendingPromptHistoryEntries.has(id)) return;
  pendingPromptHistoryEntries.set(id, {
    ...pendingPromptHistoryEntries.get(id),
    ...patch,
  });
  const next = pendingPromptHistoryEntries.get(id);
  if (String(next?.kind || "").toLowerCase() === "wiring") {
    renderWiringPromptHistoryEntries(
      latestWiringPromptHistoryEntries,
      latestWiringPromptHistorySummary,
    );
    return;
  }
  renderPromptHistoryEntries(
    latestPromptHistoryEntries,
    allProjects.find((p) => p.id === projectId)?.usage_summary || null,
  );
}

function promptHistoryPatchFromGenerationStatus(job = {}) {
  const patch = {};
  for (const key of [
    "trace_id",
    "filename",
    "model",
    "provider",
    "speed",
    "target_mode",
    "message",
    "error",
    "usage",
    "cost_usd",
    "ai_calls",
    "skills",
  ]) {
    if (job[key] !== undefined && job[key] !== null && job[key] !== "") {
      if (key === "error" && isVerboseGenerationFailureMessage(job[key])) {
        patch[key] = null;
      } else {
        patch[key] = job[key];
      }
    }
  }
  if (job.prompt) patch.prompt = job.prompt;
  if (job.mode || job.prompt_mode || job.harness) {
    patch.prompt_mode = promptModeForRef(job.mode || job.prompt_mode || job.harness);
  }
  if (job.codex_agent || job.jake_codex_agent) {
    patch.codex_agent = true;
  }
  const status = String(job.status || "").toLowerCase();
  if (["accepted", "pending", "queued", "running", "starting"].includes(status)) {
    patch.status = "running";
    patch.success = false;
    const liveLabel = String(job.progress?.label || job.progress?.thinking || job.label || "").trim();
    if (liveLabel) patch.message = liveLabel;
  } else if (status === "complete") {
    patch.status = "complete";
    patch.success = true;
  } else if (["failed", "canceled", "stopped"].includes(status)) {
    patch.status = status;
    patch.success = false;
  }
  return patch;
}

function syncPendingPromptHistoryFromGeneration(gen = {}, pid = projectId) {
  if (!gen || !pid) return;
  const candidates = [];
  if (gen.prompt_id || gen.trace_id) candidates.push(gen);
  if (Array.isArray(gen.jobs)) candidates.push(...gen.jobs);
  const seen = new Set();
  let hydratedChanged = false;
  for (const job of candidates) {
    const id = String(job?.prompt_id || "").trim();
    const trace = String(job?.trace_id || "").trim();
    const key = id || trace;
    if (!key || seen.has(key)) continue;
    seen.add(key);
    const patch = promptHistoryPatchFromGenerationStatus(job);
    if (id && pendingPromptHistoryEntries.has(id)) {
      const pending = pendingPromptHistoryEntries.get(id);
      if (pending?.project_id && pending.project_id !== pid) continue;
      updatePendingPromptHistoryEntry(id, patch);
      continue;
    }
    if (pid !== projectId) continue;
    const idx = latestPromptHistoryEntries.findIndex((entry) => (
      (id && String(entry?.id || "") === id)
      || (trace && String(entry?.trace_id || "") === trace)
    ));
    if (idx < 0) continue;
    latestPromptHistoryEntries[idx] = { ...latestPromptHistoryEntries[idx], ...patch };
    hydratedChanged = true;
  }
  if (hydratedChanged) {
    renderPromptHistoryEntries(
      latestPromptHistoryEntries,
      allProjects.find((p) => p.id === pid)?.usage_summary || null,
    );
  }
}

let promptHistoryAbort = null; // leakfix15
async function refreshPromptHistory() {
  if (!projectId) {
    if (promptHistoryAbort) {
      try { promptHistoryAbort.abort(); } catch (_) { /* ignore */ }
      promptHistoryAbort = null;
    }
    promptHistory.render([], null);
    promptHistory.setCountBadge(0);
    renderProjectCostThumb([], null);
    return [];
  }
  const pid = projectId;
  if (promptHistoryAbort) {
    try { promptHistoryAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  promptHistoryAbort = ctl;
  try {
    const data = await api(`${projectHistoryApiPath(pid, "prompt-history")}`, { signal: ctl.signal });
    if (ctl.signal.aborted || projectId !== pid) return latestPromptHistoryEntries;
    const entries = data.entries || [];
    try {
      renderPromptHistoryEntries(entries, data.usage_summary);
    } catch (renderErr) {
      console.error("prompt history render failed:", renderErr);
    }
    if (data.usage_summary) {
      const proj = allProjects.find((p) => p.id === projectId);
      if (proj) {
        proj.usage_summary = data.usage_summary;
        workspaceBrowser?.render?.();
      }
    }
    const proj = allProjects.find((p) => p.id === projectId);
    if (proj && data.generated_by) {
      proj.generated_by = data.generated_by;
      if (!proj.owner_name && data.generated_by.display_name) {
        proj.owner_name = data.generated_by.display_name;
      }
      workspaceBrowser?.render?.();
    }
    return latestPromptHistoryEntries;
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return latestPromptHistoryEntries;
    if (projectId === pid) renderPromptHistoryEntries([], null);
    return [];
  } finally {
    if (promptHistoryAbort === ctl) promptHistoryAbort = null;
  }
}

