async function ensureMissingBrowserComponentsLoaded({ keepGizmoOn = null, fitView = false } = {}) {
  if (!projectId) return;
  const browser = normalizeBrowser(await api(`/api/projects/${projectId}`));
  const visibleComps = (browser.components || []).filter((c) => !isBrowserComponentHidden(c));
  // Only pull auto-load / primary parts. Loading every browser entry after paint/edit
  // was resurrecting leftover edit artifacts as overlapping twin models.
  const toConsider = visibleComps.filter(
    (c) => !isCatalogHardwareComponent(c) && (c.auto_load === true || c.primary === true),
  );
  // Also keep any already-loaded siblings visible, but do not invent new ones.
  let loadedAny = false;
  for (const entry of toConsider) {
    // Same part can be catalogued as .step while the viewport holds the painted/edited .glb
    // (or vice versa). Never load a second copy when any same-stem entry is already present.
    const existing =
      (projectAssembly.has(entry.name) && entry.name)
      || assemblyCatalogMatchingStem(entry.name)
      || assemblyCatalogMatchingStem(entry.viewer_filename);
    if (existing) {
      projectAssembly.setVisible(existing, true);
      continue;
    }
    const viewer = entry.viewer_filename || entry.name;
    const append = projectAssembly.count() > 0;
    const ok = await loadModel(projectFileUrl(projectId, viewer), viewer, {
      projectId,
      append,
      catalogFilename: entry.name,
      center: !hasBakedPlacement(entry) && !append,
      fitView: false,
      autoGizmo: false,
      autoGridPlace: append && !hasBakedPlacement(entry),
    });
    if (ok || projectAssembly.has(entry.name)) loadedAny = true;
  }
  currentMesh = projectAssembly.getRoot();
  rebuildGrid();
  if (keepGizmoOn && projectAssembly.has(keepGizmoOn)) {
    selectAssemblyComponent(keepGizmoOn, { autoGizmo: true, fitView: false });
  } else if (fitView || loadedAny) {
    seatAssemblyToFloor();
    fitCamera();
  }
}

async function afterModelEdit(data) {
  const prevCatalog = data?.replaceCatalog || data?.replace_catalog || catalogNameForMesh(transformControls.object) || selectedFile;
  const restorePart = (() => {
    const sel = objectTools.getSelection?.();
    if (!sel?.partLevel) return null;
    return {
      catalogName: sel.catalogName || prevCatalog || selectedFile,
      bodyIndex: sel.bodyIndex,
    };
  })();
  try { transformControls.detach(); } catch (_) { }
  releaseCadTransformPivot();
  // Keep the browser/assembly identity stable across paint/edit exports that change
  // extension (.step → .glb). Otherwise ensureMissing reloads the .step as a twin.
  const stableCatalog = prevCatalog || data.filename;
  // Count components that are NOT the one about to be replaced so we know whether
  // other components are in the assembly. If yes, use append+replaceCatalog to swap
  // the reloaded mesh in-place without ever blanking the scene.
  const prevStem = fileStem(prevCatalog || "").replace(/_edited(?:_\d+)?$/i, "");
  const siblingsInAssembly = [...projectAssembly.list()].filter(([name]) => {
    if (name === prevCatalog || name === stableCatalog) return false;
    const other = fileStem(name).replace(/_edited(?:_\d+)?$/i, "");
    return !prevStem || other !== prevStem;
  }).length;
  const inAssembly = siblingsInAssembly > 0;
  const alreadyPresent = Boolean(
    (prevCatalog && projectAssembly.has(prevCatalog))
    || (stableCatalog && projectAssembly.has(stableCatalog))
    || assemblyCatalogMatchingStem(prevCatalog)
    || assemblyCatalogMatchingStem(data.filename),
  );
  const isBakedTransform = data?.action === "transform" || data?.action === "body_transform";
  const placementBaseline = isBakedTransform ? transformBaselineFromPayload(data?.placementBaseline) : null;
  const actionKey = String(data?.action || "").toLowerCase();
  const isTextureRemove = actionKey === "texture_remove" || actionKey === "remove_texture"
    || /remove\s*textur/i.test(String(data?.label || ""));
  const isTextureEdit = !isTextureRemove && (
    /texture/i.test(actionKey) || /texture/i.test(String(data?.label || ""))
  );
  const isFaceEdit =
    actionKey === "face_pull"
    || actionKey === "face_pad"
    || data?.kind === "face_pull"
    || data?.pipeline === "kernel" && /face|pad|pocket|press.?pull/i.test(String(data?.label || data?.action || "face"))
    || data?.pipeline === "freecad" && /face|pad|pocket|press.?pull|extrude/i.test(String(data?.label || data?.action || "face"))
    || /pulled|face.?pull|face.?pad|pad\/pocket|kernel pad/i.test(String(data?.label || ""));
  // Keep legacy alias used below.
  const isFacePull = isFaceEdit;

  // Snapshot authored/Mesh look BEFORE we drop the assembly mesh — transform
  // reloads as `*_edited.glb` and used to fall through to CAD plastic.
  let savedTransform = null;
  const prevMesh = projectAssembly.get?.(prevCatalog || selectedFile) || currentMesh;
  // Texture *apply* must keep maps; texture *remove* must fall back to CAD plastic.
  const keepAuthoredStyle =
    !isTextureRemove && (
      isTextureEdit
      || hasMeshFactorySibling(data.filename)
      || hasMeshFactorySibling(stableCatalog)
      || hasMeshFactorySibling(prevCatalog)
      || (prevMesh ? prefersAuthoredShading(prevMesh, prevCatalog || data.filename || "") : false)
    );
  if (prevMesh && !isBakedTransform) {
    prevMesh.updateMatrixWorld(true);
    savedTransform = {
      position: prevMesh.position.clone(),
      quaternion: prevMesh.quaternion.clone(),
      scale: prevMesh.scale.clone(),
    };
  }

  // Drop same-stem twins before reload so paint/color/transform cannot leave a ghost mesh.
  // Include stableCatalog itself — loadModel will re-add the fresh object under that key.
  // Drop only this catalog's pre-edit twin — never sibling models that share a name prefix.
  const replaceNames = new Set(
    [prevCatalog, stableCatalog, data.filename].filter(Boolean).map((n) => String(n)),
  );
  for (const [name] of [...projectAssembly.list()]) {
    const stem = fileStem(name).replace(/_edited(?:_\d+)?$/i, "");
    if (
      replaceNames.has(name)
      || (prevStem && stem === prevStem && /_edited(?:_\d+)?$/i.test(fileStem(name)))
    ) {
      projectAssembly.remove(name);
    }
  }

  selectedFile = stableCatalog;
  bumpModelCacheEpoch();
  await refreshFiles();
  await loadModel(data.url, data.filename, {
    cacheBust: true,
    projectId,
    preservePlacement: isBakedTransform ? !!placementBaseline : true,
    // Face Pad/Pocket must stay put — never re-center or re-pivot after kernel rebuild.
    center: isBakedTransform || isFaceEdit ? false : !hasBakedPlacement(data.filename),
    normalizePivot: !isBakedTransform && !isFaceEdit && !hasBakedPlacement(data.filename),
    resetTransform: isBakedTransform && !placementBaseline,
    savedTransform: isBakedTransform ? placementBaseline : savedTransform,
    catalogFilename: stableCatalog,
    append: inAssembly || alreadyPresent,
    replaceCatalog: alreadyPresent && prevCatalog && prevCatalog !== stableCatalog ? prevCatalog : null,
    fitView: false,
    // Avoid popping the transform gizmo after Extrude/Cut — it feels like a hard reload.
    autoGizmo: isBakedTransform ? false : !isFacePull && !inAssembly,
    // Mesh / textured / authored PBR must survive transform bake+reload (not CAD plastic).
    styleMode: keepAuthoredStyle ? "shaded" : "auto",
  });
  gizmoPanel.resetDragBaseline?.();
  // Transforms already swapped the edited mesh — do not re-pull browser primaries,
  // which can resurrect the pre-edit twin and cause z-fighting / pose bounce.
  // Same for face Pad/Pocket: assembly already has the rebuilt solid in place.
  if (!isBakedTransform && !isFaceEdit && projectAssembly.count() > 0) {
    await ensureMissingBrowserComponentsLoaded({
      keepGizmoOn: null,
      fitView: false,
    });
  } else if (isBakedTransform && restorePart?.catalogName && projectAssembly.has(restorePart.catalogName)) {
    const root = projectAssembly.get(restorePart.catalogName);
    const meshes = listObjectMeshes(root);
    const mesh = meshes[restorePart.bodyIndex] || meshes[0] || root;
    objectTools.selectObject?.({
      mesh,
      root,
      bodyIndex: restorePart.bodyIndex,
      catalogName: restorePart.catalogName,
      partLevel: true,
      wholeModel: false,
      isRoot: false,
    });
    showObjectGizmo(mesh, "translate", { switchTab: false });
  } else if (isBakedTransform && stableCatalog && projectAssembly.has(stableCatalog)) {
    selectAssemblyComponent(stableCatalog, { autoGizmo: true, fitView: false });
  }
  if (data.timeline) {
    timelineData = data.timeline;
    timeline.setTimeline(data.timeline, { scroll: true, scrollAlign: "end" });
  }
  // Live drag undo stays on the object pose. Cmd+Z must not walk the
  // generation timeline (that restores other models / can switch projects).
  if (isBakedTransform) {
    for (let i = viewportUndoStack.length - 1; i >= 0; i -= 1) {
      const entry = viewportUndoStack[i];
      if (entry?.type === "transform" && !entry.committed) {
        entry.committed = true;
        break;
      }
    }
  }
  await refreshTimeline();
  await refreshPromptHistory();
  if (viewportXR?.isPresenting?.()) {
    try { viewportXR.restoreRoomPoseAfterCadEdit?.(); } catch (_) { }
  }
  meshEditSession.syncTarget(currentMeshEditIdentity(stableCatalog));
  restoreFullViewportAfterInteraction({ rebuildFloor: true });
}

let objectClipboard = null;
let promptLinkClipboard = null;
const viewportUndoStack = [];
const viewportRedoStack = [];
let viewportTransformPersistInFlight = false;

function captureViewportAssemblyState() {
  return projectAssembly.list().map(([name, obj]) => ({
    name,
    visible: obj?.visible !== false,
  }));
}

function pushViewportUndoAction(action, { clearRedo = true } = {}) {
  if (!action) return;
  viewportUndoStack.push(action);
  if (viewportUndoStack.length > 20) viewportUndoStack.shift();
  if (clearRedo) viewportRedoStack.length = 0;
}

function hideXrCreateCadAction(action) {
  if (!action) return;
  const name = action.catalogName || action.filename || "";
  if (name) cancelCreateSolidPersist(name);
  const obj = (name && projectAssembly.get?.(name)) || action.object;
  if (obj) {
    action.object = obj;
    if (!action.catalogName) action.catalogName = name || catalogNameForMesh?.(obj) || "";
    obj.visible = false;
    obj.userData = { ...(obj.userData || {}), xrParked: true, xrDrawable: false };
  }
}

function showXrCreateCadAction(action) {
  if (!action) return;
  const obj = action.object;
  const name = action.catalogName || action.filename || obj?.userData?.catalogName || "";
  if (obj) {
    obj.visible = true;
    if (obj.userData) {
      obj.userData.xrParked = false;
      obj.userData.xrDrawable = true;
    }
    if (name && !projectAssembly.has?.(name)) {
      try { projectAssembly.add(name, obj); } catch (_) { }
    }
  }
}

function undoXrCreateCadOnly() {
  const top = viewportUndoStack[viewportUndoStack.length - 1];
  if (top?.type !== "xr_create") return false;
  viewportUndoStack.pop();
  viewportRedoStack.push(top);
  hideXrCreateCadAction(top);
  setEditStatus?.("ok", "Undid VR create.");
  return true;
}

function redoXrCreateCadOnly() {
  const top = viewportRedoStack[viewportRedoStack.length - 1];
  if (top?.type !== "xr_create") return false;
  viewportRedoStack.pop();
  viewportUndoStack.push(top);
  showXrCreateCadAction(top);
  setEditStatus?.("ok", "Redid VR create.");
  return true;
}

// isTimelineTransformEntry imported from locked viewport-transform-undo.js

function invertTransformDelta(delta = {}) {
  const translation = Array.isArray(delta.translation) ? delta.translation.map((n) => -Number(n || 0)) : [0, 0, 0];
  const rotation = Array.isArray(delta.rotation) ? delta.rotation.map((n) => -Number(n || 0)) : [0, 0, 0];
  const scale = Number(delta.scale);
  return {
    translation,
    rotation,
    scale: Number.isFinite(scale) && Math.abs(scale) > 1e-9 ? 1 / scale : 1,
  };
}

async function persistCommittedTransform(action, { invert = false } = {}) {
  if (viewportTransformPersistInFlight) return false;
  const filename = kernelApiFilename(action?.filename || selectedFile);
  const delta = invert ? invertTransformDelta(action?.delta || {}) : (action?.delta || null);
  if (!projectId || !filename || !delta) return false;
  const body = { mode: "delta" };
  if (delta.translation?.some((n) => Math.abs(n) > 1e-12)) body.translation = delta.translation;
  if (delta.rotation?.some((n) => Math.abs(n) > 1e-9)) body.rotation_deg = delta.rotation;
  if (Math.abs((delta.scale ?? 1) - 1) > 1e-9) body.scale = delta.scale;
  if (!body.translation && !body.rotation_deg && body.scale == null) return false;
  const tb = action.transformBody || {};
  const useBody = tb.bodyIndex != null && Number(tb.bodyCount) > 1 && tb.isRoot === false;
  if (useBody) {
    body.body_index = tb.bodyIndex;
    if (tb.bodyName) body.body_name = tb.bodyName;
  }
  const endpoint = useBody ? "transform-body" : "transform";
  viewportTransformPersistInFlight = true;
  try {
    const data = await api(`/api/projects/${projectId}/files/${encodeURIComponent(filename)}/${endpoint}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    await afterModelEdit({
      ...data,
      replaceCatalog: filename,
      action: useBody ? "body_transform" : "transform",
      placementBaseline: action.catalogPose || action.before,
    });
    sendCollabPresence({ moving: false });
    return true;
  } finally {
    viewportTransformPersistInFlight = false;
  }
}

function undoViewportAction() {
  if (viewportXR?.getAiDrawWorkspace?.()?.isActive()) { void viewportXR.getAiDrawWorkspace().action("undo"); return true; }
  if (viewportTransformPersistInFlight) return true;
  if (viewportUndoStack[viewportUndoStack.length - 1]?.type === "xr_create") {
    const ok = undoXrCreateCadOnly();
    try { viewportXR?.undoXrCreateVisual?.(); } catch (_) { }
    return ok;
  }
  // Peek first: transform on stack must never fall through to generation undo.
  if (viewportUndoBlocksTimelineFallthrough(viewportUndoStack)) {
    const action = viewportUndoStack.pop();
    if (action?.committed && action.delta) {
      viewportRedoStack.push(action);
      gizmoPanel.cancelPendingApply?.();
      void persistCommittedTransform(action, { invert: true }).then((ok) => {
        if (ok) {
          setEditStatus("ok", "Undid move/rotate.");
          return;
        }
        viewportRedoStack.pop();
        viewportUndoStack.push(action);
        setEditStatus("error", "Could not undo move.");
      }).catch((err) => {
        viewportRedoStack.pop();
        viewportUndoStack.push(action);
        setEditStatus("error", err?.message || "Could not undo move.");
      });
      return true;
    }
    const result = undoViewportTransformAction(action, {
      undoStack: viewportUndoStack,
      redoStack: viewportRedoStack,
      resolveMesh: resolveViewportTransformTarget,
      cancelPendingApply: () => gizmoPanel.cancelPendingApply?.(),
      resetDragBaseline: () => gizmoPanel.resetDragBaseline?.(),
      refreshGizmo: () => gizmoPanel.refresh?.(),
      setStatus: setEditStatus,
    });
    if (result?.undid) {
      projectAssembly.invalidateBounds?.();
      sendCollabPresence({ moving: false });
    }
    return Boolean(result?.handled);
  }
  const action = viewportUndoStack.pop();
  if (!action) return false;
  if (action.type === "texture_wrap") {
    viewportRedoStack.push(action);
    const prev = Number(action.prevIndex);
    if (Number.isInteger(prev) && prev >= 0) {
      void restoreTimelineAsLatest(prev).then(() => {
        setEditStatus("ok", "Undid texture wrap.");
      });
      return true;
    }
    if (action.prevCatalog && projectId) {
      void (async () => {
        try {
          await loadModel(projectFileUrl(projectId, action.prevCatalog), action.prevCatalog, {
            projectId,
            append: true,
            replaceCatalog: action.prevCatalog,
            catalogFilename: action.prevCatalog,
            fitView: false,
          });
          setEditStatus("ok", "Undid texture wrap.");
        } catch (err) {
          setEditStatus("error", err?.message || "Could not undo texture wrap.");
        }
      })();
      return true;
    }
    setEditStatus("error", "Nothing to undo for that texture wrap.");
    return true;
  }
  if (action.type === "fusion-component-drop") {
    const beforeNames = new Set((action.before || []).map((item) => item.name));
    for (const [name] of [...projectAssembly.list()]) {
      if (!beforeNames.has(name)) projectAssembly.remove(name);
    }
    for (const item of action.before || []) {
      projectAssembly.setVisible(item.name, item.visible);
    }
    const restoreName = action.selectedBefore || (action.before || []).find((item) => item.visible)?.name || null;
    if (restoreName && projectAssembly.has(restoreName)) {
      selectAssemblyComponent(restoreName, { fitView: true });
    } else {
      objectTools.clearSelection?.();
      transformControls.detach();
      gizmoPanel.hide();
      document.getElementById("btn-gizmo")?.classList.remove("active");
      currentMesh = projectAssembly.getRoot();
      fitCamera();
    }
    setEditStatus("ok", `Undo drop: removed ${action.label || "component"}.`);
    return true;
  }
  return false;
}

function resolveViewportTransformTarget(action = {}) {
  // Prefer the live gizmo target — part moves attach a child mesh, not the catalog root.
  if (transformControls.object) return transformControls.object;
  if (action.liveTarget === "transform-controls" && transformControls.object) {
    return transformControls.object;
  }
  const wantName = action.filename || null;
  if (wantName && projectAssembly.get(wantName)) return projectAssembly.get(wantName);
  if (currentMesh) return currentMesh;
  if (wantName) {
    for (const [name, obj] of projectAssembly.list() || []) {
      if (name === wantName) return obj;
    }
  }
  return null;
}

function redoViewportAction() {
  if (viewportXR?.getAiDrawWorkspace?.()?.isActive()) { void viewportXR.getAiDrawWorkspace().action("redo"); return true; }
  if (viewportTransformPersistInFlight) return true;
  if (viewportRedoStack[viewportRedoStack.length - 1]?.type === "xr_create") {
    const ok = redoXrCreateCadOnly();
    try { viewportXR?.redoXrCreateVisual?.(); } catch (_) { }
    return ok;
  }
  const action = viewportRedoStack[viewportRedoStack.length - 1];
  if (action?.type === "transform") {
    viewportRedoStack.pop();
    if (action.committed && action.delta) {
      viewportUndoStack.push(action);
      void persistCommittedTransform(action, { invert: false }).then((ok) => {
        if (ok) {
          setEditStatus("ok", "Redid move/rotate.");
          return;
        }
        viewportUndoStack.pop();
        viewportRedoStack.push(action);
        setEditStatus("error", "Could not redo move.");
      }).catch((err) => {
        viewportUndoStack.pop();
        viewportRedoStack.push(action);
        setEditStatus("error", err?.message || "Could not redo move.");
      });
      return true;
    }
    const result = redoViewportTransformAction(action, {
      undoStack: viewportUndoStack,
      redoStack: viewportRedoStack,
      resolveMesh: resolveViewportTransformTarget,
      resetDragBaseline: () => gizmoPanel.resetDragBaseline?.(),
      refreshGizmo: () => gizmoPanel.refresh?.(),
      setStatus: setEditStatus,
    });
    if (result?.undid) {
      projectAssembly.invalidateBounds?.();
      sendCollabPresence({ moving: false });
    }
    return Boolean(result?.handled);
  }
  const popped = viewportRedoStack.pop();
  if (!popped) return false;
  if (popped.type === "texture_wrap") {
    const next = Number(popped.nextIndex);
    viewportUndoStack.push(popped);
    if (Number.isInteger(next) && next >= 0) {
      void restoreTimelineAsLatest(next).then(() => {
        setEditStatus("ok", "Redid texture wrap.");
      });
      return true;
    }
    return false;
  }
  return false;
}

/** Cmd+Z / Cmd+Shift+Z: undo live moves only. Never walk generation timeline. */
function runViewportUndoShortcut(e, { redo = false } = {}) {
  e.preventDefault();
  if (e.repeat) return;
  if (redo) {
    if (!redoViewportAction()) setEditStatus("error", "Nothing to redo.");
    return;
  }
  if (!undoViewportAction()) setEditStatus("error", "Nothing to undo.");
}

function selectedObjectFilename() {
  const selection = objectTools.getSelection?.();
  const fromSelection = selection?.catalogName || (selection?.mesh ? catalogNameForMesh(selection.mesh) : null);
  return fromSelection || selectedFile || null;
}

function capturePromptSelectionContext() {
  const selection = objectTools.getSelection?.();
  const filename = selection?.catalogName || (selection?.mesh ? catalogNameForMesh(selection.mesh) : null) || selectedFile || null;
  if (!filename) return null;
  return {
    filename,
    targetMode: getPromptTargetMode(),
    bodyIndex: Number.isInteger(selection?.bodyIndex) ? selection.bodyIndex : null,
    bodyName: selection?.label || null,
  };
}

function restorePromptSelectionContext(context = pendingPromptSelectionContext, { resultFilename = null } = {}) {
  if (!context?.filename) return false;
  const targetModeSelect = document.getElementById("prompt-target-mode");
  if (context.targetMode === "edit" && targetModeSelect) targetModeSelect.value = "edit";
  const restoreName =
    (context.targetMode === "edit" && resultFilename && projectAssembly.has(resultFilename) ? resultFilename : null) ||
    (projectAssembly.has(context.filename) ? context.filename : null) ||
    (resultFilename && projectAssembly.has(resultFilename) ? resultFilename : null);
  if (!restoreName) return false;
  const objectSelect = document.getElementById("prompt-target-object");
  if (objectSelect) objectSelect.value = restoreName;
  selectedFile = restoreName;
  const bodyIndex = restoreName === context.filename && Number.isInteger(context.bodyIndex) ? context.bodyIndex : null;
  if (bodyIndex != null) {
    const entry = visiblePromptTargetEntries().find((candidate) => candidate.name === restoreName);
    const body = promptTargetBodies(entry).find((candidate) => candidate.index === bodyIndex);
    promptTargetSelectedBody = {
      filename: restoreName,
      bodyIndex,
      bodyName: body?.name || context.bodyName || `Body ${bodyIndex + 1}`,
    };
    const root = projectAssembly.get(restoreName);
    const meshes = root ? listObjectMeshes(root) : [];
    const mesh = meshes[bodyIndex] || meshes[0] || root;
    if (mesh && root) {
      objectTools.selectObject?.({ mesh, root, bodyIndex, catalogName: restoreName });
    }
    syncBrowserToViewportSelection(restoreName, bodyIndex, { partLevel: true });
  } else {
    promptTargetSelectedBody = null;
    selectAssemblyComponent(restoreName, { fitView: false });
  }
  featureEditor.setModel(projectId, restoreName);
  syncPromptTargetUI();
  return true;
}

function copySelectedObjectToClipboard() {
  return copySelectedPromptLinkToClipboard();
}

function buildPromptRefFromBrowserPayload(payload) {
  if (!payload) return null;
  const filename = payload.filename || payload.name || payload.viewer_filename;
  if (!filename && !payload.label) return null;
  const bodyIndex = Number.isInteger(payload.body_index) ? payload.body_index : null;
  const bodyName = payload.body_name || payload.label || (bodyIndex != null ? `Body ${bodyIndex + 1}` : null);
  const stemBase = fileStem(filename || payload.stem || payload.label || "component");
  const stem = bodyIndex != null
    ? `${stemBase}-${String(bodyName || `Body-${bodyIndex + 1}`).replace(/[^a-zA-Z0-9_-]+/g, "-")}`
    : (payload.stem || stemBase);
  const token = compactComponentToken(stem);
  return {
    id: bodyIndex != null
      ? `component-body:${projectId || "project"}:${filename}:${bodyIndex}`
      : `component:${projectId || "project"}:${filename || stem}`,
    type: payload.type === "sketch" || payload.type === "wiring" || payload.type === "dxf" ? payload.type : "component",
    token,
    label: bodyName || payload.label || stemBase,
    filename: filename || undefined,
    stem,
    format: payload.format,
    viewer_filename: payload.viewer_filename || filename,
    projectId,
    body_index: bodyIndex,
  };
}

function buildSelectedPromptLinks() {
  const links = [];
  const seen = new Set();
  const push = (ref) => {
    if (!ref?.token || seen.has(ref.id || ref.token)) return;
    seen.add(ref.id || ref.token);
    links.push(ref);
  };

  const selection = objectTools?.getSelection?.();
  for (const ref of selectedGeometryPromptReferences(selection, projectId, selectionGeometryContext)) push(ref);

  for (const payload of projectTree?.getSelectedEntries?.() || []) {
    push(buildPromptRefFromBrowserPayload(payload));
  }

  if (!links.length && selectedFile) {
    push(componentPromptReference({
      filename: selectedFile,
      stem: fileStem(selectedFile),
      label: fileStem(selectedFile),
      projectId,
    }));
  }

  if (!links.length && promptTargetSelectedBody?.filename) {
    push({
      id: `component-body:${projectId || "project"}:${promptTargetSelectedBody.filename}:${promptTargetSelectedBody.bodyIndex}`,
      type: "component",
      token: compactComponentToken(`${fileStem(promptTargetSelectedBody.filename)}-${promptTargetSelectedBody.bodyName || `Body-${promptTargetSelectedBody.bodyIndex + 1}`}`),
      label: promptTargetSelectedBody.bodyName || `Body ${promptTargetSelectedBody.bodyIndex + 1}`,
      filename: promptTargetSelectedBody.filename,
      stem: fileStem(promptTargetSelectedBody.filename),
      projectId,
      body_index: promptTargetSelectedBody.bodyIndex,
    });
  }

  return links.filter(Boolean);
}

function canCopySelectionAsPromptLink() {
  return buildSelectedPromptLinks().length > 0;
}

function setPromptTargetMode(mode) {
  const select = document.getElementById("prompt-target-mode");
  if (!select) return;
  if (mode === "edit" || mode === "new") {
    select.value = mode;
    syncPromptTargetUI();
  }
}

function sendSelectedObjectToAi(entry = null) {
  const refs = [];
  if (entry) {
    const ref = buildPromptRefFromBrowserPayload({
      filename: entry.source_filename || entry.parent_filename || entry.filename || entry.name,
      name: entry.name,
      stem: entry.stem,
      label: entry.body_name || entry.label || entry.stem || fileStem(entry.name),
      viewer_filename: entry.viewer_filename,
      format: entry.format,
      body_index: Number.isInteger(entry.body_index) ? entry.body_index : null,
      body_name: entry.body_name || entry.label || null,
      projectId,
    });
    if (ref) refs.push(ref);
  } else {
    const selection = objectTools.getSelection?.();
    const catalogName = selection?.catalogName
      || selection?.root?.userData?.catalogFilename
      || (selection?.mesh ? catalogNameForMesh(selection.mesh) : null)
      || selectedFile;
    if (selection?.partLevel && Number.isInteger(selection.bodyIndex) && catalogName) {
      const bodyLabel = selection.label || `Body ${selection.bodyIndex + 1}`;
      refs.push({
        id: `component-body:${projectId || "project"}:${catalogName}:${selection.bodyIndex}`,
        type: "component",
        token: compactComponentToken(`${fileStem(catalogName)}-${bodyLabel}`),
        label: bodyLabel,
        filename: catalogName,
        stem: `${fileStem(catalogName)}-${String(bodyLabel).replace(/[^a-zA-Z0-9_-]+/g, "-")}`,
        projectId,
        body_index: selection.bodyIndex,
        body_name: bodyLabel,
      });
    } else if (catalogName) {
      const ref = componentPromptReference({
        filename: catalogName,
        stem: fileStem(catalogName),
        label: selection?.label || fileStem(catalogName),
        projectId,
      });
      if (ref) refs.push(ref);
    }
  }
  if (!refs.length) {
    setEditStatus("error", "Select a body or object first.");
    return false;
  }
  setPromptTargetMode("edit");
  showAiComposePanel();
  for (const ref of refs) composer.addReference(ref, { insertMention: true });
  const label = refs.length === 1 ? (refs[0].label || refs[0].token) : `${refs.length} objects`;
  setEditStatus("ok", `Sent ${label} to AI as a reference.`);
  return true;
}

function formatPromptLinkPlainText(refs = []) {
  return refs.map((ref) => ref.token || compactComponentToken(ref.stem || ref.label || ref.filename || "component")).join(" ");
}

async function copySelectedPromptLinkToClipboard() {
  const refs = buildSelectedPromptLinks();
  if (!refs.length) {
    setEditStatus("error", "Select a component, body, or face to copy.");
    return false;
  }
  const plain = formatPromptLinkPlainText(refs);
  promptLinkClipboard = {
    at: Date.now(),
    plain,
    refs: refs.map((ref) => ({ ...ref })),
  };
  const filename = selectedObjectFilename();
  if (filename) objectClipboard = { projectId, filename };
  const ok = await copyText(plain);
  if (!ok) {
    setEditStatus("error", "Could not copy to clipboard.");
    return false;
  }
  const label = refs.length === 1
    ? (refs[0].label || refs[0].token)
    : `${refs.length} items`;
  setEditStatus("ok", `Copied ${label} — paste into the AI prompt (Cmd/Ctrl+V).`);
  return true;
}

function resolvePromptLinkPaste(text = "") {
  const raw = String(text || "").trim();
  if (!raw) return null;
  const stash = promptLinkClipboard;
  if (stash?.refs?.length) {
    const stashPlain = String(stash.plain || "").trim();
    const tokens = stash.refs.map((ref) => String(ref.token || "").trim()).filter(Boolean);
    const matchesStash =
      raw === stashPlain
      || tokens.some((token) => raw === token || raw.includes(token));
    if (matchesStash) return stash.refs.map((ref) => ({ ...ref }));
  }
  const tokenMatch = raw.match(/^@([A-Za-z0-9_.:-]+)$/);
  if (!tokenMatch) return null;
  const want = `@${tokenMatch[1]}`;
  const mentionable = (typeof getPromptMentionables === "function" ? getPromptMentionables() : [])
    .map((item) => item?.ref)
    .find((ref) => ref && (ref.token === want || compactComponentToken(ref.stem || ref.label || ref.filename || "") === want));
  return mentionable ? { ...mentionable } : null;
}

async function duplicateSelectedObject(filename = selectedObjectFilename()) {
  if (!projectId || !filename) {
    setEditStatus("error", "Select an object to duplicate.");
    return null;
  }
  try {
    setEditStatus("loading", `Duplicating ${filename.replace(/\.[^.]+$/, "")}…`);
    const data = await api(`/api/projects/${projectId}/files/${encodeURIComponent(filename)}/transform`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        mode: "delta",
        copy: true,
        // Small baked offset makes pasted copies visible instead of perfectly overlapping.
        translation: [20, 0, 0],
      }),
    });
    selectedFile = data.filename;
    await refreshFiles();
    await loadModel(data.url, data.filename, {
      projectId,
      append: true,
      catalogFilename: data.filename,
      center: false,
      normalizePivot: false,
      fitView: false,
      autoGizmo: true,
    });
    await refreshTimeline();
    setEditStatus("ok", `Duplicated as ${data.filename.replace(/\.[^.]+$/, "")}.`);
    return data;
  } catch (err) {
    const msg = err.message || "Duplicate failed.";
    setEditStatus("error", msg);
    viewerOverlay.showError(msg);
    return null;
  }
}

function transformBaselineFromPayload(raw) {
  if (!raw) return null;
  if (raw.position instanceof THREE.Vector3) {
    return {
      position: raw.position.clone(),
      quaternion: raw.quaternion?.clone?.() || new THREE.Quaternion(),
      scale: raw.scale?.clone?.() || new THREE.Vector3(1, 1, 1),
    };
  }
  const pos = raw.position;
  const quat = raw.quaternion;
  const scale = raw.scale;
  if (!Array.isArray(pos) || pos.length < 3) return null;
  return {
    position: new THREE.Vector3(pos[0], pos[1], pos[2]),
    quaternion: new THREE.Quaternion(
      Array.isArray(quat) && quat.length === 4 ? quat[0] : 0,
      Array.isArray(quat) && quat.length === 4 ? quat[1] : 0,
      Array.isArray(quat) && quat.length === 4 ? quat[2] : 0,
      Array.isArray(quat) && quat.length === 4 ? quat[3] : 1,
    ),
    scale: new THREE.Vector3(
      Array.isArray(scale) && scale.length >= 3 ? scale[0] : 1,
      Array.isArray(scale) && scale.length >= 3 ? scale[1] : 1,
      Array.isArray(scale) && scale.length >= 3 ? scale[2] : 1,
    ),
  };
}

function setEditStatus(kind, text) {
  const el = document.getElementById("edit-status");
  if (el) {
    el.className = `status ${kind}`;
    el.textContent = text;
  }
}

// ── Fusion-style direct modeling (press-pull, mirror, gizmo panel, units) ────
initUnitSwitcher(document.querySelectorAll(".unit-select, [data-unit-select]"));

/** When true, setUnits came from loading a project — don't PATCH back. */
let applyingProjectUnits = false;
let persistUnitsTimer = 0;

function applyProjectDisplayUnits(units, { persist = false } = {}) {
  const next = String(units || "").trim().toLowerCase();
  if (!next) return;
  applyingProjectUnits = true;
  try {
    setUnits(next);
  } finally {
    applyingProjectUnits = false;
  }
  syncMeasureUnitButtons();
  if (persist) void persistProjectDisplayUnits(next);
}

async function persistProjectDisplayUnits(units) {
  if (!projectId || applyingProjectUnits) return;
  const next = String(units || getUnits() || "mm").toLowerCase();
  try {
    const data = await api(`/api/projects/${projectId}/units`, {
      method: "PATCH",
      body: { units: next },
    });
    const saved = data?.units || next;
    const proj = allProjects.find((p) => p.id === projectId);
    if (proj) proj.units = saved;
    upsertProjectInList?.({ id: projectId, units: saved });
  } catch (err) {
    console.warn("[units] could not save project units", err);
  }
}

onUnitsChanged((units) => {
  syncMeasureUnitButtons();
  updateMeasureReadout();
  try { refreshSelectionMeasureOverlay?.(); } catch (_) { }
  if (applyingProjectUnits || !projectId) return;
  window.clearTimeout(persistUnitsTimer);
  persistUnitsTimer = window.setTimeout(() => {
    void persistProjectDisplayUnits(units);
  }, 200);
});

function syncMeasureUnitButtons() {
  const current = getUnits();
  document.querySelectorAll("[data-measure-unit]").forEach((btn) => {
    const on = btn.getAttribute("data-measure-unit") === current;
    btn.classList.toggle("active", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  });
  const select = document.getElementById("unit-select");
  if (select && select.value !== current) select.value = current;
}

function currentMmPerModelUnit() {
  if (!currentMesh) return 1;
  const box = new THREE.Box3().setFromObject(currentMesh);
  return mmPerModelUnit(box.getSize(new THREE.Vector3()).length());
}

let pendingSnapTarget = null; // object | face

function objectWorldBoxCenter(obj) {
  const box = new THREE.Box3().setFromObject(obj);
  return box.getCenter(new THREE.Vector3());
}

function objectWorldBoxCorners(obj) {
  const box = new THREE.Box3().setFromObject(obj);
  const min = box.min;
  const max = box.max;
  return [
    new THREE.Vector3(min.x, min.y, min.z),
    new THREE.Vector3(min.x, min.y, max.z),
    new THREE.Vector3(min.x, max.y, min.z),
    new THREE.Vector3(min.x, max.y, max.z),
    new THREE.Vector3(max.x, min.y, min.z),
    new THREE.Vector3(max.x, min.y, max.z),
    new THREE.Vector3(max.x, max.y, min.z),
    new THREE.Vector3(max.x, max.y, max.z),
  ];
}

function supportPointAgainstNormal(obj, normalWorld) {
  const corners = objectWorldBoxCorners(obj);
  if (!corners.length) return objectWorldBoxCenter(obj);
  let best = corners[0];
  let bestDot = best.dot(normalWorld);
  for (const corner of corners.slice(1)) {
    const d = corner.dot(normalWorld);
    if (d < bestDot) {
      best = corner;
      bestDot = d;
    }
  }
  return best.clone();
}

function worldDeltaToParentDelta(obj, deltaWorld) {
  if (!obj?.parent) return deltaWorld.clone();
  obj.parent.updateMatrixWorld(true);
  const origin = objectWorldBoxCenter(obj);
  const a = obj.parent.worldToLocal(origin.clone());
  const b = obj.parent.worldToLocal(origin.clone().add(deltaWorld));
  return b.sub(a);
}

function beginSnapTarget(type) {
  const selection = objectTools?.getSelection?.();
  if (!selection?.mesh) {
    setEditStatus("error", "Select the object you want to move first.");
    gizmoPanel.clearSnapTarget?.();
    return;
  }
  pendingSnapTarget = type === "face" ? "face" : "object";
  setEditStatus(
    "ok",
    pendingSnapTarget === "face"
      ? "Snap Face: click the target face. The selected object will sit on that face."
      : "Snap Object: click a target object. Centers will align."
  );
}

function clearSnapTarget() {
  pendingSnapTarget = null;
  gizmoPanel.clearSnapTarget?.();
}

function handlePendingSnapTarget(event) {
  if (!pendingSnapTarget) return false;
  const selection = objectTools?.getSelection?.();
  if (!selection?.mesh) {
    clearSnapTarget();
    setEditStatus("error", "Select the object you want to move first.");
    return true;
  }
  const root = projectAssembly.getRoot() || currentMesh;
  const hit = pickObject(event, {
    camera,
    domElement: renderer.domElement,
    meshRoot: root,
  });
  if (!hit?.mesh) {
    setEditStatus("error", "Click a target object or face to snap to.");
    return true;
  }
  const target = selectionTargetFromMesh(hit.mesh);
  if (target.mesh === selection.mesh || target.root === selection.root) {
    setEditStatus("error", "Pick a different object or face as the snap target.");
    return true;
  }

  const source = selection.mesh;
  const mode = pendingSnapTarget;
  const targetWorld =
    mode === "face" && hit.point
      ? hit.point.clone()
      : objectWorldBoxCenter(target.mesh);
  const sourceAnchor =
    mode === "face" && hit.normal
      ? supportPointAgainstNormal(source, hit.normal.clone().normalize())
      : objectWorldBoxCenter(source);
  const delta = worldDeltaToParentDelta(source, targetWorld.sub(sourceAnchor));
  if (!gizmoPanel.translateBy?.(delta, { autoApply: true })) {
    setEditStatus("error", "Could not move the selected object.");
    return true;
  }
  clearSnapTarget();
  setEditStatus(
    "loading",
    mode === "face" ? "Snapped to face. Saving transform…" : "Snapped to object. Saving transform…"
  );
  event.preventDefault();
  return true;
}

let multiSelectionMoveSaveInFlight = false;

async function persistMultiSelectionMove(stroke = {}) {
  if (multiSelectionMoveSaveInFlight || !projectId) return;
  const delta = Array.isArray(stroke.delta?.translation)
    ? new THREE.Vector3(...stroke.delta.translation)
    : null;
  if (!delta || delta.length() <= 1e-12) return;
  const selection = objectTools?.getSelection?.();
  const selections = (selection?.selections || []).filter((item) => item?.mesh || item?.root);
  if (selections.length < 2) return;

  const targets = [];
  const seen = new Set();
  for (const item of selections) {
    const object = item.root || item.mesh;
    const filename = kernelApiFilename(
      item.catalogName || object?.userData?.catalogFilename || catalogNameForMesh(object),
    );
    if (!object || !filename || seen.has(filename)) continue;
    if (object.userData?.localOnly || object.userData?.architectInstance) continue;
    const parentDelta = worldDeltaToParentDelta(object, delta);
    targets.push({
      object,
      filename,
      bodyIndex: item.bodyIndex ?? null,
      bodyName: String(item.label || item.mesh?.name || "").trim() || null,
      bodyCount: item.bodyCount ?? 1,
      isRoot: item.isRoot ?? item.wholeModel ?? true,
      baseline: {
        position: object.position.clone().sub(parentDelta),
        quaternion: object.quaternion.clone(),
        scale: object.scale.clone(),
      },
      translation: parentDelta.toArray(),
    });
    seen.add(filename);
  }
  if (!targets.length) return;

  multiSelectionMoveSaveInFlight = true;
  objectTools.clearSelection?.({ detachGizmo: true });
  gizmoPanel.hide?.();
  transformControls.detach();
  document.getElementById("btn-gizmo")?.classList.remove("active");
  setEditStatus("loading", `Saving moved placement for ${targets.length} object${targets.length === 1 ? "" : "s"}…`);
  try {
    let saved = 0;
    for (const target of targets) {
      const useBodyTransform = target.bodyIndex != null && target.bodyCount > 1 && target.isRoot === false;
      const body = {
        mode: "delta",
        translation: target.translation,
        ...(useBodyTransform
          ? {
            body_index: target.bodyIndex,
            ...(target.bodyName ? { body_name: target.bodyName } : {}),
          }
          : {}),
      };
      const endpoint = useBodyTransform ? "transform-body" : "transform";
      const data = await api(`/api/projects/${projectId}/files/${encodeURIComponent(target.filename)}/${endpoint}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      await afterModelEdit({
        ...data,
        replaceCatalog: target.filename,
        action: useBodyTransform ? "body_transform" : "transform",
        placementBaseline: target.baseline,
      });
      saved += 1;
    }
    setEditStatus("ok", `Saved moved placement for ${saved} object${saved === 1 ? "" : "s"}.`);
  } catch (err) {
    setEditStatus("error", err.message || "Could not save moved placement.");
    viewerOverlay.showError(err.message || "Could not save moved placement.");
  } finally {
    multiSelectionMoveSaveInFlight = false;
  }
}

const gizmoPanel = createGizmoPanel({
  viewport,
  transformControls,
  getMesh: () => isolateTransformTarget(
    objectTools?.getSelection?.()?.mesh || cadTransformPivotItem?.object,
  ),
  getModelInfo: () => {
    const selection = objectTools?.getSelection?.();
    const partLevel = !!selection?.partLevel;
    const bodyCount = Math.max(
      Number(selection?.bodyCount) || 1,
      partLevel ? Number(selection?.meshCount) || 1 : 1,
    );
    const meshName = String(selection?.mesh?.name || "").trim();
    const bodyName = partLevel
      ? (meshName || String(selection?.label || "").trim() || null)
      : null;
    const catalogName = resolveTransformCatalogName();
    const catalog = catalogName ? projectAssembly.get(catalogName) : null;
    return {
      projectId,
      filename: catalogName,
      bodyIndex: selection?.bodyIndex ?? null,
      bodyName,
      bodyCount,
      // Whole-model selection must stay isRoot so transforms bake the full file.
      // Part selection must NOT be root so body transforms apply and Cmd+Z undoes the part move.
      isRoot: partLevel ? false : (selection?.isRoot ?? true),
      catalogPose: snapshotCatalogPose(catalog),
    };
  },
  getMmPerModelUnit: currentMmPerModelUnit,
  api,
  onApplied: async (data) => {
    for (let i = viewportUndoStack.length - 1; i >= 0; i -= 1) {
      const entry = viewportUndoStack[i];
      if (entry?.type === "transform" && !entry.committed) {
        entry.committed = true;
        break;
      }
    }
    return afterModelEdit({
      ...data,
      action: data?.action || "transform",
    });
  },
  onStatus: setEditStatus,
  onSnapRequest: beginSnapTarget,
  onColor: () => showColorTool(),
  onSendToAi: () => sendSelectedObjectToAi(),
  onArticulationToggle: (on) => setCadArticulationDragEnabled(on),
  onTransformStrokeEnd: (stroke) => {
    if (!stroke?.before) return;
    pushViewportUndoAction({
      type: "transform",
      filename: stroke.filename || selectedFile || null,
      liveTarget: stroke.liveTarget || null,
      before: stroke.before,
      after: stroke.after || null,
      delta: stroke.delta || null,
      catalogPose: stroke.catalogPose || null,
      transformBody: stroke.transformBody || null,
      committed: false,
    });
    sendCollabPresence({ moving: false });
    if (stroke.skipAutoApply && stroke.mode === "translate") {
      void persistMultiSelectionMove(stroke);
    }
  },
});

let ribbon = null;
/** @type {ReturnType<typeof createSolidPreview> | null} */
let createSolidPreviewTool = null;

function setSketchModelDim(active) {
  const root = projectAssembly.getRoot();
  root?.traverse((obj) => {
    const mats = Array.isArray(obj.material) ? obj.material : obj.material ? [obj.material] : [];
    for (const mat of mats) {
      if (!mat) continue;
      if (active) {
        if (mat.userData._sketchOrigOpacity == null) {
          mat.userData._sketchOrigOpacity = mat.opacity ?? 1;
        }
        mat.transparent = true;
        mat.opacity = 0.12;
      } else if (mat.userData._sketchOrigOpacity != null) {
        mat.opacity = mat.userData._sketchOrigOpacity;
        mat.transparent = mat.opacity < 1;
      }
      mat.needsUpdate = true;
    }
  });
  if (currentMesh && !root) {
    currentMesh.traverse((obj) => {
      const mat = obj.material;
      if (!mat) return;
      if (active) {
        if (mat.userData._sketchOrigOpacity == null) mat.userData._sketchOrigOpacity = mat.opacity ?? 1;
        mat.transparent = true;
        mat.opacity = 0.12;
      } else if (mat.userData._sketchOrigOpacity != null) {
        mat.opacity = mat.userData._sketchOrigOpacity;
        mat.transparent = mat.opacity < 1;
      }
      mat.needsUpdate = true;
    });
  }
}

function formatSketchTool(tool) {
  return String(tool || "line").replace(/_/g, " ");
}

function enterSketchVisualMode() {
  savedSceneBg = scene.background?.getHex?.() ?? currentThemeSceneColors().canvas;
  scene.background.setHex(SKETCH_CANVAS);
  if (gridHelper) gridHelper.visible = false;
  ribbon?.setSketchEditing?.(true);
  document.querySelector(".sketch-mode-tab")?.classList.remove("hidden");
  setRightTab("sketch");
}

function exitSketchVisualMode() {
  scene.background.setHex(savedSceneBg ?? currentThemeSceneColors().canvas);
  savedSceneBg = null;
  applyGridVisibility();
  ribbon?.setSketchEditing?.(false);
  ribbon?.setActiveSketchTool?.(null);
  document.querySelector(".sketch-mode-tab")?.classList.add("hidden");
  document.querySelectorAll(".sketch-quick-btn").forEach((b) => b.classList.remove("active"));
}

function updateSketchChrome({ visible, plane, tool, hint, entities = 0, constraints = 0 } = {}) {
  const chrome = document.getElementById("sketch-chrome");
  if (!chrome) return;
  chrome.classList.toggle("hidden", !visible);

  const planeLabel = document.getElementById("sketch-plane-label");
  const statusTool = document.getElementById("sketch-status-tool");
  const statusHint = document.getElementById("sketch-status-hint");
  const statusStats = document.getElementById("sketch-status-stats");
  const inspPlane = document.getElementById("sketch-inspector-plane");
  const inspTool = document.getElementById("sketch-inspector-tool");
  const inspEntities = document.getElementById("sketch-inspector-entities");
  const inspConstraints = document.getElementById("sketch-inspector-constraints");
  const inspHint = document.getElementById("sketch-inspector-hint");

  const toolLabel = formatSketchTool(tool);
  if (planeLabel && visible) planeLabel.textContent = `${plane || "XY"} Plane · Edit Sketch`;
  if (statusTool) statusTool.textContent = toolLabel;
  if (statusHint) {
    statusHint.textContent = hint || "";
    statusHint.classList.toggle("sketch-status-hint--error", !!hint && /closed profile|draw a closed|constraints/i.test(hint));
  }
  if (statusStats) statusStats.textContent = `${entities} ent · ${constraints} constraints`;
  if (inspPlane) inspPlane.textContent = plane || "XY";
  if (inspTool) inspTool.textContent = toolLabel;
  if (inspEntities) inspEntities.textContent = String(entities);
  if (inspConstraints) inspConstraints.textContent = String(constraints);
  if (inspHint) inspHint.textContent = hint || "";

  document.querySelectorAll(".sketch-quick-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.sketchTool === tool);
  });
  ribbon?.setActiveSketchTool?.(tool);
}

function enterSketchMode() {
  transformControls.detach();
  gizmoPanel.hide();
  document.getElementById("btn-gizmo")?.classList.remove("active");
  objectTools.clearSelection();
  activatePickMode("off");
  directModeling.setTool?.(null);
}

function exitSketchMode() {
  if (sketchEditor.isActive()) sketchEditor.cancel();
  else {
    setSketchModelDim(false);
    document.getElementById("app")?.classList.remove("sketch-editing");
    updateSketchChrome({ visible: false });
    exitSketchVisualMode();
    controls.enabled = true;
  }
}

function finishActiveSketch() {
  if (!sketchEditor.isActive()) {
    setEditStatus("error", "No active sketch to finish.");
    return false;
  }
  try {
    return sketchEditor.finish();
  } catch (err) {
    console.error("Finish sketch failed:", err);
    setEditStatus("error", err?.message || "Finish sketch failed.");
    sketchEditor.cancel();
    exitSketchMode();
    return false;
  }
}

function enterRiggingMode() {
  transformControls.detach();
  gizmoPanel.hide();
  document.getElementById("btn-gizmo")?.classList.remove("active");
  objectTools.clearSelection();
  controls.enabled = true;
  document.getElementById("app")?.classList.remove("sketch-editing");
  document.querySelectorAll("#rigging-chrome.rigging-chrome").forEach((el) => el.classList.remove("hidden"));
  refreshRiggingPromptHistory();
  try { window.Render3DPanels?.setRightPanelHidden?.(false); } catch (_) { }
  document.getElementById("app")?.classList.remove("right-panel-hidden");
  setRightTab("rigging");
  riggingPromptHistory.setTab("compose");
  // Prefer the URDF/SRDF manage tab so Play / Pause / Create are visible.
  try { setRiggingWorkspaceMode("urdf"); } catch (_) { }
  // Always expand the viewport Rigging manage rail on enter.
  try {
    const manage = document.getElementById("rigging-viewport-manage");
    const body = document.getElementById("rigging-manage-body");
    const btn = document.getElementById("btn-rigging-manage-collapse");
    manage?.classList.remove("is-collapsed");
    if (body) body.hidden = false;
    if (btn) {
      btn.setAttribute("aria-expanded", "true");
      btn.title = "Collapse Rigging";
      const arrow = btn.querySelector(".rigging-manage-edge-arrow");
      if (arrow) arrow.textContent = "▸";
    }
    document.getElementById("rigging-manage-accordion")?.setAttribute("open", "");
  } catch (_) { }
  void (async () => {
    if (selectedFile) await loadSimForFile(selectedFile);
    await riggingEditor.show();
    const bound = riggingEditor.refreshMeshBindings?.() ?? 0;
    const root = getRiggingPartRoot() || projectAssembly.getRoot() || currentMesh;
    // Prefer URDF robots (Jake arms) when artifacts exist.
    try {
      await refreshRobotArtifacts({ quiet: true });
      const { urdfFile } = pickPreferredRobotFiles(robotArtifactData || {});
      if (urdfFile) {
        await ensureUrdfRobotScene({ quiet: false, force: true });
        if (urdfRobotRuntime.isLoaded?.()) {
          setEditStatus("ok", `URDF robot ready (${urdfFile}). Open the robot playground to pose joints, then press Play.`);
          syncRiggingViewportOverlay({ status: "Robot scene loaded — open robot playground to pose joints." });
          await syncRiggingAdjustSliders({ autoExpand: true });
          syncRiggingToolbelt();
          syncRiggingViewportPlaybackUi();
          setRiggingViewportPlaybackVisible(true);
          return;
        }
      }
    } catch (err) {
      console.warn("URDF auto-load failed", err);
    }
    // Jake contract: motion comes from .step.js (or URDF), not mesh-name heuristics.
    const stepBound = await stepModuleRuntime.bind(root);
    if (stepBound > 0 && stepModuleRuntime.hasModule()) {
      setEditStatus(
        "ok",
        `STEP module ready (${stepBound} features from ${stepModuleRuntime.moduleName() || ".step.js"}). Press Play.`
      );
    } else if (detectPlanetaryGearAssembly(root)) {
      const n = planetaryGearRuntime.bind(root);
      setEditStatus("ok", `Planetary fallback ready (${n} parts). Prefer authoring a .step.js module.`);
    } else if (bound >= 2) {
      setEditStatus("ok", `Rigging ready — ${bound} parts bound for animation. Press Play.`);
    } else if (selectedFile) {
      setEditStatus(
        "error",
        "No URDF or .step.js motion module for this model. Generate robot artifacts or a Jake-style parameter sidecar."
      );
    }
    syncRiggingToolbelt();
    syncRiggingViewportOverlay();
    await syncRiggingAdjustSliders({ autoExpand: false });
    syncRiggingViewportPlaybackUi();
    syncRiggingAnimationBanner();
  })();
  setRiggingViewportPlaybackVisible(hasAnyRiggingPlayback());
}

function exitRiggingMode() {
  document.querySelectorAll("#rigging-chrome.rigging-chrome").forEach((el) => el.classList.add("hidden"));
  document.getElementById("rigging-anim-panel")?.classList.add("hidden");
  closeUrdfMotionModal();
  stepModuleRuntime?.stop?.({ reset: true });
  planetaryGearRuntime?.stop?.({ reset: true });
  riggingEditor.hide();
  // Always restore the CAD assembly — loading a mesh URDF used to hide it and
  // leaving RIGGING never brought it back (empty / broken SOLID viewport).
  setCadAssemblyHiddenForUrdf(false);
  // Keep robot motion available on SOLID (share-style overlay), don't tear it down.
  setRiggingViewportPlaybackVisible(hasAnyRiggingPlayback());
}

