function syncRiggingViewportOverlay({ status = "" } = {}) {
  const data = robotArtifactData || {};
  const joints = (data.joints || []).filter((j) => String(j.type || "").toLowerCase() !== "fixed");
  const links = data.links || [];
  const artifacts = data.artifacts || [];
  const statusEl = document.getElementById("rigging-manage-status");
  const metaEl = document.getElementById("rigging-manage-meta");
  const sourceSelect = document.getElementById("rigging-vp-artifact-source");
  const panelSource = document.getElementById("rigging-artifact-source");
  if (sourceSelect) {
    const current = sourceSelect.value || panelSource?.value || "";
    sourceSelect.innerHTML = (data.sources || []).length
      ? (data.sources || []).map((source) => `<option value="${escapeHtml(source)}">${escapeHtml(source)}</option>`).join("")
      : `<option value="">No CAD or robot source</option>`;
    if (current && [...sourceSelect.options].some((opt) => opt.value === current)) sourceSelect.value = current;
  }
  if (statusEl) {
    statusEl.textContent = status
      || (urdfRobotRuntime.isLoaded?.()
        ? "Robot scene loaded — pose joints from the robot playground."
        : "Load a robot or motion module to pose joints.");
  }
  if (metaEl) {
    metaEl.textContent = `${artifacts.length} artifact(s) · ${links.length} link(s) · ${joints.length} joint(s)`;
  }
}

function bindRiggingViewportOverlayUi() {
  if (bindRiggingViewportOverlayUi._ready) return;
  bindRiggingViewportOverlayUi._ready = true;

  document.getElementById("btn-rigging-manage-collapse")?.addEventListener("click", () => {
    const manage = document.getElementById("rigging-viewport-manage");
    const collapsed = !manage?.classList.contains("is-collapsed");
    manage?.classList.toggle("is-collapsed", collapsed);
    const body = document.getElementById("rigging-manage-body");
    if (body) body.hidden = collapsed;
    const btn = document.getElementById("btn-rigging-manage-collapse");
    if (btn) {
      btn.setAttribute("aria-expanded", String(!collapsed));
      btn.title = collapsed ? "Expand Rigging" : "Collapse Rigging";
      const arrow = btn.querySelector(".rigging-manage-edge-arrow");
      if (arrow) arrow.textContent = collapsed ? "◂" : "▸";
    }
  });

  document.getElementById("rigging-show-bones")?.addEventListener("change", (e) => {
    const on = !!e.target?.checked;
    riggingEditor.setBoneOverlayVisible?.(on);
  });

  document.getElementById("btn-rigging-vp-load")?.addEventListener("click", async () => {
    try {
      await refreshRobotArtifacts({ quiet: true });
      const state = await ensureUrdfRobotScene({ force: true });
      if (!urdfRuntimeHasUsableMotion(state)) {
        syncRiggingViewportOverlay({ status: "Showing CAD model — no usable robot motion yet." });
        void setupRobotMotionWorkflow({ askWhenMissing: true });
        return;
      }
      syncRiggingViewportOverlay({ status: "Robot scene loaded." });
    } catch (err) {
      setEditStatus("error", err?.message || "Could not load robot.");
    }
  });
  document.getElementById("btn-rigging-vp-refresh")?.addEventListener("click", async () => {
    await refreshRobotArtifacts({ quiet: false });
    syncRiggingViewportOverlay();
  });
  document.getElementById("btn-rigging-vp-reset")?.addEventListener("click", () => resetRobotJointPose());
  document.getElementById("btn-rigging-vp-play")?.addEventListener("click", () => {
    void toggleRiggingPlayback();
  });
  document.getElementById("btn-rigging-vp-pause")?.addEventListener("click", () => {
    try {
      if (typeof pauseRiggingPlayback === "function") pauseRiggingPlayback();
      else void toggleRiggingPlayback({ forcePause: true });
    } catch (_) {
      void toggleRiggingPlayback();
    }
  });
  document.getElementById("btn-rigging-vp-create-urdf")?.addEventListener("click", () => {
    document.getElementById("btn-rigging-generate-urdf")?.click();
  });
  document.getElementById("btn-rigging-vp-create-srdf")?.addEventListener("click", () => {
    document.getElementById("btn-rigging-generate-srdf")?.click();
  });
  document.getElementById("btn-rigging-vp-create-sdf")?.addEventListener("click", () => {
    void generateRobotArtifacts("sdf").catch(() => generateRobotArtifacts("both"));
  });
  document.getElementById("btn-rigging-vp-generate")?.addEventListener("click", () => {
    setRightTab("rigging");
    try { window.Render3DPanels?.setRightPanelHidden?.(false); } catch (_) { }
    document.getElementById("btn-rigging-prompt")?.click();
  });
  document.getElementById("rigging-vp-artifact-source")?.addEventListener("change", (e) => {
    const panel = document.getElementById("rigging-artifact-source");
    if (panel) panel.value = e.target.value;
  });
}

function canvasFolderPath() {
  return `Canvas/${canvasStoreName}`;
}

function ensureTimestampedCanvasName() {
  if (!isGenericCanvasName(canvasStoreName)) return canvasStoreName;
  canvasStoreName = defaultCanvasTimestampName();
  canvasModeInstance?.setTitle?.(canvasStoreName, { silent: true });
  syncCanvasDocTab();
  return canvasStoreName;
}

function syncCanvasDocTab() {
  const id = canvasActiveTabId || CANVAS_TAB_ID;
  canvasTabStores.set(id, canvasStoreName);
  docTabs?.upsert?.({
    id,
    label: canvasStoreName || "Canvas",
    kind: "canvas",
    customLabel: canvasStoreName,
  });
}

function rememberRestoredCanvasTabs() {
  for (const tab of docTabs?.list?.() || []) {
    if (tab.kind !== "canvas") continue;
    const name = slugifyCanvasName(tab.customLabel || tab.label);
    if (name) canvasTabStores.set(tab.id, name);
  }
}

function listProjectCanvasEntries() {
  const files = [
    ...(lastProjectFiles || []),
    ...flattenBrowserEntries(lastProjectBrowser?.references),
  ];
  return collectCanvasBoardNames(files, canvasStoreName);
}

let canvasBoardsAbort = null; // leakfix50
function beginCanvasBoardsFetch() {
  if (canvasBoardsAbort) {
    try { canvasBoardsAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  canvasBoardsAbort = ctl;
  return ctl;
}

async function fetchProjectCanvasBoards() {
  const local = listProjectCanvasEntries();
  if (!projectId) return local;
  const ctl = beginCanvasBoardsFetch();
  try {
    const data = await api(`/api/projects/${projectId}/canvas-boards`, { signal: ctl.signal });
    if (ctl.signal.aborted) return local;
    const boards = Array.isArray(data?.boards) ? data.boards : [];
    return collectCanvasBoardNames(
      boards.map((row) => ({
        canvasName: row?.name,
        folder: row?.folder || `Canvas/${row?.name || ""}`,
        mtime: row?.mtime,
        updated_at: row?.updated_at,
      })),
      canvasStoreName,
    );
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return local;
    return local;
  } finally {
    if (canvasBoardsAbort === ctl) canvasBoardsAbort = null;
  }
}

function scheduleCanvasAutosave() {
  if (canvasBoardSwitching) return;
  canvasBoardDirty = true;
  if (canvasAutosaveTimer) window.clearTimeout(canvasAutosaveTimer);
  canvasAutosaveTimer = window.setTimeout(() => {
    void persistCanvasBoard({ refreshList: false });
  }, CANVAS_AUTOSAVE_MS);
}

async function persistCanvasBoard({ force = false, refreshList = true, name = null } = {}) {
  if (canvasAutosaveTimer) {
    window.clearTimeout(canvasAutosaveTimer);
    canvasAutosaveTimer = 0;
  }
  if (!projectId || canvasBoardSwitching) return;
  if (!name) ensureTimestampedCanvasName();
  const storeName = slugifyCanvasName(name || canvasStoreName);
  if (!storeName) return;
  const state = canvasModeInstance?.exportState?.();
  const hasWork = !!(state?.elements?.length);
  if (!force && !hasWork && !canvasBoardDirty) return;
  try {
    await api(`/api/projects/${projectId}/canvas-board`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: storeName, state: state || {} }),
    });
    canvasBoardDirty = false;
    canvasBoardLoadedFor = `${projectId}:${storeName}`;
    rememberEditedCanvasBoard(storeName);
    if (refreshList) await refreshFiles();
  } catch (err) {
    console.warn("Canvas autosave failed", err);
  }
}

async function loadCanvasBoardIfAny({ force = false } = {}) {
  if (!projectId) {
    ensureTimestampedCanvasName();
    return;
  }
  const key = `${projectId}:${canvasStoreName}`;
  if (!force && key === canvasBoardLoadedFor && canvasModeInstance?.hasDrawing?.()) return;
  const namesToTry = [];
  const current = canvasStoreName || "Canvas";
  namesToTry.push(current);
  if (isGenericCanvasName(current) && !namesToTry.includes("Canvas")) namesToTry.push("Canvas");
  let data = null;
  let loadedName = current;
  for (const name of namesToTry) {
    try {
      data = await api(`/api/projects/${projectId}/canvas-board?name=${encodeURIComponent(name)}`);
      loadedName = name;
      break;
    } catch {
      data = null;
    }
  }
  if (data) {
    canvasStoreName = slugifyCanvasName(data.name || loadedName);
    canvasModeInstance?.importState?.(data?.state || { elements: [] });
    canvasModeInstance?.setCanvasPermission?.(data?.canvas_permission || "edit");
    if (isGenericCanvasName(canvasStoreName)) {
      const stamped = defaultCanvasTimestampName();
      const old = canvasStoreName;
      canvasStoreName = stamped;
      try {
        await api(`/api/projects/${projectId}/canvas-board/rename`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ old_name: old, new_name: stamped }),
        });
      } catch {
        await persistCanvasBoard({ force: true, refreshList: false });
      }
    }
  } else if (!canvasModeInstance?.hasDrawing?.()) {
    canvasModeInstance?.importState?.({ elements: [] });
    ensureTimestampedCanvasName();
  } else {
    ensureTimestampedCanvasName();
  }
  canvasModeInstance?.setTitle?.(canvasStoreName, { silent: true });
  canvasBoardLoadedFor = `${projectId}:${canvasStoreName}`;
  canvasBoardDirty = false;
  if (data) rememberEditedCanvasBoard(canvasStoreName);
  syncCanvasDocTab();
}

async function ensureCanvasStore() {
  if (!projectId) await ensureProjectForUpload();
  ensureTimestampedCanvasName();
  canvasModeInstance?.setTitle?.(canvasStoreName, { silent: true });
  await persistCanvasBoard({ force: true, refreshList: false });
}

async function handleCanvasImageDrop(files, pos, { alreadyPlaced = false } = {}) {
  const incoming = [...(files || [])].filter((f) => (
    String(f?.type || "").startsWith("image/")
    || isHeicFile(f)
    || /\.(png|jpe?g|webp|gif|bmp|svg|tiff?|heic|heif)$/i.test(f?.name || "")
  ));
  const images = [];
  try {
    for (const file of incoming) images.push(await ensurePngImageFile(file));
  } catch (err) {
    setEditStatus("error", err.message || "Could not convert HEIC to PNG.");
    return;
  }
  if (!images.length) return;
  // Place from the local file immediately. Project file URLs need a Bearer
  // token, so a raw <img src="/api/..."> paints as a grey box in Chrome.
  if (!alreadyPlaced) {
    await canvasModeInstance?.addDroppedImageFiles?.(images, pos);
  }
  await ensureCanvasStore();
  for (const file of images) {
    await uploadReferenceProjectFile(file, {
      silent: true,
      referenceFolder: canvasFolderPath(),
      projectId,
    });
  }
  scheduleCanvasAutosave();
  setEditStatus("ok", `Saved to Reference Files → Canvas → ${canvasStoreName} (newest first).`);
}

async function renameCanvasStore(nextName) {
  const cleaned = slugifyCanvasName(nextName);
  if (!cleaned) {
    canvasModeInstance?.setTitle?.(canvasStoreName, { silent: true });
    return;
  }
  const old = canvasStoreName;
  if (cleaned === old) return;
  canvasStoreName = cleaned;
  canvasModeInstance?.setTitle?.(cleaned, { silent: true });
  const tabId = canvasActiveTabId || CANVAS_TAB_ID;
  canvasTabStores.set(tabId, cleaned);
  docTabs?.upsert?.({ id: tabId, label: cleaned, kind: "canvas", customLabel: cleaned });
  if (!projectId) return;
  try {
    await api(`/api/projects/${projectId}/canvas-board/rename`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ old_name: old, new_name: cleaned }),
    });
  } catch {
    canvasStoreName = old;
    canvasModeInstance?.setTitle?.(old, { silent: true });
    canvasTabStores.set(tabId, old);
    docTabs?.upsert?.({ id: tabId, label: old, kind: "canvas", customLabel: old });
    canvasBoardLoadedFor = `${projectId}:${old}`;
    return;
  }
  canvasBoardLoadedFor = `${projectId}:${cleaned}`;
  rememberEditedCanvasBoard(cleaned);
}

function maybeShowCanvasSaveHint() {
  const uid = currentUser?.id || null;
  if (reminderHasSeen(CANVAS_SAVE_HINT_KEY, uid)) return;
  const modal = document.getElementById("canvas-save-hint-modal");
  if (!modal) return;
  requestAnimationFrame(() => modal.classList.remove("hidden"));
}

function hideCanvasSaveHint({ remember = false } = {}) {
  document.getElementById("canvas-save-hint-modal")?.classList.add("hidden");
  if (remember) reminderMarkSeen(CANVAS_SAVE_HINT_KEY, currentUser?.id || null);
}

function maybeShowSharedProjectsHint() {
  const uid = currentUser?.id || null;
  if (reminderHasSeen(SHARED_PROJECTS_HINT_KEY, uid)) return;
  document.getElementById("shared-projects-hint-modal")?.classList.remove("hidden");
}

function hideSharedProjectsHint({ remember = false } = {}) {
  document.getElementById("shared-projects-hint-modal")?.classList.add("hidden");
  if (remember) reminderMarkSeen(SHARED_PROJECTS_HINT_KEY, currentUser?.id || null);
}

function sharedProjectTabId(projectId) {
  return `__sharedproj_${String(projectId || "").trim()}__`;
}

function upsertSharedProjectTab(projectId, { pinned = true } = {}) {
  const id = String(projectId || "").trim();
  if (!id || !docTabs) return;
  const proj = (typeof allProjects !== "undefined" ? allProjects : []).find((row) => String(row.id) === id);
  docTabs.upsert({
    id: sharedProjectTabId(id),
    label: proj?.name || "Shared project",
    kind: "shared",
    pinned: !!pinned,
  });
}

async function listRecentCanvasBoards() {
  const local = [
    ...(lastProjectFiles || []),
    ...flattenBrowserEntries(lastProjectBrowser?.references),
  ];
  if (!projectId) return listCanvasBoardsByRecency(local);
  const ctl = beginCanvasBoardsFetch();
  try {
    const data = await api(`/api/projects/${projectId}/canvas-boards`, { signal: ctl.signal });
    if (ctl.signal.aborted) return listCanvasBoardsByRecency(local);
    const remote = (Array.isArray(data?.boards) ? data.boards : []).map((row) => ({
      canvasName: row?.name,
      folder: row?.folder || `Canvas/${row?.name || ""}`,
      mtime: row?.mtime,
      updated_at: row?.updated_at,
    }));
    return listCanvasBoardsByRecency([...remote, ...local]);
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return listCanvasBoardsByRecency(local);
    return listCanvasBoardsByRecency(local);
  } finally {
    if (canvasBoardsAbort === ctl) canvasBoardsAbort = null;
  }
}

function hideCanvasOpenChooser() {
  document.getElementById("canvas-open-chooser-modal")?.classList.add("hidden");
}

function commitCanvasOpenDontAsk() {
  const skip = document.getElementById("canvas-open-dont-ask");
  if (skip?.checked) writeCanvasAskOpenPref(false);
}

function rememberEditedCanvasBoard(name = canvasStoreName) {
  if (!projectId) return;
  writeLastEditedCanvasName(projectId, name);
}

async function resolveOpenLastCanvasBoard() {
  const boards = await listRecentCanvasBoards();
  return pickLastCanvasBoard(boards, {
    lastEditedName: readLastEditedCanvasName(projectId),
  });
}

function showCanvasOpenChooser(last) {
  const modal = document.getElementById("canvas-open-chooser-modal");
  const nameEl = document.getElementById("canvas-open-last-name");
  if (nameEl) nameEl.textContent = last?.name || "last canvas";
  const skip = document.getElementById("canvas-open-dont-ask");
  if (skip) skip.checked = false;
  modal?.classList.remove("hidden");
}

async function openCanvasWithChooser() {
  const last = await resolveOpenLastCanvasBoard();
  if (!last || !readCanvasAskOpenPref()) {
    if (last) await openProjectCanvas(last.name, { replace: true });
    else await loadCanvasBoardIfAny();
    maybeShowCanvasSaveHint();
    return;
  }
  showCanvasOpenChooser(last);
}

function openCanvasDocTab() {
  canvasActiveTabId = canvasActiveTabId || CANVAS_TAB_ID;
  syncCanvasDocTab();
  docTabs.setActive(canvasActiveTabId, { notify: false });
  const alreadyOpen = isCanvasDesignTabActive();
  enterCanvasTab({ skipViewportResize: alreadyOpen });
  void openCanvasWithChooser();
}

async function openCanvasBoardFromBrowser(project, entry, board) {
  const ref = board || canvasBoardFromBrowserEntry(entry) || canvasBoardReference(entry);
  if (!ref?.name) return;
  if (project?.id && project.id !== projectId) {
    await loadProject(project.id);
  }
  await openProjectCanvas(ref.name);
  setEditStatus("ok", `Canvas — ${ref.name}. Keep editing in the viewport.`);
}

async function loadCanvasIntoViewer(next, tabId) {
  canvasBoardSwitching = true;
  try {
    if (canvasAutosaveTimer) {
      window.clearTimeout(canvasAutosaveTimer);
      canvasAutosaveTimer = 0;
    }
    canvasActiveTabId = tabId || canvasActiveTabId || CANVAS_TAB_ID;
    canvasStoreName = next;
    canvasTabStores.set(canvasActiveTabId, next);
    rememberEditedCanvasBoard(next);
    syncCanvasDocTab();
    docTabs.setActive(canvasActiveTabId, { notify: false });
    const alreadyOpen = isCanvasDesignTabActive();
    if (!alreadyOpen) enterCanvasTab({ skipViewportResize: false });
    else canvasModeInstance?.setTitle?.(next, { silent: true });
    await loadCanvasBoardIfAny({ force: true });
    canvasBoardDirty = false;
  } finally {
    canvasBoardSwitching = false;
  }
}

async function openProjectCanvas(name, { replace = false } = {}) {
  const next = slugifyCanvasName(name);
  if (!next) return;
  const active = docTabs?.getActive?.();
  const currentTabId = (active?.kind === "canvas" ? active.id : canvasActiveTabId) || CANVAS_TAB_ID;
  const plan = resolveCanvasTabOpen({ replace, currentTabId, nextName: next });
  const previousName = canvasStoreName;
  try { viewportVideoRecorder?.hideEditorWindow?.(); } catch { /* ignore */ }
  if (isCanvasDesignTabActive() && previousName) {
    await persistCanvasBoard({ refreshList: false, name: previousName });
  }
  if (plan.action === "replace") {
    await loadCanvasIntoViewer(next, plan.tabId || currentTabId);
    return;
  }
  const reuse = (docTabs?.list?.() || []).find((tab) => (
    tab.kind === "canvas" && slugifyCanvasName(canvasTabStores.get(tab.id) || tab.customLabel || tab.label) === next
  ));
  await loadCanvasIntoViewer(next, reuse?.id || `__canvas__${Date.now().toString(36)}__`);
}

function listProjectVideoEntries() {
  const seen = new Set();
  const out = [];
  const add = (file) => {
    const name = String(file?.name || file?.filename || "");
    const kind = String(file?.kind || "").toLowerCase();
    if (!name || seen.has(name)) return;
    if (!(kind === "video" || /\.(webm|mp4|mov|m4v)$/i.test(name))) return;
    seen.add(name);
    out.push({
      filename: file.url || file.name || name,
      name,
      label: file.label || file.stem || name.replace(/\.[^.]+$/, ""),
      folder: file.folder || "",
      mtime: file.mtime,
      kind: "video",
    });
  };
  for (const file of lastProjectFiles || []) add(file);
  for (const entry of flattenBrowserEntries(lastProjectBrowser?.references)) add(entry);
  return out.sort((a, b) => (Number(b.mtime) || 0) - (Number(a.mtime) || 0));
}

function openProjectEditorTab() {
  parkCanvasOverlay();
  ribbon?.setShellHighlight?.("EDITOR");
  void viewportVideoRecorder?.openEditorTab?.({ label: "Editor" });
  setEditStatus("ok", "Editor — timeline / film tab. Open a clip or create a new one.");
}

function isCanvasSplitActive() {
  return isCanvasDesignTabActive() && document.querySelector(".main-column")?.classList.contains("canvas-layout-split");
}

/* cansplit=20260916-1: retract left browser + right AI dock while any viewport split is on. */
const splitRetractState = { active: false, left: false, right: false };

function isViewportSplitStealingSpace() {
  const col = document.querySelector(".main-column");
  const app = document.getElementById("app");
  return !!(
    col?.classList.contains("canvas-layout-split")
    || col?.classList.contains("viewport-doc-split")
    || col?.classList.contains("code-layout-split")
    || app?.classList.contains("canvas-split-active")
  );
}

function applyCanvasSplitChrome(enabled) {
  const on = !!enabled;
  document.querySelector(".main-column")?.classList.toggle("canvas-layout-split", on);
  document.getElementById("app")?.classList.toggle("canvas-split-active", on);
  document.getElementById("canvas-workspace")?.classList.toggle("canvas-split-on", on);
  document.getElementById("canvas-mode-container")?.classList.toggle("canvas-split-on", on);
  const btn = document.getElementById("canvas-split-btn");
  btn?.setAttribute("aria-pressed", String(on));
  btn?.classList.toggle("active", on);
}

function syncSplitPanelRetract() {
  const on = isViewportSplitStealingSpace();
  if (on === splitRetractState.active) return;
  const appEl = document.getElementById("app");
  if (on) {
    splitRetractState.left = !appEl?.classList.contains("left-panel-hidden");
    splitRetractState.right = !appEl?.classList.contains("right-panel-hidden");
    splitRetractState.active = true;
    if (splitRetractState.left) {
      try { window.Render3DPanels?.setSidebarHidden?.(true, { persist: false }); } catch (_) { /* ignore */ }
    }
    if (splitRetractState.right) {
      try { window.Render3DPanels?.setRightPanelHidden?.(true, { persist: false }); } catch (_) { /* ignore */ }
    }
    return;
  }
  splitRetractState.active = false;
  if (splitRetractState.left && appEl?.classList.contains("left-panel-hidden")) {
    try { window.Render3DPanels?.setSidebarHidden?.(false, { persist: false }); } catch (_) { /* ignore */ }
  }
  if (splitRetractState.right && appEl?.classList.contains("right-panel-hidden")) {
    try { window.Render3DPanels?.setRightPanelHidden?.(false, { persist: false }); } catch (_) { /* ignore */ }
  }
  splitRetractState.left = false;
  splitRetractState.right = false;
}

function setCanvasSplit(enabled) {
  applyCanvasSplitChrome(enabled);
  if (enabled) {
    viewport.classList.remove("doc-viewer-active", "hidden");
    viewport.style.visibility = "";
    viewport.hidden = false;
  }
  syncSplitPanelRetract();
  refreshViewportAfterLayoutChange({ fit: false });
}

function parkCanvasOverlay() {
  const canvasOpen = document.getElementById("app")?.classList.contains("canvas-design-tab")
    || document.body.classList.contains("canvas-design-tab");
  // Closing a VID tab parks Canvas as a side effect. Do not hydrate the
  // project body here — that stalls Chrome's GPU process with a live WebGL view.
  if (canvasOpen) void persistCanvasBoard({ refreshList: false });
  setCanvasSplit(false);
  document.getElementById("canvas-workspace")?.classList.add("hidden");
  document.getElementById("app")?.classList.remove("canvas-design-tab");
  document.body.classList.remove("canvas-design-tab");
  canvasModeInstance?.hide?.();
  ribbon?.setShellHighlight?.(null);
  syncCanvasGenerationUi();
}

function enterCanvasTab({ skipViewportResize = false } = {}) {
  void skipViewportResize;
  catalogPanel?.close?.();
  texturePanel?.close?.();
  exitRiggingMode();
  try { viewportVideoRecorder?.hideEditorWindow?.(); } catch { /* ignore */ }
  document.getElementById("canvas-workspace")?.classList.remove("hidden");
  document.getElementById("app")?.classList.add("canvas-design-tab");
  document.body.classList.add("canvas-design-tab");
  canvasModeInstance?.show?.();
  canvasModeInstance?.setTitle?.(canvasStoreName, { silent: true });
  showAiComposePanel({ focus: false });
  ribbon?.setShellHighlight?.("CANVAS");
  syncCanvasGenerationUi();
  // Do not dispatch window.resize: 3D WebGL still sized under the overlay plus
  // Canvas ResizeObserver = Chrome GPU freeze. Park desktop render instead.
}

function exitCanvasTab() {
  parkCanvasOverlay();
  restoreStudioViewportAfterEditor();
}

function handleDesignTabChange(tab) {
  const app = document.getElementById("app");
  const leavingRobotics = app?.classList.contains("robotics-design-tab") && tab !== "ROBOTICS";
  if (tab !== "ELECTRONICS") closeElectronicsPopover();
  if (tab !== "ROBOTICS") {
    roboticSimulator?.hide?.();
    viserViewer?.closeTab?.();
    teleopViewer?.closeTab?.();
    simulationViewer?.closeTab?.();
    worktopViewer?.closeTab?.();
    workshopEditor?.hide?.();
  }
  if (tab !== "SKETCH" && sketchEditor.isActive()) {
    if (!finishActiveSketch()) sketchEditor.cancel();
  }
  if (tab === "RIGGING") {
    exitSketchMode();
    exitArchitectMode();
    enterRiggingMode();
  } else {
    exitRiggingMode();
  }
  if (tab === "ARCHITECT") {
    enterArchitectMode();
  } else {
    exitArchitectMode();
  }
  if (tab === "SKETCH") {
    setRightTab("sketch");
    focusViewportForShortcuts();
    setEditStatus("ok", "Sketch mode — click Create Sketch to enter locked 2D edit.");
  } else if (tab === "RIGGING") {
    focusViewportForShortcuts();
    setEditStatus("ok", "Rigging — model viewport with manage overlay and timeline.");
  } else if (tab === "ARCHITECT") {
    focusViewportForShortcuts();
    setEditStatus("ok", "Architect — drag walls, Shift+drag rooms, right-click delete. Middle pans; Shift+middle orbits.");
  } else if (tab === "CATALOG") {
    exitCanvasTab();
    exitSketchMode();
    texturePanel?.close?.();
    catalogPanel?.open?.();
    setRightTab("prompt");
    setEditStatus("ok", "Parts Catalog — browse parts, load McMaster-Carr, or manage STEP files.");
  } else if (tab === "TEXTURE") {
    exitCanvasTab();
    exitSketchMode();
    catalogPanel?.close?.();
    mcmasterInsert?.close?.();
    texturePanel?.open?.();
    setRightTab("prompt");
    setEditStatus("ok", "Textures — save rendered looks, favorite them, and apply to parts or faces.");
  } else if (tab === "ELECTRONICS") {
    exitCanvasTab();
    exitSketchMode();
    catalogPanel?.close?.();
    texturePanel?.close?.();
    mcmasterInsert?.close?.();
    void showElectronicsTabUi();
  } else if (tab === "ROBOTICS") {
    exitCanvasTab();
    exitSketchMode();
    catalogPanel?.close?.();
    texturePanel?.close?.();
    mcmasterInsert?.close?.();
    void showRoboticsTabUi();
  } else if (tab === "WORKSPACE") {
    exitCanvasTab();
    exitSketchMode();
    catalogPanel?.close?.();
    texturePanel?.close?.();
    mcmasterInsert?.close?.();
    void openWorkshopEditor();
    setEditStatus("ok", "Workspace — use God View or enter VR. Build the room from World.");
  } else if (tab === "CANVAS") {
    exitSketchMode();
    catalogPanel?.close?.();
    texturePanel?.close?.();
    openCanvasDocTab();
    setEditStatus("ok", "Canvas — sketch on the grid. Drops save to this canvas folder.");
  } else if (tab === "EDITOR") {
    exitSketchMode();
    catalogPanel?.close?.();
    texturePanel?.close?.();
    openProjectEditorTab();
  } else {
    closeElectronicsPopover();
    catalogPanel?.close?.();
    mcmasterInsert?.close?.();
    exitCanvasTab();
    exitSketchMode();
    setRightTab("prompt", { reveal: false });
    promptHistory.setTab("compose");
    focusViewportForShortcuts();
  }
  if (tab !== "CANVAS" && tab !== "EDITOR") ribbon?.setDesignTab(tab);
  if (tab === "ROBOTICS") {
    viserViewer?.syncList?.();
    teleopViewer?.syncList?.();
    simulationViewer?.syncList?.();
  }
  app?.classList.toggle("solid-design-tab", tab === "SOLID");
  app?.classList.toggle("sketch-design-tab", tab === "SKETCH");
  app?.classList.toggle("rigging-design-tab", tab === "RIGGING");
  app?.classList.toggle("architect-design-tab", tab === "ARCHITECT");
  app?.classList.toggle("canvas-design-tab", tab === "CANVAS");
  app?.classList.toggle("robotics-design-tab", tab === "ROBOTICS");
  app?.classList.toggle("workspace-design-tab", tab === "WORKSPACE");
  // Generation / snap paths key off body classes (same as Canvas).
  document.body.classList.toggle("architect-design-tab", tab === "ARCHITECT");
  document.body.classList.toggle("rigging-design-tab", tab === "RIGGING");
  document.body.classList.toggle("robotics-design-tab", tab === "ROBOTICS");
  document.body.classList.toggle("workspace-design-tab", tab === "WORKSPACE");
  document.body.classList.toggle("solid-design-tab", tab === "SOLID");
  document.body.classList.toggle("sketch-design-tab", tab === "SKETCH");
  syncObjectAdjustmentChrome(tab);
  if (leavingRobotics) {
    robotRailTab.noteUserTab("prompt");
    robotRailTab.sync(getDimosTeleopState());
  }
}

let sketchFacePickActive = false;

function pickFaceHit(event) {
  if (!currentMesh) return null;
  const rect = renderer.domElement.getBoundingClientRect();
  const ndc = new THREE.Vector2(
    ((event.clientX - rect.left) / rect.width) * 2 - 1,
    -((event.clientY - rect.top) / rect.height) * 2 + 1
  );
  const rc = new THREE.Raycaster();
  rc.setFromCamera(ndc, camera);
  const hits = rc.intersectObject(currentMesh, true).filter((h) => h.object.isMesh && h.faceIndex != null);
  return hits[0] || null;
}

function beginSketchFacePick() {
  if (!currentMesh) {
    setEditStatus("error", "Load a model first, then pick a face for the sketch.");
    return false;
  }
  if (sketchEditor.isActive?.()) {
    setEditStatus("ok", "Already editing a sketch — use Finish Sketch or Cancel.");
    return false;
  }
  sketchFacePickActive = true;
  activatePickMode("off");
  transformControls.detach();
  gizmoPanel.hide();
  document.getElementById("btn-gizmo")?.classList.remove("active");
  setEditStatus("ok", "Click a face on the model to sketch on it. Esc to cancel.");
  return true;
}

function cancelSketchFacePick() {
  if (!sketchFacePickActive) return;
  sketchFacePickActive = false;
  clearHover();
  setEditStatus("", "");
}

function maybeStartSketch(data = {}) {
  const planeChoice = data?.plane || "XY";
  workspaceModes.setDesignTab("SKETCH");
  ribbon?.setDesignTab("SKETCH");
  applyWorkspaceMode("design");
  if (planeChoice === "Face") {
    beginSketchFacePick();
    return;
  }
  sketchEditor.start(planeChoice);
  enterSketchMode();
}

function handleSketchAction(action, entry, data = {}) {
  if (action === "start_tab") {
    if (sketchEditor.isActive()) {
      setEditStatus("ok", "Already editing a sketch — use Finish Sketch or Cancel.");
      return;
    }
    workspaceModes.setDesignTab("SKETCH");
    maybeStartSketch(data);
    return;
  }
  if (action === "start") {
    if (sketchEditor.isActive()) {
      setEditStatus("ok", "Already editing a sketch — use Finish Sketch or Cancel.");
      return;
    }
    if (workspaceModes.getDesignTab() !== "SKETCH") {
      workspaceModes.setDesignTab("SKETCH");
    }
    maybeStartSketch(data);
    return;
  }
  if (action === "tool") {
    if (!sketchEditor.isActive()) {
      workspaceModes.setDesignTab("SKETCH");
      sketchEditor.start("XY");
      enterSketchMode();
    }
    sketchEditor.setTool(data?.tool || entry?.sketchTool || "line");
    ribbon?.setActiveSketchTool?.(data?.tool || entry?.sketchTool || "line");
    return;
  }
  if (action === "finish") {
    finishActiveSketch();
    return;
  }
  if (action === "cancel") {
    sketchEditor.cancel();
    exitSketchMode();
    return;
  }
  if (action === "extrude") {
    if (sketchEditor.isActive()) {
      setEditStatus("error", "Finish the sketch first.");
      return;
    }
    const finished = sketchEditor.getFinishedSketch?.() || sketchEditor.getActiveViewportSketch?.();
    if (!startExtrudeFromSketchData(finished)) {
      setEditStatus("error", "Finish the sketch with a closed profile first, or click a sketch in the browser.");
    }
    return;
  }
}

function handleRiggingAction(action, entry, data = {}) {
  if (workspaceModes.getDesignTab() !== "RIGGING") {
    workspaceModes.setDesignTab("RIGGING");
  }
  if (action === "tool") {
    riggingEditor.setTool(data?.tool || entry?.rigTool || "select");
    syncRiggingToolbelt();
    return;
  }
  if (action === "add") {
    riggingEditor.setTool("add");
    syncRiggingToolbelt();
    setEditStatus("ok", "Click the model or grid to place a bone.");
    return;
  }
  if (action === "connect") {
    riggingEditor.setTool("connect");
    syncRiggingToolbelt();
    setEditStatus("ok", "Connect: click parent bone, then child bone.");
    return;
  }
  if (action === "delete") {
    riggingEditor.deleteSelected();
    return;
  }
  if (action === "clear") {
    if (window.confirm("Clear all bones from this rig?")) riggingEditor.clearRig();
    return;
  }
  if (action === "save") {
    riggingEditor.save().then(() => setEditStatus("ok", "Rig saved."));
    return;
  }
  if (action === "reload") {
    riggingEditor.load().then(() => setEditStatus("ok", "Rig reloaded."));
    return;
  }
  if (action === "auto") {
    riggingEditor.autoRigChain();
    return;
  }
  if (action === "simulate") {
    void simulateRiggingModel();
    return;
  }
  if (action === "keyframe") {
    riggingEditor.insertKeyframe();
    return;
  }
  if (action === "play") {
    toggleRiggingPlayback();
    return;
  }
  if (action === "stop") {
    stepModuleRuntime?.stop?.({ reset: true });
    planetaryGearRuntime?.stop?.({ reset: true });
    urdfRobotRuntime?.stopTrajectory?.();
    riggingEditor.setPlaying(false);
    syncRiggingViewportPlaybackUi();
    return;
  }
  if (action === "export_urdf") {
    riggingEditor.exportUrdf();
    return;
  }
}

