function isRobotArtifactEntry(entry, sectionId) {
  if (sectionId === "robots" || sectionId === "robots-urdf") return true;
  return /\.(urdf|srdf|sdf)$/i.test(String(entry?.name || entry?.filename || ""));
}

function applyLoadedRobotFileVisibility() {
  const { urdfFile } = pickPreferredRobotFiles(robotArtifactData || {});
  if (!urdfFile) {
    urdfRobotRuntime?.setLoadedRobotVisible?.(true);
    return;
  }
  let hidden = new Set();
  try {
    const key = typeof hiddenComponentsStorageKey === "function" ? hiddenComponentsStorageKey(projectId) : "";
    const raw = key ? localStorage.getItem(key) : "";
    if (raw) hidden = new Set(JSON.parse(raw).map(String));
  } catch { /* ignore */ }
  urdfRobotRuntime?.setLoadedRobotVisible?.(!hidden.has(String(urdfFile)));
}

