function activeColorValue() {
  return colorToolInput?.value || "#58a6ff";
}

function setActiveColor(hex, { syncXr = true } = {}) {
  const value = String(hex || "#58a6ff").trim() || "#58a6ff";
  if (colorToolInput) colorToolInput.value = value;
  colorPaletteGrid?.querySelectorAll(".color-swatch-card").forEach((btn) => {
    btn.classList.toggle("active", (btn.dataset.color || "").toLowerCase() === value.toLowerCase());
  });
  if (syncXr) {
    try { viewportXR?.setPaintColor?.(value); } catch { /* ignore */ }
  }
  try { localStorage.setItem("render3d.paintColor", value); } catch { /* ignore */ }
  return value;
}

function renderColorPalette() {
  if (!colorPaletteGrid) return;
  colorPaletteGrid.innerHTML = "";
  COLOR_PALETTE.forEach((item) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "color-swatch-card";
    btn.dataset.color = item.hex;
    btn.title = `${item.label} (${item.hex})`;
    btn.innerHTML = `<span class="swatch" style="--swatch:${item.hex}"></span><span class="label">${item.label}</span>`;
    btn.addEventListener("click", () => {
      setActiveColor(item.hex);
      setEditStatus("ok", `Palette · ${item.label}. Shape color a body, or Face color on picked faces.`);
    });
    colorPaletteGrid.appendChild(btn);
  });
  let saved = "#58a6ff";
  try { saved = localStorage.getItem("render3d.paintColor") || saved; } catch { /* ignore */ }
  setActiveColor(colorToolInput?.value || saved, { syncXr: false });
}

function selectedColorFilename() {
  const selection = objectTools.getSelection?.();
  const fromSelection = selection?.catalogName || (selection?.mesh ? catalogNameForMesh(selection.mesh) : null);
  return fromSelection || selectedFile;
}

function showColorTool() {
  setRightTab("tools");
  directModeling.reset();
  meshCleanup.hide();
  gizmoPanel.hide();
  transformControls.detach();
  document.getElementById("btn-gizmo")?.classList.remove("active");
  colorToolPanel?.classList.remove("hidden");
  document.querySelectorAll("[data-dm-tool]").forEach((btn) => btn.classList.remove("active"));
  document.getElementById("btn-color-tool")?.classList.add("active");
  renderColorPalette();
  setEditStatus("ok", "Appearance: select a body (V), pick a swatch, then Shape color. Or pick faces and Face color.");
}

function paintBodyPayload(scope, faceRefs = []) {
  const selection = objectTools.getSelection?.();
  const bodyCount = Number(selection?.bodyCount || objectTools.getBodyInfo?.()?.count || 1);
  const bodyIndex = Number.isInteger(selection?.bodyIndex) ? selection.bodyIndex : null;
  const bodyName = String(selection?.label || "").trim() || null;
  const partBody = !!(selection && !selection.isRoot && Number.isInteger(bodyIndex) && bodyCount > 1);
  const payload = {};
  if (scope === "object") {
    if (partBody) {
      payload.body_index = bodyIndex;
      if (bodyName) payload.body_name = bodyName;
    }
    return payload;
  }
  const fromRef = faceRefs.find((r) => Number.isInteger(r.body_index));
  if (fromRef) {
    payload.body_index = Number(fromRef.body_index);
    if (fromRef.body_name) payload.body_name = fromRef.body_name;
    return payload;
  }
  if (partBody) {
    payload.body_index = bodyIndex;
    if (bodyName) payload.body_name = bodyName;
    return payload;
  }
  const uuid = faceRefs.find((r) => r.mesh_uuid)?.mesh_uuid;
  const root = selection?.root;
  if (uuid && root && bodyCount > 1) {
    const meshes = [];
    root.traverse((c) => {
      if (!c.isMesh || !c.geometry) return;
      if (c.userData?.isEdge || c.userData?.isSilhouette || c.userData?.isTransformPivot) return;
      meshes.push(c);
    });
    const idx = meshes.findIndex((m) => m.uuid === uuid);
    if (idx >= 0) payload.body_index = idx;
  }
  return payload;
}

async function paintCurrentModel(scope) {
  if (!projectId) {
    setEditStatus("error", "Select or create a project first.");
    return;
  }
  const filename = selectedColorFilename();
  if (!filename) {
    setEditStatus("error", scope === "faces" ? "Open a model and pick faces first." : "Select an object first (V).");
    return;
  }
  const refs = composer.getReferences?.() || [];
  const faceRefs = refs.filter((r) => r.type === "face" || r.face_index != null);
  if (scope === "faces" && !faceRefs.length) {
    activatePickMode("face");
    setEditStatus("error", "Pick one or more faces first, then click Face color.");
    return;
  }
  const bodyPayload = paintBodyPayload(scope, faceRefs);
  try {
    const data = await api(
      `/api/projects/${encodeURIComponent(projectId)}/files/${encodeProjectFilePath(filename)}/paint`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          scope,
          color: activeColorValue(),
          references: scope === "faces" ? faceRefs : [],
          ...bodyPayload,
        }),
      },
    );
    await afterModelEdit({ ...data, replaceCatalog: data.replace_catalog || data.replaceCatalog || filename });
    const bodyHint = Number.isInteger(bodyPayload.body_index)
      ? ` · ${bodyPayload.body_name || `body ${bodyPayload.body_index + 1}`}`
      : "";
    setEditStatus("ok", scope === "faces" ? `Colored picked faces${bodyHint}.` : `Colored${bodyHint || ` ${filename}`}.`);
    viewerOverlay.clearError();
  } catch (err) {
    const msg = err.message || "Could not apply color.";
    setEditStatus("error", msg);
    viewerOverlay.showError(msg);
  }
}

