/** Right panel → AI (CAD or Wiring) with Compose sub-tab active. */
function showAiComposePanel({ focus = true } = {}) {
  // Always uncollapse the right panel so the prompt UI is visible (auto-popup).
  try {
    window.Render3DPanels?.setRightPanelHidden?.(false);
  } catch (_) { }
  document.getElementById("app")?.classList.remove("right-panel-hidden");
  const reopen = document.getElementById("right-panel-reopen-tab");
  if (reopen) reopen.style.display = "none";

  if (workspaceModes?.isWiring?.()) {
    setRightTab("wiring");
    wiringPromptHistory.setTab("compose");
    const attached = typeof attachWiringBrowserReferenceFiles === "function"
      ? attachWiringBrowserReferenceFiles({ insertMention: false })
      : 0;
    const status = document.getElementById("wiring-prompt-status");
    if (attached > 0 && status && !status.classList.contains("loading")) {
      status.className = "status ok";
      status.textContent = attached === 1
        ? "Attached 1 Browser reference file to Wiring AI."
        : `Attached ${attached} Browser reference files to Wiring AI.`;
    }
    if (focus) {
      queueMicrotask(() => {
        wiringComposer?.editor?.focus?.({ preventScroll: true })
          || document.getElementById("wiring-prompt-input")?.focus?.({ preventScroll: true });
      });
    }
    return;
  }
  setRightTab("prompt");
  promptHistory.setTab("compose");
  // Preserve the user's selected prompt mode (Render / Draw / 2.0 / Fusion).
  // Mobile: do not steal the viewport — Menu / Tools / AI FAB open the window explicitly.
  if (!focus) return;
  queueMicrotask(() => {
    composer?.editor?.focus?.({ preventScroll: true })
      || document.getElementById("prompt-input")?.focus?.({ preventScroll: true });
  });
}

