document.getElementById("btn-feature-collapse")?.addEventListener("click", (e) => {
  const panel = document.querySelector("[data-right-panel='history']");
  const collapsed = !panel?.classList.contains("feature-history-collapsed");
  panel?.classList.toggle("feature-history-collapsed", collapsed);
  e.currentTarget.setAttribute("aria-pressed", String(collapsed));
  e.currentTarget.textContent = collapsed ? "Expand" : "Collapse";
});

function resolveTransformShortcutTarget() {
  const selected = objectTools.getSelection?.();
  const fromSel = isolateTransformTarget(selected?.mesh);
  if (fromSel) return fromSel;
  if (selectedFile) {
    const fromFile = isolateTransformTarget(projectAssembly?.get?.(selectedFile));
    if (fromFile) return fromFile;
  }
  const fromPivot = isolateTransformTarget(cadTransformPivotItem?.object);
  if (fromPivot) return fromPivot;
  const attached = transformControls?.object;
  if (attached && !attached.userData?.isTransformPivot) {
    const fromAttached = isolateTransformTarget(attached);
    if (fromAttached) return fromAttached;
  }
  const fromCurrent = isolateTransformTarget(currentMesh);
  if (fromCurrent) return fromCurrent;
  const entries = projectAssembly?.list?.() || [];
  if (entries.length === 1) return isolateTransformTarget(entries[0]?.[1]);
  return null;
}

function openTransformMode(mode) {
  setRightTab("tools");
  try {
    if (directModeling.isToolActive?.()) directModeling.setTool?.(null);
  } catch (_) { }
  document.querySelectorAll("[data-dm-tool]").forEach((btn) => btn.classList.remove("active"));
  const mesh = resolveTransformShortcutTarget();
  if (mesh) {
    showObjectGizmo(mesh, mode);
  } else {
    setEditStatus("error", "Select an object first, then press R to rotate or S to scale.");
  }
}

function isToolbarGizmoShown() {
  return Boolean(gizmoPanel?.isVisible?.() && transformControls?.object);
}

/** Ribbon Gizmo: turn the triad on even from Orbit (which hides it without clearing selection). */
function toggleToolbarGizmo() {
  if (isToolbarGizmoShown()) {
    transformControls.detach();
    gizmoPanel.hide();
    document.getElementById("btn-gizmo")?.classList.remove("active");
    controls.enabled = true;
    return;
  }
  const mesh = resolveTransformShortcutTarget();
  if (!mesh) {
    setEditStatus("ok", "Select an object first, then use Gizmo.");
    document.getElementById("btn-gizmo")?.classList.remove("active");
    return;
  }
  showObjectGizmo(mesh);
}

function openGenerativeEdits() {
  const filename = selectedObjectFilename();
  showAiComposePanel();
  applyPromptModeUI("v2");
  const targetModeSelect = document.getElementById("prompt-target-mode");
  if (targetModeSelect) targetModeSelect.value = filename ? "edit" : "new";
  if (filename) {
    const objectSelect = document.getElementById("prompt-target-object");
    selectedFile = filename;
    if (objectSelect) objectSelect.value = filename;
    projectTree.setSelected(filename);
    featureEditor.setModel(projectId, filename);
    selectAssemblyComponent(filename, { fitView: false });
  }
  syncPromptTargetUI();
  const example =
    "Resize the selected object: make the main body ___ mm wider, adjust the related supports/holes/clearances proportionally, and preserve the existing functional relationships.";
  if (!composer.getPromptText()) {
    composer.setPromptText(example);
  }
  focusPromptComposer();
  setEditStatus(
    filename ? "ok" : "error",
    filename
      ? "Generative Edits: describe width, size, clearance, or proportion changes for the selected object, then Generate."
      : "Generative Edits opened. Select an object first to edit its width/sizes."
  );
  return true;
}

function launchViewportTool(toolId) {
  closeMobilePanels();
  syncViewportForToolActivation();
  if (toolId === "off" || toolId === "none" || !toolId) {
    try {
      directModeling?.setTool?.(null);
      directModeling?.ensureTool?.(null);
    } catch (_) { }
    try {
      transformControls.detach();
      gizmoPanel.hide();
      document.getElementById("btn-gizmo")?.classList.remove("active");
    } catch (_) { }
    document.querySelectorAll("[data-dm-tool]").forEach((btn) => btn.classList.remove("active"));
    return true;
  }
  if (toolId === "generative_edits") {
    return openGenerativeEdits();
  }
  // Parametric primitives use the VibeCAD-style task panel only (no live DM tool).
  if (String(toolId).startsWith("create_")) {
    return true;
  }
  // Transform: Move gizmo on the selected object (G). No Tasks panel.
  if (toolId === "transform" || toolId === "transform-tasks") {
    openTransformMode("translate");
    setEditStatus("ok", "Transform: drag the arrows/rings to move · R rotate · S scale · Esc to exit.");
    return true;
  }
  if (toolId === "presspull-apply") {
    directModeling.syncFromTaskValues?.();
    if (!directModeling.hasPressPullSession?.()) {
      throw new Error("Select a face or a closed sketch, then click OK.");
    }
    return Promise.resolve(directModeling.applyPressPull?.()).then((ok) => {
      if (!ok) {
        throw new Error(directModeling.getLastError?.() || "Could not apply. Set Length and try OK again.");
      }
      return true;
    });
  }
  setRightTab("tools");
  activatePickMode("off");
  document.querySelectorAll("[data-dm-tool]").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.dmTool === toolId);
  });
  if (toolId === "measure") {
    beginMeasureMode("auto");
    return true;
  }
  if (toolId === "mirror") {
    gizmoPanel.hide();
    transformControls.detach();
    document.getElementById("btn-gizmo")?.classList.remove("active");
    controls.enabled = true;
    directModeling.setTool("mirror");
    setEditStatus("ok", "Mirror: choose/drag a plane or type an offset.");
    return true;
  }
  if (toolId === "hole") {
    gizmoPanel.hide();
    transformControls.detach();
    document.getElementById("btn-gizmo")?.classList.remove("active");
    controls.enabled = true;
    directModeling.setTool("hole");
    setEditStatus("ok", "Hole: click a face point, set diameter/depth/pattern, then Apply.");
    return true;
  }
  if (toolId === "fillet" || toolId === "chamfer") {
    gizmoPanel.hide();
    transformControls.detach();
    document.getElementById("btn-gizmo")?.classList.remove("active");
    controls.enabled = true;
    directModeling.setTool(toolId);
    setEditStatus(
      "ok",
      toolId === "fillet"
        ? "Fillet: drag the viewport radius handle or type a radius, then Apply."
        : "Chamfer: drag the viewport distance handle or type a distance, then Apply."
    );
    return true;
  }
  if (toolId === "presspull" || toolId === "presspull-cut" || toolId === "extrude") {
    gizmoPanel.hide();
    transformControls.detach();
    document.getElementById("btn-gizmo")?.classList.remove("active");
    controls.enabled = true;
    directModeling.setPreferredOp?.(toolId === "presspull-cut" ? "cut" : "auto");
    const faceRef = (composer.getReferences?.() || []).find((r) => r.type === "face" || r.face_index != null);
    const sketch = getSketchForExtrude();
    const sketchCount = sketchEditor.countVisibleSketches?.() ?? 0;
    if (sketch?.profile?.length && sketchCount === 1) {
      startExtrudeFromSketchData(sketch);
    } else if (faceRef && directModeling.startPressPullFromRef?.(faceRef)) {
      setEditStatus("ok", "Face selected — drag the arrow (or type a distance) to Extrude/Cut.");
    } else {
      directModeling.ensureTool?.("presspull") || directModeling.setTool("presspull");
      setEditStatus(
        "ok",
        sketchCount > 0
          ? "Click a sketch profile to extrude, or click a model face and drag to Extrude/Cut."
          : "Click a face, then drag to Extrude (pull) or Cut (push). Esc to exit."
      );
    }
    editTools.updateExtrudeTarget?.();
    return true;
  }
  return false;
}

function closeMarkingMenu() {
  document.querySelector(".marking-menu")?.remove();
  document.removeEventListener("mousedown", onMarkingMenuOutside, true);
}

function onMarkingMenuOutside(e) {
  if (e.target.closest?.(".marking-menu")) return;
  closeMarkingMenu();
}

function layoutMarkingMenuTiles(menu) {
  const buttons = [...menu.querySelectorAll(":scope > button")];
  const n = buttons.length;
  if (!n) return;
  const cs = getComputedStyle(menu);
  const tileW = parseFloat(cs.getPropertyValue("--mm-tile-w")) || 80;
  const tileH = parseFloat(cs.getPropertyValue("--mm-tile-h")) || 36;
  const gap = parseFloat(cs.getPropertyValue("--mm-gap")) || 10;
  const alpha = (Math.PI * 2) / n;
  const denom = 2 * Math.sin(alpha / 2) || 1;
  const needW = tileW + gap;
  const needH = tileH + gap;
  let radius = 0;
  for (let i = 0; i < n; i++) {
    const phi = (i / n) * Math.PI * 2 - Math.PI / 2 + alpha / 2;
    const sSin = Math.abs(Math.sin(phi));
    const sCos = Math.abs(Math.cos(phi));
    const rByX = sSin > 1e-4 ? needW / (denom * sSin) : Infinity;
    const rByY = sCos > 1e-4 ? needH / (denom * sCos) : Infinity;
    radius = Math.max(radius, Math.min(rByX, rByY));
  }
  radius = Math.ceil(radius + 2);
  const size = Math.ceil((radius + Math.hypot(tileW, tileH) / 2 + 10) * 2);
  menu.style.width = `${size}px`;
  menu.style.height = `${size}px`;
  menu.style.marginLeft = `${-Math.round(size / 2)}px`;
  menu.style.marginTop = `${-Math.round(size / 2)}px`;
  buttons.forEach((btn, i) => {
    const angle = (i / n) * Math.PI * 2 - Math.PI / 2;
    btn.style.transform = `translate(${Math.round(Math.cos(angle) * radius)}px, ${Math.round(Math.sin(angle) * radius)}px)`;
  });
}

function placeMarkingMenu(menu, clientX, clientY) {
  const half = (menu.offsetWidth || 520) / 2;
  const pad = 8;
  const x = Math.min(Math.max(clientX, half + pad), window.innerWidth - half - pad);
  const y = Math.min(Math.max(clientY, half + pad), window.innerHeight - half - pad);
  menu.style.left = `${x}px`;
  menu.style.top = `${y}px`;
}

function openMarkingMenu(event) {
  if (!currentMesh) return;
  event.preventDefault();
  closeMarkingMenu();
  const hit = pickObject(event, {
    camera,
    domElement: renderer.domElement,
    meshRoot: currentMesh,
  });
  if (hit?.mesh) {
    selectObjectHit(hit, { showGizmo: false });
  }
  const menu = document.createElement("div");
  menu.className = "marking-menu";
  const designTab = String(workspaceModes?.getDesignTab?.() || "SOLID").toUpperCase();
  const isArchitectTab = designTab === "ARCHITECT";
  const textureAction = isArchitectTab
    ? ["🧱", "AI Wall Texture", () => setArchitectPromptForSelectedEdit("texture_ai")]
    : ["◌", "Remove texture", () => { void removeTexturingFromSelectedModel(); }, "Remove texturing (back to original rendered colors)"];
  const actions = [
    ["⇕", "Press-Pull", () => launchViewportTool("presspull")],
    ["★", "Rate model", () => microEditTools?.rateModel(selectedObjectFilename())],
    ["⌁", "Micro edit", () => microEditTools?.open(false)],
    ["⌫", "Delete object", () => { void deleteActiveAssemblyObject(); }],
    ["✥", "Move", () => openTransformMode("translate")],
    ["⟳", "Rotate", () => openTransformMode("rotate")],
    ["⤢", "Scale", () => openTransformMode("scale")],
    ["⧉", "Duplicate", () => { void duplicateSelectedObject(); }],
    ["↔", "Mirror", () => launchViewportTool("mirror")],
    ["◈", "Mesh Checkup", () => {
      directModeling.reset();
      gizmoPanel.hide();
      transformControls.detach();
      setRightTab("tools");
      meshCleanup.show();
    }],
    ["⊞", "Split bodies", () => {
      setRightTab("tools");
      objectTools.splitBodies();
    }],
    ["🎨", "Color", () => showColorTool()],
    textureAction,
    ["▣", "Pick Face", () => { activatePickMode("face"); setEditStatus("ok", "Click faces on the model to add @face references."); }],
    ["⌁", "Pick Edge", () => { activatePickMode("edge"); setEditStatus("ok", "Click near edges on the model to add @edge references."); }],
    ["▣", "Select object", () => { activatePickMode("object"); setEditStatus("ok", "Click to select the whole model · double-click a part to select just that part · Cmd+Z to undo moves."); }],
    ["↶", "History", () => setRightTab("history")],
  ];
  menu.innerHTML = `<div class="marking-menu-hub" aria-hidden="true"></div>` + actions
    .map(([icon, label], i) => `<button type="button" data-mm="${i}"><span>${icon}</span><small>${label}</small></button>`)
    .join("");
  // Block outside-dismiss from stealing mousedown before button click fires.
  menu.addEventListener("mousedown", (e) => e.stopPropagation());
  menu.addEventListener("pointerdown", (e) => e.stopPropagation());
  document.body.appendChild(menu);
  layoutMarkingMenuTiles(menu);
  placeMarkingMenu(menu, event.clientX, event.clientY);
  const hub = menu.querySelector(".marking-menu-hub");
  actions.forEach(([, label, fn, hint], i) => {
    const btn = menu.querySelector(`[data-mm="${i}"]`);
    if (!btn) return;
    btn.addEventListener("pointerenter", () => {
      if (hub) hub.textContent = hint || label;
    });
    btn.addEventListener("pointerleave", () => {
      if (hub) hub.textContent = "";
    });
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      closeMarkingMenu();
      fn();
    });
  });
  setTimeout(() => document.addEventListener("mousedown", onMarkingMenuOutside, true), 0);
}

function shouldSkipViewportMarkingMenu(target) {
  return isCadDockPointerTarget(target)
    || isViewportBrowserPointerTarget(target)
    || isClipEditorPointerTarget(target);
}

// Open the marking menu only for a true right-click. Right-button drag is pan,
// so wait until pointerup and check travel distance before showing the menu.
let _rcDownX = 0, _rcDownY = 0, _rcActive = false, _rcDragged = false;
viewport.addEventListener("pointerdown", (e) => {
  if (shouldSkipViewportMarkingMenu(e.target)) {
    _rcActive = false;
    _rcDragged = false;
    return;
  }
  if (e.button === 2) {
    _rcDownX = e.clientX;
    _rcDownY = e.clientY;
    _rcActive = true;
    _rcDragged = false;
  }
}, true);
viewport.addEventListener("pointermove", (e) => {
  if (shouldSkipViewportMarkingMenu(e.target)) return;
  if (_rcActive && (e.buttons & 2)) { // right button held
    const moved = Math.hypot(e.clientX - _rcDownX, e.clientY - _rcDownY);
    if (moved > 6) _rcDragged = true;
  }
}, true);
viewport.addEventListener("pointerup", (e) => {
  if (shouldSkipViewportMarkingMenu(e.target)) {
    _rcActive = false;
    _rcDragged = false;
    return;
  }
  if (!_rcActive || e.button !== 2) return;
  const moved = Math.hypot(e.clientX - _rcDownX, e.clientY - _rcDownY);
  const shouldOpen = !_rcDragged && moved <= 6;
  _rcActive = false;
  _rcDragged = false;
  if (shouldOpen) {
    e.preventDefault();
    openMarkingMenu(e);
  }
}, true);
viewport.addEventListener("contextmenu", (e) => {
  if (shouldSkipViewportMarkingMenu(e.target)) {
    e.preventDefault();
    e.stopPropagation();
    return;
  }
  e.preventDefault();
});

const featureEditor = createFeatureEditor({
  container: document.getElementById("feature-editor"),
  api,
  rawFetch,
  onApplied: afterModelEdit,
  isBusy: () => isGenerationUiActive(projectId),
  onGenerating: (active, message) => {
    if (active) {
      showViewportOverlay(projectId, message || "Rebuilding…", { mode: "build", estimateMs: 60000 });
    } else if (!hasGenerationPoll(projectId)) {
      hideViewportOverlay(projectId, { complete: true });
    }
  },
});

function resize() {
  const presenting = !!(viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting);
  if (!shouldResizeDesktopRenderer({ presenting })) return;
  if (shouldParkDesktopViewportForCanvasTab({
    presenting,
    canvasTabActive: isCanvasDesignTabActive(),
    canvasSplit: isCanvasSplitActive(),
  })) return;
  const w = viewport.clientWidth;
  const h = viewport.clientHeight;
  // Viewport is display:none in Canvas / Wiring modes — skip so we don't shrink to 0×0.
  if (!w || !h) return;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  try {
    resetRendererView(renderer, w, h, { clearGlobalClipping: !sectionView?.isActive?.() });
  } catch (_) {
    renderer.setSize(w, h);
  }
  try { controls.handleResize?.(); } catch (_) { }
  sketchEditor.resize?.();
  collab?.resizeLabels();
  try { syncCadEdgeResolution(renderer); } catch (_) { }
}

function refreshLiveWebglViewport() {
  if (viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting) return;
  const el = document.getElementById("viewport") || viewport;
  try { reattachRendererCanvas(renderer, el); } catch (_) { }
  if (isWebglContextLost(renderer)) {
    tryRestoreWebglContext(renderer);
    return;
  }
  if (shouldParkDesktopViewportForCanvasTab({
    presenting: false,
    canvasTabActive: isCanvasDesignTabActive(),
    canvasSplit: isCanvasSplitActive(),
  })) return;
  try { startRendererAnimationLoop(renderer, animate); } catch (_) { }
  restoreFullViewportAfterInteraction({ rebuildFloor: false });
}

function isLiveXrPresenting() {
  if (renderer?.xr?.isFallbackStub) return false;
  return !!(viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting);
}

/** Undo XR swap hide / 1e-6 park so the desktop canvas actually shows CAD. */
function revealDesktopProjectMeshes() {
  if (isLiveXrPresenting()) return false;
  if (!webglAvailable) return false;
  try { projectAssembly.attachToScene?.(); } catch (_) { }
  try { projectAssembly.restoreDesktopTransform?.(); } catch (_) { }
  try {
    const root = projectAssembly.getRoot?.();
    if (root) root.visible = true;
  } catch (_) { }
  try {
    const rows = projectAssembly.list?.() || [];
    for (const [name] of rows) {
      projectAssembly.setVisible(name, !isComponentHidden(name));
    }
  } catch (_) { }
  try { renderer.compile?.(scene, camera); } catch (_) { }
  return Number(projectAssembly.count?.() || 0) > 0;
}

let recoveringWebglMeshes = false;
async function recoverDesktopMeshesAfterWebgl({ reload = false } = {}) {
  if (isLiveXrPresenting() || !webglAvailable) return false;
  if (recoveringWebglMeshes) return false;
  recoveringWebglMeshes = true;
  try {
    try { refreshLiveWebglViewport(); } catch (_) { }
    revealDesktopProjectMeshes();
    const pid = projectId;
    const wiring = !!(workspaceModes?.isWiring?.());
    if (reload && pid && !wiring) {
      try {
        if (!loadingProjectIds.has(pid)) {
          // Force a real GLB fetch — same-project reopen otherwise keeps empty GPU buffers.
          viewportMeshProjectId = null;
          await loadProject(pid);
        }
      } catch (err) {
        console.warn("WebGL mesh recover", err);
      }
      revealDesktopProjectMeshes();
    }
    try { applyHandheldDesktopPlacement(); } catch (_) { }
    try { scheduleFitCameraAfterProjectLoad(); } catch (_) { }
    return Number(projectAssembly.count?.() || 0) > 0;
  } finally {
    recoveringWebglMeshes = false;
  }
}

function restoreStudioViewportAfterEditor() {
  if (viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting) return;
  try { docTabs?.deactivate?.({ notify: false }); } catch (_) { }
  const el = document.getElementById("viewport") || viewport;
  const col = document.querySelector(".main-column");
  try { col?.setAttribute("data-shell-tab", "viewport"); } catch (_) { }
  try { revealViewportEl(el); } catch (_) { }
  hideEditorCoveringViewport({
    canvasWorkspace: document.getElementById("canvas-workspace"),
    videoModal: document.getElementById("viewport-video-share-modal"),
    mainColumn: col,
  });
  try {
    document.getElementById("app")?.classList.remove("canvas-design-tab");
    document.body.classList.remove("canvas-design-tab");
  } catch (_) { }
  const restoreCad = () => {
    try { refreshLiveWebglViewport(); } catch (_) { }
  };
  if (shouldRebuildCadOnVideoEditorCloseTick()) restoreCad();
  else if (typeof requestAnimationFrame === "function") requestAnimationFrame(restoreCad);
  else setTimeout(restoreCad, 0);
}

function restoreFullViewportAfterInteraction({ rebuildFloor = false } = {}) {
  // Quest presentation owns the framebuffer — never fight that crash path.
  if (viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting) return;
  try {
    const w = viewport.clientWidth;
    const h = viewport.clientHeight;
    if (w && h) resetRendererView(renderer, w, h, { clearGlobalClipping: true });
    else {
      renderer.clippingPlanes = [];
      renderer.setScissorTest?.(false);
    }
  } catch (_) { }
  try {
    if (sectionView?.isActive?.()) {
      if (!projectAssembly?.count?.()) sectionView.deactivate();
      else sectionView.onModelChanged?.();
    }
    if (!sectionView?.isActive?.()) renderer.localClippingEnabled = false;
    else renderer.localClippingEnabled = true;
  } catch (_) { }
  try { hardenTransformHelper?.(); } catch (_) { }
  if (rebuildFloor) {
    try { rebuildGrid(); } catch (_) { }
  }
  const bump = () => {
    try { resize(); } catch (_) { }
    try { updateCameraClipPlanes(); } catch (_) { }
    try { controls.handleResize?.(); } catch (_) { }
    try { viewCube.update?.(); } catch (_) { }
  };
  bump();
  requestAnimationFrame(bump);
  for (const delay of [80, 220]) window.setTimeout(bump, delay);
}

function syncViewportForToolActivation({ fit = false } = {}) {
  renderer.domElement?.setAttribute?.("tabindex", "0");
  renderer.domElement?.focus?.({ preventScroll: true });
  for (const delay of [0, 80, 220]) {
    window.setTimeout(() => {
      resize();
      controls.update();
      viewCube.update?.();
      if (fit && currentMesh) fitCamera();
    }, delay);
  }
}

function refreshViewportAfterLayoutChange({ fit = false } = {}) {
  requestAnimationFrame(() => {
    resize();
    controls.update();
    viewCube.update?.();
    if (fit && currentMesh) fitCamera();
  });
}
window.addEventListener("resize", resize);
window.addEventListener("render3d:viewport-chrome", () => {
  try { resize(); } catch (_) { }
});
resize();

const IMPORT_ACCEPT = /\.(stl|obj|glb|gltf|ply|off|3mf|step|stp|iges|igs|brep|brp|f3z|f3d|sldprt|sldasm|zip)$/i;
const DXF_ACCEPT = /\.dxf$/i;
const REFERENCE_ACCEPT = /\.(pdf|txt|md|markdown|csv|tsv|log|json|jsonc|ya?ml|html?|rtf|docx?|xlsx?|pptx?|png|jpe?g|webp|gif|bmp|svg|tiff?|heic|heif|webm|mp4|mov|m4v|js|mjs|cjs|jsx|ts|tsx|py|css|scss|less|sh|bash|zsh|ino|c|cc|cpp|h|hpp|java|go|rs|rb|php|sql|toml|xml)$/i;

function isViewportImportFile(name = "") {
  return IMPORT_ACCEPT.test(name) || DXF_ACCEPT.test(name) || REFERENCE_ACCEPT.test(name);
}

const viewportDropOverlay = document.getElementById("viewport-drop-overlay");
const viewportImportHud = document.getElementById("viewport-import-hud");
const viewportImportHudText = document.getElementById("viewport-import-hud-text");
const workspaceAppEl = document.getElementById("app");
let viewportImportHudHideTimer = 0;

function setViewportImportHud(state, message) {
  if (!viewportImportHud) return;
  const text = String(message || "").trim();
  if (viewportImportHudText && text) viewportImportHudText.textContent = text;
  viewportImportHud.classList.remove("hidden", "is-loaded", "is-error");
  viewportImportHud.hidden = false;
  viewportImportHud.setAttribute("aria-hidden", "false");
  if (state === "loaded") viewportImportHud.classList.add("is-loaded");
  if (state === "error") viewportImportHud.classList.add("is-error");
  if (viewportImportHudHideTimer) window.clearTimeout(viewportImportHudHideTimer);
  if (state === "loaded" || state === "error") {
    viewportImportHudHideTimer = window.setTimeout(() => {
      viewportImportHud.classList.add("hidden");
      viewportImportHud.hidden = true;
      viewportImportHud.setAttribute("aria-hidden", "true");
    }, state === "error" ? 6000 : 2200);
  }
}

function normalizeDroppedCadFile(file) {
  if (!file) return file;
  if (file.name && isViewportImportFile(file.name)) return file;
  const type = String(file.type || "").toLowerCase();
  if (/step|stp/.test(type) || ((!file.name || !/\./.test(file.name)) && (!type || type === "application/octet-stream"))) {
    const name = file.name && /\./.test(file.name) ? file.name : "dropped-model.step";
    return new File([file], name, { type: file.type || "application/octet-stream" });
  }
  return file;
}

function filesFromDataTransfer(dt) {
  const out = [];
  const seen = new Set();
  const push = (file) => {
    const next = normalizeDroppedCadFile(file);
    if (!next) return;
    const key = `${next.name}|${next.size}|${next.lastModified}`;
    if (seen.has(key)) return;
    seen.add(key);
    out.push(next);
  };
  for (const file of dt?.files || []) push(file);
  if (!out.length) {
    for (const item of dt?.items || []) {
      if (item.kind === "file") push(item.getAsFile?.());
    }
  }
  return out;
}

function isCadFileDrag(e) {
  const types = [...(e.dataTransfer?.types || [])];
  if (!types.includes("Files")) return false;
  const items = [...(e.dataTransfer?.items || [])];
  // During dragover, browsers often omit filenames/MIME — still treat as a CAD drop candidate.
  if (!items.length) return true;
  return items.some((item) => {
    if (item.kind !== "file") return false;
    const file = item.getAsFile?.();
    if (file?.name) return isViewportImportFile(file.name);
    if (!item.type || item.type === "application/octet-stream") return true;
    return /model|mesh|octet|zip|step|stl|gltf|glb|3mf|dxf|sla|wavefront|ply|pdf|text|image|png|jpe?g|webp|gif|bmp|svg|tiff?|heic|heif|html|msword|officedocument/i.test(item.type);
  });
}

function isArchitectModuleDrag(e) {
  return [...(e.dataTransfer?.types || [])].includes("application/render3d-architect-module");
}

function droppedArchitectModuleKind(e) {
  try {
    const raw = e.dataTransfer?.getData("application/render3d-architect-module");
    return raw ? JSON.parse(raw)?.kind || "" : "";
  } catch {
    return "";
  }
}

function viewportGridPointForEvent(e) {
  const rect = renderer.domElement.getBoundingClientRect();
  const ndc = new THREE.Vector2(
    ((e.clientX - rect.left) / Math.max(1, rect.width)) * 2 - 1,
    -((e.clientY - rect.top) / Math.max(1, rect.height)) * 2 + 1,
  );
  const raycaster = new THREE.Raycaster();
  raycaster.setFromCamera(ndc, camera);
  const plane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
  const point = new THREE.Vector3();
  if (!raycaster.ray.intersectPlane(plane, point)) return null;
  const grid = architectGridModelUnits();
  point.x = Math.round(point.x / grid) * grid;
  point.y = Math.round(point.y / grid) * grid;
  point.z = 0;
  return point;
}

function isDesignLikeWorkspaceMode() {
  const mode = workspaceModes?.getMode?.() || "design";
  return mode === "design" || mode === "architect";
}

function clearViewportDropOverlay() {
  viewport.classList.remove("viewport-drag-over");
  workspaceAppEl?.classList.remove("workspace-drag-over");
  viewportDropOverlay?.classList.add("hidden");
}

function showViewportDropOverlay() {
  viewport.classList.add("viewport-drag-over");
  workspaceAppEl?.classList.add("workspace-drag-over");
  viewportDropOverlay?.classList.remove("hidden");
  // Don't keep the bug-report screenshot banner up while importing into the viewport.
  document.getElementById("feedback-page-drop")?.classList.add("hidden");
  document.body.classList.remove("feedback-page-dragging");
}

async function importDroppedCadFiles(files) {
  let prepared;
  try {
    prepared = await convertHeicIngestFiles(files);
  } catch (err) {
    setViewportImportHud("error", err.message || "Could not convert HEIC to PNG.");
    setEditStatus("error", err.message || "Could not convert HEIC to PNG.");
    return;
  }
  const cadFiles = [...(prepared || [])]
    .map((f) => normalizeDroppedCadFile(f))
    .filter((f) => isViewportImportFile(f?.name || "") || isHeicFile(f));
  if (!cadFiles.length) {
    setViewportImportHud("error", "Drop a STEP, STL, GLB, or similar CAD file.");
    setEditStatus("error", "Drop STL, STEP, GLB, 3MF, SolidWorks (.sldprt/.sldasm), Fusion (.f3d/.f3z), DXF, PDF, text, image, or similar files.");
    return;
  }
  const hasCadMesh = cadFiles.some((file) => IMPORT_ACCEPT.test(file.name) && !/\.zip$/i.test(file.name));
  if (!hasCadMesh && looksLikeCodeFileList(cadFiles)) {
    await uploadCodeProjectFiles(cadFiles);
    return;
  }
  // Fast path: drop straight into the open workspace project.
  let choice;
  if (projectId) {
    choice = { destination: "current", projectId };
  } else {
    choice = await askDropDestination(cadFiles);
    if (!choice) return;
  }
  const label = cadFiles.length === 1 ? cadFiles[0].name : `${cadFiles.length} files`;
  setViewportImportHud("uploading", `Uploading ${label}…`);
  setEditStatus("ok", `Importing ${label}…`);
  await uploadProjectFiles(cadFiles, choice);
}

async function importDroppedCodeIfAny(dataTransfer, filesFallback = []) {
  try {
    const list = dataTransfer
      ? await collectDroppedCodeFiles(dataTransfer)
      : [...(filesFallback || [])];
    if (!list.length) return false;
    const hasCadMesh = list.some((file) => IMPORT_ACCEPT.test(file.name) && !/\.zip$/i.test(file.name));
    if (hasCadMesh) return false;
    if (!looksLikeCodeFileList(list) && !list.some((file) => isCodeFilename(file.name))) return false;
    await uploadCodeProjectFiles(list);
    return true;
  } catch {
    return false;
  }
}

// Accept CAD drops anywhere in the workspace (sidebar, viewport, main column).
workspaceAppEl?.addEventListener("dragenter", (e) => {
  if (!isDesignLikeWorkspaceMode() || !isCadFileDrag(e)) return;
  if (isCanvasDesignTabActive() || (isImagineComposeTabActive() && eventHitsPromptPanel(e))) {
    e.preventDefault();
    return;
  }
  e.preventDefault();
  showViewportDropOverlay();
});
workspaceAppEl?.addEventListener("dragover", (e) => {
  if (!isDesignLikeWorkspaceMode() || !isCadFileDrag(e)) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = "copy";
  if (isCanvasDesignTabActive() || (isImagineComposeTabActive() && eventHitsPromptPanel(e))) return;
  showViewportDropOverlay();
});
workspaceAppEl?.addEventListener("dragleave", (e) => {
  if (!workspaceAppEl.contains(e.relatedTarget)) clearViewportDropOverlay();
});
workspaceAppEl?.addEventListener("drop", async (e) => {
  // Architect / Fusion component drops are handled on the viewport below.
  if (isArchitectModuleDrag(e) || isExplorerComponentDrag(e)) return;
  if (!isCadFileDrag(e)) return;
  e.preventDefault();
  e.stopPropagation();
  clearViewportDropOverlay();
  if (!isDesignLikeWorkspaceMode()) return;
  try {
    const dropped = filesFromDataTransfer(e.dataTransfer);
    const images = dropped.filter((f) => (
      String(f?.type || "").startsWith("image/")
      || isHeicFile(f)
      || /\.(png|jpe?g|webp|gif|bmp|svg|tiff?|heic|heif)$/i.test(f?.name || "")
    ));
    if (isCanvasDesignTabActive() && images.length) {
      const pos = canvasModeInstance?.pointFromClient?.(e.clientX, e.clientY)
        || { clientX: e.clientX, clientY: e.clientY };
      await handleCanvasImageDrop(images, pos);
      return;
    }
    if (isImagineComposeTabActive() && !eventHitsClipEditor(e) && !eventHitsOpenRefViewer(e)) {
      const refs = dropped.filter((f) => isImagineReferenceFile(f));
      const cad = dropped.filter((f) => IMPORT_ACCEPT.test(f?.name || "") || DXF_ACCEPT.test(f?.name || ""));
      if (refs.length) {
        await imagineUi?.attachDroppedFiles?.(refs);
        showImaginePanel({ focus: false });
        if (!cad.length) return;
        await importDroppedCadFiles(cad);
        return;
      }
    }
    if (await importDroppedCodeIfAny(e.dataTransfer, dropped)) return;
    await importDroppedCadFiles(dropped);
  } catch (err) {
    setViewportImportHud("error", err.message || "Upload failed");
    setEditStatus("error", err.message || "Upload failed");
    alert(err.message || "Upload failed");
  }
});

viewport.addEventListener("dragover", (e) => {
  if (!isDesignLikeWorkspaceMode()) return;
  if (!isCadFileDrag(e) && !isExplorerComponentDrag(e) && !isArchitectModuleDrag(e)) return;
  e.preventDefault();
  e.dataTransfer.dropEffect = "copy";
});
viewport.addEventListener("drop", async (e) => {
  if (isArchitectModuleDrag(e)) {
    e.preventDefault();
    e.stopPropagation();
    clearViewportDropOverlay();
    if (!isDesignLikeWorkspaceMode()) return;
    const kind = droppedArchitectModuleKind(e) || "wall";
    const obj = placeArchitectModuleInstant(kind);
    const point = viewportGridPointForEvent(e);
    if (obj && point) {
      obj.position.copy(point);
      showObjectGizmo(obj, "translate", { switchTab: false });
      setEditStatus("ok", `Dropped ${kind} on the grid. Drag or Snap Grid to lock it into place.`);
    }
    closeArchitectLibrary();
    return;
  }
  if (isExplorerComponentDrag(e)) {
    e.preventDefault();
    e.stopPropagation();
    clearViewportDropOverlay();
    if (!isDesignLikeWorkspaceMode()) return;
    const payload = droppedExplorerRefs(e)[0];
    if (!payload?.projectId || !payload?.filename) {
      setEditStatus("error", "This Fusion item is only a reference right now; sync/import it before dropping into the viewport.");
      return;
    }
    try {
      await openProjectById(payload.projectId);
      const beforeDropState = captureViewportAssemblyState();
      const selectedBeforeDrop = selectedObjectFilename();
      const data = await api(`/api/projects/${encodeURIComponent(payload.projectId)}`);
      const browserComponents = normalizeBrowser(data).components || [];
      const compCandidates = [
        ...browserComponents,
        ...browserComponents.flatMap((entry) => entry.children || []),
      ];
      const comp = compCandidates.find((entry) =>
        entry.name === payload.filename || entry.viewer_filename === payload.filename || entry.filename === payload.filename
      );
      if (comp) {
        await openBrowserComponent(comp);
        for (const topLevel of browserComponents) {
          if (topLevel.name !== comp.name) setAssemblyComponentVisible(topLevel, false);
        }
        setAssemblyComponentVisible(comp, true);
        selectAssemblyComponent(comp.name, { fitView: true });
        pushViewportUndoAction({
          type: "fusion-component-drop",
          before: beforeDropState,
          selectedBefore: selectedBeforeDrop,
          label: comp.name || payload.name || payload.filename,
        });
      }
    } catch (err) {
      setEditStatus("error", err.message || "Could not open dropped Fusion component.");
    }
    return;
  }
  if (!isCadFileDrag(e) && !filesFromDataTransfer(e.dataTransfer).length) return;
  e.preventDefault();
  e.stopPropagation();
  clearViewportDropOverlay();
  if (!isDesignLikeWorkspaceMode()) return;
  try {
    const dropped = filesFromDataTransfer(e.dataTransfer);
    if (await routeDroppedFilesToImagine(dropped, e)) {
      const cad = dropped.filter((f) => IMPORT_ACCEPT.test(f?.name || "") || DXF_ACCEPT.test(f?.name || ""));
      if (!cad.length) return;
      await importDroppedCadFiles(cad);
      return;
    }
    if (await importDroppedCodeIfAny(e.dataTransfer, dropped)) return;
    await importDroppedCadFiles(dropped);
  } catch (err) {
    setViewportImportHud("error", err.message || "Upload failed");
    setEditStatus("error", err.message || "Upload failed");
  }
});

function isOsFileDrag(e) {
  const types = e?.dataTransfer?.types;
  if (!types) return false;
  try {
    if (typeof types.includes === "function" && types.includes("Files")) return true;
    if (typeof types.contains === "function" && types.contains("Files")) return true;
  } catch (_) { /* DOMStringList */ }
  return isCadFileDrag(e);
}

window.addEventListener("dragover", (e) => {
  // Prevent the browser from navigating away when any OS file (audio/video/CAD) is dragged.
  if (isOsFileDrag(e)) e.preventDefault();
}, true);
window.addEventListener("drop", (e) => {
  if (isOsFileDrag(e) || isCadFileDrag(e)) e.preventDefault();
  clearViewportDropOverlay();
}, true);
window.addEventListener("dragend", clearViewportDropOverlay, true);
window.addEventListener("blur", clearViewportDropOverlay);
document.addEventListener("dragleave", (e) => {
  if (!e.relatedTarget && (e.clientX <= 0 || e.clientY <= 0 || e.clientX >= window.innerWidth || e.clientY >= window.innerHeight)) {
    clearViewportDropOverlay();
  }
}, true);

let promptTargetPreview = null;
let promptTargetSearch = "";
let promptTargetSelectedBody = null;
const promptTargetBodyCache = new Map();
/** filename -> collapsed override in Edit selected picker */
const promptTargetBodyListCollapsed = new Map();

const _clipSizeScratch = new THREE.Vector3();
const _clipViewDir = new THREE.Vector3();
const _clipCorner = new THREE.Vector3();
let _cadOrbitLiteOn = false;
let _lastClipOrbitMs = 0;
const desktopFrameBudget = createFrameBudget(30);

function animate() {
  const now = performance.now();
  const xrOn = Boolean(renderer?.xr?.isPresenting || viewportXR?.isPresenting?.());
  const viewportHidden = viewport?.hidden
    || viewport?.classList?.contains("hidden")
    || viewport?.classList?.contains("doc-viewer-active")
    || viewport?.classList?.contains("dxf-viewer-active")
    || viewport?.classList?.contains("ref-viewer-active");
  if (!shouldRenderViewportFrame({ presenting: xrOn, documentHidden: document.hidden, viewportHidden })) {
    meshAnimLastFrame = now;
    desktopFrameBudget.reset();
    return;
  }
  if (!xrOn && !desktopFrameBudget.shouldRun(now)) return;
  if (xrOn) desktopFrameBudget.reset();
  if (shouldParkDesktopViewportForCanvasTab({
    presenting: xrOn,
    canvasTabActive: isCanvasDesignTabActive(),
    canvasSplit: isCanvasSplitActive(),
  })) {
    meshAnimLastFrame = now;
    return;
  }
  const dt = Math.min(0.05, Math.max(0, (now - meshAnimLastFrame) / 1000));
  meshAnimLastFrame = now;
  try {
    if (!xrOn) meshAnimationRuntime?.update?.(dt);
  } catch {
    /* animation optional */
  }
  const orbitBusy = !xrOn && !!trackballPointerSafety?.isBusy?.();
  if (orbitBusy !== _cadOrbitLiteOn) {
    _cadOrbitLiteOn = orbitBusy;
    try { setCadOrbitLite(orbitBusy, { renderer }); } catch (_) { }
  }
  if (!xrOn) {
    // Leftover Change scene / generate wrap must not stay as IBL or skybox on CAD orbit.
    if (scene.environment) scene.environment = null;
    if (scene.fog) scene.fog = null;
    if (
      scene.background
      && !scene.background.isColor
      && scene.background.mapping === THREE.EquirectangularReflectionMapping
    ) {
      try { applyViewportSceneBackground(); } catch (_) { }
      if (
        scene.background
        && !scene.background.isColor
        && scene.background.mapping === THREE.EquirectangularReflectionMapping
      ) {
        scene.background = new THREE.Color(currentThemeSceneColors().canvas);
      }
    }
  }
  try { if (!xrOn) syncCadEdgeResolution(renderer); } catch (_) { }
  if (!xrOn) {
    controls.update();
  } else {
    try {
      viewportXR.update();
    } catch (err) {
      console.warn("[xr] frame update", err);
    }
  }
  if (!xrOn) {
    architectSession?.frame?.();
    if (promptTargetPreview?.active) {
      promptTargetPreview.angle += 0.008;
      const center = promptTargetPreview.center;
      const dist = promptTargetPreview.radius;
      camera.position.set(
        center.x + Math.cos(promptTargetPreview.angle) * dist,
        center.y + Math.sin(promptTargetPreview.angle) * dist,
        center.z + dist * 0.42
      );
      controls.target.copy(center);
      camera.lookAt(center);
      controls._eye?.subVectors(camera.position, controls.target);
    } else if (explodedOrbit && orbitShouldRun() && !explodedOrbit.paused) {
      explodedOrbit.angle += 0.006;
      applyExplodedOrbitCamera();
    }

    // Dynamically adjust clip planes so zooming in/out never slices the mesh.
    // Near tracks the gap to the model (not a raw fraction of orbit distance), and
    // far always covers the model + floor grid even when tightly framed.
    // Rotate-only: throttle — AABB depths barely change vs fill cost of projection updates.
    if (!orbitBusy || now - _lastClipOrbitMs > 90) {
      updateCameraClipPlanes();
      _lastClipOrbitMs = now;
    }
  }

  // WebXR requires the default app camera — a sketch/ortho camera draws nothing in headset.
  const renderCam = xrOn ? camera : (sketchEditor.getRenderCamera?.() || camera);
  // Spectator overlay must run BEFORE the XR submit. Painting after render()
  // leaves the Quest framebuffer on a 720p target and the next headset frame
  // shows no CAD and a broken controller dock.
  if (xrOn) {
    try { viewportVideoRecorder?.onXrFrame?.(); } catch (_) { }
  }
  try { if (!xrOn) measureLabelOverlay?.update?.(); } catch (_) { }
  try { renderer.render(scene, renderCam); } catch (_) { }
  if (!xrOn) {
    try { viewCube.update(); } catch (_) { }
    try { collab?.renderLabels(renderCam); } catch (_) { }
  }
}
// GPU WebGLRenderer already implements setAnimationLoop (WebXR). Never wrap it
// with bindFallbackAnimationLoop — that would steal XR frames.
startRendererAnimationLoop(renderer, animate);
try { fitCamera(); } catch (_) { }

function expandClipBoundsForLiveTransform(bounds, contentRadius) {
  const target = transformControls?.object;
  if (!target) return { bounds, contentRadius };
  try {
    target.updateMatrixWorld(true);
    const extra = new THREE.Box3().setFromObject(target);
    if (extra.isEmpty()) return { bounds, contentRadius };
    const span = extra.getSize(new THREE.Vector3()).length();
    extra.expandByScalar(Math.max(span * 0.5, contentRadius * 0.25, 0.05));
    const next = bounds && !bounds.isEmpty() ? bounds.clone().union(extra) : extra;
    return { bounds: next, contentRadius: Math.max(contentRadius, span * 0.5, 0.05) };
  } catch {
    return { bounds, contentRadius };
  }
}

function updateCameraClipPlanes() {
  const orbitDist = camera.position.distanceTo(controls.target);
  if (!(orbitDist > 0) || !Number.isFinite(orbitDist)) return;

  const architectActive = !!(architectControlsActive || architectSession?.isActive?.());
  const transforming = !!transformGizmoDragging;
  let bounds = null;
  let contentRadius = 1;
  if (architectActive) {
    bounds = architectSession?.getWorldBounds?.() || null;
    contentRadius = Math.max(
      Number(architectSession?.getContentRadius?.()) || 0,
      Number(architectBayGrid?.getPlanExtent?.()) || 0,
      12,
    );
    if (bounds && !bounds.isEmpty()) {
      contentRadius = Math.max(contentRadius, bounds.getSize(new THREE.Vector3()).length() * 0.5);
    } else {
      // Empty plan: still cover the bay field so the lattice isn't frustum-clipped.
      const extent = contentRadius;
      bounds = new THREE.Box3(
        new THREE.Vector3(-extent, -extent, -1),
        new THREE.Vector3(extent, extent, Math.max(extent * 0.35, 8)),
      );
    }
  } else {
    bounds = sceneBounds();
    contentRadius = Math.max(
      bounds && !bounds.isEmpty() ? bounds.getSize(_clipSizeScratch).length() * 0.5 : 1,
      0.05,
    );
  }
  ({ bounds, contentRadius } = expandClipBoundsForLiveTransform(bounds, contentRadius));

  // Hidden 25k-unit floor (grid-off) used to explode `far` and push `near`
  // through a tight cadframe1 shot — CAD vanished into empty grey.
  const useFloorClip = !!gridVisible && !hideGridForRecording && !isImmersiveXrActive();
  const gridExtent = useFloorClip
    ? floorClipHalfExtent(
      floorGridWorldSize,
      Math.max(contentRadius, visibleFloorGridRadius()),
    )
    : Math.max(contentRadius * 4, 8);
  const sceneExtent = Math.max(contentRadius, gridExtent, 1);
  // Include the design floor so delete/move cannot push `near` through the grid
  // and cut it into a trapezoid island.
  const floorHalf = useFloorClip
    ? Math.min(
      Math.max(gridExtent, (floorGridWorldSize || 0) * 0.5, 8),
      Math.max(contentRadius * 80, orbitDist * 30, 128),
    )
    : Math.max(contentRadius * 2, 8);
  const floorBox = new THREE.Box3(
    new THREE.Vector3(-floorHalf, -floorHalf, -0.08),
    new THREE.Vector3(floorHalf, floorHalf, 0.08),
  );
  if (!bounds || bounds.isEmpty()) bounds = floorBox;
  else bounds = bounds.clone().union(floorBox);
  const viewDir = camera.getWorldDirection(_clipViewDir).normalize();
  let minDepth = Infinity;
  let maxDepth = -Infinity;
  if (bounds && !bounds.isEmpty()) {
    for (const x of [bounds.min.x, bounds.max.x]) {
      for (const y of [bounds.min.y, bounds.max.y]) {
        for (const z of [bounds.min.z, bounds.max.z]) {
          const depth = _clipCorner.set(x, y, z).sub(camera.position).dot(viewDir);
          minDepth = Math.min(minDepth, depth);
          maxDepth = Math.max(maxDepth, depth);
        }
      }
    }
  }

  const margin = Math.max(contentRadius * 0.1, 0.002);
  // Keep near close, but not so close that a zoomed-out far plane destroys depth precision.
  let near = Math.max(Math.min(orbitDist * 0.0005, sceneExtent * 0.01), 0.0005);
  if (Number.isFinite(minDepth) && minDepth > 1e-4) {
    if (minDepth > margin * 1.5) {
      near = Math.min(Math.max(near, minDepth * 0.02), minDepth * 0.25);
    } else {
      near = Math.min(near, minDepth * 0.35);
    }
  } else {
    // Camera is inside/near the bounds (tight zoom or huge part) — keep near tiny.
    near = Math.min(near, Math.max(orbitDist * 0.00005, 0.00005));
  }

  // Keep the XY design floor in front of the camera (iPhone has no log-depth).
  try {
    const viewZ = viewDir.z;
    if (Math.abs(viewZ) > 1e-4) {
      const tFloor = -camera.position.z / viewZ;
      if (tFloor > 0) near = Math.min(near, tFloor * 0.35);
    }
    near = Math.min(near, Math.max(Math.abs(camera.position.z) * 0.2, 0.001));
  } catch (_) { }

  // Far must enclose visible content, but should not explode with zoom distance.
  let far = Math.max(
    Number.isFinite(maxDepth) ? maxDepth + margin * 8 : 0,
    orbitDist + sceneExtent * 8,
    sceneExtent * 24,
    100,
  );

  // Log depth already handles huge ratios. Without it, never push near through
  // the closest geometry — that slices large CAD (FreeCAD keeps the solid visible).
  const logDepth = !!renderer?.capabilities?.logarithmicDepthBuffer;
  const maxRatio = architectActive ? 1e6 : (logDepth ? 1e7 : 2e5);
  if (!transforming && far / Math.max(near, 1e-8) > maxRatio) {
    const cappedNear = far / maxRatio;
    if (Number.isFinite(minDepth) && minDepth > 1e-4) {
      near = Math.min(Math.max(near, cappedNear), Math.max(minDepth * 0.35, 0.0005));
    } else {
      near = Math.min(near, Math.max(orbitDist * 0.00005, 0.00005));
    }
  }

  // Architect walls sit on the plan — never let a CAD-inflated near plane slice them.
  if (architectActive) {
    near = Math.min(near, Math.max(orbitDist * 0.0002, 0.01));
  }

  // Ratio cap can push near through the floor. Keep the ground in front of the camera.
  try {
    near = Math.min(near, Math.max(Math.abs(camera.position.z) * 0.2, 0.001));
    if (Math.abs(viewDir.z) > 1e-4) {
      const tFloor = -camera.position.z / viewDir.z;
      if (tFloor > 0) near = Math.min(near, tFloor * 0.35);
    }
  } catch (_) { }

  if (transforming) {
    // Only grow the frustum mid-drag. Tightening near/far every frame makes the
    // background pop and clips the moving solid as it crosses last frame's plane.
    if (Number.isFinite(minDepth) && minDepth > 1e-6) {
      near = Math.min(near, Math.max(minDepth * 0.2, 0.0005));
    }
    near = Math.min(near, camera.near || near);
    far = Math.max(far, camera.far || far);
    if (
      near < camera.near * 0.97
      || far > camera.far * 1.03
    ) {
      camera.near = near;
      camera.far = far;
      camera.updateProjectionMatrix();
    }
    return;
  }

  if (
    Math.abs(camera.near - near) > Math.max(near * 0.08, 1e-7)
    || Math.abs(camera.far - far) > Math.max(far * 0.08, 0.5)
  ) {
    camera.near = near;
    camera.far = far;
    camera.updateProjectionMatrix();
  }
  try {
    const el = renderer.domElement;
    if (el?.dataset) {
      el.dataset.camNear = String(camera.near);
      el.dataset.camFar = String(camera.far);
      el.dataset.clipN = String((renderer.clippingPlanes || []).length);
      el.dataset.localClip = renderer.localClippingEnabled ? "1" : "0";
    }
  } catch (_) { }
}

function clearModelContents() {
  cancelLasso();
  directModeling.reset();
  transparentObjects.clear();
  if (transparentPickEnabled) setTransparentPickEnabled(false);
  const xrLive = !!viewportXR?.isPresenting?.();
  try {
    if (xrLive) {
      // Hide + unlock — do NOT GPU-dispose mid-session (hard-crashes Quest).
      viewportXR.beginProjectSwap?.();
      viewportXR.invalidateSavedDesktop?.();
    }
  } catch (_) { }
  try { stopExplodedOrbit(); } catch (_) { }
  explodedViewEnabled = false;
  explodedSwapByAssembled.clear();
  try { clearProceduralExplode(); } catch (_) { }
  try { syncExplodedModeUi(); } catch (_) { }
  try { urdfRobotRuntime?.clear?.(); } catch (_) { }
  try { setCadAssemblyHiddenForUrdf(false); } catch (_) { }
  try { wiringSpatial?.clear?.(); } catch (_) { }
  try { createSolidPreviewTool?.stop?.(); } catch (_) { }
  projectAssembly.clear({ soft: xrLive });
  viewportMeshProjectId = null;
  disposeLiveGenerationPreview({ soft: xrLive });
  sketchEditor.clearViewportSketches?.();
  currentMesh = null;
  transformControls.detach();
  gizmoPanel.hide();
  objectTools?.clearSelection?.();
  clearHover();
  if (!xrLive) {
    try { projectAssembly.flushDeferredDispose?.(); } catch (_) { }
    rebuildGrid();
  }
}

function clearModel() {
  loadModelGeneration += 1;
  clearModelContents();
}

function resetComposerForProject() {
  // UI-only clear. Do NOT persist here — loadProject / showEmptyProjectViewport
  // call this before restore, and saving "" would wipe the draft across refresh.
  restoringModelPromptState = true;
  composer.setPromptText?.("");
  composer.replaceReferences([]);
  resetRefCounter();
  restoringModelPromptState = false;
  promptImages = [];
  renderPromptImages();
  sendCollabPresence();
}

/** Switch the UI to a blank project immediately; server create can finish after. */
function beginBlankNewProject() {
  newProjectPending = true;
  loadProjectGeneration += 1;
  // Session-global gridVisible used to stay true after the last project.
  // New Project uses the studio pref (default off) and does not persist onto the outgoing id.
  setGridVisible(readNewProjectGridVisible(), { persist: false });
  applySavedViewportLook({ persist: false });
  setSpiceEnabled(DEFAULT_SPICE_ENABLED, { persist: false });
  setCadDebugEnabled(DEFAULT_CAD_DEBUG_ENABLED, { persist: false });
  setMcMasterPartsEnabled(DEFAULT_MCMASTER_PARTS_ENABLED, { persist: false });
  microEditTools?.setEnabled?.(DEFAULT_MICRO_EDITS_ENABLED, { persist: false });
  showEmptyProjectViewport({ keepPrompt: false });
  lastProjectFiles = [];
  lastProjectBrowser = emptyProjectBrowser();
  latestElectronicsBundle = null;
  try { projectTree?.render?.(lastProjectBrowser); } catch (_) { /* tree optional */ }
  try { resetWiringLinkedState({ clearPrompt: true }); } catch (_) { /* wiring chrome optional */ }
  try { ribbon?.reset?.(); } catch (_) { }
  // Every new project starts in the CAD workspace with VibeCAD selected.
  // Existing projects and deliberate engine changes are otherwise untouched.
  setPromptCadEngine(DEFAULT_CAD_ENGINE);
  applyPromptModeUI(DEFAULT_PROMPT_MODE);
  setProjectHeader("New project", null);
  setEditStatus("ok", "New project");
  renderProjectList();
}

function showEmptyProjectViewport({ keepBrowser = false, keepModel = false, keepPrompt = true } = {}) {
  selectedFile = null;
  if (!keepModel) {
    try { clearModel(); } catch (_) { }
  }
  if (!keepPrompt) {
    try { resetComposerForProject(); } catch (_) { }
  }
  const list = document.getElementById("file-list");
  if (list) list.innerHTML = "";
  if (!keepBrowser) {
    try {
      projectTree?.render?.({ components: [], sketches: [], wiring: [], drawings: [], references: [], renders: [] });
    } catch (_) { }
  }
  try { timeline?.setTimeline?.({ entries: [], current_index: -1 }); } catch (_) { }
  try { objectHistory?.render?.([]); } catch (_) { }
  try { promptHistory?.render?.([]); } catch (_) { }
  try { promptHistory?.setCountBadge?.(0); } catch (_) { }
  // keepModel: leave the outgoing mesh + camera until the new GLB paints.
  // Resetting the orbit target here framed empty space and looked like a failed load.
  if (!keepModel) {
    try { controls.target.set(0, 0, 0); } catch (_) { }
    const xrLiveOpen = !!(viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting);
    if (!xrLiveOpen) {
      try { fitCamera(); } catch (_) { }
    }
  }
  try { resize(); } catch (_) { }
}

function prepareViewportForModels() {
  if (sketchEditor.isActive?.()) sketchEditor.cancel();
  setSketchModelDim(false);
  document.getElementById("app")?.classList.remove("sketch-editing");
  updateSketchChrome({ visible: false });
  controls.enabled = true;
}

function fileStem(name) {
  return String(name || "").replace(/\.[^.]+$/, "");
}

function isMcMasterPartStem(stem = "") {
  let value = String(stem || "").split(/[/\\]/).pop().trim();
  value = value.replace(/\.(step|stp|glb|gltf)$/i, "").replace(/_edited(?:_\d+)?$/i, "");
  if (/^[0-9]{3,6}[A-Za-z][0-9A-Za-z]{1,8}$/.test(value)) return true;
  const compact = value.replace(/[^0-9A-Za-z]/g, "").toUpperCase();
  return /^[0-9]{3,6}[A-Z][0-9A-Z]{1,8}$/.test(compact);
}

function isCatalogHardwareComponent(entry) {
  if (entry?.catalog_hardware === true) return true;
  const names = [
    entry?.stem,
    entry?.name,
    entry?.viewer_filename,
    entry?.uploaded_filename,
  ].filter(Boolean);
  if (!names.length && typeof entry === "string") names.push(entry);
  return names.some((name) => isMcMasterPartStem(fileStem(name)) || isMcMasterPartStem(name));
}

function isCatalogHardwareViewportEvent(msg = {}) {
  const action = String(msg.action || msg.kind || "").toLowerCase();
  if (action === "mcmaster.fetch" || action === "mcmaster_fetch" || action === "hardware.insert") {
    return true;
  }
  return isCatalogHardwareComponent({
    name: msg.filename,
    viewer_filename: msg.filename,
    uploaded_filename: msg.uploaded_filename,
    catalog_hardware: msg.catalog_hardware,
  });
}

let objectIterationPopover = null;
let electronicsPopover = null;

const ELECTRONICS_TYPE_LABELS = {
  "raspberry-pi": "Raspberry Pi",
  "arduino-uno": "Arduino Uno",
  "arduino-mega": "Arduino Mega",
  "servo-motor": "Servo motor",
  stepper: "Stepper motor",
  "motor-driver": "Motor driver",
  motor: "DC motor",
  led: "LED",
  resistor: "Resistor",
  transistor: "Transistor",
  diode: "Diode",
  button: "Push button",
  sensor: "Sensor",
  breadboard: "Breadboard",
};

function electronicsTypeLabel(type) {
  const key = String(type || "").toLowerCase();
  return ELECTRONICS_TYPE_LABELS[key] || prettyPartLabel(key) || key || "Part";
}

function electronicsTypeColor(type) {
  const key = String(type || "").toLowerCase();
  const colors = {
    "raspberry-pi": "#c51a4a",
    "arduino-uno": "#00979d",
    "arduino-mega": "#008184",
    "servo-motor": "#3fb950",
    stepper: "#6e7681",
    "motor-driver": "#58a6ff",
    motor: "#2ea043",
    led: "#e3b341",
    resistor: "#d4a574",
    transistor: "#8b949e",
    diode: "#484f58",
    button: "#8b949e",
    sensor: "#58a6ff",
    breadboard: "#c9d1d9",
  };
  return colors[key] || "#58a6ff";
}

async function loadElectronicsSchematicComponents(signal) {
  const fromSim = wiringSim?.getSchematic?.()?.components;
  if (Array.isArray(fromSim) && fromSim.length) return fromSim;
  const fromState = wiringSim?.getState?.()?.components;
  if (Array.isArray(fromState) && fromState.length) return fromState;
  const cached = getWiringPrefetch()?.data?.components;
  if (Array.isArray(cached) && cached.length) return cached;
  if (!projectId) return [];
  try {
    prefetchWiringForProject(projectId);
    const prefetch = getWiringPrefetch();
    const data = prefetch?.data
      || (prefetch?.promise ? await prefetch.promise : null)
      || await api(`/api/projects/${encodeURIComponent(projectId)}/wiring`, signal ? { signal } : undefined);
    return Array.isArray(data?.components) ? data.components : [];
  } catch (err) {
    if (signal?.aborted || err?.name === "AbortError") throw err;
    return [];
  }
}

async function collectElectronicsUsed(signal) {
  const wiringComponents = await loadElectronicsSchematicComponents(signal);
  const wiringItems = [];
  const byKey = new Map();
  for (const comp of wiringComponents) {
    const type = String(comp?.type || "part");
    const label = String(comp?.label || electronicsTypeLabel(type)).trim() || electronicsTypeLabel(type);
    const key = `wiring:${type}:${label.toLowerCase()}`;
    const existing = byKey.get(key);
    if (existing) {
      existing.count += 1;
      continue;
    }
    const item = {
      id: key,
      source: "wiring",
      type,
      label,
      kind: electronicsTypeLabel(type),
      color: comp?.color || electronicsTypeColor(type),
      count: 1,
      componentId: comp?.id || null,
      filename: comp?.sourceFile || comp?.filename || null,
    };
    byKey.set(key, item);
    wiringItems.push(item);
  }

  const cadItems = [];
  const seenCad = new Set();
  for (const entry of lastProjectBrowser?.components || []) {
    const name = entry?.name || entry?.filename || entry?.viewer_filename || "";
    if (!name || seenCad.has(name)) continue;
    const recognized = recognizePart(name);
    if (!recognized) continue;
    seenCad.add(name);
    cadItems.push({
      id: `cad:${name}`,
      source: "cad",
      type: recognized.wiringType,
      label: recognized.label || prettyPartLabel(name),
      kind: recognized.kind,
      color: electronicsTypeColor(recognized.wiringType),
      count: 1,
      componentId: null,
      filename: name,
      datasheet: recognized.datasheet || "",
    });
  }

  let parts = [];
  if (projectId) {
    try {
      const workspace = await api(`/api/design-assist/projects/${encodeURIComponent(projectId)}/parts`, signal ? { signal } : undefined);
      parts = (workspace.parts || []).filter(part => part.category === "electronics");
    } catch (_) { /* Existing schematic remains usable during a parts-list fetch failure. */ }
  }
  return {
    parts,
    wiring: wiringItems,
    cad: cadItems,
    total: wiringItems.reduce((n, i) => n + i.count, 0) + cadItems.length,
    suggestions: suggestElectronicsForBuild({ wiring: wiringItems, cad: cadItems }),
  };
}

function electronicsSuggestionCardsHtml(suggestions = []) {
  if (!suggestions.length) return "";
  return `
    <div class="object-iteration-history-head">Suggested for this build · ${suggestions.length}</div>
    ${suggestions.map((item, idx) => `
      <div class="object-iteration-node electronics-suggest-node" data-electronics-suggest-id="${appEscapeHtml(item.id)}" data-suggest-kind="${appEscapeHtml(item.kind || "")}" data-suggest-type="${appEscapeHtml(item.type || "")}" data-suggest-file="${appEscapeHtml(item.filename || "")}">
        <span class="object-iteration-rail" aria-hidden="true"></span>
        <div class="object-iteration-card">
          <div class="object-iteration-main">
            <span class="electronics-item-swatch" style="background:${appEscapeHtml(item.color || "#58a6ff")}"></span>
            <span class="object-iteration-badge">S${idx + 1}</span>
            <span class="object-iteration-title">${appEscapeHtml(item.label)}</span>
            ${item.qty > 1 ? `<span class="electronics-item-count">×${item.qty}</span>` : ""}
          </div>
          <div class="object-iteration-meta">${appEscapeHtml(item.reason || "")}</div>
          <span class="electronics-source-pill electronics-source-pill--suggest">Suggested</span>
          <div class="electronics-suggest-actions">
            ${item.kind !== "send-all-cad" ? `<button type="button" class="btn accent btn-compact" data-suggest-action="wiring">Add to wiring</button>` : `<button type="button" class="btn accent btn-compact" data-suggest-action="wiring-all">Send CAD to wiring</button>`}
            ${item.docs?.length ? `<button type="button" class="btn secondary btn-compact" data-suggest-action="docs">Source docs</button>` : ""}
            ${item.docs?.length ? `<button type="button" class="btn secondary btn-compact" data-suggest-action="reference">Save to references</button>` : ""}
          </div>
        </div>
      </div>
    `).join("")}
  `;
}

function electronicsUsedListHtml(data, { emptyHint = null } = {}) {
  const parts = data?.parts || [];
  const wiring = data?.wiring || [];
  const cad = data?.cad || [];
  const suggestions = data?.suggestions || [];
  if (!parts.length && !wiring.length && !cad.length && !suggestions.length) {
    return `<div class="object-iteration-empty">${appEscapeHtml(emptyHint || "No electronics used yet. Generate a wiring schematic or import electronic CAD parts.")}</div>`;
  }
  const sections = [];
  if (parts.length) sections.push(`<div class="object-iteration-history-head">Parts List · Electronics (${parts.length})</div>` + parts.map(part => `<div class="object-iteration-node"><strong>${appEscapeHtml(part.name)} ×${Number(part.qty) || 1}</strong><div class="electronics-suggest-actions"><a href="${appEscapeHtml(part.url)}" target="_blank" rel="noopener noreferrer">Product ↗</a>${(part.docs || []).map(doc => `<a href="${appEscapeHtml(doc.url)}" target="_blank" rel="noopener noreferrer">${appEscapeHtml(doc.label || "Pinout / wiring docs")} ↗</a>`).join("")}</div></div>`).join(""));
  if (suggestions.length) sections.push(electronicsSuggestionCardsHtml(suggestions));
  if (wiring.length) {
    sections.push(`<div class="object-iteration-history-head">Wiring schematic · ${wiring.reduce((n, i) => n + i.count, 0)}</div>`);
    sections.push(wiring.map((item, idx) => `
      <div class="object-iteration-node" data-electronics-id="${appEscapeHtml(item.id)}" data-electronics-source="wiring" data-component-id="${appEscapeHtml(item.componentId || "")}">
        <span class="object-iteration-rail" aria-hidden="true"></span>
        <div class="object-iteration-card">
          <div class="object-iteration-main">
            <span class="electronics-item-swatch" style="background:${appEscapeHtml(item.color)}"></span>
            <span class="object-iteration-badge">#${idx + 1}</span>
            <span class="object-iteration-title">${appEscapeHtml(item.label)}</span>
            ${item.count > 1 ? `<span class="electronics-item-count">×${item.count}</span>` : ""}
          </div>
          <div class="object-iteration-meta">${appEscapeHtml(item.kind)}${item.filename ? ` · ${appEscapeHtml(fileStem(item.filename))}` : ""}</div>
          <span class="electronics-source-pill electronics-source-pill--wiring">Wiring</span>
          <div class="electronics-suggest-actions">
            <button type="button" class="btn secondary btn-compact" data-used-action="docs" data-docs-query="${appEscapeHtml(item.datasheet || item.label)}">Source docs</button>
          </div>
        </div>
      </div>
    `).join(""));
  }
  if (cad.length) {
    sections.push(`<div class="object-iteration-history-head">CAD electronics · ${cad.length}</div>`);
    sections.push(cad.map((item, idx) => `
      <div class="object-iteration-node" data-electronics-id="${appEscapeHtml(item.id)}" data-electronics-source="cad" data-electronics-file="${appEscapeHtml(item.filename || "")}">
        <span class="object-iteration-rail" aria-hidden="true"></span>
        <div class="object-iteration-card">
          <div class="object-iteration-main">
            <span class="electronics-item-swatch" style="background:${appEscapeHtml(item.color)}"></span>
            <span class="object-iteration-badge">#${idx + 1}</span>
            <span class="object-iteration-title">${appEscapeHtml(item.label)}</span>
          </div>
          <div class="object-iteration-meta">${appEscapeHtml(item.kind)}${item.filename ? ` · ${appEscapeHtml(fileStem(item.filename))}` : ""}</div>
          <span class="electronics-source-pill electronics-source-pill--cad">CAD</span>
          <div class="electronics-suggest-actions">
            <button type="button" class="btn accent btn-compact" data-used-action="wiring-cad">Add to wiring</button>
            <button type="button" class="btn secondary btn-compact" data-used-action="docs" data-docs-query="${appEscapeHtml(item.datasheet || item.label)}">Source docs</button>
            <button type="button" class="btn secondary btn-compact" data-used-action="reference" data-docs-query="${appEscapeHtml(item.datasheet || item.label)}" data-docs-label="${appEscapeHtml(item.label)}">Save docs</button>
          </div>
        </div>
      </div>
    `).join(""));
  }
  return sections.join("");
}

let latestElectronicsBundle = null;
let electronicsSuggestDismissedFor = null;
/** Product/schematic URLs auto-seeded for Wiring AI driver_links. */
let pendingWiringElectronicsLinks = [];
let electronicsSourcingSeededKey = null;

const LS_ELECTRONICS_DOCK_SHOWN = "render3d:electronicsSuggestDockShown:v1";

function collectElectronicsSourcingUrls(bundle = latestElectronicsBundle) {
  const urls = [];
  const seen = new Set();
  const pushAll = (item) => {
    for (const entry of electronicsSourcingUrls(item || {})) {
      if (!entry.url || seen.has(entry.url)) continue;
      seen.add(entry.url);
      urls.push(entry);
    }
  };
  for (const s of bundle?.suggestions || []) {
    if (s.kind === "send-all-cad") continue;
    pushAll(s);
  }
  for (const item of [...(bundle?.used?.cad || []), ...(bundle?.used?.wiring || [])]) {
    pushAll(item);
  }
  return urls;
}

function electronicsSourcingPromptBlock(bundle = latestElectronicsBundle) {
  if (!bundle) return "";
  const lines = [];
  for (const s of (bundle.suggestions || []).slice(0, 8)) {
    if (s.kind === "send-all-cad") continue;
    const src = electronicsSourcingUrls(s)[0];
    const urlBit = src?.url ? ` — ${src.url}` : "";
    const searchBit = s.search ? ` (search: ${s.search})` : "";
    lines.push(`- ${s.label}: ${s.reason || "recommended for this build"}${urlBit}${searchBit}`);
  }
  for (const item of (bundle.used?.cad || []).slice(0, 6)) {
    const src = electronicsSourcingUrls(item)[0];
    lines.push(
      `- CAD electronics "${item.label}"${item.filename ? ` (${item.filename})` : ""}`
      + `${src?.url ? ` — ${src.url}` : ""}${item.datasheet ? ` (${item.datasheet})` : ""}`
    );
  }
  if (!lines.length) return "";
  return (
    "\n\nElectronics sourcing context (auto-attached from Electronics recommendations):\n"
    + `${lines.join("\n")}\n`
    + "Use these product pages and schematics for pinouts, wiring, and power when generating the circuit."
  );
}

function ensureWiringPromptHasElectronicsLinks(urls = []) {
  for (const entry of urls || []) {
    addWiringComposeLink(entry?.url || entry, { persist: false });
  }
}

/**
 * When Electronics finds recommendations, quietly save a sourcing markdown into
 * Reference Files (do NOT open a viewer tab — that covers the viewport / AR button).
 * Wiring AI still gets product/schematic URLs attached to its prompt.
 */
async function autoSourceElectronicsForWiring(bundle = latestElectronicsBundle) {
  if (!projectId || !bundle) return;
  const suggestions = (bundle.suggestions || []).filter((s) => s.kind !== "send-all-cad");
  const hasCad = (bundle.used?.cad || []).length > 0;
  if (!suggestions.length && !hasCad) return;

  const urls = collectElectronicsSourcingUrls(bundle);
  pendingWiringElectronicsLinks = urls.map((u) => u.url).slice(0, 3);
  ensureWiringPromptHasElectronicsLinks(urls.slice(0, 3));

  const key = `${projectId}:${suggestions.map((s) => s.id).sort().join("|")}:${(bundle.used?.cad || []).map((c) => c.filename || c.label).join(",")}`;
  if (electronicsSourcingSeededKey === key) return;
  electronicsSourcingSeededKey = key;

  try {
    await saveElectronicsDocsToReferences({
      used: bundle.used,
      suggestions: bundle.suggestions || [],
      open: false,
    });
  } catch (err) {
    console.warn("[electronics] auto-source save failed", err);
  }

  if (pendingWiringElectronicsLinks.length) {
    setEditStatus(
      "ok",
      `Electronics sourcing saved to Reference Files (${pendingWiringElectronicsLinks.length} link${pendingWiringElectronicsLinks.length === 1 ? "" : "s"} for Wiring AI).`,
    );
  }
}

function electronicsDockShownMap() {
  try {
    return JSON.parse(localStorage.getItem(LS_ELECTRONICS_DOCK_SHOWN) || "{}") || {};
  } catch {
    return {};
  }
}

function hasElectronicsDockBeenShown(pid = projectId) {
  if (!pid) return false;
  return !!electronicsDockShownMap()[pid];
}

function markElectronicsDockShown(pid = projectId) {
  if (!pid) return;
  try {
    const map = electronicsDockShownMap();
    map[pid] = true;
    localStorage.setItem(LS_ELECTRONICS_DOCK_SHOWN, JSON.stringify(map));
  } catch {
    /* best-effort */
  }
}

function hideElectronicsSuggestDock() {
  const dock = document.getElementById("electronics-suggest-dock");
  if (!dock) return;
  dock.classList.add("hidden");
  dock.hidden = true;
}

function openElectronicsDocs(searchQuery, label = "", item = null) {
  const links = item?.docs || electronicsDocLinks(searchQuery || label, label, {
    productUrl: item?.productUrl,
    schematicUrl: item?.schematicUrl,
  });
  const primary = links.find((l) => l.kind === "product" || l.kind === "schematic") || links[0];
  if (primary?.url) window.open(primary.url, "_blank", "noopener");
  // Open Digi-Key as a second source tab for purchasing/docs.
  const digikey = links.find((l) => l.provider === "Digi-Key");
  if (digikey?.url && digikey.url !== primary?.url) {
    window.setTimeout(() => window.open(digikey.url, "_blank", "noopener"), 120);
  }
  setEditStatus("ok", `Opened sourcing docs for ${label || searchQuery || "part"}.`);
}

async function saveElectronicsDocsToReferences({ used = null, suggestions = null, single = null, open = true } = {}) {
  if (!projectId) {
    setEditStatus("error", "Select a project first.");
    return null;
  }
  const bundle = used && suggestions
    ? { used, suggestions }
    : latestElectronicsBundle || { used: { wiring: [], cad: [] }, suggestions: [] };
  const projectName = allProjects?.find?.((p) => p.id === projectId)?.name || "Project";
  let markdown;
  if (single) {
    const docs = single.docs || electronicsDocLinks(single.search || single.datasheet || single.label, single.label, {
      productUrl: single.productUrl,
      schematicUrl: single.schematicUrl,
    });
    markdown = [
      `# ${single.label || "Electronics part"}`,
      "",
      single.reason ? `_${single.reason}_` : "",
      "",
      "## Source documentation",
      "",
      ...docs.map((link) => `- [${link.provider}](${link.url})`),
      "",
      single.datasheet || single.search ? `Search hint: ${single.datasheet || single.search}` : "",
      "",
      "Add this part to the Wiring Simulator after sourcing.",
    ].filter(Boolean).join("\n");
  } else {
    markdown = buildElectronicsReferenceMarkdown({
      projectName,
      used: bundle.used || bundle,
      suggestions: bundle.suggestions || suggestions || [],
    });
  }
  const safeStem = single
    ? `electronics_${String(single.type || single.label || "part").replace(/[^\w]+/g, "_").toLowerCase()}`.slice(0, 48)
    : "electronics_build_sourcing";
  const file = new File([markdown], `${safeStem}.md`, { type: "text/markdown" });
  const data = await uploadReferenceProjectFile(file, {
    destination: "current",
    projectId,
    silent: !open,
    referenceFolder: "Electronics wiring",
    replaceExisting: true,
  });
  if (open) {
    setEditStatus("ok", `Saved electronics docs to Reference Files (${data?.filename || file.name}).`);
  }
  return data;
}

async function attachElectronicsSuggestionToWiring(suggestion) {
  if (!projectId || !suggestion) return;
  // Keep Wiring AI docs in sync for this part.
  try {
    const urls = electronicsSourcingUrls(suggestion);
    if (urls.length) {
      pendingWiringElectronicsLinks = [
        ...new Set([...urls.map((u) => u.url), ...pendingWiringElectronicsLinks]),
      ].slice(0, 3);
      ensureWiringPromptHasElectronicsLinks(urls.slice(0, 3));
    }
  } catch (_) { }
  if (suggestion.kind === "send-all-cad") {
    await sendCadElectronicsToWiring();
    return;
  }
  if (suggestion.kind === "attach-cad" && suggestion.filename) {
    const entry = (lastProjectBrowser?.components || []).find((c) => (c.name || c.filename) === suggestion.filename) || {
      name: suggestion.filename,
      stem: fileStem(suggestion.filename),
    };
    await attachHierarchyComponentToWiring({ id: projectId }, entry, {
      label: suggestion.label,
      filename: suggestion.filename,
      wiringType: suggestion.type,
      part: {
        kind: suggestion.label,
        datasheet: suggestion.datasheet || suggestion.search,
        wiring_type: suggestion.type,
      },
    });
    return;
  }
  workspaceModes.setMode("wiring");
  applyWorkspaceMode("wiring");
  await wiringSim.load?.();
  await new Promise((resolve) => requestAnimationFrame(resolve));
  const qty = Math.max(1, Math.min(8, Number(suggestion.qty) || 1));
  for (let i = 0; i < qty; i += 1) {
    wiringSim.attachComponentRef?.({
      label: qty > 1 ? `${suggestion.label} ${i + 1}` : suggestion.label,
      wiringType: suggestion.type,
      part: {
        kind: suggestion.label,
        datasheet: suggestion.datasheet || suggestion.search,
        wiring_type: suggestion.type,
      },
    });
  }
  setEditStatus("ok", `Added ${suggestion.label}${qty > 1 ? ` ×${qty}` : ""} to Wiring Simulator.`);
}

async function sendCadElectronicsToWiring() {
  const cad = latestElectronicsBundle?.used?.cad || [];
  if (!cad.length) {
    setEditStatus("error", "No recognized CAD electronics to send.");
    return;
  }
  workspaceModes.setMode("wiring");
  applyWorkspaceMode("wiring");
  await wiringSim.load?.();
  await new Promise((resolve) => requestAnimationFrame(resolve));
  for (const item of cad) {
    const entry = (lastProjectBrowser?.components || []).find((c) => (c.name || c.filename) === item.filename) || {
      name: item.filename,
      stem: fileStem(item.filename),
    };
    wiringSim.attachComponentRef?.({
      label: item.label,
      filename: item.filename,
      wiringType: item.type,
      part: {
        kind: item.kind,
        datasheet: item.datasheet,
        wiring_type: item.type,
      },
      ...(entry || {}),
    });
  }
  setEditStatus("ok", `Sent ${cad.length} CAD electronic part${cad.length === 1 ? "" : "s"} to Wiring Simulator.`);
}

async function sendAllSuggestionsToWiring() {
  const suggestions = (latestElectronicsBundle?.suggestions || []).filter((s) => s.kind !== "send-all-cad");
  const hasSendAll = (latestElectronicsBundle?.suggestions || []).some((s) => s.kind === "send-all-cad");
  if (hasSendAll) await sendCadElectronicsToWiring();
  for (const suggestion of suggestions) {
    await attachElectronicsSuggestionToWiring(suggestion);
  }
  if (!suggestions.length && !hasSendAll) {
    setEditStatus("ok", "No missing electronics to add — wiring already covers the build.");
    return;
  }
  await refreshElectronicsSuggestions();
}

function bindElectronicsListActions(root) {
  root?.querySelectorAll("[data-electronics-source='cad'][data-electronics-file]")?.forEach((node) => {
    const title = node.querySelector(".object-iteration-title");
    if (title) title.style.cursor = "pointer";
    title?.addEventListener("click", async () => {
      const name = node.dataset.electronicsFile;
      if (!name || !projectId) return;
      try {
        selectedFile = name;
        projectTree?.setSelected?.(name);
        const url = projectFileUrl(projectId, name);
        await loadModel(url, name, { projectId, cacheBust: true, fitView: true });
        setEditStatus("ok", `Selected ${fileStem(name)}.`);
      } catch (err) {
        setEditStatus("error", err?.message || "Could not open part.");
      }
    });
  });
  root?.querySelectorAll("[data-electronics-source='wiring']")?.forEach((node) => {
    node.querySelector(".object-iteration-title")?.addEventListener("click", () => {
      if (workspaceModes?.getMode?.() !== "wiring") workspaceModes?.setMode?.("wiring");
      setRightTab("wiring");
      setEditStatus("ok", "Opened Wiring Simulator — electronics are listed from this schematic.");
    });
  });
  root?.querySelectorAll("[data-used-action]")?.forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const action = btn.dataset.usedAction;
      const card = btn.closest("[data-electronics-id], [data-electronics-file]");
      if (action === "docs") {
        const filename = card?.dataset?.electronicsFile;
        const item = (latestElectronicsBundle?.used?.cad || []).find((c) => c.filename === filename)
          || (latestElectronicsBundle?.used?.wiring || []).find((c) => String(c.id) === card?.dataset?.electronicsId);
        openElectronicsDocs(btn.dataset.docsQuery || "", btn.dataset.docsLabel || "", item || null);
        return;
      }
      if (action === "reference") {
        await saveElectronicsDocsToReferences({
          single: {
            label: btn.dataset.docsLabel || btn.dataset.docsQuery || "Electronics",
            search: btn.dataset.docsQuery,
            datasheet: btn.dataset.docsQuery,
            type: "part",
          },
        });
        return;
      }
      if (action === "wiring-cad") {
        const filename = card?.dataset?.electronicsFile;
        const item = (latestElectronicsBundle?.used?.cad || []).find((c) => c.filename === filename);
        if (item) {
          await attachElectronicsSuggestionToWiring({
            kind: "attach-cad",
            ...item,
            search: item.datasheet,
          });
          await refreshElectronicsSuggestions();
        }
      }
    });
  });
  root?.querySelectorAll("[data-suggest-action]")?.forEach((btn) => {
    btn.addEventListener("click", async (event) => {
      event.stopPropagation();
      const card = btn.closest("[data-electronics-suggest-id]");
      const id = card?.dataset?.electronicsSuggestId;
      const suggestion = (latestElectronicsBundle?.suggestions || []).find((s) => s.id === id);
      const action = btn.dataset.suggestAction;
      if (!suggestion && action !== "wiring-all") return;
      try {
        if (action === "wiring" || action === "wiring-all") {
          await attachElectronicsSuggestionToWiring(suggestion || { kind: "send-all-cad" });
          await refreshElectronicsSuggestions();
        } else if (action === "docs") {
          openElectronicsDocs(suggestion.search || suggestion.label, suggestion.label, suggestion);
        } else if (action === "reference") {
          await saveElectronicsDocsToReferences({ single: suggestion });
        }
      } catch (err) {
        setEditStatus("error", err?.message || "Could not apply electronics action.");
      }
    });
  });
}

function renderElectronicsSuggestDock(bundle, { force = false } = {}) {
  const dock = document.getElementById("electronics-suggest-dock");
  const list = document.getElementById("electronics-suggest-dock-list");
  const meta = document.getElementById("electronics-suggest-dock-meta");
  if (!dock || !list) return;
  const suggestions = bundle?.suggestions || [];
  // Floating dock is a one-shot after the first generation. Later viewing is via Electronics tab.
  const allowShow = force
    && !!projectId
    && suggestions.length > 0
    && electronicsSuggestDismissedFor !== projectId
    && !hasElectronicsDockBeenShown(projectId);
  if (!allowShow) {
    hideElectronicsSuggestDock();
    return;
  }
  markElectronicsDockShown(projectId);
  dock.hidden = false;
  dock.classList.remove("hidden");
  if (meta) {
    meta.textContent = `${suggestions.length} part${suggestions.length === 1 ? "" : "s"} to source / wire`;
  }
  list.innerHTML = suggestions.slice(0, 6).map((item) => `
    <div class="electronics-suggest-dock-row" data-electronics-suggest-id="${appEscapeHtml(item.id)}">
      <span class="electronics-item-swatch" style="background:${appEscapeHtml(item.color || "#58a6ff")}"></span>
      <div class="electronics-suggest-dock-copy">
        <strong>${appEscapeHtml(item.label)}${item.qty > 1 ? ` ×${item.qty}` : ""}</strong>
        <small>${appEscapeHtml(item.reason || "")}</small>
      </div>
      <div class="electronics-suggest-dock-row-actions">
        <button type="button" class="btn accent btn-compact" data-suggest-action="${item.kind === "send-all-cad" ? "wiring-all" : "wiring"}">Wiring</button>
        ${item.docs?.length ? `<button type="button" class="btn secondary btn-compact" data-suggest-action="docs">Docs</button>` : ""}
        ${item.docs?.length ? `<button type="button" class="btn secondary btn-compact" data-suggest-action="reference">Save</button>` : ""}
      </div>
    </div>
  `).join("");
  bindElectronicsListActions(list);
}

let electronicsSuggestAbort = null; // leakfix36
async function renderElectronicsUsedList(target = document.getElementById("electronics-used-list")) {
  if (!target && !document.getElementById("electronics-suggest-dock")) return null;
  if (!projectId) {
    if (electronicsSuggestAbort) {
      try { electronicsSuggestAbort.abort(); } catch (_) { /* ignore */ }
      electronicsSuggestAbort = null;
    }
    if (target) target.innerHTML = `<div class="object-iteration-empty">Select a project to list electronics.</div>`;
    hideElectronicsSuggestDock();
    return null;
  }
  if (electronicsSuggestAbort) {
    try { electronicsSuggestAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  electronicsSuggestAbort = ctl;
  const pid = projectId;
  if (target) target.innerHTML = `<div class="object-iteration-empty">Loading electronics…</div>`;
  let data;
  try {
    data = await collectElectronicsUsed(ctl.signal); // leakfix40
    if (ctl.signal.aborted || projectId !== pid) return null;
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return null;
    throw err;
  } finally {
    if (electronicsSuggestAbort === ctl) electronicsSuggestAbort = null;
  }
  latestElectronicsBundle = { used: data, suggestions: data.suggestions || [] };
  void autoSourceElectronicsForWiring(latestElectronicsBundle);
  if (target) {
    target.innerHTML = electronicsUsedListHtml(data);
    bindElectronicsListActions(target);
  }
  // Keep dock closed while refreshing the Electronics panel / lists.
  hideElectronicsSuggestDock();
  return data;
}

async function refreshElectronicsSuggestions({ showDock = false } = {}) {
  if (!projectId) {
    if (electronicsSuggestAbort) {
      try { electronicsSuggestAbort.abort(); } catch (_) { /* ignore */ }
      electronicsSuggestAbort = null;
    }
    latestElectronicsBundle = null;
    pendingWiringElectronicsLinks = [];
    electronicsSourcingSeededKey = null;
    hideElectronicsSuggestDock();
    return null;
  }
  if (electronicsSuggestAbort) {
    try { electronicsSuggestAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  electronicsSuggestAbort = ctl;
  const pid = projectId;
  let data;
  try {
    data = await collectElectronicsUsed(ctl.signal);
    if (ctl.signal.aborted || projectId !== pid) return null;
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return null;
    throw err;
  } finally {
    if (electronicsSuggestAbort === ctl) electronicsSuggestAbort = null;
  }
  latestElectronicsBundle = { used: data, suggestions: data.suggestions || [] };
  void autoSourceElectronicsForWiring(latestElectronicsBundle);
  if (showDock) {
    renderElectronicsSuggestDock(latestElectronicsBundle, { force: true });
  } else {
    hideElectronicsSuggestDock();
  }
  const panelList = document.getElementById("electronics-used-list");
  if (panelList && document.querySelector('[data-right-panel="electronics"].active')) {
    panelList.innerHTML = electronicsUsedListHtml(data);
    bindElectronicsListActions(panelList);
  }
  if (electronicsPopover) {
    const popList = electronicsPopover.querySelector("#electronics-popover-list");
    if (popList) {
      popList.innerHTML = electronicsUsedListHtml(data);
      bindElectronicsListActions(popList);
    }
  }
  try { if (wiringPartsListOpen) renderWiringPartsPickerList(); } catch (_) { /* ignore */ }
  return data;
}

/** One-shot floating suggestions after the first CAD generation for this project. */
async function maybeShowElectronicsSuggestDockAfterGeneration(pid = projectId) {
  if (!pid || pid !== projectId) return;
  if (hasElectronicsDockBeenShown(pid) || electronicsSuggestDismissedFor === pid) {
    hideElectronicsSuggestDock();
    return;
  }
  await refreshElectronicsSuggestions({ showDock: true });
}

function closeElectronicsPopover() {
  electronicsPopover?.remove();
  electronicsPopover = null;
}

async function openElectronicsPopover(anchor = document.getElementById("workspace-tabs"), { force = false } = {}) {
  if (electronicsPopover && !force) {
    closeElectronicsPopover();
    return;
  }
  closeElectronicsPopover();
  closeObjectIterationTree();
  const pop = document.createElement("div");
  pop.className = "object-iteration-popover electronics-popover";
  pop.innerHTML = `
    <div class="object-iteration-header">
      <div>
        <strong>Electronics used</strong>
        <span>${projectId ? "Wiring schematic + CAD parts" : "No project selected"}</span>
      </div>
      <button type="button" class="object-iteration-close" aria-label="Close electronics list">✕</button>
    </div>
    <div class="object-iteration-list" id="electronics-popover-list">
      <div class="object-iteration-empty">Loading electronics…</div>
    </div>
  `;
  document.body.appendChild(pop);
  electronicsPopover = pop;
  const rect = anchor?.getBoundingClientRect?.();
  const top = rect ? rect.bottom + 8 : 72;
  const right = rect ? Math.max(12, window.innerWidth - rect.right) : 16;
  pop.style.top = `${top}px`;
  pop.style.right = `${right}px`;
  pop.querySelector(".object-iteration-close")?.addEventListener("click", closeElectronicsPopover);
  const data = await renderElectronicsUsedList(pop.querySelector("#electronics-popover-list"));
  const subtitle = pop.querySelector(".object-iteration-header span");
  if (subtitle && data) {
    subtitle.textContent = data.total
      ? `${data.total} part${data.total === 1 ? "" : "s"} in this project`
      : "No electronics in this project yet";
  }
  // Keep the side panel in sync when the tab is opened.
  void renderElectronicsUsedList();
  setTimeout(() => {
    document.addEventListener("mousedown", function onDocClick(event) {
      if (electronicsPopover && !electronicsPopover.contains(event.target) && !anchor?.contains?.(event.target)) {
        closeElectronicsPopover();
      } else if (electronicsPopover) {
        document.addEventListener("mousedown", onDocClick, { once: true });
      }
    }, { once: true });
  }, 0);
}

async function showElectronicsTabUi() {
  setRightTab("electronics");
  await renderElectronicsUsedList();
  const tabsEl = document.getElementById("workspace-tabs");
  await openElectronicsPopover(tabsEl, { force: true });
  setEditStatus("ok", "Electronics — used parts, build suggestions, wiring + sourcing docs.");
}

let lastRightTabBeforeRobot = "prompt";

function rememberRightTabBeforeRobot() {
  const current = document.querySelector("[data-right-tab].active")?.dataset.rightTab;
  if (current && current !== "robot" && current !== "robotics") lastRightTabBeforeRobot = current;
}

function closeRobotTeleopPanel() {
  const prev = lastRightTabBeforeRobot || "prompt";
  const tab = prev === "robot" || prev === "robotics" ? "prompt" : prev;
  robotRailTab.noteUserTab(tab);
  setRightTab(tab);
  robotRailTab.sync(getDimosTeleopState());
}

async function showRoboticsTabUi() {
  rememberRightTabBeforeRobot();
  robotRailTab.sync(getDimosTeleopState(), { force: true });
  // Robotics Home is intentionally cheap. Live viewers, simulators, printers,
  // camera polling, and network connections are started only by their cards.
  viserViewer?.hideViewerOnly?.();
  teleopViewer?.hideViewerOnly?.();
  simulationViewer?.hideViewerOnly?.();
  worktopViewer?.hideViewerOnly?.();
  docTabs?.setActive?.(ROBOTICS_HOME_TAB_ID);
  const home = document.getElementById("robotics-home-viewer");
  home?.classList.remove("hidden");
  home?.setAttribute("aria-hidden", "false");
  void roboticsHome?.refreshDatasets?.();
  setEditStatus("ok", "Robotics Home — choose a tool to load its simulator, connection, or live view.");
}

function handleWorkspaceRibbonAction(action, entry) {
  if (action === "enter-vr") {
    void openWorkshopEditor();
    document.getElementById("btn-xr-vr")?.click();
    return;
  }
  if (action === "god-view") {
    void openWorkshopEditor();
    void viewportXR?.enterGodView?.();
    return;
  }
  if (action === "place") {
    viewportXR?.placeWorkspacePiece?.(entry?.piece);
    void openWorkshopEditor();
    setEditStatus("ok", `Placed ${entry?.piece || "piece"} in the workspace.`);
    return;
  }
  if (action === "undo-piece") {
    viewportXR?.undoWorkspacePiece?.();
    void openWorkshopEditor();
    return;
  }
  if (action === "editor") {
    void openWorkshopEditor();
  }
}

function handleRoboticsRibbonAction(action, entry) {
  const anchor = entry?.id
    ? document.querySelector(`.ribbon-btn[data-id="${entry.id}"]`)
    : document.querySelector(".ribbon-bar");
  if (action === "viser-open" || action === "viser-connect" || action === "viser-tab") {
    teleopViewer?.hideViewerOnly?.();
    simulationViewer?.hideViewerOnly?.();
    worktopViewer?.hideViewerOnly?.();
    void viserViewer?.connect?.();
    return;
  }
  if (action === "sim-tab" || action === "sim-open") {
    viserViewer?.hideViewerOnly?.();
    teleopViewer?.hideViewerOnly?.();
    worktopViewer?.hideViewerOnly?.();
    void simulationViewer?.open?.();
    return;
  }
  if (action === "worktop-tab" || action === "worktop-open") {
    viserViewer?.hideViewerOnly?.();
    teleopViewer?.hideViewerOnly?.();
    simulationViewer?.hideViewerOnly?.();
    worktopViewer?.open?.();
    return;
  }
  if (action === "god-view") {
    worktopViewer?.open?.();
    void viewportXR?.enterGodView?.();
    return;
  }
  if (action === "sim-connect" || action === "sim-approve") {
    viserViewer?.hideViewerOnly?.();
    teleopViewer?.hideViewerOnly?.();
    simulationViewer?.connect?.();
    return;
  }
  if (action === "sim-calibrate") {
    simulationViewer?.startCalibration?.();
    return;
  }
  if (action === "teleop-open" || action === "teleop-connect" || action === "teleop-tab") {
    if (roboticsOwnsExternalSession()) { setDimosTeleopArmed(true); return; }
    viserViewer?.hideViewerOnly?.();
    simulationViewer?.hideViewerOnly?.();
    worktopViewer?.hideViewerOnly?.();
    void teleopViewer?.connect?.();
    return;
  }
  if (action === "teleop-docs") {
    if (teleopViewer?.openDocs) teleopViewer.openDocs();
    else {
      try { window.open(ROBOTICS_DOCS_HREF, "_blank", "noopener"); } catch { window.location.href = ROBOTICS_DOCS_HREF; }
    }
    return;
  }
  if (action === "viser-add-ip" || action === "viser-ip") {
    viserViewer?.openControlPopup?.(anchor);
    return;
  }
  if (action === "viser-server") {
    viserViewer?.openNetworkPopup?.() || viserViewer?.openControlPopup?.(anchor);
    return;
  }
  if (action === "viser-cloud") {
    viserViewer?.openCloudPopup?.();
    return;
  }
  if (action === "control-config") {
    openStudioRoboticsProfile(anchor);
    return;
  }
  if (action === "printer-tab" || action === "printer-config") {
    setRoboticsInnerTab("printer");
    if (action === "printer-config") {
      openRoboticsPrinterConfigPopup({
        api,
        onApply: (saved) => { try { viewportXR?.setPrinterPrefs?.(saved); } catch (_) { } },
        onBounder: () => { try { viewportXR?.createPrinterBounder?.(); } catch (_) { } },
      });
    }
    return;
  }
  if (action === "cam-ip") {
    viserViewer?.openCameraPopup?.(anchor);
    return;
  }
  if (action === "cam-enable" || action === "cam-wrist") {
    if (wristCamPopups?.isOpen?.()) {
      wristCamPopups.hide();
      setEditStatus("ok", "Wrist cameras off");
      return;
    }
    // __activateZedTopCam starts publishing and opens the single ZED popup.
    // Calling show() again here doubled polling and could mount two requests.
    void window.__activateZedTopCam?.();
    void import("../xr/xr-hand-cams.js?v=roboticsworkspace3-camera-window2").then(async (mod) => {
      const user = currentUser || getStoredUser();
      await mod.activateWristCameras({
        user,
        apiFn: api,
        restart: true,
      });
      await wristCamPopups?.show?.();
      setEditStatus("ok", "Wrist cameras connected — LAN Mini via /api/robotics/hand-cam/…");
    }).catch((error) => {
      void wristCamPopups?.show?.();
      setEditStatus("error", `Wrist camera connection failed: ${error?.message || "unknown error"}`);
    });
    return;
  }
  if (action === "cam-debug") {
    viserViewer?.openCamDebugPopup?.() || viserViewer?.openCamerasTabPopup?.();
    return;
  }
  if (action === "cam-move") {
    void import("../xr/xr-hand-cams.js?v=roboticsworkspace3-camera-window1").then((mod) => {
      mod.persistHandCamMode("detach", currentUser || getStoredUser());
      setEditStatus("ok", "Hand cameras detach when a VR window is shown — grip to move, resize from the corner.");
    });
    return;
  }
  if (action === "cam-vr") {
    void import("../xr/xr-hand-cams.js?v=roboticsworkspace3-camera-window1").then((mod) => {
      const user = currentUser || getStoredUser();
      const next = mod.toggleHandCamVrScene(user);
      setEditStatus("ok", next.vrScene
        ? "VR scene on — connected wrist cameras appear in Quest (disconnected stay hidden)."
        : "VR scene off — windows only auto-show while DIMOS remote teleop is linked.");
    });
    return;
  }
  if (action === "local-terminal") {
    localTerminalUi?.open?.() || localTerminalUi?.toggle?.();
  }
}

function formatHistoryWhen(iso) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleString([], { dateStyle: "short", timeStyle: "short" });
  } catch {
    return "";
  }
}

function selectedPartFilterName() {
  const selection = objectTools.getSelection?.();
  const bodyName = selection?.label || promptTargetSelectedBody?.bodyName || null;
  if (bodyName && !/^body\s+\d+$/i.test(String(bodyName))) return bodyName;
  return null;
}

function closeObjectIterationTree() {
  objectIterationPopover?.remove();
  objectIterationPopover = null;
  document.getElementById("btn-history-tree")?.setAttribute("aria-pressed", "false");
}

function timelineParentFilename(entry) {
  const meta = entry?.meta || {};
  return meta.parent || meta.replace_catalog || meta.replaceCatalog || meta.source_file || null;
}

function timelineKindLabel(kind) {
  return {
    upload: "Upload",
    prompt: "AI",
    build: "Build",
    restore: "Restore",
    transform: "Move",
    body_transform: "Body move",
    extrude: "Extrude",
    face_pull: "Press-pull",
    fillet: "Fillet",
    chamfer: "Chamfer",
    mirror: "Mirror",
    hole: "Hole",
    paint: "Paint",
    mesh_cleanup: "Mesh cleanup",
    delete_object: "Delete",
  }[kind] || (kind ? String(kind).replace(/_/g, " ") : "Change");
}

function relatedTimelineIterations(filename) {
  const entries = timelineData?.entries || [];
  if (!entries.length) return [];
  const related = new Set([filename].filter(Boolean));
  let changed = true;
  while (changed) {
    changed = false;
    for (const entry of entries) {
      const child = entry.filename || null;
      const parent = timelineParentFilename(entry);
      if ((child && related.has(child)) || (parent && related.has(parent))) {
        for (const name of [child, parent]) {
          if (name && !related.has(name)) {
            related.add(name);
            changed = true;
          }
        }
      }
    }
  }
  return entries.filter((entry) => {
    const child = entry.filename || null;
    const parent = timelineParentFilename(entry);
    return (child && related.has(child)) || (parent && related.has(parent));
  });
}

function objectIterationTreeHtml(filename) {
  const entries = relatedTimelineIterations(filename);
  const current = timelineData?.current_index ?? -1;
  if (!entries.length) {
    return `<div class="object-iteration-empty">Version history will appear here after you apply a size change, upload, generate, or edit this object.</div>`;
  }
  return entries
    .map((entry, idx) => {
      const index = entry.index ?? idx;
      const parent = timelineParentFilename(entry);
      const filenameLabel = entry.filename ? fileStem(entry.filename) : "project";
      const parentLabel = parent && parent !== entry.filename ? `from ${fileStem(parent)}` : "";
      const active = index === current;
      const label = entry.label || timelineKindLabel(entry.kind);
      const when = formatHistoryWhen(entry.created_at);
      const meta = [timelineKindLabel(entry.kind), when, parentLabel].filter(Boolean).join(" · ");
      return `<div class="object-iteration-node${active ? " active" : ""}" data-index="${index}">
        <span class="object-iteration-rail" aria-hidden="true"></span>
        <div class="object-iteration-card">
          <div class="object-iteration-main">
            <span class="object-iteration-badge">#${index + 1}</span>
            <span class="object-iteration-title">${appEscapeHtml(label)}</span>
            ${active ? '<span class="object-iteration-current">Current</span>' : ""}
          </div>
          <div class="object-iteration-meta">${appEscapeHtml(filenameLabel)}${meta ? ` · ${appEscapeHtml(meta)}` : ""}</div>
          <div class="object-iteration-actions">
            <button type="button" class="btn secondary btn-compact" data-history-view="${index}"${timelineEntryIsRestorable(entry) ? "" : " disabled"}>View</button>
            <button type="button" class="btn secondary btn-compact" data-history-latest="${index}"${timelineEntryIsRestorable(entry) ? "" : " disabled"}>Make latest</button>
          </div>
        </div>
      </div>`;
    })
    .join("");
}

function objectResizeTarget(filename) {
  const selection = objectTools.getSelection?.();
  const catalogName = selection?.catalogName || filename;
  const root = catalogName ? projectAssembly.get(catalogName) : (selection?.root || null);
  const mesh = selection?.mesh || firstPromptTargetMesh(root);
  if (!root || !mesh) return null;
  const bodyIndex = Number.isInteger(selection?.bodyIndex) ? selection.bodyIndex : null;
  const bodyInfo = objectTools.getBodyInfo?.();
  const box = bodyIndex != null && mesh?.isMesh && (bodyInfo?.count || 0) > 1
    ? bodyBoundsForMesh(mesh, bodyIndex, bodyInfo)
    : new THREE.Box3().setFromObject(selection?.root || root);
  if (!box || box.isEmpty()) return null;
  const size = box.getSize(new THREE.Vector3());
  const label = bodyIndex != null && (bodyInfo?.count || 0) > 1
    ? (bodyInfo.body_names?.[bodyIndex] || `Body ${bodyIndex + 1}`)
    : fileStem(catalogName || filename);
  return {
    filename: catalogName || filename,
    bodyIndex,
    bodyCount: bodyInfo?.count || 1,
    label,
    size,
  };
}

function bodyBoundsForMesh(mesh, bodyIndex, bodyInfo) {
  if (!mesh?.isMesh || !mesh.geometry?.attributes?.position || !bodyInfo?.face_offsets?.length) {
    return new THREE.Box3().setFromObject(mesh);
  }
  const geom = mesh.geometry;
  const pos = geom.attributes.position;
  const index = geom.index;
  const faceCount = geom.index ? Math.floor(geom.index.count / 3) : Math.floor(pos.count / 3);
  const start = Math.max(0, bodyInfo.face_offsets[bodyIndex] ?? 0);
  const end = Math.min(bodyInfo.face_offsets[bodyIndex + 1] ?? faceCount, faceCount);
  const box = new THREE.Box3();
  const v = new THREE.Vector3();
  for (let fi = start; fi < end; fi += 1) {
    for (let j = 0; j < 3; j += 1) {
      const vi = index ? index.getX(fi * 3 + j) : fi * 3 + j;
      v.fromBufferAttribute(pos, vi);
      mesh.localToWorld(v);
      box.expandByPoint(v);
    }
  }
  return box.isEmpty() ? new THREE.Box3().setFromObject(mesh) : box;
}

function objectSizeControlsHtml(filename) {
  const target = objectResizeTarget(filename);
  if (!target) {
    return `<section class="object-size-panel">
      <strong>Generative Size Controls</strong>
      <p class="object-size-hint">Select an object or body in the viewport, then use this panel to adjust width, depth, and height.</p>
    </section>`;
  }
  const dims = [
    ["width", "Width", target.size.x],
    ["depth", "Depth", target.size.y],
    ["height", "Height", target.size.z],
  ];
  const rows = dims.map(([axis, label, value]) => {
    const base = Math.max(0.01, value);
    const min = Math.max(0.1, base * 0.2);
    const max = Math.max(base * 2.5, min + 1);
    return `<label class="object-size-row" data-axis="${axis}">
      <span>${label}</span>
      <input type="range" min="${min.toFixed(2)}" max="${max.toFixed(2)}" step="0.1" value="${base.toFixed(2)}" data-size-range="${axis}" data-base="${base.toFixed(6)}" />
      <input type="number" min="0.1" step="0.1" value="${base.toFixed(2)}" data-size-number="${axis}" />
      <em>mm</em>
    </label>`;
  }).join("");
  return `<section class="object-size-panel" data-resize-filename="${appEscapeHtml(target.filename)}" data-resize-body="${target.bodyIndex ?? ""}">
    <div class="object-size-head">
      <div>
        <strong>Generative Size Controls</strong>
        <span>${appEscapeHtml(target.label)} · ${target.bodyCount > 1 && target.bodyIndex != null ? "selected body" : "selected object"}</span>
      </div>
      <button type="button" class="btn secondary btn-compact" data-size-reset title="Restore the original model size from when this panel opened">Reset</button>
    </div>
    ${rows}
    <label class="object-size-row object-size-row--uniform">
      <span>Overall</span>
      <input type="range" min="20" max="250" step="1" value="100" data-size-uniform />
      <input type="number" min="1" step="1" value="100" data-size-uniform-number />
      <em>%</em>
    </label>
    <div class="object-size-actions">
      <button type="button" class="btn accent btn-compact" data-size-apply>Apply size change</button>
      <small>${target.bodyCount > 1 && target.bodyIndex != null
      ? "Selected body: release or Apply to bake (live preview disabled so the whole assembly doesn’t scale)."
      : "Drag for live preview; release to bake the size into the model."}</small>
    </div>
  </section>`;
}

function bindObjectSizeControls(pop, filename) {
  const panel = pop.querySelector(".object-size-panel[data-resize-filename]");
  if (!panel) return;
  let applyTimer = null;
  let applying = false;
  let queued = false;
  let lastAppliedKey = "";
  let previewObj = null;
  let previewBaseScale = null;
  const originalBases = {
    width: Number(panel.querySelector('[data-size-range="width"]')?.dataset.base),
    depth: Number(panel.querySelector('[data-size-range="depth"]')?.dataset.base),
    height: Number(panel.querySelector('[data-size-range="height"]')?.dataset.base),
  };
  // Frozen at panel open — Reset restores this original model size, not the last bake.
  const sessionOriginalBases = { ...originalBases };
  const sessionOriginalUniform = 100;

  const syncNumber = (axis, value) => {
    const num = panel.querySelector(`[data-size-number="${axis}"]`);
    if (num) num.value = Number(value).toFixed(2);
  };
  const syncRange = (axis, value) => {
    const range = panel.querySelector(`[data-size-range="${axis}"]`);
    if (range) range.value = String(value);
  };
  const currentSizeValues = () => ["width", "depth", "height"].map((axis) => Number(panel.querySelector(`[data-size-number="${axis}"]`)?.value));

  const ensurePreviewObj = () => {
    const target = objectResizeTarget(filename);
    if (!target) return null;
    const obj = projectAssembly.get(target.filename);
    if (!obj) return null;
    if (previewObj !== obj) {
      previewObj = obj;
      previewBaseScale = obj.scale.clone();
    }
    return previewObj;
  };

  const applyLivePreview = () => {
    const target = objectResizeTarget(filename);
    // Multi-body: don't scale the whole assembly while editing one body —
    // that made every drag look like "the whole model got bigger."
    if (target?.bodyCount > 1 && target.bodyIndex != null) {
      return;
    }
    const obj = ensurePreviewObj();
    if (!obj || !previewBaseScale) return;
    const values = currentSizeValues();
    if (!values.every((value) => Number.isFinite(value) && value > 0)) return;
    const bases = [originalBases.width, originalBases.depth, originalBases.height].map((v) => Math.max(0.01, Number(v) || 0.01));
    obj.scale.set(
      previewBaseScale.x * (values[0] / bases[0]),
      previewBaseScale.y * (values[1] / bases[1]),
      previewBaseScale.z * (values[2] / bases[2])
    );
  };

  const resetLivePreview = () => {
    if (previewObj && previewBaseScale) previewObj.scale.copy(previewBaseScale);
  };

  const applySizeChange = async (status = "Applying size change...") => {
    if (applying) {
      queued = true;
      return;
    }
    const target = objectResizeTarget(filename);
    if (!target) {
      setEditStatus("error", "Select an object or body first.");
      return;
    }
    const values = currentSizeValues();
    if (!values.every((value) => Number.isFinite(value) && value > 0)) return;
    // Scale against the panel's original bases (file geometry), not the live-preview bounds.
    const bases = [originalBases.width, originalBases.depth, originalBases.height].map((v) => Math.max(0.01, Number(v) || 0.01));
    const scale = values.map((value, idx) => value / bases[idx]);
    const valueKey = `${target.filename}:${target.bodyIndex ?? "all"}:${scale.map((v) => v.toFixed(4)).join(":")}`;
    if (valueKey === lastAppliedKey) return;
    applying = true;
    const applyBtn = panel.querySelector("[data-size-apply]");
    if (applyBtn) applyBtn.disabled = true;
    setEditStatus("loading", status);
    try {
      const endpoint = target.bodyCount > 1 && target.bodyIndex != null
        ? `/api/projects/${projectId}/files/${encodeURIComponent(target.filename)}/transform-body`
        : `/api/projects/${projectId}/files/${encodeURIComponent(target.filename)}/transform`;
      const body = target.bodyCount > 1 && target.bodyIndex != null
        ? {
          body_index: target.bodyIndex,
          ...(target.label ? { body_name: String(target.label).trim() } : {}),
          scale,
        }
        : { scale };
      const data = await api(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      // Clear live preview only after a successful bake so failures keep the preview size.
      resetLivePreview();
      await afterModelEdit({ ...data, replaceCatalog: target.filename });
      lastAppliedKey = valueKey;
      // Refresh bases to the newly baked size.
      const next = objectResizeTarget(data.filename || target.filename);
      if (next) {
        originalBases.width = next.size.x;
        originalBases.depth = next.size.y;
        originalBases.height = next.size.z;
        ["width", "depth", "height"].forEach((axis, idx) => {
          const range = panel.querySelector(`[data-size-range="${axis}"]`);
          const val = [next.size.x, next.size.y, next.size.z][idx];
          if (range) {
            range.dataset.base = String(val);
            const min = Math.max(0.1, val * 0.2);
            const max = Math.max(val * 2.5, min + 1);
            range.min = String(min);
            range.max = String(max);
            range.value = String(val);
          }
          syncNumber(axis, val);
        });
        const uniform = panel.querySelector("[data-size-uniform]");
        const uniformNumber = panel.querySelector("[data-size-uniform-number]");
        if (uniform) uniform.value = "100";
        if (uniformNumber) uniformNumber.value = "100";
      }
      previewObj = null;
      previewBaseScale = null;
      ensurePreviewObj();
      setEditStatus("ok", `Resized ${target.label}.`);
    } catch (err) {
      setEditStatus("error", err.message || "Could not apply size change.");
      applyLivePreview();
    } finally {
      applying = false;
      if (applyBtn) applyBtn.disabled = false;
      if (queued) {
        queued = false;
        await applySizeChange("Applying latest size change...");
      }
    }
  };

  const scheduleApply = (delayMs = 260) => {
    if (applyTimer) window.clearTimeout(applyTimer);
    applyTimer = window.setTimeout(() => {
      applyTimer = null;
      void applySizeChange("Applying size change...");
    }, delayMs);
  };

  panel.querySelectorAll("[data-size-range]").forEach((range) => {
    range.addEventListener("input", () => {
      syncNumber(range.dataset.sizeRange, range.value);
      applyLivePreview();
    });
    range.addEventListener("change", () => scheduleApply(60));
    range.addEventListener("pointerup", () => scheduleApply(40));
  });
  panel.querySelectorAll("[data-size-number]").forEach((num) => {
    num.addEventListener("input", () => {
      syncRange(num.dataset.sizeNumber, num.value);
      applyLivePreview();
    });
    num.addEventListener("change", () => scheduleApply(80));
  });
  const applyUniform = (percent) => {
    const factor = Math.max(0.01, Number(percent || 100) / 100);
    panel.querySelectorAll("[data-size-range]").forEach((range) => {
      const base = Number(range.dataset.base || range.value || 1);
      const next = base * factor;
      range.value = String(next);
      syncNumber(range.dataset.sizeRange, next);
    });
  };
  panel.querySelector("[data-size-uniform]")?.addEventListener("input", (event) => {
    const value = event.currentTarget.value;
    const number = panel.querySelector("[data-size-uniform-number]");
    if (number) number.value = value;
    applyUniform(value);
    applyLivePreview();
  });
  panel.querySelector("[data-size-uniform]")?.addEventListener("change", () => scheduleApply(60));
  panel.querySelector("[data-size-uniform]")?.addEventListener("pointerup", () => scheduleApply(40));
  panel.querySelector("[data-size-uniform-number]")?.addEventListener("input", (event) => {
    const value = event.currentTarget.value;
    const range = panel.querySelector("[data-size-uniform]");
    if (range) range.value = value;
    applyUniform(value);
    applyLivePreview();
  });
  panel.querySelector("[data-size-uniform-number]")?.addEventListener("change", () => scheduleApply(80));
  panel.querySelector("[data-size-reset]")?.addEventListener("click", () => {
    // Keep originalBases as the *current baked* size so applySizeChange scales
    // back toward the frozen session-original dimensions.
    ["width", "depth", "height"].forEach((axis) => {
      const target = Math.max(0.1, Number(sessionOriginalBases[axis]) || 0.1);
      const range = panel.querySelector(`[data-size-range="${axis}"]`);
      if (range) {
        const min = Math.max(0.1, target * 0.2);
        const max = Math.max(target * 2.5, min + 1);
        range.min = String(min);
        range.max = String(max);
        range.value = String(target);
      }
      syncNumber(axis, target);
    });
    const uniform = panel.querySelector("[data-size-uniform]");
    const uniformNumber = panel.querySelector("[data-size-uniform-number]");
    if (uniform) uniform.value = String(sessionOriginalUniform);
    if (uniformNumber) uniformNumber.value = String(sessionOriginalUniform);
    resetLivePreview();
    lastAppliedKey = "";
    setEditStatus("ok", "Restoring original model size…");
    void applySizeChange("Restoring original model size…");
  });
  panel.querySelector("[data-size-apply]")?.addEventListener("click", async () => {
    if (applyTimer) {
      window.clearTimeout(applyTimer);
      applyTimer = null;
    }
    await applySizeChange();
  });
}

async function openObjectIterationTree(anchor = document.getElementById("btn-history-tree")) {
  if (objectIterationPopover) {
    closeObjectIterationTree();
    return;
  }
  closeElectronicsPopover();
  const filename = selectedObjectFilename();
  if (!projectId || !filename) {
    setEditStatus("error", "Select an object first to view its iteration tree.");
    return;
  }
  const partFilter = selectedPartFilterName();
  const cadParams = await fetchCadParams(rawFetch, projectId, filename, { part: partFilter });
  const pop = document.createElement("div");
  pop.className = "object-iteration-popover";
  pop.innerHTML = `
    <div class="object-iteration-header">
      <div>
        <strong>Object Adjustments</strong>
        <span>${appEscapeHtml(fileStem(filename))}</span>
      </div>
      <button type="button" class="object-iteration-close" aria-label="Close history tree">✕</button>
    </div>
    <div class="object-iteration-list">
      ${cadParamControlsHtml(cadParams, { partLabel: partFilter })}
      ${objectSizeControlsHtml(filename)}
      <div class="object-iteration-history-head">History Tree</div>
      ${objectIterationTreeHtml(filename)}
    </div>
  `;
  document.body.appendChild(pop);
  objectIterationPopover = pop;
  anchor?.setAttribute("aria-pressed", "true");
  const rect = anchor?.getBoundingClientRect?.();
  const top = rect ? rect.bottom + 8 : 72;
  const right = rect ? Math.max(12, window.innerWidth - rect.right) : 16;
  pop.style.top = `${top}px`;
  pop.style.right = `${right}px`;
  pop.querySelector(".object-iteration-close")?.addEventListener("click", closeObjectIterationTree);
  bindCadParamControls(pop, {
    projectId,
    filename,
    part: partFilter,
    initialData: cadParams,
    api,
    rawFetch,
    onStatus: setEditStatus,
    getPreviewRoot: () => {
      const name = selectedObjectFilename() || filename;
      return (name && projectAssembly.get(name)) || currentMesh || null;
    },
    // Jake-style: bake envelope dims via /transform (or /transform-body per part).
    bakeScale: async ({ scale }) => {
      const target = objectResizeTarget(filename);
      if (!target) throw new Error("Select an object or body first.");
      const useBody = target.bodyCount > 1 && target.bodyIndex != null;
      const endpoint = useBody
        ? `/api/projects/${projectId}/files/${encodeURIComponent(target.filename)}/transform-body`
        : `/api/projects/${projectId}/files/${encodeURIComponent(target.filename)}/transform`;
      const body = useBody
        ? {
          body_index: target.bodyIndex,
          ...(target.label ? { body_name: String(target.label).trim() } : {}),
          scale,
        }
        : { scale };
      const data = await api(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      await afterModelEdit({ ...data, replaceCatalog: target.filename });
      return { ...data, _skipOnApplied: true };
    },
    onApplied: async (result) => {
      const reloadName = result?.artifacts?.glb || filename;
      if (result?.artifacts?.urdf) {
        bumpModelCacheEpoch();
        await refreshFiles();
        await refreshRobotArtifacts({ quiet: true });
        await ensureUrdfRobotScene({ quiet: false, force: true });
        if (reloadName && /\.(glb|stl)$/i.test(reloadName)) {
          const url = projectFileUrl(projectId, reloadName);
          await afterModelEdit({
            filename: reloadName,
            url,
            replaceCatalog: filename,
          });
        }
        setEditStatus("ok", `Rebuilt URDF robot from ${result.artifacts.source || "source"}.`);
        return;
      }
      const url = projectFileUrl(projectId, reloadName);
      // Always swap the selected catalog for the rebuilt generative GLB.
      await afterModelEdit({
        filename: reloadName,
        url,
        replaceCatalog: filename,
      });
      featureEditor.setModel(projectId, reloadName);
      selectedFile = reloadName;
    },
  });
  bindObjectSizeControls(pop, filename);
  pop.querySelectorAll("[data-history-view]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const index = parseInt(btn.dataset.historyView, 10);
      closeObjectIterationTree();
      if (!Number.isNaN(index)) await restoreTimeline(index);
    });
  });
  pop.querySelectorAll("[data-history-latest]").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const index = parseInt(btn.dataset.historyLatest, 10);
      closeObjectIterationTree();
      if (!Number.isNaN(index)) await restoreTimelineAsLatest(index);
    });
  });
  setTimeout(() => {
    document.addEventListener("mousedown", function onDocClick(event) {
      if (objectIterationPopover && !objectIterationPopover.contains(event.target) && !anchor?.contains?.(event.target)) {
        closeObjectIterationTree();
      } else if (objectIterationPopover) {
        document.addEventListener("mousedown", onDocClick, { once: true });
      }
    }, { once: true });
  }, 0);
}

let simLoadAbort = null; // leakfix101
function beginSimLoadFetch() {
  if (simLoadAbort) {
    try { simLoadAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  simLoadAbort = ctl;
  return ctl;
}

async function loadSimForFile(filename) {
  if (!projectId) {
    if (simLoadAbort) {
      try { simLoadAbort.abort(); } catch (_) { /* ignore */ }
    }
    currentSim = null;
    return null;
  }
  const ctl = beginSimLoadFetch();

  const stems = new Set();
  if (filename) stems.add(fileStem(filename));
  for (const [name] of projectAssembly.list()) {
    const safeName = String(name || "");
    if (safeName.toLowerCase().endsWith(".glb")) stems.add(fileStem(safeName));
  }

  for (const stem of stems) {
    if (ctl.signal.aborted) return currentSim;
    try {
      const res = await rawFetch(
        `/api/projects/${projectId}/files/${encodeURIComponent(`${stem}.sim.json`)}`,
        { signal: ctl.signal }
      );
      if (ctl.signal.aborted) return currentSim;
      if (!res.ok) continue;
      const sim = await res.json();
      if (ctl.signal.aborted) return currentSim;
      const parts = sim?.parts || [];
      const joints = sim?.joints || [];
      if (parts.length || joints.length) {
        currentSim = sim;
        if (riggingEditor.isActive?.()) riggingEditor.refreshMeshBindings?.();
        return currentSim;
      }
    } catch (err) {
      if (ctl.signal.aborted || err?.name === "AbortError") return currentSim;
      /* try next stem */
    }
  }
  if (ctl.signal.aborted) return currentSim;
  currentSim = null;
  return null;
}

function primaryViewportComponent(comps = [], latestFile = null) {
  const auto = comps.filter((c) => c.auto_load === true);
  const assembly = auto.find((c) => c.primary) || comps.find((c) => c.primary);
  if (latestFile) {
    const latestStem = fileStem(latestFile).replace(/_edited(?:_\d+)?$/i, "").replace(/_exploded$/i, "");
    const latest =
      auto.find((c) => c.name === latestFile || c.viewer_filename === latestFile) ||
      comps.find((c) => c.name === latestFile || c.viewer_filename === latestFile) ||
      auto.find((c) => c.stem === latestStem || fileStem(c.name) === latestStem) ||
      comps.find((c) => c.stem === latestStem || fileStem(c.name) === latestStem);
    // Timeline/latest-file already resolves prompt artifacts back to the primary
    // assembly on the backend. If it names a real transformed mesh, prefer it so
    // applied gizmo rotations/moves persist after refresh.
    if (latest) {
      if (
        latest.name !== latestFile
        && latest.viewer_filename !== latestFile
        && /\.(glb|gltf|stl|obj|ply|off)$/i.test(latestFile)
        && !/_exploded$/i.test(fileStem(latestFile))
      ) {
        return { ...latest, name: latestFile, viewer_filename: latestFile };
      }
      return latest;
    }
  }
  return assembly || auto[0] || comps[0] || null;
}

function componentsAlreadyLoaded(comps = [], latestFile = null) {
  const visible = (comps || []).filter((c) => !isBrowserComponentHidden(c) && !isCatalogHardwareComponent(c));
  if (!visible.length) return false;
  if (latestFile) {
    const latest =
      visible.find((c) => c.name === latestFile || c.viewer_filename === latestFile) || null;
    if (latest && !projectAssembly.has(latest.name)) return false;
    // Latest file is on disk but not yet a browser component — still needs a load.
    if (!latest && /\.(glb|gltf|stl|obj|ply|off)$/i.test(String(latestFile))) return false;
  }
  const auto = visible.filter((c) => c.auto_load === true);
  const required = auto.length
    ? auto
    : [primaryViewportComponent(visible, latestFile)].filter(Boolean);
  if (!required.length) return false;
  return required.every((c) => projectAssembly.has(c.name));
}

function assemblyCatalogMatchingStem(filename) {
  const raw = String(filename || "").trim();
  if (!raw) return null;
  if (projectAssembly.has(raw)) return raw;
  const stem = fileStem(raw).replace(/_edited(?:_\d+)?$/i, "");
  for (const [name] of projectAssembly.list()) {
    const other = fileStem(name).replace(/_edited(?:_\d+)?$/i, "");
    if (other === stem) return name;
  }
  return null;
}

function objectWorldBox(obj) {
  if (!obj) return null;
  obj.updateMatrixWorld?.(true);
  const box = new THREE.Box3().setFromObject(obj);
  return box.isEmpty() ? null : box;
}

function plainWorldBox(box) {
  if (!box) return null;
  return {
    min: { x: box.min.x, y: box.min.y, z: box.min.z },
    max: { x: box.max.x, y: box.max.y, z: box.max.z },
  };
}

function isScaledOverlappingCopy(keepBox, otherBox) {
  if (!keepBox || !otherBox) return false;
  const keepSize = keepBox.getSize(new THREE.Vector3());
  const otherSize = otherBox.getSize(new THREE.Vector3());
  const keepMax = Math.max(keepSize.x, keepSize.y, keepSize.z, 1e-9);
  const otherMax = Math.max(otherSize.x, otherSize.y, otherSize.z, 1e-9);
  const small = otherMax <= keepMax ? otherBox : keepBox;
  const large = otherMax <= keepMax ? keepBox : otherBox;
  const smallSize = small.getSize(new THREE.Vector3());
  const largeSize = large.getSize(new THREE.Vector3());
  const ratio = Math.max(smallSize.x, smallSize.y, smallSize.z) / Math.max(largeSize.x, largeSize.y, largeSize.z, 1e-9);
  if (!(ratio > 0.02 && ratio < 0.4)) return false;
  const largeCenter = large.getCenter(new THREE.Vector3());
  const smallCenter = small.getCenter(new THREE.Vector3());
  if (smallCenter.distanceTo(largeCenter) > Math.max(largeSize.x, largeSize.y, largeSize.z) * 0.4) return false;
  const a = [largeSize.x, largeSize.y, largeSize.z].sort((x, y) => x - y);
  const b = [smallSize.x, smallSize.y, smallSize.z].sort((x, y) => x - y);
  return a.every((v, i) => {
    const scale = b[i] / Math.max(v, 1e-9);
    return scale > 0.02 && scale < 0.45;
  });
}

/** Hide leftover scaled copies that generation sometimes leaves beside the real model. */
function hideOverlappingScaledDuplicates(preferredName) {
  const keepName = assemblyCatalogMatchingStem(preferredName) || preferredName;
  const keepObj = projectAssembly.get(keepName);
  const keepBox = objectWorldBox(keepObj);
  if (!keepBox) return;
  const hidden = [];
  for (const [name, obj] of projectAssembly.list()) {
    if (!name || name === keepName) continue;
    if (isCatalogHardwareComponent({ name })) continue;
    if (/_exploded$/i.test(fileStem(name))) continue;
    if (!sameModelLineage(name, keepName)) continue;
    const otherBox = objectWorldBox(obj);
    const sameEnvelope = nearDuplicateModelBoxes(plainWorldBox(keepBox), plainWorldBox(otherBox));
    if (!(sameEnvelope || isScaledOverlappingCopy(keepBox, otherBox))) continue;
    const keepMax = Math.max(...keepBox.getSize(new THREE.Vector3()).toArray());
    const otherMax = Math.max(...otherBox.getSize(new THREE.Vector3()).toArray());
    // The completed generation is authoritative for equal-size overlaps. For
    // scaled copies retain the larger envelope as before.
    const hideName = sameEnvelope ? name : (otherMax < keepMax ? name : keepName);
    if (hideName === keepName) continue;
    projectAssembly.setVisible(hideName, false);
    setStoredComponentHidden(projectId, hideName, true);
    hidden.push(hideName);
  }
  if (hidden.length) {
    projectTree.setHidden?.([...loadHiddenComponentState()]);
    setEditStatus("ok", hidden.length === 1
      ? `Hidden a scaled duplicate of ${fileStem(keepName)}.`
      : `Hidden ${hidden.length} scaled duplicates.`);
  }
}

function modelMatchesSelection(viewFilename, catalogName) {
  const sel = catalogName || selectedFile;
  if (!sel) return true;
  if (viewFilename === sel) return true;
  return fileStem(viewFilename) === fileStem(sel);
}

function hasBakedPlacement(filenameOrEntry) {
  if (filenameOrEntry && typeof filenameOrEntry === "object" && filenameOrEntry.baked_placement) return true;
  const name = typeof filenameOrEntry === "string" ? filenameOrEntry : filenameOrEntry?.name || filenameOrEntry?.viewer_filename || "";
  return /(?:_edited(?:_\d+)?|_copy\d*|component_mounting_fixture)\.(glb|gltf|stl|obj|ply|off)$/i.test(String(name || ""));
}

function isDesignedCadSiblingEntry(entry) {
  if (!entry) return false;
  const name = String(entry.name || entry.viewer_filename || "");
  if (!name || isCatalogHardwareComponent(entry) || isInternalCadSidecar(name)) return false;
  const stem = String(entry.stem || fileStem(name)).toLowerCase();
  if (stem.endsWith("_exploded")) return false;
  return true;
}

/** Multiple millimetre CAD files in one project share a world frame — do not center each one. */
function designedCadSiblingCount() {
  const comps = projectTree?.getComponents?.() || [];
  const stems = new Set();
  for (const entry of comps) {
    if (!isDesignedCadSiblingEntry(entry)) continue;
    const stem = String(entry.stem || fileStem(entry.name || entry.viewer_filename || ""))
      .toLowerCase()
      .replace(/_edited(?:_\d+)?$/i, "");
    if (stem) stems.add(stem);
  }
  return stems.size;
}

function shouldPreserveCadWorldFrame(opts = {}, catalogName = "") {
  if (opts.preservePlacement === true || opts.append === true) return true;
  if (opts.center === false || hasBakedPlacement(catalogName) || hasBakedPlacement(opts.catalogFilename)) return true;
  return designedCadSiblingCount() > 1;
}

function seatAssemblyToFloor() {
  const root = projectAssembly?.getRoot?.();
  if (!root) return;
  // Drop any previous root lift, then seat the current union so appending a
  // millimetre sibling (OpenArm + helmet) keeps one shared frame on the grid.
  root.position.z = 0;
  root.updateMatrixWorld(true);
  try { projectAssembly.invalidateBounds?.(); } catch (_) { }
  const cluster = projectAssembly.boundingBox?.({ force: true });
  const dz = floorDeltaZ(cluster);
  if (dz) {
    root.position.z += dz;
    root.updateMatrixWorld(true);
    try { projectAssembly.invalidateBounds?.(); } catch (_) { }
    return;
  }
  seatObjectToFloor(root);
}

function isFixtureArtifactFilename(name) {
  return /component_mounting_fixture|fixture_base|mounting_plate|mount_plate/i.test(String(name || ""));
}

function getPromptTargetMode() {
  return document.getElementById("prompt-target-mode")?.value === "edit" ? "edit" : "new";
}

function visiblePromptTargetEntries() {
  const entries = (projectTree.getComponents?.() || [])
    .filter((entry) => {
      if (!entry?.name || isBrowserComponentHidden(entry) || isFixtureArtifactFilename(entry.name)) return false;
      const viewer = viewportViewerFor(entry) || entry.viewer_filename || entry.name;
      return projectAssembly.has(entry.name)
        || isViewportViewableFilename(viewer)
        || /\.(step|stp)$/i.test(entry.name);
    });
  if (
    selectedFile
    && !entries.some((entry) => entry.name === selectedFile)
    && !isComponentHidden(selectedFile)
    && !isFixtureArtifactFilename(selectedFile)
    && (projectAssembly.has(selectedFile) || isViewportViewableFilename(selectedFile) || /\.(step|stp)$/i.test(selectedFile))
  ) {
    entries.unshift({
      name: selectedFile,
      stem: fileStem(selectedFile),
      viewer_filename: selectedFile,
    });
  }
  return entries;
}

function promptTargetEntryLabel(entry) {
  return entry?.stem || fileStem(entry?.name || "") || entry?.name || "Object";
}

function promptTargetEntrySubtitle(entry) {
  const fmt = String(entry?.format || entry?.name?.split(".").pop() || "model").toUpperCase();
  const viewer = entry?.viewer_filename && entry.viewer_filename !== entry.name
    ? ` - view ${entry.viewer_filename.split(".").pop()?.toUpperCase()}`
    : "";
  const obj = projectAssembly.get(entry?.name);
  if (!obj) return `${fmt}${viewer}`;
  obj.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(obj);
  if (box.isEmpty()) return `${fmt}${viewer}`;
  const size = box.getSize(new THREE.Vector3());
  const dims = [size.x, size.y, size.z].map((v) => Math.max(0, v).toFixed(v >= 10 ? 0 : 1)).join(" x ");
  return `${fmt}${viewer} - ${dims} mm`;
}

function designModelState() {
  const activeFilename = selectedObjectFilename() || "";
  const entries = visiblePromptTargetEntries();
  const activeIndex = entries.findIndex((entry) => entry.name === activeFilename);
  if (activeIndex > 0) entries.unshift(entries.splice(activeIndex, 1)[0]);
  const targets = entries.map((entry) => ({
    filename: entry.name,
    label: promptTargetEntryLabel(entry),
    subtitle: promptTargetEntrySubtitle(entry),
  }));
  const selectedFilename = activeFilename || document.getElementById("prompt-target-object")?.value || "";
  return {
    selectedFilename: targets.some((item) => item.filename === selectedFilename)
      ? selectedFilename
      : targets[0]?.filename || "",
    targets,
  };
}

function selectDesignModel(filename) {
  const state = designModelState();
  if (!state.targets.some((item) => item.filename === filename)) return false;
  const objectSelect = document.getElementById("prompt-target-object");
  if (objectSelect) objectSelect.value = filename;
  selectAssemblyComponent(filename, { fitView: false });
  return true;
}

function promptTargetBodyInfo(entry) {
  return promptTargetBodyCache.get(entry?.name)?.data || null;
}

async function loadPromptTargetBodyInfo(entry) {
  if (!projectId || !entry?.name) return null;
  const fileName = String(entry.source_filename || entry.parent_filename || entry.name || "")
    .split("#body:")[0]
    .trim();
  if (!fileName) return null;
  const cached = promptTargetBodyCache.get(fileName);
  if (cached?.data || cached?.promise) return cached.data || cached.promise;
  const promise = api(`/api/projects/${projectId}/files/${encodeURIComponent(fileName)}/bodies`)
    .then((data) => {
      promptTargetBodyCache.set(fileName, { data });
      promptTargetBodyCache.set(entry.name, { data });
      return data;
    })
    .catch(() => {
      promptTargetBodyCache.set(fileName, { data: null });
      promptTargetBodyCache.set(entry.name, { data: null });
      return null;
    });
  promptTargetBodyCache.set(fileName, { promise });
  promptTargetBodyCache.set(entry.name, { promise });
  return promise;
}

function refreshPromptTargetBodies(entries = visiblePromptTargetEntries()) {
  const popup = document.getElementById("prompt-target-popup");
  if (!popup || popup.classList.contains("hidden")) return;
  entries.forEach((entry) => {
    if (promptTargetBodyCache.has(entry.name)) return;
    void loadPromptTargetBodyInfo(entry).then(() => {
      if (!popup.classList.contains("hidden")) {
        renderPromptTargetPopup();
        positionPromptTargetPopup();
      }
    });
  });
}

function promptTargetBodies(entry) {
  const info = promptTargetBodyInfo(entry);
  const count = Number(info?.count) || 0;
  if (count <= 1) return [];
  return Array.from({ length: count }, (_, index) => ({
    index,
    name: info?.body_names?.[index] || `Body ${index + 1}`,
  }));
}

function promptTargetBodiesAreCollapsed(entryName, bodyCount) {
  if (bodyCount < 2) return false;
  if (promptTargetBodyListCollapsed.has(entryName)) {
    return !!promptTargetBodyListCollapsed.get(entryName);
  }
  if (String(promptTargetSearch || "").trim()) return false;
  if (promptTargetSelectedBody?.filename === entryName) return false;
  return true;
}

function promptTargetSearchText(entry) {
  const bodyNames = promptTargetBodies(entry).map((body) => body.name).join(" ");
  return `${entry?.name || ""} ${entry?.stem || ""} ${promptTargetEntryLabel(entry)} ${promptTargetEntrySubtitle(entry)} ${bodyNames}`.toLowerCase();
}

function visiblePromptTargetEntriesForSearch(entries) {
  const query = promptTargetSearch.trim().toLowerCase();
  if (!query) return entries;
  return entries.filter((entry) => promptTargetSearchText(entry).includes(query));
}

function firstPromptTargetMesh(root) {
  let found = null;
  root?.traverse?.((child) => {
    if (!found && child.isMesh && child.geometry && !child.userData?.isEdge && !child.userData?.isSilhouette) {
      found = child;
    }
  });
  return found || (root?.isMesh ? root : null);
}

function selectedPromptTargetBodyRef() {
  if (getPromptTargetMode() !== "edit" || !promptTargetSelectedBody?.filename) return null;
  const filename = promptTargetSelectedBody.filename;
  const stem = fileStem(filename);
  return {
    id: `component:${projectId || "project"}:${filename}:body:${promptTargetSelectedBody.bodyIndex}`,
    type: "component",
    token: compactComponentToken(`${stem}-body-${Number(promptTargetSelectedBody.bodyIndex) + 1}`),
    label: promptTargetSelectedBody.bodyName || `Body ${Number(promptTargetSelectedBody.bodyIndex) + 1}`,
    filename,
    stem,
    format: filename.split(".").pop(),
    viewer_filename: filename,
    projectId,
    body_index: promptTargetSelectedBody.bodyIndex,
    body_name: promptTargetSelectedBody.bodyName,
  };
}

function selectedPromptTargetObjectRef() {
  if (getPromptTargetMode() !== "edit") return null;
  const filename = promptBaseFilename();
  if (!filename) return null;
  const stem = fileStem(filename);
  const entry = visiblePromptTargetEntries().find((item) => item.name === filename || item.viewer_filename === filename);
  return {
    id: `component:${projectId || "project"}:${filename}:object`,
    type: "component",
    token: compactComponentToken(stem),
    label: entry ? promptTargetEntryLabel(entry) : stem,
    filename,
    stem,
    format: filename.split(".").pop(),
    viewer_filename: entry?.viewer_filename || filename,
    projectId,
  };
}

function promptReferencesForSubmit() {
  let refs = composer.getReferences();
  if (getPromptTargetMode() !== "edit") {
    const staleAutoRefs = refs.filter(isAutoSelectedObjectReference);
    for (const ref of staleAutoRefs) composer.removeReference(ref.id);
    refs = refs.filter((ref) => !isAutoSelectedObjectReference(ref));
  }
  const bodyRef = selectedPromptTargetBodyRef();
  const objectRef = selectedPromptTargetObjectRef();
  const additions = [objectRef, bodyRef, ...(getPromptTargetMode() === "edit" ? buildSelectedPromptLinks() : [])].filter(Boolean);
  return mergePromptGeometryReferences(refs, additions).map((ref) => {
    if (ref.geometry_context) return ref;
    const root = projectAssembly.get(ref.filename) || projectAssembly.get(ref.viewer_filename);
    const context = modelGeometryContext(root);
    return context ? { ...ref, geometry_context: context } : ref;
  });
}

function resolveRenderGeometryTarget(promptReferences = []) {
  const componentRefs = (promptReferences || []).filter((ref) => {
    const type = String(ref?.type || "").toLowerCase();
    return ["component", "face", "edge", "corner", "lasso", "path"].includes(type) && (ref.filename || ref.viewer_filename);
  });
  for (const ref of componentRefs) {
    const candidates = [ref.filename, ref.viewer_filename].filter(Boolean);
    for (const name of candidates) {
      if (projectAssembly.has(name)) {
        return {
          filename: name,
          ref,
          object: projectAssembly.get(name),
        };
      }
    }
  }
  const fallback = currentModelFilenameForRenderTexture();
  return fallback && projectAssembly.has(fallback)
    ? { filename: fallback, ref: null, object: projectAssembly.get(fallback) }
    : { filename: fallback || null, ref: null, object: null };
}

function prepareLinkedGeometryForRender(promptReferences = []) {
  const target = resolveRenderGeometryTarget(promptReferences);
  if (!target.object || !target.filename) return target;
  projectAssembly.setVisible(target.filename, true);
  selectedFile = target.filename;
  projectTree.setSelected(target.filename);
  featureEditor.setModel(projectId, target.filename);
  // Keep the user's camera. Re-homing to the Fusion iso view flipped facing
  // and made photoreal + texture wrap miss the exact viewport model.
  controls?.update?.();
  return target;
}

function promptTargetColor(entry) {
  const seed = String(entry?.name || entry?.stem || "object");
  let hash = 0;
  for (let i = 0; i < seed.length; i++) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  return ["#58a6ff", "#3fb950", "#d29922", "#a371f7", "#f778ba", "#56d4dd"][hash % 6];
}

function drawPromptTargetThumb(canvas, entry, active = false, opts = {}) {
  const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2));
  const w = opts.topDown ? 56 : 68;
  const h = opts.topDown ? 48 : 52;
  canvas.width = Math.round(w * dpr);
  canvas.height = Math.round(h * dpr);
  canvas.style.width = `${w}px`;
  canvas.style.height = `${h}px`;
  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);
  const accent = promptTargetColor(entry);
  if (opts.topDown) {
    ctx.fillStyle = "#e8eaed";
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = active ? "#58a6ff" : "rgba(48,54,61,0.45)";
    ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
  } else {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, active ? "rgba(88,166,255,0.28)" : "rgba(88,166,255,0.12)");
    grad.addColorStop(1, "rgba(13,17,23,0.92)");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = active ? "#58a6ff" : "rgba(139,148,158,0.35)";
    ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
  }

  let sx = 34;
  let sy = 20;
  let sz = 16;
  const obj = projectAssembly.get(entry?.name);
  if (obj) {
    obj.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(obj);
    if (!box.isEmpty()) {
      const size = box.getSize(new THREE.Vector3());
      const max = Math.max(size.x, size.y, size.z, 1);
      sx = Math.max(10, (size.x / max) * 38);
      sy = Math.max(8, (size.y / max) * 24);
      sz = Math.max(8, (size.z / max) * 28);
    }
  }
  if (opts.topDown) {
    const maxXY = Math.max(sx, sy, 1);
    const bw = Math.max(16, (sx / maxXY) * (w - 12));
    const bh = Math.max(12, (sy / maxXY) * (h - 14));
    const x = (w - bw) / 2;
    const y = (h - bh) / 2 - 1;
    ctx.fillStyle = accent;
    ctx.fillRect(x, y, bw, bh);
    ctx.strokeStyle = "rgba(22, 27, 34, 0.45)";
    ctx.strokeRect(x + 0.5, y + 0.5, bw - 1, bh - 1);
    ctx.fillStyle = "rgba(13, 17, 23, 0.55)";
    ctx.fillRect(x + bw * 0.28, y + bh * 0.28, bw * 0.44, bh * 0.44);
    return;
  }
  const cx = 34;
  const cy = 31;
  const dx = sx * 0.45;
  const dy = sy * 0.35;
  const top = [[cx - dx, cy - sz * 0.5 - dy], [cx, cy - sz * 0.5 - dy * 1.8], [cx + dx, cy - sz * 0.5 - dy], [cx, cy - sz * 0.5]];
  const right = [top[2], [top[2][0], top[2][1] + sz], [top[3][0], top[3][1] + sz], top[3]];
  const left = [top[0], top[3], [top[3][0], top[3][1] + sz], [top[0][0], top[0][1] + sz]];
  const poly = (pts, fill) => {
    ctx.beginPath();
    pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.strokeStyle = "rgba(255,255,255,0.16)";
    ctx.stroke();
  };
  poly(left, "rgba(88,166,255,0.28)");
  poly(right, "rgba(163,113,247,0.22)");
  poly(top, accent);
  ctx.fillStyle = "rgba(255,255,255,0.78)";
  ctx.font = "700 10px system-ui, sans-serif";
  ctx.textAlign = "right";
  ctx.fillText(String(entry?.format || entry?.name?.split(".").pop() || "3D").toUpperCase().slice(0, 4), w - 6, h - 6);
}

function renderPromptTargetThumb(target, entry, active = false) {
  if (!target) return;
  target.innerHTML = "";
  if (!entry) return;
  const canvas = document.createElement("canvas");
  drawPromptTargetThumb(canvas, entry, active);
  target.appendChild(canvas);
}

promptTargetPreview = {
  name: null,
  saved: null,
  center: new THREE.Vector3(),
  radius: 1,
  angle: 0,
  active: false,
};

function savePromptTargetPreviewCamera() {
  if (promptTargetPreview.saved) return;
  promptTargetPreview.saved = {
    position: camera.position.clone(),
    target: controls.target.clone(),
    up: camera.up.clone(),
  };
}

function syncControlsAfterCameraMove() {
  camera.lookAt(controls.target);
  controls._up0?.copy(camera.up);
  controls._position0?.copy(camera.position);
  controls._target0?.copy(controls.target);
  controls._eye?.subVectors(camera.position, controls.target);
  controls._lastAngle = 0;
  controls.update();
  viewCube.update?.();
}

function framePromptTargetPreview(obj) {
  obj.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(obj);
  if (box.isEmpty()) return false;
  const size = box.getSize(new THREE.Vector3()).length() || 1;
  const center = box.getCenter(new THREE.Vector3());
  const radius = Math.max(size * 0.5, 0.1);
  const halfFovRad = (camera.fov * Math.PI) / 360;
  const dist = Math.max((radius / Math.tan(halfFovRad)) * 1.05, 0.15);
  promptTargetPreview.center.copy(center);
  promptTargetPreview.radius = dist;
  promptTargetPreview.angle = Math.atan2(camera.position.y - center.y, camera.position.x - center.x) || -0.8;
  controls.target.copy(center);
  camera.up.copy(VIEW_CUBE_WORLD_UP);
  camera.position.set(
    center.x + Math.cos(promptTargetPreview.angle) * dist,
    center.y + Math.sin(promptTargetPreview.angle) * dist,
    center.z + dist * 0.42
  );
  syncControlsAfterCameraMove();
  return true;
}

function beginPromptTargetPreview(name) {
  if (!name || promptTargetPreview.name === name) return;
  const obj = projectAssembly.get(name);
  if (!obj) return;
  savePromptTargetPreviewCamera();
  promptTargetPreview.name = name;
  promptTargetPreview.active = framePromptTargetPreview(obj);
  document.querySelectorAll(".prompt-target-card").forEach((card) => {
    card.classList.toggle("previewing", card.dataset.promptTargetName === name);
  });
}

function endPromptTargetPreview({ restore = true } = {}) {
  if (restore && promptTargetPreview.saved) {
    camera.position.copy(promptTargetPreview.saved.position);
    controls.target.copy(promptTargetPreview.saved.target);
    camera.up.copy(promptTargetPreview.saved.up);
    syncControlsAfterCameraMove();
  }
  promptTargetPreview.name = null;
  promptTargetPreview.saved = null;
  promptTargetPreview.active = false;
  document.querySelectorAll(".prompt-target-card.previewing").forEach((card) => card.classList.remove("previewing"));
}

function commitPromptTargetPreview() {
  endPromptTargetPreview({ restore: false });
}

function choosePromptTargetObject(name, bodyIndex = null) {
  if (!name) return;
  const objectSelect = document.getElementById("prompt-target-object");
  if (objectSelect) objectSelect.value = name;
  selectedFile = name;
  projectTree.setSelected(name);
  featureEditor.setModel(projectId, name);
  selectAssemblyComponent(name, { fitView: false });
  if (Number.isInteger(bodyIndex)) {
    const entry = visiblePromptTargetEntries().find((candidate) => candidate.name === name);
    const body = promptTargetBodies(entry).find((candidate) => candidate.index === bodyIndex);
    promptTargetSelectedBody = {
      filename: name,
      bodyIndex,
      bodyName: body?.name || `Body ${bodyIndex + 1}`,
    };
    const root = projectAssembly.get(name) || currentMesh;
    const mesh = firstPromptTargetMesh(root);
    if (mesh && root) {
      objectTools.selectObject?.({ mesh, root, bodyIndex, catalogName: name });
    }
    setEditStatus("ok", `Editing ${promptTargetSelectedBody.bodyName} in ${promptTargetEntryLabel(entry)}.`);
  } else {
    promptTargetSelectedBody = null;
  }
  commitPromptTargetPreview();
  closePromptTargetPopup({ restorePreview: false });
  syncPromptTargetUI();
  if (pendingCadRigPick) {
    pendingCadRigPick = false;
    cadComposeRigging = true;
    syncCadComposeRiggingUi();
    document.getElementById("prompt-input")?.focus?.();
    composer?.editor?.focus?.();
    setEditStatus("ok", `Rigging ${name}. Describe the motion, then Generate.`);
    if (!restoringModelPromptState) saveActiveModelPromptState();
  }
}

function closePromptTargetPopup({ restorePreview = true } = {}) {
  if (restorePreview) endPromptTargetPreview();
  const popup = document.getElementById("prompt-target-popup");
  const trigger = document.getElementById("prompt-target-picker-btn");
  popup?.classList.add("hidden");
  trigger?.setAttribute("aria-expanded", "false");
}

function positionPromptTargetPopup() {
  const popup = document.getElementById("prompt-target-popup");
  const trigger = document.getElementById("prompt-target-picker-btn");
  if (!popup || !trigger) return;
  const rect = trigger.getBoundingClientRect();
  const width = Math.min(420, window.innerWidth - 18);
  let left = Math.min(window.innerWidth - width - 8, Math.max(8, rect.right - width));
  let top = rect.bottom + 8;
  const height = Math.min(520, popup.offsetHeight || 420);
  if (top + height > window.innerHeight - 8) top = Math.max(8, rect.top - height - 8);
  popup.style.width = `${width}px`;
  popup.style.left = `${left}px`;
  popup.style.top = `${top}px`;
}

function renderPromptTargetPopup() {
  const popup = document.getElementById("prompt-target-popup");
  if (!popup) return;
  const allEntries = visiblePromptTargetEntries();
  const entries = visiblePromptTargetEntriesForSearch(allEntries);
  const current = document.getElementById("prompt-target-object")?.value || selectedFile || entries[0]?.name || "";
  popup.innerHTML = "";
  const header = document.createElement("div");
  header.className = "prompt-target-popup-header";
  header.innerHTML = `<div><strong>Select object/body to edit</strong><span>Search components and bodies. Hover a component to preview it.</span></div><button type="button" class="prompt-target-popup-close" aria-label="Close">x</button>`;
  header.querySelector("button")?.addEventListener("click", closePromptTargetPopup);
  popup.appendChild(header);
  const searchWrap = document.createElement("div");
  searchWrap.className = "prompt-target-search";
  searchWrap.innerHTML = `
    <span aria-hidden="true">⌕</span>
    <input type="search" id="prompt-target-search-input" placeholder="Search bodies, objects, filenames..." value="${appEscapeHtml(promptTargetSearch)}" />
    ${promptTargetSearch ? '<button type="button" class="prompt-target-search-clear" aria-label="Clear search">x</button>' : ""}
  `;
  const searchInput = searchWrap.querySelector("input");
  searchInput?.addEventListener("input", (event) => {
    promptTargetSearch = event.currentTarget.value;
    renderPromptTargetPopup();
    positionPromptTargetPopup();
    requestAnimationFrame(() => {
      const next = document.getElementById("prompt-target-search-input");
      next?.focus();
      next?.setSelectionRange(promptTargetSearch.length, promptTargetSearch.length);
    });
  });
  searchWrap.querySelector(".prompt-target-search-clear")?.addEventListener("click", () => {
    promptTargetSearch = "";
    renderPromptTargetPopup();
    positionPromptTargetPopup();
    requestAnimationFrame(() => document.getElementById("prompt-target-search-input")?.focus());
  });
  popup.appendChild(searchWrap);
  const list = document.createElement("div");
  list.className = "prompt-target-popup-list";
  if (!entries.length) {
    const empty = document.createElement("p");
    empty.className = "prompt-target-popup-empty";
    empty.textContent = allEntries.length
      ? "No matching objects or bodies."
      : "No visible objects available. Show a component in the Browser first.";
    list.appendChild(empty);
  }
  for (const entry of entries) {
    const selectedBodyMatches = promptTargetSelectedBody?.filename === entry.name;
    const active = entry.name === current && !selectedBodyMatches;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = `prompt-target-card${active ? " active" : ""}`;
    btn.dataset.promptTargetName = entry.name;
    btn.title = entry.name;
    const thumb = document.createElement("span");
    thumb.className = "prompt-target-card-thumb";
    renderPromptTargetThumb(thumb, entry, active);
    const info = document.createElement("span");
    info.className = "prompt-target-card-info";
    const name = document.createElement("strong");
    name.textContent = promptTargetEntryLabel(entry);
    const meta = document.createElement("small");
    meta.textContent = promptTargetEntrySubtitle(entry);
    const file = document.createElement("em");
    file.textContent = entry.name;
    info.append(name, meta, file);
    const check = document.createElement("span");
    check.className = "prompt-target-card-check";
    check.textContent = active ? "Selected" : "Choose";
    btn.append(thumb, info, check);
    list.appendChild(btn);
    const bodies = promptTargetBodies(entry);
    if (bodies.length) {
      const collapsed = promptTargetBodiesAreCollapsed(entry.name, bodies.length);
      const bodyWrap = document.createElement("div");
      bodyWrap.className = `prompt-target-body-list${collapsed ? " is-collapsed" : ""}`;
      const toggle = document.createElement("button");
      toggle.type = "button";
      toggle.className = "prompt-target-body-toggle";
      toggle.dataset.promptTargetBodiesToggle = entry.name;
      toggle.dataset.bodyCount = String(bodies.length);
      toggle.setAttribute("aria-expanded", String(!collapsed));
      toggle.title = collapsed ? "Show bodies" : "Hide bodies";
      toggle.innerHTML = `
        <span class="prompt-target-body-toggle-chevron" aria-hidden="true">${collapsed ? "▸" : "▾"}</span>
        <span>${bodies.length} ${bodies.length === 1 ? "body" : "bodies"}</span>
        <span class="prompt-target-body-toggle-hint">${collapsed ? "Show" : "Hide"}</span>
      `;
      bodyWrap.appendChild(toggle);
      if (!collapsed) {
        bodies.forEach((body) => {
          const bodyActive = promptTargetSelectedBody?.filename === entry.name && promptTargetSelectedBody?.bodyIndex === body.index;
          const bodyBtn = document.createElement("button");
          bodyBtn.type = "button";
          bodyBtn.className = `prompt-target-body-card${bodyActive ? " active" : ""}`;
          bodyBtn.dataset.promptTargetName = entry.name;
          bodyBtn.dataset.promptTargetBodyIndex = String(body.index);
          bodyBtn.innerHTML = `
            <span class="prompt-target-body-badge">Body ${body.index + 1}</span>
            <span class="prompt-target-body-name">${appEscapeHtml(body.name)}</span>
            <span class="prompt-target-body-action">${bodyActive ? "Selected" : "Edit body"}</span>
          `;
          bodyWrap.appendChild(bodyBtn);
        });
      }
      list.appendChild(bodyWrap);
    } else if (!promptTargetBodyCache.get(entry.name)) {
      const loading = document.createElement("div");
      loading.className = "prompt-target-body-loading";
      loading.textContent = "Checking bodies...";
      list.appendChild(loading);
    }
  }
  popup.appendChild(list);
  refreshPromptTargetBodies(allEntries);
}

function openPromptTargetPopup() {
  const popup = document.getElementById("prompt-target-popup");
  const trigger = document.getElementById("prompt-target-picker-btn");
  if (!popup || !trigger) return;
  renderPromptTargetPopup();
  popup.classList.remove("hidden");
  trigger.setAttribute("aria-expanded", "true");
  positionPromptTargetPopup();
}

function togglePromptTargetPopup() {
  const popup = document.getElementById("prompt-target-popup");
  if (!popup || popup.classList.contains("hidden")) openPromptTargetPopup();
  else closePromptTargetPopup();
}

function syncPromptTargetUI() {
  const select = document.getElementById("prompt-target-mode");
  const objectSelect = document.getElementById("prompt-target-object");
  const pickerBtn = document.getElementById("prompt-target-picker-btn");
  const pickerTitle = document.getElementById("prompt-target-picker-title");
  const pickerSubtitle = document.getElementById("prompt-target-picker-subtitle");
  const pickerThumb = document.getElementById("prompt-target-picker-thumb");
  const entries = visiblePromptTargetEntries();
  const targetControlsEnabled = ["standard", "v2", "mesh"].includes(promptMode);
  const canEdit = targetControlsEnabled && entries.length > 0;
  if (select) {
    select.disabled = !targetControlsEnabled;
    select.querySelector("option[value='edit']")?.toggleAttribute("disabled", !canEdit);
    // Keep Edit selected when empty: submission must block instead of silently creating.
  }
  if (objectSelect) {
    const current = entries.some((entry) => entry.name === objectSelect.value)
      ? objectSelect.value
      : entries.some((entry) => entry.name === selectedFile)
        ? selectedFile
        : latestEditableTarget(entries, lastProjectFiles)?.name || "";
    objectSelect.innerHTML = "";
    for (const entry of entries) {
      const option = document.createElement("option");
      option.value = entry.name;
      option.textContent = promptTargetEntryLabel(entry);
      option.title = entry.name;
      objectSelect.appendChild(option);
    }
    objectSelect.value = current;
    objectSelect.disabled = !canEdit || getPromptTargetMode() !== "edit";
    objectSelect.hidden = true;
  }
  const editing = select?.value === "edit" && canEdit;
  const currentEntry = entries.find((entry) => entry.name === objectSelect?.value) || entries[0];
  if (promptTargetSelectedBody && promptTargetSelectedBody.filename !== currentEntry?.name) {
    promptTargetSelectedBody = null;
  }
  if (pickerBtn) {
    pickerBtn.hidden = !editing;
    pickerBtn.disabled = !editing;
  }
  if (pickerTitle) {
    pickerTitle.textContent = editing && currentEntry
      ? (promptTargetSelectedBody?.bodyName || promptTargetEntryLabel(currentEntry))
      : "Select object";
  }
  if (pickerSubtitle) {
    pickerSubtitle.textContent = editing && currentEntry
      ? promptTargetSelectedBody
        ? `${promptTargetEntryLabel(currentEntry)} - body ${Number(promptTargetSelectedBody.bodyIndex) + 1}`
        : promptTargetEntrySubtitle(currentEntry)
      : `${entries.length} visible component${entries.length === 1 ? "" : "s"}`;
  }
  renderPromptTargetThumb(pickerThumb, currentEntry, true);
  if (!editing) closePromptTargetPopup();
  else if (!document.getElementById("prompt-target-popup")?.classList.contains("hidden")) {
    renderPromptTargetPopup();
    positionPromptTargetPopup();
  }
}

function ensurePromptEditSelection() {
  if (getPromptTargetMode() !== "edit") return null;
  const entries = visiblePromptTargetEntries();
  const picked = objectTools?.getSelection?.();
  const refs = composer?.getReferences?.() || [];
  const referenced = refs.find((r) => ["face", "edge", "vertex", "corner", "lasso", "path"].includes(r.type) && r.filename);
  const name = (picked?.catalogName && entries.some((e) => e.name === picked.catalogName) ? picked.catalogName : null)
    || (referenced && entries.find((e) => e.name === referenced.filename)?.name)
    || latestEditableTarget(entries, lastProjectFiles)?.name;
  if (!name) return null;
  const targetSelect = document.getElementById("prompt-target-object");
  if (targetSelect) targetSelect.value = name;
  if (!picked && !referenced) selectAssemblyComponent(name, { fitView: false });
  selectedFile = name;
  return name;
}

function promptBaseFilename({ canvasAttached = false } = {}) {
  if (getPromptTargetMode() !== "edit") return null;
  const chosen = document.getElementById("prompt-target-object")?.value || selectedFile;
  if (!chosen || isComponentHidden(chosen) || isFixtureArtifactFilename(chosen)) return null;
  return chosen;
}

/** Prefer explicit edit target; fall back to face/component @refs so Mode 2.0 revises the viewport object. */
function resolvePromptEditTarget(promptReferences = [], { canvasAttached = false } = {}) {
  let targetMode = getPromptTargetMode();
  let baseFilename = promptBaseFilename({ canvasAttached });
  const surfaceTypes = new Set(["face", "edge", "vertex", "corner", "lasso", "path", "line", "component"]);
  const refWithFile = (promptReferences || []).find(
    (ref) => ref?.filename && surfaceTypes.has(String(ref.type || "").toLowerCase())
  );
  const hasSurfaceRef = (promptReferences || []).some((ref) =>
    ["face", "edge", "vertex", "corner", "lasso", "path", "line"].includes(String(ref.type || "").toLowerCase())
  );
  if (!baseFilename && refWithFile?.filename) {
    baseFilename = refWithFile.filename;
  }
  if (!baseFilename && selectedFile && !isComponentHidden(selectedFile) && !isFixtureArtifactFilename(selectedFile)) {
    if (targetMode === "edit" || hasSurfaceRef) baseFilename = selectedFile;
  }
  if ((hasSurfaceRef || baseFilename) && (hasSurfaceRef || targetMode === "edit")) {
    targetMode = "edit";
  }
  return { targetMode, baseFilename };
}

function annotatePickedReference(ref) {
  if (!ref || !selectedFile) return ref;
  return {
    ...ref,
    filename: ref.filename || selectedFile,
    viewer_filename: ref.viewer_filename || selectedFile,
    projectId: ref.projectId || projectId,
  };
}

function allowAutoUpsideDownFlip(filename = "") {
  const ext = String(filename || "").split(".").pop()?.toLowerCase() || "";
  // GLB/GLTF files can carry explicit authoring transforms/material scene roots.
  // A footprint guess is too aggressive for robot arms and often flips them.
  // Fusion tessellated STEP is Z-up; still allow a base flip when the AABB is inverted.
  if (isFusionAuthoredModel(filename)) return true;
  return ext !== "glb" && ext !== "gltf";
}

/** Slug used to match Fusion item names to local stems (`House Framing` → `house_framing`). */
function fusionSourceStem(value = "") {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

/** True when `stem` is the Fusion source model or a derived sibling/part. */
function stemMatchesFusionSource(stem, src) {
  if (!stem || !src) return false;
  return (
    stem === src
    || stem.startsWith(`${src}_`)
    || stem.startsWith(`${src}__`)
    || stem.startsWith(`${src}.`)
  );
}

/** Fusion/APS imports: `.autodesk_source_*` or project fusion_source. Tessellated STEP is Z-up. */
function isFusionAuthoredModel(filename = "") {
  const raw = String(filename || "").split("#body:")[0].trim();
  if (!raw) return false;
  if (/autodesk_source/i.test(raw)) return true;
  const stem = raw
    .replace(/\.[^.]+$/, "")
    .toLowerCase()
    .replace(/\.part$/i, "")
    .replace(/__part_.*$/i, "");
  if (!stem) return false;
  const names = (lastProjectFiles || []).map((f) => String(typeof f === "string" ? f : f?.name || ""));
  if (names.some((name) => {
    const m = String(name).match(/^\.autodesk_source_(.+)\.(step|stp|glb|gltf)$/i);
    if (!m) return false;
    return stemMatchesFusionSource(stem, String(m[1] || "").toLowerCase());
  })) {
    return true;
  }
  const src = lastProjectFusionSource;
  if (!src || typeof src !== "object") return false;
  // Prefer explicit local/import stem when present; fall back to item name slug.
  const candidates = [
    fusionSourceStem(src.local_stem || src.local_filename || ""),
    fusionSourceStem(src.item_name || ""),
  ].filter(Boolean).map((s) => s.replace(/\.(step|stp|glb|gltf)$/i, ""));
  return candidates.some((c) => stemMatchesFusionSource(stem, c));
}

function ensureModelZUp(object3d, filename = "") {
  /**
   * LOCKED — Jul 16 axis heuristic (do not bring back footprint ±90° scoring).
   * Rotate clear Y-up meshes into Render3D's Z-up viewport. Leave already-Z-up
   * models alone — the old footprint tipper laid bikes/long assemblies on their side.
   * Exception: do not special-case Fusion length-along-X (that +90° tipped
   * already-Z-up Fusion STEP assemblies onto their side / “turned left”).
   * Fusion files still get rotateX(+90°) when they are clearly Y-up (tallest=Y).
   * See `.cursor/rules/model-upright-orientation.mdc`.
   */
  if (!object3d) return false;
  if (object3d.userData?.render3dZUp) return false;
  object3d.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object3d);
  if (box.isEmpty()) return false;
  const size = box.getSize(new THREE.Vector3());
  const sx = Math.abs(size.x);
  const sy = Math.abs(size.y);
  const sz = Math.abs(size.z);
  const max = Math.max(sx, sy, sz);
  if (!(max > 0)) return false;

  let rotated = false;

  // Floor plates / chassis: Z is up but short, and XY is a real plan (not a skinny
  // standing silhouette). Must run BEFORE "tallest is Y" — VibeCAD STEP GLBs are
  // already Z-up and often longest in Y, so that check used to rotateX(90°) and
  // lay them on their side ("turned left").
  const minXy = Math.min(sx, sy);
  const maxXy = Math.max(sx, sy);
  const zUpFloorPlate = sz < minXy * 0.5 && minXy / (maxXy || 1) > 0.45;

  if (sz >= max * 0.99) {
    // Already standing in Z-up (height along Z) — includes Fusion STEP tessellations.
    rotated = false;
  } else if (zUpFloorPlate) {
    return false;
  } else if (sy >= max * 0.99) {
    // Tallest axis is Y → classic Y-up standing model (glTF / some APS viewers).
    object3d.rotateX(Math.PI / 2);
    rotated = true;
  } else if (sz < Math.min(sx, sy) * 0.5) {
    // Flat Z-up plate/gear on the XY floor (thin Z vs both plan extents).
    return false;
  } else if (max <= 25 && sy >= sz * 0.98) {
    object3d.rotateX(Math.PI / 2);
    rotated = true;
  } else if (sy > sz * 1.12 && sy >= sx * 0.9) {
    object3d.rotateX(Math.PI / 2);
    rotated = true;
  }

  if (rotated) {
    object3d.updateMatrixWorld(true);
    // If the wider footprint ended up on +Z, flip 180° so the base sits down.
    if (allowAutoUpsideDownFlip(filename) && footprintPrefersFlip180(object3d)) {
      object3d.rotateX(Math.PI);
      object3d.updateMatrixWorld(true);
    }
    object3d.userData.render3dZUp = true;
    object3d.userData.render3dZUpSource = filename || true;
    if (isFusionAuthoredModel(filename)) object3d.userData.render3dFusionYUp = true;
    return true;
  }

  // Already Z-up-ish but possibly inverted (base on +Z).
  if (allowAutoUpsideDownFlip(filename) && sz >= sy * 0.9 && footprintPrefersFlip180(object3d)) {
    object3d.rotateX(Math.PI);
    object3d.updateMatrixWorld(true);
    object3d.userData.render3dZUp = true;
    object3d.userData.render3dZUpSource = filename || true;
    return true;
  }
  return false;
}

/** Rough base-vs-top footprint test using the world AABB corners of child geometries. */
function footprintPrefersFlip180(object3d) {
  object3d.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object3d);
  if (box.isEmpty()) return false;
  const size = box.getSize(new THREE.Vector3());
  if (!(size.z > 1e-9)) return false;
  const tol = size.z * 0.04;
  let minArea = 0;
  let maxArea = 0;
  object3d.traverse((child) => {
    if (!child.isMesh || !child.geometry) return;
    const pos = child.geometry.attributes?.position;
    if (!pos) return;
    const v = new THREE.Vector3();
    let minSpanX = 0; let minSpanY = 0; let minCount = 0;
    let maxSpanX = 0; let maxSpanY = 0; let maxCount = 0;
    let minMinX = Infinity; let minMaxX = -Infinity; let minMinY = Infinity; let minMaxY = -Infinity;
    let maxMinX = Infinity; let maxMaxX = -Infinity; let maxMinY = Infinity; let maxMaxY = -Infinity;
    for (let i = 0; i < pos.count; i++) {
      v.fromBufferAttribute(pos, i).applyMatrix4(child.matrixWorld);
      if (Math.abs(v.z - box.min.z) <= tol) {
        minCount += 1;
        minMinX = Math.min(minMinX, v.x); minMaxX = Math.max(minMaxX, v.x);
        minMinY = Math.min(minMinY, v.y); minMaxY = Math.max(minMaxY, v.y);
      }
      if (Math.abs(v.z - box.max.z) <= tol) {
        maxCount += 1;
        maxMinX = Math.min(maxMinX, v.x); maxMaxX = Math.max(maxMaxX, v.x);
        maxMinY = Math.min(maxMinY, v.y); maxMaxY = Math.max(maxMaxY, v.y);
      }
    }
    if (minCount >= 8) {
      minSpanX = minMaxX - minMinX; minSpanY = minMaxY - minMinY;
      const mn = Math.min(minSpanX, minSpanY);
      const mx = Math.max(minSpanX, minSpanY) || 1;
      minArea += mn * (1 - Math.abs(minSpanX - minSpanY) / mx);
    }
    if (maxCount >= 8) {
      maxSpanX = maxMaxX - maxMinX; maxSpanY = maxMaxY - maxMinY;
      const mn = Math.min(maxSpanX, maxSpanY);
      const mx = Math.max(maxSpanX, maxSpanY) || 1;
      maxArea += mn * (1 - Math.abs(maxSpanX - maxSpanY) / mx);
    }
  });
  return maxArea > minArea * 1.05 && maxArea > 1e-8;
}

/** Lift/drop so the visible-mesh AABB base sits on the grid plane (z = 0). */
function seatObjectToFloor(object3d) {
  if (!object3d) return;
  object3d.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object3d);
  if (!isTightFrameBox(box)) return;
  const dz = floorDeltaZ({ min: box.min, max: box.max });
  if (!dz) return;
  object3d.position.z += dz;
  object3d.updateMatrixWorld(true);
}

function materializeObject(object3d, {
  center = true,
  normalizePivot = center,
  // Always floor-seat unless restoring an explicit saved world transform.
  // Edited/copied parts used to skip centering entirely and stayed origin-centered
  // (half under the grid) even when upright.
  seatToFloor = true,
  filename = "",
  orient = true,
  orientationMode = null,
  styleMode = "auto",
  skipEdges = false,
} = {}) {
  // Jake GLBs are accepted from STEP in +Z-up. Preserve that authored frame;
  // bounds inference can mistake a wide assembly for Y-up and tip it 90°.
  // Mesh/img2threejs GLBs are converted to Z-up in export_glb.mjs. Do not run
  // the CAD heuristic on them (it tipped plates/vehicles) and do not shift
  // child pivots (that breaks skinned-character binds).
  const meshAuthored = hasMeshFactorySibling(filename) || prefersAuthoredShading(object3d, filename);
  captureSourceFrames(object3d);
  const vibecadAuthored = hasVibecadSourceSibling(filename);
  const authoredCadZUp = shouldTrustAuthoredCadZUp(orientationMode);
  if (meshAuthored || vibecadAuthored || authoredCadZUp) {
    object3d.userData.render3dZUp = object3d.userData.render3dZUp || true;
  }
  if (!meshAuthored && !vibecadAuthored && !authoredCadZUp && orient) {
    ensureModelZUp(object3d, filename);
  }
  object3d.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object3d);
  meshCenterOffset = isTightFrameBox(box) ? box.getCenter(new THREE.Vector3()) : new THREE.Vector3();
  object3d.userData.meshCenterOffset = meshCenterOffset.clone();
  if (center && isTightFrameBox(box)) {
    // Z-up CAD: center in X/Y. Skip a collapsed axis (Inf bbox sanitized to 0)
    // so centering cannot slide the solid by a dummy 0-span.
    const size = box.getSize(new THREE.Vector3());
    const maxSpan = Math.max(Math.abs(size.x), Math.abs(size.y), Math.abs(size.z), 0);
    const collapse = Math.max(maxSpan * 1e-6, 1e-9);
    if (Math.abs(size.x) > collapse && Number.isFinite(meshCenterOffset.x)) {
      object3d.position.x -= meshCenterOffset.x;
    }
    if (Math.abs(size.y) > collapse && Number.isFinite(meshCenterOffset.y)) {
      object3d.position.y -= meshCenterOffset.y;
    }
    object3d.updateMatrixWorld(true);
  }
  if (normalizePivot && !meshAuthored) {
    normalizeObjectPivotToBounds(object3d);
  }
  if (seatToFloor) {
    seatObjectToFloor(object3d);
  }
  const resolvedStyle = resolveViewportStyleMode(object3d, filename, styleMode);
  cachePresentationBounds(object3d);
  try {
    object3d.userData.catalogName = filename || object3d.userData.catalogName || "";
    object3d.name = object3d.name || String(filename || "").replace(/\.[^.]+$/, "") || object3d.name;
  } catch (_) { }
  // XR: skip crease wireframe — EdgesGeometry / LineSegments2 froze Quest on enter.
  const xrPresenting = !!(typeof viewportXR !== "undefined" && viewportXR?.isPresenting?.());
  if (xrPresenting) {
    try { setXrSkipCadExtras(true); } catch (_) { }
  }
  applyViewportStyle(object3d, {
    filename,
    styleMode: resolvedStyle,
    syncViewportLights: true,
    skipCadExtras: xrPresenting,
    skipEdges: skipEdges && !xrPresenting,
  });
  if (!xrPresenting) {
    // Desktop only: mixed assemblies may use look-dev (env maps disabled globally).
    try {
      let anyAuthored = resolvedStyle === "shaded" || resolvedStyle === "authored" || resolvedStyle === "pbr";
      if (!anyAuthored && typeof projectAssembly?.list === "function") {
        for (const [name, obj] of projectAssembly.list()) {
          if (obj === object3d) continue;
          if (hasMeshFactorySibling(name) || prefersAuthoredShading(obj, name)) {
            anyAuthored = true;
            break;
          }
        }
      }
      if (anyAuthored) setViewportShadingMode("lookdev");
      // Lights + clearColor only — never dispose meshes or refetch the GLB.
      applySavedViewportLook({ persist: false });
    } catch {
      /* lighting slider / assembly optional during early boot */
    }
  }
  // Silhouette/edge helpers can slightly expand the AABB — re-seat so the solid base stays on z = 0.
  if (seatToFloor) {
    seatObjectToFloor(object3d);
  }
  positionShadowFloor(scene, object3d);
  captureMaterializedSourceFrame(object3d);
  return object3d;
}

function resolveViewportStyleMode(object3d, filename = "", styleMode = "auto") {
  const explicit = String(styleMode || "auto").toLowerCase();
  if (explicit === "cad" || explicit === "shaded" || explicit === "authored" || explicit === "pbr") {
    return explicit === "authored" || explicit === "pbr" ? "shaded" : explicit;
  }
  if (isCatalogHardwareComponent({ name: filename })) {
    return "shaded";
  }
  if (hasMeshFactorySibling(filename) || prefersAuthoredShading(object3d, filename)) {
    return "shaded";
  }
  return "cad";
}

function hasVibecadSourceSibling(filename = "") {
  const rel = String(filename || "").replace(/\\/g, "/");
  if (/^vibecad\//i.test(rel)) return true;
  const base = rel.includes("/") ? rel.slice(rel.lastIndexOf("/") + 1) : rel;
  const stem = fileStemName(base || "");
  if (!stem) return false;
  const candidates = new Set([stem]);
  const withoutEdit = stem.replace(/_edited(?:_\d+)?$/i, "");
  if (withoutEdit) candidates.add(withoutEdit);
  const withoutCopy = withoutEdit.replace(/_copy\d*$/i, "") || stem.replace(/_copy\d*$/i, "");
  if (withoutCopy) candidates.add(withoutCopy);
  for (const c of [...candidates]) {
    const bare = c.replace(/\.vibecad$/i, "");
    if (bare) candidates.add(bare);
  }
  const names = new Set();
  for (const f of lastProjectFiles || []) {
    if (f?.name) names.add(String(f.name).replace(/\\/g, "/"));
  }
  try {
    for (const entry of projectTree?.getComponents?.() || []) {
      if (entry?.name) names.add(String(entry.name).replace(/\\/g, "/"));
      if (entry?.viewer_filename) names.add(String(entry.viewer_filename).replace(/\\/g, "/"));
      if (entry?.source) names.add(String(entry.source).replace(/\\/g, "/"));
    }
  } catch {
    /* tree optional */
  }
  const suffixes = [".vibecad.py", ".vibecad.json", ".freecad.py"];
  for (const c of candidates) {
    for (const suf of suffixes) {
      if (names.has(`${c}${suf}`) || names.has(`vibecad/${c}${suf}`)) return true;
    }
  }
  for (const n of names) {
    const lower = n.toLowerCase();
    if (!lower.endsWith(".vibecad.py") && !lower.endsWith(".vibecad.json") && !lower.endsWith(".freecad.py")) continue;
    const nBase = n.includes("/") ? n.slice(n.lastIndexOf("/") + 1) : n;
    const nStem = fileStemName(nBase).replace(/\.vibecad$/i, "");
    if (candidates.has(nStem) || candidates.has(`${nStem}.vibecad`)) return true;
  }
  return false;
}

function hasMeshFactorySibling(filename = "") {
  const rel = String(filename || "").replace(/\\/g, "/");
  if (/^mesh\//i.test(rel) && /\.(glb|gltf)$/i.test(rel) && !/\.generation-live\./i.test(rel)) {
    return true;
  }
  const base = rel.includes("/") ? rel.slice(rel.lastIndexOf("/") + 1) : rel;
  const stem = fileStemName(base || "");
  if (!stem) return false;
  // Transform/paint bakes write `Foo_edited.glb` / `Foo_copy2.glb` — factory stays `Foo.mesh.mjs`.
  const candidates = new Set([stem]);
  const withoutEdit = stem.replace(/_edited(?:_\d+)?$/i, "");
  if (withoutEdit) candidates.add(withoutEdit);
  const withoutCopy = withoutEdit.replace(/_copy\d*$/i, "") || stem.replace(/_copy\d*$/i, "");
  if (withoutCopy) candidates.add(withoutCopy);
  for (const c of [...candidates]) {
    const bare = c.replace(/\.mesh$/i, "");
    if (bare) candidates.add(bare);
  }
  const names = new Set();
  for (const f of lastProjectFiles || []) {
    if (f?.name) names.add(String(f.name).replace(/\\/g, "/"));
  }
  try {
    for (const entry of projectTree?.getComponents?.() || []) {
      if (entry?.name) names.add(String(entry.name).replace(/\\/g, "/"));
      if (entry?.viewer_filename) names.add(String(entry.viewer_filename).replace(/\\/g, "/"));
      if (entry?.source) names.add(String(entry.source).replace(/\\/g, "/"));
    }
  } catch {
    /* tree optional */
  }
  const suffixes = [".mesh.mjs", ".mesh.js"];
  for (const c of candidates) {
    for (const suf of suffixes) {
      if (names.has(`${c}${suf}`) || names.has(`mesh/${c}${suf}`)) return true;
    }
  }
  for (const n of names) {
    const lower = n.toLowerCase();
    if (!lower.endsWith(".mesh.mjs") && !lower.endsWith(".mesh.js")) continue;
    const nBase = n.includes("/") ? n.slice(n.lastIndexOf("/") + 1) : n;
    const nStem = fileStemName(nBase).replace(/\.mesh$/i, "");
    if (candidates.has(nStem) || candidates.has(`${nStem}.mesh`)) return true;
  }
  return false;
}

function normalizeObjectPivotToBounds(object3d) {
  if (!object3d) return;
  object3d.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object3d);
  if (box.isEmpty()) return;

  // STEP/GLB imports can keep geometry far from the scene root origin. Move the
  // root pivot to the visible bounds center, then offset its contents back so
  // the part does not visually move. TransformControls attach to this pivot.
  const pivot = box.getCenter(new THREE.Vector3());
  const delta = pivot.sub(object3d.position);
  if (delta.lengthSq() < 1e-12) return;

  if (object3d.isMesh && object3d.geometry) {
    object3d.geometry.translate(-delta.x, -delta.y, -delta.z);
  } else {
    for (const child of object3d.children) {
      child.position.sub(delta);
    }
  }
  object3d.position.add(delta);
  object3d.updateMatrixWorld(true);
}

function centerAndMaterialize(object3d) {
  return materializeObject(object3d, { center: true });
}

function resetTrackballZoomResiduals() {
  try { trackballPointerSafety?.endDrag?.(); } catch (_) { }
  if (!controls) return;
  controls.state = -1;
  if ("keyState" in controls) controls.keyState = -1;
  if (typeof controls._lastAngle === "number") controls._lastAngle = 0;
  if (controls._zoomStart && controls._zoomEnd?.copy) controls._zoomStart.copy(controls._zoomEnd);
  if (controls._panStart && controls._panEnd?.copy) controls._panStart.copy(controls._panEnd);
  if (controls._movePrev && controls._moveCurr?.copy) controls._movePrev.copy(controls._moveCurr);
  if (typeof controls._touchZoomDistanceStart === "number") {
    controls._touchZoomDistanceStart = controls._touchZoomDistanceEnd || 0;
  }
}

function assemblyFrameBox() {
  try { projectAssembly.invalidateBounds?.(); } catch (_) { }
  if (explodedViewEnabled) {
    const overview = projectAssembly.boundingBox({ force: true, union: true });
    if (overview && !overview.isEmpty()) return overview;
  }
  const box = projectAssembly.boundingBox({ force: true });
  if (box && !box.isEmpty()) return box;
  return null;
}

function isUsableFrameBox(box) {
  if (!box || box.isEmpty()) return false;
  const size = box.getSize(new THREE.Vector3());
  const span = size.length();
  return Number.isFinite(span) && span > 1e-5;
}

function frameCameraToBox(box, { zoomOutOnly = false, keepViewDir = false } = {}) {
  if (!box) return;
  // Mutating the desktop camera while WebXR owns it hard-crashes Quest.
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
  if (!isUsableFrameBox(box)) return;
  try { resize(); } catch (_) { }
  resetTrackballZoomResiduals();
  if (typeof camera.zoom === "number" && camera.zoom !== 1) {
    camera.zoom = 1;
    camera.updateProjectionMatrix();
  }
  const size = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  // Sphere of the AABB, then fit through the tighter of v/h FOV. Use sin so the
  // sphere is inside the frustum (tan under-frames and looks zoomed into the part).
  const radius = Math.max(size.length() * 0.5, 1e-4);
  // ~15% margin beyond a full-sphere fit (CAD zoom-extents).
  const needed = fitOrbitDistance(radius, { fovDeg: camera.fov, aspect: camera.aspect });
  if (!Number.isFinite(needed) || needed > 5e5) return;
  let dist = needed;
  if (zoomOutOnly && controls?.target) {
    const current = camera.position.distanceTo(controls.target);
    if (Number.isFinite(current) && current > dist) dist = current;
  }
  camera.up.copy(VIEW_CUBE_WORLD_UP);
  // Fusion-style home: front-right (+Y front, +X right), slightly above; Z stays vertical.
  let viewDir = new THREE.Vector3(1, 1, 0.72).normalize();
  if (keepViewDir && controls?.target) {
    const eye = camera.position.clone().sub(controls.target);
    if (eye.lengthSq() > 1e-8) viewDir = eye.normalize();
  }
  controls.target.copy(center);
  camera.position.copy(center).addScaledVector(viewDir, dist);
  camera.lookAt(center);
  controls._up0?.copy(camera.up);
  controls._position0?.copy(camera.position);
  controls._target0?.copy(controls.target);
  controls._zoom0 = 1;
  controls._eye?.subVectors(camera.position, controls.target);
  controls._lastAngle = 0;
  controls.update();
  const orbitDist = camera.position.distanceTo(controls.target);
  // Leftover Trackball zoom / previous-project pose can leave the camera inside the solid.
  if (!(orbitDist > radius * 0.9)) {
    camera.position.copy(center).addScaledVector(viewDir, dist);
    controls.target.copy(center);
    controls._eye?.subVectors(camera.position, controls.target);
    camera.lookAt(center);
  }
  updateCameraClipPlanes();
  viewCube.update();
}

function fitCamera() {
  // Never run desktop framing while Quest AR is presenting — it fights XR placement
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
  try {
    const sx = Math.abs(Number(projectAssembly?.getRoot?.()?.scale?.x) || 0);
    if (sx > 0 && sx < 0.05) projectAssembly.restoreDesktopTransform?.();
  } catch (_) { }
  const box = assemblyFrameBox();
  if (isUsableFrameBox(box)) {
    frameCameraToBox(box);
    return true;
  }
  // Meshes exist but world bounds are not ready (parked scale, GPU tree not updated).
  // Do not frame the dummy origin cube — that parks the camera inside the real part.
  if (projectAssembly.count() > 0) return false;
  const extent = Math.max(8, niceGridSize(1) * 0.2);
  frameCameraToBox(new THREE.Box3(
    new THREE.Vector3(-extent, -extent, -0.5),
    new THREE.Vector3(extent, extent, 4),
  ));
  return true;
}

/** explfit1 — camera-fit the full exploded CAD AABB (visible meshes only). Zoom out if the span is larger than the current frustum; never punch in on one part. */
function fitExplodedOverview() {
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
  try {
    const sx = Math.abs(Number(projectAssembly?.getRoot?.()?.scale?.x) || 0);
    if (sx > 0 && sx < 0.05) projectAssembly.restoreDesktopTransform?.();
  } catch (_) { }
  try { projectAssembly.invalidateBounds?.(); } catch (_) { }
  const box = projectAssembly.boundingBox({ force: true, union: true }) || assemblyFrameBox();
  if (isUsableFrameBox(box)) {
    frameCameraToBox(box, { zoomOutOnly: true, keepViewDir: true });
    return true;
  }
  if (projectAssembly.count() > 0) return false;
  return fitCamera();
}

function scheduleFitCameraAfterProjectLoad() {
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
  const gen = loadProjectGeneration;
  const retries = [32, 120, 280];
  const frame = () => {
    if (gen !== loadProjectGeneration) return;
    if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
    if (trackballPointerSafety?.isBusy?.()) return;
    try { projectAssembly.invalidateBounds?.(); } catch (_) { }
    try { resize(); } catch (_) { }
    // Retry only if model bounds are not ready. Four unconditional fits kept
    // walking every CAD face and snapping the camera after the model appeared.
    if (fitCamera() === false && retries.length) window.setTimeout(frame, retries.shift());
  };
  window.requestAnimationFrame(frame);
}

const HANDHELD_VIEW_M = 0.12;

function showProjectLoadSpinner(pid, message = "Loading project…") {
  if (!pid) return;
  showViewportOverlay(pid, message, { mode: "load", kind: "project_load", estimateMs: 20000 });
  try { viewportXR?.setAiGenerating?.(true, message); } catch (_) { }
}

function hideProjectLoadSpinner(pid) {
  if (viewportOverlayState?.kind === "project_load") hideViewportOverlay(pid);
  try { viewportXR?.setAiGenerating?.(false, ""); } catch (_) { }
}

function applyHandheldDesktopPlacement() {
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return false;
  const root = projectAssembly?.getRoot?.();
  if (!root || !projectAssembly.count()) {
    fitCamera();
    return false;
  }
  // Undo XR park (1e-6) / handheld bake, then frame like the Aug 5 golden CAD view.
  try { projectAssembly.restoreDesktopTransform?.(); } catch (_) {
    try { root.visible = true; } catch (_) { }
    try { root.scale.set(1, 1, 1); } catch (_) { }
  }
  root.updateMatrixWorld(true);
  try { projectAssembly.invalidateBounds?.(); } catch (_) { }
  seatAssemblyToFloor();
  fitCamera();
  return true;
}

function placeLoadedAssemblyInFront() {
  if (viewportXR?.isPresenting?.() || viewportXR?.isDesktopVrWorkspace?.()) {
    return viewportXR.placeAfterProjectLoad?.({ attempts: 20, delayMs: 80 }) || Promise.resolve(false);
  }
  return Promise.resolve(applyHandheldDesktopPlacement());
}

function recenterAssemblyForEveryone({ broadcast = false } = {}) {
  if (viewportXR?.isPresenting?.()) {
    try {
      viewportXR.placeInFront?.({ spawnId: "eye", keepZoom: false, recaptureDesktop: true, force: true });
    } catch (_) { }
  } else {
    applyHandheldDesktopPlacement();
  }
  if (broadcast) {
    try { collab?.send?.({ type: "xr.fit", action: "recenter", size_m: HANDHELD_VIEW_M }); } catch (_) { }
  }
  return true;
}

function isViewportHelperObject(obj) {
  let node = obj;
  while (node) {
    const u = node.userData || {};
    // Skip overlay / dummy visuals only. Do not treat isUrdfRobot as a helper —
    // real GLB parts can sit under that root, and walking up would skip the mesh.
    if (u.jointOverlay || u.excludeFromFit || u.urdfPlaceholder || u.isOriginHelper || u.isAxisGuide) {
      return true;
    }
    node = node.parent;
  }
  return false;
}

function fitCameraToObject(object) {
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
  if (!object) {
    fitCamera();
    return;
  }
  try { object.updateMatrixWorld(true); } catch (_) { /* ignore */ }
  const box = new THREE.Box3();
  let any = false;
  object.traverse?.((child) => {
    if (!child?.isMesh || !child.geometry) return;
    if (isViewportHelperObject(child)) return;
    box.expandByObject(child);
    any = true;
  });
  if (any && isUsableFrameBox(box)) {
    frameCameraToBox(box);
    return;
  }
  fitCamera();
}

function fitCameraToComponent(catalogName) {
  if (renderer?.xr?.isPresenting || viewportXR?.isPresenting?.()) return;
  const box = projectAssembly.boundingBoxFor?.(catalogName);
  if (isUsableFrameBox(box)) {
    frameCameraToBox(box);
    return;
  }
  const obj = projectAssembly.get(catalogName);
  if (obj) {
    fitCameraToObject(obj);
    return;
  }
  fitCamera();
}

function encodeProjectFileRel(filename) {
  return encodeProjectFilePath(filename);
}

function resolveViewerPaths(filename, url) {
  let viewFilename = filename;
  let viewUrl = url;
  const ext = filename.split(".").pop().toLowerCase();
  // Formats without a browser loader are previewed via a sibling .glb from upload / tessellation.
  const previewViaGlb = new Set([
    "3mf", "ply", "off", "step", "stp",
    "sldprt", "sldasm", "iges", "igs", "brep", "brp",
    "sat", "sab", "x_t", "x_b", "f3d",
  ]);
  if (previewViaGlb.has(ext)) {
    viewFilename = `${fileStem(filename)}.glb`;
    viewUrl = String(url || "").replace(/\/files\/[^?#]*/, `/files/${encodeProjectFileRel(viewFilename)}`);
  }
  // Prefer solid body GLB over OCC face-dump (__faceted) for STEP-style viewing.
  if (/__faceted\.(glb|gltf)$/i.test(viewFilename)) {
    const solid = viewFilename.replace(/__faceted(?=\.(glb|gltf)$)/i, "");
    viewFilename = solid;
    viewUrl = (viewUrl || "").replace(/__faceted(?=\.(glb|gltf)(?:\?|#|$))/i, "");
  }
  return { viewFilename, viewUrl };
}

function _apiPath(url) {
  if (!url) return url;
  if (url.startsWith("/")) return url;
  try {
    const u = new URL(url, window.location.origin);
    return u.pathname + u.search;
  } catch {
    return url;
  }
}

function formatApiDetail(detail, statusText = "", status = 0) {
  if (typeof detail === "string" && detail.trim()) return detail.trim();
  if (detail && typeof detail === "object") {
    if (Array.isArray(detail)) {
      const parts = detail
        .map((item) => {
          const msg = item?.msg || item?.message || (typeof item === "string" ? item : "");
          const loc = Array.isArray(item?.loc) ? item.loc.join(".") : "";
          const maxLen = Number(item?.ctx?.max_length);
          if (/string should have at most \d+ characters/i.test(msg) && /prompt/i.test(loc || "prompt")) {
            return maxLen
              ? `This CAD prompt is longer than Studio’s request limit (${maxLen} characters). Astra/Codex are not the limiter — shorten or split the spec.`
              : "This CAD prompt is longer than Studio’s request limit. Astra/Codex are not the limiter — shorten or split the spec.";
          }
          return msg;
        })
        .filter(Boolean);
      if (parts.length) return parts.join("; ");
    } else if (detail.msg || detail.message) {
      return String(detail.msg || detail.message);
    } else {
      const encoded = JSON.stringify(detail);
      if (encoded && encoded !== "{}" && encoded !== "null") return encoded;
    }
  }
  if (status === 502 || status === 503 || status === 504) {
    return "Server is restarting or busy — wait a few seconds and try again.";
  }
  if (status === 409) {
    return "Too many generations are already running in this project. Wait for one to finish or stop one first.";
  }
  const text = (statusText || "").trim();
  if (text) return text;
  if (status) return `Request failed (${status})`;
  return "Cannot reach the server — is Studio running?";
}

function isBenignGenerationInterrupt(message) {
  return /interrupted by server restart|stopped during a server (update|restart)|was not re-run automatically|interrupted \(page refresh|Generation interrupted by server/i.test(
    String(message || ""),
  );
}

function extractApiErrorMessage(text) {
  const raw = String(text || "").trim();
  if (!raw) return "";
  const jsonMatch = raw.match(/;\s*response=(\{[\s\S]+\})\s*$/);
  if (jsonMatch) {
    try {
      const payload = JSON.parse(jsonMatch[1]);
      const nested = payload?.error?.message || payload?.message;
      if (typeof nested === "string" && nested.trim()) return nested.trim();
    } catch {
      /* ignore malformed JSON tail */
    }
  }
  return raw
    .replace(/^Design failed:\s*/i, "")
    .replace(/^Anthropic API error \([^)]+\):\s*/i, "")
    .replace(/Client error '[^']+' for url '[^']+'\s*/i, "")
    .replace(/For more information check:[^\n]*\n?/i, "")
    .replace(/;\s*response=\{[\s\S]*$/s, "")
    .trim();
}

function formatUserError(err, fallback = "Something went wrong — check Prompt History.") {
  if (!err) return fallback;
  if (typeof err === "string" && err.trim()) return formatUserError({ message: err.trim() }, fallback);
  const name = err.name || "";
  const msg = (err.message || "").trim();
  if (name === "AbortError" || /aborted a request/i.test(msg)) {
    if (userCancelRequested) return "Generation canceled.";
    return "Generation was interrupted (page refresh or navigation). The server may still be building — wait a minute, refresh, and check Prompt History before retrying.";
  }
  if (msg === "Failed to fetch" || /networkerror/i.test(msg)) {
    return "Connection lost during generation. The server may still be building — wait a minute, refresh, and check Prompt History before retrying.";
  }
  if (/credit balance is too low/i.test(msg)) {
    return "Claude API credits are exhausted. Add credits at console.anthropic.com/settings/billing, or switch to OpenAI/Kimi in the AI key picker.";
  }
  if (/overloaded|529|rate limit hit \(429\)/i.test(msg)) {
    const cleaned = msg.replace(/^Server error \d+:\s*/i, "").replace(/^\{.*"detail":\s*"([^"]+)".*\}$/s, "$1");
    return cleaned.includes("Anthropic") ? cleaned : "Anthropic's API is temporarily overloaded. Wait a minute and try again, or switch models in the account menu.";
  }
  if (/truncated at token limit|max_output_tokens/i.test(msg)) {
    const cleaned = msg.replace(/^Server error \d+:\s*/i, "").replace(/^\{.*"detail":\s*"([^"]+)".*\}$/s, "$1");
    return cleaned.includes("Try again") ? cleaned : "The AI response was cut off before it finished. Try again or switch to a faster model in the account menu.";
  }
  if (/string should have at most \d+ characters/i.test(msg)) {
    return "This CAD prompt is longer than Studio’s request limit. Astra/Codex are not the limiter — shorten or split the spec.";
  }
  if (/missing build123d source that assigns [`']?result/i.test(msg)) {
    return "VibeCAD did not return a complete CAD program. The model replied without build123d source that assigns `result`, so nothing could be built.";
  }
  if (/^Design failed:/i.test(msg) || /Anthropic API error/i.test(msg)) {
    const cleaned = extractApiErrorMessage(msg);
    if (/credit balance is too low/i.test(cleaned)) {
      return "Claude API credits are exhausted. Add credits at console.anthropic.com/settings/billing, or switch to OpenAI/Kimi in the AI key picker.";
    }
    return cleaned || msg || fallback;
  }
  return msg || fallback;
}

function isVerboseGenerationFailureMessage(text) {
  const msg = String(text || "").trim();
  if (!msg) return false;
  return /design failed|anthropic api error|openai api error|bad request for url|credit balance is too low|invalid_request_error/i.test(msg);
}

function briefPromptFailureStatus() {
  return "Generation failed — see viewport.";
}

function generationFailureAdvice(err) {
  const msg = String(err?.message || err || "");
  if (/missing build123d source that assigns [`']?result/i.test(msg)) {
    return [
      "Retry this prompt — Astra sometimes returns notes instead of a `result = {…}` program.",
      "Keep the job to one chassis and attach the existing OpenArm mount STEP as a reference.",
      "If it fails again, switch to CAD 2.0 (Jake), which uses the tool-using authoring loop.",
    ];
  }
  if (/codex exec failed/i.test(msg)) {
    return [
      "Check ChatGPT is signed in under Subscriptions.",
      "Retry once. If Codex is outdated or the model id is rejected, Prompt History will say so.",
    ];
  }
  return [];
}

function showPromptGenerationFailure(err, context = {}, dedupeKey = null) {
  const message = formatUserError(err);
  const suggestions = generationFailureAdvice(err);
  const key =
    dedupeKey ||
    context?.traceId ||
    lastPromptCopyContext?.traceId ||
    context?.promptId ||
    message.slice(0, 120);
  if (generationWatchOverlay?.shownFailureTrace && key && generationWatchOverlay.shownFailureTrace === key) {
    return message;
  }
  if (generationWatchOverlay && key) {
    generationWatchOverlay.shownFailureTrace = key;
  }
  viewerOverlay.showError(message, { ...lastPromptCopyContext, ...context, suggestions });
  return message;
}

function setPromptPanelFailureStatus(statusEl) {
  if (!statusEl) return;
  statusEl.className = "status error";
  statusEl.textContent = briefPromptFailureStatus();
}

// Stable within a session so reopening projects can use browser HTTP cache.
// Bumped after model edits / generation so the next fetch gets fresh bytes.
let modelCacheSessionEpoch = Date.now();
let modelCacheEpoch = 0;
const modelBlobCache = createModelBlobCache();

function bumpModelCacheEpoch() {
  modelCacheEpoch = Date.now();
  modelBlobCache.clear();
}

function _cacheBustModelPath(path, { force = false } = {}) {
  return modelCachePath(path, {
    files: lastProjectFiles || [], projectId,
    epoch: modelCacheEpoch, sessionEpoch: modelCacheSessionEpoch,
    force: force ? Date.now() : null,
  });
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchModelBlob(path, { retries = 2 } = {}) {
  return modelBlobCache.get(path, () => fetchModelBlobUncached(path, { retries }), currentUser?.id || "anonymous");
}

async function fetchModelBlobUncached(path, { retries = 2 } = {}) {
  let lastError = null;
  const started = Date.now();
  // Large McMaster STEPs can take minutes to tessellate; keep polling 503s.
  const previewDeadlineMs = 12 * 60 * 1000;
  let attempt = 0;
  while (true) {
    const fetchPath = attempt ? _cacheBustModelPath(path.split("?")[0], { force: true }) : path;
    const res = await rawFetch(fetchPath, {}, 25000);
    if (res.ok) return res.blob();
    const data = await res.json().catch(() => ({}));
    const detail = data.detail;
    const msg = typeof detail === "string" ? detail : JSON.stringify(detail) || res.statusText;
    lastError = new Error(`fetch for "${API}${fetchPath}" responded with ${res.status}: ${msg}`);
    const previewPending = res.status === 503 && (data.preview_pending === true || /still building/i.test(msg));
    if (previewPending && Date.now() - started < previewDeadlineMs) {
      const retryAfterSec = Number(res.headers.get("Retry-After") || 3);
      const waitMs = Math.min(15000, Math.max(1000, (Number.isFinite(retryAfterSec) ? retryAfterSec : 3) * 1000));
      if (attempt === 0 || attempt % 4 === 0) {
        const mcmaster = /mcmaster/i.test(msg);
        setEditStatus?.(
          "ok",
          mcmaster
            ? "Fetching 3-D STEP from McMaster… then building the viewport preview."
            : "Building 3D preview… large STEP files can take a few minutes.",
        );
      }
      await sleep(waitMs);
      attempt += 1;
      continue;
    }
    if (![502, 503, 504].includes(res.status) || attempt >= retries) break;
    await sleep(350 * (attempt + 1));
    attempt += 1;
  }
  throw lastError || new Error(`Could not fetch model "${API}${path}".`);
}

function sanitizeGltfNodeCycles(gltf) {
  if (!gltf || typeof gltf !== "object" || !Array.isArray(gltf.nodes)) {
    return { gltf, changed: false };
  }
  const nodes = gltf.nodes;
  let changed = false;
  const sceneRoots = (gltf.scenes || [])
    .flatMap((scene) => Array.isArray(scene?.nodes) ? scene.nodes : [])
    .filter((idx) => Number.isInteger(idx) && idx >= 0 && idx < nodes.length);
  const roots = sceneRoots.length ? sceneRoots : nodes.map((_, idx) => idx);

  function cleanNode(idx, stack = new Set()) {
    const node = nodes[idx];
    if (!node || !Array.isArray(node.children)) return;
    stack.add(idx);
    const children = [];
    for (const childIdx of node.children) {
      if (!Number.isInteger(childIdx) || childIdx < 0 || childIdx >= nodes.length || stack.has(childIdx)) {
        changed = true;
        continue;
      }
      children.push(childIdx);
      cleanNode(childIdx, new Set(stack));
    }
    if (children.length !== node.children.length) {
      if (children.length) node.children = children;
      else delete node.children;
      changed = true;
    }
  }

  roots.forEach((idx) => cleanNode(idx));
  return { gltf, changed };
}

async function sanitizeGltfBlobForLoader(blob, ext = "") {
  const kind = String(ext || "").toLowerCase();
  try {
    if (kind === "gltf") {
      const text = await blob.text();
      if (!jsonTextNeedsSanitize(text)) return { blob, repaired: false };
      const parsed = parseJsonFinite(text);
      const { gltf, changed } = sanitizeGltfNodeCycles(parsed);
      const bboxChanged = sanitizeGltfAccessors(gltf);
      const repaired = changed || bboxChanged || jsonTextNeedsSanitize(text);
      return repaired
        ? { blob: new Blob([JSON.stringify(gltf)], { type: blob.type || "model/gltf+json" }), repaired: true }
        : { blob, repaired: false };
    }
    if (kind !== "glb") return { blob, repaired: false };
    // Fast path: only inspect the JSON chunk. Copying/parsing the BIN on every
    // project open was stalling the main thread before GLTFLoader ran.
    try {
      const jsonText = await readGlbJsonChunkText(blob);
      if (jsonText && !jsonTextNeedsSanitize(jsonText)) return { blob, repaired: false };
    } catch (_) { /* fall through to full sanitize */ }
    const buffer = await blob.arrayBuffer();
    const bytes = new Uint8Array(buffer);
    const view = new DataView(buffer);
    if (bytes.length < 20 || bytes[0] !== 0x67 || bytes[1] !== 0x6c || bytes[2] !== 0x54 || bytes[3] !== 0x46) {
      return { blob, repaired: false };
    }

    let offset = 12;
    let jsonChunkStart = -1;
    let jsonChunkLen = 0;
    while (offset + 8 <= bytes.length) {
      const chunkLen = view.getUint32(offset, true);
      const chunkType = view.getUint32(offset + 4, true);
      offset += 8;
      if (chunkType === 0x4e4f534a) {
        jsonChunkStart = offset;
        jsonChunkLen = chunkLen;
        break;
      }
      offset += chunkLen;
    }
    if (jsonChunkStart < 0 || jsonChunkLen <= 0 || jsonChunkStart + jsonChunkLen > bytes.length) {
      return { blob, repaired: false };
    }

    const text = new TextDecoder().decode(bytes.slice(jsonChunkStart, jsonChunkStart + jsonChunkLen)).trim();
    const hadNonFinite = jsonTextNeedsSanitize(text);
    const parsed = parseJsonFinite(text);
    const { gltf, changed } = sanitizeGltfNodeCycles(parsed);
    const bboxChanged = sanitizeGltfAccessors(gltf);
    if (!changed && !bboxChanged && !hadNonFinite) return { blob, repaired: false };

    const encoded = new TextEncoder().encode(JSON.stringify(gltf));
    if (encoded.length > jsonChunkLen) return { blob, repaired: true };
    const out = new Uint8Array(buffer.slice(0));
    out.fill(0x20, jsonChunkStart, jsonChunkStart + jsonChunkLen);
    out.set(encoded, jsonChunkStart);
    return { blob: new Blob([out], { type: blob.type || "model/gltf-binary" }), repaired: true };
  } catch (err) {
    console.warn("Could not sanitize glTF before load", err);
    return { blob, repaired: false };
  }
}

function refreshLoadedGeometryBounds(root) {
  // GLTFLoader stamps accessor min/max onto boundingSphere. Zeroed Infinity
  // axes leave a tiny sphere so the real mesh frustum-pops while zooming.
  root?.traverse?.((child) => {
    const geo = child?.geometry;
    if (!geo || typeof geo.computeBoundingBox !== "function") return;
    try {
      geo.boundingBox = null;
      geo.boundingSphere = null;
      geo.computeBoundingBox();
      geo.computeBoundingSphere();
    } catch (_) { }
  });
}

function hardenLoadedCadMaterials(root, { recomputeBounds = true } = {}) {
  if (recomputeBounds) refreshLoadedGeometryBounds(root);
  root?.traverse?.((child) => {
    if (!child?.isMesh || !child.material) return;
    const materials = Array.isArray(child.material) ? child.material : [child.material];
    for (const mat of materials) {
      if (!mat) continue;
      mat.side = THREE.DoubleSide;
      mat.needsUpdate = true;
    }
  });
}

function livePreviewBounds() {
  if (!livePreviewRoot?.visible) return null;
  try {
    livePreviewRoot.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(livePreviewRoot);
    return box.isEmpty() ? null : box;
  } catch (_) {
    return null;
  }
}

function unionLivePreviewBounds(box) {
  const live = livePreviewBounds();
  if (box && live) {
    box.union(live);
    return box;
  }
  return box || live;
}

function cancelLivePreviewReveal() {
  if (livePreviewRevealRaf) {
    cancelAnimationFrame(livePreviewRevealRaf);
    livePreviewRevealRaf = 0;
  }
}

function restoreLivePreviewHiddenAssembly() {
  for (const name of livePreviewHiddenCatalogs) {
    const obj = projectAssembly.get?.(name);
    if (obj) obj.visible = true;
  }
  livePreviewHiddenCatalogs = [];
}

function hideAssemblyMatchingLivePreviewStem(stem) {
  if (!stem || viewportXR?.isPresenting?.()) return;
  restoreLivePreviewHiddenAssembly();
  for (const [name, obj] of projectAssembly.list?.() || []) {
    if (livePreviewSourceStem(name) !== stem) continue;
    if (!obj?.visible) continue;
    obj.visible = false;
    livePreviewHiddenCatalogs.push(name);
  }
}

function disposeLiveGenerationPreview({ soft = false } = {}) {
  cancelLivePreviewReveal();
  livePreviewToken += 1;
  livePreviewKey = "";
  livePreviewPendingKey = "";
  livePreviewDidFit = false;
  livePreviewFitSize = 0;
  livePreviewLoading = false;
  if (!soft) restoreLivePreviewHiddenAssembly();
  if (livePreviewDebounce) {
    clearTimeout(livePreviewDebounce);
    livePreviewDebounce = 0;
  }
  if (livePreviewAbort) {
    try { livePreviewAbort.abort(); } catch (_) { }
    livePreviewAbort = null;
  }
  if (!livePreviewRoot) return;
  if (soft) {
    livePreviewRoot.visible = false;
    return;
  }
  try { scene.remove(livePreviewRoot); } catch (_) { }
  try { disposeStyledModel(livePreviewRoot); } catch (_) { }
  livePreviewRoot = null;
}

function ensureLivePreviewRoot() {
  if (livePreviewRoot && livePreviewRoot.parent === scene) return livePreviewRoot;
  if (livePreviewRoot) {
    try { scene.remove(livePreviewRoot); } catch (_) { }
    try { disposeStyledModel(livePreviewRoot); } catch (_) { }
    livePreviewRoot = null;
  }
  livePreviewRoot = new THREE.Group();
  livePreviewRoot.name = "__generation_live__";
  livePreviewRoot.userData.isLiveGenerationPreview = true;
  scene.add(livePreviewRoot);
  return livePreviewRoot;
}

function clearLivePreviewChildren() {
  if (!livePreviewRoot) return;
  const kids = [...livePreviewRoot.children];
  for (const kid of kids) {
    livePreviewRoot.remove(kid);
    try { disposeStyledModel(kid); } catch (_) { }
  }
}

function liveRevealUnits(object) {
  const skip = (c) => !!(c?.userData?.isEdge || c?.userData?.isSilhouette || c?.userData?.cadInternalHidden);
  const top = (object?.children || []).filter((c) => !skip(c));
  if (top.length >= 2) return top.slice(0, LIVE_PREVIEW_MAX_UNITS);
  const meshes = [];
  object?.traverse?.((c) => {
    if ((c.isMesh || c.isSkinnedMesh) && !skip(c)) meshes.push(c);
  });
  if (meshes.length > LIVE_PREVIEW_MAX_UNITS) {
    return [object];
  }
  return meshes.length ? meshes : (object ? [object] : []);
}

function staggerLiveReveal(object, token) {
  cancelLivePreviewReveal();
  const units = liveRevealUnits(object);
  if (units.length <= 1) {
    if (object) object.visible = true;
    units.forEach((u) => { u.visible = true; });
    return;
  }
  for (const u of units) u.visible = false;
  object.visible = true;
  const perFrame = Math.max(1, Math.ceil(units.length / 36));
  let i = 0;
  const step = () => {
    if (token !== livePreviewToken) return;
    const end = Math.min(units.length, i + perFrame);
    for (; i < end; i += 1) units[i].visible = true;
    if (i < units.length) {
      livePreviewRevealRaf = requestAnimationFrame(step);
    } else {
      livePreviewRevealRaf = 0;
    }
  };
  livePreviewRevealRaf = requestAnimationFrame(step);
}

function isViewportPointerBusy() {
  try {
    if (trackballPointerSafety?.isBusy?.()) return true;
  } catch (_) { }
  return Number(controls?.state) >= 0;
}

function maybeFitLivePreview() {
  if (viewportXR?.isPresenting?.()) return;
  if (isViewportPointerBusy()) return;
  if (Number(projectAssembly.count?.() || 0) > 0) return;
  const box = livePreviewBounds();
  if (!box) return;
  const size = box.getSize(new THREE.Vector3()).length();
  if (!livePreviewDidFit || (livePreviewFitSize > 0 && size > livePreviewFitSize * 2.2)) {
    livePreviewDidFit = true;
    livePreviewFitSize = size;
    fitCamera();
  }
}

function livePreviewKeyFromProgress(progress) {
  const filename = String(progress?.preview_filename || "").trim();
  if (!filename) return "";
  return [
    filename,
    progress?.preview_mtime || 0,
    progress?.preview_seq || 0,
    progress?.preview_part || "",
    progress?.preview_append ? "a" : "r",
  ].join(":");
}

function scheduleLiveGenerationPreview(progress, { running = true } = {}) {
  if (!running || !projectId) return;
  if (generationWatchPid && generationWatchPid !== projectId) return;
  if (viewportXR?.isPresenting?.()) return;
  const filename = String(progress?.preview_filename || "").trim();
  if (!filename || !/\.(glb|gltf)$/i.test(filename)) return;
  if (isCatalogHardwareComponent({ name: filename, stem: fileStem(filename) })) return;
  if (String(progress?.stage || "").toLowerCase() === "hardware") return;
  if (Number(progress?.preview_bytes || 0) > LIVE_PREVIEW_MAX_BYTES) return;
  const key = livePreviewKeyFromProgress(progress);
  if (!key || key === livePreviewKey || key === livePreviewPendingKey) return;
  livePreviewPendingKey = key;
  if (livePreviewDebounce) clearTimeout(livePreviewDebounce);
  livePreviewDebounce = window.setTimeout(() => {
    livePreviewDebounce = 0;
    if (isViewportPointerBusy()) {
      livePreviewPendingKey = "";
      scheduleLiveGenerationPreview(progress, { running: true });
      return;
    }
    void loadLiveGenerationPreview(progress);
  }, isViewportPointerBusy() ? 500 : 180);
}

async function loadLiveGenerationPreview(progress) {
  const expectedProjectId = projectId;
  const filename = String(progress?.preview_filename || "").trim();
  const key = livePreviewKeyFromProgress(progress);
  if (!expectedProjectId || !filename || !key) return;
  if (viewportXR?.isPresenting?.()) return;
  if (key === livePreviewKey) return;

  const token = ++livePreviewToken;
  livePreviewLoading = true;
  if (livePreviewAbort) {
    try { livePreviewAbort.abort(); } catch (_) { }
  }
  const abort = new AbortController();
  livePreviewAbort = abort;
  const assemblyFilenames = [...(projectAssembly.list?.() || [])].map(([name]) => name);
  const append = livePreviewShouldAppend({
    previewAppend: progress?.preview_append === true,
    previewFilename: filename,
    livePreviewHasChildren: !!livePreviewRoot?.children?.length,
    targetMode: generationWatchOverlay?.targetMode || getPromptTargetMode(),
    assemblyFilenames,
  });
  const url = `/api/projects/${encodeURIComponent(expectedProjectId)}/files/${encodeProjectFileRel(filename)}?_=${encodeURIComponent(String(progress?.preview_mtime || Date.now()))}`;
  try {
    const res = await rawFetch(url, { signal: abort.signal }, 20000);
    if (!res.ok) return;
    const blob = await res.blob();
    if (token !== livePreviewToken || expectedProjectId !== projectId) return;
    if (!blob || blob.size < 80 || blob.size > LIVE_PREVIEW_MAX_BYTES) return;
    const ext = filename.split(".").pop().toLowerCase();
    const sanitized = await sanitizeGltfBlobForLoader(blob, ext);
    const safeBlob = sanitized?.blob || blob;
    const blobUrl = URL.createObjectURL(safeBlob);
    let object;
    try {
      const gltf = await new GLTFLoader().loadAsync(blobUrl);
      object = gltf.scene;
    } finally {
      URL.revokeObjectURL(blobUrl);
    }
    if (token !== livePreviewToken || expectedProjectId !== projectId) {
      try { disposeStyledModel(object); } catch (_) { }
      return;
    }
    hardenLoadedCadMaterials(object, { recomputeBounds: !!sanitized?.repaired });
    const meshLive = /\.generation-live\./i.test(filename) || object.userData?.render3dPipeline === "img2threejs";
    materializeObject(object, {
      center: false,
      normalizePivot: false,
      seatToFloor: false,
      filename,
      orient: !meshLive,
      // Live tessellation swaps often — skip Fusion crease rebuilds on every preview.
      styleMode: "shaded",
    });
    object.userData.isLiveGenerationPreview = true;
    const root = ensureLivePreviewRoot();
    root.visible = true;
    const keepWorld = append && Number(projectAssembly.count?.() || 0) > 0;
    if (append) {
      root.position.set(0, 0, 0);
      root.quaternion.identity();
      root.scale.set(1, 1, 1);
      clearLivePreviewChildren();
    } else {
      root.position.set(0, 0, 0);
      root.quaternion.identity();
      root.scale.set(1, 1, 1);
      clearLivePreviewChildren();
    }
    const previewStem = livePreviewSourceStem(filename);
    if (!append) hideAssemblyMatchingLivePreviewStem(previewStem);
    root.add(object);
    if (!keepWorld) {
      root.position.set(0, 0, 0);
      root.updateMatrixWorld(true);
      const box = new THREE.Box3().setFromObject(root);
      if (!box.isEmpty()) {
        const center = box.getCenter(new THREE.Vector3());
        root.position.set(-center.x, -center.y, -box.min.z);
        root.updateMatrixWorld(true);
      }
    } else {
      placeNewestAssemblyObjectInGrid("__generation_live__", root);
      root.updateMatrixWorld(true);
    }
    livePreviewKey = key;
    livePreviewPendingKey = "";
    staggerLiveReveal(object, token);
    maybeFitLivePreview();
  } catch (err) {
    if (err?.name === "AbortError") return;
    console.warn("Live generation preview failed", err);
  } finally {
    if (livePreviewAbort === abort) livePreviewAbort = null;
    if (token === livePreviewToken) livePreviewLoading = false;
  }
}

async function loadModel(url, filename, opts = {}) {
  const expectedProjectId = opts.projectId ?? projectId;
  if (isDxfDrawingFilename(filename)) {
    return openDxfDrawingByName(filename, {
      projectId: expectedProjectId,
      label: opts.label,
    });
  }
  const append = opts.append === true;
  const catalogName = opts.catalogFilename || filename;
  if (
    !opts.inspectCatalogHardware
    && isCatalogHardwareComponent({ name: catalogName, viewer_filename: filename })
  ) {
    return false;
  }
  if (isCatalogHardwareComponent({ name: catalogName, viewer_filename: filename })) {
    opts = { ...opts, styleMode: opts.styleMode && opts.styleMode !== "auto" ? opts.styleMode : "shaded" };
  }
  const preservePlacement = opts.preservePlacement === true;
  const replaceCatalog = opts.replaceCatalog || null;
  const { viewFilename, viewUrl } = resolveViewerPaths(filename, url);
  const viewExt = viewFilename.split(".").pop().toLowerCase();
  if (viewExt === "stl" || viewExt === "obj") {
    const stem = String(viewFilename).replace(/\.(stl|obj)$/i, "");
    const glbHit = (lastProjectFiles || []).find((file) => {
      const name = String(file?.name || "").replace(/\\/g, "/");
      const base = name.split("/").pop() || name;
      return base.toLowerCase() === `${stem.split("/").pop() || stem}.glb`.toLowerCase();
    });
    if (glbHit?.name) {
      return loadModel(projectFileUrl(expectedProjectId, glbHit.name), glbHit.name, opts);
    }
  }
  const gen = ++loadModelGeneration;
  const knownBytes = Number(
    (lastProjectFiles || []).find((f) => f.name === viewFilename || f.name === filename)?.size || 0,
  );
  if (knownBytes > VIEWPORT_MAX_MESH_BYTES) {
    console.warn("Skipping oversized viewport mesh", viewFilename, knownBytes);
    return false;
  }
  const path = _cacheBustModelPath(_apiPath(viewUrl), { force: !!opts.cacheBust });
  const blob = (opts.blob && opts.blob.size > 0) ? opts.blob : await fetchModelBlob(path);
  let object;
  let gltfRepaired = false;
  if (viewExt === "stl") {
    const geo = new STLLoader().parse(await blob.arrayBuffer());
    geo.computeVertexNormals();
    object = new THREE.Mesh(geo);
  } else if (viewExt === "obj") {
    object = new OBJLoader().parse(await blob.text());
  } else if (viewExt === "glb" || viewExt === "gltf") {
    const head = new Uint8Array(await blob.slice(0, 64).arrayBuffer());
    const isBinGltf = head.length >= 4 && head[0] === 0x67 && head[1] === 0x6c && head[2] === 0x54 && head[3] === 0x46;
    const asText = new TextDecoder().decode(head);
    const isDriveStub = asText.trimStart().startsWith("{") && asText.includes('"id"');
    if (viewExt === "glb" && !isBinGltf) {
      const base = String(viewFilename || filename || "").replace(/\\/g, "/").split("/").pop();
      const alt = (lastProjectFiles || []).find((file) => {
        const name = String(file?.name || "").replace(/\\/g, "/");
        if (!name.endsWith("/" + base) || name === viewFilename || name === filename) return false;
        return Number(file.size || 0) > 80;
      });
      if (alt?.name && !opts._driveStubRetry) {
        return loadModel(projectFileUrl(expectedProjectId, alt.name), alt.name, { ...opts, _driveStubRetry: true });
      }
      if (isDriveStub && !opts._driveStubRetry && base) {
        for (const prefix of ["vibecad/", "mesh/", "jake/"]) {
          try {
            return await loadModel(
              projectFileUrl(expectedProjectId, prefix + base),
              prefix + base,
              { ...opts, catalogFilename: catalogName, _driveStubRetry: true },
            );
          } catch (err) {
            console.warn("engine-folder GLB retry failed", prefix + base, err);
          }
        }
        console.warn("Skipping Drive-id stub GLB", viewFilename);
        return false;
      }
      if (isDriveStub) {
        console.warn("Skipping Drive-id stub GLB", viewFilename);
        return false;
      }
    }
    const sanitized = await sanitizeGltfBlobForLoader(blob, viewExt);
    const safeBlob = sanitized?.blob || blob;
    gltfRepaired = !!sanitized?.repaired;
    const blobUrl = URL.createObjectURL(safeBlob);
    try {
      const gltf = await new GLTFLoader().loadAsync(blobUrl);
      object = gltf.scene;
      if (gltf.animations?.length) {
        object.animations = gltf.animations;
        object.userData.gltfAnimations = gltf.animations;
      }
    } finally {
      URL.revokeObjectURL(blobUrl);
    }
    hardenLoadedCadMaterials(object, { recomputeBounds: gltfRepaired });
    prepareLoadedMeshResources(object);
  } else {
    throw new Error(`Unsupported format: ${viewExt}`);
  }

  const loadedArtifact = meshArtifactIdentityFromFiles(expectedProjectId, catalogName, lastProjectFiles, viewFilename);
  object.userData = {
    ...(object.userData || {}),
    catalogFilename: catalogName,
    viewerFilename: viewFilename,
    artifactHash: loadedArtifact.artifactHash,
    artifactRevision: loadedArtifact.revision,
  };

  if (gen !== loadModelGeneration || expectedProjectId !== projectId) {
    disposeStyledModel(object);
    return false;
  }
  if (opts.cancelIfSelectionChanged && !append && !modelMatchesSelection(viewFilename, catalogName)) {
    disposeStyledModel(object);
    onStatus?.("error", "Model load cancelled — selection changed.");
    return false;
  }

  // Only wipe the scene if we're doing a full fresh load (not appending or swapping one component).
  if (!append && !replaceCatalog) clearModelContents();

  const shouldCenter = opts.center !== false;
  const shouldNormalizePivot = opts.normalizePivot !== false;
  const preserveWorld = !preservePlacement && shouldPreserveCadWorldFrame(opts, catalogName);
  if (opts.editPlacement) {
    materializeObject(object, {
      center: false, normalizePivot: false, seatToFloor: false,
      orient: false, filename: viewFilename, styleMode: opts.styleMode, skipEdges: opts.skipEdges === true
    });
    applyEditPlacement(object, opts.editPlacement);
  } else if (preservePlacement) {
    const saved = opts.savedTransform;
    if (saved) {
      // Restore the previous mesh's exact world transform so the model
      // doesn't jump after a press-pull, fillet, chamfer, etc.
      materializeObject(object, {
        center: false,
        normalizePivot: shouldNormalizePivot,
        seatToFloor: false,
        filename: viewFilename,
        orient: false,
        orientationMode: opts.orientationMode,
        styleMode: opts.styleMode,
        skipEdges: opts.skipEdges === true,
      });
      object.position.copy(saved.position);
      object.quaternion.copy(saved.quaternion);
      object.scale.copy(saved.scale);
    } else {
      // Fallback: re-center (floor-align + X/Y center) so the model
      // sits in the same visual area rather than jumping to raw origin.
      materializeObject(object, { center: shouldCenter, normalizePivot: shouldNormalizePivot, filename: viewFilename, orientationMode: opts.orientationMode, styleMode: opts.styleMode, skipEdges: opts.skipEdges === true });
    }
    object.updateMatrixWorld(true);
  } else {
    materializeObject(object, {
      center: shouldCenter && !preserveWorld,
      normalizePivot: shouldNormalizePivot && !preserveWorld,
      seatToFloor: !preserveWorld,
      filename: viewFilename,
      orientationMode: opts.orientationMode,
      styleMode: opts.styleMode,
      skipEdges: opts.skipEdges === true,
    });
  }
  if (opts.resetTransform) {
    object.position.set(0, 0, 0);
    object.quaternion.set(0, 0, 0, 1);
    object.scale.set(1, 1, 1);
    object.updateMatrixWorld(true);
    // Identity can leave origin-centered meshes straddling the grid — seat the base.
    seatObjectToFloor(object);
  }
  const xrPresenting = isLiveXrPresenting();
  if (!xrPresenting) {
    try { projectAssembly.restoreDesktopTransform?.({ unbakeChildren: !append }); } catch (_) { }
  }
  // Quest crash root cause: desktop-scale CAD in the LIVE XR scene (even if hidden),
  // then placeInFront sets scale=1 again. Pre-scale to ~12cm BEFORE attach.
  // Skip when appending into an assembly that is already handheld-scaled — a second
  // 12cm bake made new VR solids mismatch, and a full reload then dropped siblings.
  const rootSx = Math.abs(Number(projectAssembly.getRoot?.()?.scale?.x) || 0);
  const appendIntoLiveXr = xrPresenting && append && rootSx >= 1e-4;
  if (xrPresenting && !appendIntoLiveXr && !opts.editPlacement) {
    try {
      object.visible = false;
      object.updateMatrixWorld(true);
      const preBox = new THREE.Box3().setFromObject(object);
      if (!preBox.isEmpty()) {
        const preSize = preBox.getSize(new THREE.Vector3());
        const maxDim = Math.max(preSize.x, preSize.y, preSize.z, 1e-4);
        const targetM = 0.12;
        const factor = THREE.MathUtils.clamp(targetM / maxDim, 1e-8, 50);
        object.scale.multiplyScalar(factor);
        object.updateMatrixWorld(true);
      }
    } catch (_) { }
  }
  // Reset assembly root so a prior XR scale does not compound the pre-scale above.
  // Keep it hidden while identity — never flash desktop-scale content in the headset.
  if (xrPresenting && !append) {
    try {
      const root = projectAssembly.getRoot?.();
      if (root) {
        root.visible = false;
        root.position.set(0, 0, 0);
        root.quaternion.identity();
        root.scale.set(1, 1, 1);
        root.updateMatrixWorld(true);
      }
    } catch (_) { }
  }
  projectAssembly.add(catalogName, object, { soft: xrPresenting });
  if (opts.autoGridPlace === true && append && !opts.editPlacement && !preservePlacement && !xrPresenting) {
    placeNewestAssemblyObjectInGrid(catalogName, object);
  }
  if (/_exploded$/i.test(fileStemName(viewFilename))) {
    object.userData.explodedViewerFilename = viewFilename;
  }
  if (replaceCatalog && replaceCatalog !== catalogName) {
    projectAssembly.remove(replaceCatalog, { soft: xrPresenting });
  }
  projectAssembly.setVisible(catalogName, !isComponentHidden(catalogName));
  currentMesh = projectAssembly.getRoot();
  if (xrPresenting && !append) {
    try {
      if (currentMesh) currentMesh.visible = false;
      try { projectAssembly.attachToScene?.(); } catch (_) { }
      viewportXR.invalidateSavedDesktop?.();
    } catch (_) { }
  } else {
    try {
      if (object && !isComponentHidden(catalogName)) object.visible = true;
      if (currentMesh) currentMesh.visible = true;
      projectAssembly.attachToScene?.();
    } catch (_) { }
  }
  reapplyViewMode(currentMesh);
  if (!xrPresenting) {
    positionShadowFloor(scene, currentMesh);
    rebuildGrid();
  }
  featureEditor.setModel(projectId, catalogName);
  objectTools.clearSelection?.();
  scheduleStudioIdle(() => objectTools.refreshBodyInfo?.().catch(() => { }));
  if (opts.skipEdges === true && !xrPresenting) {
    scheduleStudioIdle(() => {
      try { ensureCadEdges(object); } catch (_) { }
    });
  }
  // Do NOT prefetch USDZ here — export freezes the main thread on real CAD
  // models and trapped the studio boot spinner. AR prepares on demand.
  try { invalidateMobileArCache(); } catch (_) { /* ignore */ }
  if (opts.fitView !== false && !xrPresenting) {
    if (!opts.editPlacement) seatAssemblyToFloor();
    if (append && projectAssembly.count() > 1) fitCamera();
    else fitCameraToComponent(catalogName);
  }

  if (opts.autoGizmo) {
    selectAssemblyComponent(catalogName, { autoGizmo: true, fitView: false });
  } else if (!append) {
    transformControls.detach();
    gizmoPanel.hide();
    document.getElementById("btn-gizmo")?.classList.remove("active");
  }
  safeRestoreActiveModelPromptState({ restoreMode: false });
  collab?.refreshAllRemote(currentMesh);
  const refs = composer.getReferences();
  if (refs?.length || objectTools.getSelection?.()) sendCollabPresence();
  sectionView.onModelChanged?.();
  if (riggingEditor.isActive?.()) {
    void loadSimForFile(catalogName);
  }
  if (opts.autoGizmo) {
    const sel = objectTools.getSelection()?.mesh;
    if (sel) showObjectGizmo(sel, opts.gizmoMode || transformControls.getMode?.() || "translate", { switchTab: false });
  }
  syncExportButton();
  if (isAuthoredImg2threejsMesh(object, catalogName)) {
    void attachMeshAnimationForLoadedModel(object, catalogName, expectedProjectId);
  } else if (meshAnimationRuntime) {
    meshAnimationRuntime.dispose();
    meshAnimationRuntime = null;
    syncMeshViewportPlaybackUi();
    void attachRobotPlaybackForLoadedModel(catalogName, expectedProjectId);
  } else {
    void attachRobotPlaybackForLoadedModel(catalogName, expectedProjectId);
  }
  return true;
}

async function rawFetch(path, options = {}, timeoutMs = 200000) {
  const externalSignal = options.signal;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const onExternalAbort = () => controller.abort();
  if (externalSignal) {
    if (externalSignal.aborted) {
      clearTimeout(timer);
      throw new DOMException("The operation was aborted.", "AbortError");
    }
    externalSignal.addEventListener("abort", onExternalAbort, { once: true });
  }
  const { signal: _ignored, ...rest } = options;
  const headers = authHeaders(rest.headers || {});
  // JSON string bodies need an explicit Content-Type or FastAPI returns 422.
  if (
    typeof rest.body === "string"
    && rest.body
    && !headers["Content-Type"]
    && !headers["content-type"]
  ) {
    const looksJson = /^\s*[\{\[]/.test(rest.body);
    if (looksJson) headers["Content-Type"] = "application/json";
  }
  try {
    return await fetch(`${API}${path}`, { credentials: "include", ...rest, headers, signal: controller.signal });
  } finally {
    clearTimeout(timer);
    if (externalSignal) externalSignal.removeEventListener("abort", onExternalAbort);
  }
}

async function api(path, options = {}, timeoutMs = 200000) {
  const method = options.method || "GET";
  const skipLog =
    path.startsWith("/api/logs")
    || path.startsWith("/api/xr-agent/")
    || (typeof projectId === "string"
      && projectId
      && path.includes(`/projects/${projectId}`)
      && !!allProjects.find((p) => p.id === projectId)?.incognito);
  const t0 = performance.now();
  let bodyPreview = "";
  if (options.body && typeof options.body === "string") {
    if (path.includes("diagnose-photo") || options.body.length > 50000) {
      try {
        const parsed = JSON.parse(options.body);
        const imgCount = Array.isArray(parsed?.images) ? parsed.images.length : 0;
        bodyPreview = {
          ...parsed,
          images: imgCount ? `[${imgCount} image(s)]` : parsed?.images,
        };
        if (bodyPreview.client_secret) bodyPreview.client_secret = "[redacted]";
        if (bodyPreview.consumer_secret) bodyPreview.consumer_secret = "[redacted]";
        if (bodyPreview.x_consumer_secret) bodyPreview.x_consumer_secret = "[redacted]";
        if (bodyPreview.xai_api_key) bodyPreview.xai_api_key = "[redacted]";
        if (parsed?.images) delete bodyPreview.images?.[0]?.data_url;
      } catch {
        bodyPreview = { note: "large payload", bytes: options.body.length };
      }
    } else {
      try {
        bodyPreview = JSON.parse(options.body);
        if (bodyPreview?.client_secret) bodyPreview.client_secret = "[redacted]";
        if (bodyPreview?.consumer_secret) bodyPreview.consumer_secret = "[redacted]";
        if (bodyPreview?.x_consumer_secret) bodyPreview.x_consumer_secret = "[redacted]";
        if (bodyPreview?.xai_api_key) bodyPreview.xai_api_key = "[redacted]";
      } catch {
        bodyPreview = options.body.slice(0, 200);
      }
    }
  }

  if (!skipLog) {
    activityLog.push({
      level: "info",
      message: `→ ${method} ${path}`,
      data: bodyPreview ? { request: bodyPreview } : undefined,
    });
  }

  try {
    const res = await rawFetch(path, options, timeoutMs);
    const data = await res.json().catch(() => ({}));
    const ms = performance.now() - t0;
    const traceId = res.headers.get("X-Trace-Id") || data.trace_id;

    if (!res.ok) {
      if (res.status === 429) {
        stampStudioCreditIncident("network.throttle", `Throttled ${method} ${path}`, { path, method, status: 429 });
      }
      const detail = data.detail;
      const msg = formatApiDetail(detail, res.statusText, res.status);
      if (!skipLog) {
        activityLog.push({
          level: "error",
          message: `✗ ${method} ${path} (${res.status})`,
          trace_id: traceId,
          duration_ms: ms,
          status: res.status,
          data: { error: msg, trace_id: traceId, ...data },
        });
      }
      if (!skipLog) activityLog.refreshServerDebounced();
      // Do not clearSession on 401 here — uvicorn KeepAlive/502 hops can look
      // like auth failures. Drop the JWT only when it is past exp.
      if (res.status === 401 && isTokenExpired()) {
        try {
          setEditStatus?.("error", "Session expired — sign in again to load projects.");
        } catch (_) { }
      }
      const err = new Error(traceId ? `${msg} [trace #${traceId}]` : msg);
      err.status = res.status;
      if (detail && typeof detail === "object" && !Array.isArray(detail)) {
        err.code = detail.code || null;
        err.detail = detail;
      }
      throw err;
    }

    const logData = { ...data };
    if (logData.trace?.ai?.raw_preview) {
      logData.ai_raw_preview = logData.trace.ai.raw_preview;
    }
    delete logData.trace;

    if (!skipLog) {
      activityLog.push({
        level: "info",
        message: `✓ ${method} ${path}`,
        trace_id: traceId || data.trace_id,
        duration_ms: ms,
        status: res.status,
        data: summarizeResponse(logData),
      });
      if (data.trace) {
        activityLog.push({
          level: "info",
          message: "AI trace",
          trace_id: traceId || data.trace_id,
          data: data.trace,
        });
      }
      activityLog.refreshServerDebounced();
    }
    return data;
  } catch (err) {
    const ms = performance.now() - t0;
    if (err.name === "AbortError") {
      if (userCancelRequested || options.signal?.aborted) {
        activityLog.push({ level: "info", message: `✗ ${method} ${path} (canceled)`, duration_ms: ms });
        throw new Error("Generation canceled.");
      }
      stampStudioCreditIncident("network.timeout", `Request timed out ${method} ${path}`, { path, method, name: err.name });
      const isPrompt = path.includes("/prompt");
      const msg = isPrompt
        ? "Generation request timed out waiting for the server. The job may still be running — refresh and check History. GPT-5.6 Sol can take a long time; do not cancel if progress is still updating."
        : "Request timed out — is the server running?";
      activityLog.push({ level: "error", message: `✗ ${method} ${path} (timeout)`, duration_ms: ms, data: { error: msg } });
      throw new Error(msg);
    }
    if (err.message === "Failed to fetch" || /load failed|networkerror/i.test(err.message || "")) {
      stampStudioCreditIncident(
        studioNetworkKind({ name: err.name, message: err.message, kind: "fetch.fail" }),
        `Fetch failed ${method} ${path}`,
        { path, method, name: err.name, message: err.message },
      );
      const isPrompt = path.includes("/prompt");
      const msg = isPrompt
        ? "Connection lost during generation (server may have restarted mid-build). Refresh the page and retry — use a simpler prompt if it keeps failing."
        : "Cannot reach server — refresh the page. If it persists, the backend service may need a restart.";
      activityLog.push({ level: "error", message: `✗ ${method} ${path}`, duration_ms: ms, data: { error: msg } });
      const net = new Error(msg);
      net.status = err.status || 0;
      throw net;
    }
    if (!err.message?.includes("[trace #")) {
      activityLog.push({ level: "error", message: `✗ ${method} ${path}`, duration_ms: ms, data: { error: formatUserError(err) } });
    }
    const wrapped = new Error(formatUserError(err));
    wrapped.status = err.status || 0;
    wrapped.code = err.code;
    wrapped.detail = err.detail;
    throw wrapped;
  }
}

function summarizeResponse(data) {
  if (!data || typeof data !== "object") return data;
  const out = { ...data };
  if (out.actions) out.actions = `[${out.actions.length} ops]`;
  return out;
}

function formatCostUsd(value) {
  if (value == null || !Number.isFinite(Number(value))) return null;
  const n = Number(value);
  if (n === 0) return "$0.00";
  if (n < 0.01) return `$${n.toFixed(4)}`;
  return `$${n.toFixed(2)}`;
}

function promptKeyOptionValue(source, keyId) {
  return `${source}:${keyId}`;
}

function parsePromptKeyOptionValue(value) {
  if (!value || !String(value).includes(":")) return null;
  const [source, ...rest] = String(value).split(":");
  const keyId = rest.join(":");
  if (!source || !keyId) return null;
  return { source, keyId };
}

function normalizePlatformProviderId(provider) {
  const p = String(provider || "openai").trim().toLowerCase();
  if (p === "anthropic" || p === "claude") return "anthropic";
  if (p === "kimi" || p === "moonshot") return "kimi";
  if (p === "xai" || p === "grok") return "xai";
  if (p === "gemini" || p === "google") return "gemini";
  if (p === "qwen" || p === "dashscope" || p === "alibaba") return "qwen";
  return "openai";
}

function platformProviderLabel(provider) {
  const p = normalizePlatformProviderId(provider);
  if (p === "anthropic") return "Anthropic";
  if (p === "kimi") return "Kimi";
  if (p === "xai") return "Grok";
  if (p === "gemini") return "Gemini";
  if (p === "qwen") return "Qwen";
  return "OpenAI";
}

function platformKeyDisplayName(provider) {
  return "Render3D Key";
}

/** True when a stored platform:* key disagrees with the account's Render3D provider. */
function storedPlatformConflictsWithAccount(value, status) {
  const parsed = parsePromptKeyOptionValue(value);
  if (!parsed || parsed.source !== "platform") return false;
  const preferred = normalizePlatformProviderId(status?.credits?.platform_provider);
  const keyId = normalizePlatformProviderId(parsed.keyId);
  return keyId !== preferred;
}

function defaultPlatformModelForProvider(provider, status = aiStatus) {
  const credits = status?.credits || {};
  const pinned = String(credits.platform_model || "").trim();
  const prov = normalizePlatformProviderId(provider);
  if (prov === "anthropic") {
    if (pinned && !/^(gpt|o1|o3|chatgpt|kimi)/i.test(pinned)) return pinned;
    return "claude-opus-4-8";
  }
  if (prov === "kimi") {
    if (pinned && /^kimi/i.test(pinned)) return pinned;
    return "kimi-k3";
  }
  // Preserve explicit valid pins; otherwise use the shared Astra default.
  if (pinned && /^(gpt|o1|o3|chatgpt)/i.test(pinned) && !isRetiredOpenAiPromptModel(pinned)) return pinned;
  return DEFAULT_AI_MODEL;
}

function getStoredPromptAiKeyValue() {
  try {
    return localStorage.getItem(LS_PROMPT_AI_KEY) || "";
  } catch {
    return "";
  }
}

function getProjectPromptAiKeyMap() {
  try {
    return JSON.parse(localStorage.getItem(LS_PROJECT_PROMPT_AI_KEY) || "{}") || {};
  } catch {
    return {};
  }
}

function getStoredProjectPromptAiKeyValue(pid = projectId) {
  if (!pid) return "";
  const map = getProjectPromptAiKeyMap();
  return typeof map[pid] === "string" ? map[pid] : "";
}

function storeProjectPromptAiKeyValue(value, pid = projectId) {
  if (!pid) return;
  try {
    const map = getProjectPromptAiKeyMap();
    if (value) map[pid] = value;
    else delete map[pid];
    localStorage.setItem(LS_PROJECT_PROMPT_AI_KEY, JSON.stringify(map));
  } catch (_) { }
}

function storePromptAiKeyValue(value, { projectScoped = true } = {}) {
  try {
    if (value) localStorage.setItem(LS_PROMPT_AI_KEY, value);
    else localStorage.removeItem(LS_PROMPT_AI_KEY);
  } catch (_) { }
  if (projectScoped) storeProjectPromptAiKeyValue(value);
}

function defaultPromptKeyValue(status) {
  // New / unset picker: subscription logins win over a saved personal API key.
  if (chatgptSubscriptionReady(status)) {
    return promptKeyOptionValue("chatgpt", "subscription");
  }
  if (cursorSubscriptionReady(status)) {
    return promptKeyOptionValue("cursor", "subscription");
  }
  if (claudeSubscriptionReady(status)) {
    return promptKeyOptionValue("claude", "subscription");
  }
  // Prefer the activated personal key so "Save & activate" / Use this stick,
  // instead of silently falling back to a team or Render3D Claude key.
  if (status?.active_key_id) {
    return promptKeyOptionValue("personal", status.active_key_id);
  }
  const eff = status?.effective;
  if (eff?.source === "platform" && (eff?.key_id || eff?.provider)) {
    return promptKeyOptionValue("platform", eff.key_id || normalizePlatformProviderId(eff.provider));
  }
  if (eff?.key_id && eff?.source) {
    return promptKeyOptionValue(eff.source, eff.key_id);
  }
  const platformKeys = getPlatformPromptKeys(status);
  if (platformKeys.length && status?.credits?.use_platform_key) {
    const preferred = normalizePlatformProviderId(status.credits.platform_provider);
    const match = platformKeys.find((k) => k.id === preferred) || platformKeys[0];
    return promptKeyOptionValue("platform", match.id);
  }
  return "";
}

function getSelectedPromptAiKey() {
  return parsePromptKeyOptionValue(document.getElementById("prompt-ai-key-select")?.value);
}

function getPromptAiKeyBodyFields({ surface = "prompt" } = {}) {
  const pinned = getPinnedPromptKey();
  if (pinned && !getSelectedPromptAiKey()) selectPromptAiKeyValue(pinned);
  const picked = getSelectedPromptAiKey() || parsePromptKeyOptionValue(pinned);
  const info = getSelectedPromptModelInfo();
  const fields = {};
  if (picked?.source === "chatgpt" || picked?.source === "subscription") {
    fields.ai_key_source = "chatgpt";
    if (info?.model) fields.model = info.model;
  } else if (picked?.source === "cursor") {
    fields.ai_key_source = "cursor";
    if (info?.model) fields.model = info.model;
  } else if (picked?.source === "claude") {
    fields.ai_key_source = "claude";
    if (info?.model) fields.model = info.model;
  } else {
    if (picked?.keyId) {
      fields.ai_key_id = picked.keyId;
      fields.ai_key_source = picked.source;
    }
    if (info?.model) fields.model = info.model;
  }
  if (surface === "wiring" || surface === "diagnose") {
    fields.model = loadWiringPreferredModel();
  }
  Object.assign(fields, modelReasoningRequestField(info?.provider, fields.model || info?.model));
  return fields;
}

function getPlatformPromptKeys(status) {
  const credits = status?.credits || {};
  const balance = Number(credits.balance_cents || 0);
  if (!credits.available || balance <= 0) return [];
  if (Array.isArray(status?.platform_keys) && status.platform_keys.length) {
    return status.platform_keys.map((key) => {
      const provider = normalizePlatformProviderId(key.provider || key.id);
      return {
        id: key.id || provider,
        name: key.name || platformKeyDisplayName(provider),
        provider,
        model: key.model || "",
        source: "platform",
      };
    });
  }
  const providers = credits.providers || {};
  const preferred = normalizePlatformProviderId(credits.platform_provider);
  const preferredModel = credits.platform_model || "";
  const models = credits.models || [];
  const keys = [];
  if (providers.openai) {
    keys.push({
      id: "openai",
      name: "Render3D Key",
      provider: "openai",
      model: preferred === "openai" ? preferredModel : (models.find((m) => m.provider === "openai")?.model || ""),
      source: "platform",
    });
  }
  if (providers.anthropic) {
    keys.push({
      id: "anthropic",
      name: "Render3D Key",
      provider: "anthropic",
      model: preferred === "anthropic" ? preferredModel : (models.find((m) => m.provider === "anthropic")?.model || ""),
      source: "platform",
    });
  }
  if (providers.kimi) {
    keys.push({
      id: "kimi",
      name: "Render3D Key",
      provider: "kimi",
      model: preferred === "kimi" ? preferredModel : (models.find((m) => m.provider === "kimi")?.model || "kimi-k3"),
      source: "platform",
    });
  }
  return keys;
}

/** Platform OpenAI / Anthropic / Kimi keys offered to anyone with Studio credits. */
function getRender3dKeyChoices(status) {
  return getPlatformPromptKeys(status).map((key) => ({
    source: "platform",
    id: key.id,
    provider: normalizePlatformProviderId(key.provider || key.id),
    model: key.model || "",
    label: platformProviderLabel(key.provider || key.id),
    name: key.name || platformKeyDisplayName(key.provider || key.id),
  }));
}

function render3dChoiceValue(choice) {
  return promptKeyOptionValue(choice.source, choice.id);
}

function findRender3dChoice(status, value) {
  const choices = getRender3dKeyChoices(status);
  const parsed = value ? parsePromptKeyOptionValue(value) : null;
  if (parsed?.source === "platform") {
    const match = choices.find((choice) => String(choice.id) === String(parsed.keyId));
    if (match) return match;
  }
  const preferred = normalizePlatformProviderId(status?.credits?.platform_provider);
  return choices.find((choice) => choice.provider === preferred) || choices[0] || null;
}

function getSelectedPromptAiKeyLabel() {
  const sel = document.getElementById("prompt-ai-key-select");
  if (!sel?.value) return aiStatus?.effective?.key_name || "Default key";
  // find label from aiStatus rather than option text
  const parsed = parsePromptKeyOptionValue(sel.value);
  if (!parsed) return aiStatus?.effective?.key_name || "Default key";
  if (parsed.source === "chatgpt" || parsed.source === "subscription") {
    return "ChatGPT subscription";
  }
  if (parsed.source === "cursor") return cursorPickerLabel();
  if (parsed.source === "claude") return claudePickerLabel();
  if (parsed.source === "platform") {
    const platformKey = getPlatformPromptKeys(aiStatus).find((k) => k.id === parsed.keyId);
    return platformKey?.name || "Render3D key";
  }
  const allKeys = [...(aiStatus?.keys || []), ...(aiStatus?.team_keys || [])];
  const found = allKeys.find((k) => k.id === parsed.keyId);
  return found?.name || "Selected key";
}

/** Flat list of selectable prompt keys for XR / shared pickers. */
function listPromptAiKeyOptions(status = aiStatus) {
  const out = [];
  const push = (source, key, fallbackName) => {
    if (!key?.id) return;
    const provider = key.provider_label || platformProviderLabel(key.provider) || "";
    const name = String(key.name || fallbackName || "Key").trim();
    const label = provider && !name.toLowerCase().includes(String(provider).toLowerCase())
      ? `${name} · ${provider}`
      : name;
    out.push({
      value: promptKeyOptionValue(source, key.id),
      label,
      source,
      id: key.id,
    });
  };
  getPlatformPromptKeys(status).forEach((key) => push("platform", key, "Render3D key"));
  if (claudeSubscriptionReady(status)) {
    out.unshift({
      value: promptKeyOptionValue("claude", "subscription"),
      label: claudePickerLabel(status),
      source: "claude",
      id: "subscription",
    });
  }
  if (cursorSubscriptionReady(status)) {
    out.unshift({
      value: promptKeyOptionValue("cursor", "subscription"),
      label: cursorPickerLabel(status),
      source: "cursor",
      id: "subscription",
    });
  }
  if (chatgptSubscriptionReady(status)) {
    out.unshift({
      value: promptKeyOptionValue("chatgpt", "subscription"),
      label: chatgptPickerLabel(status),
      source: "chatgpt",
      id: "subscription",
    });
  }
  (status?.keys || []).forEach((key) => push("personal", key, "Personal key"));
  (status?.team_keys || [])
    .filter((k) => k.enabled !== false && aiKeyAllowedForCurrentProject(k))
    .forEach((key) => push("team", key, "Shared key"));
  return out;
}

function xrPromptHistoryForPanel() {
  return (latestPromptHistoryEntries || []).slice(0, 8).map((entry) => ({
    id: entry.id,
    prompt: String(entry.original_prompt || entry.prompt || "").replace(/\s+/g, " ").trim().slice(0, 80),
    model: entry.model || "",
  })).filter((row) => row.prompt);
}

function reuseXrPromptHistoryIndex(index) {
  const rows = xrPromptHistoryForPanel();
  const id = rows[Number(index)]?.id;
  const match = (latestPromptHistoryEntries || []).find((e) => String(e.id) === String(id));
  if (!match) return Promise.resolve(false);
  return reusePromptHistoryEntry(match, { useOriginal: true });
}

function cycleXrPromptKey(dir = 1) {
  xrKeyUserOverride = true;
  const opts = listPromptAiKeyOptions(aiStatus);
  if (!opts.length) return false;
  const cur = document.getElementById("prompt-ai-key-select")?.value || "";
  const i = Math.max(0, opts.findIndex((o) => o.value === cur));
  const next = opts[(i + dir + opts.length) % opts.length];
  return selectPromptAiKeyValue(next.value);
}

let xrKeyUserOverride = false;

function preferXrOpenAiSubscription({ force = false } = {}) {
  if (!chatgptSubscriptionReady()) return false;
  if (xrKeyUserOverride && !force) return false;
  const value = promptKeyOptionValue("chatgpt", "subscription");
  const sel = document.getElementById("prompt-ai-key-select");
  if (sel && ![...sel.options].some((opt) => opt.value === value)) {
    try { renderPromptAiKeySelect(aiStatus, { preserveSelection: false }); } catch (_) { }
  }
  if (!sel || ![...sel.options].some((opt) => opt.value === value)) return false;
  if (sel.value === value) return true;
  return selectPromptAiKeyValue(value);
}

function listXrPromptModelOptions() {
  const parsed = parsePromptKeyOptionValue(document.getElementById("prompt-ai-key-select")?.value);
  const source = String(parsed?.source || "");
  const short = (o) => ({ value: o.value, label: String(o.label || o.value).replace(/ · .*/, "") });
  if (source === "chatgpt" || source === "subscription") {
    return CHATGPT_CODEX_MODEL_OPTIONS.map(short);
  }
  if (source === "cursor") {
    return CURSOR_SUBSCRIPTION_MODEL_OPTIONS.map(short);
  }
  if (source === "claude") {
    return (PROMPT_KEY_MODEL_OPTIONS.anthropic || []).map(short);
  }
  let provider = "openai";
  if (source === "platform") {
    provider = normalizePlatformProviderId(parsed.keyId);
  } else {
    provider = String(getSelectedPromptModelInfo()?.provider || "openai").toLowerCase();
  }
  const opts = PROMPT_KEY_MODEL_OPTIONS[provider]
    || [...OPENAI_GPT56_MODEL_OPTIONS, ...OPENAI_GPT6_MODEL_OPTIONS];
  return opts.map(short);
}

function currentXrPromptModelValue() {
  const opts = listXrPromptModelOptions();
  const info = getSelectedPromptModelInfo();
  const v = String(info.model || "");
  if (opts.some((o) => o.value === v)) return v;
  return opts[0]?.value || v;
}

function cycleXrPromptModel(dir = 1) {
  const opts = listXrPromptModelOptions();
  if (!opts.length) return Promise.resolve(false);
  const cur = currentXrPromptModelValue();
  const i = Math.max(0, opts.findIndex((o) => o.value === cur));
  const next = opts[(i + dir + opts.length) % opts.length];
  return applyXrPromptModel(next.value);
}

async function applyXrPromptModel(newModel) {
  const parsed = parsePromptKeyOptionValue(document.getElementById("prompt-ai-key-select")?.value);
  const source = String(parsed?.source || "chatgpt");
  const keyId = parsed?.keyId || parsed?.id || "subscription";
  if (source === "chatgpt" || source === "subscription") {
    storeChatgptCodexModel(newModel);
    selectPromptAiKeyValue(promptKeyOptionValue("chatgpt", "subscription"));
    syncPromptKeyPill(aiStatus);
    return true;
  }
  if (source === "cursor") {
    storeCursorSubscriptionModel(newModel);
    selectPromptAiKeyValue(promptKeyOptionValue("cursor", "subscription"));
    syncPromptKeyPill(aiStatus);
    return true;
  }
  if (source === "claude") {
    storeClaudeSubscriptionModel(newModel);
    selectPromptAiKeyValue(promptKeyOptionValue("claude", "subscription"));
    syncPromptKeyPill(aiStatus);
    return true;
  }
  try {
    if (source === "platform") {
      const data = await api("/api/user/ai-credits", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          use_platform_key: true,
          platform_provider: normalizePlatformProviderId(keyId),
          platform_model: newModel || null,
        }),
      });
      const updatedAi = { ...(data.ai || aiStatus || {}), credits: data.credits || data.ai?.credits };
      aiKeyUi?.render(updatedAi);
      renderAIStatus(updatedAi);
    } else if (source === "team") {
      const teamKey = (aiStatus?.team_keys || []).find((key) => key.id === keyId);
      if (!teamKey?.team_id) return false;
      const data = await api(`/api/teams/${teamKey.team_id}/ai-keys/${keyId}/toggle`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ use_key: true, model: newModel }),
      });
      const updatedAi = { ...(data.ai || {}), keys: data.ai?.keys || [] };
      aiKeyUi?.render(updatedAi);
      renderAIStatus(updatedAi);
    } else if (keyId) {
      const data = await api(`/api/user/ai-keys/${keyId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ model: newModel }),
      });
      const updatedAi = { ...(data.ai || {}), keys: data.ai?.keys || [] };
      aiKeyUi?.render(updatedAi);
      renderAIStatus(updatedAi);
    }
    selectPromptAiKeyValue(promptKeyOptionValue(source, keyId));
    syncPromptKeyPill(aiStatus);
    return true;
  } catch (err) {
    console.warn("[xr] apply model", err);
    return false;
  }
}

function teamKeyDisplayModel(key) {
  return key?.effective_model || key?.model || "";
}

function authoringModelFromKey(model, provider) {
  const m = String(model || "").trim();
  if (!m) return "";
  if (String(provider || "").toLowerCase() === "openai" && isRetiredOpenAiPromptModel(m)) {
    return DEFAULT_AI_MODEL;
  }
  if (/codex/i.test(m)) {
    return String(provider || "").toLowerCase() === "openai" ? DEFAULT_AI_MODEL : "";
  }
  return m;
}

function getSelectedPromptModelInfo() {
  const parsed = parsePromptKeyOptionValue(document.getElementById("prompt-ai-key-select")?.value);
  if (parsed?.source === "chatgpt" || parsed?.source === "subscription") {
    return { model: loadChatgptCodexModel(), provider: "openai", source: "chatgpt" };
  }
  if (parsed?.source === "cursor") {
    return { model: loadCursorSubscriptionModel(), provider: "cursor", source: "cursor" };
  }
  if (parsed?.source === "claude") {
    return { model: loadClaudeSubscriptionModel(), provider: "anthropic", source: "claude" };
  }
  if (parsed?.source === "platform") {
    const platformKey = getPlatformPromptKeys(aiStatus).find((k) => k.id === parsed.keyId);
    if (platformKey) {
      const provider = platformKey.provider || "";
      return { model: authoringModelFromKey(platformKey.model || "", provider), provider, source: "platform" };
    }
  }
  const allKeys = [...(aiStatus?.keys || []), ...(aiStatus?.team_keys || [])];
  const found = parsed ? allKeys.find((k) => k.id === parsed.keyId) : null;
  if (found) {
    const provider = found.provider || "";
    return {
      model: authoringModelFromKey(teamKeyDisplayModel(found) || found.model || "", provider),
      provider,
      source: parsed?.source || "personal",
    };
  }
  if (chatgptSubscriptionReady() && !(aiStatus?.keys || []).length && !(aiStatus?.team_keys || []).length) {
    return { model: loadChatgptCodexModel(), provider: "openai", source: "chatgpt" };
  }
  if (cursorSubscriptionReady() && !(aiStatus?.keys || []).length && !(aiStatus?.team_keys || []).length) {
    return { model: loadCursorSubscriptionModel(), provider: "cursor", source: "cursor" };
  }
  if (claudeSubscriptionReady() && !(aiStatus?.keys || []).length && !(aiStatus?.team_keys || []).length) {
    return { model: loadClaudeSubscriptionModel(), provider: "anthropic", source: "claude" };
  }
  if (aiStatus?.ai_ready) {
    const eff = aiStatus.effective || {};
    const provider = eff.provider || aiStatus.provider || "";
    return {
      model: authoringModelFromKey(eff.model || aiStatus.model || "", provider),
      provider,
      source: String(eff.source || ""),
    };
  }
  return { model: "", provider: "", source: "" };
}

let lastPromptDefaultKeyValue = "";

function promptKeyProviderLabel(providerName = "", source = "") {
  const s = String(source || "").toLowerCase();
  const p = String(providerName || "").toLowerCase();
  if (s === "chatgpt" || s === "subscription" || p === "openai") return "ChatGPT";
  if (s === "claude" || p === "anthropic") return "Claude";
  if (s === "cursor" || p === "cursor") return "Cursor";
  return "";
}

function promptKeyProviderMark(providerName = "", source = "") {
  const s = String(source || "").toLowerCase();
  const p = String(providerName || "").toLowerCase();
  if (s === "chatgpt" || s === "subscription" || p === "openai") return { provider: "openai", letter: "G" };
  if (s === "claude" || p === "anthropic") return { provider: "anthropic", letter: "C" };
  if (s === "cursor" || p === "cursor") return { provider: "cursor", letter: "◆" };
  if (s === "gemini" || p === "gemini" || p === "google") return { provider: "gemini", letter: "G" };
  if (s === "xai" || s === "grok" || p === "xai") return { provider: "xai", letter: "X" };
  if (s === "kimi" || p === "kimi") return { provider: "kimi", letter: "K" };
  if (s === "qwen" || p === "qwen") return { provider: "qwen", letter: "Q" };
  return { provider: "", letter: "" };
}

// Update the pill button text to reflect current selection
function syncPromptKeyPill(status) {
  const sel = document.getElementById("prompt-ai-key-select");
  const parsed = sel?.value ? parsePromptKeyOptionValue(sel.value) : null;
  const platformKeys = getPlatformPromptKeys(status);
  const platformFound = parsed?.source === "platform"
    ? platformKeys.find((k) => k.id === parsed.keyId)
    : null;
  const allKeys = [...(status?.keys || []), ...(status?.team_keys || [])];
  const found = parsed && parsed.source !== "platform"
    ? allKeys.find((k) => k.id === parsed.keyId)
    : null;

  let keyName, modelName, providerName;
  if (platformFound) {
    keyName = platformFound.name || platformKeyDisplayName(platformFound.provider) || "Render3D Key";
    modelName = platformFound.model || "";
    providerName = platformFound.provider || "";
  } else if (found) {
    keyName = found.name || found.provider_label || "";
    modelName = teamKeyDisplayModel(found) || found.model || "";
    providerName = found.provider || "";
  } else if (parsed?.source === "chatgpt" || parsed?.source === "subscription") {
    keyName = chatgptPickerLabel(status);
    modelName = loadChatgptCodexModel();
    providerName = "openai";
  } else if (parsed?.source === "cursor") {
    keyName = cursorPickerLabel(status);
    modelName = loadCursorSubscriptionModel();
    providerName = "cursor";
  } else if (parsed?.source === "claude") {
    keyName = claudePickerLabel(status);
    modelName = loadClaudeSubscriptionModel();
    providerName = "anthropic";
  } else if (status?.ai_ready) {
    const eff = status.effective;
    keyName = "";
    modelName = eff?.model || status.model || "";
    providerName = eff?.provider || status.provider || "";
  } else if (chatgptSubscriptionReady(status)) {
    keyName = chatgptPickerLabel(status);
    modelName = loadChatgptCodexModel();
    providerName = "openai";
  } else if (cursorSubscriptionReady(status)) {
    keyName = cursorPickerLabel(status);
    modelName = loadCursorSubscriptionModel();
    providerName = "cursor";
  } else if (claudeSubscriptionReady(status)) {
    keyName = claudePickerLabel(status);
    modelName = loadClaudeSubscriptionModel();
    providerName = "anthropic";
  } else {
    keyName = "No key";
    modelName = "";
    providerName = "";
  }
  const pickerSource = parsed?.source || providerName || "";
  const displayName = keyName || promptKeyProviderLabel(providerName, pickerSource) || (modelName ? "API key" : "");
  const modelLabel = formatModelLabel(modelName, providerName) || modelName || displayName;

  // Sync all pill buttons (design prompt + wiring prompt + circuit debugger)
  const wiringModel = loadWiringPreferredModel();
  const wiringLabel = formatModelLabel(wiringModel, providerName || "openai") || wiringModel || modelLabel;
  const mark = promptKeyProviderMark(providerName, pickerSource);
  for (const [nameId, modelId] of [
    ["prompt-key-pill-name", "prompt-key-pill-model"],
    ["imagine-key-pill-name", "imagine-key-pill-model"],
    ["wiring-key-pill-name", "wiring-key-pill-model"],
    ["wdbg-key-pill-name", "wdbg-key-pill-model"],
  ]) {
    const nameEl = document.getElementById(nameId);
    const modelEl = document.getElementById(modelId);
    const wiringPill = nameId.startsWith("wiring-") || nameId.startsWith("wdbg-");
    if (nameEl) {
      nameEl.textContent = displayName;
      nameEl.classList.toggle("hidden", !displayName);
    }
    if (modelEl) modelEl.textContent = wiringPill ? wiringLabel : modelLabel;
  }
  for (const markId of ["wiring-key-pill-mark", "wdbg-key-pill-mark"]) {
    const markEl = document.getElementById(markId);
    if (!markEl) continue;
    markEl.dataset.provider = mark.provider;
    markEl.textContent = mark.letter;
    markEl.hidden = !mark.provider;
    markEl.setAttribute("aria-hidden", mark.provider ? "false" : "true");
  }
  const wiringKeyBtn = document.getElementById("wiring-key-picker-btn");
  if (wiringKeyBtn) {
    wiringKeyBtn.title = [displayName, wiringLabel].filter(Boolean).join(" · ") || "Select AI key and model";
  }
  document.querySelectorAll("[data-vtl-key-name]").forEach((el) => {
    el.textContent = keyName || "API key";
  });
  document.querySelectorAll("[data-vtl-key-model]").forEach((el) => {
    el.textContent = modelLabel || "";
  });
  syncAgentDefaultsForSelectedKey();
  syncSpeedModeForSelectedModel();
  syncPromptWeeklyUsageChip(status);
  window.dispatchEvent(new CustomEvent("render3d:prompt-ai-selection-changed", {
    detail: { provider: providerName, model: modelName, source: pickerSource },
  }));
}

