function buildCursorSubscriptionModelOptionsHTML(selected) {
  return CURSOR_SUBSCRIPTION_MODEL_OPTIONS.map((o) =>
    `<option value="${o.value}"${o.value === selected ? " selected" : ""}>${o.label}</option>`
  ).join("");
}

function buildClaudeSubscriptionModelOptionsHTML(selected) {
  const opts = PROMPT_KEY_MODEL_OPTIONS.anthropic || [];
  const current = opts.some((o) => o.value === selected) ? selected : defaultClaudeSubscriptionModel();
  return opts.map((o) =>
    `<option value="${o.value}"${o.value === current ? " selected" : ""}>${o.label}</option>`
  ).join("");
}

function buildGroupedModelOptionsHTML(groups, selected) {
  const known = groups.flatMap((g) => g.options.map((o) => o.value));
  const current = known.includes(selected) ? selected : (groups[0]?.options[0]?.value || "");
  let html = groups.map((group) => {
    const inner = group.options.map((o) =>
      `<option value="${o.value}"${o.value === current ? " selected" : ""}>${o.label}</option>`
    ).join("");
    return `<optgroup label="${group.label}">${inner}</optgroup>`;
  }).join("");
  if (selected && !known.includes(selected) && !isRetiredOpenAiPromptModel(selected)) {
    const fallbackLabel = formatModelLabel(selected, "openai") || selected;
    html += `<option value="${selected}" selected>${fallbackLabel}</option>`;
  }
  return html;
}

function openaiPickerGroups({ includeGpt55 = false } = {}) {
  const groups = [
    { label: "GPT-6", options: OPENAI_GPT6_MODEL_OPTIONS },
    { label: "GPT-5.6", options: OPENAI_GPT56_MODEL_OPTIONS },
  ];
  if (includeGpt55) {
    groups.push({ label: "GPT-5.5", options: OPENAI_GPT55_MODEL_OPTIONS });
  }
  return groups;
}

function promptKeyPopupIsWiring() {
  const id = String(promptKeyPopupAnchor?.id || "");
  return id === "wiring-key-picker-btn" || id === "wdbg-key-picker-btn";
}

function loadWiringPreferredModel() {
  try {
    const raw = String(localStorage.getItem(LS_WIRING_MODEL) || "").trim();
    if (raw && !isRetiredOpenAiPromptModel(raw)) return raw;
  } catch (_) { }
  return DEFAULT_AI_MODEL;
}

function storeWiringPreferredModel(value) {
  const groups = openaiPickerGroups({ includeGpt55: true });
  const known = groups.flatMap((g) => g.options.map((o) => o.value));
  const next = known.includes(value) ? value : DEFAULT_AI_MODEL;
  try { localStorage.setItem(LS_WIRING_MODEL, next); } catch (_) { }
  return next;
}

function buildChatgptCodexModelOptionsHTML(selected, { includeGpt55 = false } = {}) {
  const groups = openaiPickerGroups({ includeGpt55 });
  const known = groups.flatMap((g) => g.options.map((o) => o.value));
  const current = known.includes(selected) ? selected : loadChatgptCodexModel();
  return buildGroupedModelOptionsHTML(groups, current);
}

function isRetiredOpenAiPromptModel(value) {
  const m = String(value || "").trim().toLowerCase();
  return m === "gpt-5.5-pro" || m.startsWith("gpt-5.5-pro");
}

function buildModelOptionsHTML(provider, currentModel, allowedModels = null, { includeGpt55 = false } = {}) {
  if (String(provider || "").toLowerCase() === "openai") {
    let groups = openaiPickerGroups({ includeGpt55 });
    if (Array.isArray(allowedModels) && allowedModels.length) {
      const allow = new Set(allowedModels);
      groups = groups
        .map((group) => ({ ...group, options: group.options.filter((o) => allow.has(o.value)) }))
        .filter((group) => group.options.length);
      if (!groups.length) groups = openaiPickerGroups({ includeGpt55 });
    }
    let selected = currentModel;
    if (/codex/i.test(String(selected || ""))) selected = DEFAULT_AI_MODEL;
    if (isRetiredOpenAiPromptModel(selected)) selected = DEFAULT_AI_MODEL;
    return buildGroupedModelOptionsHTML(groups, selected);
  }
  let opts = PROMPT_KEY_MODEL_OPTIONS[provider] || PROMPT_KEY_MODEL_OPTIONS.openai;
  if (Array.isArray(allowedModels) && allowedModels.length) {
    const allow = new Set(allowedModels);
    const filtered = opts.filter((o) => allow.has(o.value));
    if (filtered.length) opts = filtered;
  }
  const known = opts.map((o) => o.value);
  let selected = currentModel;
  if (/codex/i.test(String(selected || ""))) {
    selected = selected;
  }
  let html = opts.map((o) =>
    `<option value="${o.value}"${o.value === selected ? " selected" : ""}>${o.label}</option>`
  ).join("");
  if (selected && !known.includes(selected)) {
    const fallbackLabel = formatModelLabel(selected, provider) || selected;
    html += `<option value="${selected}" selected>${fallbackLabel}</option>`;
  }
  return html;
}

function aiKeyAllowedForCurrentProject(key) {
  if (!key || !key.scope_type || key.scope_type === "all") return true;
  if (key.scope_type === "project") {
    return !!projectId && String(key.scope_project_id || "") === String(projectId);
  }
  if (key.scope_type === "folder") {
    const current = allProjects.find((project) => String(project.id || "") === String(projectId || ""));
    return !!current?.folder_id && String(current.folder_id) === String(key.scope_project_id || "");
  }
  return true;
}

let promptKeySelectionContext = "";

function getPinnedPromptKey(status = aiStatus) {
  return pinnedPromptKey(status, currentUser || getStoredUser());
}

function renderPromptAiKeySelect(status, { preserveSelection = true } = {}) {
  const sel = document.getElementById("prompt-ai-key-select");
  if (!sel) return;
  const prev = preserveSelection ? sel.value : "";
  const pinned = getPinnedPromptKey(status);
  const context = `${(currentUser || getStoredUser())?.id || "guest"}:${projectId || "new"}`;
  const sameContext = promptKeySelectionContext === context;
  promptKeySelectionContext = context;
  const defaultValue = pinned || defaultPromptKeyValue(status);
  sel.innerHTML = "";

  const personalKeys = status?.keys || [];
  const teamKeys = (status?.team_keys || []).filter((k) => k.enabled !== false && aiKeyAllowedForCurrentProject(k));
  const platformKeys = getPlatformPromptKeys(status);
  const chatgptReady = chatgptSubscriptionReady(status);
  const cursorReady = cursorSubscriptionReady(status);
  const claudeReady = claudeSubscriptionReady(status);

  if (!personalKeys.length && !teamKeys.length && !platformKeys.length && !chatgptReady && !cursorReady && !claudeReady && !pinned) {
    sel.disabled = true;
    const opt = document.createElement("option");
    opt.value = "";
    opt.textContent = "";
    sel.appendChild(opt);
    syncPromptKeyPill(status);
    return;
  }

  if (chatgptReady) {
    const opt = document.createElement("option");
    opt.value = promptKeyOptionValue("chatgpt", "subscription");
    opt.textContent = chatgptPickerLabel(status);
    sel.appendChild(opt);
  }
  if (cursorReady) {
    const opt = document.createElement("option");
    opt.value = promptKeyOptionValue("cursor", "subscription");
    opt.textContent = cursorPickerLabel(status);
    sel.appendChild(opt);
  }
  if (claudeReady) {
    const opt = document.createElement("option");
    opt.value = promptKeyOptionValue("claude", "subscription");
    opt.textContent = claudePickerLabel(status);
    sel.appendChild(opt);
  }
  platformKeys.forEach((key) => {
    const opt = document.createElement("option");
    opt.value = promptKeyOptionValue("platform", key.id);
    opt.textContent = key.name || "Render3D key";
    sel.appendChild(opt);
  });
  personalKeys.forEach((key) => {
    const opt = document.createElement("option");
    opt.value = promptKeyOptionValue("personal", key.id);
    opt.textContent = key.name || "Personal key";
    sel.appendChild(opt);
  });
  teamKeys.forEach((key) => {
    const opt = document.createElement("option");
    opt.value = promptKeyOptionValue("team", key.id);
    opt.textContent = key.name || "Shared key";
    sel.appendChild(opt);
  });

  if (pinned && ![...sel.options].some((opt) => opt.value === pinned)) {
    const opt = document.createElement("option");
    opt.value = pinned;
    opt.textContent = "OpenAI Sub — reconnect to use";
    sel.appendChild(opt);
  }
  sel.disabled = false;
  const projectStored = getStoredProjectPromptAiKeyValue();
  const chatgptValue = chatgptReady ? promptKeyOptionValue("chatgpt", "subscription") : "";
  const candidates = promptKeyCandidates({
    pinned, previous: prev, sameContext, preserveSelection, projectStored,
    chatgpt: chatgptValue, globalStored: getStoredPromptAiKeyValue(), fallback: defaultValue,
  });
  for (const value of candidates) {
    if (storedPlatformConflictsWithAccount(value, status)) continue;
    if ([...sel.options].some((opt) => opt.value === value)) {
      sel.value = value;
      storePromptAiKeyValue(sel.value);
      lastPromptDefaultKeyValue = defaultValue || sel.value || "";
      syncPromptKeyPill(status);
      return;
    }
  }
  sel.value = defaultValue || sel.options[0]?.value || "";
  if (sel.value) storePromptAiKeyValue(sel.value);
  lastPromptDefaultKeyValue = defaultValue || sel.value || "";
  syncPromptKeyPill(status);

  // Refresh popup if open
  if (promptKeyPopupOpen) renderPromptKeyPopup(status);
}

// ── Prompt key popup ──────────────────────────────────────────────────────────
let promptKeyPopupOpen = false;
let promptKeyPopupAnchor = null; // the pill button that last opened the popup

function renderPromptKeyPopup(status) {
  const popup = document.getElementById("prompt-key-popup");
  if (!popup) return;

  const wiringPicker = promptKeyPopupIsWiring();
  const includeGpt55 = wiringPicker;
  const wiringSelected = loadWiringPreferredModel();
  const personalKeys = status?.keys || [];
  const teamKeys = (status?.team_keys || []).filter((k) => k.enabled !== false && aiKeyAllowedForCurrentProject(k));
  const render3dChoices = getRender3dKeyChoices(status);
  const currentValue = document.getElementById("prompt-ai-key-select")?.value || "";

  const isSelected = (source, id) => currentValue === promptKeyOptionValue(source, id);

  const reasoningSelect = (provider, model) => {
    const options = modelReasoningOptions(provider, model);
    const selected = loadModelReasoning(provider, model);
    return `<select class="prompt-key-popup-model-select prompt-key-popup-reasoning-select"
      data-action="change-reasoning" data-provider="${escapeHtml(provider)}" data-model="${escapeHtml(model)}"
      title="Reasoning effort for ${escapeHtml(model)}"${options.length === 1 ? " disabled" : ""}>
      ${modelReasoningOptionsHTML(provider, model, selected)}
    </select>`;
  };

  const keyRow = (key, source) => {
    const active = isSelected(source, key.id);
    const badge = BADGE_CLASS_MAP[key.provider] || "badge-openai";
    const providerLabel = key.provider_label || platformProviderLabel(key.provider);
    const keyModel = source === "team" ? teamKeyDisplayModel(key) : (key.model || "");
    const selectedModel = wiringPicker && String(key.provider || "").toLowerCase() === "openai"
      ? wiringSelected
      : keyModel;
    return `<div class="prompt-key-popup-row${active ? " active" : ""}"
         data-action="select-key" data-source="${source}" data-key-id="${key.id}">
      <div class="prompt-key-popup-check">
        <div class="prompt-key-popup-check-dot"></div>
      </div>
      <div class="prompt-key-popup-info">
        <span class="prompt-key-popup-name">
          ${key.name || "Key"}
          <span class="prompt-key-popup-badge ${badge}">${providerLabel}</span>
        </span>
      </div>
      <div class="prompt-key-popup-model-wrap">
        <select class="prompt-key-popup-model-select"
          data-action="change-model"
          data-key-id="${key.id}"
          data-source="${source}"
          title="Model for this key">
          ${buildModelOptionsHTML(key.provider, selectedModel, source === "team" ? (key.allowed_models || null) : null, { includeGpt55 })}
        </select>
        ${reasoningSelect(key.provider, selectedModel)}
      </div>
    </div>`;
  };

  const pendingShares = pendingSubscriptionShareMarkup(status);
  let html = `
    <div class="prompt-key-popup-header">
      <span class="prompt-key-popup-title">AI Key</span>
      <button type="button" class="prompt-key-popup-manage" data-action="open-key-manager">Manage keys →</button>
    </div>${pendingShares}`;

  if (!personalKeys.length && !teamKeys.length && !render3dChoices.length && !chatgptSubscriptionReady(status) && !cursorSubscriptionReady(status) && !claudeSubscriptionReady(status) && !getPinnedPromptKey(status)) {
    if (!pendingShares) html += `<p class="prompt-key-popup-empty">No keys saved. Use <strong>Manage keys</strong> to add one, or <strong>Subscriptions</strong> to use Cloud credits or sign in with ChatGPT.</p>`;
  } else {
    const chatgptReady = chatgptSubscriptionReady(status);
    const cursorReady = cursorSubscriptionReady(status);
    const claudeReady = claudeSubscriptionReady(status);
    if (chatgptReady || cursorReady || claudeReady) {
      html += `<div class="prompt-key-popup-section">Subscription</div>`;
    }
    if (chatgptReady || getPinnedPromptKey(status) === "chatgpt:subscription") {
      const chatgptActive = currentValue === promptKeyOptionValue("chatgpt", "subscription") || (!currentValue && chatgptReady && !cursorReady && !claudeReady);
      html += `<div class="prompt-key-popup-row${chatgptActive ? " active" : ""}"
           data-action="select-key" data-source="chatgpt" data-key-id="subscription">
        <div class="prompt-key-popup-check">
          <div class="prompt-key-popup-check-dot"></div>
        </div>
        <div class="prompt-key-popup-info">
          <span class="prompt-key-popup-name">
            ${chatgptPickerLabel(status)}
            <span class="prompt-key-popup-badge badge-openai">OpenAI</span>

          </span>
        </div>
            <button type="button" class="prompt-key-pin" data-action="pin-chatgpt-default"
              aria-pressed="${getPinnedPromptKey(status) === "chatgpt:subscription"}"
              title="${getPinnedPromptKey(status) === "chatgpt:subscription" ? "Unpin account default" : "Default to OpenAI subscription across projects"}"
              aria-label="${getPinnedPromptKey(status) === "chatgpt:subscription" ? "Unpin OpenAI subscription default" : "Pin OpenAI subscription as account default"}">📌</button>
        <div class="prompt-key-popup-model-wrap">
          <select class="prompt-key-popup-model-select"
            data-action="change-model"
            data-key-id="subscription"
            data-source="chatgpt"
            title="Sol, Terra, and Luna can use an API key. Astra uses this ChatGPT login.">
            ${buildChatgptCodexModelOptionsHTML(wiringPicker ? wiringSelected : loadChatgptCodexModel(), { includeGpt55 })}
          </select>
          ${reasoningSelect("openai", wiringPicker ? wiringSelected : loadChatgptCodexModel())}
        </div>
      </div>`;
    }
    if (cursorReady) {
      const cursorActive = currentValue === promptKeyOptionValue("cursor", "subscription");
      html += `<div class="prompt-key-popup-row${cursorActive ? " active" : ""}"
           data-action="select-key" data-source="cursor" data-key-id="subscription">
        <div class="prompt-key-popup-check">
          <div class="prompt-key-popup-check-dot"></div>
        </div>
        <div class="prompt-key-popup-info">
          <span class="prompt-key-popup-name">
            ${cursorPickerLabel(status)}
            <span class="prompt-key-popup-badge badge-openai">Cursor</span>
          </span>
        </div>
        <div class="prompt-key-popup-model-wrap">
          <select class="prompt-key-popup-model-select"
            data-action="change-model"
            data-key-id="subscription"
            data-source="cursor"
            title="CAD 2.0, Architect, VibeCAD, and Mesh run on your Cursor plan.">
            ${buildCursorSubscriptionModelOptionsHTML(loadCursorSubscriptionModel())}
          </select>
          ${reasoningSelect("cursor", loadCursorSubscriptionModel())}
        </div>
      </div>`;
    }
    if (claudeReady) {
      const claudeActive = currentValue === promptKeyOptionValue("claude", "subscription");
      html += `<div class="prompt-key-popup-row${claudeActive ? " active" : ""}"
           data-action="select-key" data-source="claude" data-key-id="subscription">
        <div class="prompt-key-popup-check">
          <div class="prompt-key-popup-check-dot"></div>
        </div>
        <div class="prompt-key-popup-info">
          <span class="prompt-key-popup-name">
            ${claudePickerLabel(status)}
            <span class="prompt-key-popup-badge badge-claude">Claude</span>
          </span>
        </div>
        <div class="prompt-key-popup-model-wrap">
          <select class="prompt-key-popup-model-select"
            data-action="change-model"
            data-key-id="subscription"
            data-source="claude"
            title="CAD 2.0, Architect, VibeCAD, and Mesh run on your Claude Pro/Max plan.">
            ${buildClaudeSubscriptionModelOptionsHTML(loadClaudeSubscriptionModel())}
          </select>
          ${reasoningSelect("anthropic", loadClaudeSubscriptionModel())}
        </div>
      </div>`;
    }
    if (render3dChoices.length) {
      const current = findRender3dChoice(status, currentValue) || render3dChoices[0];
      const platformActive = render3dChoices.some((c) => isSelected(c.source, c.id));
      html += `<div class="prompt-key-popup-section">Render3D Key</div>`;
      html += `<div class="prompt-key-popup-row prompt-key-popup-row--platform${platformActive ? " active" : ""}"
           data-action="select-key" data-source="platform" data-key-id="${current.id}">
        <div class="prompt-key-popup-check">
          <div class="prompt-key-popup-check-dot"></div>
        </div>
        <span class="prompt-key-popup-name prompt-key-popup-name--platform">Render3D Key</span>
        <div class="prompt-key-popup-model-wrap prompt-key-popup-platform-wrap">
          <select class="prompt-key-popup-model-select prompt-key-popup-provider-select" data-action="render3d-provider" title="OpenAI, Anthropic, or Kimi">
            ${render3dChoices.map((c) => {
        const selected = String(c.id) === String(current.id) ? " selected" : "";
        return `<option value="${render3dChoiceValue(c)}"${selected}>${c.label}</option>`;
      }).join("")}
          </select>
          <select class="prompt-key-popup-model-select prompt-key-popup-platform-model"
            data-action="change-model"
            data-key-id="${current.id}"
            data-source="platform"
            title="Model for this Render3D key">
            ${buildModelOptionsHTML(
        current.provider,
        wiringPicker && current.provider === "openai" ? wiringSelected : (current.model || ""),
        null,
        { includeGpt55 },
      )}
          </select>
          ${reasoningSelect(current.provider, wiringPicker && current.provider === "openai" ? wiringSelected : (current.model || ""))}
        </div>
      </div>`;
    }
    if (personalKeys.length) {
      html += `<div class="prompt-key-popup-section">Your keys</div>`;
      html += personalKeys.map((k) => keyRow(k, "personal")).join("");
    }
    if (teamKeys.length) {
      html += `<div class="prompt-key-popup-section">Shared keys</div>`;
      html += teamKeys.map((k) => keyRow(k, "team")).join("");
    }
  }

  popup.innerHTML = html;
}

function positionPromptKeyPopup() {
  const anchor = promptKeyPopupAnchor || document.getElementById("prompt-key-picker-btn");
  const popup = document.getElementById("prompt-key-popup");
  if (!anchor || !popup) return;
  const rect = anchor.getBoundingClientRect();
  const popupW = Math.min(400, window.innerWidth - 16);
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const gap = 6;
  const edge = 8;

  let left = rect.right - popupW;
  if (left < edge) left = edge;
  if (left + popupW > vw - edge) left = Math.max(edge, vw - popupW - edge);

  // Prefer opening upward when the pill sits near the bottom (Wiring / debugger).
  const spaceBelow = vh - rect.bottom - gap - edge;
  const spaceAbove = rect.top - gap - edge;
  const preferAbove = spaceBelow < 280 && spaceAbove > spaceBelow;
  const available = Math.max(160, preferAbove ? spaceAbove : spaceBelow);
  const maxH = Math.min(520, available);
  popup.style.maxHeight = `${maxH}px`;

  // Measure after maxHeight is applied so flip math uses the real height.
  popup.style.visibility = "hidden";
  popup.style.display = "flex";
  const popupH = Math.min(popup.scrollHeight || maxH, maxH);
  popup.style.visibility = "";

  let top;
  if (preferAbove) {
    top = Math.max(edge, rect.top - gap - popupH);
  } else {
    top = rect.bottom + gap;
    if (top + popupH > vh - edge) {
      top = Math.max(edge, vh - edge - popupH);
    }
  }

  popup.style.top = `${Math.round(top)}px`;
  popup.style.left = `${Math.round(left)}px`;
  popup.style.width = `${popupW}px`;
}

function openPromptKeyPopup(anchor) {
  const popup = document.getElementById("prompt-key-popup");
  if (!popup) return;
  const pinned = getPinnedPromptKey(aiStatus);
  if (pinned && !getSelectedPromptAiKey()) selectPromptAiKeyValue(pinned);
  promptKeyPopupAnchor = anchor || document.getElementById("prompt-key-picker-btn");
  promptKeyPopupOpen = true;
  renderPromptKeyPopup(aiStatus);
  popup.classList.remove("hidden");
  promptKeyPopupAnchor?.setAttribute("aria-expanded", "true");
  // Double-rAF so layout has the real popup height before flip math.
  requestAnimationFrame(() => {
    positionPromptKeyPopup();
    requestAnimationFrame(() => positionPromptKeyPopup());
  });
  void import("../components/model-pick-recommend.js?v=20260802-dont-show").then((mod) => {
    mod.bindModelPickRecommend?.({
      getUserId: () => currentUser?.id || null,
    });
    mod.maybeShowModelPickRecommend?.({
      getUserId: () => currentUser?.id || null,
    });
  });
}

function closePromptKeyPopup() {
  const popup = document.getElementById("prompt-key-popup");
  if (!popup) return;
  promptKeyPopupOpen = false;
  promptKeyPopupAnchor?.setAttribute("aria-expanded", "false");
  const allPills = document.querySelectorAll("#prompt-key-picker-btn, #imagine-key-picker-btn, #wiring-key-picker-btn, #wdbg-key-picker-btn, [data-vtl-gear], [data-vtl-key-pill]");
  allPills.forEach((b) => b.setAttribute("aria-expanded", "false"));
  popup.classList.add("hidden");
  promptKeyPopupAnchor = null;
}

function initPromptKeyPopup() {
  const popup = document.getElementById("prompt-key-popup");
  if (!popup) return;

  // Attach to both design-prompt pill and wiring-prompt pill
  const pillIds = ["prompt-key-picker-btn", "imagine-key-picker-btn", "wiring-key-picker-btn", "wdbg-key-picker-btn"];
  for (const id of pillIds) {
    const btn = document.getElementById(id);
    if (!btn) continue;
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      if (promptKeyPopupOpen && promptKeyPopupAnchor === btn) {
        closePromptKeyPopup();
        return;
      }
      openPromptKeyPopup(btn);
    });
  }

  // Close on outside click (not on any pill button)
  document.addEventListener("click", (e) => {
    if (!promptKeyPopupOpen) return;
    if (popup.contains(e.target)) return;
    if (pillIds.some((id) => document.getElementById(id)?.contains(e.target))) return;
    if (e.target.closest?.("[data-vtl-gear], [data-vtl-key-pill]")) return;
    closePromptKeyPopup();
  });

  // Close on Escape
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && promptKeyPopupOpen) closePromptKeyPopup();
  });

  // Reposition on resize/scroll
  window.addEventListener("resize", () => { if (promptKeyPopupOpen) positionPromptKeyPopup(); });

  // Delegate clicks/changes in popup
  popup.addEventListener("click", async (e) => {
    const pin = e.target.closest("[data-action='pin-chatgpt-default']");
    if (pin) {
      e.preventDefault();
      e.stopPropagation();
      pin.disabled = true;
      const value = getPinnedPromptKey() === "chatgpt:subscription" ? "" : "chatgpt:subscription";
      try {
        const result = await api("/api/user/ai-key/pinned-default", { method: "PUT", body: JSON.stringify({ value }) });
        aiStatus = { ...aiStatus, pinned_prompt_key: result.pinned_prompt_key };
        renderPromptAiKeySelect(aiStatus, { preserveSelection: false });
        renderPromptKeyPopup(aiStatus);
        setEditStatus("ok", value ? "ChatGPT subscription pinned as your account default." : "Account default unpinned.");
      } catch (err) {
        pin.disabled = false;
        setEditStatus("error", err?.message || "Could not save the default. Try again.");
      }
      return;
    }
    const manageBtn = e.target.closest("[data-action='open-key-manager']");
    if (manageBtn) {
      closePromptKeyPopup();
      document.getElementById("btn-ai-key-menu")?.click();
      return;
    }

    const row = e.target.closest("[data-action='select-key']");
    if (row && !e.target.closest("select")) {
      const source = row.dataset.source;
      const keyId = row.dataset.keyId;
      const selectedValue = promptKeyOptionValue(source, keyId);
      const sel = document.getElementById("prompt-ai-key-select");
      if (sel) {
        sel.value = selectedValue;
        storePromptAiKeyValue(sel.value);
      }
      syncPromptKeyPill(aiStatus);
      closePromptKeyPopup();
      // Make the chosen key the exclusive active default so generate
      // doesn't fall back to another opted-in OpenAI shared key.
      if (source === "platform") {
        try {
          const platformKey = getPlatformPromptKeys(aiStatus).find((key) => key.id === keyId);
          const provider = normalizePlatformProviderId(platformKey?.provider || keyId);
          const rowModel = String(platformKey?.model || "").trim();
          const modelCompatible = (
            (provider === "anthropic" && rowModel && !/^(gpt|o1|o3|chatgpt|kimi)/i.test(rowModel))
            || (provider === "kimi" && /^kimi/i.test(rowModel))
            || (provider === "openai" && /^(gpt|o1|o3|chatgpt)/i.test(rowModel))
          );
          const platformModel = modelCompatible
            ? rowModel
            : (defaultPlatformModelForProvider(provider, aiStatus)
              || PROMPT_KEY_MODEL_OPTIONS[provider]?.[0]?.value
              || null);
          const data = await api("/api/user/ai-credits", {
            method: "PATCH",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              use_platform_key: true,
              platform_provider: provider,
              platform_model: platformModel || null,
            }),
          });
          const updatedAi = { ...(data.ai || aiStatus || {}), credits: data.credits || data.ai?.credits };
          aiKeyUi?.render(updatedAi);
          renderAIStatus(updatedAi);
          selectPromptAiKeyValue(selectedValue);
        } catch (err) {
          console.error("Could not activate Render3D key:", err);
        }
      } else if (source === "personal") {
        try {
          const data = await api(`/api/user/ai-keys/${keyId}/activate`, { method: "PUT" });
          // Stop routing fallbacks through Render3D Claude/OpenAI when a personal key is chosen.
          let credits = data.ai?.credits || aiStatus?.credits;
          try {
            const creditData = await api("/api/user/ai-credits", {
              method: "PATCH",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ use_platform_key: false }),
            });
            credits = creditData.credits || creditData.ai?.credits || credits;
          } catch (_) { /* non-fatal */ }
          // Opt out of opted-in team keys so server-side default matches the personal pick.
          const teamKeys = (aiStatus?.team_keys || []).filter((tk) => tk.use_key && tk.team_id);
          for (const tk of teamKeys) {
            try {
              await api(`/api/teams/${tk.team_id}/ai-keys/${tk.id}/toggle`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ use_key: false }),
              });
            } catch (_) { /* non-fatal */ }
          }
          const refreshed = teamKeys.length
            ? await api("/api/user/ai-keys").catch(() => null)
            : null;
          const updatedAi = refreshed
            ? { ...(refreshed.ai || {}), keys: refreshed.keys || refreshed.ai?.keys || [], credits }
            : { ...(data.ai || data || aiStatus || {}), credits };
          aiKeyUi?.render(updatedAi);
          renderAIStatus(updatedAi);
          selectPromptAiKeyValue(selectedValue);
        } catch (err) {
          console.error("Could not activate personal key:", err);
        }
      } else if (source === "team") {
        const teamKey = (aiStatus?.team_keys || []).find((key) => key.id === keyId);
        if (teamKey?.team_id) {
          try {
            const data = await api(`/api/teams/${teamKey.team_id}/ai-keys/${keyId}/toggle`, {
              method: "PUT",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                use_key: true,
                model: teamKeyDisplayModel(teamKey) || teamKey.model || undefined,
              }),
            });
            const updatedAi = { ...(data.ai || {}), keys: data.ai?.keys || [] };
            aiKeyUi?.render(updatedAi);
            renderAIStatus(updatedAi);
            const hidden = document.getElementById("prompt-ai-key-select");
            if (hidden && [...hidden.options].some((opt) => opt.value === selectedValue)) {
              hidden.value = selectedValue;
              storePromptAiKeyValue(selectedValue);
              syncPromptKeyPill(aiStatus);
            }
          } catch (err) {
            console.error("Could not activate shared key:", err);
          }
        }
      }
    }
  });

  popup.addEventListener("change", async (e) => {
    const reasoningSel = e.target.closest("[data-action='change-reasoning']");
    if (reasoningSel) {
      e.stopPropagation();
      storeModelReasoning(reasoningSel.dataset.provider, reasoningSel.dataset.model, reasoningSel.value);
      renderPromptKeyPopup(aiStatus);
      return;
    }
    const providerSel = e.target.closest("[data-action='render3d-provider'], [data-action='platform-provider']");
    if (providerSel) {
      e.stopPropagation();
      const selectedValue = String(providerSel.value || "");
      const parsed = parsePromptKeyOptionValue(selectedValue);
      if (!parsed) return;
      const choice = getRender3dKeyChoices(aiStatus).find((c) => String(c.id) === String(parsed.keyId))
        || {
        id: normalizePlatformProviderId(parsed.keyId),
        provider: normalizePlatformProviderId(parsed.keyId),
        model: "",
      };
      const resolvedProvider = normalizePlatformProviderId(choice.provider || choice.id || parsed.keyId);
      const defaultModel = defaultPlatformModelForProvider(resolvedProvider, aiStatus)
        || choice.model
        || PROMPT_KEY_MODEL_OPTIONS[resolvedProvider]?.[0]?.value
        || "";
      const platformValue = promptKeyOptionValue("platform", choice.id || resolvedProvider);
      const hiddenSelect = document.getElementById("prompt-ai-key-select");
      if (hiddenSelect) {
        if (![...hiddenSelect.options].some((opt) => opt.value === platformValue)) {
          const opt = document.createElement("option");
          opt.value = platformValue;
          opt.textContent = platformKeyDisplayName(resolvedProvider);
          hiddenSelect.appendChild(opt);
        }
        hiddenSelect.value = platformValue;
        storePromptAiKeyValue(platformValue);
      }
      try {
        const data = await api("/api/user/ai-credits", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            use_platform_key: true,
            platform_provider: resolvedProvider,
            platform_model: defaultModel || null,
          }),
        });
        const updatedAi = { ...(data.ai || aiStatus || {}), credits: data.credits || data.ai?.credits };
        aiKeyUi?.render(updatedAi);
        renderAIStatus(updatedAi);
        selectPromptAiKeyValue(platformValue);
        renderPromptKeyPopup(aiStatus);
      } catch (err) {
        console.error("Could not switch Render3D provider:", err);
      }
      return;
    }

    const modelSel = e.target.closest("[data-action='change-model']");
    if (!modelSel) return;
    e.stopPropagation();
    const keyId = modelSel.dataset.keyId;
    const source = modelSel.dataset.source;
    let newModel = modelSel.value;
    const wiringPicker = promptKeyPopupIsWiring();
    if (wiringPicker) {
      storeWiringPreferredModel(newModel);
      const selectedValue = promptKeyOptionValue(source, keyId);
      const hiddenSelect = document.getElementById("prompt-ai-key-select");
      if (hiddenSelect) {
        hiddenSelect.value = selectedValue;
        storePromptAiKeyValue(selectedValue);
      }
      syncPromptKeyPill(aiStatus);
      renderPromptKeyPopup(aiStatus);
      return;
    }
    if (source === "chatgpt") {
      storeChatgptCodexModel(newModel);
      const selectedValue = promptKeyOptionValue("chatgpt", "subscription");
      const hiddenSelect = document.getElementById("prompt-ai-key-select");
      if (hiddenSelect) {
        hiddenSelect.value = selectedValue;
        storePromptAiKeyValue(selectedValue);
      }
      syncPromptKeyPill(aiStatus);
      renderPromptKeyPopup(aiStatus);
      return;
    }
    if (source === "cursor") {
      storeCursorSubscriptionModel(newModel);
      const selectedValue = promptKeyOptionValue("cursor", "subscription");
      const hiddenSelect = document.getElementById("prompt-ai-key-select");
      if (hiddenSelect) {
        hiddenSelect.value = selectedValue;
        storePromptAiKeyValue(selectedValue);
      }
      syncPromptKeyPill(aiStatus);
      renderPromptKeyPopup(aiStatus);
      return;
    }
    if (source === "claude") {
      storeClaudeSubscriptionModel(newModel);
      const selectedValue = promptKeyOptionValue("claude", "subscription");
      const hiddenSelect = document.getElementById("prompt-ai-key-select");
      if (hiddenSelect) {
        hiddenSelect.value = selectedValue;
        storePromptAiKeyValue(selectedValue);
      }
      syncPromptKeyPill(aiStatus);
      renderPromptKeyPopup(aiStatus);
      return;
    }
    if (isRetiredOpenAiPromptModel(newModel)) {
      newModel = DEFAULT_AI_MODEL;
      modelSel.value = newModel;
    }
    const selectedValue = promptKeyOptionValue(source, keyId);
    const hiddenSelect = document.getElementById("prompt-ai-key-select");
    if (hiddenSelect) {
      hiddenSelect.value = selectedValue;
      storePromptAiKeyValue(selectedValue);
    }
    try {
      const teamKey = source === "team"
        ? (aiStatus?.team_keys || []).find((key) => key.id === keyId)
        : null;
      if (source === "team" && !teamKey?.team_id) {
        throw new Error("Could not find the shared key team for this model change.");
      }
      let data;
      if (source === "platform") {
        data = await api("/api/user/ai-credits", {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            use_platform_key: true,
            platform_provider: normalizePlatformProviderId(keyId),
            platform_model: newModel || null,
          }),
        });
        data = { ai: { ...(data.ai || aiStatus || {}), credits: data.credits || data.ai?.credits } };
      } else if (source === "team") {
        data = await api(`/api/teams/${teamKey?.team_id}/ai-keys/${keyId}/toggle`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ use_key: true, model: newModel }),
        });
      } else {
        data = await api(`/api/user/ai-keys/${keyId}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ model: newModel }),
        });
      }
      const updatedAi = { ...(data.ai || {}), keys: data.ai?.keys || [] };
      aiKeyUi?.render(updatedAi);
      renderAIStatus(updatedAi);
      const sel = document.getElementById("prompt-ai-key-select");
      if (sel && [...sel.options].some((opt) => opt.value === selectedValue)) {
        sel.value = selectedValue;
        storePromptAiKeyValue(selectedValue);
        syncPromptKeyPill(aiStatus);
      }
      renderPromptKeyPopup(aiStatus);
    } catch (err) {
      console.error("Could not update model:", err);
      const status = document.getElementById("prompt-status");
      if (status) {
        status.className = "status error";
        status.textContent = err.message || "Could not update selected AI model.";
      }
    }
  });
}

function renderAIStatus(status) {
  aiStatus = status || null;
  renderPromptAiKeySelect(aiStatus);
  reconcileCodexToggleWithKeys();
  const el = document.getElementById("prompt-status");
  if (!el || !aiStatus) return;
  // If weekly free-trial spots are exhausted, never leave the $10 popup visible.
  if (aiStatus?.credits?.trial?.blocked_weekly_cap || aiStatus?.credits?.trial?.waitlisted) {
    document.getElementById("trial-credits-modal")?.classList.add("hidden");
  }
  if (aiStatus.ai_ready) {
    el.className = "status";
    el.textContent = "";
    renderProjectCostThumb(latestPromptHistoryEntries || [], allProjects.find((p) => p.id === projectId)?.usage_summary || null);
    maybeOfferTrialCreditsPopup();
    return;
  }
  if (chatgptSubscriptionReady()) {
    const remaining = chatgptTrialRemaining();
    const trialNote = remaining == null || aiStatus?.chatgpt?.source !== "trial"
      ? ""
      : remaining === 1
        ? " 1 trial render left."
        : ` ${remaining} trial renders left.`;
    el.className = "status";
    el.textContent = `${chatgptPickerLabel()} — pick GPT-5.6 Sol, Terra, Luna, Astra, or Astra Pro.${trialNote}`;
    renderProjectCostThumb(latestPromptHistoryEntries || [], allProjects.find((p) => p.id === projectId)?.usage_summary || null);
    maybeOfferTrialCreditsPopup();
    return;
  }
  if (cursorSubscriptionReady()) {
    el.className = "status";
    el.textContent = `${cursorPickerLabel()} — pick Auto, Grok 4.6, Composer, or Opus for CAD.`;
    renderProjectCostThumb(latestPromptHistoryEntries || [], allProjects.find((p) => p.id === projectId)?.usage_summary || null);
    maybeOfferTrialCreditsPopup();
    return;
  }
  if (claudeSubscriptionReady()) {
    el.className = "status";
    el.textContent = `${claudePickerLabel()} — CAD 2.0, Architect, VibeCAD, and Mesh run on that Claude plan.`;
    renderProjectCostThumb(latestPromptHistoryEntries || [], allProjects.find((p) => p.id === projectId)?.usage_summary || null);
    maybeOfferTrialCreditsPopup();
    return;
  }
  el.className = "status error";
  el.textContent = "Add your own AI key or buy shared-key credits before prompting.";
  renderProjectCostThumb(latestPromptHistoryEntries || [], allProjects.find((p) => p.id === projectId)?.usage_summary || null);
  maybeOfferTrialCreditsPopup();
  maybeOfferSharedKeyCredits();
}

function closeTrialCreditsPopup() {
  document.getElementById("trial-credits-modal")?.classList.add("hidden");
}

function trialCreditsPopupSeenKey(user = currentUser) {
  return user?.id ? `render3d:trialCreditsPopupSeen:v1:${user.id}` : "render3d:trialCreditsPopupSeen:v1";
}

function markTrialCreditsPopupSeenLocal() {
  try {
    localStorage.setItem(trialCreditsPopupSeenKey(), "1");
  } catch (_) { }
  if (aiStatus?.credits?.trial) {
    aiStatus = {
      ...aiStatus,
      credits: {
        ...aiStatus.credits,
        trial: {
          ...aiStatus.credits.trial,
          popup_seen: true,
          show_popup: false,
        },
      },
    };
  }
}

async function ackTrialCreditsPopup() {
  closeTrialCreditsPopup();
  markTrialCreditsPopupSeenLocal();
  try {
    const data = await api("/api/user/ai-credits/trial-ack", { method: "POST" });
    if (data?.ai) {
      // Keep show_popup false even if a stale payload races in.
      if (data.ai.credits?.trial) {
        data.ai.credits.trial.show_popup = false;
        data.ai.credits.trial.popup_seen = true;
      }
      renderAIStatus(data.ai);
    } else if (data?.credits && aiStatus) {
      aiStatus = {
        ...aiStatus,
        credits: {
          ...data.credits,
          trial: {
            ...(data.credits.trial || {}),
            show_popup: false,
            popup_seen: true,
          },
        },
      };
    }
  } catch (err) {
    console.warn("Could not acknowledge trial credits popup:", err);
  }
}

function isTrialCreditsUnavailable() {
  const credits = aiStatus?.credits || {};
  const trial = credits.trial || {};
  const blocked = !!(
    trial.blocked_weekly_cap
    || trial.waitlisted
    || trial.blocked_ip
    || trial.reclaimed_at
  );
  if (blocked) return true;
  if (trial.kind === "chatgpt_renders") {
    return !(Number(trial.renders_remaining) > 0);
  }
  return !(Number(credits.balance_cents) > 0);
}

function isVrHeadsetBrowserUi() {
  try {
    if (document.documentElement.classList.contains("vr-headset-browser")) return true;
    if (document.body.classList.contains("vr-headset-browser")) return true;
  } catch {
    /* ignore */
  }
  return /OculusBrowser|MetaBrowser|Horizon|Quest|XRBrowser|Mobile VR|Wolvic|Helio|Snapchat|Spectacles|PicoBrowser/i.test(
    navigator.userAgent || "",
  );
}

function shouldShowTrialCreditsPopup() {
  if (isVrHeadsetBrowserUi()) return false;
  if (!currentUser || !aiStatus) return false;
  if (window.__render3dShowMeFromQuery) return false;
  if (new URLSearchParams(window.location.search).has("showMe")) return false;
  try {
    if (localStorage.getItem(trialCreditsPopupSeenKey()) === "1") return false;
  } catch (_) { }
  const credits = aiStatus?.credits || {};
  const trial = credits.trial || {};
  // Never tease free credits when the weekly allotment is out, waitlisted,
  // reclaimed, or the balance is already $0.
  if (isTrialCreditsUnavailable()) {
    document.getElementById("trial-credits-modal")?.classList.add("hidden");
    return false;
  }
  if (!(trial.on_free_trial || trial.active || trial.granted)) return false;
  return !!trial.show_popup;
}

let trialCreditsPopupTimer = null;
let trialCreditsPopupOffered = false;

function maybeOfferTrialCreditsPopup() {
  if (trialCreditsPopupOffered) return;
  if (!shouldShowTrialCreditsPopup()) return;
  if (trialCreditsPopupTimer) return;
  const wait = typeof window.__whenStudioReady === "function"
    ? window.__whenStudioReady
    : (cb) => cb();
  wait(() => {
    if (trialCreditsPopupOffered || trialCreditsPopupTimer) return;
    if (!shouldShowTrialCreditsPopup()) return;
    const setupOpen = !document.getElementById("ai-setup-intro-modal")?.classList.contains("hidden");
    if (setupOpen) closeAISetupIntro({ remember: false });
    trialCreditsPopupTimer = window.setTimeout(() => {
      trialCreditsPopupTimer = null;
      if (trialCreditsPopupOffered || !shouldShowTrialCreditsPopup()) return;
      const modal = document.getElementById("trial-credits-modal");
      if (!modal) return;
      trialCreditsPopupOffered = true;
      markTrialCreditsPopupSeenLocal();
      void api("/api/user/ai-credits/trial-ack", { method: "POST" }).catch(() => { });
      modal.classList.remove("hidden");
      modal.querySelector("[data-trial-credits-action='start']")?.focus();
    }, 400);
  });
}

function initTrialCreditsModal() {
  const modal = document.getElementById("trial-credits-modal");
  if (!modal) return;
  modal.querySelectorAll("[data-trial-credits-close]").forEach((el) => {
    el.addEventListener("click", () => {
      void ackTrialCreditsPopup();
    });
  });
  modal.addEventListener("click", (event) => {
    const actionEl = event.target.closest("[data-trial-credits-action]");
    if (!actionEl) return;
    const action = actionEl.dataset.trialCreditsAction;
    void ackTrialCreditsPopup().then(() => {
      if (action === "buy") {
        aiKeyUi?.openRequired?.({
          message: "Add an API key or buy Studio credits after your trial renders.",
          openAdd: false,
        });
      }
    });
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !modal.classList.contains("hidden")) {
      event.preventDefault();
      void ackTrialCreditsPopup();
    }
  });
}

function aiSetupIntroKey(user = currentUser) {
  return user?.id ? `${LS_AI_SETUP_INTRO_DISMISSED}:${user.id}` : LS_AI_SETUP_INTRO_DISMISSED;
}

function aiSetupIntroOfferedKey(user = currentUser) {
  return user?.id ? `${SS_AI_SETUP_INTRO_OFFERED}:${user.id}` : SS_AI_SETUP_INTRO_OFFERED;
}

function closeAISetupIntro({ remember = true } = {}) {
  const modal = document.getElementById("ai-setup-intro-modal");
  modal?.classList.add("hidden");
  const dontShow = document.getElementById("ai-setup-dont-show");
  if (remember || dontShow?.checked) {
    try {
      localStorage.setItem(aiSetupIntroKey(), "1");
    } catch (_) { }
  }
}

function shouldShowAISetupIntro({ ignoreSessionOffer = false } = {}) {
  if (isVrHeadsetBrowserUi()) return false;
  if (!currentUser || !aiStatus || aiStatus.ai_ready) return;
  if (anyCliSubscriptionReady()) return false;
  if (window.__render3dShowMeFromQuery) return false;
  if (new URLSearchParams(window.location.search).has("showMe")) return false;
  try {
    if (localStorage.getItem(aiSetupIntroKey()) === "1") return false;
    if (!ignoreSessionOffer && sessionStorage.getItem(aiSetupIntroOfferedKey()) === "1") return false;
  } catch (_) { }
  return true;
}

let aiSetupIntroTimer = null;

function syncAISetupIntroCopyForTrialAvailability() {
  const modal = document.getElementById("ai-setup-intro-modal");
  if (!modal) return;
  const outForWeek = !!(aiStatus?.credits?.trial?.blocked_weekly_cap || aiStatus?.credits?.trial?.waitlisted);
  const copy = modal.querySelector(".ai-setup-copy p:not(.info-eyebrow)");
  const creditsBtn = modal.querySelector("[data-ai-setup-action='credits']");
  const stepCredits = Array.from(modal.querySelectorAll(".ai-setup-step-grid span")).find((el) =>
    /load credits/i.test(el.textContent || ""),
  );
  if (outForWeek) {
    if (copy) {
      copy.textContent =
        "Your account is ready, but AI generation needs one more step: add your OpenAI or Claude API key, or open Getting Started to learn the workflow first.";
    }
    creditsBtn?.classList.add("hidden");
    if (stepCredits) stepCredits.textContent = "2. Buy credits anytime";
  } else {
    if (copy) {
      copy.textContent =
        "Your account is ready, but AI generation needs one more step: add your OpenAI or Claude API key, load shared credits for Render Studio’s platform key, or open Getting Started to learn the workflow first.";
    }
    creditsBtn?.classList.remove("hidden");
    if (stepCredits) stepCredits.textContent = "2. Or load credits";
  }
}

function maybeOfferSharedKeyCredits() {
  if (shouldShowTrialCreditsPopup()) return;
  if (aiStatus?.credits?.trial?.blocked_weekly_cap || aiStatus?.credits?.trial?.waitlisted) {
    document.getElementById("trial-credits-modal")?.classList.add("hidden");
  }
  if (!shouldShowAISetupIntro()) return;
  if (aiSetupIntroTimer) return;
  const wait = typeof window.__whenStudioReady === "function"
    ? window.__whenStudioReady
    : (cb) => cb();
  wait(() => {
    if (shouldShowTrialCreditsPopup()) return;
    if (!shouldShowAISetupIntro()) return;
    if (aiSetupIntroTimer) return;
    try {
      sessionStorage.setItem(aiSetupIntroOfferedKey(), "1");
    } catch (_) { }
    aiSetupIntroTimer = window.setTimeout(() => {
      aiSetupIntroTimer = null;
      if (shouldShowTrialCreditsPopup()) return;
      if (!shouldShowAISetupIntro({ ignoreSessionOffer: true })) return;
      const modal = document.getElementById("ai-setup-intro-modal");
      if (!modal) return;
      syncAISetupIntroCopyForTrialAvailability();
      modal.classList.remove("hidden");
      modal.querySelector("[data-ai-setup-action='key']")?.focus();
    }, 500);
  });
}

function initAISetupIntroModal() {
  const modal = document.getElementById("ai-setup-intro-modal");
  if (!modal) return;
  modal.querySelectorAll("[data-ai-setup-close]").forEach((el) => {
    el.addEventListener("click", () => closeAISetupIntro({ remember: true }));
  });
  modal.addEventListener("click", (event) => {
    const actionEl = event.target.closest("[data-ai-setup-action]");
    if (!actionEl) return;
    const action = actionEl.dataset.aiSetupAction;
    closeAISetupIntro({ remember: action !== "tutorial" });
    if (action === "key") {
      aiKeyUi?.openRequired?.({
        message: "Add your OpenAI or Claude API key to start generating CAD.",
        openAdd: true,
      });
      return;
    }
    if (action === "credits") {
      aiKeyUi?.openRequired?.({
        message: "Load shared-key credits to use Render3D's platform AI key without pasting your own key.",
        openAdd: false,
      });
      return;
    }
    if (action === "tutorial") {
      void import("../site/show-me-tour.js?v=20260908-agent-tabs-logo-ko1-20260914-teleop2-settings-redesign2&vrboard=20260915-spatial-draw4").then((mod) => {
        mod.startShowMe?.("prompt-onboarding", { onDocsPage: false });
      });
    }
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !modal.classList.contains("hidden")) {
      closeAISetupIntro({ remember: true });
    }
  });
}

function saveLastProjectId(id) {
  try {
    localStorage.setItem(LS_LAST_PROJECT, id);
  } catch (_) { }
  captureSessionSnapshot();
}

function readLastProjectId() {
  try {
    return String(localStorage.getItem(LS_LAST_PROJECT) || "").trim();
  } catch {
    return "";
  }
}

function firstProjectPromptOnboardingKey(user = currentUser) {
  return user?.id ? `${LS_FIRST_PROJECT_PROMPT_ONBOARDING}:${user.id}` : LS_FIRST_PROJECT_PROMPT_ONBOARDING;
}

function googleNewUserWalkthroughKey(user = currentUser) {
  return user?.id ? `${LS_GOOGLE_NEW_USER_WALKTHROUGH}:${user.id}` : LS_GOOGLE_NEW_USER_WALKTHROUGH;
}

function maybeStartFirstProjectPromptOnboarding() {
  if (isVrHeadsetBrowserUi()) return;
  if (!currentUser || !projectId) return;
  if (pendingGoogleNewUserWalkthrough) return;
  if (window.__render3dShowMeFromQuery) return;
  if (new URLSearchParams(window.location.search).has("showMe")) return;
  if ((allProjects || []).length > 1) return;
  const key = firstProjectPromptOnboardingKey();
  try {
    if (localStorage.getItem(key) === "1") return;
    localStorage.setItem(key, "1");
  } catch {
    return;
  }
  window.setTimeout(() => {
    void import("../site/show-me-tour.js?v=20260908-agent-tabs-logo-ko1-20260914-teleop2-settings-redesign2&vrboard=20260915-spatial-draw4").then((mod) => {
      mod.startShowMe?.("prompt-onboarding", { onDocsPage: false });
    });
  }, 1200);
}

function maybeStartGoogleNewUserWalkthrough(data = {}) {
  if (!currentUser || data?.social_new !== true || String(data?.social_provider || "").toLowerCase() !== "google") return;
  const key = googleNewUserWalkthroughKey();
  try {
    if (localStorage.getItem(key) === "1") return;
    localStorage.setItem(key, "1");
    localStorage.setItem(firstProjectPromptOnboardingKey(), "1");
  } catch {
    return;
  }
  pendingGoogleNewUserWalkthrough = false;
}

function captureSessionSnapshot() {
  if (!projectId) return;
  saveSessionSnapshot({
    projectId,
    selectedFile: selectedFile || null,
    workspaceId: document.getElementById("team-select")?.value || readSavedWorkspaceId() || null,
  });
}

function getSelectedWorkspaceId() {
  const value = document.getElementById("team-select")?.value;
  if (value === "__all__") return null;
  return value || allTeams[0]?.id || null;
}

function hiddenWorkspacesStorageKey() {
  const uid = currentUser?.id || "anon";
  return `${LS_HIDDEN_WORKSPACES}:${uid}`;
}

function readHiddenWorkspaceIdsFromStorage() {
  try {
    const scoped = JSON.parse(localStorage.getItem(hiddenWorkspacesStorageKey()) || "null");
    if (Array.isArray(scoped)) return new Set(scoped.map((id) => String(id)));
    const raw = JSON.parse(localStorage.getItem(LS_HIDDEN_WORKSPACES) || "[]");
    return new Set((Array.isArray(raw) ? raw : []).map((id) => String(id)));
  } catch {
    return new Set();
  }
}

function writeHiddenWorkspaceIds(hidden) {
  try {
    localStorage.setItem(hiddenWorkspacesStorageKey(), JSON.stringify([...hidden]));
  } catch (_) { }
}

function recentWorkspacesStorageKey() {
  return `${LS_RECENT_WORKSPACES}:${currentUser?.id || "anon"}`;
}

function readRecentWorkspaceIds() {
  try {
    const raw = JSON.parse(localStorage.getItem(recentWorkspacesStorageKey()) || "[]");
    return (Array.isArray(raw) ? raw : []).map((id) => String(id));
  } catch {
    return [];
  }
}

function touchRecentWorkspace(teamId) {
  const id = String(teamId || "").trim();
  if (!id) return;
  const next = [id, ...readRecentWorkspaceIds().filter((row) => row !== id)].slice(0, 24);
  try {
    localStorage.setItem(recentWorkspacesStorageKey(), JSON.stringify(next));
  } catch (_) { }
  try { workspaceBrowser?.render?.(); } catch (_) { }
}

function explorerPrefsStorageKey() {
  return `${LS_EXPLORER_PREFS}:${currentUser?.id || "anon"}`;
}

function readExplorerPrefs() {
  try {
    const raw = JSON.parse(localStorage.getItem(explorerPrefsStorageKey()) || "{}");
    return raw && typeof raw === "object" ? raw : {};
  } catch {
    return {};
  }
}

function writeExplorerPrefs(patch) {
  const next = { ...readExplorerPrefs(), ...patch };
  try {
    localStorage.setItem(explorerPrefsStorageKey(), JSON.stringify(next));
  } catch (_) { }
  return next;
}

let personalPinIds = [];

function currentPersonalPinIds() {
  return normalizePersonalPinIds(personalPinIds);
}

function persistPersonalPins(ids, { sync = true } = {}) {
  personalPinIds = normalizePersonalPinIds(ids);
  savePersonalPinIds(currentUser?.id, personalPinIds);
  writeExplorerPrefs({ pinnedIds: personalPinIds });
  try { workspaceBrowser?.render?.(); } catch (_) { }
  try { viewportSearch?.refresh?.(); } catch (_) { }
  if (sync && currentUser?.id) {
    void api("/api/users/me/project-pins", {
      method: "PUT",
      body: JSON.stringify({ pinned_ids: personalPinIds }),
    }).catch((err) => {
      setEditStatus("error", err?.message || "Could not save pinned projects.");
    });
  }
  return personalPinIds;
}

function togglePersonalPin(project) {
  if (!canPinPersonalProject(project)) return { ok: false };
  const result = togglePersonalProjectPin(personalPinIds, project?.id);
  if (!result.ok) {
    setEditStatus("error", result.error || "Unpin one project first — you can pin up to 5.");
    return result;
  }
  persistPersonalPins(result.pinnedIds);
  const name = project?.name || project?.id || "Project";
  setEditStatus("ok", result.pinned ? `Pinned “${name}” to Projects.` : `Unpinned “${name}” from Projects.`);
  return result;
}

async function hydratePersonalPins() {
  personalPinIds = loadPersonalPinIds(currentUser?.id);
  const fromPrefs = normalizePersonalPinIds(readExplorerPrefs()?.pinnedIds);
  if (!personalPinIds.length && fromPrefs.length) personalPinIds = fromPrefs;
  if (!currentUser?.id) {
    try { workspaceBrowser?.render?.(); } catch (_) { }
    return personalPinIds;
  }
  try {
    const data = await api("/api/users/me/project-pins");
    const server = normalizePersonalPinIds(data?.pinned_ids);
    if (Array.isArray(data?.pinned_ids)) {
      if (!server.length && personalPinIds.length) {
        persistPersonalPins(personalPinIds);
      } else {
        personalPinIds = server;
        savePersonalPinIds(currentUser.id, personalPinIds);
        writeExplorerPrefs({ pinnedIds: personalPinIds });
      }
    }
  } catch (_) { }
  try { workspaceBrowser?.render?.(); } catch (_) { }
  return personalPinIds;
}

function hiddenWorkspaceIds() {
  const hidden = readHiddenWorkspaceIdsFromStorage();
  for (const team of allTeams || []) {
    if (!team?.id) continue;
    const flag = team.explorer_visible;
    if (flag === false || flag === 0) hidden.add(String(team.id));
    else if (flag === true || flag === 1) hidden.delete(String(team.id));
  }
  return hidden;
}

function setWorkspaceVisible(teamId, visible) {
  if (!teamId) return;
  const id = String(teamId);
  const team = (allTeams || []).find((row) => String(row.id) === id);
  if (team) team.explorer_visible = !!visible;
  const hidden = readHiddenWorkspaceIdsFromStorage();
  if (visible) hidden.delete(id);
  else hidden.add(id);
  writeHiddenWorkspaceIds(hidden);
  try { workspaceBrowser?.render?.(); } catch (_) { }
  void api(`/api/teams/${encodeURIComponent(id)}/explorer-visible`, {
    method: "PATCH",
    body: JSON.stringify({ visible: !!visible }),
  }).catch((err) => {
    setEditStatus("error", err?.message || "Could not update workspace visibility.");
  });
}

function getFolderTeamId() {
  const selected = getSelectedWorkspaceId();
  if (selected && (allTeams || []).some((team) => team.id === selected)) return selected;
  return personalWorkspaceId() || allTeams[0]?.id || null;
}

function userFirstName(user = currentUser) {
  const raw = String(user?.display_name || user?.email?.split("@")[0] || "My").trim();
  return raw.split(/\s+/)[0] || "My";
}

function personalWorkspaceId(teams = allTeams) {
  const mine = teams
    .filter((team) => team.role === "owner" && (!currentUser?.id || team.created_by === currentUser.id))
    .sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
  const looksPersonal = (team) => {
    const name = String(team?.name || "").trim().toLowerCase();
    return (
      /'s\s+workspace$/i.test(name)
      || /’s\s+workspace$/i.test(name)
      || name === "my workspace"
      || name === "personal workspace"
      || name === "personal"
      || name === "projects"
      || name.includes("@")
    );
  };
  // Prefer a true solo personal workspace. Multi-member collab teams (Render3D)
  // must not steal the personal slot or they disappear from shared-workspace UI.
  const solo = mine.filter((team) => workspaceMemberCount(team) <= 1);
  const named = solo.find(looksPersonal);
  if (named) return named.id;
  const hasCollab = teams.some((team) => workspaceMemberCount(team) > 1);
  // Leftover unnamed 1-member teams must not hide owned Render3D / Fusion projects.
  if (hasCollab) return null;
  return solo[0]?.id || null;
}

function isPersonalWorkspace(team) {
  if (!team?.id) return false;
  // Multi-member workspaces are always shared, even if owned by you.
  if (workspaceMemberCount(team) > 1) return false;
  const personalId = personalWorkspaceId();
  return !!personalId && team.id === personalId;
}

function isSharedWorkspace(team) {
  if (!team?.id) return false;
  if (workspaceMemberCount(team) > 1) return true;
  return !isPersonalWorkspace(team);
}

function workspaceMemberCount(team) {
  return Number(team?.member_count ?? team?.members_count ?? 1) || 1;
}

function personalWorkspaceLabel() {
  return `${userFirstName()}'s Workspace`;
}

function personalRootFolderLabel() {
  return `${userFirstName()}'s files`;
}

function workspaceExplorerLabel(team) {
  if (!team) return "Workspace";
  return isPersonalWorkspace(team) ? personalWorkspaceLabel() : (team.name || "Shared workspace");
}

function getWorkspaceMeta(teamId = getSelectedWorkspaceId()) {
  const team = allTeams.find((t) => t.id === teamId) || null;
  const personal = !!team && isPersonalWorkspace(team);
  const shared = !!team && isSharedWorkspace(team);
  return {
    id: team?.id || null,
    name: team?.name || "",
    label: workspaceExplorerLabel(team),
    rootLabel: personal ? personalRootFolderLabel() : workspaceExplorerLabel(team),
    personal,
    shared,
    memberCount: workspaceMemberCount(team),
  };
}

function readNewProjectWorkspaceDefault() {
  try {
    const value = localStorage.getItem(LS_NEW_PROJECT_WORKSPACE_DEFAULT) || "ask";
    return ["ask", "personal", "current"].includes(value) ? value : "ask";
  } catch (_) {
    return "ask";
  }
}

function writeNewProjectWorkspaceDefault(value) {
  const next = ["ask", "personal", "current"].includes(value) ? value : "ask";
  try {
    localStorage.setItem(LS_NEW_PROJECT_WORKSPACE_DEFAULT, next);
  } catch (_) { }
  return next;
}

function userWorkspaceStorageKey(user = currentUser) {
  return user?.id ? `${LS_LAST_WORKSPACE}:${user.id}` : LS_LAST_WORKSPACE;
}

function readSavedWorkspaceId() {
  try {
    const userScoped = localStorage.getItem(userWorkspaceStorageKey());
    if (userScoped) return userScoped;
    return localStorage.getItem(LS_LAST_WORKSPACE) || "";
  } catch (_) {
    return "";
  }
}

function hasUserScopedSavedWorkspace(id) {
  if (!id) return false;
  try {
    return localStorage.getItem(userWorkspaceStorageKey()) === id;
  } catch (_) {
    return false;
  }
}

function writeSavedWorkspaceId(id) {
  if (!id) return;
  try {
    localStorage.setItem(userWorkspaceStorageKey(), id);
    localStorage.setItem(LS_LAST_WORKSPACE, id);
  } catch (_) { }
}

function defaultWorkspaceIdForUser(teams = allTeams) {
  const personal = personalWorkspaceId(teams);
  return personal || teams[0]?.id || "";
}

function hasTrackedUsageSummary(summary) {
  if (!summary || typeof summary !== "object") return false;
  if (Number(summary.tracked_count) > 0) return true;
  if (Number(summary.cost_usd || 0) > 0) return true;
  if (Number(summary.openai_cost_usd || 0) > 0) return true;
  return usageTokenTotal(summary.usage) > 0;
}

function mergeLiveGenerationFields(next, prev) {
  if (!next || typeof next !== "object") return prev || next;
  if (!prev || typeof prev !== "object") return next;
  const merged = { ...prev, ...next };
  for (const key of ["usage", "cost_usd", "ai_calls", "harness", "model", "provider", "started_at"]) {
    if (merged[key] == null && prev[key] != null) merged[key] = prev[key];
  }
  const prevCost = Number(prev.cost_usd);
  const nextCost = Number(next.cost_usd);
  if (Number.isFinite(prevCost) && (!Number.isFinite(nextCost) || prevCost > nextCost)) {
    merged.cost_usd = prev.cost_usd;
    if (prev.usage && !next.usage) merged.usage = prev.usage;
  }
  merged.progress = { ...(prev.progress || {}), ...(next.progress || {}) };
  const prevPct = Number(prev.progress?.pct);
  const nextPct = Number(next.progress?.pct);
  if (Number.isFinite(prevPct) && (!Number.isFinite(nextPct) || prevPct > nextPct)) {
    merged.progress.pct = prevPct;
  }
  if (merged.progress.cost_usd == null && merged.cost_usd != null) {
    merged.progress.cost_usd = merged.cost_usd;
  }
  if (!merged.progress.usage && merged.usage) merged.progress.usage = merged.usage;
  if (!merged.progress.harness && merged.harness) merged.progress.harness = merged.harness;
  if (Array.isArray(next.running_jobs)) {
    const prevJobs = Array.isArray(prev.running_jobs) ? prev.running_jobs : [];
    merged.running_jobs = next.running_jobs.map((job) => {
      const older = prevJobs.find((row) => (
        String(row?.trace_id || row?.id || "") === String(job?.trace_id || job?.id || "")
      ));
      return older ? mergeLiveGenerationFields(job, older) : job;
    });
  } else if (next.trace_id && Array.isArray(merged.running_jobs)) {
    delete merged.running_jobs;
  }
  return merged;
}

function upsertProjectInList(summary = {}) {
  const id = summary?.id;
  if (!id) return;
  const idx = allProjects.findIndex((p) => p.id === id);
  if (idx >= 0) {
    const prev = allProjects[idx];
    const next = { ...prev, ...summary, id };
    const prevOpen = Date.parse(prev?.opened_at || "") || 0;
    const nextOpen = Date.parse(next?.opened_at || "") || 0;
    if (prevOpen > nextOpen) next.opened_at = prev.opened_at;
    if (!hasTrackedUsageSummary(next.usage_summary) && hasTrackedUsageSummary(prev.usage_summary)) {
      next.usage_summary = prev.usage_summary;
    }
    if (summary.generation || prev.generation) {
      next.generation = mergeLiveGenerationFields(summary.generation || next.generation, prev.generation);
    }
    allProjects[idx] = next;
  } else {
    allProjects = [{ ...summary, id }, ...allProjects];
  }
}

function markProjectOpenedInExplorer(id) {
  if (!id) return;
  const now = new Date().toISOString();
  allProjects = promoteOpenedProjectInList(allProjects, id, now);
  try {
    if (currentUser?.id) writeCachedProjectList(currentUser.id, allProjects);
  } catch (_) { }
  renderProjectList();
  if (isAnonymousPublicProject(id)) return;
  void api(`/api/projects/${encodeURIComponent(id)}/opened`, { method: "PATCH" })
    .then((data) => {
      const openedAt = data?.opened_at || data?.meta?.opened_at;
      if (!openedAt) return;
      const row = allProjects.find((p) => p.id === id);
      if (row) row.opened_at = openedAt;
      try {
        if (currentUser?.id) writeCachedProjectList(currentUser.id, allProjects);
      } catch (_) { }
      renderProjectList();
    })
    .catch(() => { });
}

async function ensureActiveProjectListed(activeId = projectId) {
  if (!activeId) return true;
  if (allProjects.some((p) => p.id === activeId)) return true;
  try {
    const data = await api(`/api/projects/${activeId}?view=open`);
    upsertProjectInList({
      id: activeId,
      name: data.name || activeId,
      updated_at: data.updated_at,
      created_at: data.created_at,
      file_count: data.files?.length ?? data.file_count ?? 0,
      files: data.files,
      browser: normalizeBrowser(data),
      timeline: data.timeline,
      latest_file: data.latest_file,
      generation: data.generation,
    });
    return true;
  } catch {
    return false;
  }
}

let projectFetchSucceeded = false;

function isAnonymousPublicProject(id = projectId) {
  return !currentUser && !!id && allProjects.some((p) => p.id === id && p.public);
}

function isPublicProject(id = projectId) {
  return !!id && allProjects.some((p) => p.id === id && p.public);
}

function projectApiPath(id = projectId) {
  return isAnonymousPublicProject(id) ? `/api/public/projects/${id}` : `/api/projects/${id}`;
}

function projectHistoryApiPath(id = projectId, kind = "prompt-history") {
  const base = isAnonymousPublicProject(id) ? `/api/public/projects/${id}` : `/api/projects/${id}`;
  return `${base}/${kind}`;
}

function projectFileUrl(id, filename) {
  return `${projectApiPath(id)}/files/${encodeProjectFileRel(filename)}`;
}

async function fetchPublicProjectsForAnonymous() {
  const data = await api("/api/public/projects");
  const folder = data.folder || {
    id: "__public__",
    name: "Public",
    virtual: true,
    read_only: true,
    public: true,
  };
  allProjects = (data.projects || []).map((p) => ({
    ...p,
    folder_id: p.folder_id || folder.id,
    read_only_project: true,
    public: true,
  }));
  workspaceBrowser.setFolders([folder]);
  projectFetchSucceeded = true;
  renderProjectList();
  return allProjects;
}

function hydrateProjectListFromCache() {
  if (allProjects.length) return false;
  const cached = readCachedProjectList(currentUser?.id);
  if (!cached.length) return false;
  allProjects = cached;
  projectFetchSucceeded = true;
  try { renderProjectList(); } catch (_) { }
  return true;
}

async function fetchAllProjects({ force = false } = {}) {
  if (!force && projectsFetchInFlight) return projectsFetchInFlight;
  if (
    !force
    && projectFetchSucceeded
    && allProjects.length
    && (Date.now() - projectsFetchMemoAt) < PROJECTS_FETCH_MEMO_MS
  ) {
    return allProjects;
  }
  const run = fetchAllProjectsUncached();
  projectsFetchInFlight = run;
  projectsListLoading = true;
  try { renderProjectList(); } catch (_) { }
  try {
    return await run;
  } finally {
    if (projectsFetchInFlight === run) projectsFetchInFlight = null;
  }
}

async function fetchAllProjectsUncached() {
  const fetchGen = ++projectsFetchGeneration;
  // Always load every workspace the user can access. Shared-workspace checkboxes
  // (hiddenWorkspaceIds) decide what the Projects browser shows — focusing a
  // workspace in the folder menu only changes create/invite/active context.
  hydrateProjectListFromCache();
  const previousProjects = allProjects;
  projectFetchSucceeded = previousProjects.length > 0;
  const applyPayload = (data) => {
    if (fetchGen !== projectsFetchGeneration) return false;
    const incoming = Array.isArray(data?.projects) ? data.projects : [];
    const prevById = new Map((previousProjects || []).map((row) => [row.id, row]));
    allProjects = incoming.map((row) => {
      const prev = prevById.get(row.id);
      if (!prev) return row;
      const next = { ...prev, ...row, id: row.id };
      if (!hasTrackedUsageSummary(row.usage_summary) && hasTrackedUsageSummary(prev.usage_summary)) {
        next.usage_summary = prev.usage_summary;
      }
      next.generation = mergeLiveGenerationFields(row.generation, prev.generation);
      return next;
    });
    projectFetchSucceeded = true;
    projectsFetchMemoAt = Date.now();
    try { writeCachedProjectList(currentUser?.id, allProjects); } catch (_) { }
    return true;
  };
  const hydrateFolders = () => {
    void workspaceBrowser.refreshFolders().then(() => {
      if (fetchGen === projectsFetchGeneration) {
        try { renderProjectList(); } catch (_) { }
      }
    }).catch(() => { });
  };
  try {
    const request = api("/api/projects?lite=1");
    const raced = await Promise.race([
      request.then((d) => ({ ok: true, d })).catch((err) => ({ ok: false, err })),
      new Promise((resolve) => setTimeout(() => resolve({ timeout: true, request }), PROJECTS_FETCH_WAIT_MS)),
    ]);
    if (raced?.timeout) {
      // Unstick Explorer/tools; apply the list when /api/projects finally returns.
      projectFetchSucceeded = previousProjects.length > 0;
      void raced.request.then((d) => {
        if (!applyPayload(d)) return;
        hydrateFolders();
        try { renderProjectList(); } catch (_) { }
      }).catch((err) => {
        console.warn("fetchAllProjects late failure:", err);
      }).finally(() => {
        projectsListLoading = false;
        try { renderProjectList(); } catch (_) { }
      });
      hydrateFolders();
      void resumeGenerationFromProjects();
      return allProjects;
    }
    projectsListLoading = false;
    if (!raced?.ok) throw raced.err || new Error("Could not load projects");
    if (!applyPayload(raced.d)) return allProjects;
  } catch (err) {
    projectsListLoading = false;
    if (fetchGen !== projectsFetchGeneration) return allProjects;
    const authBlocked = !currentUser || !getToken() || isTokenExpired() || err?.status === 401;
    if (authBlocked) {
      try {
        return await fetchPublicProjectsForAnonymous();
      } catch (_) {
        allProjects = allProjects.filter((p) => p.public);
        workspaceBrowser.setFolders([{
          id: "__public__",
          name: "Public",
          virtual: true,
          read_only: true,
          public: true,
        }]);
        try { renderProjectList(); } catch (_) { }
        return allProjects;
      }
    }
    if (!previousProjects.length) allProjects = [];
    const msg = err.message || "Could not load projects";
    setEditStatus("error", msg);
    if (isTokenExpired()) {
      document.getElementById("auth-modal")?.classList.remove("hidden");
      const browser = document.getElementById("project-browser");
      if (browser && !browser.querySelector(".proj-item")) {
        browser.innerHTML =
          '<p class="status error browser-empty">Session expired — sign in again from the account menu (top right).</p>';
      }
    }
    hydrateFolders();
    throw err;
  }
  if (fetchGen !== projectsFetchGeneration) return allProjects;
  if (projectId && !allProjects.some((p) => p.id === projectId)) {
    await Promise.race([
      ensureActiveProjectListed(projectId),
      new Promise((resolve) => setTimeout(resolve, 4000)),
    ]);
  }
  hydrateFolders();
  void resumeGenerationFromProjects();
  projectsListLoading = false;
  return allProjects;
}

function expandViewportLoadEntries(comps = []) {
  const out = [];
  const seen = new Set();
  for (const entry of comps || []) {
    const kids = (entry.children || []).filter((child) => child?.sidecar_filename);
    if ((entry.virtual_component || entry.orphan_part_group) && kids.length) {
      for (const child of kids) {
        const viewer = String(child.sidecar_filename || "").replace(/\\/g, "/");
        if (!viewer || seen.has(viewer)) continue;
        seen.add(viewer);
        out.push({
          ...entry,
          name: viewer,
          viewer_filename: viewer,
          stem: child.stem || fileStem(viewer),
          virtual_component: false,
          auto_load: true,
        });
      }
      continue;
    }
    const key = entry?.viewer_filename || entry?.name;
    if (!entry || !key || seen.has(key)) continue;
    seen.add(key);
    out.push(entry);
  }
  return out;
}

async function loadProjectComponents(comps, { projectId: pid, latestFile, loadGen, fitView = true, loadAll = false, placeLatestBeside = false, orientationMode = null, styleMode = "auto", cacheBust = false, replaceExisting = false, onFirstLoaded = null } = {}) {
  if (loadGen != null && loadGen !== loadProjectGeneration) return false;
  if (!comps?.length) return false;
  if (isInternalCadSidecar(latestFile)) {
    latestFile = firstDesignedViewportName() || null;
  }
  comps = comps.filter((entry) => {
    const name = entry?.name;
    if (isJakeStepPreviewName(name) || isJakeStepPreviewName(entry?.viewer_filename)) return true;
    return !isInternalCadSidecar(name);
  });
  if (!comps.length) return false;
  prepareViewportForModels();
  const visibleComps = comps.filter((c) => !isBrowserComponentHidden(c));
  if (!visibleComps.length) {
    selectedFile = null;
    clearModelContents();
    currentMesh = projectAssembly.getRoot();
    setEditStatus("ok", "All components are hidden.");
    syncExportButton();
    return false;
  }
  let designedComps = visibleComps.filter((c) => !isCatalogHardwareComponent(c) && (viewportViewerFor(c) || (c.children || []).some((k) => k.sidecar_filename)));
  designedComps = expandViewportLoadEntries(designedComps);
  if (!designedComps.length) {
    designedComps = (lastProjectFiles || [])
      .map((file) => (typeof file === "string" ? { name: file } : file))
      .filter((file) => {
        const name = file?.name;
        return name
          && isViewportViewableFilename(name)
          && !isInternalCadSidecar(name)
          && !isCatalogHardwareComponent(file);
      })
      .map((file) => ({
        name: file.name,
        viewer_filename: file.viewer_filename || file.name,
        stem: fileStem(file.name),
        size: file.size,
        auto_load: true,
      }));
  }
  if (!designedComps.length) {
    selectedFile = null;
    clearModelContents();
    currentMesh = projectAssembly.getRoot();
    setEditStatus("ok", "Catalog hardware is in the browser — generate to assemble it into one model.");
    syncExportButton();
    return false;
  }
  const primary = primaryViewportComponent(designedComps, latestFile);
  if (!primary) return false;
  if (loadGen != null && loadGen !== loadProjectGeneration) return false;
  const seen = new Set();
  const ordered = [];
  const pushUnique = (entry) => {
    const key = entry?.viewer_filename || entry?.name;
    if (!entry || !key || seen.has(key)) return;
    seen.add(key);
    ordered.push(entry);
  };
  if (!loadAll || !placeLatestBeside) pushUnique(primary);
  const existingAssemblyCount = Number(projectAssembly.count?.() || 0);
  const meshBelongsHere = viewportMeshProjectId === pid;
  const shouldReplace = replaceExisting || !meshBelongsHere;
  // keepModel leaves the outgoing catalog in the assembly. Reuse only when
  // that catalog is this project's — untitled.glb from Police Rack ≠ Skull.
  const reuseExisting = !shouldReplace && meshBelongsHere && existingAssemblyCount > 0;
  if (loadAll) {
    const loadOrder = placeLatestBeside
      ? latestGenerationLast(designedComps, latestFile)
      : designedComps;
    const autoLoadComps = loadOrder.filter((c) => c.auto_load === true);
    if (!placeLatestBeside) {
      for (const comp of autoLoadComps) pushUnique(comp);
    }
    for (const comp of loadOrder) pushUnique(comp);
  } else if (latestFile) {
    const latestComp = designedComps.find((c) => c.name === latestFile || c.viewer_filename === latestFile);
    pushUnique(latestComp);
  }
  selectedFile = primary.name;
  let lastError = null;
  let loadedCount = 0;
  let firstLoadedEntry = null;
  let firstPainted = false;
  const markFirstLoaded = () => {
    if (firstPainted) return;
    firstPainted = true;
    try { onFirstLoaded?.(); } catch (_) { }
  };
  const assembledStems = assembledStemsFromEntries(designedComps);
  const blobByViewer = startBlobPrefetch(
    ordered.flatMap((entry) => {
      const viewer = viewportViewerFor(entry) || entry.viewer_filename || entry.name;
      if (!isViewportViewableFilename(viewer)) return [];
      if (shouldSkipDuplicateExploded(viewer, assembledStems)) return [];
      if (reuseExisting && meshBelongsHere && (projectAssembly.has(entry.name) || projectAssembly.has(viewer))) return [];
      const knownBytes = Number(
        (lastProjectFiles || []).find((f) => f.name === viewer || f.name === entry.name)?.size || 0,
      );
      if (knownBytes > VIEWPORT_MAX_MESH_BYTES) return [];
      const url = projectFileUrl(pid, viewer);
      const path = _cacheBustModelPath(_apiPath(url), { force: !!cacheBust });
      return [{ key: viewer, fetch: () => fetchModelBlob(path) }];
    }),
  );
  try {
    for (const entry of ordered) {
      if (loadGen != null && loadGen !== loadProjectGeneration) return false;
      const viewer = viewportViewerFor(entry) || entry.viewer_filename || entry.name;
      if (!isViewportViewableFilename(viewer)) continue;
      if (shouldSkipDuplicateExploded(viewer, assembledStems)) continue;
      selectedFile = entry.name;
      if (
        reuseExisting
        && meshBelongsHere
        && (projectAssembly.has(entry.name) || projectAssembly.has(viewer))
      ) {
        firstLoadedEntry ||= entry;
        loadedCount += 1;
        markFirstLoaded();
        continue;
      }
      let blob = null;
      const pending = blobByViewer.get(viewer);
      if (pending) {
        try {
          blob = await pending;
        } catch (err) {
          lastError = err;
          console.warn("prefetch skipped, loading directly", entry.name, err);
          blob = null;
        }
      }
      if (loadGen != null && loadGen !== loadProjectGeneration) return false;
      let ok = false;
      try {
        ok = await loadModel(
          projectFileUrl(pid, viewer),
          viewer,
          {
            projectId: pid,
            append: loadedCount > 0 || reuseExisting,
            autoGridPlace: placeLatestBeside
              && (entry.name === latestFile || entry.viewer_filename === latestFile),
            catalogFilename: entry.name,
            center: !hasBakedPlacement(entry),
            fitView: false,
            autoGizmo: false,
            cacheBust: !!cacheBust,
            blob,
            orientationMode: (orientationMode && (entry.name === latestFile || entry.viewer_filename === latestFile)) ? orientationMode : null,
            styleMode: (styleMode && styleMode !== "auto")
              ? ((entry.name === latestFile || entry.viewer_filename === latestFile || hasMeshFactorySibling(entry.name) || hasMeshFactorySibling(entry.viewer_filename))
                ? styleMode
                : "auto")
              : (hasMeshFactorySibling(entry.name) || hasMeshFactorySibling(entry.viewer_filename) ? "shaded" : "auto"),
            skipEdges: true,
          },
        );
      } catch (err) {
        if (loadGen != null && loadGen !== loadProjectGeneration) return false;
        lastError = err;
        console.warn("Project component failed to load", entry.name, err);
        continue;
      }
      if (loadGen != null && loadGen !== loadProjectGeneration) return false;
      const leftoverSameName = !meshBelongsHere
        && (projectAssembly.has(entry.name) || projectAssembly.has(viewer));
      if (!ok && (!projectAssembly.has(entry.name) || leftoverSameName)) {
        lastError = lastError || new Error(`Model load was cancelled or did not complete for ${entry.name}.`);
        console.warn("loadModel skipped", entry.name, lastError);
        continue;
      }
      if (ok || (meshBelongsHere && projectAssembly.has(entry.name))) {
        firstLoadedEntry ||= entry;
        loadedCount += 1;
        markFirstLoaded();
      }
    }
    if (!loadedCount) {
      selectedFile = null;
      if (shouldReplace) {
        clearModelContents();
        currentMesh = projectAssembly.getRoot();
      }
      syncExportButton();
      const msg = lastError?.message || "Could not load model into the viewport.";
      setEditStatus("error", msg);
      viewerOverlay.showError(msg);
      stampStudioCreditIncident("models.missing", msg, { projectId: pid, designed: designedComps.length });
      return false;
    }
    selectedFile = firstLoadedEntry.name;
    projectTree.setSelected(selectedFile);
    featureEditor.setModel(projectId, selectedFile);
    safeRestoreActiveModelPromptState({ restoreMode: false });
    hideOverlappingScaledDuplicates(selectedFile);
    if (fitView && !(viewportXR?.isPresenting?.() || renderer?.xr?.isPresenting)) {
      // Fit the visible mesh cluster (not origin + sky). Do not re-seat an
      // existing assembly onto the floor — that jumps live parts when appending.
      // Never run this on the live XR framebuffer (scale=1 / fitCamera crash Quest).
      if (reuseExisting && projectAssembly.count() > 1) {
        fitCamera();
      } else {
        seatAssemblyToFloor();
        fitCamera();
      }
    }
    setEditStatus(lastError ? "error" : "ok", lastError
      ? `Loaded ${loadedCount} component(s); another component failed: ${lastError.message}`
      : "Loaded model in viewport.");
    viewerOverlay.clearError();
    if (pid) viewportMeshProjectId = pid;
    stampStudioCreditIncident("models.loaded", `Loaded ${loadedCount} component(s)`, { projectId: pid, loadedCount });
    return true;
  } catch (err) {
    lastError = err;
    console.error("loadModel failed:", primary.name, err);
    const msg = lastError?.message || "Could not load model into the viewport.";
    setEditStatus("error", msg);
    viewerOverlay.showError(msg);
    stampStudioCreditIncident("models.missing", msg, { projectId: pid });
    return false;
  }
}

let sketchOpenAbort = null; // leakfix104
function beginSketchOpenFetch() {
  if (sketchOpenAbort) {
    try { sketchOpenAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  sketchOpenAbort = ctl;
  return ctl;
}

async function openSketchInViewport(entry) {
  if (!projectId || !entry || entry.format !== "sketch") {
    if (sketchOpenAbort) {
      try { sketchOpenAbort.abort(); } catch (_) { /* ignore */ }
    }
    return;
  }
  workspaceModes.setMode("design");
  applyWorkspaceMode("design");
  workspaceModes.setDesignTab("SKETCH");
  const ctl = beginSketchOpenFetch();
  try {
    const sketch = await api(`/api/projects/${projectId}/sketches/${encodeURIComponent(entry.stem)}`, { signal: ctl.signal });
    if (ctl.signal.aborted) return;
    sketchEditor.loadSketch(sketch);
    ribbon?.setSketchProfile(sketch.profile, sketch.plane || "XY");
    projectTree.setSelected(entry.name);
    setEditStatus("ok", `Loaded sketch “${sketch.name || entry.name}”.`);
    setRightTab("sketch");
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return;
    setEditStatus("error", err.message || "Could not load sketch.");
  }
}

async function openSketchForEdit(entry) {
  if (!projectId || !entry || entry.format !== "sketch") {
    if (sketchOpenAbort) {
      try { sketchOpenAbort.abort(); } catch (_) { /* ignore */ }
    }
    return;
  }
  if (sketchEditor.isActive()) {
    setEditStatus("ok", "Already editing a sketch — finish or cancel first.");
    return;
  }
  workspaceModes.setMode("design");
  applyWorkspaceMode("design");
  workspaceModes.setDesignTab("SKETCH");
  const ctl = beginSketchOpenFetch();
  try {
    const sketch = await api(`/api/projects/${projectId}/sketches/${encodeURIComponent(entry.stem)}`, { signal: ctl.signal });
    if (ctl.signal.aborted) return;
    sketchEditor.applySketchData(sketch);
    enterSketchMode();
    const nameEl = document.getElementById("sketch-name");
    if (nameEl && sketch.name) nameEl.textContent = sketch.name;
    ribbon?.setSketchProfile(sketch.profile, sketch.plane || "XY");
    projectTree.setSelected(entry.name);
    setEditStatus("ok", `Editing sketch “${sketch.name || entry.name}”.`);
    setRightTab("sketch");
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return;
    setEditStatus("error", err.message || "Could not open sketch for editing.");
  }
}

async function openProgramForEdit(entry) {
  if (!projectId || !entry || entry.format !== "program") return;
  setEditStatus("loading", `Opening ${entry.stem}…`);
  try {
    // Load the GLB in the viewport
    const data = await api(`/api/projects/${projectId}`);
    const comp = (data.browser?.components || []).find((c) => c.stem === entry.stem);
    if (comp) {
      await openBrowserComponent(comp);
    } else {
      // Fall back: just set the selected file
      selectedFile = `${entry.stem}.glb`;
      featureEditor.setModel(projectId, selectedFile);
    }
    // Show the feature editor (History tab on right panel)
    setRightTab("history");
    featureEditor.setModel(projectId, `${entry.stem}.glb`);
    setEditStatus("ok", `Editing features for "${entry.stem}" — modify values then Rebuild.`);
  } catch (err) {
    setEditStatus("error", err.message || "Could not open program for editing.");
  }
}

async function openHierarchyItem(project, entry, sectionId, { fitView = false } = {}) {
  if (!project?.id || !entry) return;
  if (sectionId === "wiring") {
    if (project.id !== projectId) await loadProject(project.id);
    await openWiringDiagramTab({ label: entry?.name || "Wiring", entry });
    return;
  }
  if (project.id !== projectId) {
    await loadProject(project.id);
  }
  if (sectionId === "components" || sectionId === "bodies" || sectionId === "vr_creations") {
    await openBrowserComponent(entry, { fitView });
    return;
  }
  if (sectionId === "imagine") {
    if (/\.(step|stp|stl|glb|gltf|3mf)$/i.test(String(entry.name || ""))) {
      await openBrowserComponent(entry);
    } else {
      await openReferenceFile(entry);
      showImaginePanel();
    }
    return;
  }
  if (sectionId === "drawings" || sectionId === "references" || sectionId === "renders") {
    if (entry.format === "dxf" || isDxfDrawingFilename(entry.name)) {
      await openDxfDrawing(entry);
    } else {
      await openReferenceFile(entry);
    }
    showAiComposePanel();
    return;
  }
  if (sectionId === "sketches") {
    if (entry.format === "sketch") {
      await openSketchInViewport(entry);
      return;
    }
    const data = await api(`/api/projects/${projectId}`);
    const comp = (data.browser?.components || []).find((c) => c.stem === entry.stem);
    if (comp) await openBrowserComponent(comp);
    else featureEditor.setModel(projectId, `${entry.stem}.glb`);
    showAiComposePanel();
    return;
  }
  workspaceModes.setMode("wiring");
  applyWorkspaceMode("wiring");
  await wiringSim.load?.();
  await refreshWiringPromptHistory();
}

async function deleteHierarchyComponent(project, entry, sectionId = "components") {
  const filename = entryDeleteName(entry);
  if (!project?.id || !filename) return;
  if (entry?.virtual_component && entry?.orphan_part_group && !/\.(glb|gltf|step|stp|stl|3mf)$/i.test(filename.split("/").pop() || "")) {
    return;
  }
  const kind =
    sectionId === "references"
      ? "reference file"
      : sectionId === "renders"
        ? "render"
        : sectionId === "robots"
          ? "robot file"
          : sectionId === "imagine"
            ? "Imagine file"
            : "component";
  const warned = await openDeleteConfirmDialog({
    eyebrow: "Explorer",
    title: `Delete ${kind} “${filename}” from this project?`,
    body: `This removes the ${kind} from the project. This cannot be undone.`,
    confirmLabel: "Delete",
  });
  if (!warned) return;
  try {
    const data = await api(projectFileDeleteApiPath(project.id, filename), { method: "DELETE" });
    if (project.id === projectId) {
      try {
        projectAssembly.remove(filename);
        if (entry?.name) projectAssembly.remove(entry.name);
        if (entry?.sidecar_filename) projectAssembly.remove(entry.sidecar_filename);
      } catch (_) { /* already gone */ }
      dxfViewer?.closeIfOpen?.(filename);
      referenceFilesViewer?.closeTab?.(filename);
      await syncAfterObjectDelete({ deletedFile: filename, ...data });
      setEditStatus("ok", `Deleted ${kind} ${filename}.`);
    } else {
      await fetchAllProjects();
    }
  } catch (err) {
    alert(err.message || `Failed to delete ${kind}`);
  }
}

async function deleteHierarchyComponents(project, rows = []) {
  const items = (rows || []).map((row) => ({
    filename: entryDeleteName(row?.entry || row),
    sectionId: row?.sectionId || "components",
  })).filter((row) => row.filename);
  if (!project?.id || !items.length) return;
  if (items.length === 1) {
    await deleteHierarchyComponent(project, { name: items[0].filename }, items[0].sectionId);
    return;
  }
  const warned = await openDeleteConfirmDialog({
    eyebrow: "Explorer",
    title: `Delete ${items.length} items from this project?`,
    body: "This removes the selected files from the project. This cannot be undone.",
    confirmLabel: `Delete ${items.length}`,
  });
  if (!warned) return;
  let lastData = null;
  const deleted = [];
  try {
    for (const item of items) {
      lastData = await api(projectFileDeleteApiPath(project.id, item.filename), { method: "DELETE" });
      dxfViewer?.closeIfOpen?.(item.filename);
      referenceFilesViewer?.closeTab?.(item.filename);
      deleted.push(item.filename);
    }
    if (project.id === projectId) {
      await syncAfterObjectDelete({ deletedFile: deleted[deleted.length - 1], deleted_files: deleted, ...lastData });
      setEditStatus("ok", `Deleted ${deleted.length} items.`);
    } else {
      await fetchAllProjects();
    }
  } catch (err) {
    if (deleted.length && project.id === projectId) {
      await syncAfterObjectDelete({ deletedFile: deleted[deleted.length - 1], deleted_files: deleted, ...lastData });
    }
    alert(err.message || "Failed to delete items");
  }
}

async function renameHierarchyComponent(project, entry) {
  if (!project?.id || !entry?.name) return;
  if (project.id !== projectId) {
    await loadProject(project.id);
  }
  renameProjectFile(entry.name);
}

async function attachHierarchyComponentToWiring(project, entry, payload) {
  if (!project?.id || !entry) return;
  if (project.id !== projectId) {
    await loadProject(project.id);
  }
  workspaceModes.setMode("wiring");
  applyWorkspaceMode("wiring");
  await wiringSim.load?.();
  await new Promise((resolve) => requestAnimationFrame(resolve));
  const result = wiringSim.attachComponentRef?.(payload || entry);
  const label = payload?.label || entry.stem || entry.name;
  setEditStatus("ok", `${label} attached to the Wiring Simulator${result?.recognized === false ? " as a generic module" : ""}.`);
}

