function componentIdentityNames(entryOrName = {}) {
  if (typeof entryOrName === "string") return [entryOrName].filter(Boolean);
  const entry = entryOrName || {};
  if (entry.virtual_component) {
    return [
      entry.name,
      entry.id,
      entry.stem,
      entry.component_name,
      entry.node_name,
      entry.source_filename,
      entry.parent_filename,
      entry.viewer_filename,
    ].filter(Boolean).map(String);
  }
  if (entry.virtual_body) {
    return [
      entry.name,
      entry.id,
      entry.stem,
      entry.body_name,
      entry.body_name ? `${entry.body_name}.glb` : null,
      entry.body_name ? `${entry.body_name}.step` : null,
      entry.body_name ? `${entry.body_name}.stp` : null,
    ].filter(Boolean).map(String);
  }
  return [
    entry.name,
    entry.filename,
    entry.viewer_filename,
    entry.source_filename,
    entry.parent_filename,
    entry.source_file,
    entry.glb,
    entry.step_file,
    entry.id,
    entry.stem,
    entry.stem ? `${entry.stem}.glb` : null,
    entry.stem ? `${entry.stem}.step` : null,
    entry.stem ? `${entry.stem}.stp` : null,
  ].filter(Boolean).map(String);
}

function setStoredComponentHidden(pid, entryOrName, hidden) {
  const candidateNames = componentIdentityNames(entryOrName);
  if (!pid || !candidateNames.length) return new Set();
  const names = new Set(loadHiddenComponentState(pid));
  const candidateStems = new Set(candidateNames.map(componentStemName).filter(Boolean));
  if (hidden) {
    for (const name of candidateNames) names.add(name);
  } else {
    for (const name of [...names]) {
      if (candidateNames.includes(name) || candidateStems.has(componentStemName(name))) {
        names.delete(name);
      }
    }
  }
  const key = hiddenComponentsStorageKey(pid);
  if (key) {
    try {
      localStorage.setItem(key, JSON.stringify([...names]));
    } catch {
      /* local storage is best-effort */
    }
  }
  return names;
}

function componentStemName(name = "") {
  return String(name || "")
    .toLowerCase()
    .replace(/\.[^.]+$/, "")
    .replace(/^.+?__\d+_/, "")
    .replace(/_edited(?:_\d+)?$/i, "")
    .replace(/_cleaned(?:_\d+)?$/i, "")
    .replace(/_(loops|duct|hole|extruded|pulled|mirrored)(?:_\d+)?$/i, "")
    .replace(/_copy\d*$/i, "");
}

function componentVisibilityCandidates(entry = {}) {
  const raw = componentIdentityNames(entry);
  const stems = new Set(raw.map(componentStemName).filter(Boolean));
  for (const [name] of projectAssembly.list()) {
    if (raw.includes(name) || stems.has(componentStemName(name))) raw.push(name);
  }
  return [...new Set(raw)];
}

function setAssemblyComponentVisible(entry, visible) {
  // Virtual bodies must toggle the indexed mesh under the parent — stem matching
  // incorrectly hides the whole component or the wrong fragment.
  if (entry?.virtual_body && Number.isInteger(entry.body_index)) {
    const parentName = String(entry.source_filename || entry.parent_filename || entry.filename || "")
      .split("#body:")[0]
      .trim();
    const root =
      (parentName && projectAssembly.get(parentName))
      || projectAssembly.get(entry.viewer_filename)
      || (selectedFile ? projectAssembly.get(selectedFile) : null)
      || currentMesh;
    if (root) {
      const changed = setAssemblyBodyVisible(root, entry.body_index, visible, {
        bodyName: entry.body_name || entry.label || null,
        partNumber: Number.isInteger(entry.part_number) ? entry.part_number : null,
      });
      if (changed) {
        if (!visible) {
          const selected = objectTools.getSelection?.();
          if (
            selected?.bodyIndex === entry.body_index
            || (selected?.mesh && listObjectMeshes(root).includes(selected.mesh) && selected.bodyIndex == null)
          ) {
            objectTools.clearSelection?.();
            transformControls.detach();
            gizmoPanel.hide();
            document.getElementById("btn-gizmo")?.classList.remove("active");
          }
        }
        return true;
      }
    }
    // Never fall through to whole-component hide for virtual bodies — that either
    // no-ops or hides the entire assembly when bodies share one GLB mesh.
    return false;
  }
  let changed = false;
  const tried = new Set();
  const tryName = (name) => {
    const key = String(name || "");
    if (!key || tried.has(key)) return false;
    tried.add(key);
    const didChange = projectAssembly.setVisible(key, visible);
    if (!didChange) return false;
    if (!visible) {
      const selected = objectTools.getSelection?.();
      const selectedName = selected?.catalogName || (selected?.mesh ? catalogNameForMesh(selected.mesh) : null);
      if (selectedName === key || componentStemName(selectedName) === componentStemName(key)) {
        objectTools.clearSelection?.();
        transformControls.detach();
        gizmoPanel.hide();
        document.getElementById("btn-gizmo")?.classList.remove("active");
      }
    } else {
      // Re-apply per-body eye state after a parent unhide (traverse forces all meshes on).
      reapplyHiddenBodyVisibilityForParent(key);
    }
    return true;
  };
  for (const name of componentVisibilityCandidates(entry)) {
    if (tryName(name)) changed = true;
  }
  // Fallbacks when catalog keys don't line up with the browser row (.step vs .glb, etc.)
  if (!changed) {
    for (const name of [
      entry?.viewer_filename,
      entry?.filename,
      entry?.source_filename,
      entry?.name,
      selectedFile,
    ]) {
      if (tryName(name)) {
        changed = true;
        break;
      }
    }
  }
  if (!changed) {
    const list = projectAssembly.list?.() || [];
    const stem = componentStemName(entry?.name || entry?.viewer_filename || "");
    for (const [name] of list) {
      if (stem && componentStemName(name) === stem && tryName(name)) {
        changed = true;
        break;
      }
    }
    // Single-model projects: hide/show the only loaded part
    if (!changed && list.length === 1) {
      changed = tryName(list[0][0]);
    }
  }
  return changed;
}

/** Collapse Jake/cadpy fragment names (`1_bca52d`, `reservoir_a1b2c3`) to a logical body key. */
function logicalMeshBodyKey(name = "") {
  let text = String(name || "").trim().toLowerCase();
  if (!text) return "";
  if (text.includes("|")) text = text.split("|", 1)[0].trim();
  // Prefer leading part index used by multi-solid tessellation (1_*, 2_*, …).
  const numbered = text.match(/^(\d+)(?:[_-]|$)/);
  if (numbered) return numbered[1];
  text = text.replace(/_[0-9a-f]{5,10}$/i, "").trim();
  return text.replace(/[_]+/g, " ").trim() || String(name || "").trim().toLowerCase();
}

/**
 * Resolve which viewport meshes belong to a browser body row.
 * Part-sidecar Bodies (Reservoir/Base/…) often map to many GLB fragments that share
 * a logical key (1_*, 2_*, …) — hiding only meshes[bodyIndex] looks like a no-op.
 */
function meshesForAssemblyBody(meshes, bodyIndex, { bodyName = null, partNumber = null } = {}) {
  const list = Array.isArray(meshes) ? meshes.filter(Boolean) : [];
  if (!list.length || !Number.isInteger(bodyIndex) || bodyIndex < 0) return [];

  if (bodyName) {
    const want = String(bodyName).trim().toLowerCase().replace(/[_]+/g, " ");
    const exact = list.filter((m) => {
      const raw = String(m?.name || m?.userData?.name || "").trim().toLowerCase().replace(/[_]+/g, " ");
      return raw === want;
    });
    if (exact.length) return exact;
  }

  const partNum = Number.isInteger(partNumber) ? partNumber : null;
  if (partNum != null && partNum > 0) {
    const byPart = list.filter((m) => logicalMeshBodyKey(m?.name || m?.userData?.name) === String(partNum));
    if (byPart.length) return byPart;
  }

  const groups = new Map();
  for (let i = 0; i < list.length; i += 1) {
    const mesh = list[i];
    const key = logicalMeshBodyKey(mesh?.name || mesh?.userData?.name) || `idx:${i}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(mesh);
  }
  const keys = [...groups.keys()].sort((a, b) => {
    const na = Number(a);
    const nb = Number(b);
    if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
    return String(a).localeCompare(String(b));
  });
  // Many fragments → few logical bodies (typical Jake multi-solid GLB).
  if (keys.length > 1 && keys.length < list.length && bodyIndex < keys.length) {
    return groups.get(keys[bodyIndex]) || [];
  }
  // 1:1 mesh ↔ body index
  return list[bodyIndex] ? [list[bodyIndex]] : [];
}

/** Hide/show one body inside a parent assembly (multi-mesh OR single-mesh face ranges). */
function setAssemblyBodyVisible(root, bodyIndex, visible, { bodyName = null, bodyInfo = null, partNumber = null } = {}) {
  if (!root || !Number.isInteger(bodyIndex) || bodyIndex < 0) return false;
  const meshes = listObjectMeshes(root);
  if (meshes.length > 1) {
    const targets = meshesForAssemblyBody(meshes, bodyIndex, { bodyName, partNumber });
    if (!targets.length) return false;
    for (const mesh of targets) {
      mesh.visible = visible;
      mesh.traverse?.((child) => {
        child.visible = visible;
      });
    }
    return true;
  }
  const mesh = meshes[0];
  if (!mesh?.isMesh || !mesh.geometry) return false;
  const info = bodyInfo || objectTools.getBodyInfo?.() || null;
  if (!info?.face_offsets?.length || (info.count || 0) <= 1) {
    // Can't surgically hide one body in a fused mesh without face map.
    return false;
  }
  return setSingleMeshBodyVisible(mesh, bodyIndex, visible, info);
}

function setSingleMeshBodyVisible(mesh, bodyIndex, visible, bodyInfo) {
  if (!ensureMeshBodyMaterialGroups(mesh, bodyInfo)) return false;
  const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
  const mat = mats[bodyIndex];
  if (!mat) return false;
  const hidden = mesh.userData.hiddenBodyIndices || (mesh.userData.hiddenBodyIndices = new Set());
  if (visible) hidden.delete(bodyIndex);
  else hidden.add(bodyIndex);
  mat.visible = visible;
  mat.transparent = !visible ? true : !!mat.userData?.bodyMatWasTransparent;
  if (!visible) {
    if (mat.userData?.bodyMatWasTransparent == null) {
      mat.userData = mat.userData || {};
      mat.userData.bodyMatWasTransparent = !!mat.transparent;
      mat.userData.bodyMatWasOpacity = mat.opacity;
      mat.userData.bodyMatWasDepthWrite = mat.depthWrite;
    }
    mat.opacity = 0;
    mat.depthWrite = false;
  } else if (mat.userData) {
    mat.transparent = !!mat.userData.bodyMatWasTransparent;
    if (mat.userData.bodyMatWasOpacity != null) mat.opacity = mat.userData.bodyMatWasOpacity;
    if (mat.userData.bodyMatWasDepthWrite != null) mat.depthWrite = mat.userData.bodyMatWasDepthWrite;
  }
  mat.needsUpdate = true;
  return true;
}

function ensureMeshBodyMaterialGroups(mesh, bodyInfo) {
  const geom = mesh?.geometry;
  const offsets = bodyInfo?.face_offsets;
  const count = Number(bodyInfo?.count || 0);
  if (!geom || !Array.isArray(offsets) || count <= 1) return false;
  const faceTotal = geom.index
    ? Math.floor(geom.index.count / 3)
    : Math.floor((geom.attributes?.position?.count || 0) / 3);
  if (faceTotal <= 0) return false;

  const readyKey = `${count}:${offsets.join(",")}`;
  if (geom.userData?.bodyGroupsKey === readyKey && Array.isArray(mesh.material) && mesh.material.length >= count) {
    return true;
  }

  const base = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
  if (!base) return false;
  const mats = [];
  for (let i = 0; i < count; i += 1) {
    const clone = base.clone();
    clone.userData = { ...(clone.userData || {}), bodyIndex: i };
    mats.push(clone);
  }
  geom.clearGroups();
  for (let i = 0; i < count; i += 1) {
    const start = Math.max(0, Number(offsets[i]) || 0);
    const end = Math.min(faceTotal, Number(offsets[i + 1] ?? faceTotal) || faceTotal);
    const faceCount = Math.max(0, end - start);
    if (faceCount > 0) geom.addGroup(start * 3, faceCount * 3, i);
  }
  mesh.material = mats;
  mesh.userData.hiddenBodyIndices = mesh.userData.hiddenBodyIndices || new Set();
  geom.userData.bodyGroupsKey = readyKey;
  return true;
}

function reapplyHiddenBodyVisibilityForParent(parentName) {
  const parent = String(parentName || "").split("#body:")[0].trim();
  if (!parent || !projectId) return;
  const root = projectAssembly.get(parent) || null;
  if (!root) return;
  const info = objectTools.getBodyInfo?.() || null;
  const walk = (entry) => {
    if (!entry) return;
    if (entry.virtual_body && Number.isInteger(entry.body_index)) {
      const src = String(entry.source_filename || entry.parent_filename || "").split("#body:")[0];
      if (src && componentStemName(src) === componentStemName(parent)) {
        const wantVisible = !isBrowserComponentHidden(entry);
        setAssemblyBodyVisible(root, entry.body_index, wantVisible, {
          bodyName: entry.body_name || entry.label || null,
          bodyInfo: info,
          partNumber: Number.isInteger(entry.part_number) ? entry.part_number : null,
        });
      }
    }
    for (const child of entry.children || []) walk(child);
  };
  for (const entry of projectTree.getComponents?.() || []) walk(entry);
}

function isHierarchyEntryHidden(project, entry) {
  const names = new Set(loadHiddenComponentState(project?.id || projectId));
  const candidates = componentVisibilityCandidates(entry);
  const candidateStems = new Set(candidates.map(componentStemName).filter(Boolean));
  return [...names].some((name) => candidates.includes(name) || candidateStems.has(componentStemName(name)));
}

async function setHierarchyComponentVisible(project, entry, visible) {
  if (!entry?.name) return;
  const pid = project?.id || projectId;
  if (!pid) return;
  const hidden = setStoredComponentHidden(pid, entry, !visible);
  const rowKey = entry?.name || entry?.viewer_filename || entry?.filename;
  if (rowKey) {
    if (!visible) hidden.add(String(rowKey));
    else hidden.delete(String(rowKey));
    try {
      const key = hiddenComponentsStorageKey(pid);
      if (key) localStorage.setItem(key, JSON.stringify([...hidden]));
    } catch { /* best-effort */ }
  }
  if (pid === projectId) {
    projectTree.setHidden?.([...hidden]);
    if (entry?.virtual_body && Number.isInteger(entry.body_index)) {
      const parentName = String(entry.source_filename || entry.parent_filename || entry.filename || "")
        .split("#body:")[0]
        .trim();
      try {
        if (parentName) await objectTools.refreshBodyInfo?.(parentName);
      } catch { /* best-effort */ }
    }
    const changed = setAssemblyComponentVisible(entry, visible);
    if (visible && !changed && !entry?.virtual_body) {
      await openBrowserComponent(entry);
    } else {
      fitCamera();
    }
    syncExportButton();
  }
  workspaceBrowser?.render?.();
}

function resolveLoadedCatalogName(entry) {
  const names = [
    entry?.sidecar_filename,
    entry?.viewer_filename,
    entry?.source_filename,
    entry?.parent_filename,
    entry?.filename,
    entry?.name,
  ].filter(Boolean).map((n) => String(n).split("#")[0].trim());
  return names.find((n) => projectAssembly.has(n)) || names[0] || "";
}

async function openBrowserComponent(entry, { fitView = false } = {}) {
  if (!projectId || !entry) return;
  if (entry.format === "dxf" || isDxfDrawingFilename(entry.name)) {
    await openDxfDrawing(entry);
    await refreshPromptHistory();
    showAiComposePanel();
    return;
  }
  if (isReferenceFilename(entry.name) || isReferenceFilename(referenceDiskPath(entry)) || isTextLikeKind(entry.kind) || entry.kind === "code" || entry.kind === "json" || entry.kind === "csv" || entry.kind === "spreadsheet" || entry.kind === "text" || entry.kind === "image" || entry.kind === "pdf") {
    await openReferenceFile(entry);
    return;
  }
  saveActiveModelPromptState();
  referenceFilesViewer?.closeAll?.({ localOnly: true });
  projectCodeEditor?.clear();
  dxfViewer?.closeAll?.({ localOnly: true });
  docTabs?.clear?.();
  canvasTabStores.clear();
  docTabs?.restorePinnedTabs?.();
  rememberRestoredCanvasTabs();
  prepareViewportForModels();
  try {
    const catalogName = resolveLoadedCatalogName(entry)
      || ((entry.virtual_body || entry.virtual_component)
        ? (entry.source_filename || entry.parent_filename || entry.filename || entry.name)
        : entry.name);
    if (projectAssembly.has(catalogName)) {
      if (entry.virtual_component) {
        selectBrowserVirtualComponent(entry, { fitView });
      } else if (entry.virtual_body) {
        await selectBrowserBody(entry, { fitView });
      } else {
        selectAssemblyComponent(catalogName, { fitView });
      }
      await refreshPromptHistory();
      showAiComposePanel();
      return;
    }
    selectedFile = catalogName;
    projectTree.setSelected(entry.name);
    let viewer = viewportViewerFor(entry) || entry.viewer_filename || entry.name;
    if (!isJakeStepPreviewName(viewer) && (isInternalCadSidecar(viewer) || isInternalCadSidecar(catalogName))) {
      viewer = firstDesignedViewportName();
      if (!viewer) return;
    }
    const inspectCatalog = isCatalogHardwareComponent(entry) || isCatalogHardwareComponent({ name: catalogName });
    const ok = await loadModel(projectFileUrl(projectId, viewer), viewer, {
      projectId,
      append: projectAssembly.count() > 0,
      catalogFilename: catalogName,
      center: !hasBakedPlacement(entry),
      fitView,
      autoGizmo: false,
      inspectCatalogHardware: inspectCatalog,
      styleMode: inspectCatalog ? "shaded" : undefined,
    });
    if (!ok) {
      if (!projectAssembly.has(entry.name)) {
        throw new Error("Model load was cancelled or did not complete.");
      }
    }
    if (ok && entry.virtual_component) {
      selectBrowserVirtualComponent(entry, { fitView });
    } else if (ok && entry.virtual_body) {
      await selectBrowserBody(entry, { fitView });
    } else if (ok) {
      selectAssemblyComponent(catalogName, { fitView });
    }
    viewerOverlay.clearError();
    await refreshPromptHistory();
    showAiComposePanel();
  } catch (err) {
    setEditStatus("error", err.message || "Could not load model.");
    viewerOverlay.showError(err.message || "Could not load model.");
  }
}

// Cache of per-component part profiles (identity, stats, online source).
const partProfiles = new Map();
function getPartProfile(stem) {
  return stem ? partProfiles.get(stem) || null : null;
}
let partProfilesAbort = null; // leakfix35
async function refreshPartProfiles() {
  if (!projectId) {
    if (partProfilesAbort) {
      try { partProfilesAbort.abort(); } catch (_) { /* ignore */ }
      partProfilesAbort = null;
    }
    partProfiles.clear();
    try { renderWiringPartsPickerList(); } catch (_) { }
    return;
  }
  if (partProfilesAbort) {
    try { partProfilesAbort.abort(); } catch (_) { /* ignore */ }
  }
  const ctl = new AbortController();
  partProfilesAbort = ctl;
  const pid = projectId;
  try {
    const data = await api(`/api/projects/${pid}/parts`, { signal: ctl.signal });
    if (ctl.signal.aborted || projectId !== pid) return;
    partProfiles.clear();
    for (const [stem, profile] of Object.entries(data.profiles || {})) {
      partProfiles.set(stem, profile);
    }
    projectTree.setPartProfiles?.(partProfiles);
    renderProjectList();
  } catch (err) {
    if (ctl.signal.aborted || err?.name === "AbortError") return;
    /* profiles are best-effort */
  } finally {
    if (partProfilesAbort === ctl) partProfilesAbort = null;
  }
  try { renderWiringPartsPickerList(); } catch (_) { }
}

