async function applyOnlineModelAction(action, project, extra = {}) {
  if (!action || !project?.id) return;
  const hit = {
    projectId: project.id,
    title: project.name,
    latestFile: project.latest_file || project.latest_model,
  };
  if (action === "open") {
    await openProjectById(project.id);
    return;
  }
  if (action === "profile") {
    const handle = extra.handle || project.owner_handle;
    const userId = extra.userId || project.owner_user_id;
    try {
      const { openUserProfile } = await import("../components/user-profile.js?v=20260909-measkeep1-shareov1-20260909-remix1-histprof1-settings-redesign2&leakfix75");
      await openUserProfile({ handle, userId });
    } catch (err) {
      if (handle) window.open(`/u/${encodeURIComponent(handle)}`, "_blank", "noopener");
      else setEditStatus("error", err?.message || "Could not open profile.");
    }
    return;
  }
  if (action === "add-author") {
    const userId = extra.userId || project.owner_user_id;
    if (!userId) {
      setEditStatus("error", "This author has no profile to add.");
      return;
    }
    try {
      const result = await api("/api/social/friends", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: userId }),
      });
      setEditStatus("ok", result?.status === "pending" ? "Friend request sent." : "Added.");
    } catch (err) {
      setEditStatus("error", err?.message || "Could not add this person.");
    }
    return;
  }
  if (action === "prompt-history") {
    try {
      const data = await api(`/api/public/projects/${encodeURIComponent(project.id)}/prompt-history`);
      const rows = data.entries || data.prompts || data.history || [];
      showPublicPromptHistoryPopup(project, rows);
    } catch (err) {
      setEditStatus("error", err?.message || "Could not load prompt history.");
    }
    return;
  }
  if (action === "share") {
    if (project?.id) await workspaceBrowser?.openProjectShare?.(project);
    return;
  }
  if (action === "copy-link" || action === "download") {
    await applyViewportSearchAction(action, hit);
    return;
  }
  if (action === "remix" || action === "add-new-project") {
    await runViewportRemix(project.id);
    return;
  }
  if (action === "add-current-project") {
    if (requireStudioAuth({ kind: "remix-into-current", projectId: project.id, targetProjectId: projectId })) return;
    if (!projectId) {
      await runViewportRemix(project.id);
      return;
    }
    try {
      setEditStatus("loading", "Adding to the current project…");
      const data = await api(`/api/public/projects/${encodeURIComponent(project.id)}/remix`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ target_project_id: projectId }),
      });
      await enterRemixedProject(data, { message: "Added this public model to the current project." });
    } catch (err) {
      setEditStatus("error", err?.message || "Could not add to the current project.");
    }
    return;
  }
  if (action === "send-to" || action === "send-to-person" || action === "send-to-team" || action === "send-to-workspace") {
    if (requireStudioAuth({ kind: action, projectId: project.id })) return;
    if (action === "send-to-workspace") {
      await workspaceBrowser?.openProjectShare?.(project);
      return;
    }
    try {
      const mod = await import("../workspace/workspace-send-invite.js?v=20260908-ws-inv1&leakfix43&leakfix44&leakfix45&leakfix46");
      mod.openWorkspaceSendInvite?.({
        getActiveTeam,
        getTeams: () => allTeams,
        api,
        preferProjectId: project.id,
      });
    } catch (err) {
      await workspaceBrowser?.openProjectShare?.(project);
      if (err) setEditStatus("ok", "Opened share so you can send this model.");
    }
  }
}

function showPublicPromptHistoryPopup(project, rows) {
  document.querySelector(".online-models-prompt-pop")?.remove();
  const modal = document.createElement("div");
  modal.className = "catalog-panel-overlay online-models-prompt-pop";
  const items = (rows || []).slice(0, 24);
  modal.innerHTML = `
    <div class="catalog-panel catalog-panel--store" role="dialog" aria-label="Prompt history">
      <div class="catalog-panel-head">
        <div>
          <strong>Prompt history</strong>
          <span class="muted small">${appEscapeHtml(project.name || project.id)}</span>
        </div>
        <button type="button" class="catalog-panel-close" aria-label="Close prompt history">×</button>
      </div>
      <div class="catalog-panel-results">
        ${items.length
      ? items.map((row) => `<p class="online-models-prompt-row">${appEscapeHtml(row.prompt || row.original_prompt || row.text || "")}</p>`).join("")
      : `<p class="muted small">No public prompts for this project.</p>`}
      </div>
    </div>
  `;
  modal.querySelector(".catalog-panel-close")?.addEventListener("click", () => modal.remove());
  modal.addEventListener("mousedown", (e) => { if (e.target === modal) modal.remove(); });
  document.body.appendChild(modal);
}

async function restoreOnlineModelsAfterAuth() {
  let pending = peekOnlineModelsReturn();
  try {
    const url = new URL(window.location.href);
    if (!pending && (url.searchParams.get("onlineModels") === "1" || url.hash === "#online-models")) {
      pending = { open: true, tab: url.searchParams.get("omTab") || "public", query: "" };
      url.searchParams.delete("onlineModels");
      url.searchParams.delete("omTab");
      if (url.hash === "#online-models") url.hash = "";
      window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}` || "/");
    }
  } catch {
    /* optional */
  }
  if (!pending?.open && !pending?.pendingAction) return false;
  consumeOnlineModelsReturn();
  openOnlineModelsCatalog({ tab: pending.tab || "public", query: pending.query || "" });
  const action = pending.pendingAction;
  if (action?.action && action.projectId) {
    const proj = (allProjects || []).find((p) => String(p.id) === String(action.projectId)) || {
      id: action.projectId,
      name: action.projectId,
    };
    await applyOnlineModelAction(action.action, proj, action);
  }
  return true;
}

const LS_MCMASTER_INSERT_DEST = "render3d:mcmasterInsertDest:v1";
const LS_FUSION_IMPORT_DEST = "render3d:fusionImportDest:v1";

function readMcMasterInsertDest() {
  try {
    const mode = localStorage.getItem(LS_MCMASTER_INSERT_DEST) || "ask";
    return ["ask", "current", "new"].includes(mode) ? mode : "ask";
  } catch {
    return "ask";
  }
}

function writeMcMasterInsertDest(mode) {
  const next = ["ask", "current", "new"].includes(mode) ? mode : "ask";
  try {
    localStorage.setItem(LS_MCMASTER_INSERT_DEST, next);
  } catch {
    /* ignore */
  }
  return next;
}

function readFusionImportDest() {
  try {
    const mode = localStorage.getItem(LS_FUSION_IMPORT_DEST) || "ask";
    return ["ask", "current", "new"].includes(mode) ? mode : "ask";
  } catch {
    return "ask";
  }
}

function writeFusionImportDest(mode) {
  const next = ["ask", "current", "new"].includes(mode) ? mode : "ask";
  try {
    localStorage.setItem(LS_FUSION_IMPORT_DEST, next);
  } catch {
    /* ignore */
  }
  return next;
}

async function resolveFusionImportDestination(files, opts = {}) {
  const mode = opts.forceAsk ? "ask" : readFusionImportDest();
  const currentId = opts.currentProjectId || projectId;
  if (mode === "current") {
    if (!currentId) {
      try {
        await ensureProjectForUpload();
      } catch {
        try { await ensureProject(); } catch { /* ask below */ }
      }
    }
    const id = opts.currentProjectId || projectId;
    if (id) return { destination: "current", projectId: id };
  }
  if (mode === "new") return { destination: "new" };
  return askDropDestination(files);
}

async function resolveMcMasterInsertDestination(files, opts = {}) {
  if (opts.forceCurrent) {
    if (!projectId) {
      try {
        await ensureProjectForUpload();
      } catch {
        try { await ensureProject(); } catch { /* ask below */ }
      }
    }
    if (projectId) return { destination: "current", projectId };
  }
  const mode = opts.forceAsk ? "ask" : readMcMasterInsertDest();
  if (mode === "current") {
    if (!projectId) {
      try {
        await ensureProjectForUpload();
      } catch {
        try { await ensureProject(); } catch { /* ask below */ }
      }
    }
    if (projectId) return { destination: "current", projectId };
  }
  if (mode === "new") return { destination: "new" };
  const choice = await askDropDestination(files);
  if (choice?.destination) writeMcMasterInsertDest(choice.destination);
  try { mcmasterInsert?.syncDest?.(); } catch { /* insert may not exist yet */ }
  return choice;
}

