async function openViewportLayoutTab(tab) {
  const id = String(tab?.id || "").trim();
  const kind = String(tab?.kind || "file");
  const label = String(tab?.label || tab?.customLabel || id || "Pane");
  if (!id) return;
  try {
    if (kind === "parts" || id === "__parts_list__") {
      partsListSurface.open();
      return;
    }
    if (kind === "wiring") {
      docTabs.upsert({ id, label, kind: "wiring" });
      showWiringDocumentSurface();
      docTabs.setActive(id);
      return;
    }
    if (kind === "canvas" || id === CANVAS_TAB_ID || id.startsWith("__canvas__")) {
      docTabs.upsert({ id, label, kind: "canvas" });
      docTabs.setActive(id);
      return;
    }
    if (kind === "clip" || id === CLIP_EDITOR_TAB_ID) {
      docTabs.upsert({ id, label, kind: "clip" });
      docTabs.setActive(id);
      return;
    }
    if (kind === "dxf") {
      await openDxfDrawingByName(id, { projectId, label });
      return;
    }
    if (kind === "mcmaster" || kind === "catalog" || kind === "parts-catalog" || id === "mcmaster" || id === "mcmaster:catalog") {
      docTabs.upsert({ id: id === "mcmaster:catalog" ? id : (id || "mcmaster"), label: label || "McMaster-Carr", kind: kind === "catalog" || kind === "parts-catalog" ? kind : "mcmaster" });
      docTabs.setActive(id === "mcmaster:catalog" ? id : (id || "mcmaster"));
      mcmasterInsert?.activateFromShared?.();
      document.getElementById("mcmaster-viewer")?.classList.remove("hidden");
      return;
    }
    if (kind === "viser") {
      docTabs.upsert({ id, label, kind });
      viserViewer?.activateFromShared?.();
      docTabs.setActive(id);
      return;
    }
    if (kind === "teleop") {
      docTabs.upsert({ id, label, kind });
      teleopViewer?.activateFromShared?.();
      docTabs.setActive(id);
      return;
    }
    if (kind === "simulation") {
      docTabs.upsert({ id, label, kind });
      simulationViewer?.activateFromShared?.();
      docTabs.setActive(id);
      return;
    }
    if (kind === "worktop") {
      docTabs.upsert({ id, label, kind });
      worktopViewer?.activateFromShared?.();
      docTabs.setActive(id);
      return;
    }
    await openReferenceFile({ name: id, filename: id, label, kind });
  } catch {
    docTabs.upsert({ id, label: label || "Missing pane", kind: kind || "file" });
    docTabs.setActive(id);
  }
}

function ensureLayoutTab(id, wanted, fallbackKind = "file") {
  if (!id || docTabs.has(id)) return;
  const missing = (wanted || []).find((row) => row.id === id);
  docTabs.upsert({
    id,
    label: missing?.label || "Missing pane",
    kind: missing?.kind || fallbackKind,
  });
}

function revealViewportSplitSurfaces() {
  const ids = docTabs.splitDocIds?.() || [];
  for (const id of ids) {
    const tab = docTabs.list().find((row) => row.id === id) || { id };
    const pane = documentPaneForTab(tab);
    if (pane) {
      pane.classList?.remove?.("hidden");
      try { pane.hidden = false; } catch { /* ignore */ }
      try {
        if (pane.style?.display === "none") pane.style.display = "";
        if (pane.style?.visibility === "hidden") pane.style.visibility = "";
      } catch { /* ignore */ }
    }
    if (tab.kind === "parts" || id === "__parts_list__") partsListSurface?.activate?.();
    if (tab.kind === "wiring" || id === WIRING_TAB_ID) showWiringDocumentSurface();
    if (tab.kind === "mcmaster" || tab.kind === "catalog" || id === "mcmaster" || id === "mcmaster:catalog") {
      mcmasterInsert?.activateFromShared?.();
      document.getElementById("mcmaster-viewer")?.classList.remove("hidden");
    }
  }
  docTabs.render?.();
}

async function restoreViewportLayout(layout) {
  const live = sanitizeSavedLayout(layout);
  const state = splitStateFromTree(live.tree);
  const wanted = (live.tabs?.length ? live.tabs : state.tabs) || [];
  for (const tab of wanted) {
    await openViewportLayoutTab(tab);
  }
  const docId = state.docId;
  if (state.direction && docId) {
    ensureLayoutTab(docId, wanted);
    docTabs.split?.(state.direction, docId, { ratio: state.ratio, notify: false });
    if (state.cross?.direction) {
      ensureLayoutTab(state.cross.docId, wanted);
      ensureLayoutTab(state.cross.extraId, wanted);
      docTabs.split?.(state.cross.direction, state.cross.docId, {
        extraId: state.cross.extraId,
        crossRatio: state.cross.ratio,
      });
    }
    revealViewportSplitSurfaces();
  } else {
    docTabs.unsplit?.();
  }
}

async function openImportedViewportLayout(layout, { destination = "viewport", name = layout?.name, pinned = false } = {}) {
  const live = sanitizeSavedLayout(layout);
  if (destination === "tab") {
    const id = `viewport-layout:${live.id}`;
    docTabs.upsert({ id, label: name || live.name, customLabel: name || live.name, kind: "viewport-layout", pinned, layout: live });
    await restoreViewportLayout(live);
    docTabs.setActive(id, { notify: false });
    setEditStatus("ok", `Opened “${name || live.name}” in a ${pinned ? "pinned " : ""}project tab.`);
    return;
  }
  await restoreViewportLayout(live);
  docTabs.setViewportLayout?.(live.name);
  setEditStatus("ok", `Opened “${live.name}” in Viewport.`);
}

