async function consumeViewportLayoutQuery({ token, listingId, imported } = {}) {
  try {
    if (token) {
      const meta = await api(`/api/share/${encodeURIComponent(token)}`);
      const layout = meta.layout || meta;
      await importLayoutIntoStore(api, { ...sanitizeSavedLayout(layout), shareToken: token });
      await restoreViewportLayout(layout);
    } else if (listingId) {
      const data = await api(`/api/model-listings/${encodeURIComponent(listingId)}`).catch(() => null)
        || await api(`/api/marketplace/product/model/${encodeURIComponent(listingId)}`).catch(() => null);
      const listing = data?.listing || data;
      const layout = layoutFromListing(listing);
      if (!layout) throw new Error("That marketplace item is not a viewport layout.");
      await importLayoutIntoStore(api, layout);
      await restoreViewportLayout(layout);
    }
    window.dispatchEvent(new CustomEvent("render3d:open-preferences-tab", { detail: { tab: "viewport" } }));
    viewportLayoutSaves?.showImportHint?.();
    const params = new URLSearchParams(window.location.search);
    ["import_viewport_layout", "install_viewport_layout", "vp_layout_imported"].forEach((key) => params.delete(key));
    const qs = params.toString();
    window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}${window.location.hash || ""}` || "/");
    if (token || listingId || imported) setEditStatus("ok", "Viewport layout saved to your general Studio settings.");
  } catch (err) {
    setEditStatus("error", err?.message || "Could not import that viewport layout.");
    window.dispatchEvent(new CustomEvent("render3d:open-preferences-tab", { detail: { tab: "viewport" } }));
    viewportLayoutSaves?.showImportHint?.();
  }
}

const mcmasterInsert = createMcMasterInsert({
  docTabs,
  viewerEl: document.getElementById("mcmaster-viewer"),
  resolveDestination: (files, opts) => resolveMcMasterInsertDestination(files, opts),
  getInsertDest: readMcMasterInsertDest,
  setInsertDest: (mode) => {
    writeMcMasterInsertDest(mode);
    mcmasterInsert?.syncDest?.();
  },
  onSuggestParts: async (q, opts = {}) => {
    try {
      const data = await api(`/api/mcmaster/suggest?q=${encodeURIComponent(String(q || "").trim())}`, { signal: opts.signal });
      if (opts.signal?.aborted) return [];
      return data?.entries || [];
    } catch (err) {
      if (opts.signal?.aborted || err?.name === "AbortError") return [];
      return [];
    }
  },
  onImportFiles: async (files, choice) => uploadProjectFiles(files, choice),
  onFetchServerPart: async (part) => {
    await ensureProject();
    const pn = String(part?.number || part?.id || "").trim();
    const data = await api(
      `/api/projects/${projectId}/mcmaster-fetch`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ part_number: pn }),
      },
      180000,
    );
    mcmasterLibraryCache = { projectId, at: 0, entries: [] };
    await refreshFiles();
    const viewer = data.viewer_filename || data.filename;
    // Keep catalog STEP on the server for Generate. Do not dump the tessellated
    // fastener into the live assembly (Fusion crease edges hitch the tab).
    setEditStatus("ok", `Fetched ${data.part_number || viewer} onto the server — Generate can import this STEP.`);
    return data;
  },
  onInsertCatalogPart: async (part) => {
    await ensureProject();
    const data = await api(`/api/projects/${projectId}/hardware/insert`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ catalog_id: part.id || part.number }),
    });
    mcmasterLibraryCache = { projectId, at: 0, entries: [] };
    await refreshFiles();
    const viewer = data.viewer_filename || data.filename;
    setEditStatus("ok", `Inserted ${data.part_number || viewer} — Generate can mate to this part.`);
    return data;
  },
  onLoadLibrary: async () => {
    if (!projectId) return [];
    try {
      const data = await api(`/api/projects/${projectId}/mcmaster-library`);
      return data?.entries || [];
    } catch {
      return [];
    }
  },
  onLibrarySave: async (filenames, choice, meta = {}) => {
    const pid = choice?.projectId || projectId;
    if (!pid || !filenames?.length) return [];
    try {
      const data = await api(`/api/projects/${pid}/mcmaster-library`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          filenames,
          source: "mcmaster",
          page_urls: meta.pageUrls || {},
          part_numbers: meta.partNumbers || {},
          references: meta.references || {},
          titles: meta.titles || {},
        }),
      });
      return data?.entries || [];
    } catch {
      return [];
    }
  },
  onSavePartReference: async ({ cadFilename, partNumber, pageUrl, title }, choice) => {
    const dest = choice || { destination: "current", projectId };
    const pid = dest.projectId || projectId;
    const pn = String(partNumber || "").trim();
    if (!pid || !pn) return null;
    try {
      const data = await api(`/api/projects/${pid}/mcmaster-parts`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          part_number: pn,
          description: title || "",
          used_in: cadFilename || "",
          status: "on_server",
          buy_url: pageUrl || "",
        }),
      });
      if (cadFilename) {
        try {
          await api(`/api/projects/${pid}/mcmaster-library`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              filenames: [cadFilename],
              source: "mcmaster",
              page_urls: pageUrl ? { [cadFilename]: pageUrl } : {},
              part_numbers: { [cadFilename]: pn },
              titles: title ? { [cadFilename]: title } : {},
              references: { [cadFilename]: "parts_list.md" },
            }),
          });
        } catch {
          /* optional index link */
        }
      }
      await refreshFiles();
      setEditStatus("ok", `Updated McMaster parts list with ${pn}.`);
      return data;
    } catch (err) {
      console.warn("McMaster parts list save failed", err);
      return null;
    }
  },
  onStatus: (kind, text) => {
    if (text) setEditStatus(kind || "ok", text);
  },
});
