let projectCodeEditor = null;

const referenceFilesViewer = createReferenceFilesViewer({
  docTabs,
  tabBarEl: document.getElementById("doc-tab-bar"),
  viewerEl: document.getElementById("ref-viewer"),
  api,
  rawFetch,
  getProjectId: () => projectId,
  listBrowsableFiles: () => {
    const seen = new Set();
    const out = [];
    const add = (name, label) => {
      const key = String(name || "").trim();
      if (!key || seen.has(key)) return;
      if (!/\.(png|jpe?g|webp|gif|bmp|svg|tiff?|pdf|webm|mp4|mov|m4v|mp3|wav|m4a|aac|ogg|flac)$/i.test(key)) return;
      const base = key.replace(/^.*\//, "");
      if (base !== key && seen.has(base)) return;
      seen.add(key);
      seen.add(base);
      out.push({ name: key, label: label || base.replace(/\.[^.]+$/, "") });
    };
    for (const file of lastProjectFiles || []) {
      add(file?.name, file?.label || file?.stem);
    }
    for (const entry of flattenBrowserEntries(lastProjectBrowser?.references)) {
      add(entry?.name || entry?.filename, entry?.label || entry?.stem);
    }
    for (const entry of flattenBrowserEntries(lastProjectBrowser?.renders)) {
      add(entry?.name || entry?.filename, entry?.label || entry?.stem);
    }
    for (const entry of flattenBrowserEntries(lastProjectBrowser?.imagine)) {
      add(entry?.name || entry?.filename, entry?.label || entry?.stem);
    }
    return out.sort((a, b) => String(a.label).localeCompare(String(b.label)));
  },
  getAiKeyBodyFields: () => getPromptAiKeyBodyFields(),
  getAiKeyPickerState: () => {
    const options = (typeof listPromptAiKeyOptions === "function" ? listPromptAiKeyOptions(aiStatus) : [])
      .map((opt) => ({ value: opt.value, label: opt.label || opt.value }));
    const selected = document.getElementById("prompt-ai-key-select")?.value || "";
    return { options, selected };
  },
  setAiKeyPickerValue: (value) => {
    const sel = document.getElementById("prompt-ai-key-select");
    if (!sel || !value) return;
    if (![...sel.options].some((o) => o.value === value)) {
      const opt = document.createElement("option");
      opt.value = value;
      opt.textContent = value;
      sel.appendChild(opt);
    }
    sel.value = value;
    try {
      localStorage.setItem(LS_PROMPT_AI_KEY, value);
      if (projectId) storeProjectPromptAiKeyValue(value, projectId);
    } catch {
      /* ignore */
    }
    syncPromptKeyPill(aiStatus);
  },
  onOpenAiKeyPicker: (anchor) => {
    openPromptKeyPopup(anchor);
  },
  onAskRenderAgent: ({ question, autoSend } = {}) => {
    void renderAgentUi?.openWithQuestion?.(question, { autoSend: autoSend !== false });
  },
  onStatus: (kind, text) => {
    if (text) setEditStatus(kind || "ok", text);
  },
  onDropFiles: async (files) => {
    let list;
    try {
      list = await convertHeicIngestFiles([...(files || [])].filter(Boolean));
    } catch (err) {
      setEditStatus("error", err.message || "Could not convert HEIC to PNG.");
      throw err;
    }
    if (!list.length) return;
    for (const file of list) {
      const uploaded = await uploadReferenceProjectFile(file, {
        destination: "current",
        projectId,
        silent: true,
      });
      const filename = uploaded?.filename || file.name;
      await referenceFilesViewer.openTab(filename, {
        projectId: projectId || uploaded?.project_id,
        label: String(file.name || filename).replace(/\.[^.]+$/, ""),
        kind: uploaded?.kind,
      });
    }
    setEditStatus("ok", list.length === 1 ? `Opened ${list[0].name} in the image viewer.` : `Opened ${list.length} files in the image viewer.`);
  },
  onSendToPrompt: (payload) => sendReferenceMarkupToPrompt(payload),
  onReferenceAction: (payload) => handleReferenceImageAction(payload),
  onOpenVideoEditor: (payload) => {
    void openClipEditorForEntry(payload);
  },
  onAddToVideoEditor: (payload) => {
    void openClipEditorForEntry(payload, { addStill: true });
  },
  onRenderEdited: async ({ projectId: pid }) => {
    if (pid === projectId) {
      try {
        await refreshFiles();
      } catch {
        /* optional */
      }
    }
  },
  onActiveChange: (filename) => {
    if (filename) {
      selectedFile = filename;
      projectTree?.setSelected?.(filename);
      return;
    }
    if (isReferenceFilename(selectedFile) && !docTabs.getActive()) {
      selectedFile = projectAssembly.list?.()[0]?.[0] || null;
      projectTree?.setSelected?.(selectedFile);
    }
  },
});

