function promptDocumentReference({ filename, label, format, text_content } = {}) {
  const name = String(filename || "").trim();
  if (!name) return null;
  const stem = String(label || name).replace(/\.[^.]+$/, "") || "doc";
  const ext = String(format || name.split(".").pop() || "pdf").toLowerCase();
  return {
    id: `document:${projectId || "project"}:${name}`,
    type: "document",
    token: compactComponentToken(stem),
    label: name,
    filename: name,
    stem,
    format: ext,
    text_content: text_content || undefined,
    projectId,
  };
}

function unlinkPromptDocumentChipIfOrphaned(sourceFilename) {
  const source = String(sourceFilename || "").trim();
  if (!source) return;
  if (promptImages.some((img) => String(img.source_filename || "") === source)) return;
  const id = `document:${projectId || "project"}:${source}`;
  const stillLinked = (composer.getReferences?.() || []).some((ref) => ref.id === id);
  if (stillLinked) composer.removeReference?.(id);
}

function stripPromptReferenceProse(filename) {
  if (!composer?.setPromptText) return;
  const current = String(composer.getRawPromptText?.() || composer.getPromptText?.() || "");
  if (!current) return;
  const next = stripPromptFileBanners(current, filename);
  if (next !== current.trim()) composer.setPromptText(next);
}

function promptAttachmentTextContent(payload = {}) {
  const bits = [];
  if (payload.strokeCount) {
    bits.push(
      `Attached marked-up ${payload.kind === "pdf" ? "PDF page(s)" : "image"} with ${payload.strokeCount} hand-drawn markup stroke(s). Use the marks as design intent.`,
    );
  }
  if (payload.documentText) bits.push(String(payload.documentText).trim());
  else if (payload.notes) bits.push(`Notes:\n${payload.notes}`);
  return bits.filter(Boolean).join("\n\n") || undefined;
}

async function sendReferenceMarkupToPrompt(payload = {}) {
  if (!payload?.filename) return;
  if (isImagineRel(payload.filename) || document.getElementById("prompt-pane-imagine")?.classList.contains("active")) {
    showImaginePanel();
    imagineUi?.receiveMarkup?.(payload);
    setEditStatus("ok", `Sent markup back to Imagine to iterate ${payload.filename}.`);
    return;
  }
  showAiComposePanel();
  stripPromptReferenceProse(payload.filename);
  const filename = String(payload.filename);
  const isPdfOrDoc =
    payload.kind === "pdf" ||
    payload.kind === "text" ||
    payload.kind === "svg" ||
    /\.(pdf|svg)$/i.test(filename);
  composer.removeReference?.(`document:${projectId || "project"}:${filename}:notes`);
  if (isPdfOrDoc) {
    const ref = promptDocumentReference({
      filename,
      label: payload.label || filename,
      format: payload.kind === "pdf" ? "pdf" : String(filename).split(".").pop()?.toLowerCase() || payload.kind,
      text_content: promptAttachmentTextContent(payload),
    });
    if (ref) {
      composer.removeReference?.(ref.id);
      composer.addReference(ref, { insertMention: false });
    }
  } else if (payload.kind === "video" || /\.(webm|mp4|mov|m4v)$/i.test(filename)) {
    const stem = String(payload.label || filename).replace(/\.[^.]+$/, "") || "video";
    const ref = {
      id: `video:${projectId || "project"}:${filename}`,
      type: "video",
      token: compactComponentToken(stem),
      label: payload.label || filename,
      filename,
      stem,
      format: String(filename).split(".").pop()?.toLowerCase() || "webm",
      url: projectId
        ? `/api/projects/${encodeURIComponent(projectId)}/files/${String(filename).split("/").map(encodeURIComponent).join("/")}`
        : undefined,
      mime: payload.mime || "video/webm",
      projectId,
    };
    composer.removeReference?.(ref.id);
    composer.addReference(ref, { insertMention: false });
  } else if (payload.documentText) {
    const stem = String(payload.label || payload.filename || "doc")
      .replace(/\.[^.]+$/, "")
      .replace(/[^a-zA-Z0-9_-]+/g, "-")
      .replace(/^-+|-+$/g, "") || "doc";
    composer.addReference({
      id: `document:${projectId || "project"}:${payload.filename}:notes`,
      type: "document",
      token: `@doc-${stem}-notes`,
      label: `${payload.filename} notes`,
      filename: payload.filename,
      stem,
      format: "notes",
      text_content: payload.documentText,
      projectId,
    });
  }

  let attachedImages = 0;
  for (const img of payload.images || []) {
    if (promptImages.length >= 8) break;
    promptImages = promptImages.filter(
      (p) => !(p.source_filename && p.source_filename === payload.filename),
    );
    if (promptImages.length >= 8) break;
    promptImages.push({
      id: img.id || `ref-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      name: img.name || `${payload.label || payload.filename}-marked.png`,
      media_type: img.media_type || "image/png",
      data_url: img.data_url,
      source_filename: payload.filename,
      role: img.role || (isCanvasReference({ filename: payload.filename }) ? "canvas" : undefined),
      drawing_metadata: img.drawing_metadata,
    });
    attachedImages += 1;
    const last = promptImages[promptImages.length - 1];
    queuePromptImagePersist(last);
  }
  if (attachedImages) renderPromptImages();

  if (!restoringModelPromptState) saveActiveModelPromptState();
  const parts = [];
  if (attachedImages) parts.push("marked-up image");
  if (payload.notes) parts.push("notes");
  if (payload.strokeCount) parts.push(`${payload.strokeCount} markup stroke${payload.strokeCount === 1 ? "" : "s"}`);
  setEditStatus(
    "ok",
    parts.length
      ? `Sent ${payload.filename} to AI prompt (${parts.join(" · ")}).`
      : `Sent ${payload.filename} to AI prompt.`,
  );
  promptImageList?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
}

function currentModelFilenameForRenderTexture() {
  if (selectedFile && !isReferenceFilename(selectedFile) && !isDxfDrawingFilename(selectedFile)) return selectedFile;
  return projectAssembly?.list?.()?.[0]?.[0] || null;
}

function openStoreListingForEntry(entry, sectionId, pid = projectId) {
  const filename = browserDiskFilename(entry) || entry?.name;
  if (!filename) {
    setEditStatus("error", "Nothing to add to the store.");
    return;
  }
  const cad = sectionId === "components" || sectionId === "bodies" || sectionId === "vr_creations";
  openStoreListingPopup({
    api,
    projectId: pid,
    filename,
    kind: cad ? "model" : (entry?.kind || ""),
    label: entry?.label || entry?.stem || filename,
    modelFilename: cad ? filename : currentModelFilenameForRenderTexture(),
    onStatus: (level, msg) => setEditStatus(level, msg),
  });
}

let renderShareTargetModalEl = null;

function renderShareFileUrl(pid, filename) {
  return `/api/projects/${encodeURIComponent(pid)}/files/${encodeProjectFileRel(filename)}`;
}

async function renderShareBlob(payload, pid) {
  const url = payload.blobUrl || renderShareFileUrl(pid, payload.filename);
  const res = String(url).startsWith("blob:") || String(url).startsWith("data:")
    ? await fetch(url)
    : await rawFetch(url);
  if (!res.ok) throw new Error("Could not load render image for sharing.");
  return res.blob();
}

function closeRenderShareTargetModal() {
  renderShareTargetModalEl?.classList.add("hidden");
}

function ensureRenderShareTargetModal() {
  if (renderShareTargetModalEl) return renderShareTargetModalEl;
  const modal = document.createElement("div");
  modal.className = "auth-modal hidden";
  modal.id = "render-share-target-modal";
  modal.setAttribute("role", "dialog");
  modal.setAttribute("aria-modal", "true");
  modal.innerHTML = `
    <div class="auth-backdrop" data-render-share-close></div>
    <div class="auth-card app-dialog-card render-share-target-card">
      <button type="button" class="auth-close" data-render-share-close aria-label="Close">&times;</button>
      <h2 class="app-dialog-title">Share Render</h2>
      <p class="muted small">Select a teammate, group, or thread to send this render to.</p>
      <div data-render-share-body></div>
      <p class="auth-error hidden" data-render-share-error></p>
    </div>
  `;
  document.body.appendChild(modal);
  modal.querySelectorAll("[data-render-share-close]").forEach((el) => {
    el.addEventListener("click", closeRenderShareTargetModal);
  });
  return modal;
}

function threadShareLabel(thread = {}) {
  if (thread.kind === "group") return "Group";
  if (thread.visibility === "private") return "Private thread";
  if (thread.slug === "general") return "Project chat";
  return "Thread";
}

async function postRenderShareToThread({ pid, threadId, payload }) {
  if (!threadId) throw new Error("Choose a chat target first.");
  const blob = await renderShareBlob(payload, pid);
  const form = new FormData();
  const label = payload.label || payload.filename;
  form.append("body", [`Shared render: ${label}`, payload.debugText || ""].filter(Boolean).join("\n\n"));
  form.append("images", blob, payload.filename);
  return api(`/api/projects/${encodeURIComponent(pid)}/chat/threads/${encodeURIComponent(threadId)}/messages`, {
    method: "POST",
    body: form,
  });
}

async function shareRenderToProjectChat(payload = {}, pid = projectId) {
  if (!pid || !payload?.filename) return;
  setEditStatus("loading", "Sharing render to project chat...");
  try {
    const threadData = await api(`/api/projects/${encodeURIComponent(pid)}/chat/threads`);
    const threads = threadData.threads || [];
    const target =
      threads.find((thread) => thread.slug === "general")
      || threads.find((thread) => thread.visibility !== "private")
      || threads[0];
    if (!target?.id) throw new Error("No project chat thread is available.");
    await postRenderShareToThread({ pid, threadId: target.id, payload });
    void projectChat?.refreshUnread?.();
    await projectChat?.open?.();
    setEditStatus("ok", "Render shared to project chat.");
  } catch (err) {
    setEditStatus("error", err.message || "Could not share render to project chat.");
  }
}

async function openRenderShareTargetPicker(payload = {}, pid = projectId) {
  if (!pid || !payload?.filename) return;
  const modal = ensureRenderShareTargetModal();
  const body = modal.querySelector("[data-render-share-body]");
  const error = modal.querySelector("[data-render-share-error]");
  modal.classList.remove("hidden");
  if (error) {
    error.classList.add("hidden");
    error.textContent = "";
  }
  body.innerHTML = `<p class="muted small">Loading people and threads...</p>`;
  try {
    const [threadData, memberData] = await Promise.all([
      api(`/api/projects/${encodeURIComponent(pid)}/chat/threads`),
      api(`/api/projects/${encodeURIComponent(pid)}/chat/members`),
    ]);
    const me = String(currentUser?.id || "");
    const members = (memberData.members || []).filter((member) => member?.id && String(member.id) !== me);
    const threads = threadData.threads || [];
    const groups = threads.filter((thread) => thread.kind === "group");
    const groupIds = new Set(groups.map((thread) => thread.id));
    const otherThreads = threads.filter((thread) => !groupIds.has(thread.id));
    body.innerHTML = `
      <div class="render-share-target-section">
        <strong>People</strong>
        <div class="render-share-target-list">
          ${members.length ? members.map((member) => `
            <button type="button" class="render-share-target" data-share-user="${appEscapeHtml(member.id)}">
              <span>${appEscapeHtml(member.display_name || member.email || "Teammate")}</span>
              <small>${appEscapeHtml(member.email || member.handle || "Direct message")}</small>
            </button>
          `).join("") : `<p class="muted small">No teammates are available for this project yet.</p>`}
        </div>
      </div>
      <div class="render-share-target-section">
        <strong>Groups</strong>
        <div class="render-share-target-list">
          ${groups.length ? groups.map((thread) => `
            <button type="button" class="render-share-target" data-share-thread="${appEscapeHtml(thread.id)}">
              <span>${appEscapeHtml(thread.title || "Group")}</span>
              <small>${Number(thread.member_count || 1)} people · ${threadShareLabel(thread)}</small>
            </button>
          `).join("") : `<p class="muted small">No group threads yet.</p>`}
        </div>
      </div>
      <div class="render-share-target-section">
        <strong>Threads</strong>
        <div class="render-share-target-list">
          ${otherThreads.length ? otherThreads.map((thread) => `
            <button type="button" class="render-share-target" data-share-thread="${appEscapeHtml(thread.id)}">
              <span>${appEscapeHtml(thread.title || "Thread")}</span>
              <small>${threadShareLabel(thread)} · ${Number(thread.message_count || 0)} messages</small>
            </button>
          `).join("") : `<p class="muted small">No other threads yet.</p>`}
        </div>
      </div>
    `;
    const setBusy = (target, busy) => {
      body.querySelectorAll("button").forEach((btn) => {
        btn.disabled = busy;
      });
      if (target && busy) target.querySelector("small").textContent = "Sending...";
    };
    body.querySelectorAll("[data-share-thread]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        setBusy(btn, true);
        try {
          await postRenderShareToThread({ pid, threadId: btn.dataset.shareThread, payload });
          closeRenderShareTargetModal();
          void projectChat?.refreshUnread?.();
          setEditStatus("ok", "Render shared to chat.");
        } catch (err) {
          setBusy(btn, false);
          if (error) {
            error.textContent = err.message || "Could not share render.";
            error.classList.remove("hidden");
          }
        }
      });
    });
    body.querySelectorAll("[data-share-user]").forEach((btn) => {
      btn.addEventListener("click", async () => {
        const userId = btn.dataset.shareUser;
        const member = members.find((entry) => String(entry.id) === String(userId));
        setBusy(btn, true);
        try {
          const created = await api(`/api/projects/${encodeURIComponent(pid)}/chat/threads`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              title: member?.display_name || member?.email || "Direct message",
              visibility: "private",
              kind: "dm",
              invite_user_ids: [userId],
            }),
          });
          await postRenderShareToThread({ pid, threadId: created.thread?.id, payload });
          closeRenderShareTargetModal();
          void projectChat?.refreshUnread?.();
          setEditStatus("ok", `Render shared with ${member?.display_name || member?.email || "teammate"}.`);
        } catch (err) {
          setBusy(btn, false);
          if (error) {
            error.textContent = err.message || "Could not share render.";
            error.classList.remove("hidden");
          }
        }
      });
    });
  } catch (err) {
    body.innerHTML = "";
    if (error) {
      error.textContent = err.message || "Could not load chat recipients.";
      error.classList.remove("hidden");
    }
  }
}

async function handleReferenceShareAction(payload = {}) {
  const filename = payload.filename;
  const pid = payload.projectId || projectId;
  const action = payload.action;
  if (!filename || !pid || !action) return;
  const kind = payload.kind
    || (/\.(webm|mp4|mov|m4v)$/i.test(filename) ? "video"
      : /\.(png|jpe?g|webp|gif|bmp|svg)$/i.test(filename) ? "image"
        : /\.pdf$/i.test(filename) ? "pdf" : "file");
  try {
    if (action === "copy-link") {
      if (requireStudioAuth({
        kind: "copy-share",
        projectId: pid,
        filename,
        shareContext: currentVisibleShareContext,
      })) return;
      if (isCodeFilename(filename) || /(?:^|\/)Project Code(?:\/|$)/i.test(String(filename || payload.folder || "")) || payload.kind === "code" || payload.kind === "code-project") {
        promptCodeShare({
          filename,
          folder: payload.folder || codeFolderRootFromEntry({ filename, folder: payload.folder, name: filename }),
          active: filename,
          files: [{ name: filename, filename, path: filename }],
        });
        return;
      }
      try {
        const url = await createShareUrl(pid, filename, currentVisibleShareContext);
        try {
          await navigator.clipboard.writeText(url);
          setEditStatus("ok", "Share link copied — pick a shared workspace if you want.");
        } catch {
          window.prompt("Copy this share link:", url);
          setEditStatus("ok", "Share link ready.");
        }
      } catch (err) {
        setEditStatus("error", err?.message || "Could not copy share link");
      }
      await openFileExportMenu({
        api,
        projectId: pid,
        filename,
        anchorEl: document.body,
        shareContext: currentVisibleShareContext,
        openWorkspacePicker: true,
        title: `Share ${filename}`,
      });
      return;
    }
    if (action === "download") {
      await downloadFile(
        `/api/projects/${encodeURIComponent(pid)}/files/${encodeProjectFilePath(filename)}`,
        String(filename).split("/").pop(),
      );
      setEditStatus("ok", `Downloaded ${filename}`);
      return;
    }
    if (action === "export-share" || action === "share-link") {
      const isMedia = kind === "video" || kind === "image" || kind === "pdf";
      await openFileExportMenu({
        api,
        projectId: pid,
        filename,
        anchorEl: document.body,
        shareContext: currentVisibleShareContext,
        allowOnshape: !isMedia,
        allowFusion: !isMedia,
        title: `Share ${filename}`,
        hint: isMedia
          ? "Copy a public share link, or download CAD exports if this file is paired with a model."
          : undefined,
      });
      setEditStatus("ok", "Opened export / share menu.");
      return;
    }
    if (action === "share-slack" || action === "share-discord") {
      const network = action === "share-discord" ? "discord" : "slack";
      if (requireStudioAuth({
        kind: action,
        projectId: pid,
        filename,
        shareContext: currentVisibleShareContext,
      })) return;
      const title = payload.label || filename || "Render Studio share";
      try {
        setEditStatus("ok", network === "discord" ? "Preparing Discord share…" : "Preparing Slack share…");
        let url = "";
        try {
          url = await createShareUrl(pid, filename, currentVisibleShareContext);
        } catch (err) {
          if (kind !== "image" && kind !== "video") throw err;
          await copyShareText(`${title}\nBuilt in Render Studio`);
          if (network === "discord") {
            window.open(discordOpenHref(), "_blank", "noopener,noreferrer");
            setEditStatus("ok", "Message copied — Discord is open. Attach the file in the channel.");
          } else {
            window.open(slackShareHref({ title }), "_blank", "noopener,noreferrer");
            setEditStatus("ok", "Message copied — Slack is open. Attach the file in the channel.");
          }
          return;
        }
        if (network === "discord") {
          await shareToDiscord(url, { title });
          setEditStatus("ok", "Message copied — Discord is open. Paste in a channel.");
        } else {
          await shareToSlack(url, { title });
          setEditStatus("ok", "Message copied — Slack is open.");
        }
      } catch (err) {
        setEditStatus("error", err?.message || `Could not share to ${network === "discord" ? "Discord" : "Slack"}.`);
      }
      return;
    }
    if (action === "share-x") {
      setEditStatus("ok", kind === "video" ? "Preparing clip for X…" : "Preparing share for X…");
      let blob = payload.blob || null;
      if (!blob) {
        const res = await rawFetch(
          `/api/projects/${encodeURIComponent(pid)}/files/${encodeProjectFilePath(filename)}`,
        );
        if (!res.ok) throw new Error("Could not load file for sharing");
        blob = await res.blob();
      }
      if (kind === "video" || String(blob.type || "").startsWith("video/")) {
        await viewportVideoRecorder?.shareBlobToX?.(blob, {
          inPlace: true,
          skipCaption: !!payload.skipCaption,
        });
        setEditStatus(
          "ok",
          payload.skipCaption
            ? "Opened X compose — drag and drop the downloaded video onto X."
            : "Add a caption, then Post — the timeline stays open.",
        );
        return;
      }
      // Images / other: download + open X compose (same pattern as video studio desktop flow)
      triggerTrackedBlobDownload(blob, filename, xImageDownloadCreated);
      const params = new URLSearchParams();
      params.set("text", "\n\nBuilt in Render Studio https://render3d.app");
      window.open(`https://twitter.com/intent/tweet?${params.toString()}`, "_blank", "noopener,noreferrer");
      setEditStatus("ok", "Downloaded file and opened X — attach the download in compose.");
      return;
    }
  } catch (err) {
    setEditStatus("error", err?.message || "Share action failed");
  }
}

async function handleReferenceImageAction(payload = {}) {
  if (payload.action === "viewport-undo") {
    if (!undoViewportAction()) setEditStatus("error", "Nothing to undo.");
    return;
  }
  if (payload.action === "viewport-redo") {
    if (!redoViewportAction()) setEditStatus("error", "Nothing to redo.");
    return;
  }
  if (!payload?.filename) return;
  const pid = payload.projectId || projectId;
  if (payload.action === "delete") {
    if (pid && pid !== projectId) {
      await loadProject(pid);
    }
    await deleteProjectFile(payload.filename);
    return;
  }
  if (payload.action === "copy-link" || payload.action === "share-x" || payload.action === "share-slack" || payload.action === "share-discord" || payload.action === "download" || payload.action === "export-share") {
    await handleReferenceShareAction(payload);
    return;
  }
  if (payload.action === "save-edited-video") {
    // Timeline + path refs live in editor.json. Never copy video bytes into Video Editor.
    return;
  }
  if (payload.action === "texture-model") {
    const baseFilename = currentModelFilenameForRenderTexture();
    if (!baseFilename) {
      setEditStatus("error", "Open or select a model before wrapping this image as a texture.");
      return;
    }
    await applyRenderedTextureReference({
      renderFilename: payload.filename,
      renderUrl: payload.textureDataUrl || payload.blobUrl || `/api/projects/${encodeURIComponent(pid)}/files/${encodeURIComponent(payload.filename)}`,
      baseFilename,
      renderPrompt: payload.debugText || "",
      wrapMode: payload.wrapMode || "cover",
      maxSize: 2048,
    });
    return;
  }
  if (payload.action === "share-link") {
    await handleReferenceShareAction({ ...payload, action: "export-share" });
    return;
  }
  if (payload.action === "share-chat") {
    await shareRenderToProjectChat(payload, pid);
    return;
  }
  if (payload.action === "share-dm") {
    await openRenderShareTargetPicker(payload, pid);
    return;
  }
  if (payload.action === "store") {
    openStoreListingPopup({
      api,
      projectId: pid,
      filename: payload.filename,
      kind: payload.kind || "image",
      label: payload.label,
      modelFilename: currentModelFilenameForRenderTexture(),
      onStatus: (level, msg) => setEditStatus(level, msg),
    });
  }
}

