async function openRoboticsMonitorSplit(kind = "viser") {
  const liveKind = String(kind || "viser").toLowerCase() === "mujoco" ? "mujoco" : "viser";
  const liveId = liveKind === "mujoco" ? SIMULATION_TAB_ID : VISER_TAB_ID;
  const replacedLiveId = liveKind === "mujoco" ? VISER_TAB_ID : SIMULATION_TAB_ID;
  prepareRoboticsMonitorReplacement(docTabs, {
    replaceId: replacedLiveId,
    onReplace: () => liveKind === "mujoco" ? viserViewer?.closeTab?.() : simulationViewer?.closeTab?.(),
    documentRef: document,
  });
  if (liveKind === "mujoco") {
    simulationViewer?.open?.();
  } else {
    await viserViewer?.connect?.();
  }
  const liveReady = setRoboticsMonitorSideSplit(docTabs, {
    homeId: ROBOTICS_HOME_TAB_ID,
    liveId,
  });
  if (!liveReady) {
    setEditStatus("error", `Could not open the Robotics Home + ${liveKind === "mujoco" ? "MuJoCo" : "Viser"} split.`);
    return false;
  }
  const homePane = document.getElementById("robotics-home-viewer");
  const livePane = document.getElementById(liveKind === "mujoco" ? "simulation-viewer" : "viser-viewer");
  homePane?.classList.remove("hidden");
  homePane?.classList.add("vp-split-doc");
  livePane?.classList.remove("hidden");
  livePane?.classList.add("vp-split-doc");
  const monitorColumn = document.querySelector(".main-column");
  monitorColumn?.classList.add("robotics-monitor-split");
  revealViewportSplitSurfaces();
  for (const [pane, column] of [[homePane, "1"], [livePane, "3"]]) {
    pane?.style.setProperty("display", "flex", "important");
    pane?.style.setProperty("position", "relative", "important");
    pane?.style.setProperty("inset", "auto", "important");
    pane?.style.setProperty("grid-column", column, "important");
    pane?.style.setProperty("grid-row", "2", "important");
    pane?.style.setProperty("width", "auto", "important");
    pane?.style.setProperty("height", "auto", "important");
    pane?.style.setProperty("visibility", "visible", "important");
  }
  document.getElementById("viewport")?.style.setProperty("display", "none", "important");
  if (liveKind === "mujoco") {
    // The iframe was commonly initialized while hidden. Wait until the split
    // owns real dimensions, then explicitly resize, unpause, and use the
    // front task camera. This replaces the old accidental double-click fix.
    await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    simulationViewer?.activateViewport?.({ taskView: true });
  }
  setEditStatus("ok", `Robotics Home and ${liveKind === "mujoco" ? "MuJoCo" : "Viser"} are running side by side.`);
  return true;
}
