async function configureGeneratedModelPlacement(action) {
  const targetProject = projectId;
  if (!targetProject || !viewportXR?.isWorkshopActive?.()) throw new Error('Enter this project’s Workshop first.');
  const { readWorkshopConfig, saveWorkshopConfig } = await import('./workshop-config.js?v=20260929-workshop-scene-v3');
  const surface = action === 'generation_surface' ? await viewportXR.pickGenerationSurface?.() : null;
  if (projectId !== targetProject) return;
  if (action === 'generation_surface' && !surface) return;
  const config = readWorkshopConfig(targetProject);
  if (surface) config.generationPlacement = { ...config.generationPlacement, ...surface, target: 'surface' };
  else config.generationPlacement.sizeMeters = { generation_size_small: 0.3, generation_size_medium: 0.6, generation_size_large: 1 }[action];
  const savedConfig = saveWorkshopConfig(config, targetProject);
  viewportXR.updateWorkshop?.(savedConfig);
  const message = `New models: ${savedConfig.generationPlacement.label} · longest side ${savedConfig.generationPlacement.sizeMeters} m`;
  viewportXR.setAiPanelStatus?.(message);
  setEditStatus('ok', message);
}

