function toggleMobileViewportBrowser() {
  closeMobilePanels();
  window.Render3DMobileChrome?.closeMobileToolsPopup?.();
  if (!projectId) {
    openMobileLeftPanel();
    return;
  }
  const panel = document.getElementById("viewport-browser-panel");
  const open = !!(panel && !panel.classList.contains("hidden") && !panel.hidden);
  if (open) {
    setViewportBrowserCollapsed(true);
  } else {
    setViewportBrowserCollapsed(false);
    mountDesignBrowserInViewport();
  }
  const fab = document.getElementById("mobile-browser-fab");
  const nextOpen = !open && !!projectId;
  fab?.classList.toggle("is-open", nextOpen);
  fab?.setAttribute("aria-pressed", String(nextOpen));
}

