function resolveWiringPartObject(name) {
  const raw = String(name || "").trim();
  if (!raw) return null;
  const stem = raw.replace(/\.[^.]+$/, "");
  const tries = [raw, `${stem}.glb`, `${stem}.stl`, `${stem}.obj`];
  for (const key of tries) {
    const obj = projectAssembly.get(key);
    if (obj) return obj;
  }
  const needle = stem.toLowerCase();
  for (const [key, obj] of projectAssembly.list?.() || []) {
    if (String(key).toLowerCase().replace(/\.[^.]+$/, "") === needle) return obj;
  }
  return null;
}

function showWiringQuestions(schematic, pid) {
  import('../wiring/wiring-questions.js?v=20260928-dialog-close-1').then(({ updateWiringQuestions }) => {
    if (pid !== projectId) return;
    updateWiringQuestions({
      root: document.getElementById('wiring-content-area'), projectId: pid, schematic,
      onContinue: async request => {
        if (pid !== projectId) throw new Error('Return to this project to continue its wiring.');
        const result = await runWiringPrompt(request);
        if (!result) throw new Error('Generation did not start. Check the wiring status and try again.');
      }
    });
  }).catch(error => console.warn('Wiring questions:', error));
}

