function speechRecognitionLang() {
  try {
    return String(navigator.language || navigator.userLanguage || "").trim();
  } catch (_err) {
    return "";
  }
}
const promptDictation = {
  rec: null,
  recorder: null,
  chunks: [],
  btn: null,
  stream: null,
  targetId: "prompt-input",
  committed: "",
  liveText: "",
  lastError: "",
  mode: "", // "speech" | "recorder"
  liveTimer: 0,
  liveBusy: false,
};

function isPromptDictationActive() {
  const recState = promptDictation.recorder?.state;
  return !!(
    promptDictation.rec
    || (promptDictation.recorder && recState && recState !== "inactive")
  );
}

function stopWhisperLiveLoop() {
  if (promptDictation.liveTimer) {
    clearInterval(promptDictation.liveTimer);
    promptDictation.liveTimer = 0;
  }
  promptDictation.liveBusy = false;
}

function pushXrLiveTranscript() {
  try { viewportXR?.refreshAiPromptPanel?.(); } catch (_) { }
}

async function tickWhisperLive(textarea) {
  if (promptDictation.liveBusy) return;
  if (promptDictation.mode !== "recorder" || !promptDictation.recorder) return;
  if (promptDictation.recorder.state === "inactive") return;
  promptDictation.liveBusy = true;
  try {
    try { promptDictation.recorder.requestData?.(); } catch (_) { }
    await new Promise((r) => setTimeout(r, 50));
    const chunks = promptDictation.chunks.slice();
    if (!chunks.length) return;
    const blob = new Blob(chunks, { type: promptDictation.recorder.mimeType || "audio/webm" });
    if (blob.size < 1500) return;
    const text = await transcribeAudioBlob(blob);
    if (!text || promptDictation.mode !== "recorder") return;
    const base = promptDictation.committed || "";
    const live = base ? `${base.replace(/\s*$/, "")} ${text}` : text;
    promptDictation.liveText = live;
    pushXrLiveTranscript();
    if (textarea) writePromptMicTranscript(textarea, live);
    pushXrLiveTranscript();
  } catch (err) {
    // Partial WebM often fails mid-stream — keep polling
  } finally {
    promptDictation.liveBusy = false;
  }
}

function preferMediaRecorderDictation() {
  const ua = navigator.userAgent || "";
  if (/OculusBrowser|Quest|Mobile VR|FBAN|FB_IAB/i.test(ua)) return true;
  if (document.body.classList.contains("xr-presenting")) return true;
  if (!(window.SpeechRecognition || window.webkitSpeechRecognition)) return true;
  return false;
}

function writePromptMicTranscript(textarea, text) {
  if (!textarea) return;
  textarea.value = text;
  if (text) textarea.setAttribute("data-transcribed", "1");
  textarea.dispatchEvent(new Event("input", { bubbles: true }));
}

function setPromptMicActiveUi(on, btn = null) {
  const target = btn || document.querySelector('.prompt-mic-btn[data-mic-target="prompt-input"]');
  document.querySelectorAll(".prompt-mic-btn.mic-active").forEach((b) => {
    b.classList.remove("mic-active");
    b.title = "Dictate prompt (click to start/stop)";
  });
  if (on && target) {
    target.classList.add("mic-active");
    target.title = "Recording… click to stop";
  }
}

function stopPromptDictationStreamOnly() {
  if (promptDictation.stream) {
    try { promptDictation.stream.getTracks().forEach((tr) => tr.stop()); } catch (_) { }
    promptDictation.stream = null;
  }
}

function stopPromptDictation() {
  stopWhisperLiveLoop();
  const rec = promptDictation.rec;
  promptDictation.rec = null;
  if (rec) {
    try { rec.onresult = null; } catch (_) { }
    try { rec.onerror = null; } catch (_) { }
    try { rec.onend = null; } catch (_) { }
    try { rec.stop(); } catch (_) { }
    try { rec.abort(); } catch (_) { }
  }
  const recorder = promptDictation.recorder;
  promptDictation.recorder = null;
  if (recorder && recorder.state === "recording") {
    try { recorder.onstop = null; } catch (_) { }
    try { recorder.stop(); } catch (_) { }
  }
  promptDictation.chunks = [];
  promptDictation.mode = "";
  stopPromptDictationStreamOnly();
  promptDictation.btn = null;
  setPromptMicActiveUi(false);
}

const MIC_TRANSCRIBE_PREF = "render3d:mic-transcribe:v1";
let micPermissionModalBound = false;
let micPermissionWaiter = null;

function micTranscribeUserKey() {
  return String(currentUser?.id || currentUser?.email || "anon").trim().toLowerCase() || "anon";
}

function micTranscribeStorageKey() {
  return `${MIC_TRANSCRIBE_PREF}:${micTranscribeUserKey()}`;
}

function readMicTranscribePrefs() {
  const empty = { asked: false, granted: false, blocked: false };
  try {
    const raw = JSON.parse(localStorage.getItem(micTranscribeStorageKey()) || "null");
    if (raw && typeof raw === "object") {
      return {
        asked: !!raw.asked,
        granted: !!raw.granted,
        blocked: !!raw.blocked,
      };
    }
  } catch { /* ignore */ }
  return empty;
}

function writeMicTranscribePrefs(patch = {}, { persist = true } = {}) {
  const next = { ...readMicTranscribePrefs(), ...patch };
  if (persist) {
    try {
      localStorage.setItem(micTranscribeStorageKey(), JSON.stringify(next));
    } catch { /* private mode */ }
  }
  return next;
}

async function queryBrowserMicPermission() {
  try {
    const status = await navigator.permissions?.query?.({ name: "microphone" });
    return String(status?.state || "");
  } catch {
    return "";
  }
}

function bindMicPermissionModal() {
  if (micPermissionModalBound) return;
  micPermissionModalBound = true;
  const modal = document.getElementById("mic-permission-modal");
  if (!modal) return;
  modal.querySelectorAll("[data-mic-permission-close]").forEach((el) => {
    el.addEventListener("click", () => closeMicPermissionModal({ ok: false, dismissed: true }));
  });
  document.getElementById("mic-permission-allow")?.addEventListener("click", () => {
    void requestMicFromPermissionModal();
  });
}

function setMicPermissionModalCopy({ blocked = false, error = "" } = {}) {
  const title = document.getElementById("mic-permission-title");
  const copy = document.getElementById("mic-permission-copy");
  const errEl = document.getElementById("mic-permission-error");
  const allowBtn = document.getElementById("mic-permission-allow");
  if (title) title.textContent = blocked ? "Microphone is blocked" : "Allow the microphone";
  if (copy) {
    copy.textContent = blocked
      ? "This browser has the mic off for this site (that’s often the default). Open the lock / site settings next to the URL, set Microphone to Allow, then tap Allow microphone here."
      : "Transcription needs the mic. Browsers keep it off until you allow this site. We’ll save that on your account so we don’t keep asking.";
  }
  if (errEl) {
    errEl.textContent = error || "";
    errEl.classList.toggle("hidden", !error);
  }
  if (allowBtn) allowBtn.textContent = blocked ? "Try again" : "Allow microphone";
}

function closeMicPermissionModal(result) {
  const modal = document.getElementById("mic-permission-modal");
  modal?.classList.add("hidden");
  const waiter = micPermissionWaiter;
  micPermissionWaiter = null;
  waiter?.resolve?.(result);
}

async function requestMicFromPermissionModal() {
  const allowBtn = document.getElementById("mic-permission-allow");
  const remember = !!document.getElementById("mic-permission-remember")?.checked;
  if (allowBtn) allowBtn.disabled = true;
  try {
    if (!navigator.mediaDevices?.getUserMedia) {
      throw new Error("This browser cannot use the microphone");
    }
    const stream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    });
    try { stream.getTracks().forEach((track) => track.stop()); } catch { /* keep permission */ }
    writeMicTranscribePrefs({ asked: true, granted: true, blocked: false }, { persist: remember });
    closeMicPermissionModal({ ok: true });
  } catch (err) {
    const blocked = /NotAllowed|SecurityError|PermissionDenied/i.test(String(err?.name || err?.message || ""));
    writeMicTranscribePrefs(
      { asked: true, granted: false, blocked: blocked || readMicTranscribePrefs().blocked },
      { persist: remember },
    );
    setMicPermissionModalCopy({
      blocked: true,
      error: blocked
        ? "The browser blocked the mic. Turn it on for this site, then try again."
        : (err?.message || "Could not turn the microphone on."),
    });
  } finally {
    if (allowBtn) allowBtn.disabled = false;
  }
}

function showMicPermissionModal({ blocked = false, error = "" } = {}) {
  bindMicPermissionModal();
  const modal = document.getElementById("mic-permission-modal");
  if (!modal) {
    return Promise.resolve({ ok: false, error: "Microphone permission dialog missing" });
  }
  if (micPermissionWaiter) {
    return micPermissionWaiter.promise;
  }
  setMicPermissionModalCopy({ blocked, error });
  const remember = document.getElementById("mic-permission-remember");
  if (remember) remember.checked = true;
  modal.classList.remove("hidden");
  let resolve;
  const promise = new Promise((res) => { resolve = res; });
  micPermissionWaiter = { promise, resolve };
  return promise;
}

async function ensureMicTranscribePermission() {
  if (!navigator.mediaDevices?.getUserMedia) {
    return { ok: false, error: "This browser cannot use the microphone" };
  }
  if (document.body.classList.contains("xr-presenting")) {
    return { ok: true };
  }
  const pref = readMicTranscribePrefs();
  const perm = await queryBrowserMicPermission();
  if (perm === "granted") {
    writeMicTranscribePrefs({ asked: true, granted: true, blocked: false });
    return { ok: true };
  }
  if (perm === "denied" || pref.blocked) {
    const result = await showMicPermissionModal({ blocked: true });
    if (result?.ok) return { ok: true };
    return { ok: false, error: "Microphone is blocked for this site" };
  }
  if (pref.granted) return { ok: true };
  const result = await showMicPermissionModal({ blocked: false });
  if (result?.ok) return { ok: true };
  if (result?.dismissed) {
    writeMicTranscribePrefs({ asked: true, granted: false }, { persist: !!document.getElementById("mic-permission-remember")?.checked });
    return { ok: false, error: "Microphone not allowed yet" };
  }
  return { ok: false, error: "Microphone not allowed yet" };
}

async function transcribeAudioBlob(blob) {
  const fd = new FormData();
  const type = blob.type || "audio/webm";
  const ext = type.includes("mp4") ? "mp4" : type.includes("ogg") ? "ogg" : "webm";
  fd.append("file", blob, `speech.${ext}`);
  const headers = { ...(authHeaders?.() || {}) };
  // Let browser set multipart boundary — do not force Content-Type
  delete headers["Content-Type"];
  const res = await fetch("/api/transcribe", { method: "POST", headers, body: fd });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data?.detail || data?.error || `Transcribe failed (${res.status})`);
  return String(data?.text || "").trim();
}

async function stopMediaRecorderDictation(textarea) {
  const recorder = promptDictation.recorder;
  if (!recorder) {
    stopPromptDictation();
    return { ok: true, listening: false };
  }
  stopWhisperLiveLoop();
  promptDictation.liveText = promptDictation.liveText && promptDictation.liveText !== "Listening…"
    ? `${promptDictation.liveText}\n(Transcribing final…)`
    : "Transcribing…";
  pushXrLiveTranscript();
  if (textarea) {
    // Keep committed prompt visible while we upload; status is in liveText for XR panel
  }

  const blob = await new Promise((resolve) => {
    recorder.ondataavailable = (e) => {
      if (e.data && e.data.size) promptDictation.chunks.push(e.data);
    };
    recorder.onstop = () => {
      resolve(new Blob(promptDictation.chunks.slice(), { type: recorder.mimeType || "audio/webm" }));
    };
    try { recorder.requestData?.(); } catch (_) { }
    try { recorder.stop(); } catch (_) { resolve(null); }
  });
  promptDictation.recorder = null;
  promptDictation.chunks = [];
  stopPromptDictationStreamOnly();
  setPromptMicActiveUi(false);
  promptDictation.mode = "";

  if (!blob || blob.size < 64) {
    promptDictation.lastError = "No audio captured — try again";
    if (textarea) writePromptMicTranscript(textarea, promptDictation.committed || textarea.value || "");
    return { ok: false, error: promptDictation.lastError, listening: false };
  }

  try {
    const text = await transcribeAudioBlob(blob);
    const base = promptDictation.committed || "";
    const next = text
      ? (base ? `${base.replace(/\s*$/, "")} ${text}` : text)
      : base;
    promptDictation.committed = next;
    promptDictation.liveText = next;
    if (textarea) writePromptMicTranscript(textarea, next);
    pushXrLiveTranscript();
    if (!text) {
      promptDictation.lastError = "No speech detected";
      return { ok: false, error: promptDictation.lastError, listening: false };
    }
    return { ok: true, listening: false, text };
  } catch (err) {
    promptDictation.lastError = err?.message || "Transcription failed";
    console.warn("[mic] transcribe", err);
    if (textarea) writePromptMicTranscript(textarea, promptDictation.committed || textarea.value || "");
    return { ok: false, error: promptDictation.lastError, listening: false };
  }
}

async function startMediaRecorderDictation(textarea, targetId, btn) {
  stopPromptDictation();
  try {
    promptDictation.stream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    });
    writeMicTranscribePrefs({ asked: true, granted: true, blocked: false });
  } catch (err) {
    promptDictation.lastError = "Mic permission blocked — allow microphone for this site";
    writeMicTranscribePrefs({ asked: true, granted: false, blocked: true });
    if (!document.body.classList.contains("xr-presenting")) {
      const retry = await showMicPermissionModal({
        blocked: true,
        error: "The browser blocked the mic. Turn it on for this site, then try again.",
      });
      if (retry?.ok) return startMediaRecorderDictation(textarea, targetId, btn);
    }
    return { ok: false, error: promptDictation.lastError };
  }

  const mimeCandidates = [
    "audio/webm;codecs=opus",
    "audio/webm",
    "audio/mp4",
    "audio/ogg;codecs=opus",
  ];
  const mime = mimeCandidates.find((m) => window.MediaRecorder?.isTypeSupported?.(m)) || "";
  let recorder;
  try {
    recorder = mime
      ? new MediaRecorder(promptDictation.stream, { mimeType: mime })
      : new MediaRecorder(promptDictation.stream);
  } catch (err) {
    stopPromptDictationStreamOnly();
    promptDictation.lastError = "Recording not supported in this browser";
    return { ok: false, error: promptDictation.lastError };
  }

  promptDictation.chunks = [];
  promptDictation.recorder = recorder;
  promptDictation.mode = "recorder";
  promptDictation.targetId = targetId;
  promptDictation.committed = textarea.value || "";
  promptDictation.liveText = "Listening… speak now";
  promptDictation.lastError = "";
  promptDictation.btn = btn;
  recorder.ondataavailable = (e) => {
    if (e.data && e.data.size) promptDictation.chunks.push(e.data);
  };
  recorder.start(250);
  setPromptMicActiveUi(true, btn);
  pushXrLiveTranscript();
  stopWhisperLiveLoop();
  // Rolling Whisper so Quest shows words while you speak (Web Speech is blocked there)
  promptDictation.liveTimer = window.setInterval(() => {
    void tickWhisperLive(textarea);
  }, 1600);
  window.setTimeout(() => { void tickWhisperLive(textarea); }, 700);
  return { ok: true, listening: true };
}

/**
 * Toggle speech-to-text into a prompt textarea.
 * Quest XR: MediaRecorder + Whisper (click to record / click to stop).
 * Desktop: Web Speech when available, otherwise same recorder path.
 * @returns {{ ok: boolean, listening?: boolean, error?: string, text?: string }}
 */
async function togglePromptDictation(targetId = "prompt-input", btn = null) {
  const textarea = document.getElementById(targetId);
  if (!textarea) return { ok: false, error: "Prompt field missing" };

  // Click again → stop
  if (isPromptDictationActive() && (!btn || btn === promptDictation.btn || targetId === promptDictation.targetId)) {
    if (promptDictation.mode === "recorder" || promptDictation.recorder) {
      return stopMediaRecorderDictation(textarea);
    }
    const committed = promptDictation.committed;
    stopPromptDictation();
    if (committed) writePromptMicTranscript(textarea, committed);
    return { ok: true, listening: false };
  }

  const allowed = await ensureMicTranscribePermission();
  if (!allowed.ok) {
    promptDictation.lastError = allowed.error || "Microphone not allowed yet";
    try { setEditStatus("error", promptDictation.lastError); } catch { /* optional */ }
    return { ok: false, error: promptDictation.lastError };
  }

  // Quest / XR / no Web Speech → MediaRecorder + Whisper (click record / click stop)
  if (preferMediaRecorderDictation() || !(window.SpeechRecognition || window.webkitSpeechRecognition)) {
    if (!window.MediaRecorder) {
      promptDictation.lastError = "Recording not supported in this browser";
      return { ok: false, error: promptDictation.lastError };
    }
    return startMediaRecorderDictation(textarea, targetId, btn);
  }

  // Desktop Web Speech path
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    if (window.MediaRecorder) return startMediaRecorderDictation(textarea, targetId, btn);
    promptDictation.lastError = "Speech not supported in this browser";
    return { ok: false, error: promptDictation.lastError };
  }

  stopPromptDictation();
  try {
    promptDictation.stream = await navigator.mediaDevices.getUserMedia({
      audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
    });
    writeMicTranscribePrefs({ asked: true, granted: true, blocked: false });
  } catch (err) {
    // Fall back to recorder if getUserMedia works later — but permission blocked
    promptDictation.lastError = "Mic permission blocked — allow microphone for this site";
    writeMicTranscribePrefs({ asked: true, granted: false, blocked: true });
    if (!document.body.classList.contains("xr-presenting")) {
      const retry = await showMicPermissionModal({
        blocked: true,
        error: "The browser blocked the mic. Turn it on for this site, then try again.",
      });
      if (retry?.ok) {
        try {
          promptDictation.stream = await navigator.mediaDevices.getUserMedia({
            audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true },
          });
          writeMicTranscribePrefs({ asked: true, granted: true, blocked: false });
        } catch {
          return { ok: false, error: promptDictation.lastError };
        }
      } else {
        return { ok: false, error: promptDictation.lastError };
      }
    } else {
      return { ok: false, error: promptDictation.lastError };
    }
  }

  const rec = new SpeechRecognition();
  rec.continuous = true;
  rec.interimResults = true;
  const dictationLang = speechRecognitionLang();
  if (dictationLang) rec.lang = dictationLang;
  const base = textarea.value || "";
  let committed = base;
  promptDictation.committed = committed;
  promptDictation.targetId = targetId;
  promptDictation.lastError = "";
  promptDictation.liveText = base;
  promptDictation.mode = "speech";
  promptDictation.btn = btn;

  rec.onresult = (e) => {
    let interim = "";
    let finals = base;
    for (const r of e.results) {
      if (r.isFinal) finals += (finals && !finals.endsWith(" ") ? " " : "") + r[0].transcript;
      else interim += r[0].transcript;
    }
    committed = finals;
    promptDictation.committed = finals;
    const live = finals + (interim ? ` ${interim}` : "");
    promptDictation.liveText = live;
    writePromptMicTranscript(textarea, live);
  };

  rec.onerror = (e) => {
    const code = e?.error || "error";
    if (code === "aborted") return;
    // Auto-fallback to MediaRecorder when browser blocks Web Speech (Quest)
    console.warn("[mic] speech error, falling back to recorder", code);
    try { rec.stop(); } catch (_) { }
    promptDictation.rec = null;
    void startMediaRecorderDictation(textarea, targetId, btn).then(() => {
      try { viewportXR?.refreshAiPromptPanel?.(); } catch (_) { }
    });
  };

  rec.onend = () => {
    if (promptDictation.rec === rec) {
      writePromptMicTranscript(textarea, committed);
      stopPromptDictation();
    }
  };

  try {
    rec.start();
  } catch (err) {
    console.warn("[mic] speech start failed, using recorder", err);
    return startMediaRecorderDictation(textarea, targetId, btn);
  }

  promptDictation.rec = rec;
  setPromptMicActiveUi(true, btn);
  return { ok: true, listening: true };
}

function activateStudioVoiceAgent(options = {}) {
  return voiceStartGate(async () => {
    syncVoiceOrderControls(true);
    const requestedModel = xrAgent?.getState?.()?.settings?.voiceModel || "";
    const cachedAccess = voiceSubscriptionAccess(aiStatus, requestedModel);
    if (!cachedAccess.allowed) {
      // Keep the click's media gesture alive while replacing stale account state.
      void Promise.resolve(voiceMold?.primeMedia?.({ stream: options.stream })).catch(() => {});
    }
    const access = await refreshedVoiceSubscriptionAccess({
      status: aiStatus,
      requestedModel,
      refresh: async () => {
        await refreshPromptAiKeysFromServer();
        return aiStatus;
      },
    });
    if (!access.allowed) {
      try { voiceMold?.stop?.(); } catch { /* release any primed media */ }
      try { setEditStatus("error", access.reason); } catch { /* status is optional */ }
      const viewportWidth = document.documentElement?.clientWidth || window.innerWidth || 0;
      if (shouldAutoOpenSubscriptionPopup(viewportWidth)) {
        document.getElementById("btn-subscriptions-menu")?.click();
      }
      syncVoiceOrderControls(false);
      return { ok: false, error: access.reason, source: options.source || "order" };
    }
    if (access.model && access.model !== requestedModel) {
      await xrAgent?.action?.("agent:setting", { voiceModel: access.model });
    }
    return activateStudioVoiceAgentNow(options);
  });
}

async function activateStudioVoiceAgentNow({ source = "order", toggle = false, text = "", greet = true, stream } = {}) {
  const live = !!(voiceMold?.getState?.()?.live || xrAgent?.getState?.()?.live);
  const spoken = String(text || "").trim();
  const headset = stream || (() => { try { return viewportXR?.getVoiceMicStream?.() || null; } catch { return null; } })();
  if (live) {
    if (source === "wake" || greet && !toggle) {
      try { voiceMold?.greet?.(spoken); } catch { /* already live */ }
      syncVoiceOrderControls(true);
      return { ok: true, live: true, source };
    }
    if (toggle) {
      await finalizeHeyAiContext({ stopVoice: true });
      try { voiceWake?.sync?.(); } catch { /* ignore */ }
      syncVoiceOrderControls(false);
      return { ok: true, live: false, source };
    }
    try { voiceMold?.greet?.(spoken); } catch { /* already live */ }
    return { ok: true, live: true, source };
  }
  try { stopPromptDictation(); } catch { /* release the dictation mic */ }
  try { voiceWake?.stop?.(); } catch { /* Realtime PCM needs the mic */ }
  beginHeyAiContext();
  syncVoiceOrderControls(true);
  // The bridge primes media synchronously before settings/network awaits.
  // It also owns microphone acquisition; overlapping Talk controls share this start.
  try {
    if (xrAgent?.start) await xrAgent.start({ greet: greet !== false, text: spoken, stream: headset });
    else if (voiceMold?.start) await voiceMold.start({ greet: greet !== false, text: spoken, stream: headset });
    else throw new Error("Voice agent is not ready");
  } catch (err) {
    const message = err?.message || "Voice could not start";
    const failedRefId = activeHeyAiContext?.id;
    await finalizeHeyAiContext({ removed: true });
    if (failedRefId) composer?.removeReference?.(failedRefId);
    activeHeyAiContext = null;
    try { setEditStatus?.("error", message); } catch { /* ignore */ }
    try { voiceWake?.sync?.(); } catch { /* ignore */ }
    return { ok: false, error: message, source };
  }
  const state = voiceMold?.getState?.() || {};
  if (!state.live && !state.connecting) {
    const message = state.statusMessage || "Voice could not start. Check your selected model and API key.";
    const failedRefId = activeHeyAiContext?.id;
    await finalizeHeyAiContext({ removed: true });
    if (failedRefId) composer?.removeReference?.(failedRefId);
    activeHeyAiContext = null;
    try { setEditStatus?.("error", message); } catch { /* ignore */ }
    try { voiceWake?.sync?.(); } catch { /* ignore */ }
    return { ok: false, error: message, source };
  }
  startHeyAiAudioCapture(
    headset
    || voiceMold?.getInputStream?.()
    || (() => { try { return viewportXR?.getVoiceMicStream?.() || null; } catch { return null; } })()
  );
  if (activeHeyAiContext?.askGenerateAnother && voiceMold?.getState?.()?.live) {
    voiceMold.sendText?.(
      "A previous Hey AI design conversation was completed. Briefly ask the user whether they want to generate another part, edit the selected model, or continue without generating. Do not generate until they explicitly answer yes or ask you to generate.",
      { respond: true },
    );
    activeHeyAiContext.askGenerateAnother = false;
  }
  syncVoiceOrderControls(!!state.live);
  return { ok: true, live: !!state.live, connecting: !!state.connecting, source };
}

function syncVoiceOrderControls(live) {
  const on = live === true || !!(voiceMold?.getState?.()?.live || xrAgent?.getState?.()?.live);
  const requestedModel = xrAgent?.getState?.()?.settings?.voiceModel || "";
  const access = voiceSubscriptionAccess(aiStatus, requestedModel);
  ensureHeyAiVoiceDropdowns();
  document.querySelectorAll("#btn-voice-order, .prompt-voice-order, .prompt-mic-btn[data-voice-order='1']").forEach((el) => {
    el.classList.toggle("is-live", on);
    el.classList.toggle("mic-active", on);
    el.setAttribute("aria-pressed", on ? "true" : "false");
    el.setAttribute("aria-disabled", access.allowed ? "false" : "true");
    el.dataset.voiceSubscriptionReady = access.allowed ? "1" : "0";
    el.setAttribute("aria-label", on ? "Stop listening" : (access.allowed ? "Start voice agent" : access.reason));
    el.title = on
      ? "Stop listening — save voice, pointer, selection, and scene context"
      : (access.allowed ? `Hey AI uses your connected ${access.provider === "claude" ? "Claude" : "ChatGPT"} subscription` : access.reason);
    const label = el.querySelector?.(".prompt-voice-order-label");
    if (label) label.textContent = on ? "Listening" : (el.dataset.voiceIdleLabel || "Hey");
  });
}

function ensureHeyAiVoiceDropdowns() {
  document.querySelectorAll(".hey-ai-voice-select").forEach((select) => select.remove());
}

(function initPromptMicButtons() {
  try {
    window.__togglePromptDictation = togglePromptDictation;
    window.__stopPromptDictation = (targetId) => {
      if (targetId && promptDictation.targetId && promptDictation.targetId !== targetId) return;
      stopPromptDictation();
    };
    window.__activateStudioVoiceAgent = activateStudioVoiceAgent;
  } catch {
    /* ignore */
  }
  // Event delegation so dynamically added mics (e.g. video caption, suggestions) work too
  document.addEventListener("click", (e) => {
    const order = e.target?.closest?.("#btn-voice-order, .prompt-voice-order, [data-voice-order='1']");
    if (order && isVoiceOrderControl(order)) {
      e.preventDefault();
      void activateStudioVoiceAgent({ source: "order", toggle: true });
      return;
    }
    const btn = e.target?.closest?.(".prompt-mic-btn");
    if (!btn) return;
    const targetId = btn.dataset.micTarget || "prompt-input";
    void togglePromptDictation(targetId, btn);
  });
})();

// ── Canvas mode ───────────────────────────────────────────────────────────
function attachVoiceDrawSketchImage(dataUrl, { id, name, promptAugment } = {}) {
  if (!dataUrl) return false;
  const images = promptImages || [];
  if (id && images.some((img) => img.id === id)) return true;
  const entry = {
    id: id || `voice-draw-${Date.now()}`,
    name: name || nextVoiceDrawImageName(images),
    media_type: "image/png",
    data_url: dataUrl,
    kind: "voice-draw",
    promptAugment: String(promptAugment || ""),
  };
  const drawCount = images.filter(isVoiceDrawImage).length;
  if (drawCount >= 4 || images.length >= 8) return false;
  promptImages = [...images, entry];
  try { renderPromptImages(); } catch (_) { }
  if (!restoringModelPromptState) {
    try { saveActiveModelPromptState(); } catch (_) { }
  }
  try { viewportXR?.refreshAiPromptPanel?.(); } catch (_) { }
  return true;
}

function applyVoiceDrawToPrompt() {
  const snap = viewportXR?.snapshotVoiceDrawForPrompt?.();
  const clips = Array.isArray(snap?.clips) && snap.clips.length
    ? snap.clips
    : (snap?.imageDataUrl ? [snap] : []);
  for (const clip of clips) {
    if (clip?.imageDataUrl) {
      attachVoiceDrawSketchImage(clip.imageDataUrl, {
        id: clip.id,
        promptAugment: clip.promptAugment,
      });
    }
  }
  if (!snap && !clips.length) return null;
  return {
    ...(snap || {}),
    clips,
    promptAugment: snap?.promptAugment || mergeComposeAugment("", clips),
    strokeCount: snap?.strokeCount || clips.reduce((n, c) => n + (c.strokeCount || 0), 0),
  };
}

async function talkXrComposeWithAi() {
  const setXrStatus = (msg) => {
    try { viewportXR?.setAiPanelStatus?.(msg); } catch (_) { }
  };
  try {
    if (isPromptDictationActive()) {
      setXrStatus("Finishing transcription…");
      try { await togglePromptDictation("prompt-input"); } catch (err) {
        console.warn("[xr] finalize mic", err);
      }
    }
    if (viewportXR?.isVoiceDrawOn?.()) {
      try { viewportXR.toggleVoiceDraw(); } catch (_) { }
    }
    applyVoiceDrawToPrompt();
    let text = String(
      composer?.getPromptText?.()
      || document.getElementById("prompt-input")?.value
      || "",
    ).trim();
    text = seedXrComposePrompt({
      hasDrawings: composeImagesForPanel(promptImages).length > 0,
      spoken: text,
    });
    if (!text) {
      setXrStatus("Say, draw, or enter a prompt first");
      return { ok: false, error: "Prompt is empty" };
    }
    try { composer?.setPromptText?.(text); } catch (_) { }
    setXrStatus("Talking with AI…");
    await Promise.allSettled(pendingPromptImagePersists?.slice?.() || []);
    const improveImages = (promptImages || [])
      .map(promptImageApiPayload)
      .filter((img) => img && (promptImageHasBytes(img) || img.stored_name || img.url))
      .slice(0, 8);
    const improveText = promptHasCanvasSketchImage()
      ? augmentPromptForCanvasSketch(text)
      : text;
    const data = await api("/api/prompt/improve", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: improveText,
        mode: promptMode || "v2",
        target_mode: typeof getPromptTargetMode === "function" ? getPromptTargetMode() : "new",
        base_filename: promptBaseFilename(),
        references: promptReferencesForSubmit(),
        speed: "fast",
        project_id: projectId || null,
        has_images: improveImages.length > 0,
        images: improveImages,
        ...getPromptAiKeyBodyFields(),
        ...getCadMcMasterPartsBodyFields(promptMode || "v2"),
      }),
    }, 120000);
    const improved = String(data?.improved_prompt || "").trim();
    if (!improved) {
      setXrStatus("AI did not return a prompt — try again");
      return { ok: false, error: "No improved prompt" };
    }
    try { composer?.setPromptText?.(improved); } catch (_) { }
    setXrStatus("Prompt placed — keep talking or Run to generate");
    try { viewportXR?.refreshAiPromptPanel?.(); } catch (_) { }
    return { ok: true, improved };
  } catch (err) {
    console.warn("[xr] talkXrComposeWithAi", err);
    const msg = err?.message || "Talk failed";
    setXrStatus(msg);
    return { ok: false, error: msg };
  }
}

function isXrVoiceDrawUi() {
  return !!(document.body.classList.contains("xr-presenting") || viewportXR?.isPresenting?.());
}

function syncVoiceDrawButton() {
  const btn = document.getElementById("btn-voice-draw");
  if (!btn) return;
  const xrOn = isXrVoiceDrawUi();
  const on = xrOn && !!viewportXR?.isVoiceDrawOn?.();
  btn.hidden = !xrOn;
  btn.setAttribute("aria-hidden", xrOn ? "false" : "true");
  btn.classList.toggle("is-active", on);
  btn.setAttribute("aria-pressed", on ? "true" : "false");
  btn.title = on
    ? "Drawing in 3D — drag on the model or in the viewport, talk, then Generate"
    : "Draw in 3D on the model while you talk, then Generate";
}

function getCanvasPromptGraph() {
  const state = canvasModeInstance?.exportState?.();
  return canvasModeInstance?.getPromptGraph?.() || canvasPromptGraph(state?.elements || [], {
    boardName: canvasModeInstance?.getTitle?.() || canvasStoreName || "Canvas",
    description: state?.description || "",
  });
}

function attachCanvasGoalMetadata({
  elements = [],
  boardName = canvasStoreName || "Canvas",
  description = "",
} = {}) {
  const payload = buildCanvasGoalMetadata({ elements, boardName, description });
  const filename = `references/Canvas/${boardName}/canvas-metadata.json`;
  const ref = {
    id: `document:${projectId || "project"}:${filename}`,
    type: "document",
    token: "@canvas-metadata",
    label: "canvas-metadata.json",
    filename,
    stem: "canvas-metadata",
    format: "json",
    text_content: JSON.stringify(payload, null, 2).slice(0, 100000),
    projectId,
  };
  composer.removeReference?.(ref.id);
  composer.addReference(ref, { insertMention: false });
  return ref;
}

function canvasElementsForPrompt(extra = null) {
  const state = canvasModeInstance?.exportState?.() || {};
  if (Array.isArray(state.elements) && state.elements.length) return state.elements;
  if (Array.isArray(extra) && extra.length) return extra;
  return canvasMetadataForImprove()?.elements || [];
}

function attachCanvasSketchImage(dataUrl, target = "design", metadata = null, sourceName = canvasStoreName) {
  if (!dataUrl) return false;
  const entry = {
    id: `canvas-${Date.now()}`,
    name: `canvas-sketch-${sourceName}.jpg`.slice(0, 160),
    media_type: "image/jpeg",
    data_url: dataUrl,
    role: "canvas",
    source_filename: `references/Canvas/${sourceName}/canvas.json`,
    drawing_metadata: metadata || canvasModeInstance.getDrawingMetadata?.(),
  };
  if (target === "wiring") {
    wiringPromptImages = mergeCanvasPromptImages(wiringPromptImages, entry, { limit: 4 });
    renderWiringPromptImages();
    return true;
  }
  promptImages = mergeCanvasPromptImages(promptImages, entry, { limit: 8 });
  queuePromptImagePersist(entry);
  renderPromptImages();
  if (!restoringModelPromptState) saveActiveModelPromptState();
  return true;
}

const CANVAS_SKETCH_PROMPT_SEED = "Model from this canvas layout drawing.";

const CANVAS_IMPROVE_DIRECTIVE = [
  "REWRITE INSTRUCTIONS (do not copy this block into improved_prompt):",
  "The attached canvas is a layout drawing that explains the user's intent — not a photo of the finished part and not DXF.",
  "Read the hand drawings (pen strokes), typed and handwritten text, arrows, boxes, tags, numbered dotted image links (#1, #2, …) with their relationship captions, and any board description.",
  "Treat arrows and boxes as callouts / edit regions / spatial direction, not as extra box solids.",
  "Numbered dotted links connect images or nodes; encode each relationship in CAD language (same part from another view, exploded of, mates to, cutaway of, before/after, etc.).",
  "Numbered faces, edges, views, and splits of interest (#1, #2, …) are the regions to edit. Each has its own instruction. Extrude arrows grow material in that view direction; inverse/cut arrows remove material; split marks split the face or part. Do not treat a dotted face box as a new box solid.",
  "LOGIC CHECK: compare the user's original prompt to the drawings. Keep their intent. If the original is vague, incomplete, or contradicts the drawings, change it so the drawings are explained well enough to model. If it already matches, keep that intent and add missing layout/mate language.",
  "Write a concrete CAD prompt the generator can model. Do not mention layout drawings, DXF, or that you rewrote the prompt.",
  "Read the attached canvas-metadata.json document to connect @image references, numbered links, faces of interest, and the modeling goal.",
].join("\n");

function promptHasCanvasSketchImage() {
  return (promptImages || []).some(isCanvasReference);
}

function currentGenerateUsedCanvas({ canvasAttached = false } = {}) {
  if (canvasAttached) return true;
  if (promptHasCanvasSketchImage()) return true;
  const refs = composer.getReferences?.() || [];
  if (refs.some((ref) => canvasBoardReference(ref) || isCanvasReference(ref))) return true;
  if (document.body.classList.contains("canvas-design-tab") && canvasModeInstance?.hasDrawing?.()) return true;
  return generationUsedCanvas({
    images: promptImages,
    prompt: composer.getPromptText?.() || "",
  });
}

function canvasTaggedContextPrompt() {
  const drawings = promptImages.filter(isCanvasReference).map((img) => img.drawing_metadata).filter(Boolean);
  if (!drawings.length) return "";
  return "Canvas drawing metadata (pixels, not mm):\n" + JSON.stringify(drawings);
}

function canvasMetadataForImprove() {
  return canvasModeInstance?.getDrawingMetadata?.()
    || (promptImages || []).find(isCanvasReference)?.drawing_metadata
    || null;
}

function augmentPromptForCanvasSketch(prompt) {
  const text = String(prompt || "").trim() || CANVAS_SKETCH_PROMPT_SEED;
  if (/REWRITE INSTRUCTIONS \(do not copy this block/i.test(text)) return text;
  const notes = formatCanvasLayoutNotes(canvasMetadataForImprove() || {});
  return `${text}\n\n${CANVAS_IMPROVE_DIRECTIVE}${notes ? `\n\nCanvas notes:\n${notes}` : ""}`;
}

function enableSpiceForCanvasSketch() {
  if (!isSpiceEnabled()) setSpiceEnabled(true);
  syncSpiceTipForPromptMode();
}

async function applyCanvasSketchToPrompt({ showFeedback = false } = {}) {
  if (!document.body.classList.contains("canvas-design-tab")) {
    const prompt = composer.getPromptText?.() || "";
    const refs = composer.getReferences?.() || [];
    const explicit = refs.find((ref) => canvasBoardReference(ref));
    if (!explicit && (promptHasCanvasSketchImage() || !/\b(canvas|drawing|drew|sketch|top view|front view|side view)\b/i.test(prompt))) return false;
    const pid = explicit?.projectId || projectId;
    if (!pid) return false;
    let name = canvasBoardReference(explicit)?.name;
    if (!name) {
      const data = await api(`/api/projects/${pid}/canvas-boards`);
      const boards = data?.boards || [];
      const named = boards.find((b) => b.name && prompt.toLowerCase().includes(b.name.toLowerCase()));
      const current = boards.find((b) => b.name === canvasStoreName);
      name = (named || current || boards.sort((a, b) => (b.mtime || 0) - (a.mtime || 0))[0])?.name;
    }
    if (!name) return false;
    const board = await api(`/api/projects/${pid}/canvas-board?name=${encodeURIComponent(name)}`);
    if (!board?.state?.elements?.length) return false;
    const snap = await renderCanvasBoardSnapshot(board.state, { fetchFile: (url) => rawFetch(url) });
    if (!attachCanvasSketchImage(snap.data_url, "design", snap.drawing_metadata, name)) return false;
    attachCanvasGoalMetadata({
      elements: board.state.elements,
      boardName: name,
      description: board.state.description || "",
    });
    return true;
  }
  canvasModeInstance.stopVoice?.();
  if (!canvasModeInstance.hasDrawing?.()) {
    if (showFeedback) {
      const status = document.getElementById("prompt-status");
      if (status) {
        status.className = "status error";
        status.textContent = "Draw something on the canvas first.";
      }
    }
    return false;
  }
  const snapshot = await canvasModeInstance.getPromptSnapshot();
  if (!snapshot.data_url || !attachCanvasSketchImage(snapshot.data_url, "design", snapshot.drawing_metadata)) return false;
  const state = canvasModeInstance.exportState?.() || {};
  attachCanvasGoalMetadata({
    elements: canvasElementsForPrompt(state.elements),
    boardName: canvasModeInstance.getTitle?.() || canvasStoreName || "Canvas",
    description: state.description || canvasModeInstance.getDescription?.() || "",
  });
  if (showFeedback) enableSpiceForCanvasSketch();
  else if (promptHasCanvasSketchImage()) syncSpiceTipForPromptMode();
  showAiComposePanel({ focus: false });
  promptImageList?.scrollIntoView?.({ block: "nearest", behavior: "smooth" });
  if (showFeedback) {
    const status = document.getElementById("prompt-status");
    if (status) {
      status.className = "status ok";
      status.textContent = "Canvas and metadata attached. Smart description will write the prompt.";
    }
  }
  return true;
}

function handleCanvasSendRegion(el, { elements = [], boardName = canvasStoreName || "Canvas", description = "" } = {}) {
  if (!el) return false;
  const phrase = canvasPromptMentionPhrase(el);
  const token = el.promptToken;
  const text = composer.getRawPromptText?.() || composer.getPromptText?.() || "";
  if (token && phrase && !String(text).includes(token)) {
    try {
      composer.setPromptText?.(insertMentionWithTrailingSpace(text, phrase).value);
    } catch (_) { }
  }
  const ref = canvasRegionPromptReference(el, {
    projectId,
    boardName: boardName || canvasModeInstance?.getTitle?.() || canvasStoreName || "Canvas",
    elements,
  });
  if (ref) {
    composer.removeReference?.(ref.id);
    composer.addReference(ref, { insertMention: false });
  }
  attachCanvasGoalMetadata({
    elements: elements.length ? elements : canvasElementsForPrompt(),
    boardName: boardName || canvasModeInstance?.getTitle?.() || canvasStoreName || "Canvas",
    description,
  });
  showAiComposePanel({ focus: true });
  const status = document.getElementById("prompt-status");
  if (status) {
    status.className = "status ok";
    status.textContent = `Linked ${phrase} in the prompt.`;
  }
  try { saveActiveModelPromptState(); } catch (_) { }
  void applyCanvasSketchToPrompt({ showFeedback: false }).catch(() => { });
  return true;
}

function canvasSmartDescriptionRef(el, boardName) {
  const name = String(el?.imageName || el?.tag || "").trim()
    || String(el?.sourceFilename || el?.id || "image").split(/[\\/]/).pop().replace(/\.[^.]+$/, "")
    || "image";
  const token = el?.promptToken || canvasPromptMentionToken(name);
  const filename = String(el.sourceFilename || `${name}.png`).split(/[\\/]/).pop();
  return {
    id: `canvas-image:${projectId || "project"}:${el.id}`,
    type: "image",
    token,
    label: name,
    filename,
    stem: name,
    projectId,
    canvas_element_id: el.id,
    canvas_board: boardName,
    data_url: el.dataUrl || "",
    source_filename: `references/Canvas/${boardName}/${filename}`,
    final_example: isCanvasFinalExample(el) || undefined,
  };
}

function attachCanvasSmartDescriptionAssets(elements = [], boardName = "Canvas") {
  const images = collectSmartDescriptionImages(elements);
  const ordered = [
    ...images.filter((el) => isCanvasFinalExample(el)),
    ...images.filter((el) => !isCanvasFinalExample(el)),
  ];
  const refs = [];
  for (const el of ordered) {
    refs.push(canvasSmartDescriptionRef(el, boardName));
    const dataUrl = el.dataUrl;
    if (!dataUrl) continue;
    const id = `canvas-img-${el.id}`;
    if (promptImages.some((img) => img.id === id || img.canvas_element_id === el.id)) continue;
    if (promptImages.length >= 8) continue;
    const name = refs.at(-1).label;
    const entry = {
      id,
      name: `${name}.jpg`.slice(0, 160),
      media_type: "image/jpeg",
      data_url: dataUrl,
      role: isCanvasFinalExample(el) ? "final-example" : "canvas-image",
      canvas_element_id: el.id,
      source_filename: `references/Canvas/${boardName}/${name}.jpg`,
    };
    promptImages.push(entry);
    queuePromptImagePersist(entry);
  }
  if (refs.length) composer.addReferences?.(refs, { insertMention: false });
  renderPromptImages();
  return refs;
}

function hideCanvasSmartDescModal() {
  document.getElementById("canvas-smart-desc-modal")?.classList.add("hidden");
}

function openCanvasSmartDescModal(items = []) {
  return new Promise((resolve) => {
    const modal = document.getElementById("canvas-smart-desc-modal");
    const list = document.getElementById("canvas-smart-desc-questions");
    if (!modal || !list) {
      resolve(null);
      return;
    }
    list.innerHTML = items.length
      ? items.map((item) => {
        const tags = (item.tokens || []).join(" ");
        const rel = item.relation ? ` <em>${appEscapeHtml(item.relation)}</em>` : "";
        return `<label class="canvas-smart-desc-q">
          <span>What should ${appEscapeHtml(tags || item.linkName || "this link")} do?${rel}</span>
          <textarea data-smart-link="${appEscapeHtml(item.id)}" rows="2" placeholder="Answer using the @/# tags">${appEscapeHtml(item.relation || "")}</textarea>
        </label>`;
      }).join("")
      : `<p class="muted small">No named links yet. Shift-select objects and right-click Link, or draw a dotted link.</p>`;
    const edit = modal.querySelector("[name=canvas-smart-target][value=edit]");
    const create = modal.querySelector("[name=canvas-smart-target][value=new]");
    if (create) create.checked = true;
    if (edit) edit.checked = false;
    modal.classList.remove("hidden");
    modal._finishSmartDesc = (value) => {
      hideCanvasSmartDescModal();
      modal._finishSmartDesc = null;
      resolve(value);
    };
  });
}

function bindCanvasSmartDescModal() {
  const modal = document.getElementById("canvas-smart-desc-modal");
  if (!modal || modal.dataset.bound === "1") return;
  modal.dataset.bound = "1";
  document.getElementById("canvas-smart-desc-fill")?.addEventListener("click", () => {
    const answers = {};
    modal.querySelectorAll("[data-smart-link]").forEach((el) => {
      answers[el.getAttribute("data-smart-link")] = el.value;
    });
    answers.editCurrent = modal.querySelector("[name=canvas-smart-target]:checked")?.value || "new";
    modal._finishSmartDesc?.(answers);
  });
  modal.querySelectorAll("[data-canvas-smart-close]").forEach((btn) => {
    btn.addEventListener("click", () => modal._finishSmartDesc?.(null));
  });
}

async function handleCanvasSmartDescribe() {
  const status = document.getElementById("prompt-status");
  bindCanvasSmartDescModal();
  try {
    const state = canvasModeInstance?.exportState?.() || {};
    const elements = state.elements || [];
    const boardName = canvasModeInstance?.getTitle?.() || canvasStoreName || "Canvas";
    const original = String(composer.getPromptText?.() || "").trim();
    if (!collectSmartDescriptionImages(elements).length && !canvasModeInstance?.hasDrawing?.() && !collectCanvasInterviewItems(elements).length) {
      if (status) {
        status.className = "status error";
        status.textContent = "Draw something on the canvas first.";
      }
      return { ok: false, generated: false };
    }
    attachCanvasSmartDescriptionAssets(elements, boardName);
    await applyCanvasSketchToPrompt({ showFeedback: false });
    enableSpiceForCanvasSketch();
    showAiComposePanel({ focus: false });
    const answers = await openCanvasSmartDescModal(collectCanvasInterviewItems(elements));
    if (!answers) return { ok: false, generated: false };
    if (answers.editCurrent === "edit") {
      const selected = objectTools?.getSelection?.();
      if (!selected?.catalogName && !selected?.root && !selected?.mesh && status) {
        status.className = "status ok";
        status.textContent = "Select the current model to edit, then Generate when ready.";
      }
    }
    const filled = mergeSmartDescriptionPrompt(
      original,
      composeSmartDescriptionInterview({
        originalPrompt: original,
        elements,
        boardName,
        description: state.description || canvasModeInstance?.getDescription?.() || "",
        answers,
      }),
      elements,
      boardName,
    );
    if (!filled) {
      if (status) {
        status.className = "status error";
        status.textContent = "Could not organize this canvas. Add linked photos or a final example, then try again.";
      }
      return { ok: false, generated: false };
    }
    const notes = formatCanvasLayoutNotes(canvasMetadataForImprove() || canvasPromptGraph(elements, { boardName }) || {});
    canvasModeInstance.setDescription?.(notes || filled.slice(0, 600));
    attachCanvasSmartDescriptionAssets(elements, boardName);
    attachCanvasGoalMetadata({
      elements,
      boardName,
      description: state.description || canvasModeInstance?.getDescription?.() || "",
    });
    try { composer.setPromptText?.(filled); } catch (_) { }
    try { saveActiveModelPromptState(); } catch (_) { }
    if (status && answers.editCurrent !== "edit") {
      status.className = "status ok";
      status.textContent = "Prompt organized from the canvas — review or edit it, then Generate when ready.";
    }
    return { ok: true, generated: false, prompt: filled };
  } catch (err) {
    if (status) {
      status.className = "status error";
      status.textContent = err?.message || "Smart description failed.";
    }
    throw err;
  }
}

async function handleCanvasShare({ action, shareMode, share } = {}) {
  if (!projectId) await ensureProjectForUpload();
  if (!projectId) throw new Error("Save this canvas to a project first.");
  await persistCanvasBoard({ force: true, refreshList: false });
  const name = canvasStoreName || "Canvas";
  const filename = `references/Canvas/${name}/canvas.json`;
  const mode = shareMode === "edit" ? "edit" : shareMode === "remix" ? "remix" : "view";
  if (action === "set-mode") {
    writeShareDefaultMode(mode);
    if (share?.token) {
      const data = await patchShareSettings(share.token, { share_mode: mode });
      return { ...share, ...data, share_mode: data.share_mode || mode };
    }
    return { ...(share || {}), share_mode: mode };
  }
  const authKind = action === "share-discord" ? "share-discord" : "copy-share";
  if (requireStudioAuth({
    kind: authKind,
    projectId,
    filename,
    shareContext: currentVisibleShareContext,
  })) return { cancelled: true };
  let record = share;
  if (!record?.token || !record?.share_url) {
    let viewportImage = "";
    try {
      const snapshot = await canvasModeInstance.getPromptSnapshot?.();
      viewportImage = snapshot?.data_url || "";
    } catch {
      viewportImage = "";
    }
    record = await createShareRecord(projectId, filename, {
      viewport_image: viewportImage,
      visible_filenames: [filename],
      force_new: true,
    }, { share_mode: mode });
  }
  if (action === "copy-link") {
    const url = record.share_url;
    try {
      await navigator.clipboard.writeText(url);
    } catch {
      window.prompt("Copy this share link:", url);
    }
    setEditStatus("ok", "Share link copied.");
  }
  if (action === "share-discord") {
    await shareToDiscord(record.share_url, { title: name });
    setEditStatus("ok", "Message copied — Discord is open. Paste in a channel.");
  }
  return record;
}

async function handleCanvasInvite({ action, kind, query, userId, email, teamId, shareMode } = {}) {
  if (!projectId) await ensureProjectForUpload();
  if (!projectId) throw new Error("Save this canvas to a project first.");
  const mode = shareMode === "edit" ? "edit" : shareMode === "remix" ? "remix" : "view";
  if (action === "search") {
    return api(`/api/projects/${projectId}/canvas-invite/search?q=${encodeURIComponent(query || "")}`);
  }
  if (action === "remix") {
    const name = canvasStoreName || "Canvas";
    const data = await api(`/api/projects/${projectId}/canvas-board/remix`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    if (data?.url) window.location.assign(data.url);
    return data;
  }
  if (action === "invite") {
    return api(`/api/projects/${projectId}/canvas-invite`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        kind: kind || "user",
        user_id: userId || undefined,
        email: email || undefined,
        team_id: teamId || undefined,
        share_mode: mode,
        board_name: canvasStoreName || "Canvas",
      }),
    });
  }
  return null;
}

function handleCanvasAuthorAction({ action, userId, displayName } = {}) {
  const uid = String(userId || "").trim();
  if (!uid) return;
  if (action === "profile") {
    try { userProfileUi?.open?.({ userId: uid, compact: true }); } catch { /* optional */ }
    return;
  }
  if (action === "add") {
    void api("/api/social/friends", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ user_id: uid }),
    }).then(() => setEditStatus("ok", "Added as a friend.")).catch((err) => {
      setEditStatus("error", err?.message || "Could not add friend.");
    });
    return;
  }
  if (action === "dm") {
    try { userProfileUi?.open?.({ userId: uid }); } catch { /* optional */ }
    try {
      projectChat?.prefillMention?.({
        id: uid,
        display_name: displayName || "user",
        type: "user",
      });
    } catch { /* optional */ }
  }
}

let lastInterestCardStructure = "";

function canvasInterestPlaceholder(kind) {
  if (kind === "view") return "e.g. side view pointing out — this is the camera for this drawing";
  if (kind === "edge") return "e.g. round this edge and blend it into the mount";
  if (kind === "split") return "e.g. split this region off as its own body";
  return "e.g. I want this to go outside and round the corners, or go out 45 mm and curve to fit a Meta Quest headset";
}

function canvasInterestCardsFromMetadata() {
  const meta = canvasMetadataForImprove() || {};
  const source = Array.isArray(meta.interests) && meta.interests.length
    ? meta.interests
    : collectCanvasInterests(meta.elements || []);
  return source.map((el) => ({
    id: el.id,
    kind: el.interestKind || el.kind || "",
    number: Number(el.interestNumber || el.number) || 0,
    viewName: String(el.viewName || ""),
    action: String(el.action || ""),
    direction: String(el.direction || ""),
    tag: String(el.tag || ""),
    interestPrompt: String(el.interestPrompt || ""),
    title: canvasInterestTitle(el),
  }));
}

function updateCanvasInterestPrompt(id, text) {
  if (canvasModeInstance?.updateInterestPrompt?.(id, text)) return;
  for (const img of promptImages || []) {
    const meta = img.drawing_metadata;
    if (!meta) continue;
    const nodes = [...(meta.elements || []), ...(meta.interests || [])];
    let hit = false;
    for (const node of nodes) {
      if (node?.id !== id) continue;
      node.interestPrompt = String(text || "");
      hit = true;
    }
    if (hit) return;
  }
}

function renderCanvasInterestCards() {
  const list = document.getElementById("canvas-interest-list");
  if (!list) return;
  const interests = (canvasModeInstance?.getInterests?.() || []).length
    ? canvasModeInstance.getInterests()
    : canvasInterestCardsFromMetadata();
  list.classList.toggle("hidden", !interests.length);
  if (!interests.length) {
    lastInterestCardStructure = "";
    list.innerHTML = "";
    return;
  }
  const structure = interests.map((row) => `${row.id}:${row.kind}:${row.number}:${row.action}:${row.direction}:${row.viewName}:${row.tag}:${row.title}`).join("|");
  if (structure !== lastInterestCardStructure) {
    lastInterestCardStructure = structure;
    const dirIcon = { up: "↑", down: "↓", left: "←", right: "→" };
    const actionIcon = { extrude: "↗", cut: "↙", split: "✂" };
    list.innerHTML = interests.map((row) => {
      const metaBits = [row.viewName, row.action && `${actionIcon[row.action] || ""} ${row.action}`.trim(), row.direction && `${dirIcon[row.direction] || ""} ${row.direction}`.trim()]
        .filter(Boolean)
        .join(" · ");
      return `<div class="prompt-interest-card" data-interest-id="${appEscapeHtml(row.id)}">
        <div class="prompt-interest-head">
          <span class="prompt-interest-num">#${row.number || ""}</span>
          <strong class="prompt-interest-title">${appEscapeHtml(row.title)}</strong>
          ${metaBits ? `<span class="prompt-interest-meta">${appEscapeHtml(metaBits)}</span>` : ""}
        </div>
        <textarea class="prompt-interest-prompt" data-interest-prompt data-interest-id="${appEscapeHtml(row.id)}" rows="2" placeholder="${appEscapeHtml(canvasInterestPlaceholder(row.kind))}">${appEscapeHtml(row.interestPrompt)}</textarea>
      </div>`;
    }).join("");
    list.querySelectorAll("[data-interest-prompt]").forEach((ta) => {
      ta.addEventListener("input", () => {
        updateCanvasInterestPrompt(ta.getAttribute("data-interest-id"), ta.value);
      });
    });
  } else {
    list.querySelectorAll("[data-interest-prompt]").forEach((ta) => {
      if (document.activeElement === ta) return;
      const row = interests.find((item) => item.id === ta.getAttribute("data-interest-id"));
      if (row && ta.value !== row.interestPrompt) ta.value = row.interestPrompt;
    });
  }
}

