// Drop a CAD component from the browser onto the Wiring AI prompt to reference it.
const wiringPromptInput = document.getElementById("wiring-prompt-input");
const wiringInlineRefs = document.getElementById("wiring-inline-ref-chips");
let wiringPromptRefs = [];

function getWiringPromptMentionables() {
  const items = [];
  const seenIds = new Set();
  const seenTokens = new Set();
  const pushItem = (item) => {
    if (!item?.id) return;
    if (seenIds.has(item.id)) return;
    let token = String(item.token || "").trim();
    if (!token) return;
    if (seenTokens.has(token)) {
      let n = 2;
      while (seenTokens.has(`${token}-${n}`)) n += 1;
      token = `${token}-${n}`;
      item = { ...item, token };
      if (item.ref) item.ref = { ...item.ref, token };
    }
    seenIds.add(item.id);
    seenTokens.add(token);
    items.push({ ...item, token });
  };
  for (const part of listWiringProjectParts({ includeHidden: true })) {
    const token = compactComponentToken(part.stem || part.label || part.filename);
    const ref = normalizeWiringPromptRef({
      id: `component:${part.filename}`,
      type: "component",
      token,
      label: part.label,
      stem: part.stem,
      filename: part.filename,
      kind: part.kind || "",
    });
    pushItem({
      id: ref.id,
      token: ref.token,
      label: ref.label,
      detail: [part.kind, part.sourced ? "sourced" : "", part.filename].filter(Boolean).join(" · "),
      type: "component",
      filename: part.filename,
      stem: part.stem,
      ref,
    });
  }
  const browser = lastProjectBrowser || {};
  for (const entry of flattenBrowserEntries(browser.references)) {
    const filename = String(entry.filename || entry.viewer_filename || entry.name || "").trim();
    if (!filename || isInternalCadSidecar(filename)) continue;
    const type = mentionTypeForFilename(filename, "document");
    const stem = entry.stem || fileStem(filename);
    const token = compactComponentToken(stem || filename);
    const ref = {
      id: `${type}:${filename}`,
      type,
      token,
      label: entry.label || stem || filename,
      filename,
      stem,
    };
    pushItem({
      id: ref.id,
      token,
      label: ref.label,
      detail: "reference file",
      type,
      filename,
      stem,
      ref,
    });
  }
  for (const file of lastProjectFiles || []) {
    const name = String(file?.name || "");
    if (!name || isInternalCadSidecar(name)) continue;
    if (!isReferenceFilename(name) && !isDxfDrawingFilename(name)) continue;
    const type = mentionTypeForFilename(name, "document");
    const stem = fileStem(name);
    const token = compactComponentToken(stem);
    const ref = { id: `${type}:${name}`, type, token, label: stem, filename: name, stem };
    pushItem({
      id: ref.id,
      token,
      label: stem,
      detail: "reference file",
      type,
      filename: name,
      stem,
      ref,
    });
  }
  for (const ref of wiringPromptRefs) {
    if (ref.type === "wire" || ref.type === "wiring" || ref.type === "url" || ref.type === "link" || ref.type === "document") {
      pushItem({
        id: ref.id,
        token: ref.token,
        label: ref.label,
        detail: ref.type === "url" || ref.type === "link" ? (ref.url || "link") : "selected wire",
        type: ref.type,
        url: ref.url,
        ref,
      });
    }
  }
  return items;
}

function listWiringBrowserFileRefs() {
  const refs = [];
  const seen = new Set();
  const pushEntry = (entry) => {
    const filename = String(entry?.filename || entry?.viewer_filename || entry?.name || "").trim();
    if (!filename || isInternalCadSidecar(filename)) return;
    if (/\.(png|jpe?g|webp|gif|bmp|svg|tiff?|webm|mp4|mov|m4v)$/i.test(filename)) return;
    if (seen.has(filename)) return;
    seen.add(filename);
    const type = mentionTypeForFilename(filename, "document");
    const stem = entry.stem || fileStem(filename);
    const token = compactComponentToken(stem || filename);
    const ref = normalizeWiringPromptRef({
      id: `${type}:${filename}`,
      type,
      token,
      label: entry.label || stem || filename,
      filename,
      stem,
    });
    if (ref) refs.push(ref);
  };
  for (const entry of flattenBrowserEntries((lastProjectBrowser || {}).references)) {
    pushEntry(entry);
  }
  for (const file of lastProjectFiles || []) {
    const name = String(file?.name || "");
    if (!name || isInternalCadSidecar(name)) continue;
    if (!isReferenceFilename(name)) continue;
    pushEntry({ name, filename: name, stem: fileStem(name), label: fileStem(name) });
  }
  return refs;
}

function attachWiringBrowserReferenceFiles({ insertMention = false } = {}) {
  if (newProjectPending || !projectId) return 0;
  const files = listWiringBrowserFileRefs();
  if (!files.length) return 0;
  let added = 0;
  if (wiringComposer?.addReference) {
    const existing = new Set((wiringComposer.getReferences() || []).map((r) => r.id));
    for (const ref of files) {
      if (!ref?.id || existing.has(ref.id)) continue;
      wiringComposer.addReference(ref, { insertMention });
      existing.add(ref.id);
      added += 1;
    }
    wiringPromptRefs = wiringComposer.getReferences().map(normalizeWiringPromptRef).filter(Boolean);
  } else {
    const existing = new Set((wiringPromptRefs || []).map((r) => r.id));
    for (const ref of files) {
      if (!ref?.id || existing.has(ref.id)) continue;
      wiringPromptRefs.push(ref);
      existing.add(ref.id);
      added += 1;
    }
  }
  if (added) renderWiringPromptRefs();
  return added;
}

function wiringPromptRefsForRequest() {
  const current = (wiringPromptRefs || []).map(normalizeWiringPromptRef).filter(Boolean);
  const seen = new Set(current.map((r) => r.id));
  const merged = [...current];
  for (const ref of listWiringBrowserFileRefs()) {
    if (!ref?.id || seen.has(ref.id)) continue;
    seen.add(ref.id);
    merged.push(ref);
  }
  return merged.slice(0, 48);
}

