const PROMPT_URL_CHIP_RE = /https?:\/\/[^\s<>\]\)\"']+/gi;

let wiringComposeLinks = [];
let restoringWiringComposeDraft = false;

function normalizeWiringLinkUrl(raw = "") {
  try {
    const u = new URL(String(raw || "").trim());
    if (!/^https?:$/i.test(u.protocol)) return "";
    u.hash = "";
    for (const key of ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content"]) {
      u.searchParams.delete(key);
    }
    let href = u.href;
    if (href.endsWith("/") && u.pathname !== "/") href = href.replace(/\/$/, "");
    return href;
  } catch {
    return "";
  }
}

const wiringComposeLinkTitles = new Map();

function clipWiringLinkTitle(title = "", maxWords = 5) {
  const words = String(title || "").replace(/\s+/g, " ").trim().split(" ").filter(Boolean);
  if (!words.length) return "";
  return words.slice(0, maxWords).join(" ");
}

function amazonAsinFromWiringUrl(url = "") {
  try {
    const u = new URL(url);
    const host = String(u.hostname || "");
    if (!/(^|\.)amazon\.[a-z.]+$/i.test(host)) return "";
    const pathMatch = String(u.pathname || "").match(/\/(?:dp|gp\/product|gp\/aw\/d)\/([A-Z0-9]{10})/i)
      || String(u.pathname || "").match(/\/([A-Z0-9]{10})(?:[/?]|$)/i);
    if (pathMatch) return pathMatch[1].toUpperCase();
    const asin = u.searchParams.get("asin") || u.searchParams.get("ASIN");
    if (asin && /^[A-Z0-9]{10}$/i.test(asin)) return asin.toUpperCase();
  } catch { /* ignore */ }
  return "";
}

function wiringLinkHostBrand(url = "") {
  try {
    const host = new URL(url).hostname.replace(/^www\./i, "").toLowerCase();
    if (host.includes("amazon.")) return "Amazon";
    if (host.includes("digikey.")) return "Digi-Key";
    if (host.includes("mouser.")) return "Mouser";
    if (host.includes("adafruit.")) return "Adafruit";
    if (host.includes("sparkfun.")) return "SparkFun";
    if (host.includes("mcmaster.")) return "McMaster";
    if (host.includes("pololu.")) return "Pololu";
    if (host.includes("ti.com")) return "Texas Instruments";
    const root = host.split(".")[0] || "Link";
    return root.charAt(0).toUpperCase() + root.slice(1);
  } catch {
    return "Link";
  }
}

function wiringLinkFavicon(url = "") {
  try {
    const host = new URL(url).hostname;
    return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(host)}&sz=32`;
  } catch {
    return "";
  }
}

function wiringLinkTitleFromDocs(url = "") {
  const norm = normalizeWiringLinkUrl(url);
  if (!norm) return "";
  const cached = wiringComposeLinkTitles.get(norm);
  if (cached) return clipWiringLinkTitle(cached);
  const items = [
    ...(latestElectronicsBundle?.suggestions || []),
    ...(latestElectronicsBundle?.used?.cad || []),
    ...(latestElectronicsBundle?.used?.wiring || []),
  ];
  for (const item of items) {
    if (!item || item.kind === "send-all-cad") continue;
    const hits = typeof electronicsSourcingUrls === "function" ? electronicsSourcingUrls(item) : [];
    if (hits.some((entry) => normalizeWiringLinkUrl(entry.url) === norm)) {
      return clipWiringLinkTitle(item.label || item.title || item.name || "");
    }
  }
  for (const ref of wiringPromptRefs || []) {
    if (normalizeWiringLinkUrl(ref.url || (ref.type === "url" ? ref.filename : "")) !== norm) continue;
    const label = String(ref.label || ref.description || "").trim();
    if (label && !label.includes("/") && !/^https?:/i.test(label)) return clipWiringLinkTitle(label);
  }
  return "";
}

function wiringLinkLabel(url = "") {
  const fromDocs = wiringLinkTitleFromDocs(url);
  if (fromDocs) return fromDocs;
  const asin = amazonAsinFromWiringUrl(url);
  if (asin) return `Amazon ${asin}`;
  const brand = wiringLinkHostBrand(url);
  try {
    const leaf = (new URL(url).pathname.split("/").filter(Boolean).pop() || "")
      .replace(/\.[a-z0-9]{2,8}$/i, "")
      .replace(/[-_]+/g, " ")
      .trim();
    if (leaf && !/^B0[A-Z0-9]{8}$/i.test(leaf)) return clipWiringLinkTitle(`${brand} ${leaf}`);
    return brand;
  } catch {
    return brand;
  }
}

function wiringLinkFilename(url = "") {
  let host = "link";
  try {
    host = new URL(url).hostname.replace(/^www\./i, "").replace(/[^a-z0-9.-]+/gi, "-") || "link";
  } catch { /* keep default */ }
  const digest = Math.abs([...url].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) | 0, 0)).toString(36);
  return `wiring-link-${host}-${digest}.md`;
}

function wiringLinkRef(url, label = "") {
  const norm = normalizeWiringLinkUrl(url);
  if (!norm) return null;
  const host = wiringLinkLabel(norm);
  return normalizeWiringPromptRef({
    id: `url:${norm}`,
    type: "url",
    token: compactComponentToken(host),
    label: label || host,
    url: norm,
    filename: norm,
    stem: host,
  });
}

function existingWiringLinkUrls() {
  const seen = new Set();
  const add = (raw) => {
    const url = normalizeWiringLinkUrl(raw);
    if (url) seen.add(url);
  };
  for (const url of wiringComposeLinks) add(url);
  for (const ref of wiringPromptRefs || []) {
    add(ref.url);
    if (ref.type === "url" || ref.type === "link") add(ref.filename);
  }
  for (const entry of flattenBrowserEntries(lastProjectBrowser?.references)) {
    add(entry.url);
    add(entry.source_url);
    add(entry.href);
    const name = String(entry.name || entry.filename || "");
    if (/wiring-link-/i.test(name)) {
      for (const extracted of extractPromptUrls(String(entry.description || entry.note || ""), 4)) add(extracted);
    }
  }
  for (const file of lastProjectFiles || []) {
    const name = String(file?.name || "");
    if (/wiring-link-/i.test(name) || /Wiring links/i.test(name)) {
      add(file.url);
      add(file.source_url);
    }
  }
  return seen;
}

function projectHasWiringLinkFile(url) {
  const want = wiringLinkFilename(url);
  const hay = [
    ...(lastProjectFiles || []).map((f) => String(f?.name || "")),
    ...flattenBrowserEntries(lastProjectBrowser?.references).map((e) => String(e.name || e.filename || "")),
  ];
  return hay.some((name) => name.endsWith(want) || name.includes(`/Wiring links/${want}`));
}

function renderWiringComposeLinks() {
  const chips = document.getElementById("wiring-compose-links-chips");
  if (!chips) return;
  chips.hidden = wiringComposeLinks.length === 0;
  chips.innerHTML = wiringComposeLinks.map((url) => {
    const label = appEscapeHtml(wiringLinkLabel(url));
    const href = appEscapeHtml(url);
    const favicon = appEscapeHtml(wiringLinkFavicon(url));
    return `<span class="wiring-compose-link-chip" data-wiring-link="${href}" title="${href}">
      <a href="${href}" target="_blank" rel="noopener">${label}</a>
      ${favicon ? `<img class="wiring-compose-link-favicon" src="${favicon}" alt="" width="12" height="12" loading="lazy" referrerpolicy="no-referrer" />` : ""}
      <button type="button" data-wiring-link-remove="${href}" title="Remove link" aria-label="Remove link">×</button>
    </span>`;
  }).join("");
  chips.querySelectorAll("[data-wiring-link-remove]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const url = normalizeWiringLinkUrl(btn.getAttribute("data-wiring-link-remove"));
      wiringComposeLinks = wiringComposeLinks.filter((item) => item !== url);
      renderWiringComposeLinks();
      try { renderWiringPartsPickerList(); } catch (_) { /* optional */ }
      if (!restoringWiringComposeDraft && !wiringDraftSwitchLock) saveWiringComposeDraft();
    });
  });
}

function addWiringComposeLink(raw, { persist = false } = {}) {
  const extras = extractPromptUrls(String(raw || ""), 8);
  const candidates = extras.length ? extras : [raw];
  let added = 0;
  const existing = existingWiringLinkUrls();
  for (const candidate of candidates) {
    const url = normalizeWiringLinkUrl(candidate);
    if (!url || existing.has(url)) continue;
    existing.add(url);
    wiringComposeLinks.push(url);
    added += 1;
  }
  if (added) {
    renderWiringComposeLinks();
    try { renderWiringPartsPickerList(); } catch (_) { /* optional */ }
  }
  if (persist && added) void saveWiringComposeLinksToProjectParts(wiringComposeLinks);
  return added;
}

async function saveWiringComposeLinksToProjectParts(urls = wiringComposeLinks) {
  if (!projectId) return [];
  const saved = [];
  const existing = existingWiringLinkUrls();
  for (const raw of urls || []) {
    const url = normalizeWiringLinkUrl(raw);
    if (!url) continue;
    const alreadyListed = existing.has(url) && projectHasWiringLinkFile(url);
    if (alreadyListed) continue;
    existing.add(url);
    if (!wiringComposeLinks.includes(url)) wiringComposeLinks.push(url);
    const ref = wiringLinkRef(url);
    if (ref) addWiringPromptRef(ref, { insertMention: false });
    if (projectHasWiringLinkFile(url)) {
      saved.push(url);
      continue;
    }
    const file = new File([`# Wiring link\n\n${url}\n`], wiringLinkFilename(url), { type: "text/markdown" });
    try {
      await uploadReferenceProjectFile(file, {
        destination: "current",
        projectId,
        silent: true,
        referenceFolder: "Wiring links",
      });
      saved.push(url);
    } catch (err) {
      console.warn("[wiring] link save skipped", url, err);
    }
  }
  renderWiringComposeLinks();
  try { renderWiringPartsPickerList(); } catch (_) { /* optional */ }
  return saved;
}

function collectWiringComposeLinkUrls() {
  const input = document.getElementById("wiring-compose-links-input");
  if (input?.value) addWiringComposeLink(input.value, { persist: false });
  if (input) input.value = "";
  return [...wiringComposeLinks];
}

function readWiringComposeDrafts() {
  let raw;
  try {
    raw = JSON.parse(localStorage.getItem(LS_WIRING_COMPOSE_DRAFT) || "{}") || {};
  } catch {
    return {};
  }
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  const nested = Object.values(raw).some((value) => (
    value && typeof value === "object" && !Array.isArray(value)
    && ("prompt" in value || "links" in value)
  ));
  if (!nested && ("prompt" in raw || "links" in raw)) {
    const pid = String(raw.project_id || "").trim();
    return pid ? { [pid]: { ...raw, project_id: pid } } : {};
  }
  const map = {};
  for (const [key, value] of Object.entries(raw)) {
    if (!value || typeof value !== "object" || Array.isArray(value)) continue;
    if (!("prompt" in value) && !("links" in value)) continue;
    const pid = String(key || "").trim();
    if (!pid) continue;
    if (value.project_id && String(value.project_id) !== pid) continue;
    map[pid] = { ...value, project_id: pid };
  }
  return map;
}

function writeWiringComposeDrafts(map) {
  try {
    localStorage.setItem(LS_WIRING_COMPOSE_DRAFT, JSON.stringify(map));
  } catch (_) { /* quota / private mode */ }
}

function currentWiringComposeSnapshot() {
  const input = document.getElementById("wiring-prompt-input");
  const linksInput = document.getElementById("wiring-compose-links-input");
  const typedLink = normalizeWiringLinkUrl(linksInput?.value || "");
  const links = [...wiringComposeLinks];
  if (typedLink && !links.includes(typedLink)) links.push(typedLink);
  const titles = {};
  for (const url of links) {
    const title = wiringComposeLinkTitles.get(url);
    if (title) titles[url] = title;
  }
  return {
    prompt: wiringComposer?.getRawPromptText?.() || input?.value || "",
    links,
    titles,
    project_id: projectId || null,
    updated_at: Date.now(),
  };
}

function saveWiringComposeDraft({ forceEmpty = false, pid = projectId } = {}) {
  if (restoringWiringComposeDraft || promptDraftSwitchLock || wiringDraftSwitchLock) return;
  const key = String(pid || "").trim();
  if (!key) return;
  // Never write the visible box into another project's slot.
  if (projectId && String(projectId) !== key) return;
  const snapshot = currentWiringComposeSnapshot();
  snapshot.project_id = key;
  const map = readWiringComposeDrafts();
  if (!shouldPersistComposeSnapshot(snapshot, map[key], {
    forceEmpty,
    protectExisting: restoringWiringComposeDraft || wiringDraftSwitchLock,
  })) return;
  map[key] = snapshot;
  writeWiringComposeDrafts(map);
}

function storedWiringComposeDraft(pid = projectId) {
  const key = String(pid || "").trim();
  if (!key) return null;
  return readWiringComposeDrafts()[key] || null;
}

function restoreWiringComposeDraft(pid = projectId, { allowLiveFallback = false } = {}) {
  const key = String(pid || "").trim();
  const draft = key ? storedWiringComposeDraft(key) : null;
  const owned = draft && String(draft.project_id || key) === key ? draft : null;
  const stored = String(owned?.prompt || "");
  const live = allowLiveFallback
    ? (wiringComposer?.getRawPromptText?.() || document.getElementById("wiring-prompt-input")?.value || "")
    : "";
  const text = pickComposeRestorePrompt({ stored, live, allowLiveFallback });
  restoringWiringComposeDraft = true;
  try {
    if (wiringComposer) wiringComposer.setPromptText?.(text);
    else {
      const ta = document.getElementById("wiring-prompt-input");
      if (ta) ta.value = text;
    }
    wiringComposeLinks = [...new Set((owned?.links || []).map((url) => normalizeWiringLinkUrl(url)).filter(Boolean))];
    wiringComposeLinkTitles.clear();
    for (const [url, title] of Object.entries(owned?.titles || {})) {
      const norm = normalizeWiringLinkUrl(url);
      if (norm && title) wiringComposeLinkTitles.set(norm, String(title));
    }
    renderWiringComposeLinks();
    try { renderWiringPartsPickerList(); } catch (_) { /* optional */ }
  } finally {
    restoringWiringComposeDraft = false;
  }
}

function extractPromptUrls(text = "", limit = 4) {
  const seen = new Set();
  const urls = [];
  PROMPT_URL_CHIP_RE.lastIndex = 0;
  for (const match of String(text || "").matchAll(PROMPT_URL_CHIP_RE)) {
    let url = match[0].replace(/[),.;:!?]+$/g, "");
    if (!url || seen.has(url)) continue;
    seen.add(url);
    urls.push(url);
    if (urls.length >= limit) break;
  }
  return urls;
}

function promptUrlChipLabel(url = "") {
  try {
    const u = new URL(url);
    const path = u.pathname.length > 36 ? `${u.pathname.slice(0, 33)}…` : u.pathname;
    return `${u.hostname}${path === "/" ? "" : path}`;
  } catch {
    return String(url || "").slice(0, 64);
  }
}

function renderPromptUrlChips(chipsEl, text) {
  if (!chipsEl) return;
  const urls = extractPromptUrls(text);
  chipsEl.innerHTML = "";
  chipsEl.classList.toggle("hidden", !urls.length);
  for (const url of urls) {
    const a = document.createElement("a");
    a.className = "prompt-url-chip";
    a.href = url;
    a.target = "_blank";
    a.rel = "noopener noreferrer";
    a.title = url;
    a.innerHTML = `<span class="prompt-url-chip-label">${appEscapeHtml(promptUrlChipLabel(url))}</span><span class="prompt-url-chip-hint">${/\.pdf(\?|$)/i.test(url) ? "PDF" : "Link"}</span>`;
    chipsEl.appendChild(a);
  }
}

function bindPromptUrlChips(textarea, chipsEl) {
  if (!textarea || !chipsEl) return;
  const refresh = () => renderPromptUrlChips(chipsEl, textarea.value || "");
  textarea.addEventListener("input", refresh);
  textarea.addEventListener("change", refresh);
  textarea.addEventListener("paste", () => setTimeout(refresh, 0));
  refresh();
}

// Wiring uses Prompt 2.0 inline URL links inside the composer — keep external chips for rigging only.
document.getElementById("wiring-prompt-link-chips")?.classList.add("hidden");
bindPromptUrlChips(
  document.getElementById("rigging-prompt-input"),
  document.getElementById("rigging-prompt-link-chips"),
);

function normalizeWiringPromptRef(ref = {}) {
  if (!ref?.id) return null;
  const type = ref.type || (ref.filename ? "component" : "wire");
  const label = ref.label || ref.stem || ref.filename || ref.id;
  return {
    ...ref,
    type,
    label,
    token: ref.token || (type === "wire" || type === "wiring"
      ? `@wire-${String(ref.id).replace(/[^a-zA-Z0-9_-]+/g, "-")}`
      : compactComponentToken(label)),
    projectId: ref.projectId || projectId || null,
  };
}

function wiringPromptReferencesForReuse(entry = {}) {
  return (Array.isArray(entry.references) ? entry.references : [])
    .map(normalizeWiringPromptRef)
    .filter(Boolean);
}

function renderWiringPromptRefs() {
  // Inline chips are owned by wiringComposer (Prompt 2.0). Keep the parts picker in sync.
  if (!wiringComposer && wiringInlineRefs) {
    wiringInlineRefs.innerHTML = "";
    wiringInlineRefs.classList.toggle("hidden", wiringPromptRefs.length === 0);
    for (const ref of wiringPromptRefs) {
      const chip = document.createElement("span");
      chip.className = "ref-chip ref-chip--inline";
      chip.innerHTML = `<span class="ref-token">${appEscapeHtml(ref.token)}</span><span class="ref-coords">${appEscapeHtml(ref.label || ref.stem)}</span><button type="button" class="ref-remove" title="Remove">×</button>`;
      chip.querySelector(".ref-remove")?.addEventListener("click", (ev) => {
        ev.stopPropagation();
        wiringPromptRefs = wiringPromptRefs.filter((r) => r.id !== ref.id);
        renderWiringPromptRefs();
      });
      chip.addEventListener("click", (ev) => {
        if (ev.target.closest?.(".ref-remove")) return;
        ev.preventDefault();
        void copyPromptChipValue(ref).then((payload) => {
          if (!payload) return;
          const status = document.getElementById("wiring-prompt-status");
          if (status) {
            status.className = "status ok";
            status.textContent = copiedChipStatus(payload.kind);
          }
        });
      });
      wiringInlineRefs.appendChild(chip);
    }
  }
  renderWiringPartsPickerList();
}

function listWiringProjectParts({ includeHidden = false } = {}) {
  const entries = [];
  const seen = new Set();
  const push = (entry) => {
    if (!entry?.name || isFixtureArtifactFilename?.(entry.name)) return;
    if (!includeHidden && typeof isBrowserComponentHidden === "function" && isBrowserComponentHidden(entry)) return;
    const filename = entry.viewer_filename || entry.filename || entry.name;
    if (!filename || seen.has(filename)) return;
    seen.add(filename);
    const stem = entry.stem || fileStem(filename);
    const profile = getPartProfile?.(stem) || entry.profile || null;
    entries.push({
      entry,
      name: entry.name,
      filename,
      stem,
      label: profile?.label || entry.label || entry.component_name || entry.body_name || stem,
      kind: profile?.kind || entry.wiringType || entry.part?.kind || "",
      sourced: !!(profile?.source || entry.profile?.source),
      thumbUrl: profile?.source?.png_url || profile?.png_url || entry.preview_url || "",
      profile,
      part: entry.part || (profile ? { kind: profile.kind, label: profile.label, datasheet: profile.datasheet } : null),
    });
  };
  for (const entry of projectTree?.getComponents?.() || []) {
    push(entry);
    for (const child of entry.children || []) push(child);
  }
  // Sourced first, then alphabetical.
  entries.sort((a, b) => Number(!!b.sourced) - Number(!!a.sourced) || String(a.label).localeCompare(String(b.label)));
  return entries;
}

let wiringPartsFilters = loadWiringPartsFilters();
let wiringPartsSelected = new Set();
let wiringPartsLastId = "";
let wiringPartsVisible = [];
let wiringPartsListOpen = false;
let wiringPartsListFs = false;
let wiringPartsFsRestore = null;
let wiringPartsCatalogHits = [];
let wiringPartsSearchTimer = 0;
let wiringPartsCatalogGen = 0;

function wiringPartThumbHtml(part) {
  return `<span class="wiring-parts-picker-thumb wiring-parts-picker-thumb--canvas" aria-hidden="true" data-wiring-thumb-for="${appEscapeHtml(part.id || part.name || part.filename)}"></span>`;
}

function insertWiringPromptToken(token) {
  if (!token) return;
  if (wiringComposer?.insertToken) {
    wiringComposer.insertToken(token);
    return;
  }
  const input = document.getElementById("wiring-prompt-input");
  if (!input) return;
  const text = input.value || "";
  if (text.includes(token)) {
    input.focus();
    return;
  }
  const start = input.selectionStart ?? text.length;
  const end = input.selectionEnd ?? text.length;
  const before = text.slice(0, start);
  const after = text.slice(end);
  const needsSpaceBefore = before && !/\s$/.test(before);
  const needsSpaceAfter = after && !/^\s/.test(after);
  const insert = `${needsSpaceBefore ? " " : ""}${token}${needsSpaceAfter ? " " : ""}`;
  input.value = `${before}${insert}${after}`;
  const caret = before.length + insert.length;
  input.setSelectionRange(caret, caret);
  input.dispatchEvent(new Event("input", { bubbles: true }));
  input.focus();
}

function wiringPartsBucketPredicates() {
  return {
    isMcMaster: (part) => isCatalogHardwareComponent(part.entry || part)
      || isMcMasterPartStem(part.stem)
      || isMcMasterPartStem(part.filename)
      || isMcMasterPartStem(part.name)
      || !!part.mcmaster_part_number,
    isElectronics: (part) => !!recognizePart(part.filename || part.name || part.label || part.stem),
  };
}

function collectWiringPartsForUi() {
  const project = annotateWiringParts(listWiringProjectParts(), wiringPartsBucketPredicates());
  const seen = new Set();
  for (const part of project) {
    if (part.filename) seen.add(part.filename);
    seen.add(part.id);
  }
  const extras = [];
  const pushExtra = (item) => {
    const mapped = electronicsItemToPart(item);
    if (mapped.filename && seen.has(mapped.filename)) return;
    if (seen.has(mapped.id)) return;
    seen.add(mapped.id);
    extras.push(mapped);
  };
  for (const item of latestElectronicsBundle?.used?.cad || []) pushExtra(item);
  for (const item of latestElectronicsBundle?.suggestions || []) {
    if (item?.kind === "send-all-cad") continue;
    pushExtra(item);
  }
  const catalog = wiringPartsFilters.mcmaster
    ? wiringPartsCatalogHits.map(catalogCandidateToPart).filter((part) => !seen.has(part.id))
    : [];
  const links = wiringComposeLinks.map((url) => {
    const label = wiringLinkLabel(url);
    return {
      id: `url:${url}`,
      filename: url,
      stem: label,
      label,
      kind: "link",
      sourced: true,
      url,
      type: "url",
      thumbUrl: "",
      entry: { name: url, url },
    };
  }).filter((part) => !seen.has(part.id) && !seen.has(part.filename));
  return [...project, ...extras, ...catalog, ...links];
}

function wiringPartIsLinked(part) {
  return wiringPromptRefs.some((ref) => (
    ref.id === part.id
    || (part.filename && (ref.id === `component:${part.filename}` || ref.filename === part.filename))
    || (part.mcmaster_part_number && ref.mcmaster_part_number === part.mcmaster_part_number)
    || (part.url && (ref.url === part.url || ref.filename === part.url))
  )) || (part.url && wiringComposeLinks.includes(part.url));
}

function fillWiringPartThumb(host, part) {
  if (!host || !part) return;
  host.replaceChildren();
  if (part.thumbUrl) {
    const img = document.createElement("img");
    img.src = part.thumbUrl;
    img.alt = "";
    img.loading = "lazy";
    host.appendChild(img);
    return;
  }
  const canvas = document.createElement("canvas");
  drawPromptTargetThumb(canvas, part.entry || part, false, { topDown: true });
  host.appendChild(canvas);
}

function wiringPartsItemHtml(part) {
  const linked = wiringPartIsLinked(part);
  const selected = wiringPartsSelected.has(part.id);
  const meta = [part.bucket, part.kind, part.sourced ? "sourced" : "", part.filename || part.mcmaster_part_number]
    .filter(Boolean)
    .join(" · ");
  const badge = linked
    ? `<span class="wiring-parts-picker-item-badge wiring-parts-picker-item-badge--linked">Linked</span>`
    : part.origin === "catalog"
      ? `<span class="wiring-parts-picker-item-badge">McMaster</span>`
      : part.sourced
        ? `<span class="wiring-parts-picker-item-badge">Sourced</span>`
        : "";
  const productHref = String(part.url || part.datasheet || "").trim();
  const hasProduct = /^https:\/\//i.test(productHref);
  const amazonQ = amazonSearchUrl(partShopQuery({
    name: part.label,
    part_number: part.mcmaster_part_number,
    kind: part.kind,
    category: part.bucket === "electronics" ? "electronics" : part.bucket,
  }));
  const needsAmazon = part.bucket === "electronics" && !hasProduct;
  const infoAttr = part.filename
    ? `data-wiring-part-info="${appEscapeHtml(part.filename)}"`
    : part.datasheet
      ? `data-wiring-part-docs="${appEscapeHtml(part.datasheet)}"`
      : "";
  const infoBtn = infoAttr
    ? `<button type="button" class="wiring-parts-picker-info" ${infoAttr} title="View / source this part" aria-label="View ${appEscapeHtml(part.label)}">ⓘ</button>`
    : "";
  return `<div class="wiring-parts-picker-item${linked ? " is-linked" : ""}${selected ? " is-selected" : ""}" role="option" aria-selected="${selected ? "true" : "false"}" data-wiring-part-id="${appEscapeHtml(part.id)}" data-wiring-part-file="${appEscapeHtml(part.filename || "")}">
      <label class="wiring-parts-check"><input type="checkbox" data-wiring-part-check="${appEscapeHtml(part.id)}" ${selected ? "checked" : ""} aria-label="Select ${appEscapeHtml(part.label)}" /></label>
      ${wiringPartThumbHtml(part)}
      <div class="wiring-parts-picker-item-copy">
        <div class="wiring-parts-picker-item-top">
          <span class="wiring-parts-picker-item-name" title="${appEscapeHtml(part.label)}">${appEscapeHtml(part.label)}</span>
          ${badge}
          ${needsAmazon ? `<span class="assist-nolink">No link</span>` : ""}
        </div>
        <span class="wiring-parts-picker-item-meta" title="${appEscapeHtml(meta)}">${appEscapeHtml(meta)}</span>
      </div>
      <div class="wiring-parts-picker-item-actions">
        ${infoBtn}
        ${needsAmazon ? `<button type="button" class="wiring-parts-picker-link" data-amazon-open="${appEscapeHtml(amazonQ)}">Amazon</button>
        <button type="button" class="wiring-parts-picker-link" data-amazon-copy="${appEscapeHtml(amazonQ)}">Copy</button>
        <button type="button" class="wiring-parts-picker-link" data-amazon-fit="${appEscapeHtml(part.id)}">Fit?</button>` : ""}
        <button type="button" class="wiring-parts-picker-link" data-wiring-part-link="${appEscapeHtml(part.id)}" title="Link in Wiring AI prompt">${linked ? "Linked" : "Link"}</button>
      </div>
    </div>`;
}

function bindWiringPartsListEl(listEl, parts) {
  if (!listEl) return;
  listEl.querySelectorAll("[data-amazon-open]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      const href = btn.getAttribute("data-amazon-open") || "";
      if (href) window.open(href, "_blank", "noopener,noreferrer");
    });
  });
  listEl.querySelectorAll("[data-amazon-copy]").forEach((btn) => {
    btn.addEventListener("click", async (ev) => {
      ev.stopPropagation();
      const href = btn.getAttribute("data-amazon-copy") || "";
      try { if (href) await navigator.clipboard.writeText(href); } catch { /* ignore */ }
    });
  });
  listEl.querySelectorAll("[data-amazon-fit]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      const id = btn.getAttribute("data-amazon-fit");
      const part = parts.find((item) => item.id === id);
      if (!part) return;
      renderAgentUi?.openWithQuestion?.(electronicsFitPrompt({
        name: part.label,
        part_number: part.mcmaster_part_number,
        kind: part.kind,
        category: "electronics",
        description: part.meta || part.kind,
      }), { autoSend: true, mini: true, partsList: true });
    });
  });
  listEl.querySelectorAll("[data-wiring-thumb-for]").forEach((host) => {
    const id = host.getAttribute("data-wiring-thumb-for");
    const part = parts.find((item) => item.id === id || item.name === id || item.filename === id);
    fillWiringPartThumb(host, part);
  });
  listEl.querySelectorAll("[data-wiring-part-check]").forEach((input) => {
    input.addEventListener("click", (ev) => ev.stopPropagation());
    input.addEventListener("change", (ev) => {
      ev.stopPropagation();
      const id = input.getAttribute("data-wiring-part-check");
      const next = applyListSelection(wiringPartsSelected, id, parts.map((p) => p.id), { toggle: true }, wiringPartsLastId);
      wiringPartsSelected = next.selected;
      wiringPartsLastId = next.lastId;
      renderWiringPartsPickerList();
    });
  });
  listEl.querySelectorAll("[data-wiring-part-id]").forEach((row) => {
    row.addEventListener("click", (ev) => {
      if (ev.target.closest?.("button, a, input, label")) return;
      const id = row.getAttribute("data-wiring-part-id");
      const next = applyListSelection(
        wiringPartsSelected,
        id,
        parts.map((p) => p.id),
        {
          shift: ev.shiftKey,
          toggle: ev.metaKey || ev.ctrlKey,
          replace: !ev.shiftKey && !ev.metaKey && !ev.ctrlKey,
        },
        wiringPartsLastId,
      );
      wiringPartsSelected = next.selected;
      wiringPartsLastId = next.lastId;
      renderWiringPartsPickerList();
    });
  });
  listEl.querySelectorAll("[data-wiring-part-info]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const filename = btn.getAttribute("data-wiring-part-info");
      const part = parts.find((p) => p.filename === filename);
      if (!part) return;
      try {
        componentProfileUI?.open?.(part.entry || {
          name: part.name,
          stem: part.stem,
          filename: part.filename,
          label: part.label,
          viewer_filename: part.filename,
        }, projectId);
      } catch (err) {
        setEditStatus("error", err?.message || "Could not open part profile.");
      }
    });
  });
  listEl.querySelectorAll("[data-wiring-part-docs]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const href = btn.getAttribute("data-wiring-part-docs");
      if (href) window.open(href, "_blank", "noopener");
    });
  });
  listEl.querySelectorAll("[data-wiring-part-link]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      const id = btn.getAttribute("data-wiring-part-link");
      const part = parts.find((p) => p.id === id);
      if (!part) return;
      sendWiringPartsToPrompt([part]);
    });
  });
}

function renderWiringPartsPickerList() {
  const pickerList = document.getElementById("wiring-parts-picker-list");
  const boardList = document.getElementById("wiring-parts-list");
  const countEl = document.getElementById("wiring-parts-picker-count");
  const query = String(document.getElementById("wiring-parts-list-search")?.value || "");
  const allParts = collectWiringPartsForUi();
  const pickerParts = filterWiringParts(allParts, wiringPartsFilters, "");
  const boardParts = filterWiringParts(allParts, wiringPartsFilters, query);
  wiringPartsVisible = boardParts;
  if (countEl) countEl.textContent = String(pickerParts.length);
  syncWiringPartsFilterInputs();

  const renderInto = (listEl, parts, emptyProject, emptyFilter) => {
    if (!listEl) return;
    if (!projectId) {
      listEl.innerHTML = `<p class="wiring-parts-picker-empty">${emptyProject}</p>`;
      return;
    }
    if (!parts.length) {
      listEl.innerHTML = `<p class="wiring-parts-picker-empty">${emptyFilter}</p>`;
      return;
    }
    listEl.innerHTML = parts.map(wiringPartsItemHtml).join("");
    bindWiringPartsListEl(listEl, parts);
  };

  renderInto(
    pickerList,
    pickerParts,
    "Select a project to list parts.",
    "No matching project parts. Toggle Models, McMaster, or Electronics.",
  );
  if (wiringPartsListOpen) {
    renderInto(
      boardList,
      boardParts,
      "Select a project to list parts.",
      query.trim()
        ? "No matching parts. Try another search or filter."
        : "No matching parts. Toggle Models, McMaster, or Electronics.",
    );
  }
}

function syncWiringPartsFilterInputs() {
  document.querySelectorAll("[data-wiring-parts-filter]").forEach((input) => {
    const key = input.getAttribute("data-wiring-parts-filter");
    if (key && key in wiringPartsFilters) input.checked = wiringPartsFilters[key] !== false;
  });
}

function setWiringPartsFilter(key, on) {
  if (!(key in wiringPartsFilters)) return;
  wiringPartsFilters = saveWiringPartsFilters({ ...wiringPartsFilters, [key]: !!on });
  if (!wiringPartsFilters.mcmaster) wiringPartsCatalogHits = [];
  renderWiringPartsPickerList();
}

function sendWiringPartsToPrompt(parts) {
  const list = (parts || []).filter(Boolean);
  if (!list.length) {
    setEditStatus("ok", "Select parts first, then Send to wiring.");
    const status = document.getElementById("wiring-prompt-status");
    if (status) {
      status.className = "status";
      status.textContent = "Select parts first, then Send to wiring.";
    }
    return 0;
  }
  let count = 0;
  for (const part of list) {
    let ref = null;
    if (part.filename && part.origin !== "catalog") {
      ref = addWiringPromptComponentRef(part);
    } else {
      ref = addWiringPromptRef({
        id: part.id,
        type: "component",
        token: compactComponentToken(part.stem || part.label),
        label: part.label,
        filename: part.filename || undefined,
        stem: part.stem,
        kind: part.kind,
        mcmaster_part_number: part.mcmaster_part_number,
        datasheet: part.datasheet,
      });
    }
    if (ref?.token && !wiringComposer) insertWiringPromptToken(ref.token);
    if (ref) count += 1;
  }
  const status = document.getElementById("wiring-prompt-status");
  if (status) {
    status.className = "status ok";
    status.textContent = count === 1
      ? `Linked ${list[0].label} in the wiring prompt.`
      : `Linked ${count} parts in the wiring prompt.`;
  }
  setEditStatus("ok", status?.textContent || `Linked ${count} part${count === 1 ? "" : "s"}.`);
  renderWiringPartsPickerList();
  return count;
}

function selectedWiringPartsFrom(visible) {
  const wanted = wiringPartsSelected;
  return (visible || []).filter((part) => wanted.has(part.id));
}

function openWiringPartsListTab() {
  wiringPartsListOpen = true;
  const listPanel = document.getElementById("wiring-parts-list-panel");
  listPanel?.classList.remove("hidden");
  listPanel?.removeAttribute("hidden");
  document.getElementById("app")?.classList.add("wiring-parts-list-open");
  document.getElementById("wiring-workspace")?.classList.add("parts-list-open");
  document.getElementById("wiring-content-area")?.classList.add("parts-list-open");
  try { void refreshPartProfiles?.(); } catch (_) { /* ignore */ }
  try { void refreshElectronicsSuggestions?.(); } catch (_) { /* ignore */ }
  renderWiringPartsPickerList();
}

function closeWiringPartsListTab() {
  if (wiringPartsListFs) setWiringPartsListFullscreen(false);
  wiringPartsListOpen = false;
  wiringPartsCatalogHits = [];
  const listPanel = document.getElementById("wiring-parts-list-panel");
  listPanel?.classList.add("hidden");
  listPanel?.setAttribute("hidden", "");
  document.getElementById("app")?.classList.remove("wiring-parts-list-open");
  document.getElementById("wiring-content-area")?.classList.remove("parts-list-open");
}

function setWiringPartsListFullscreen(on) {
  const appEl = document.getElementById("app");
  const next = !!on;
  wiringPartsListFs = next;
  appEl?.classList.toggle("wiring-parts-list-fs", next);
  const fsBtn = document.getElementById("wiring-parts-list-fs");
  const fsExit = document.getElementById("wiring-parts-list-fs-exit");
  if (fsBtn) fsBtn.hidden = next;
  if (fsExit) fsExit.hidden = !next;
  if (next) {
    wiringPartsFsRestore = {
      left: !!appEl?.classList.contains("left-panel-hidden"),
      right: !!appEl?.classList.contains("right-panel-hidden"),
    };
    try { window.Render3DPanels?.setSidebarHidden?.(true, { persist: false }); } catch (_) { /* ignore */ }
    try { window.Render3DPanels?.setRightPanelHidden?.(true, { persist: false }); } catch (_) { /* ignore */ }
  } else if (wiringPartsFsRestore) {
    try { window.Render3DPanels?.setSidebarHidden?.(wiringPartsFsRestore.left, { persist: false }); } catch (_) { /* ignore */ }
    try { window.Render3DPanels?.setRightPanelHidden?.(wiringPartsFsRestore.right, { persist: false }); } catch (_) { /* ignore */ }
    wiringPartsFsRestore = null;
  }
}

function scheduleWiringPartsCatalogSearch(query) {
  window.clearTimeout(wiringPartsSearchTimer);
  const q = String(query || "").trim();
  if (!wiringPartsFilters.mcmaster || q.length < 2) {
    wiringPartsCatalogHits = [];
    renderWiringPartsPickerList();
    return;
  }
  wiringPartsSearchTimer = window.setTimeout(() => {
    void searchWiringPartsCatalog(q);
  }, 280);
}

async function searchWiringPartsCatalog(query) {
  const q = String(query || "").trim();
  if (!wiringPartsFilters.mcmaster || q.length < 2) {
    wiringPartsCatalogHits = [];
    renderWiringPartsPickerList();
    return;
  }
  const gen = ++wiringPartsCatalogGen;
  try {
    const params = new URLSearchParams();
    params.set("q", q);
    params.set("sources", "step_parts");
    params.set("limit", "24");
    const data = await api(`/api/catalog/search?${params.toString()}`);
    if (gen !== wiringPartsCatalogGen) return;
    wiringPartsCatalogHits = Array.isArray(data?.candidates) ? data.candidates : [];
    renderWiringPartsPickerList();
  } catch {
    if (gen !== wiringPartsCatalogGen) return;
    wiringPartsCatalogHits = [];
    renderWiringPartsPickerList();
  }
}

function initWiringPartsPicker() {
  const toggle = document.getElementById("wiring-parts-picker-toggle");
  const pickerPanel = document.getElementById("wiring-parts-picker-panel");
  if (!toggle || !pickerPanel) {
    renderWiringPartsPickerList();
    return;
  }
  if (toggle.dataset.bound === "1") {
    renderWiringPartsPickerList();
    return;
  }
  toggle.dataset.bound = "1";
  toggle.addEventListener("click", () => {
    const open = toggle.getAttribute("aria-expanded") === "true";
    const next = !open;
    toggle.setAttribute("aria-expanded", String(next));
    pickerPanel.classList.toggle("hidden", !next);
    if (next) {
      try { void refreshPartProfiles?.(); } catch (_) { /* ignore */ }
      renderWiringPartsPickerList();
    }
  });
  document.querySelectorAll("[data-wiring-parts-filter]").forEach((input) => {
    input.addEventListener("change", () => {
      setWiringPartsFilter(input.getAttribute("data-wiring-parts-filter"), input.checked);
      const q = document.getElementById("wiring-parts-list-search")?.value;
      if (input.getAttribute("data-wiring-parts-filter") === "mcmaster") scheduleWiringPartsCatalogSearch(q);
    });
  });
  document.getElementById("wiring-parts-picker-send")?.addEventListener("click", () => {
    const visible = filterWiringParts(collectWiringPartsForUi(), wiringPartsFilters, "");
    sendWiringPartsToPrompt(selectedWiringPartsFrom(visible));
  });
  document.getElementById("wiring-parts-picker-send-all")?.addEventListener("click", () => {
    sendWiringPartsToPrompt(filterWiringParts(collectWiringPartsForUi(), wiringPartsFilters, ""));
  });
  document.getElementById("wiring-parts-list-send")?.addEventListener("click", () => {
    sendWiringPartsToPrompt(selectedWiringPartsFrom(wiringPartsVisible));
  });
  document.getElementById("wiring-parts-list-send-all")?.addEventListener("click", () => {
    sendWiringPartsToPrompt(wiringPartsVisible);
  });
  document.getElementById("wiring-parts-picker-fs")?.addEventListener("click", () => {
    if (workspaceModes?.getMode?.() !== "wiring") workspaceModes?.setMode?.("wiring");
    workspaceModes?.setWiringTab?.("PARTS_LIST");
    openWiringPartsListTab();
    setWiringPartsListFullscreen(true);
  });
  document.getElementById("wiring-parts-list-fs")?.addEventListener("click", () => {
    setWiringPartsListFullscreen(true);
  });
  document.getElementById("wiring-parts-list-fs-exit")?.addEventListener("click", () => {
    setWiringPartsListFullscreen(false);
  });
  document.getElementById("wiring-parts-list-close")?.addEventListener("click", () => {
    workspaceModes?.setWiringTab?.("WIRING");
  });
  document.getElementById("wiring-parts-list-search")?.addEventListener("input", (ev) => {
    scheduleWiringPartsCatalogSearch(ev.target.value);
    renderWiringPartsPickerList();
  });
  bindMarqueeSelect(document.getElementById("wiring-parts-picker-list"), {
    onSelect: (ids, { additive } = {}) => {
      if (!additive) wiringPartsSelected = new Set();
      for (const id of ids) wiringPartsSelected.add(id);
      if (ids.length) wiringPartsLastId = ids[ids.length - 1];
      renderWiringPartsPickerList();
    },
  });
  bindMarqueeSelect(document.getElementById("wiring-parts-list"), {
    onSelect: (ids, { additive } = {}) => {
      if (!additive) wiringPartsSelected = new Set();
      for (const id of ids) wiringPartsSelected.add(id);
      if (ids.length) wiringPartsLastId = ids[ids.length - 1];
      renderWiringPartsPickerList();
    },
  });
  syncWiringPartsFilterInputs();
  renderWiringPartsPickerList();
}

function addWiringPromptComponentRef(payload) {
  if (!payload?.filename && !payload?.name) return null;
  const filename = payload.filename || payload.name;
  const stem = payload.stem || filename.replace(/\.[^.]+$/, "");
  const ref = normalizeWiringPromptRef({
    id: `component:${filename}`,
    type: "component",
    token: compactComponentToken(stem),
    label: payload.label || stem,
    stem,
    filename,
    kind: payload.part?.kind || payload.profile?.kind || payload.wiringType || payload.kind || "",
  });
  if (wiringComposer?.addReference) {
    const already = wiringComposer.getReferences().some((r) => r.id === ref.id);
    if (already) {
      const text = wiringComposer.getRawPromptText?.() || "";
      if (ref.token && !String(text).includes(ref.token)) wiringComposer.insertToken(ref.token);
    } else {
      wiringComposer.addReference(ref, { insertMention: true });
    }
    wiringPromptRefs = wiringComposer.getReferences().map(normalizeWiringPromptRef).filter(Boolean);
    renderWiringPartsPickerList();
    return ref;
  }
  if (!wiringPromptRefs.some((r) => r.id === ref.id)) {
    wiringPromptRefs.push(ref);
    renderWiringPromptRefs();
  } else {
    renderWiringPartsPickerList();
  }
  return ref;
}

function addWiringPromptRef(refLike, { insertMention = true } = {}) {
  const ref = normalizeWiringPromptRef(refLike);
  if (!ref) return null;
  if (wiringComposer?.addReference) {
    const already = wiringComposer.getReferences().some((r) => r.id === ref.id || (ref.url && r.url === ref.url));
    if (already) {
      if (insertMention) {
        const text = wiringComposer.getRawPromptText?.() || "";
        if (ref.token && !String(text).includes(ref.token)) wiringComposer.insertToken(ref.token);
      }
    } else {
      wiringComposer.addReference(ref, { insertMention });
    }
    wiringPromptRefs = wiringComposer.getReferences().map(normalizeWiringPromptRef).filter(Boolean);
    renderWiringPartsPickerList();
    return ref;
  }
  if (!wiringPromptRefs.some((r) => r.id === ref.id || (ref.url && r.url === ref.url))) {
    wiringPromptRefs.push(ref);
    renderWiringPromptRefs();
  }
  return ref;
}

function wiringPromptTextWithRefs(prompt, refs = wiringPromptRefs) {
  const list = (refs || []).filter(Boolean);
  if (!list.length) return prompt;
  const lines = list
    .map((r) => {
      if (r.type === "url" || r.type === "link" || r.url) {
        return `- ${r.token}: ${r.description ? r.description + ": " : ""}linked page "${r.label || r.url}" (${r.url}).`;
      }
      if (r.type === "wire") {
        const from = r.endpoints?.from || r.from_label || "";
        const to = r.endpoints?.to || r.to_label || "";
        const detail = [from, to].filter(Boolean).join(" -> ");
        return `- ${r.token}: selected wire "${r.label}"${detail ? ` (${detail})` : ""}.`;
      }
      return `- ${r.token}: "${r.label}"${r.kind ? ` (${r.kind})` : ""}${r.filename ? ` from file ${r.filename}` : ""}.`;
    })
    .join("\n");
  return `${prompt}\n\nReferenced wiring context:\n${lines}`;
}

wiringPromptInput?.addEventListener("dragover", (e) => {
  if (isExplorerComponentDrag(e)) {
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
    wiringPromptInput.classList.add("dragging");
    wiringComposer?.editor?.classList?.add("dragging");
  }
});
wiringPromptInput?.addEventListener("dragleave", () => {
  wiringPromptInput.classList.remove("dragging");
  wiringComposer?.editor?.classList?.remove("dragging");
});
function handleWiringPromptDrop(e) {
  const payloads = droppedExplorerRefs(e).filter((ref) => !ref.type || ref.type === "component");
  const files = [...(e.dataTransfer?.files || [])];
  if (!payloads.length && !files.length) return;
  e.preventDefault();
  wiringPromptInput?.classList.remove("dragging");
  wiringComposer?.editor?.classList?.remove("dragging");
  if (files.length && wiringComposer?.addReference) {
    for (const file of files) {
      const kind = isPromptLinkedMediaFile(file) ? promptLinkedFileType(file) : "document";
      const stem = String(file.name || "file").replace(/\.[^.]+$/, "") || kind;
      wiringComposer.addReference({
        id: `${kind}:wiring:${file.name}`,
        type: isPromptFileLinkType(kind) ? kind : "document",
        token: compactComponentToken(stem),
        label: file.name,
        filename: file.name,
        stem,
        mime: file.type,
      }, { insertMention: false });
    }
    wiringComposer.setPromptText?.(stripPromptFileBanners(wiringComposer.getRawPromptText?.() || ""));
  }
  if (!payloads.length) return;
  let ref = null;
  payloads.forEach((payload) => {
    ref = addWiringPromptComponentRef(payload) || ref;
  });
  wiringComposer?.editor?.focus?.() || wiringPromptInput?.focus();
  const status = document.getElementById("wiring-prompt-status");
  if (status) {
    status.className = "status ok";
    status.textContent = `Referenced ${payloads.length} component${payloads.length === 1 ? "" : "s"} in the wiring prompt.`;
  }
}
wiringPromptInput?.addEventListener("drop", handleWiringPromptDrop);
wiringComposer?.editor?.addEventListener("dragover", (e) => {
  if (isExplorerComponentDrag(e)) {
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
    wiringComposer.editor.classList.add("dragging");
  }
});
wiringComposer?.editor?.addEventListener("dragleave", () => {
  wiringComposer?.editor?.classList?.remove("dragging");
});
wiringComposer?.editor?.addEventListener("drop", handleWiringPromptDrop);

document.getElementById("wiring-compose-links-add")?.addEventListener("click", () => {
  const input = document.getElementById("wiring-compose-links-input");
  addWiringComposeLink(input?.value || "", { persist: false });
  if (input) input.value = "";
});
document.getElementById("wiring-compose-links-input")?.addEventListener("keydown", (e) => {
  if (e.key !== "Enter") return;
  e.preventDefault();
  addWiringComposeLink(e.currentTarget.value || "", { persist: false });
  e.currentTarget.value = "";
});

document.getElementById("btn-wiring-prompt")?.addEventListener("click", () => {
  runWiringPrompt();
});
document.getElementById("btn-wiring-stop")?.addEventListener("click", () => {
  void cancelActiveGeneration();
});
document.getElementById("btn-wiring-toolbelt-stop")?.addEventListener("click", () => {
  void cancelActiveGeneration();
});

async function runWiringPrompt(continuation = null) {
  if (continuation instanceof Event) continuation = null;
  if (!projectId) {
    setEditStatus("error", "Select a project in the sidebar first.");
    return;
  }
  const input = document.getElementById("wiring-prompt-input");
  const driverLinkInput = document.getElementById("wiring-driver-link-input");
  const status = document.getElementById("wiring-prompt-status");
  const prompt = (continuation?.prompt || wiringComposer?.getPromptText?.() || input?.value || "").trim();
  const driverLink = driverLinkInput?.value?.trim();
  const pastedLinks = extractPromptUrls(prompt, 8);
  const chipLinks = (wiringComposer?.getReferences?.() || wiringPromptRefs || [])
    .map((r) => String(r?.url || "").trim())
    .filter(Boolean);
  // Prefer auto-sourced product/schematic pages so Wiring AI can fetch pinouts.
  const autoLinks = [
    ...pendingWiringElectronicsLinks,
    ...collectElectronicsSourcingUrls(latestElectronicsBundle).map((u) => u.url),
  ];
  const driverLinks = [...new Set([driverLink, ...chipLinks, ...pastedLinks, ...autoLinks].filter(Boolean))].slice(0, 16);
  if (wiringPromptSubmitInFlight) {
    if (status) {
      status.className = "status loading";
      status.textContent = "Wiring generation is already starting…";
    }
    return;
  }
  if (!prompt) {
    if (status) {
      status.className = "status error";
      status.textContent = "Describe the circuit you want to wire.";
    }
    return;
  }
  attachWiringBrowserReferenceFiles({ insertMention: false });
  const promptRefs = wiringPromptRefsForRequest();
  const promptForAi = continuation?.prompt || `${wiringPromptTextWithRefs(prompt, promptRefs)}${electronicsSourcingPromptBlock(latestElectronicsBundle)}`.slice(0, 8000);
  const fileCount = promptRefs.filter((r) => r?.filename && r.type !== "wire" && r.type !== "url" && r.type !== "link").length;
  if (status) {
    status.className = "status loading";
    if (fileCount && driverLinks.length) {
      status.textContent = `Generating schematic with ${fileCount} reference file${fileCount === 1 ? "" : "s"} and ${driverLinks.length} sourced doc${driverLinks.length === 1 ? "" : "s"}…`;
    } else if (fileCount) {
      status.textContent = `Generating schematic with ${fileCount} Browser reference file${fileCount === 1 ? "" : "s"}…`;
    } else if (driverLinks.length) {
      status.textContent = `Generating schematic with ${driverLinks.length} sourced doc${driverLinks.length === 1 ? "" : "s"}…`;
    } else {
      status.textContent = "Generating schematic…";
    }
  }
  wiringPromptSubmitInFlight = true;
  userCancelRequested = false;
  const promptHistoryId = stampWiringPromptHistoryPending({
    prompt,
    model: (typeof getSelectedPromptModelInfo === "function" ? getSelectedPromptModelInfo() : {}).model,
    provider: (typeof getSelectedPromptModelInfo === "function" ? getSelectedPromptModelInfo() : {}).provider,
    speed: getWiringGenerationSpeed(),
  });
  lastPromptCopyContext = {
    projectId,
    filename: selectedFile,
    promptText: promptForAi,
    promptHistoryId,
  };
  showAiComposePanel();
  beginGenerationWatch(projectId, { kind: "wiring", pendingStart: true });
  try {
    const data = await api(`/api/projects/${projectId}/wiring/prompt`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        prompt: promptForAi,
        images: wiringPromptImages.map(({ id, name, media_type, data_url }) => ({
          id,
          name,
          media_type,
          data_url,
        })),
        driver_links: driverLinks,
        references: promptRefs,
        speed: getWiringGenerationSpeed(),
        ...getPromptAiKeyBodyFields(),
        ...getKnowledgePromptFields(),
        ...(continuation || {}),
      }),
    });
    lastPromptCopyContext = {
      ...lastPromptCopyContext,
      promptId: data?.prompt_id || promptHistoryId,
      promptHistoryId,
      traceId: data?.trace_id,
    };
    updatePendingPromptHistoryEntry(promptHistoryId, {
      status: "running",
      trace_id: data?.trace_id,
    });
    if (data?.accepted || data?.status === "running") {
      if (status) {
        status.className = "status loading";
        status.textContent = "Generating schematic… safe to refresh.";
      }
      return { accepted: true };
    }
    stopGenerationWatch(projectId);
    wiringSim.applySchematic(data.schematic, { revealRequirements: true });
    await refreshFiles();
    await refreshWiringPromptHistory();
    await refreshPromptHistory();
    const blocker = data?.blocker || data?.schematic?.blocker;
    if (blocker?.reason) {
      wiringOverlay?.showError(blocker.reason, {
        promptId: data?.prompt_id,
        projectId,
        traceId: data?.trace_id,
        promptText: promptForAi,
        suggestions: blocker.suggestions || [],
      });
      if (status) {
        status.className = "status error";
        status.textContent = "Could not complete this wiring — see the message on the canvas.";
      }
    } else if (status) {
      status.className = "status ok";
      status.textContent = data.message || "Schematic updated.";
    }
    markGenerationApplied(projectId, data.trace_id);
    wiringPromptImages = [];
    wiringPromptRefs = [];
    if (wiringComposer) {
      wiringComposer.clearReferences();
      // Keep the written prompt; only clear chips/refs after success.
    }
    if (driverLinkInput) driverLinkInput.value = "";
    renderWiringPromptRefs();
    renderWiringPromptImages();
    return { accepted: true };
  } catch (err) {
    if (!userCancelRequested) stopGenerationWatch(projectId);
    const wasCanceled = userCancelRequested || err.name === "AbortError" || err.message?.toLowerCase().includes("cancel");
    updatePendingPromptHistoryEntry(promptHistoryId, {
      status: wasCanceled ? "canceled" : "failed",
      success: false,
      error: wasCanceled ? null : (err.message || "Wiring prompt failed."),
    });
    await refreshWiringPromptHistory();
    if (status) {
      status.className = wasCanceled ? "status" : "status error";
      status.textContent = wasCanceled ? "Generation canceled." : (err.message || "Wiring prompt failed.");
    }
    if (!wasCanceled) {
      wiringOverlay?.showError(formatUserError(err, err.message || "Wiring prompt failed."), {
        projectId,
        promptText: promptForAi,
        suggestions: generationFailureAdvice(err),
      });
    }
  } finally {
    wiringPromptSubmitInFlight = false;
  }
}

