async function generateRobotArtifacts(kind = "both") {
  if (!projectId) {
    setEditStatus("error", "Select a project first.");
    return;
  }
  const source = document.getElementById("rigging-artifact-source")?.value;
  const status = document.getElementById("rigging-prompt-status");
  if (!source) {
    setEditStatus("error", "Select a CAD source, URDF, or SRDF file.");
    if (status) {
      status.className = "status error";
      status.textContent = "No CAD or robot-description source selected.";
    }
    return;
  }
  if (status) {
    status.className = "status loading";
    status.textContent = `Generating ${kind.toUpperCase()} robot artifacts… safe to refresh or switch projects.`;
  }
  beginGenerationWatch(projectId, { kind: "rigging", mode: "rigging", pendingStart: true });
  try {
    const data = await api(`/api/projects/${projectId}/rigging/generate-artifacts`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ source, kind }),
    });
    if (data?.accepted || data?.status === "running") {
      const liveGen = data.generation || { status: "running", kind: "rigging", trace_id: data.trace_id };
      const proj = allProjects.find((p) => p.id === projectId);
      if (proj) proj.generation = liveGen;
      renderProjectList();
      if (status) {
        status.className = "status loading";
        status.textContent = "Generating robot artifacts in background… safe to refresh.";
      }
      return;
    }
    robotArtifactData = data;
    await refreshFiles();
    renderRobotArtifacts();
    const outputs = (data.outputs || []).map((out) => out.filename).filter(Boolean).join(", ");
    const errors = (data.errors || []).length;
    const msg = outputs
      ? `Generated ${outputs}${errors ? ` (${errors} warning${errors === 1 ? "" : "s"})` : ""}.`
      : data.message || "No robot artifacts generated.";
    setEditStatus(errors ? "error" : "ok", msg);
    if (status) {
      status.className = errors ? "status error" : "status ok";
      status.textContent = msg;
    }
    if (!errors) {
      const proj = allProjects.find((p) => p.id === projectId);
      if (proj) proj.has_rig = true;
      renderProjectList();
      setRiggingViewportPlaybackVisible(true);
      await attachRobotPlaybackForLoadedModel(source, projectId);
      setRiggingViewportPlaybackVisible(true);
      syncRiggingViewportPlaybackUi();
      notifyAgentFinish({ kind: "rigging", pid: projectId, gen: data });
    }
  } catch (err) {
    if (await keepRiggingGenerationOpenIfRunning(projectId, status)) return;
    await refreshRobotArtifacts({ quiet: true });
    const msg = err?.message || "Robot artifact generation failed.";
    if (/missing\s+gen_urdf|missing\s+gen_srdf|does not define callable gen_(?:urdf|srdf)/i.test(msg)) {
      if (status) {
        status.className = "status loading";
        status.textContent = "This source needs robot generators first. Authoring URDF/SRDF with AI…";
      }
      await authorJakeRobotDescription({ source, kind, openMotion: false });
      return;
    }
    setEditStatus("error", msg);
    if (status) {
      status.className = "status error";
      status.textContent = msg;
    }
  }
}

function getXrRobotRiggingState() {
  try {
    const { urdfFile, srdfFile } = pickPreferredRobotFiles(robotArtifactData || {});
    const fileNames = (lastProjectFiles || [])
      .map((f) => (typeof f === "string" ? f : (f?.name || f?.filename || "")))
      .filter(Boolean);
    const hasUrdf = !!(urdfFile || fileNames.some((name) => /\.urdf$/i.test(name)));
    const hasSrdf = !!(srdfFile || fileNames.some((name) => /\.srdf$/i.test(name)));
    const source = pickSimMotionPythonSource({ filename: selectedFile }, robotArtifactData)
      || document.getElementById("rigging-artifact-source")?.value
      || "";
    const generating = !!(
      projectId
      && generationWatchPid === projectId
      && String(generationWatchOverlay?.kind || "").toLowerCase() === "rigging"
    );
    const liveGen = allProjects.find((p) => p.id === projectId)?.generation;
    const genRunning = !!(
      generating
      || (
        String(liveGen?.kind || "").toLowerCase() === "rigging"
        && String(liveGen?.status || "").toLowerCase() === "running"
      )
    );
    let status = "";
    if (genRunning) status = generationWatchOverlay?.message || "Generating URDF / SRDF…";
    else if (urdfRobotRuntime?.isLoaded?.()) status = `Robot loaded${urdfFile ? `: ${urdfFile}` : ""}`;
    else if (hasUrdf) status = `${urdfFile || "URDF"} available`;
    else if (source) status = `Ready to generate from ${source}`;
    else status = "Add a direct URDF/SRDF file or build a CAD robot model";
    return {
      hasUrdf,
      hasSrdf,
      urdfFile: urdfFile || null,
      srdfFile: srdfFile || null,
      source: source || null,
      loaded: !!urdfRobotRuntime?.isLoaded?.(),
      playing: !!urdfRobotRuntime?.isPlaying?.(),
      generating: !!genRunning,
      status,
    };
  } catch (err) {
    console.warn("[xr] robot state", err);
    return {
      hasUrdf: false,
      hasSrdf: false,
      loaded: false,
      playing: false,
      generating: false,
      status: err?.message || "Robot state unavailable",
    };
  }
}

async function handleXrRobotRiggingAction(action, payload = {}) {
  try {
    if (!projectId) {
      return { ok: false, error: "Open a project first" };
    }
    if (action === "robot_refresh") {
      await refreshRobotArtifacts({ quiet: false });
      await refreshFiles?.();
      const state = getXrRobotRiggingState();
      return {
        ok: true,
        message: state.hasUrdf
          ? `${state.urdfFile || "URDF"}${state.hasSrdf ? " + SRDF" : ""} found`
          : (state.source ? `Source ready: ${state.source}` : "No URDF/SRDF yet"),
      };
    }
    if (action === "robot_generate") {
      await refreshRobotArtifacts({ quiet: true });
      let source = pickSimMotionPythonSource({ filename: selectedFile }, robotArtifactData);
      if (!source) {
        const sources = (robotArtifactData?.sources || []).map(String).filter((name) => /\.py$/i.test(name));
        source = sources[0] || "";
      }
      if (!source) {
        return {
          ok: false,
          error: "No CAD, URDF, or SRDF source. Generate or upload a robot description first",
        };
      }
      const sourceSelect = document.getElementById("rigging-artifact-source");
      if (sourceSelect) {
        if (![...sourceSelect.options].some((opt) => opt.value === source)) {
          const opt = document.createElement("option");
          opt.value = source;
          opt.textContent = source;
          sourceSelect.appendChild(opt);
        }
        sourceSelect.value = source;
      }
      const vpSource = document.getElementById("rigging-vp-artifact-source");
      if (vpSource) {
        if (![...vpSource.options].some((opt) => opt.value === source)) {
          const opt = document.createElement("option");
          opt.value = source;
          opt.textContent = source;
          vpSource.appendChild(opt);
        }
        vpSource.value = source;
      }
      const kind = payload?.kind === "urdf" || payload?.kind === "srdf" ? payload.kind : "both";
      await generateRobotArtifacts(kind);
      await refreshRobotArtifacts({ quiet: true });
      const after = getXrRobotRiggingState();
      return {
        ok: true,
        message: after.generating
          ? `Generating ${kind === "both" ? "URDF + SRDF" : kind.toUpperCase()}…`
          : (after.hasUrdf ? `Generated ${after.urdfFile || "URDF"}` : "Generate started"),
      };
    }
    if (action === "robot_load") {
      await refreshRobotArtifacts({ quiet: true });
      const { urdfFile } = pickPreferredRobotFiles(robotArtifactData || {});
      if (!urdfFile) {
        return { ok: false, error: "No URDF yet — Generate first" };
      }
      await ensureUrdfRobotScene({ quiet: false, force: true });
      setCadAssemblyHiddenForUrdf(false);
      setRiggingViewportPlaybackVisible(true);
      if (!urdfRobotRuntime?.isLoaded?.()) {
        return { ok: false, error: "Could not load robot scene" };
      }
      try {
        viewportXR?.placeInFront?.({ keepZoom: true, force: true });
      } catch (_) { /* optional */ }
      return {
        ok: true,
        message: `Loaded ${urdfFile}`,
      };
    }
    if (action === "robot_play") {
      if (!urdfRobotRuntime?.isLoaded?.()) {
        await refreshRobotArtifacts({ quiet: true });
        await ensureUrdfRobotScene({ quiet: false, force: true });
        setCadAssemblyHiddenForUrdf(false);
      }
      if (!urdfRobotRuntime?.isLoaded?.()) {
        return { ok: false, error: "Load the robot first" };
      }
      await toggleRiggingPlayback();
      return {
        ok: true,
        message: urdfRobotRuntime?.isPlaying?.() ? "Motion running" : "Motion paused",
      };
    }
    if (action === "robot_stop") {
      try {
        if (urdfRobotRuntime?.isPlaying?.()) urdfRobotRuntime.stopTrajectory?.();
        stepModuleRuntime?.stop?.({ reset: false });
        planetaryGearRuntime?.stop?.({ reset: false });
        riggingEditor?.setPlaying?.(false);
        syncRiggingViewportPlaybackUi?.();
      } catch (err) {
        console.warn("[xr] stop robot", err);
      }
      return { ok: true, message: "Motion stopped" };
    }
    if (action === "robot_aim") {
      const point = payload?.point;
      if (!point || !Number.isFinite(point.x)) {
        return { ok: false, error: "Missing aim point" };
      }
      if (!urdfRobotRuntime?.isLoaded?.()) {
        await refreshRobotArtifacts({ quiet: true });
        await ensureUrdfRobotScene({ quiet: true, force: true });
        setCadAssemblyHiddenForUrdf(false);
      }
      if (!urdfRobotRuntime?.isLoaded?.()) {
        return { ok: false, error: "Load the robot first" };
      }
      try {
        if (urdfRobotRuntime?.isPlaying?.()) urdfRobotRuntime.stopTrajectory?.();
      } catch (_) { /* ignore */ }
      const result = urdfRobotRuntime.aimTowardWorldPoint?.(point) || { ok: false, error: "Aim not supported" };
      syncUrdfSlidersFromRuntime?.();
      return result?.ok
        ? { ok: true, message: `Moved toward target (${Math.round(result.distanceMm || 0)} mm)` }
        : { ok: false, error: result?.error || "Could not aim" };
    }
    if (action === "robot_ask_open") {
      return { ok: true, message: "Open robot panel", state: getXrRobotRiggingState() };
    }
    return { ok: false, error: `Unknown action: ${action}` };
  } catch (err) {
    console.warn("[xr] robot action", err);
    return { ok: false, error: err?.message || "Robot action failed" };
  }
}

async function setupRobotMotionWorkflow({ autoGenerate = true, askWhenMissing = true } = {}) {
  if (!projectId) {
    setEditStatus("error", "Select a project first.");
    return;
  }
  // Stay on SOLID — motion overlays the same viewport (don't swap to RIGGING).
  workspaceModes.setDesignTab("SOLID");
  ribbon?.setDesignTab?.("SOLID");
  exitRiggingMode();
  setRightTab("rigging");
  riggingPromptHistory.setTab("compose");
  setRiggingWorkspaceMode("urdf");

  const status = document.getElementById("rigging-prompt-status");
  if (status) {
    status.className = "status loading";
    status.textContent = "Checking robot motion setup…";
  }
  setEditStatus("loading", "Setting up robot motion (URDF/SRDF) on the solid viewport…");

  const artifacts = await refreshRobotArtifacts({ quiet: true }) || robotArtifactData || {};
  if (projectAlreadyHasSimMotion({ filename: selectedFile }, artifacts)) {
    const state = await ensureUrdfRobotScene({ quiet: false, force: true });
    if (!urdfRuntimeHasUsableMotion(state)) {
      setCadAssemblyHiddenForUrdf(false);
      setEditStatus("ok", "Showing the CAD model. Existing robot files are placeholders, so motion needs to be generated.");
    } else {
      syncRiggingViewportOverlay({ status: "Robot motion ready on solid viewport." });
      await syncRiggingAdjustSliders({ autoExpand: true });
      setRiggingViewportPlaybackVisible(true);
      setEditStatus("ok", "Robot motion ready. Use Play in the viewport or the Rigging panel to pose and play.");
      if (status) {
        status.className = "status ok";
        status.textContent = "URDF/SRDF ready — playing on the solid viewport.";
      }
      return;
    }
  }

  const source = pickSimMotionPythonSource({ filename: selectedFile }, artifacts);
  if (!source) {
    const input = document.getElementById("rigging-prompt-input");
    if (input && !input.value.trim()) {
      input.value = "Set up this model as a robot: define base_link, movable revolute/prismatic joints, joint limits, link hierarchy, end effector, URDF/SRDF, and a MoveIt2 planning group.";
    }
    const msg = "No CAD, URDF, or SRDF source found. Generate a model or upload a robot description, then click Rig Robot again.";
    setEditStatus("error", msg);
    if (status) {
      status.className = "status error";
      status.textContent = msg;
    }
    return;
  }

  const sourceSelect = document.getElementById("rigging-artifact-source");
  if (sourceSelect) sourceSelect.value = source;
  if (!autoGenerate) {
    setEditStatus("ok", "Robot setup ready. Click Author URDF/SRDF with AI when ready.");
    return;
  }

  let kind = "both";
  if (askWhenMissing) {
    const choice = await askGenerateSimulatedMotion({
      reason: "No usable robot motion is available for this model yet. Generate URDF/SRDF so the model can be posed and played in the solid viewport.",
    });
    if (choice.action === "skip") {
      setEditStatus("ok", "Showing the CAD model. Generate motion files when you are ready.");
      if (status) {
        status.className = "status ok";
        status.textContent = "Model visible. Motion generation skipped.";
      }
      return;
    }
    kind = choice.action;
    if (choice.remember) setSimMotionAfterGenPref(kind, { announce: true });
  }

  await authorJakeRobotDescription({ source, kind, openMotion: true });
}

