document.getElementById("viewport-generation-user")?.addEventListener("click", async (event) => {
  event.stopPropagation();
  const btn = document.getElementById("viewport-generation-user");
  if (!btn) return;
  const people = viewportCollaboratorGenerators.length
    ? viewportCollaboratorGenerators
    : collaboratorPeopleForBadge(allProjects.find((p) => p.id === projectId)?.generation);
  if (people.length > 1 && !viewportGenerationUserExpanded) {
    viewportGenerationUserExpanded = true;
    syncViewportGenerationUserBadge(allProjects.find((p) => p.id === projectId)?.generation);
    return;
  }
  const personEl = event.target.closest(".vgu-person");
  if (people.length > 1 && viewportGenerationUserExpanded && !personEl) return;
  const person = personEl
    ? people.find((p) => (
      (personEl.dataset.userId && p.by_user_id === personEl.dataset.userId)
      || (!personEl.dataset.userId && p.by_user_name === personEl.dataset.user)
    )) || people[0]
    : people[0];
  if (!person) return;
  const gen = person.job || allProjects.find((p) => p.id === projectId)?.generation || {};
  if (!latestPromptHistoryEntries.length && projectId) {
    try {
      const data = await api(`/api/projects/${projectId}/prompt-history`);
      latestPromptHistoryEntries = data.entries || [];
    } catch {
      latestPromptHistoryEntries = [];
    }
  }
  const recentPrompts = latestPromptsForGenerationUser(
    person.by_user_id || gen.by_user_id || personEl?.dataset.userId || "",
    person.by_user_name || gen.by_user_name || personEl?.dataset.user || "",
  );
  const latestPrompt = recentPrompts[0]?.prompt
    || gen.prompt
    || personEl?.dataset.prompt
    || btn.dataset.prompt
    || "";
  const user = person.by_user_name || btn.dataset.user || "Someone";
  showAiComposePanel();
  const statusEl = document.getElementById("prompt-status");
  if (statusEl) {
    statusEl.className = "status ok";
    statusEl.textContent = latestPrompt
      ? `Copied to clipboard: latest prompt by ${user}`
      : `${user} is generating. No prompt text found to copy.`;
  }
  if (latestPrompt) {
    const ok = await copyText(latestPrompt);
    setEditStatus(ok ? "ok" : "error", ok ? "Copied to clipboard: latest prompt." : "Could not copy prompt.");
  }
  showViewportPromptDropdown(personEl || btn, recentPrompts.length
    ? recentPrompts
    : (latestPrompt ? [{ prompt: latestPrompt, user_id: person.by_user_id, user_name: user }] : []));
});

