      if (!next) return { ok: false, error: "The design proposal has no CAD prompt." };
      const frozenFilename = String(selectedFilename || "");
      if (targetMode === "edit" && !designModelState().targets.some((item) => item.filename === frozenFilename)) {
        return { ok: false, error: "The working model is no longer available. Choose another model and try again." };
      }
      // Trial/shared subscription availability can change after the page loads.
      // Refresh immediately before the paid harness boundary so a vanished trial
      // host is removed and the user's already-active saved key becomes selected.
      await refreshPromptAiKeysFromServer();
      if (targetMode === "edit" && !selectDesignModel(frozenFilename)) {
        return { ok: false, error: "The working model is no longer available. Choose another model and try again." };
      }
      if (typeof composer?.setPromptText === "function") composer.setPromptText(next);
      else {
        const input = document.getElementById("prompt-input");
        if (input) input.value = next;
      }
      if (targetMode) setPromptTargetMode(targetMode);
