  async function openSharedPreviewIntoProject(token) {
    const cleanToken = String(token || "").trim();
    if (!cleanToken) return;
    setEditStatus("loading", "Opening shared preview options...");
    try {
      const meta = await rawFetch(`/api/share/${encodeURIComponent(cleanToken)}`)
        .then((res) => res.ok ? res.json() : Promise.reject(new Error("Could not load shared preview")));
      showSharedPreviewArrivalModal(cleanToken, meta);
    } catch (err) {
      setEditStatus("error", err?.message || "Could not remix shared preview.");
    }
  }

  function shareDownloadUrl(token, meta) {
    const filename = meta?.filename || meta?.source_model?.filename || "";
    return filename ? `/api/share/${encodeURIComponent(token)}/files/${encodeURIComponent(filename)}` : `/share/${encodeURIComponent(token)}`;
  }

  function showSharedPreviewArrivalModal(token, meta) {
    document.querySelector(".share-arrival-modal")?.remove();
    const projects = (allProjects || []).filter((project) => project?.id && !isAnonymousPublicProject(project.id));
    const currentProject = projectId && projects.find((project) => project.id === projectId);
    const options = projects.map((project) => `
      <option value="${appEscapeHtml(project.id)}"${project.id === projectId ? " selected" : ""}>
        ${appEscapeHtml(project.name || project.id)}
      </option>
    `).join("");
    const sharer = meta?.shared_by;
    const workspaces = sharedWorkspacesFromTeams(allTeams, {
      personalTeamId: personalWorkspaceId(),
      currentUserId: currentUser?.id,
    });
    const modal = document.createElement("div");
    modal.className = "auth-modal share-arrival-modal";
    modal.setAttribute("role", "dialog");
    modal.setAttribute("aria-modal", "true");
    modal.innerHTML = `
      <div class="auth-backdrop" data-share-arrival-close></div>
      <div class="auth-card share-arrival-card">
        <button type="button" class="auth-close" data-share-arrival-close aria-label="Close remix options">&times;</button>
        <div class="share-arrival-head">
          <div class="share-arrival-icon" aria-hidden="true">R</div>
          <div>
            <p class="share-arrival-eyebrow">Shared Render3D model</p>
            <h2>What do you want to do?</h2>
            <p>${appEscapeHtml(meta?.project_name || meta?.filename || "Shared model")}</p>
          </div>
        </div>
        <div class="share-arrival-targets">
          <label class="share-arrival-target">
            <input type="radio" name="share-arrival-target" value="new" checked />
            <span><strong>Import to a new project</strong><small>Create a clean editable copy and open it in the editor.</small></span>
          </label>
          <label class="share-arrival-target">
            <input type="radio" name="share-arrival-target" value="existing" ${projects.length ? "" : "disabled"} />
            <span><strong>Select a current project</strong><small>Add the shared files to one of your projects.</small></span>
          </label>
          <select class="share-arrival-project-select" disabled>
            ${projects.length ? options : '<option value="">No editable projects found</option>'}
          </select>
          <div class="share-arrival-workspace-host">${sharedWorkspacePickerHtml({
      workspaces,
      sharer,
      prefix: "share-arrival",
      escapeHtml: appEscapeHtml,
    })}</div>
        </div>
        <div class="share-arrival-actions">
          <button type="button" class="share-arrival-action share-arrival-action--primary" data-share-action="open">Create project & open editor</button>
          <button type="button" class="share-arrival-action" data-share-action="slicer">${(() => {
        const s = getPreferredSlicer();
        return s ? slicerExportLabel(s) : "Export to slicer";
      })()
      }</button>
          <button type="button" class="share-arrival-action" data-share-action="fusion">Export to Fusion 360</button>
          <button type="button" class="share-arrival-action" data-share-action="onshape">Export to Onshape</button>
          <button type="button" class="share-arrival-action" data-share-action="download">Download</button>
        </div>
        <p class="share-arrival-status muted small"></p>
      </div>
    `;
    document.body.appendChild(modal);
    bindSharedWorkspacePicker(modal);
    const status = modal.querySelector(".share-arrival-status");
    const select = modal.querySelector(".share-arrival-project-select");
    const workspaceHost = modal.querySelector(".share-arrival-workspace-host");
    const primaryBtn = modal.querySelector("[data-share-action='open']");
    const close = () => {
      modal.remove();
      const cleanUrl = `${window.location.pathname}${window.location.hash || ""}`;
      window.history.replaceState({}, "", cleanUrl || "/");
      setEditStatus("ok", "Shared preview options closed.");
    };
    modal.querySelectorAll("[data-share-arrival-close]").forEach((btn) => btn.addEventListener("click", close));
    modal.querySelectorAll('input[name="share-arrival-target"]').forEach((input) => {
      input.addEventListener("change", () => {
        const existing = modal.querySelector('input[name="share-arrival-target"]:checked')?.value === "existing";
        select.disabled = !existing || !projects.length;
        workspaceHost?.classList.toggle("hidden", existing);
        if (primaryBtn) primaryBtn.textContent = existing ? "Import into project" : "Create project & open editor";
      });
    });

    const importShare = async () => {
      const targetMode = modal.querySelector('input[name="share-arrival-target"]:checked')?.value || "new";
      const targetProjectId = targetMode === "existing" ? (select.value || "") : "";
      if (targetMode === "existing" && !targetProjectId) throw new Error("Choose a project first.");
      const workspace = readSharedWorkspacePicker(modal);
      if (targetMode === "new" && workspace.mode === "existing" && !workspace.teamId) {
        throw new Error("Choose a shared workspace, or create a new one.");
      }
      status.textContent = targetMode === "existing" ? "Importing into selected project..." : "Creating editable remix project...";
      return api(`/api/share/${encodeURIComponent(token)}/open-in-project`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(remixOpenBody(workspace, { targetProjectId })),
      });
    };

    modal.querySelector(".share-arrival-actions")?.addEventListener("click", async (event) => {
      const btn = event.target.closest("[data-share-action]");
      if (!btn) return;
      const action = btn.dataset.shareAction;
      modal.querySelectorAll(".share-arrival-action").forEach((el) => (el.disabled = true));
      status.textContent = action === "download" ? "Preparing download..." : "Preparing shared model...";
      try {
        if (action === "download") {
          window.open(shareDownloadUrl(token, meta), "_blank", "noopener");
          close();
          return;
        }
        const data = await importShare();
        const collaboration = data.shared_with_sharer ? " Shared with the original sharer for collaboration." : "";
        await enterRemixedProject(data, {
          message: `Opened remix as ${data.filename || "a Render3D project"}.${collaboration}`,
        });
        if (action === "open") return;
        const anchor = document.getElementById("btn-export-model") || document.body;
        await openFileExportMenu({
          api,
          projectId: data.project_id,
          filename: data.filename || meta?.filename,
          anchorEl: anchor,
          autoAction: action,
        });
      } catch (err) {
        status.textContent = err?.message || "Could not complete this action.";
        modal.querySelectorAll(".share-arrival-action").forEach((el) => (el.disabled = false));
      }
    });

    requestAnimationFrame(() => modal.querySelector(".share-arrival-action--primary")?.focus());
  }

  async function resumePendingShareAction({ shareModalOpened = false } = {}) {
    const pending = takePendingShareAction();
    if (!pending?.kind) return;
    if (pending.kind === "share-history-profile") {
      const dest = String(pending.returnTo || "");
      if (dest.startsWith("/share/")) location.assign(dest);
      return;
    }
    if (pending.kind === "remix-share" || pending.kind === "remix") {
      if (shareModalOpened) return;
      if (pending.token) await openSharedPreviewIntoProject(pending.token);
      return;
    }
    if (pending.kind === "remix-viewport" || pending.kind === "remix" || pending.kind === "add-new-project") {
      await runViewportRemix(pending.projectId || projectId);
      return;
    }
    if (pending.kind === "remix-into-current" || pending.kind === "add-current-project") {
      const proj = (allProjects || []).find((p) => String(p.id) === String(pending.projectId)) || { id: pending.projectId };
      await applyOnlineModelAction("add-current-project", proj);
      return;
    }
    if (pending.kind === "online-models" || pending.kind === "open-catalog") {
      openOnlineModelsCatalog({ tab: "public" });
      return;
    }
    if (pending.kind === "copy-share" || pending.kind === "share-workspace" || pending.kind === "share-slack" || pending.kind === "share-discord") {
      if (!pending.projectId || !pending.filename) return;
      await openFileExportMenu({
        api,
        projectId: pending.projectId,
        filename: pending.filename,
        anchorEl: document.body,
        shareContext: pending.shareContext || currentVisibleShareContext,
        openWorkspacePicker: pending.kind === "share-workspace",
        autoAction: pending.kind === "share-slack" || pending.kind === "share-discord" ? pending.kind : null,
        title: `Share ${pending.filename}`,
      });
    }
  }

  const auth = createAuthUI({
    api,
    onUserMenuOpen: () => {
      void refreshWorkspaceAiUsage();
    },
    onReady: async (data) => {
      currentUser = data.user;
      bindQuestUser(data.user);
      pendingGoogleNewUserWalkthrough = data?.social_new === true
        && String(data?.social_provider || "").toLowerCase() === "google";
      renderAgentUi?.setUser?.(data.user, { suppressOnboarding: pendingGoogleNewUserWalkthrough });
      allTeams = data.teams || [];
      if (data.ai && !data.ai.deferred) aiKeyUi.render(data.ai);
      connectUserRealtime();
      renderTeams();
      await startApp();
      maybePromptMissingHandle(data.user);
      maybeStartGoogleNewUserWalkthrough(data);
      pendingGoogleNewUserWalkthrough = false;
      if (askAgentParam) {
        setTimeout(() => renderAgentUi?.openWithQuestion?.(askAgentParam, {
          autoSend: missingSettingParam === "1",
          missingSetting: missingSettingParam === "1",
        }), 250);
      }
      if (openPrefsParam) {
        setTimeout(() => {
          window.dispatchEvent(new CustomEvent("render3d:open-preferences-tab", { detail: { tab: openPrefsParam } }));
        }, 300);
      }
      if (importViewportLayoutParam || installViewportLayoutParam || vpLayoutImportedParam) {
        setTimeout(() => void consumeViewportLayoutQuery({
          token: importViewportLayoutParam,
          listingId: installViewportLayoutParam,
          imported: vpLayoutImportedParam,
        }), 400);
      }
      if (openShareParam) {
        await openSharedPreviewIntoProject(openShareParam);
      }
      await resumePendingShareAction({ shareModalOpened: !!openShareParam });
      await restoreOnlineModelsAfterAuth();
      if (shouldRevealViewportShellAfterBoot() && !onlineModelsPanel?.isOpen?.()) enterStudioViewportShell();
      if (projectShareParam) {
        try {
          const accepted = await api(`/api/projects/share-invites/${encodeURIComponent(projectShareParam)}/accept`, {
            method: "POST",
          });
          setEditStatus("ok", accepted?.copied_to_mine
            ? "Shared project copied into your files."
            : "Shared project added to your files.");
          try {
            await refreshWorkspaceRealtimeEditor?.();
          } catch (_) { }
          const openId = accepted?.copy_project_id || accepted?.project_id;
          if (openId) {
            await openProjectById?.(openId);
          }
          if (String(accepted?.role || "") === "editor") maybeShowSharedProjectsHint();
        } catch (err) {
          setEditStatus("error", err.message || "Could not accept project share.");
        }
        const params = new URLSearchParams(window.location.search);
        params.delete("project_share");
        const qs = params.toString();
        window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}${window.location.hash || ""}` || "/");
      }
      if (joinProjectParam) {
        try {
          const joined = await api(`/api/projects/join/${encodeURIComponent(joinProjectParam)}`, {
            method: "POST",
          });
          const role = String(joined?.role || "viewer");
          setEditStatus("ok", joined?.already_member
            ? "You're already on this shared project."
            : (role === "editor"
              ? "Joined the shared project as an editor."
              : role === "remixer"
                ? "Joined the shared project as a remixer."
                : "Joined the shared project as a viewer."));
          try {
            await refreshWorkspaceRealtimeEditor?.();
          } catch (_) { }
          if (joined?.project_id) {
            await openProjectById?.(joined.project_id);
          }
          if (role === "editor") maybeShowSharedProjectsHint();
        } catch (err) {
          setEditStatus("error", err.message || "Could not join this project.");
        }
        const joinParams = new URLSearchParams(window.location.search);
        joinParams.delete("join_project");
        const joinQs = joinParams.toString();
        window.history.replaceState({}, "", `${window.location.pathname}${joinQs ? `?${joinQs}` : ""}${window.location.hash || ""}` || "/");
      }
    },
  });
  authUi = auth;

  if (askAgentParam && !getToken?.()) {
    // Prompt sign-in; question opens after onReady.
    setTimeout(() => authUi?.openModal?.(), 300);
  }
  if (openShareParam && !getToken?.()) {
    setTimeout(() => authUi?.openModal?.(), 300);
  }
  if ((signinParam || mustAuthBeforeRemixOrShare(getToken())) && !getToken?.() && (openShareParam || signinParam)) {
    setTimeout(() => authUi?.openModal?.({ tab: "login" }), 300);
  }
  if (projectShareParam && !getToken?.()) {
    setTimeout(() => authUi?.openModal?.(), 300);
  }
  if (joinProjectParam && !getToken?.()) {
    setTimeout(() => authUi?.openModal?.(), 300);
  }

  window.addEventListener("render3d:require-auth", (event) => {
    const action = event.detail;
    if (action?.kind) savePendingShareAction(action);
    authUi?.openModal?.({ tab: action?.tab || "login" });
  });

  let teleopAuthPromptAt = 0;
  window.addEventListener("render3d:teleop-auth-required", (event) => {
    setDimosTeleopArmed(false);
    const message = event.detail?.message
      || "Render sign-in expired on this headset. Sign in again, then reconnect VR controls.";
    setEditStatus("error", message);
    const now = Date.now();
    if (now - teleopAuthPromptAt < 1500) return;
    teleopAuthPromptAt = now;
    authUi?.openModal?.({ tab: "login" });
  });

  window.addEventListener("render3d:open-fusion-library", () => {
    const appEl = document.getElementById("app");
    if (appEl?.classList.contains("left-panel-hidden")) {
      appEl.classList.remove("left-panel-hidden");
      const reopen = document.getElementById("sidebar-reopen-tab");
      if (reopen) reopen.style.display = "none";
      try {
        window.Render3DPanels?.setSidebarHidden?.(false);
      } catch (_) { }
    }
    // CAD sections live in the logo-rail popup / viewport dock — do not scroll the sidebar.
  });

  // Onshape Library panel — initialised once; auto-loads when scrolled into view
  initOnshapePanel({
    api,
    getCurrentProjectId: () => projectId,
    onImported: async (importedProjectId, filename, name) => {
      await loadProject(importedProjectId);
      await loadModel(`/api/projects/${importedProjectId}/files/${encodeURIComponent(filename)}`, filename, {
        projectId: importedProjectId,
        catalogFilename: filename,
        label: name,
      });
    },
    onView: async (viewProjectId, filename, name) => {
      await loadProject(viewProjectId);
      await loadModel(`/api/projects/${viewProjectId}/files/${encodeURIComponent(filename)}`, filename, {
        projectId: viewProjectId,
        catalogFilename: filename,
        label: name,
      });
    },
  });

  initFusionPanel({
    api,
    getCurrentProjectId: () => projectId,
    getCurrentProjectLabel: () => currentProjectLabel(),
    getSelectedFile: () => selectedFile,
    getWorkspaceId: () => getSelectedWorkspaceId(),
    resolveImportDestination: (files, opts) => resolveFusionImportDestination(files, opts),
    onImported: async (importedProjectId, filename, name, result = {}) => {
      upsertProjectInList({ id: importedProjectId, name: name || importedProjectId });
      const intoCurrent = !!(result.into_existing || (importedProjectId && importedProjectId === projectId));
      const hadComponents = typeof projectAssembly?.count === "function" && projectAssembly.count() > 0;
      try { await refreshProjectShell({ forceExplorer: true }); } catch (_) { }
      if (!intoCurrent) {
        await openProjectById(importedProjectId);
      } else {
        try { await refreshFiles(); } catch (_) { }
        try { await refreshTimeline(); } catch (_) { }
      }
      if (!filename) return;
      try {
        await loadModel(projectFileUrl(importedProjectId, filename), filename, {
          projectId: importedProjectId,
          catalogFilename: filename,
          label: name,
          cacheBust: true,
          fitView: !hadComponents,
          append: intoCurrent,
        });
        try { await refreshTimeline(); } catch (_) { }
        setEditStatus("ok", intoCurrent
          ? `Imported ${name || filename} into this project.`
          : `Imported ${name || filename} from Fusion.`);
      } catch (err) {
        setEditStatus("error", err?.message || "Fusion file imported, but it did not open in the viewport.");
      }
    },
    onView: async (viewProjectId, filename, name) => {
      await loadProject(viewProjectId);
      await loadModel(`/api/projects/${viewProjectId}/files/${encodeURIComponent(filename)}`, filename, {
        projectId: viewProjectId,
        catalogFilename: filename,
        label: name,
      });
    },
    onOpenProject: async (openProjectId) => {
      await loadProject(openProjectId);
    },
    onStatus: (kind, message) => setEditStatus(kind, message),
    onMirrorLinked: () => void refreshWorkspaceRealtimeEditor(),
    onCopiedToMine: async (copiedProjectId, detail) => {
      if (!copiedProjectId) return;
      await adoptCopiedProject(
        { project_id: copiedProjectId, copied_to_mine: true },
        { message: detail || "Copied this shared project into your files for Fusion." },
      );
    },
  });

  try { createCadLibraryRail(); } catch (_) { /* rail optional */ }

  async function restoreSessionSnapshot() {
    const snap = readPendingRestore();
    if (!snap?.projectId) return false;
    clearPendingRestore();
    try {
      const sel = document.getElementById("team-select");
      if (snap.workspaceId && sel && [...sel.options].some((opt) => opt.value === snap.workspaceId)) {
        if (sel.value !== snap.workspaceId) {
          sel.value = snap.workspaceId;
          writeSavedWorkspaceId(snap.workspaceId);
        }
      }
      revealDesktopProjectViewport({ forceSolid: true });
      if (projectId !== snap.projectId) {
        await loadProject(snap.projectId);
      }
      if (snap.selectedFile && projectId === snap.projectId && selectedFile !== snap.selectedFile) {
        const file = snap.selectedFile;
        if (isDxfDrawingFilename(file)) {
          await openDxfDrawingByName(file, { projectId });
        } else if (!isComponentHidden(file)) {
          await loadModel(projectFileUrl(projectId, file), file, {
            projectId,
            catalogFilename: file,
            fitView: false,
          });
          selectAssemblyComponent(file, { fitView: false });
        }
      }
      captureSessionSnapshot();
      return true;
    } catch (err) {
      console.warn("Session restore failed:", err);
      return false;
    }
  }

  async function startApp() {
    try {
      try { console.debug("[studio-boot]", `${Math.round(performance.now())}ms`, "startApp"); } catch (_) { }
      try { hydrateProjectListFromCache(); } catch (_) { }
      void hydratePersonalPins();
      try { renderProjectList(); } catch (_) { }
      if (shouldRevealViewportShellAfterBoot()) enterStudioViewportShell();
      try { clearGlobalComposeDraft(); } catch (_) { }
      try { safeRestoreActiveModelPromptState(); } catch (_) { }
      const urlProject = new URLSearchParams(window.location.search).get("project");
      const bootPid = String(window.__xrBootPreferredProjectId || "").trim();
      const snap = readPendingRestore();
      const lastId = urlProject || bootPid || snap?.projectId || readLastProjectId();
      window.setTimeout(() => { void hydrateAiKeysFromServer(); }, 2500);
      const listP = onWorkspaceChange({ deferProjectPick: true }).catch((err) => {
        console.warn("workspace list load failed:", err);
      });
      void listP.then(() => { try { renderProjectList(); } catch (_) { } });
      if (lastId) {
        try {
          try { console.debug("[studio-boot]", `${Math.round(performance.now())}ms`, "openProject", lastId); } catch (_) { }
          await openProjectById(lastId, { replaceUrl: !!urlProject, throwOnError: true });
          try { console.debug("[studio-boot]", `${Math.round(performance.now())}ms`, "openProject-done"); } catch (_) { }
          clearPendingRestore();
          captureSessionSnapshot();
        } catch (err) {
          console.warn("Boot project open failed:", err);
          if (urlProject) removeProjectUrlParam();
          const restored = await restoreSessionSnapshot();
          if (!restored) await ensureProject();
        }
      } else {
        const restored = await restoreSessionSnapshot();
        if (!restored) await ensureProject();
        else captureSessionSnapshot();
      }
      void resumeGenerationFromProjects();
      if (webglAvailable && !isLiveXrPresenting()) {
        if (projectId && Number(projectAssembly.count?.() || 0) === 0 && !(workspaceModes?.isWiring?.())) {
          try { await recoverDesktopMeshesAfterWebgl({ reload: true }); } catch (_) { }
        } else {
          try { revealDesktopProjectMeshes(); } catch (_) { }
          try { applyHandheldDesktopPlacement(); } catch (_) { }
        }
      }
      if (shouldRevealViewportShellAfterBoot()) enterStudioViewportShell();
      activityLog.refreshServerDebounced();
      requestAnimationFrame(() => requestAnimationFrame(() => {
        document.querySelector(".sidebar.left .left-scroll")?.scrollTo?.({ top: 0, left: 0 });
      }));
    } catch (err) {
      console.error("startApp failed:", err);
      setEditStatus("error", err.message || "Failed to load workspace");
      try { showEmptyProjectViewport(); } catch (_) { }
      renderProjectList();
    }
  }

  async function onWorkspaceChange({ deferProjectPick = false } = {}) {
    const rawId = document.getElementById("team-select")?.value || "";
    const id = getSelectedWorkspaceId();
    writeSavedWorkspaceId(rawId);
    updateWorkspaceRenameButton();
    try {
      await fetchAllProjects();
    } catch {
      renderProjectList();
      return;
    }
    renderProjectList();
    // Invite suggestions and membership UI do not gate the project list or its
    // first model. These used to be two serial network waits before fetching it.
    void Promise.allSettled([refreshTeamMembers(), refreshInviteCandidates()]);
    void refreshWorkspaceHistory();
    // Fusion realtime trees load when the popup opens — prefetching them on
    // every workspace change queued /api/projects and the viewport GLB.
    void refreshWorkspaceAiUsage();
    if (projectId && !allProjects.some((p) => p.id === projectId)) {
      const stillThere = await ensureActiveProjectListed(projectId);
      renderProjectList();
      if (stillThere) return;
    }
    if (projectId && allProjects.some((p) => p.id === projectId)) return;
    if (deferProjectPick) return;
    const last = localStorage.getItem(LS_LAST_PROJECT);
    if (last && allProjects.some((p) => p.id === last)) return;
    if (allProjects.length) {
      await loadProject(allProjects[0].id);
    } else if (projectId) {
      projectId = null;
      ribbon.setProjectId(null);
      setProjectHeader(null, null);
      clearModel();
      const list = document.getElementById("file-list");
      if (list) list.innerHTML = "";
    }
  }

  function getActiveTeam() {
    const teamId = document.getElementById("team-select")?.value || allTeams[0]?.id;
    if (!teamId || teamId === "__all__") return null;
    return allTeams.find((t) => t.id === teamId) || null;
  }

  function renderSharedWorkspaceMenu() {
    const btn = document.getElementById("btn-shared-workspaces-menu");
    const menu = document.getElementById("shared-workspaces-menu");
    if (!btn || !menu) return;
    const personalId = personalWorkspaceId();
    const sharedTeams = allTeams
      .filter((team) => isSharedWorkspace(team))
      .sort((a, b) => String(a.name || "").localeCompare(String(b.name || "")));
    const hidden = hiddenWorkspaceIds();
    const listedTeams = (() => {
      const personalTeam = allTeams.find((t) => t.id === personalId) || null;
      return [...(personalTeam ? [personalTeam] : []), ...sharedTeams];
    })();
    const visibleCount = listedTeams.filter((team) => !hidden.has(String(team.id))).length;
    let activeId = document.getElementById("team-select")?.value || "";
    if (activeId === "__all__") activeId = personalId || listedTeams[0]?.id || "";
    const hasTeams = allTeams.length > 0;
    btn.hidden = !hasTeams;
    btn.title = listedTeams.length
      ? `${visibleCount}/${listedTeams.length} workspace${listedTeams.length === 1 ? "" : "s"} visible · click to switch`
      : "Manage workspaces";
    btn.classList.toggle("has-hidden-workspaces", listedTeams.length > 0 && visibleCount < listedTeams.length);
    menu.innerHTML = hasTeams
      ? `
        <div class="shared-workspaces-menu-title">
          <strong>Workspaces</strong>
          <small>${visibleCount}/${listedTeams.length} visible</small>
        </div>
        <p class="shared-workspace-menu-hint">Check to show a workspace in Projects · click a name to make it active</p>
        ${listedTeams.map((team) => {
        const checked = !hidden.has(String(team.id));
        const active = activeId === team.id;
        const personal = team.id === personalId;
        const members = workspaceMemberCount(team);
        const meta = personal
          ? "Personal workspace"
          : `👥 ${members} member${members === 1 ? "" : "s"}`;
        return `
            <div class="shared-workspace-menu-row${active ? " is-active" : ""}">
              <button type="button" class="shared-workspace-menu-switch" role="menuitem" data-shared-workspace-switch="${appEscapeHtml(team.id)}" aria-current="${active ? "true" : "false"}">
                <strong>${appEscapeHtml(personal ? personalWorkspaceLabel() : (team.name || "Shared workspace"))}</strong>
                <small>${appEscapeHtml(meta)}</small>
              </button>
              <label class="shared-workspace-menu-check" title="${checked ? "Hide from Projects" : "Show in Projects"}">
                <input type="checkbox" class="shared-workspace-check-input" data-shared-workspace-visible="${appEscapeHtml(team.id)}" ${checked ? "checked" : ""} />
                <span class="shared-workspace-check-ui" aria-hidden="true"></span>
              </label>
            </div>
          `;
      }).join("")}
      `
      : `<p class="muted small">Sign in to manage workspaces.</p>`;
  }

  function visibleTeamsForExplorer() {
    const hidden = hiddenWorkspaceIds();
    const visible = allTeams.filter((t) => !hidden.has(String(t.id)));
    const teams = visible.length ? visible : allTeams;
    const personalId = personalWorkspaceId(teams);
    return [...teams].sort((a, b) => {
      if (a.id === personalId) return -1;
      if (b.id === personalId) return 1;
      const ac = workspaceMemberCount(a);
      const bc = workspaceMemberCount(b);
      const aShared = a.id !== personalId;
      const bShared = b.id !== personalId;
      if (aShared !== bShared) return aShared ? 1 : -1;
      if (bc !== ac) return bc - ac;
      return String(a.name || "").localeCompare(String(b.name || ""));
    });
  }

  function updateWorkspaceRenameButton() {
    const btn = document.getElementById("btn-rename-workspace");
    const team = getActiveTeam();
    if (!btn) return;
    const isOwner = team?.role === "owner";
    btn.hidden = !isOwner;
    btn.disabled = !isOwner;
  }

  function renderTeams() {
    const sel = document.getElementById("team-select");
    if (!sel) return;
    sel.innerHTML = "";
    // Hidden select keeps every team so the Projects folder menu can switch freely.
    // Visibility checkboxes only filter what appears in the project browser.
    const explorerTeams = (() => {
      const personalId = personalWorkspaceId(allTeams);
      return [...allTeams].sort((a, b) => {
        if (a.id === personalId) return -1;
        if (b.id === personalId) return 1;
        const ac = workspaceMemberCount(a);
        const bc = workspaceMemberCount(b);
        const aShared = a.id !== personalId;
        const bShared = b.id !== personalId;
        if (aShared !== bShared) return aShared ? 1 : -1;
        if (bc !== ac) return bc - ac;
        return String(a.name || "").localeCompare(String(b.name || ""));
      });
    })();
    const personalTeams = explorerTeams.filter((team) => isPersonalWorkspace(team));
    const sharedTeams = explorerTeams.filter((team) => !isPersonalWorkspace(team));
    const appendTeamOption = (parent, team) => {
      const opt = document.createElement("option");
      opt.value = team.id;
      const members = workspaceMemberCount(team);
      opt.textContent = isPersonalWorkspace(team)
        ? personalWorkspaceLabel()
        : `${team.name}${members > 1 ? ` · 👥 ${members}` : " · shared"}`;
      parent.appendChild(opt);
    };
    personalTeams.forEach((team) => appendTeamOption(sel, team));
    sharedTeams.forEach((team) => appendTeamOption(sel, team));
    const saved = readSavedWorkspaceId();
    // Migrate away from the retired "All workspaces" focus option.
    if (saved === "__all__") {
      const fallback = defaultWorkspaceIdForUser(explorerTeams);
      if (fallback) writeSavedWorkspaceId(fallback);
    }
    const savedNow = readSavedWorkspaceId();
    if (savedNow && savedNow !== "__all__" && explorerTeams.some((t) => t.id === savedNow)) {
      const savedTeam = explorerTeams.find((t) => t.id === savedNow);
      const hasUserScopedSave = hasUserScopedSavedWorkspace(savedNow);
      const savedIsOwned = savedTeam?.role === "owner";
      sel.value = hasUserScopedSave || savedIsOwned ? savedNow : defaultWorkspaceIdForUser(explorerTeams);
    } else if (explorerTeams.length) {
      sel.value = defaultWorkspaceIdForUser(explorerTeams);
    }
    sel.onchange = () => {
      sel.classList.toggle("team-select--shared", isSharedWorkspace(getActiveTeam()));
      onWorkspaceChange();
      updateWorkspaceRenameButton();
    };
    updateWorkspaceRenameButton();
    sel.classList.toggle("team-select--shared", isSharedWorkspace(getActiveTeam()));
    const inviteBtn = document.getElementById("btn-open-workspace-invite");
    if (inviteBtn) {
      const active = getActiveTeam();
      const canInvite = !!(active && (active.can_invite || active.role === "owner"));
      inviteBtn.disabled = !canInvite;
      inviteBtn.title = canInvite
        ? "Invite someone to a workspace or shared folder"
        : "You do not have permission to invite people to this workspace";
      inviteBtn.classList.toggle("is-disabled", !canInvite);
    }
    renderSharedWorkspaceMenu();
    refreshTeamMembers();
    refreshTeamInvites();
    workspaceManagement?.syncMenuVisibility?.();
  }

  function placeSharedWorkspaceMenu() {
    const btn = document.getElementById("btn-shared-workspaces-menu");
    const menu = document.getElementById("shared-workspaces-menu");
    if (!btn || !menu || menu.classList.contains("hidden")) return;
    if (menu.parentElement !== document.body) {
      document.body.appendChild(menu);
    }
    const rect = btn.getBoundingClientRect();
    const gap = 8;
    const menuWidth = Math.min(280, window.innerWidth - 16);
    menu.style.width = `${menuWidth}px`;
    menu.style.maxHeight = `${Math.min(420, window.innerHeight - 16)}px`;

    // Prefer aligning to the button's right edge so it stays inside the left sidebar.
    let left = rect.right - menuWidth;
    left = Math.max(8, Math.min(left, window.innerWidth - menuWidth - 8));

    menu.style.left = `${Math.round(left)}px`;
    menu.style.right = "auto";

    // Measure height after width is applied.
    const menuHeight = menu.offsetHeight || 240;
    let top = rect.bottom + gap;
    if (top + menuHeight > window.innerHeight - 8) {
      top = Math.max(8, rect.top - gap - menuHeight);
    }
    menu.style.top = `${Math.round(top)}px`;
  }

  function openSharedWorkspaceMenu() {
    const btn = document.getElementById("btn-shared-workspaces-menu");
    const menu = document.getElementById("shared-workspaces-menu");
    if (!btn || !menu) return;
    renderSharedWorkspaceMenu();
    menu.classList.remove("hidden");
    btn.setAttribute("aria-expanded", "true");
    placeSharedWorkspaceMenu();
  }

  function closeSharedWorkspaceMenu() {
    const btn = document.getElementById("btn-shared-workspaces-menu");
    const menu = document.getElementById("shared-workspaces-menu");
    if (!menu) return;
    menu.classList.add("hidden");
    btn?.setAttribute("aria-expanded", "false");
  }

  async function switchWorkspaceFromMenu(teamId) {
    const sel = document.getElementById("team-select");
    if (!sel || !teamId) return;
    if (teamId !== "__all__" && !allTeams.some((t) => t.id === teamId)) return;
    if (teamId !== "__all__") {
      const hidden = hiddenWorkspaceIds();
      if (hidden.has(String(teamId))) {
        setWorkspaceVisible(teamId, true);
      }
    }
    writeSavedWorkspaceId(teamId);
    renderTeams();
    sel.value = teamId;
    sel.classList.toggle("team-select--shared", isSharedWorkspace(getActiveTeam()));
    renderSharedWorkspaceMenu();
    updateWorkspaceRenameButton();
    closeSharedWorkspaceMenu();
    await onWorkspaceChange();
    await refreshWorkspaceMenuPanel();
  }

  document.getElementById("btn-shared-workspaces-menu")?.addEventListener("click", (event) => {
    event.stopPropagation();
    const menu = document.getElementById("shared-workspaces-menu");
    if (!menu) return;
    if (menu.classList.contains("hidden")) openSharedWorkspaceMenu();
    else closeSharedWorkspaceMenu();
  });

  document.getElementById("shared-workspaces-menu")?.addEventListener("change", async (event) => {
    const input = event.target.closest("[data-shared-workspace-visible]");
    if (!input) return;
    setWorkspaceVisible(input.getAttribute("data-shared-workspace-visible"), input.checked);
    renderTeams();
    placeSharedWorkspaceMenu();
    await onWorkspaceChange();
    await refreshWorkspaceMenuPanel();
  });

  // Menu is portaled to body; bind once via delegation on document for switch clicks
  // after portal, the original element listener still works if we attach to the menu node itself.
  document.addEventListener("click", async (event) => {
    const menu = document.getElementById("shared-workspaces-menu");
    if (!menu || menu.classList.contains("hidden")) return;
    const switchBtn = event.target.closest("[data-shared-workspace-switch]");
    if (switchBtn && menu.contains(switchBtn)) {
      event.preventDefault();
      event.stopPropagation();
      await switchWorkspaceFromMenu(switchBtn.getAttribute("data-shared-workspace-switch"));
      return;
    }
    if (event.target.closest("#btn-shared-workspaces-menu") || menu.contains(event.target)) return;
    closeSharedWorkspaceMenu();
  });

  window.addEventListener("resize", () => placeSharedWorkspaceMenu());
  document.querySelector(".sidebar.left .left-scroll")?.addEventListener("scroll", () => {
    placeSharedWorkspaceMenu();
  }, { passive: true });

  function openWorkspaceRenameModal() {
    const team = getActiveTeam();
    if (!team || team.role !== "owner") return;
    const modal = document.getElementById("workspace-rename-modal");
    const input = document.getElementById("workspace-rename-input");
    const err = document.getElementById("workspace-rename-error");
    if (!modal || !input) return;
    input.value = team.name;
    err?.classList.add("hidden");
    if (err) err.textContent = "";
    modal.classList.remove("hidden");
    input.focus();
    input.select();
  }

  function closeWorkspaceRenameModal() {
    document.getElementById("workspace-rename-modal")?.classList.add("hidden");
  }

  document.getElementById("btn-rename-workspace")?.addEventListener("click", openWorkspaceRenameModal);
  document.querySelectorAll("[data-ws-rename-close]").forEach((el) => {
    el.addEventListener("click", closeWorkspaceRenameModal);
  });
  document.getElementById("btn-workspace-rename-save")?.addEventListener("click", async () => {
    const team = getActiveTeam();
    const input = document.getElementById("workspace-rename-input");
    const err = document.getElementById("workspace-rename-error");
    if (!team || !input) return;
    const name = input.value.trim();
    if (!name || name === team.name) {
      closeWorkspaceRenameModal();
      return;
    }
    err?.classList.add("hidden");
    try {
      const data = await api(`/api/teams/${team.id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name }),
      });
      const updated = data.team;
      const idx = allTeams.findIndex((t) => t.id === team.id);
      if (idx >= 0 && updated) allTeams[idx] = { ...allTeams[idx], ...updated };
      renderTeams();
      const sel = document.getElementById("team-select");
      if (sel) sel.value = team.id;
      closeWorkspaceRenameModal();
    } catch (e) {
      if (err) {
        err.textContent = e.message || "Could not rename workspace";
        err.classList.remove("hidden");
      }
    }
  });
  document.getElementById("workspace-rename-input")?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") document.getElementById("btn-workspace-rename-save")?.click();
  });

  function costText(value) {
    return formatCostUsd(Number(value) || 0) || "$0.00";
  }

  function renderCostBars(daily = []) {
    const recent = daily.slice(-30);
    const max = Math.max(0.000001, ...recent.map((d) => Number(d.total_usd) || 0));
    return `
      <div class="profile-costs-bars" aria-label="Daily AI costs">
        ${recent.map((d) => {
      const mine = Number(d.mine_usd) || 0;
      const shared = Number(d.shared_usd) || 0;
      const total = mine + shared;
      const height = Math.max(3, Math.round((total / max) * 54));
      const minePct = total > 0 ? Math.round((mine / total) * 100) : 0;
      const sharedPct = Math.max(0, 100 - minePct);
      return `
            <div class="profile-cost-bar" title="${appEscapeHtml(d.date)} · ${costText(total)}">
              <span style="height:${height}px">
                <i class="mine" style="height:${minePct}%"></i>
                <i class="shared" style="height:${sharedPct}%"></i>
              </span>
            </div>
          `;
    }).join("")}
      </div>
      <div class="profile-costs-legend">
        <span><i class="mine"></i> Mine</span>
        <span><i class="shared"></i> Shared</span>
      </div>
    `;
  }

  let costsAnalyticsModal = null;
  let costsAnalyticsState = {
    days: 30,
    filter: "all",
    chart: "stacked",
    metric: "cost",
    data: null,
    promptSort: { key: "cost", dir: "desc" },
    expandedProjects: new Set(),
  };

  function filteredCostDaily(data, filter) {
    const daily = data?.daily || [];
    if (filter === "mine") {
      return daily.map((d) => ({ ...d, shared_usd: 0, total_usd: Number(d.mine_usd) || 0 }));
    }
    if (filter === "shared") {
      return daily.map((d) => ({ ...d, mine_usd: 0, total_usd: Number(d.shared_usd) || 0 }));
    }
    if (filter?.startsWith("user:")) {
      const uid = filter.slice(5);
      const user = (data?.shared_users || []).find((u) => u.user_id === uid);
      const byDate = new Map((user?.daily || []).map((d) => [d.date, Number(d.cost_usd) || 0]));
      return daily.map((d) => {
        const shared = byDate.get(d.date) || 0;
        return { ...d, mine_usd: 0, shared_usd: shared, total_usd: shared };
      });
    }
    return daily;
  }

  function svgPointSeries(daily, width, height, pad) {
    const max = Math.max(0.000001, ...daily.map((d) => Number(d.total_usd) || 0));
    const innerW = width - pad.left - pad.right;
    const innerH = height - pad.top - pad.bottom;
    return daily.map((d, i) => {
      const x = pad.left + (daily.length <= 1 ? innerW / 2 : (i / (daily.length - 1)) * innerW);
      const y = pad.top + innerH - ((Number(d.total_usd) || 0) / max) * innerH;
      return { ...d, x, y };
    });
  }

  function renderCostLineChart(data, filter = "all", { area = false } = {}) {
    const daily = filteredCostDaily(data, filter);
    const width = 1000;
    const height = 330;
    const pad = { left: 54, right: 22, top: 18, bottom: 52 };
    const pts = svgPointSeries(daily, width, height, pad);
    const max = Math.max(0.000001, ...daily.map((d) => Number(d.total_usd) || 0));
    const line = pts.map((p) => `${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(" ");
    const areaPath = pts.length
      ? `M ${pts[0].x.toFixed(1)} ${height - pad.bottom} L ${pts.map((p) => `${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(" L ")} L ${pts.at(-1).x.toFixed(1)} ${height - pad.bottom} Z`
      : "";
    const labelEvery = Math.max(1, Math.ceil(daily.length / 14));
    return `
      <div class="costs-modal-chart">
        <svg class="costs-modal-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${area ? "Area" : "Line"} chart of AI costs">
          ${[0, 0.25, 0.5, 0.75, 1].map((t) => {
      const y = pad.top + (height - pad.top - pad.bottom) * t;
      const value = max * (1 - t);
      return `<line class="cost-grid-line ${t === 1 ? "" : "muted"}" x1="${pad.left}" y1="${y}" x2="${width - pad.right}" y2="${y}" /><text class="cost-axis-label" x="8" y="${y + 5}">${costText(value)}</text>`;
    }).join("")}
          ${area && areaPath ? `<path class="cost-area-fill" d="${areaPath}" />` : ""}
          <polyline class="cost-line-total" points="${line}" />
          ${pts.map((p, i) => i % labelEvery === 0 || i === pts.length - 1 ? `<text class="cost-date-label" x="${p.x}" y="${height - 16}" text-anchor="middle">${appEscapeHtml(String(p.date).slice(5))}</text>` : "").join("")}
          ${pts.map((p) => `<circle cx="${p.x}" cy="${p.y}" r="5" fill="var(--accent)" opacity="${Number(p.total_usd) > 0 ? "1" : "0.25"}"><title>${appEscapeHtml(p.date)} · ${costText(p.total_usd)}</title></circle>`).join("")}
        </svg>
      </div>
    `;
  }

  function renderCostUserBars(data) {
    const totals = data?.totals || {};
    const rows = [
      { label: "Mine", sub: "Your prompts", cost: Number(totals.mine_window_usd) || 0, kind: "mine" },
      ...(data?.shared_users || []).map((u) => ({
        label: u.display_name || u.email || "Team member",
        sub: `${u.email || ""}${u.tracked_count ? ` · ${u.tracked_count} tracked` : ""}`,
        cost: Number(u.window_cost_usd) || 0,
        kind: "shared",
      })),
    ].sort((a, b) => b.cost - a.cost);
    const max = Math.max(0.000001, ...rows.map((r) => r.cost));
    return `
      <div class="costs-modal-feature-bars" role="img" aria-label="AI cost by person">
        ${rows.map((row) => {
      const pct = Math.max(1, Math.round((row.cost / max) * 100));
      return `
            <div class="costs-feature-row" title="${appEscapeHtml(row.label)} · ${costText(row.cost)}">
              <span><strong>${appEscapeHtml(row.label)}</strong><small>${appEscapeHtml(row.sub || "")}</small></span>
              <div><i class="${row.kind}" style="width:${pct}%"></i></div>
              <strong>${costText(row.cost)}</strong>
            </div>
          `;
    }).join("") || `<p class="muted small">No cost data in this range.</p>`}
      </div>
    `;
  }

  function costMetricValue(row) {
    const metric = costsAnalyticsState.metric || "cost";
    if (metric === "tokens") return Number(row.total_tokens || 0);
    if (metric === "prompts") return Number(row.display_tracked_count ?? row.tracked_count ?? row.prompt_count ?? 0);
    if (metric === "calls") return Number(row.ai_calls || 0);
    return Number(row.display_cost_usd ?? row.window_cost_usd ?? row.cost ?? 0);
  }

  function costMetricText(row) {
    const metric = costsAnalyticsState.metric || "cost";
    const value = costMetricValue(row);
    if (metric === "tokens") return `${value.toLocaleString()} tokens`;
    if (metric === "prompts") return `${value.toLocaleString()} prompts`;
    if (metric === "calls") return `${value.toLocaleString()} calls`;
    return costText(value);
  }

  function fullCostAndTokenText(row, costKey = "display_cost_usd") {
    const cost = Number(row?.[costKey] ?? row?.window_cost_usd ?? row?.cost_usd ?? row?.cost ?? 0) || 0;
    const tokens = Number(row?.total_tokens || 0) || 0;
    return `${costText(cost)} · ${tokens.toLocaleString()} tokens`;
  }

  function effectiveTokenRateText(cost, tokens) {
    const c = Number(cost) || 0;
    const t = Number(tokens) || 0;
    if (!c || !t) return "";
    return `${costText((c / t) * 1_000_000)} / 1M tok`;
  }

  function projectModelBreakdownHtml(project) {
    const rows = project?.model_breakdown || [];
    if (!rows.length) return `<div class="costs-model-breakdown"><p class="muted small">No per-model breakdown available for this project yet.</p></div>`;
    return `
      <div class="costs-model-breakdown">
        ${rows.map((row) => {
      const cost = Number(row.window_cost_usd || row.total_cost_usd || 0) || 0;
      const tokens = Number(row.total_tokens || 0) || 0;
      const modelLabel = formatModelLabel(row.model, row.provider) || row.model || row.provider || "AI";
      const rate = effectiveTokenRateText(cost, tokens);
      return `
            <div class="costs-model-row">
              <span>
                <strong>${appEscapeHtml(modelLabel)}</strong>
                <small>${appEscapeHtml(row.provider || "AI")} · ${Number(row.prompt_count || 0)} prompts · ${Number(row.ai_calls || 0)} calls${rate ? ` · ${appEscapeHtml(rate)}` : ""}</small>
              </span>
              <span>${Number(row.input_tokens || 0).toLocaleString()} in · ${Number(row.output_tokens || 0).toLocaleString()} out</span>
              <strong>${costText(cost)} · ${tokens.toLocaleString()} tokens</strong>
            </div>
          `;
    }).join("")}
      </div>
    `;
  }

  function filteredCostProjects(data, filter = "all") {
    const projects = data?.projects || [];
    return projects.map((project) => {
      let cost = Number(project.window_cost_usd) || 0;
      let promptCount = Number(project.tracked_count || 0);
      if (filter === "mine") {
        cost = Number(project.mine_window_usd) || 0;
      } else if (filter === "shared") {
        cost = Number(project.shared_window_usd) || 0;
      } else if (filter?.startsWith("user:")) {
        const uid = filter.slice(5);
        const userRow = (project.users || []).find((u) => u.user_id === uid);
        cost = Number(userRow?.window_cost_usd) || 0;
        promptCount = Number(userRow?.tracked_count || 0);
      }
      return { ...project, display_cost_usd: cost, display_tracked_count: promptCount };
    }).filter((project) => project.display_cost_usd > 0 || project.display_tracked_count > 0)
      .sort((a, b) => b.display_cost_usd - a.display_cost_usd);
  }

  function filteredCostPrompts(data, filter = "all") {
    const currentUserId = data?.current_user_id;
    return (data?.recent_prompts || []).filter((prompt) => {
      if (filter === "mine") return prompt.user_id === currentUserId && prompt.key_source !== "team";
      if (filter === "shared") return prompt.user_id !== currentUserId || prompt.key_source === "team";
      if (filter?.startsWith("user:")) return prompt.user_id === filter.slice(5);
      return true;
    });
  }

  function promptSortValue(row, key) {
    if (key === "prompt") return row.prompt || "Untitled prompt";
    if (key === "project") return row.project_name || row.project_id || "";
    if (key === "model") return row.model || row.provider || "AI";
    if (key === "usage") return Number(row.total_tokens || 0);
    if (key === "cost") return Number(row.cost_usd || 0);
    return "";
  }

  function sortedCostPrompts(data, filter = "all") {
    const sort = costsAnalyticsState.promptSort || { key: "cost", dir: "desc" };
    const dir = sort.dir === "asc" ? 1 : -1;
    return [...filteredCostPrompts(data, filter)].sort((a, b) => {
      const av = promptSortValue(a, sort.key);
      const bv = promptSortValue(b, sort.key);
      if (typeof av === "number" || typeof bv === "number") {
        return ((Number(av) || 0) - (Number(bv) || 0)) * dir;
      }
      return String(av).localeCompare(String(bv), undefined, { numeric: true, sensitivity: "base" }) * dir;
    });
  }

  function costPromptSortHeader(key, label) {
    const sort = costsAnalyticsState.promptSort || {};
    const active = sort.key === key;
    const isText = key === "prompt" || key === "project" || key === "model";
    const nextDir = active && sort.dir === "desc" ? "asc" : "desc";
    const hint = isText
      ? (active && sort.dir === "asc" ? "Z-A" : "A-Z")
      : (active && sort.dir === "asc" ? "Highest first" : "Lowest first");
    const arrow = active ? (sort.dir === "asc" ? "↑" : "↓") : "↕";
    return `
      <button type="button"
        class="costs-sort-btn${active ? " active" : ""}"
        data-action="cost-prompt-sort"
        data-sort-key="${appEscapeHtml(key)}"
        data-sort-dir="${appEscapeHtml(nextDir)}"
        title="Sort ${appEscapeHtml(label)} ${appEscapeHtml(hint)}">
        <span>${appEscapeHtml(label)}</span><i aria-hidden="true">${arrow}</i>
      </button>`;
  }

  function renderCostProjectBars(data, filter = "all") {
    const rows = filteredCostProjects(data, filter);
    const max = Math.max(0.000001, ...rows.map((r) => costMetricValue(r)));
    return `
      <div class="costs-modal-feature-bars" role="img" aria-label="AI cost by project">
        ${rows.map((row) => {
      const value = costMetricValue(row);
      const pct = Math.max(1, Math.round((value / max) * 100));
      const expanded = costsAnalyticsState.expandedProjects?.has?.(row.project_id);
      return `
            <div class="costs-project-group">
              <div class="costs-feature-row" title="${appEscapeHtml(row.name)} · ${appEscapeHtml(fullCostAndTokenText(row))}">
                <span><strong>${appEscapeHtml(row.name || row.project_id)}</strong><small>${Number(row.display_tracked_count || 0)} prompts · ${Number(row.total_tokens || 0).toLocaleString()} tokens</small></span>
                <div><i class="project" style="width:${pct}%"></i></div>
                <strong>${appEscapeHtml(fullCostAndTokenText(row))}<button type="button" data-action="cost-project-toggle" data-project-id="${appEscapeHtml(row.project_id)}">${expanded ? "Hide" : "View more"}</button></strong>
              </div>
              ${expanded ? projectModelBreakdownHtml(row) : ""}
            </div>
          `;
    }).join("") || `<p class="muted small">No project cost data in this range.</p>`}
      </div>
    `;
  }

  function renderCostPromptRows(data, filter = "all") {
    const rows = sortedCostPrompts(data, filter);
    return `
      <div class="costs-modal-table" role="table" aria-label="Recent AI prompts and usage">
        <div class="costs-table-head" role="row">
          ${costPromptSortHeader("prompt", "Prompt")}
          ${costPromptSortHeader("project", "Project")}
          ${costPromptSortHeader("model", "Model")}
          ${costPromptSortHeader("usage", "Usage")}
          ${costPromptSortHeader("cost", "Cost")}
        </div>
        ${rows.map((row) => `
          <div class="costs-table-row" role="row" title="${appEscapeHtml(row.prompt || "")}">
            <span>
              <strong>${appEscapeHtml((row.prompt || "Untitled prompt").slice(0, 92))}${(row.prompt || "").length > 92 ? "..." : ""}</strong>
              <small>${appEscapeHtml(row.user_name || "Unknown user")} · ${appEscapeHtml(row.created_at ? new Date(row.created_at).toLocaleString() : "")}</small>
            </span>
            <span>${appEscapeHtml(row.project_name || row.project_id || "")}</span>
            <span>${appEscapeHtml(row.model || row.provider || "AI")}</span>
            <span>${Number(row.total_tokens || 0).toLocaleString()} tokens${row.ai_calls ? ` · ${Number(row.ai_calls)} calls` : ""}</span>
            <strong>${costText(row.cost_usd)}</strong>
          </div>
        `).join("") || `<p class="muted small">No prompt usage in this range.</p>`}
      </div>
    `;
  }

  function renderLargeCostBars(data, filter = "all") {
    const daily = filteredCostDaily(data, filter);
    const max = Math.max(0.000001, ...daily.map((d) => Number(d.total_usd) || 0));
    return `
      <div class="costs-modal-chart">
        ${daily.map((d) => {
      const mine = Number(d.mine_usd) || 0;
      const shared = Number(d.shared_usd) || 0;
      const total = Number(d.total_usd) || mine + shared;
      const height = total > 0 ? Math.max(10, Math.round((total / max) * 320)) : 3;
      const minePct = total > 0 ? Math.round((mine / total) * 100) : 0;
      return `
            <div class="costs-modal-bar" title="${appEscapeHtml(d.date)} · ${costText(total)}">
              <span class="${total > 0 ? "" : "empty"}" style="height:${height}px">
                <i class="mine" style="height:${minePct}%"></i>
                <i class="shared" style="height:${Math.max(0, 100 - minePct)}%"></i>
              </span>
              <em>${appEscapeHtml(d.date.slice(5))}</em>
            </div>
          `;
    }).join("")}
      </div>
    `;
  }

  function renderSelectedCostChart(data, filter = "all") {
    const chart = costsAnalyticsState.chart || "stacked";
    if (chart === "line") return renderCostLineChart(data, filter);
    if (chart === "area") return renderCostLineChart(data, filter, { area: true });
    if (chart === "users") return renderCostUserBars(data);
    if (chart === "projects") return renderCostProjectBars(data, filter);
    if (chart === "prompts") return renderCostPromptRows(data, filter);
    return renderLargeCostBars(data, filter);
  }

  function applyCostChartPrompt(raw) {
    const text = String(raw || "").toLowerCase();
    if (!text.trim()) return;
    if (text.includes("project")) costsAnalyticsState.chart = "projects";
    else if (text.includes("prompt") || text.includes("usage")) costsAnalyticsState.chart = "prompts";
    else if (text.includes("person") || text.includes("people") || text.includes("user") || text.includes("individual")) costsAnalyticsState.chart = "users";
    else if (text.includes("line")) costsAnalyticsState.chart = "line";
    else if (text.includes("area")) costsAnalyticsState.chart = "area";
    else if (text.includes("bar")) costsAnalyticsState.chart = "stacked";
    if (text.includes("token")) costsAnalyticsState.metric = "tokens";
    else if (text.includes("call")) costsAnalyticsState.metric = "calls";
    else if (text.includes("prompt")) costsAnalyticsState.metric = "prompts";
    else if (text.includes("cost") || text.includes("spend") || text.includes("price")) costsAnalyticsState.metric = "cost";
    if (text.includes("mine") || text.includes("my ")) costsAnalyticsState.filter = "mine";
    else if (text.includes("shared") || text.includes("team")) costsAnalyticsState.filter = "shared";
    const dayMatch = text.match(/(\d+)\s*(day|days)/);
    if (dayMatch) costsAnalyticsState.days = Math.min(365, Math.max(7, Number(dayMatch[1]) || 30));
    renderCostsAnalyticsModal();
    if (dayMatch) refreshCostsAnalyticsModal();
  }

  function renderCostDetailSection(data, filter = "all") {
    const chart = costsAnalyticsState.chart || "stacked";
    if (chart === "projects") {
      const projects = filteredCostProjects(data, filter).slice(0, 12);
      return `
        <div class="costs-modal-users">
          <h3>Project comparison</h3>
          ${projects.map((project) => `
            <div class="profile-cost-user">
              <div>
                <strong>${appEscapeHtml(project.name || project.project_id)}</strong>
                <span class="muted small">${Number(project.prompt_count || 0)} prompts · ${Number(project.total_tokens || 0).toLocaleString()} tokens · ${Number(project.ai_calls || 0)} AI calls</span>
              </div>
              <div class="profile-cost-user-stats">
                <strong>${costText(project.display_cost_usd)}</strong>
                <span class="muted small">${costText(project.total_cost_usd)} all time</span>
              </div>
            </div>
            ${costsAnalyticsState.expandedProjects?.has?.(project.project_id) ? projectModelBreakdownHtml(project) : ""}
          `).join("") || `<p class="muted small">No projects with tracked cost in this range.</p>`}
        </div>
      `;
    }
    if (chart === "prompts") {
      const prompts = filteredCostPrompts(data, filter).slice(0, 8);
      return `
        <div class="costs-modal-users">
          <h3>Recent prompts</h3>
          ${prompts.map((prompt) => `
            <div class="profile-cost-user">
              <div>
                <strong>${appEscapeHtml((prompt.prompt || "Untitled prompt").slice(0, 110))}${(prompt.prompt || "").length > 110 ? "..." : ""}</strong>
                <span class="muted small">${appEscapeHtml(prompt.project_name || "")} · ${Number(prompt.total_tokens || 0).toLocaleString()} tokens · ${appEscapeHtml(prompt.model || prompt.provider || "AI")}</span>
              </div>
              <div class="profile-cost-user-stats">
                <strong>${costText(prompt.cost_usd)}</strong>
                <span class="muted small">${appEscapeHtml(prompt.created_at ? new Date(prompt.created_at).toLocaleDateString() : "")}</span>
              </div>
            </div>
          `).join("") || `<p class="muted small">No prompt usage in this range.</p>`}
        </div>
      `;
    }
    const sharedUsers = data.shared_users || [];
    return `
      <div class="costs-modal-users">
        <h3>Shared key users</h3>
        ${sharedUsers.length ? sharedUsers.map((u) => `
          <div class="profile-cost-user">
            <div>
              <strong>${appEscapeHtml(u.display_name || u.email || "Team member")}</strong>
              <span class="muted small">${appEscapeHtml(u.email || "")} · ${Number(u.tracked_count || 0)} tracked prompts</span>
            </div>
            <div class="profile-cost-user-stats">
              <strong>${costText(u.window_cost_usd)}</strong>
              <span class="muted small">${costText(u.total_cost_usd)} all time</span>
            </div>
          </div>
        `).join("") : `<p class="muted small">No shared-key users with access found.</p>`}
      </div>
    `;
  }

  function ensureCostsAnalyticsModal() {
    if (costsAnalyticsModal) return costsAnalyticsModal;
    costsAnalyticsModal = document.createElement("div");
    costsAnalyticsModal.className = "auth-modal hidden";
    costsAnalyticsModal.id = "costs-analytics-modal";
    costsAnalyticsModal.innerHTML = `
      <div class="auth-backdrop" data-costs-close></div>
      <div class="auth-card app-dialog-card costs-modal-card">
        <button type="button" class="auth-close" data-costs-close aria-label="Close">&times;</button>
        <div class="costs-modal-header">
          <div>
            <h2 class="app-dialog-title">AI cost analytics</h2>
            <p class="muted small">Filter spend by range, personal usage, shared usage, or a shared-key user.</p>
          </div>
          <div class="costs-modal-filters">
            <label>Range
              <select id="costs-range-filter">
                <option value="7">Last 7 days</option>
                <option value="14">Last 14 days</option>
                <option value="30">Last 30 days</option>
                <option value="60">Last 60 days</option>
                <option value="90">Last 90 days</option>
                <option value="180">Last 6 months</option>
                <option value="365">Last year</option>
              </select>
            </label>
            <label>View
              <select id="costs-user-filter">
                <option value="all">Mine + shared</option>
                <option value="mine">Mine only</option>
                <option value="shared">Shared only</option>
              </select>
            </label>
            <label>Chart
              <select id="costs-chart-filter">
                <option value="stacked">Stacked bars</option>
                <option value="line">Line</option>
                <option value="area">Area</option>
                <option value="users">By person</option>
                <option value="projects">By project</option>
                <option value="prompts">Recent prompts</option>
              </select>
            </label>
            <label>Metric
              <select id="costs-metric-filter">
                <option value="cost">Cost</option>
                <option value="tokens">Tokens</option>
                <option value="prompts">Prompts</option>
                <option value="calls">AI calls</option>
              </select>
            </label>
          </div>
        </div>
        <div class="costs-quickbar">
          <button type="button" data-cost-chart="projects" data-cost-metric="cost">Compare projects</button>
          <button type="button" data-cost-chart="projects" data-cost-metric="tokens">Project tokens</button>
          <button type="button" data-cost-chart="prompts" data-cost-metric="prompts">Prompt usage</button>
          <button type="button" data-cost-chart="users" data-cost-metric="cost">Compare users</button>
          <label>Prompt chart
            <input id="costs-chart-prompt" type="text" placeholder="e.g. compare project token usage last 90 days" />
          </label>
          <button type="button" id="costs-chart-prompt-run">Build</button>
        </div>
        <div id="costs-analytics-body" class="costs-modal-body">Loading costs...</div>
      </div>
    `;
    document.body.appendChild(costsAnalyticsModal);
    costsAnalyticsModal.querySelectorAll("[data-costs-close]").forEach((el) => {
      el.addEventListener("click", () => costsAnalyticsModal.classList.add("hidden"));
    });
    costsAnalyticsModal.querySelector("#costs-range-filter")?.addEventListener("change", async (e) => {
      costsAnalyticsState.days = Number(e.target.value) || 30;
      await refreshCostsAnalyticsModal();
    });
    costsAnalyticsModal.querySelector("#costs-user-filter")?.addEventListener("change", (e) => {
      costsAnalyticsState.filter = e.target.value;
      renderCostsAnalyticsModal();
    });
    costsAnalyticsModal.querySelector("#costs-chart-filter")?.addEventListener("change", (e) => {
      costsAnalyticsState.chart = e.target.value || "stacked";
      renderCostsAnalyticsModal();
    });
    costsAnalyticsModal.querySelector("#costs-metric-filter")?.addEventListener("change", (e) => {
      costsAnalyticsState.metric = e.target.value || "cost";
      renderCostsAnalyticsModal();
    });
    costsAnalyticsModal.querySelectorAll("[data-cost-chart]").forEach((btn) => {
      btn.addEventListener("click", () => {
        costsAnalyticsState.chart = btn.dataset.costChart || "stacked";
        costsAnalyticsState.metric = btn.dataset.costMetric || costsAnalyticsState.metric || "cost";
        renderCostsAnalyticsModal();
      });
    });
    costsAnalyticsModal.querySelector("#costs-chart-prompt-run")?.addEventListener("click", () => {
      applyCostChartPrompt(costsAnalyticsModal.querySelector("#costs-chart-prompt")?.value);
    });
    costsAnalyticsModal.querySelector("#costs-chart-prompt")?.addEventListener("keydown", (e) => {
      if (e.key === "Enter") applyCostChartPrompt(e.currentTarget.value);
    });
    costsAnalyticsModal.querySelector("#costs-analytics-body")?.addEventListener("click", (e) => {
      const projectToggle = e.target.closest("[data-action='cost-project-toggle']");
      if (projectToggle) {
        const id = projectToggle.dataset.projectId;
        if (id) {
          if (!costsAnalyticsState.expandedProjects) costsAnalyticsState.expandedProjects = new Set();
          if (costsAnalyticsState.expandedProjects.has(id)) costsAnalyticsState.expandedProjects.delete(id);
          else costsAnalyticsState.expandedProjects.add(id);
          costsAnalyticsState.chart = "projects";
          renderCostsAnalyticsModal();
        }
        return;
      }
      const sortBtn = e.target.closest("[data-action='cost-prompt-sort']");
      if (!sortBtn) return;
      costsAnalyticsState.promptSort = {
        key: sortBtn.dataset.sortKey || "cost",
        dir: sortBtn.dataset.sortDir || "desc",
      };
      costsAnalyticsState.chart = "prompts";
      renderCostsAnalyticsModal();
    });
    return costsAnalyticsModal;
  }

  function renderCostsAnalyticsModal() {
    const modal = ensureCostsAnalyticsModal();
    const body = modal.querySelector("#costs-analytics-body");
    const select = modal.querySelector("#costs-user-filter");
    const rangeSelect = modal.querySelector("#costs-range-filter");
    const chartSelect = modal.querySelector("#costs-chart-filter");
    const metricSelect = modal.querySelector("#costs-metric-filter");
    const data = costsAnalyticsState.data;
    if (!body || !data) return;
    const sharedUsers = data.shared_users || [];
    const current = costsAnalyticsState.filter || "all";
    const currentChart = costsAnalyticsState.chart || "stacked";
    if (rangeSelect) rangeSelect.value = String(costsAnalyticsState.days || data.days || 30);
    if (chartSelect) chartSelect.value = currentChart;
    if (metricSelect) metricSelect.value = costsAnalyticsState.metric || "cost";
    if (select) {
      select.innerHTML = `
        <option value="all">Mine + shared</option>
        <option value="mine">Mine only</option>
        <option value="shared">Shared only</option>
        ${sharedUsers.map((u) => `<option value="user:${appEscapeHtml(u.user_id)}">${appEscapeHtml(u.display_name || u.email || "Team member")}</option>`).join("")}
      `;
      select.value = current;
    }
    const totals = data.totals || {};
    body.innerHTML = `
      <div class="costs-modal-summary">
        <div><span>Total</span><strong>${costText(totals.all_window_usd)}</strong></div>
        <div><span>Mine</span><strong>${costText(totals.mine_window_usd)}</strong></div>
        <div><span>Shared</span><strong>${costText(totals.shared_window_usd)}</strong></div>
        <div><span>Tokens</span><strong>${compactTokenCount(totals.total_tokens)}</strong></div>
      </div>
      ${renderSelectedCostChart(data, current)}
      <div class="profile-costs-legend">
        <span><i class="mine"></i> Mine</span>
        <span><i class="shared"></i> Shared</span>
      </div>
      ${renderCostDetailSection(data, current)}
    `;
  }

  let costsRefreshAbort = null; // leakfix53
  function beginCostsFetch() {
    if (costsRefreshAbort) {
      try { costsRefreshAbort.abort(); } catch (_) { /* ignore */ }
    }
    const ctl = new AbortController();
    costsRefreshAbort = ctl;
    return ctl;
  }

  async function refreshCostsAnalyticsModal() {
    const ctl = beginCostsFetch();
    const modal = ensureCostsAnalyticsModal();
    const body = modal.querySelector("#costs-analytics-body");
    if (body && !body.querySelector(".profile-cost-user") && !body.querySelector(".profile-costs-legend")) {
      body.textContent = "Loading costs...";
    }
    try {
      costsAnalyticsState.data = await api(`/api/user/ai-costs?days=${costsAnalyticsState.days}`, { signal: ctl.signal });
      if (ctl.signal.aborted) return;
      renderCostsAnalyticsModal();
    } catch (err) {
      if (ctl.signal.aborted || err?.name === "AbortError") return;
      throw err;
    } finally {
      if (costsRefreshAbort === ctl) costsRefreshAbort = null;
    }
  }

  async function openCostsAnalyticsModal() {
    ensureCostsAnalyticsModal().classList.remove("hidden");
    await refreshCostsAnalyticsModal();
  }

  function setProfileAvatarStatus(message, cls = "muted small") {
    const status = document.getElementById("profile-avatar-status");
    if (!status) return;
    status.className = `${cls} profile-preferences-note`;
    status.textContent = message || "";
  }

  let profileHandleCheckTimer = null;
  let profileHandleCheckSeq = 0;

  function setProfileHandleStatus(state = "idle", message = "Check") {
    const status = document.getElementById("pref-handle-status");
    if (!status) return;
    status.className = `profile-handle-status is-${state}`;
    status.textContent = message;
  }

  function profileHandleValue() {
    return (document.getElementById("pref-handle")?.value || "").trim().replace(/^@+/, "");
  }

  function validateProfileHandleInline(handle) {
    if (!handle) return "Enter a handle";
    if (!/^[A-Za-z0-9][A-Za-z0-9_-]{2,23}$/.test(handle)) {
      return "3–24 letters, numbers, _ or -";
    }
    return "";
  }

  function userNeedsHandle(user = currentUser) {
    return !String(user?.handle || "").trim();
  }

  let claimHandleTimer = null;
  let claimHandleSeq = 0;
  let handleAvailabilityAbort = null; // leakfix76
  function beginHandleAvailabilityFetch() {
    if (handleAvailabilityAbort) {
      try { handleAvailabilityAbort.abort(); } catch (_) { /* ignore */ }
    }
    const ctl = new AbortController();
    handleAvailabilityAbort = ctl;
    return ctl;
  }
  let claimHandleAvailable = false;

  function setClaimHandleStatus(state, message) {
    const el = document.getElementById("handle-claim-status");
    if (!el) return;
    el.className = `profile-handle-status is-${state}`;
    el.textContent = message;
    const submit = document.getElementById("handle-claim-submit");
    if (submit) submit.disabled = state !== "ok";
    claimHandleAvailable = state === "ok";
  }

  function scheduleClaimHandleCheck({ immediate = false } = {}) {
    window.clearTimeout(claimHandleTimer);
    const run = async () => {
      const handle = (document.getElementById("handle-claim-input")?.value || "").trim().replace(/^@+/, "");
      const invalid = validateProfileHandleInline(handle);
      if (invalid) {
        setClaimHandleStatus(handle ? "error" : "idle", handle ? invalid : "@");
        return;
      }
      const seq = ++claimHandleSeq;
      const ctl = beginHandleAvailabilityFetch();
      setClaimHandleStatus("checking", "…");
      try {
        const data = await api(`/api/users/me/handle-availability?handle=${encodeURIComponent(handle)}`, { signal: ctl.signal });
        if (ctl.signal.aborted || seq !== claimHandleSeq) return;
        if (data.valid === false) {
          setClaimHandleStatus("error", data.message || "Invalid");
        } else if (data.available) {
          setClaimHandleStatus("ok", "✓");
        } else {
          setClaimHandleStatus("error", "Taken");
        }
      } catch (err) {
        if (ctl.signal.aborted || err?.name === "AbortError" || seq !== claimHandleSeq) return;
        setClaimHandleStatus("error", err.message || "Could not check");
      } finally {
        if (handleAvailabilityAbort === ctl) handleAvailabilityAbort = null;
      }
    };
    claimHandleTimer = window.setTimeout(run, immediate ? 0 : 320);
  }

  function showHandleClaimModal(show) {
    const modal = document.getElementById("handle-claim-modal");
    if (!modal) return;
    modal.classList.toggle("hidden", !show);
    modal.setAttribute("aria-hidden", show ? "false" : "true");
    if (show) {
      const err = document.getElementById("handle-claim-error");
      if (err) err.textContent = "";
      const input = document.getElementById("handle-claim-input");
      if (input && !input.value) {
        const seed = String(currentUser?.display_name || currentUser?.email || "")
          .split("@")[0]
          .toLowerCase()
          .replace(/[^a-z0-9_-]+/g, "-")
          .replace(/^-+|-+$/g, "")
          .slice(0, 24);
        if (seed.length >= 3) input.value = seed;
      }
      scheduleClaimHandleCheck({ immediate: true });
      setTimeout(() => document.getElementById("handle-claim-input")?.focus(), 50);
    }
  }

  function maybePromptMissingHandle(user = currentUser) {
    if (!user || !getToken()) return false;
    if (!userNeedsHandle(user)) {
      showHandleClaimModal(false);
      return false;
    }
    showHandleClaimModal(true);
    return true;
  }

  document.getElementById("handle-claim-input")?.addEventListener("input", (e) => {
    const el = e.target;
    el.value = String(el.value || "").replace(/[^A-Za-z0-9_-]/g, "");
    const err = document.getElementById("handle-claim-error");
    if (err) err.textContent = "";
    scheduleClaimHandleCheck();
  });

  document.getElementById("handle-claim-form")?.addEventListener("submit", async (e) => {
    e.preventDefault();
    const handle = (document.getElementById("handle-claim-input")?.value || "").trim().replace(/^@+/, "");
    const errEl = document.getElementById("handle-claim-error");
    const invalid = validateProfileHandleInline(handle);
    if (invalid) {
      if (errEl) errEl.textContent = invalid;
      setClaimHandleStatus("error", invalid);
      return;
    }
    if (!claimHandleAvailable) {
      if (errEl) errEl.textContent = "Pick an available username first";
      scheduleClaimHandleCheck({ immediate: true });
      return;
    }
    const submit = document.getElementById("handle-claim-submit");
    if (submit) submit.disabled = true;
    try {
      const data = await api("/api/users/me", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ handle }),
      });
      applyUpdatedUser(data.user || { ...currentUser, handle });
      showHandleClaimModal(false);
      setEditStatus("ok", `Username saved as @${(data.user?.handle || handle).replace(/^@/, "")}`);
    } catch (err) {
      if (errEl) errEl.textContent = err.message || "Could not save username";
      scheduleClaimHandleCheck({ immediate: true });
    } finally {
      if (submit) submit.disabled = !claimHandleAvailable;
    }
  });

  function scheduleProfileHandleAvailabilityCheck({ immediate = false } = {}) {
    window.clearTimeout(profileHandleCheckTimer);
    const run = async () => {
      const handle = profileHandleValue();
      const currentHandle = String(currentUser?.handle || "").replace(/^@/, "");
      const invalid = validateProfileHandleInline(handle);
      if (invalid) {
        setProfileHandleStatus("error", invalid);
        return;
      }
      if (handle.toLowerCase() === currentHandle.toLowerCase()) {
        setProfileHandleStatus("ok", "✓ Current");
        return;
      }
      const seq = ++profileHandleCheckSeq;
      const ctl = beginHandleAvailabilityFetch();
      setProfileHandleStatus("checking", "Checking…");
      try {
        const data = await api(`/api/users/me/handle-availability?handle=${encodeURIComponent(handle)}`, { signal: ctl.signal });
        if (ctl.signal.aborted || seq !== profileHandleCheckSeq) return;
        if (data.valid === false) {
          setProfileHandleStatus("error", data.message || "Invalid");
        } else if (data.available) {
          setProfileHandleStatus("ok", "✓ Available");
        } else {
          setProfileHandleStatus("error", "Taken");
        }
      } catch (err) {
        if (ctl.signal.aborted || err?.name === "AbortError" || seq !== profileHandleCheckSeq) return;
        setProfileHandleStatus("error", err.message || "Could not check");
      } finally {
        if (handleAvailabilityAbort === ctl) handleAvailabilityAbort = null;
      }
    };
    profileHandleCheckTimer = window.setTimeout(run, immediate ? 0 : 350);
  }

  function applyUpdatedUser(user) {
    if (!user) return;
    currentUser = user;
    bindQuestUser(user);
    authUi?.setUser?.(user);
    renderPreferencesMenuPanel();
  }

  async function uploadProfileAvatar(file) {
    if (!file) return;
    if (!/^image\/(png|jpeg|jpg)$/i.test(file.type || "")) {
      setProfileAvatarStatus("Upload a PNG or JPEG image.", "status error");
      return;
    }
    if (file.size > 1_500_000) {
      setProfileAvatarStatus("Profile picture must be under 1.5 MB.", "status error");
      return;
    }
    setProfileAvatarStatus("Uploading profile picture...");
    const form = new FormData();
    form.append("file", file);
    try {
      let data;
      try {
        data = await api("/api/users/me/avatar", { method: "POST", body: form });
      } catch (err) {
        if (!/Method Not Allowed/i.test(err.message || "")) throw err;
        const retry = new FormData();
        retry.append("file", file);
        data = await api("/api/users/me/avatar", { method: "PUT", body: retry });
      }
      applyUpdatedUser(data.user);
      setProfileAvatarStatus("Profile picture updated.", "status ok");
    } catch (err) {
      setProfileAvatarStatus(err.message || "Could not upload profile picture.", "status error");
    }
  }

  async function removeProfileAvatar() {
    setProfileAvatarStatus("Removing profile picture...");
    try {
      const data = await api("/api/users/me/avatar", { method: "DELETE" });
      applyUpdatedUser(data.user);
      setProfileAvatarStatus("Profile picture removed.", "status ok");
    } catch (err) {
      setProfileAvatarStatus(err.message || "Could not remove profile picture.", "status error");
    }
  }

  async function refreshCostsMenuPanel() {
    const panel = document.getElementById("ai-billing-costs-panel") || document.getElementById("profile-costs-panel");
    if (!panel || panel.classList.contains("hidden")) return;
    const ctl = beginCostsFetch();
    if (!panel.querySelector(".profile-cost-card")) {
      panel.innerHTML = `<div class="profile-workspace-loading muted small">Loading costs…</div>`;
    }
    try {
      const data = await api("/api/user/ai-costs?days=30", { signal: ctl.signal });
      if (ctl.signal.aborted) return;
      const totals = data.totals || {};
      const sharedUsers = data.shared_users || [];
      const topProjects = (data.projects || [])
        .filter((project) => Number(project.window_cost_usd || 0) > 0 || Number(project.total_tokens || 0) > 0)
        .slice(0, 5);
      panel.innerHTML = `
        <div class="profile-workspace-title">
          <strong>Costs</strong>
          <span class="muted small">${appEscapeHtml(data.range?.start || "")} to ${appEscapeHtml(data.range?.end || "")}</span>
          <button type="button" class="ai-chip-btn profile-costs-expand" id="btn-costs-expand" data-ai-billing-analytics="costs">View analytics</button>
        </div>
        <div class="profile-costs-grid">
          <div class="profile-cost-card">
            <span class="muted small">All time total</span>
            <strong>${costText(totals.all_total_usd)}</strong>
          </div>
          <div class="profile-cost-card">
            <span class="muted small">Last 30 days</span>
            <strong>${costText(totals.all_window_usd)}</strong>
          </div>
          <div class="profile-cost-card">
            <span class="muted small">Mine</span>
            <strong>${costText(totals.mine_window_usd)}</strong>
          </div>
          <div class="profile-cost-card">
            <span class="muted small">Shared</span>
            <strong>${costText(totals.shared_window_usd)}</strong>
          </div>
        </div>
        ${renderCostBars(data.daily || [])}
        <div class="profile-costs-section">
          <div class="profile-costs-section-title">
            <strong>Top projects</strong>
            <span class="muted small">Cost + tokens</span>
          </div>
          ${topProjects.length ? topProjects.map((project) => `
            <div class="profile-cost-user">
              <div>
                <strong>${appEscapeHtml(project.name || project.project_id)}</strong>
                <span class="muted small">${Number(project.tracked_count || 0)} prompts · ${Number(project.total_tokens || 0).toLocaleString()} tokens</span>
              </div>
              <div class="profile-cost-user-stats">
                <strong>${costText(project.window_cost_usd)}</strong>
                <span class="muted small">${costText(project.total_cost_usd)} all time</span>
              </div>
            </div>
          `).join("") : `<p class="muted small">No project cost data found yet.</p>`}
        </div>
        <div class="profile-costs-section">
          <div class="profile-costs-section-title">
            <strong>Shared key users</strong>
            <span class="muted small">${sharedUsers.length} user${sharedUsers.length === 1 ? "" : "s"}</span>
          </div>
          ${sharedUsers.length ? sharedUsers.map((u) => `
            <div class="profile-cost-user">
              <div>
                <strong>${appEscapeHtml(u.display_name || u.email || "Team member")}</strong>
                <span class="muted small">${appEscapeHtml(u.email || "")}</span>
              </div>
              <div class="profile-cost-user-stats">
                <strong>${costText(u.window_cost_usd)}</strong>
                <span class="muted small">${costText(u.total_cost_usd)} all time</span>
              </div>
            </div>
          `).join("") : `<p class="muted small">No shared-key usage found yet.</p>`}
        </div>
        <p class="muted small profile-costs-note">
          Estimates use tracked prompt token usage. Shared costs are attributed to users currently using your shared keys.
        </p>
      `;
      panel.querySelector("#btn-costs-expand")?.addEventListener("click", () => {
        void openCostsAnalyticsModal();
      });
    } catch (err) {
      if (ctl.signal.aborted || err?.name === "AbortError") return;
      panel.innerHTML = `<span class="ai-key-members-error">${appEscapeHtml(err.message || "Could not load costs")}</span>`;
    } finally {
      if (costsRefreshAbort === ctl) costsRefreshAbort = null;
    }
  }

