  function minutesFromMidnightToTime(mins) {
    const n = Math.max(0, Math.min(24 * 60 - 1, Number(mins) || 0));
    const h = Math.floor(n / 60);
    const m = n % 60;
    return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
  }

  function timeToMinutesFromMidnight(value) {
    const parts = String(value || "09:00").split(":");
    const h = Number(parts[0]);
    const m = Number(parts[1]);
    if (!Number.isFinite(h) || !Number.isFinite(m)) return 540;
    return Math.max(0, Math.min(24 * 60 - 1, h * 60 + m));
  }

  function fillAvailabilityEditor(windows) {
    const host = document.getElementById("pref-availability-editor");
    if (!host) return;
    const tz = windows?.[0]?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
    host.dataset.timezone = tz;
    const byDay = new Map((windows || []).map((w) => [Number(w.weekday), w]));
    const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
    host.innerHTML = `${days.map((label, weekday) => {
      const w = byDay.get(weekday);
      const on = w ? w.available !== false : weekday < 5;
      const start = minutesFromMidnightToTime(w?.start_minute ?? 540);
      const end = minutesFromMidnightToTime(w?.end_minute ?? 1020);
      return `<label class="pref-avail-day">
        <input type="checkbox" data-avail-day="${weekday}" ${on ? "checked" : ""} />
        <span>${label}</span>
        <input type="time" data-avail-start="${weekday}" value="${start}" />
        <span class="pref-avail-to">to</span>
        <input type="time" data-avail-end="${weekday}" value="${end}" />
      </label>`;
    }).join("")}
      <p class="muted small profile-preferences-note">Times in ${appEscapeHtml(tz)}. Saved as minutes from midnight (0=Mon … 6=Sun).</p>`;
  }

  function readAvailabilityWindows() {
    const host = document.getElementById("pref-availability-editor");
    const tz = host?.dataset.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
    const windows = [];
    for (let weekday = 0; weekday < 7; weekday += 1) {
      const on = !!host?.querySelector(`[data-avail-day="${weekday}"]`)?.checked;
      const start = timeToMinutesFromMidnight(host?.querySelector(`[data-avail-start="${weekday}"]`)?.value || "09:00");
      const end = timeToMinutesFromMidnight(host?.querySelector(`[data-avail-end="${weekday}"]`)?.value || "17:00");
      windows.push({
        weekday,
        start_minute: start,
        end_minute: Math.max(start + 30, end),
        available: on,
        timezone: tz,
      });
    }
    return windows;
  }

