  async function saveFeatureRequestNotifyPref(value, panel = document.getElementById("profile-preferences-panel")) {
    const note = panel?.querySelector("#pref-email-status");
    try {
      const data = await api("/api/admin/site-settings", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ feature_request_notify_enabled: !!value }),
      });
      const input = panel?.querySelector("#pref-feature-request-notify");
      if (input) input.checked = data.settings?.feature_request_notify_enabled !== false;
      if (note) note.textContent = "Feature request notifications saved.";
    } catch (err) {
      if (note) note.textContent = err.message || "Could not save feature request notifications.";
    }
  }

  let emailPreferencesAbort = null; // leakfix56
  async function loadEmailPreferences(panel = document.getElementById("profile-preferences-panel")) {
    if (!currentUser) return;
    if (emailPreferencesAbort) {
      try { emailPreferencesAbort.abort(); } catch (_) { /* ignore */ }
    }
    const ctl = new AbortController();
    emailPreferencesAbort = ctl;
    try {
      const data = await api("/api/users/me/email-preferences", { signal: ctl.signal });
      if (ctl.signal.aborted) return;
      emailPreferences = { ...emailPreferences, ...(data.preferences || {}) };
      syncPreferencesMenuControls(panel);
    } catch (err) {
      if (ctl.signal.aborted || err?.name === "AbortError") return;
      const note = panel?.querySelector("#pref-email-status");
      if (note) note.textContent = `Could not load email preferences: ${err.message || "error"}`;
    } finally {
      if (emailPreferencesAbort === ctl) emailPreferencesAbort = null;
    }
  }

  async function saveEmailPreference(key, value, panel = document.getElementById("profile-preferences-panel")) {
    if (!key) return;
    emailPreferences = { ...emailPreferences, [key]: !!value };
    syncPreferencesMenuControls(panel);
    const note = panel?.querySelector("#pref-email-status");
    try {
      const data = await api("/api/users/me/email-preferences", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ [key]: !!value }),
      });
      emailPreferences = { ...emailPreferences, ...(data.preferences || {}) };
      syncPreferencesMenuControls(panel);
      if (note) note.textContent = "Email preferences saved.";
    } catch (err) {
      if (note) note.textContent = err.message || "Could not save email preferences.";
    }
  }

  function askAuthorizedAppXPin() {
    return new Promise((resolve) => {
      document.getElementById("authorized-x-pin-modal")?.remove();
      const modal = document.createElement("div");
      modal.id = "authorized-x-pin-modal";
      modal.className = "auth-modal";
      modal.setAttribute("role", "dialog");
      modal.setAttribute("aria-modal", "true");
      modal.innerHTML = `
        <div class="auth-backdrop" data-x-pin-cancel></div>
        <div class="auth-card app-dialog-card" style="width:min(420px,calc(100vw - 28px))">
          <button type="button" class="auth-close" data-x-pin-cancel aria-label="Close">&times;</button>
          <h2 class="app-dialog-title">Enter the PIN from X</h2>
          <p class="muted small">Authorize Render3D in the X window, then type the PIN shown there.</p>
          <div class="viewport-x-pin-row" style="margin-top:12px">
            <input type="text" inputmode="numeric" autocomplete="one-time-code" data-x-pin-input placeholder="PIN code" maxlength="12" />
            <button type="button" class="btn accent" data-x-pin-submit>Connect</button>
            <button type="button" class="btn secondary" data-x-pin-cancel>Cancel</button>
          </div>
        </div>
      `;
      const finish = (value) => {
        modal.remove();
        resolve(value);
      };
      modal.addEventListener("click", (ev) => {
        if (ev.target.closest("[data-x-pin-submit]")) {
          const pin = String(modal.querySelector("[data-x-pin-input]")?.value || "").trim();
          finish(pin || null);
          return;
        }
        if (ev.target.closest("[data-x-pin-cancel]")) finish(null);
      });
      modal.querySelector("[data-x-pin-input]")?.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter") {
          ev.preventDefault();
          const pin = String(modal.querySelector("[data-x-pin-input]")?.value || "").trim();
          finish(pin || null);
        }
        if (ev.key === "Escape") {
          ev.preventDefault();
          finish(null);
        }
      });
      document.body.appendChild(modal);
      window.setTimeout(() => modal.querySelector("[data-x-pin-input]")?.focus(), 40);
    });
  }

  const X_CORP_LOGO_HTML = `<img src="/assets/brands/x-corp.svg?v=20260727-x" width="16" height="16" alt="" />`;

  async function connectXAccount({ onStatus } = {}) {
    const note = (kind, message) => {
      if (typeof onStatus === "function") onStatus(kind, message);
      else setEditStatus(kind, message);
    };
    note("ok", "Opening X authorization...");
    const data = await api("/api/integrations/twitter/link-url", { method: "POST" });
    if (!data?.url) throw new Error("X authorization URL was not returned.");
    const mode = String(data.mode || "redirect").toLowerCase();
    const width = 560;
    const height = 720;
    const left = Math.max(0, Math.round(window.screenX + (window.outerWidth - width) / 2));
    const top = Math.max(0, Math.round(window.screenY + (window.outerHeight - height) / 2));
    const popup = window.open(
      data.url,
      "render3d-twitter-connect",
      `popup=yes,width=${width},height=${height},left=${left},top=${top}`,
    );
    if (!popup) throw new Error("Popup blocked — allow popups for Render3D.");
    if (mode === "oob") {
      const pin = await askAuthorizedAppXPin();
      try { popup.close(); } catch (_) { }
      if (!pin) {
        note("error", "Connect cancelled — no PIN entered.");
        return false;
      }
      note("ok", "Finishing X connect…");
      await api("/api/integrations/twitter/link-pin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ state: data.state, pin }),
      });
      note("ok", "X connected.");
      return true;
    }
    await new Promise((resolve) => {
      const onMessage = (event) => {
        if (event.origin !== window.location.origin) return;
        if (!event.data || event.data.type !== "render3d:oauth-done") return;
        if (!["twitter", "x"].includes(String(event.data.provider || "").toLowerCase())) return;
        window.removeEventListener("message", onMessage);
        window.clearInterval(timer);
        resolve(event.data);
      };
      window.addEventListener("message", onMessage);
      const timer = window.setInterval(() => {
        if (!popup.closed) return;
        window.clearInterval(timer);
        window.removeEventListener("message", onMessage);
        resolve(null);
      }, 800);
      window.setTimeout(() => {
        window.clearInterval(timer);
        window.removeEventListener("message", onMessage);
        resolve(null);
      }, 10 * 60 * 1000);
    });
    note("ok", "X connect finished — refresh if status didn’t update.");
    return true;
  }

